P.entries["npc:merissa-stilwell"] = {n="梅里萨·斯蒂维尔",s="在北郡修道院，梅里萨·斯蒂维尔迎接初到北郡山谷的人们。这位年轻的人类热情地欢迎在附近受训的人，并向他们伸出援手。",h="在北郡修道院，梅里萨·斯蒂维尔迎接初到北郡山谷的人们。这位年轻的人类热情地欢迎在附近受训的人，并向他们伸出援手。",kw={"艾尔文","梅里萨","北郡","斯迪威尔"},ang={["faction:Alliance"]="作为一名走出北郡宁静修道院的联盟新兵，在切身体会迪菲亚威胁的残酷现实之前，你会先感受到梅里萨的热情款待。"},sec={{t="北郡的亲切面孔",b="梅里萨·斯蒂维尔在北郡修道院欢迎来到北郡山谷的新兵。她以朴素的方式待客，并提供休息和认路的实用建议。王国各地的一些工匠和农庄居民也与她同姓，其中包括铁匠乔丹·斯迪威尔和西部荒野的守卫者达芙妮·斯迪威尔。王国的局势日渐紧张，梅里萨依然在当地过着平静的生活。"}},faq={{q="梅里萨·斯蒂维尔是谁？",a="梅里萨·斯蒂维尔是一位友善的人类，住在艾尔文森林的北郡修道院。她欢迎旅人，并为他们提供建议。",al={"梅里萨·斯蒂维尔","梅里萨是谁","北郡斯迪威尔女孩"}},{q="在哪里可以找到梅里萨·斯蒂维尔？",a="你可以在艾尔文森林北郡山谷的北郡修道院找到梅里萨·斯蒂维尔。",al={"梅里萨·斯蒂维尔位置","梅里萨在哪里","寻找梅里萨"}},{q="梅里萨与王国里其他姓斯迪威尔的人有亲属关系吗？",a="梅里萨·斯蒂维尔与铁匠乔丹·斯迪威尔以及西部荒野的达芙妮·斯迪威尔同姓。她在北郡修道院安静地生活，迎接往来的旅人，并不与匪徒作战，也不锻造刀剑。",al={"斯迪威尔家族","达芙妮·斯迪威尔亲属","乔丹·斯迪威尔亲属"}},{q="梅里萨·斯蒂维尔提供任务吗？",a="不。梅里萨·斯蒂维尔没有任务交给旅人。她只是向途经北郡的新来者致意。",al={"梅里萨任务","梅里萨·斯蒂维尔任务"}}},fx={a071eba0={q="梅里萨·斯蒂维尔效忠哪一方？",a="梅里萨·斯蒂维尔是大联盟和暴风城王国的忠诚子民。她在北郡修道院过着平静的生活，迎接来到山谷的旅人和新兵。",al={"梅里萨·斯蒂维尔的阵营","梅里萨·斯蒂维尔是否属于联盟"}},["57a6fac4"]={q="梅里萨·斯蒂维尔为什么在北郡？",a="梅里萨平日在北郡修道院周围活动。和王国的许多普通百姓一样，她在艾尔文森林生活，欢迎来到山谷的新面孔。",al={"梅里萨·斯蒂维尔为何在这里","梅里萨在北郡做什么"}}},fp="16,163,30.412.0,24.130.0,34.93.0,57.206.0,39.103.0"}
P.entries["npc:merrin-rockweaver"] = {n="麦琳·石纹",s="在维尔加挖掘场上方的山脊上，麦琳·石纹与幸存者们一同等待。迅猛龙肆虐，迫使他们撤离了挖掘场，她原本在那里代表探险者协会工作。",h="在维尔加挖掘场上方的山脊上，麦琳·石纹与幸存者们一同等待。迅猛龙肆虐，迫使他们撤离了挖掘场，她原本在那里代表探险者协会工作。",kw={"探险者协会","麦琳·石纹","迅猛龙","搜寻工具","湿地","维尔加挖掘场","维尔加避难所"},ang={["faction:Alliance"]="作为联盟的冒险者，你可以帮助麦琳维持铁炉堡在湿地的研究活动，并巩固联盟在这片荒野沼泽中尚不稳固的立足点。",["race:Dwarf"]="作为矮人，你可以帮助麦琳保护探险者协会冒着生命危险发掘出的 Titan 遗物和历史记录。"},sec={{t="被迫撤离挖掘场",b="麦琳·石纹代表铁炉堡的探险者协会来到湿地，寻找淤泥之下古老的 泰坦 秘密。队员们挖出的大块骸骨将迅猛龙引到了挖掘场，考察行动就此瓦解。野兽涌入挖掘沟，麦琳和幸存的队员被迫逃离，留下了装备、笔记和此前的工作成果。如今，麦琳和几名幸存者困在一处高崖上，俯瞰着被迅猛龙占据的废墟。"},{t="挽救考察成果",b="高崖上的幸存者仍希望尽可能挽回考察成果。奥莫尔·铁衣计划向这些野兽复仇，勘察员维尔加则想找回迅猛龙盘踞的挖掘沟中的石板碎片。麦琳担心她的丈夫塔雷尔，他已经数周没有收到她的消息了。长须派来寻找考察队的斥候可以将他们的困境告知他。"}},faq={{q="麦琳·石纹是谁？",a="麦琳·石纹是铁炉堡探险者协会的矮人考古学家。迅猛龙占据挖掘场之前，她一直在湿地的维尔加挖掘场工作。",al={"麦琳·石纹背景故事","麦琳是谁","湿地矮人麦琳"}},{q="她为什么被困在挖掘场上方？",a="考察队挖出的大块骸骨引来了迅猛龙，挖掘场随之沦陷，许多人因此丧命。奥莫尔·铁衣护送麦琳和勘察员维尔加逃到附近的高崖上，他们至今仍被困在那里。",al={"麦琳为什么在避难所","维尔加避难所 麦琳","她的营地发生了什么"}},{q="麦琳需要什么帮助？",a="麦琳需要有人给她的丈夫塔雷尔送去一封信，告知他这场灾难。自从收不到她的来信，他就一直忧心忡忡。",al={"麦琳任务","麦琳·石纹任务","收集工具 背景故事"}},{q="考察队想寻找什么？",a="湿地考察队寻找的是与矮人起源有关的古代文物，以及隐藏在卡兹莫丹各处的神秘 泰坦 遗物。",al={"他们在挖什么","挖掘场的用途"}}},fp="17,165,20.418.0,23.399.0,25.177.0,38.212.0,32.131.0,39.131.0"}
P.entries["npc:miles-welsh"] = {n="麦尔斯·威尔什",s="在雷霆崖下方的预见之池，麦尔斯·威尔什教导牧师。这位被遗忘者训练师在牛头人的都城传授灵性知识与暗影之道。",h="在雷霆崖下方的预见之池，麦尔斯·威尔什教导牧师。这位被遗忘者训练师在牛头人的都城传授灵性知识与暗影之道。",kw={"噬灵瘟疫","被遗忘者","麦尔斯·威尔什","预见之池","牧师训练师","灵魂高地","雷霆崖"},ang={["class:Priest"]="作为一名游历卡利姆多的牧师，你可以向麦尔斯·威尔什学习新法术，精进灵性修行。他是部落领地腹地少有的此类导师之一。",["race:Undead"]="作为一名亡灵旅人，在这座充满泥土气息、阳光普照的牛头人都城里，麦尔斯·威尔什那张冰冷的面孔或许会让你感到熟悉。"},sec={{t="洞穴中的暗影",b="麦尔斯·威尔什在雷霆崖下方的预见之池教导牧师。远离洛丹伦饱受瘟疫摧残的废墟，这位被遗忘者牧师在城下的洞穴中安了家。他教导旅人运用神圣与暗影能量。他在莫高雷腹地的立足之地，体现了被遗忘者与部落之间脆弱的联系。在那里，他与牛头人的秘术师和萨满祭司共处一方庇护之所，引导学徒研习暗影与信仰。"}},faq={{q="麦尔斯·威尔什是谁？",a="麦尔斯·威尔什在雷霆崖下方的预见之池训练牧师。他帮助部落牧师接受训练，研习专门的技艺。",al={"麦尔斯·威尔什职责","麦尔斯·威尔什是谁","麦尔斯·威尔什牧师训练师"}},{q="在哪里可以找到麦尔斯·威尔什？",a="麦尔斯·威尔什位于预见之池，也就是雷霆崖灵魂高地下方的洞穴。从台地上的洞口进入即可。",al={"麦尔斯·威尔什位置","麦尔斯·威尔什在哪","如何找到麦尔斯·威尔什"}},{q="为什么雷霆崖会有一位亡灵牧师训练师？",a="被遗忘者与牛头人同为部落的盟友。玛加萨·野性图腾曾主张接纳被遗忘者加入部落，使麦尔斯·威尔什这样的使者和训练师得以在莫高雷效力。",al={"被遗忘者为何在雷霆崖","牛头人城市中的亡灵牧师"}},{q="他传授哪些技能？",a="麦尔斯·威尔什传授通用的牧师法术。他也帮助被遗忘者和巨魔学徒研习种族专属技艺，例如虚弱之触或暗影守卫。",al={"雷霆崖牧师法术","麦尔斯·威尔什教什么"}}},fp="11,169,23.438.0,19.143.0,29.137.0,49.173.0,29.163.0"}
P.entries["npc:milli-featherwhistle"] = {n="米利·羽哨",s="在钢架补给站，米利·羽哨为诺莫瑞根流离失所的居民制造和维护机械陆行鸟。她将这些发条驱动的坐骑卖给自己的同胞，以及流亡者信赖的盟友。",h="在钢架补给站，米利·羽哨为诺莫瑞根流离失所的居民制造和维护机械陆行鸟。她将这些发条驱动的坐骑卖给自己的同胞，以及流亡者信赖的盟友。",kw={"丹莫罗","诺莫瑞根","卡拉诺斯","机械陆行鸟","梅卡托克","米利·羽哨","坐骑商人","钢架补给站"},ang={["faction:Alliance"]="作为联盟的英雄，你可以在赢得诺莫瑞根流亡者的最高敬意后去找米利。届时，你便能驾驭艾泽拉斯最迅捷的机械坐骑之一。",["profession:Engineering"]="米利的机械陆行鸟代表着侏儒交通技术的巅峰。它们配有陀螺平衡装置和高扭矩机械肢体。",["race:Gnome"]="作为侏儒，你能看到米利如何传承大工匠梅卡托克的技术才华。她是你们族中首屈一指的坐骑工程师，即使流亡在地下家园之外，仍在继续工作。"},sec={{t="机械陆行鸟大师",b="米利在卡拉诺斯以东不远处，冒着丹莫罗刺骨的严寒在户外工作。她调校每只坐骑的齿轮、活塞和平衡陀螺仪，让它们能够载着骑手穿越积雪的峭壁。矮人和暗夜精灵偏爱活生生的坐骑。对诺莫瑞根流离失所的居民而言，米利的发条坐骑满足的是另一种需求。"},{t="梅卡托克的传承",b="米利沿用大工匠Gelbin Mekkatorque最初绘制的蓝图。她减轻底盘重量，改进排气口，提升了每只机械陆行鸟的性能。但她依然遵循大工匠最初的设计。即使身在流亡之中，她的工作仍让侏儒的雄心不断向前。"}},faq={{q="米利·羽哨是谁？",a="米利是诺莫瑞根首屈一指的机械陆行鸟培育者和工程师。她在丹莫罗的钢架补给站制造发条坐骑，并将它们出售给符合条件的骑手。",al={"米利·羽哨","米利是谁","机械陆行鸟商人"}},{q="在哪里可以找到米利·羽哨？",a="米利在丹莫罗的钢架补给站工作，从卡拉诺斯沿道路向东走一小段路就能到达。",al={"米利位置","米利·羽哨在哪里","寻找米利"}},{q="谁可以向她购买坐骑？",a="侏儒冒险者可以直接购买米利的造物。其他联盟种族的骑手必须赢得她的充分信任，并在诺莫瑞根流亡者中达到崇拜声望，她才会放心地将机械陆行鸟交给他们。",al={"能否购买机械陆行鸟","机械陆行鸟购买条件","谁能骑机械陆行鸟"}},{q="机械陆行鸟是如何制造的？",a="米利按照大工匠格尔宾·梅卡托克的蓝图，亲手制造每一只机械陆行鸟。她改进了引擎和平衡性能。",al={"机械陆行鸟如何制造","谁制造机械陆行鸟","机械陆行鸟起源"}},{q="她出售哪些种类的坐骑？",a="米利出售机架未涂装以及涂有蓝色、绿色和红色的普通机械陆行鸟。她还出售白色、绿色和黄色的迅捷型号。",al={"米利的坐骑颜色","机械陆行鸟型号","米利出售哪些坐骑"}},{q="她为什么在钢架补给站的雪地里工作？",a="一场辐射灾难和穴居人的入侵迫使侏儒离开诺莫瑞根，此后，难民们在一切能够落脚的地方聚集。卡拉诺斯外的钢架补给站自然而然地成为集结中心，他们可以在那里与矮人工程师一起测试载具、维护机械。",al={"米利为什么在丹莫罗","为什么选择钢架补给站"}}},fx={["2267a2b3"]={q="米利·羽哨效忠哪一方？",a="米利·羽哨忠于诺莫瑞根和大联盟。她在钢架补给站与矮人工匠一起工作，直接向侏儒同胞，以及赢得诺莫瑞根流亡者充分尊重的可靠联盟勇士供应机械陆行鸟。",al={"米利·羽哨的阵营","米利·羽哨为谁效力","米利是否属于联盟"}},f07f7c95={q="米利·羽哨想要什么？",a="米利想要制造并维护丹莫罗最出色的机械陆行鸟。她以大工匠梅卡托克最初的设计图为基础，不断改进构造，让侏儒旅人和经受过考验的盟友随时都能获得可靠的机械坐骑。",al={"米利·羽哨做什么","米利·羽哨的目标","米利想做什么"}}},fp="20,199,25.300.0,21.295.0,28.161.0,38.96.0,43.209.0,29.132.0,36.149.0,57.274.0"}
P.entries["npc:milton-sheaf"] = {n="米尔顿·西弗",s="米尔顿·西弗在暴风要塞照管皇家图书馆，并请联盟旅者找回散失的书籍和记录。",h="米尔顿·西弗在暴风要塞照管皇家图书馆，并请联盟旅者找回散失的书籍和记录。",kw={"书籍","历史","图书管理员","米尔顿·西弗","皇家图书馆","暴风要塞","典籍"},ang={["faction:Alliance"]="身为联盟旅者，你可以帮助米尔顿·西弗保存人类诸国乃至整个联盟以文字传承的遗产。",["race:Human"]="身为人类，米尔顿·西弗守护的也是你的历史。他保存着历经暴风城陷落与重建而留存下来的编年史。"},sec={{t="暴风城历史的守护者",b="米尔顿·西弗照管着暴风要塞内的皇家图书馆。宫廷忙于权衡政务、贵族纷争和军事事务，而他则守护着文字记载。对他而言，确保联盟与东部王国的历史记载准确无误是一份职责，尤其是在战乱、损失与动荡之中。"},{t="寻回散失的典籍",b="米尔顿·西弗派旅者前往王国各地，找回散落的书籍。书卷在翻阅中逐渐磨损，而记录则存放在修道院的档案室、偏远的哨站和被遗忘的废墟中。从北郡修道院到北方的南海镇，他派遣联盟冒险者寻回遗失的书籍，查阅古老的文献，并将珍贵的手稿安全送回要塞。"}},faq={{q="米尔顿·西弗是谁？",a="米尔顿·西弗是一位人类学者，照管着暴风城暴风要塞内的皇家图书馆。他管理王国的书籍与编年史。",al={"米尔顿·西弗是谁","米尔顿·西弗的职责","暴风城图书管理员"}},{q="在哪里可以找到米尔顿·西弗？",a="米尔顿·西弗就在暴风要塞的皇家图书馆侧翼，紧邻王宫的主走廊。",al={"米尔顿·西弗的位置","米尔顿·西弗在哪里","暴风城图书馆位置"}},{q="米尔顿·西弗为什么需要冒险者？",a="米尔顿·西弗依靠四处旅行的联盟冒险者寻找历史手稿、替换受损的书籍，并与王国各地的学者和牧师合作，充实皇家图书馆的馆藏。",al={"米尔顿·西弗的任务","米尔顿需要什么","为什么发布任务"}},{q="米尔顿·西弗与王国内的其他学者有往来吗？",a="米尔顿·西弗与修道院的档案管理员和宗教学者保持着联系，其中包括北郡山谷的帕克斯顿修士。他们共同保存神圣的教义与历史记录。",al={"米尔顿 北郡","米尔顿 帕克斯顿修士","米尔顿的人脉"}}},fx={["440d1fb9"]={q="米尔顿·西弗效忠哪一方？",a="米尔顿·西弗为暴风城王国和联盟效力。他驻守在暴风要塞内，直接为王室档案馆工作，编纂史料，为王国的学者和统治者保存知识。",al={"米尔顿·西弗的阵营","米尔顿·西弗为谁效力","米尔顿·西弗与联盟"}},["1fad6188"]={q="米尔顿·西弗为什么在暴风要塞这里？",a="米尔顿负责管理和维护皇家图书馆。他照管着王国收藏的大量卷轴、典籍和历史文献，确保记述艾泽拉斯往昔的重要资料得到妥善保护，并可供宫廷查阅。",al={"米尔顿·西弗为什么在皇家图书馆","米尔顿·西弗在这里的目的","米尔顿为什么在暴风城"}}},fp="12,122,36.288.0,21.356.0,20.147.0,30.106.0,39.200.0,62.184.0"}
P.entries["npc:miner-johnson"] = {n="矿工约翰森",s="在死亡矿井深处，矿工约翰森游走于迪菲亚劳工之间。他是一名经验丰富的矿工，负责监督重型机械前方的挖掘工作，不过他只是偶尔现身。",h="在死亡矿井深处，矿工约翰森游走于迪菲亚劳工之间。他是一名经验丰富的矿工，负责监督重型机械前方的挖掘工作，不过他只是偶尔现身。",kw={"凹洞","死亡矿井","迪菲亚","精英","矿工约翰森","月溪镇","稀有","伐木机","西部荒野"},ang={["faction:Alliance"]="击败约翰森会扰乱矿石供应，阻碍月溪镇地下的迪菲亚战争机器运转。",["profession:Mining"]="对于勘探者而言，约翰森展现了在西部荒野地下采矿的危险，他在那里挥舞矿镐，守卫着矿藏。"},sec={{t="矿井深处的罕见面孔",b="矿工约翰森与其他劳工一起，在死亡矿井地下挖掘，为艾德温·范克里夫建造隐秘要塞。他在左侧的一处凹洞中等候，就在Mast Room的伐木机前方。他比其他矿工更强壮，也更具攻击性，在隧道中游荡时很难找到。"},{t="为迪菲亚战争机器供给资源",b="在月溪镇地下，迪菲亚潜行者需要矿石来制造武器、加固矿井，并打造各种机械装置。约翰森和其他矿工开采着西部荒野地下的矿脉。任何进入他作业区域的人，都会发现他守卫这里时有多凶狠。"}},faq={{q="矿工约翰森是谁？",a="矿工约翰森是一名效力于迪菲亚潜行者的人类矿工。他与其他劳工一起，在死亡矿井深处、地精伐木机前方的侧面凹洞中工作。",al={"矿工约翰森背景故事","矿工约翰森是谁","死亡矿井矿工约翰森"}},{q="矿工约翰森的具体位置在哪里？",a="约翰森在死亡矿井上层的矿道中工作，就在斯尼德及其伐木机所在的房间前方。留意左侧的一处小凹洞，那里有矿工正在凿岩。",al={"矿工约翰森位置","矿工约翰森在哪里","如何找到矿工约翰森"}},{q="为什么矿工约翰森并不总在那里？",a="矿工约翰森只是偶尔出现在死亡矿井中。大多数队伍在他的位置上找到的只是一名普通矿工。",al={"矿工约翰森不刷新","矿工约翰森是稀有怪吗","矿工约翰森刷新几率"}},{q="矿工约翰森与任何任务有关吗？",a="矿工约翰森没有正式的悬赏。探索死亡矿井的队伍可能会意外遇到他。",al={"矿工约翰森任务","矿工约翰森有任务吗"}},{q="矿工约翰森在死亡矿井中负责什么？",a="矿工约翰森帮助迪菲亚潜行者开采金属、石料和其他资源，供其地下基地与隐秘战舰使用。",al={"矿工约翰森做什么","矿工约翰森职责"}},{q="矿工约翰森比其他矿工更危险吗？",a="是的。矿工约翰森比普通矿工强悍得多，攻击也更重。队伍必须齐心协力，才能稳妥地击败他。",al={"矿工约翰森难度","矿工约翰森是精英吗"}}},fp="13,154,23.298.0,30.247.0,21.162.0,39.175.0,37.106.0,35.101.0,46.128.0,52.125.0"}
P.entries["npc:minor-manifestation-of-earth"] = {n="大地之魂",s="在莫高雷和杜隆塔尔的神圣岩石旁，大地之魂隐匿着身形，静静等候。初出茅庐的萨满祭司喝下大地灵契后，便能与这位元素之灵相见，获得粗石英，用来雕刻自己的第一个大地图腾。",h="在莫高雷和杜隆塔尔的神圣岩石旁，大地之魂隐匿着身形，静静等候。初出茅庐的萨满祭司喝下大地灵契后，便能与这位元素之灵相见，获得粗石英，用来雕刻自己的第一个大地图腾。",kw={"大地的召唤","大地灵契","大地图腾","科多石","大地之魂","粗石英","灵魂石地"},ang={["class:Shaman"]="身为年轻的部落萨满祭司，你借助大地灵契的效力与大地之魂沟通，赢得自己的第一个图腾。",["race:Tauren"]="身为年轻的牛头人，你向东穿越莫高雷，前往科多石与这位大地之魂沟通，完成先祖传下的灵魂试炼中的一环。"},sec={{t="岩石之声",b="大地之灵栖居于泥土与岩石之下，但要接触它们，必须举行特定的仪式。在莫高雷的科多石和杜隆塔尔的灵魂石地，大地之魂徘徊于寻常视线之外，周围环绕着较弱的元素之灵。只有喝下萨满导师调制的大地灵契，学徒才能穿过物质世界与元素之间的帷幕。当学徒与大地之魂取得联系时，它便会赐予大地的祝福和一块粗石英。新手可以用这块石英作为凝聚灵力的媒介，制作大地图腾。"}},faq={{q="为什么我看不见大地之魂？",a="大地之魂身处元素位面，寻常视线无法看见。喝下萨满祭司训练师提供的大地灵契，就能感知元素之灵，并与它们交谈。",al={"看不见大地之魂","大地之灵在哪里","大地之魂隐形"}},{q="在哪里能找到这些大地之灵？",a="这些大地之灵出现在莫高雷的科多石和杜隆塔尔的灵魂石地。这两处地方都是年轻的牛头人、兽人和巨魔萨满祭司接受试炼的传统场所。",al={"大地之魂位置","哪里能找到大地之魂"}},{q="大地之魂在仪式中起什么作用？",a="大地之魂会考验并认可你与大地元素之间的联系。与它交谈后，它会给你粗石英，让你带回萨满祭司训练师那里，制作大地图腾。",al={"大地之魂有什么作用","大地之魂任务目的"}},{q="它周围那些较小的生物是什么？",a="较弱的大地之灵聚集在中央的大地之魂周围。它们是被这片圣地吸引而来的微弱元素回响，是自然交流的一部分，无法与之直接互动。",al={"较弱的大地之灵","周围的小型大地元素"}}},fp="28,220,18.518.0,49.170.0,39.157.0,45.196.0,46.193.0"}
P.entries["npc:minor-manifestation-of-water"] = {n="水之魂",s="在银松森林海边的北流海岸，水之魂等待着萨满祭司。必须先净化它那腐化的化身，才能向这位平和的灵魂求教。",h="在银松森林海边的北流海岸，水之魂等待着萨满祭司。必须先净化它那腐化的化身，才能向这位平和的灵魂求教。",kw={"水之召唤","元素","水之魂","北流海岸","萨满祭司任务","银松森林","水之图腾"},ang={["class:Shaman"]="作为萨满祭司，净化这个元素身上的腐化，接受它的祝福，与潮汐建立共鸣，制作你的水之图腾。",["faction:Horde"]="作为巨魔、兽人或牛头人萨满祭司，你从卡利姆多远赴洛丹伦的海岸，与这位灵魂交流。"},sec={{t="西方潮汐之灵",b="水之魂在瑟伯切尔以西的北流海岸等待着。对于修行中的萨满祭司来说，拜会这位灵魂是一项不可或缺的仪式。水元素象征着生命、复苏与流动，却也会受到邪恶疫病的腐化。初学者必须面对并击败一个腐化的化身，纯净的灵魂才会现身。净化之后，水之魂会指引萨满祭司踏上制作水之图腾的神圣旅程。"}},faq={{q="在哪里可以找到水之魂？",a="水之魂位于银松森林西海岸的北流海岸，就在瑟伯切尔以西。",al={"水之魂位置","水之魂在哪里","北流海岸元素"}},{q="为什么初次接近时，这个元素会有敌意？",a="萨满祭司必须先召唤并消灭堕落的水之魂。将其击败后，平和的化身便会出现，与你交谈。",al={"腐化的水之魂","水之魂为什么愤怒","水之魂攻击我"}},{q="哪个任务与这个元素有关？",a="水之魂会在水之召唤系列任务中指引萨满祭司，让他们最终学会施放水之图腾。",al={"水之召唤任务","银松森林水之图腾任务","这是哪个任务的"}},{q="非萨满祭司能与这位灵魂互动吗？",a="水之魂指引萨满祭司完成灵魂的试炼。其他冒险者很少有理由寻找这位灵魂。",al={"是否仅限萨满祭司","谁都能与水之魂交谈吗","谁与水之魂交谈"}}},fp="28,193,29.454.0,50.126.0,51.152.0,35.137.0,42.136.0"}
P.entries["npc:misha"] = {n="米沙",s="米沙是部落勇士雷克萨忠诚的熊伙伴。她始终陪伴在这位半食人魔兽王身旁，漫游卡利姆多。",h="米沙是部落勇士雷克萨忠诚的熊伙伴。她始终陪伴在这位半食人魔兽王身旁，漫游卡利姆多。",kw={"熊","兽王","凄凉之地","菲拉斯","米沙","雷克萨","石爪山"},ang={["class:Hunter"]="对猎人而言，米沙代表着动物伙伴的至高理想：以相互尊重而非单纯支配为基础，结成牢不可破、相伴一生的关系。",["faction:Horde"]="米沙曾与雷克萨并肩作战，在塞拉摩岛为新生的部落争取自由，赢得了杜隆塔尔各地老兵无声的敬意。"},sec={{t="无尽的羁绊",b="米沙是一头棕熊，陪伴着四处漂泊的雷克萨，他性情孤独，对野兽的信任胜过对人。一路走来，他们结成了紧密的伙伴关系，彼此奋力守护，历经无数荒野与浴血之战的考验。"},{t="杜隆塔尔的守护者",b="米沙远不只是一只驯服的宠物；她还是一位身经百战的勇士。她曾与雷克萨并肩作战，在塞拉摩岛与海军上将戴林·普罗德摩尔展开惨烈交锋，帮助新生的部落生存下来。在战斗之外，她敏锐的感官和强大的力量也如同雷克萨意志的延伸。"},{t="卡利姆多的荒野",b="如今，旅人沿着穿越石爪山脉、凄凉之地和菲拉斯的漫长小径前行时，可以看到米沙在雷克萨身旁悄然踱步。她凶猛无比，足以撕碎任何愚蠢到胆敢威胁他们的掠食者，而在这个难以信任的世界里，她始终是雷克萨坚定的依靠。"}},faq={{q="米沙是谁？",a="米沙是一头凶猛的棕熊，也是部落勇士雷克萨相伴一生的伙伴。她陪着他漫游卡利姆多中部的荒野。",al={"雷克萨的熊","雷克萨身边的熊是谁","棕熊米沙"}},{q="现在在哪里能找到米沙？",a="米沙沿着石爪山脉、凄凉之地和菲拉斯的漫长巡逻路线游荡，忠实地陪伴雷克萨踏上无尽的旅途。",al={"米沙位置","米沙在哪里","寻找米沙"}},{q="米沙参与了杜隆塔尔的建立吗？",a="是的。第三次大战之后，米沙陪同雷克萨在塞拉摩岛迎战海军上将戴林·普罗德摩尔的军队，保卫新生的部落。",al={"米沙塞拉摩","米沙与戴林交战过吗","米沙第三次大战"}},{q="米沙对联盟玩家有敌意吗？",a="是的。作为部落勇士的伙伴，米沙会奋力保护雷克萨，攻击任何靠得太近的联盟闯入者。",al={"联盟能攻击米沙吗","米沙会主动攻击吗"}},{q="为什么雷克萨更喜欢米沙这样的野兽，而不是人？",a="人形种族的欺骗与战争让雷克萨深感失望，于是他选择独居荒野。他相信野兽直率而诚实，而米沙正是他找到的绝不会背叛的伙伴。",al={"雷克萨为什么与野兽为伴","雷克萨的熊伙伴"}}},fp="5,162,16.212.0,19.247.0,17.257.0,13.162.0,35.101.0,47.153.0,37.143.0,51.190.0"}
P.entries["npc:misha-tor-kren"] = {n="米莎·托克伦",s="在杜隆塔尔西部的托克雷农场，米莎·托克伦正等待着儿子的消息。克鲁恩向西前往怒水河猎杀鳄鱼，却迟迟未归。",h="在杜隆塔尔西部的托克雷农场，米莎·托克伦正等待着儿子的消息。克鲁恩向西前往怒水河猎杀鳄鱼，却迟迟未归。",kw={"鳄鱼","克鲁恩","逝者的思念","米沙","米莎·托克伦","怒水河","雷霆山","托克雷农场"},ang={["class:Hunter"]="米沙的儿子还未掌握在荒野中生存的本领，就遭遇了河中捕食者的威胁。",["race:Orc"]="克鲁恩试图挑战杜隆塔尔的野兽来证明自己的力量，展现了年轻气盛所付出的代价。"},sec={{t="母亲的守望",b="米莎·托克伦在雷霆山东南方的山脚附近照料农场。她的儿子克鲁恩向西前往怒水河猎杀鳄鱼，想证明自己的勇气，却再也没有回家。杜隆塔尔边境危机四伏，兽人的哨塔守卫疲于应付，米沙至今得不到儿子的下落。她需要有旅人愿意沿着河岸寻找儿子的踪迹。"},{t="悲痛的信物",b="克鲁恩命丧怒水河的鳄鱼之口。米沙能收到的，只有寻回的儿子的护符，它令人痛心地提醒着人们，年轻兽人在卡利姆多的荒野中试图证明自己的力量时，会面临怎样的危险。"}},faq={{q="米莎·托克伦是谁？",a="米莎·托克伦在杜隆塔尔西部、雷霆山东南方的托克雷农场务农。",al={"米莎·托克伦","米沙是谁","托克雷农场主人"}},{q="她的儿子克鲁恩去了哪里？",a="克鲁恩向西前往怒水河猎杀鳄鱼，想证明自己是一名合格的猎人，却没有回家。",al={"克鲁恩 在哪里","克鲁恩 遭遇了什么","米沙的儿子"}},{q="寻找克鲁恩时会发生什么？",a="米沙请旅人沿河寻找克鲁恩。儿子的失踪让她忧心忡忡，她需要有人前去调查。",al={"克鲁恩 死了吗","寻找 克鲁恩","永不遗忘"}},{q="她和雷克萨的熊米沙有什么关系吗？",a="没有。米沙是杜隆塔尔的一名兽人农民，与雷克萨那位同名的忠诚熊伙伴并非同一个。",al={"熊米沙","雷克萨的熊米沙","她是那只熊吗"}}},fp="14,166,16.351.0,12.208.1,22.86.0,26.115.0,36.135.1,38.104.0"}
P.entries["npc:mitsuwa"] = {n="米苏瓦",s="在佐拉姆加前哨站，米苏瓦悼念那些在穿越灰谷途中遇害的巨魔。他呼吁部落的勇士夺回他们被抢走的符咒。",h="在佐拉姆加前哨站，米苏瓦悼念那些在穿越灰谷途中遇害的巨魔。他呼吁部落的勇士夺回他们被抢走的符咒。",kw={"灰谷","黑暗之矛","熊怪","玛鲁凯","米苏瓦","蓟皮","巨魔","巨魔符咒","佐拉姆加"},ang={["faction:Horde"]="佐拉姆加前哨站是一处孤立无援、四面受敌的驻地。帮助米苏瓦，能让部落在卡利姆多西部面对野兽和联盟斥候时，稳住岌岌可危的阵脚。",["race:Troll"]="对黑暗之矛的冒险者而言，米苏瓦的呼吁关乎自己的同胞。从熊怪手中夺回先祖的符咒，既能向遇害的同胞致敬，也能让他们的灵魂得到安宁。"},sec={{t="为遇害的同胞复仇",b="米苏瓦与玛鲁凯一同在佐拉姆海岸的佐拉姆加前哨站为部落效力。灰谷北部的蓟皮熊怪伏击并屠杀了一群前往前哨站的巨魔旅人。米苏瓦认为，杀害他们是极大的冒犯。他派遣勇士前往蓟皮的巢穴，夺回被抢走的巨魔符咒，告慰同胞的灵魂。"}},faq={{q="米苏瓦是谁？",a="米苏瓦是一名黑暗之矛丛林巨魔，驻守在灰谷西北部的佐拉姆加前哨站。他与玛鲁凯一同守卫前哨站，指挥应对附近的威胁。",al={"米苏瓦","米苏瓦是谁","米苏瓦的故事"}},{q="前往佐拉姆加的巨魔遭遇了什么？",a="蓟皮熊怪伏击并屠杀了一群穿越灰谷、前往佐拉姆加前哨站的巨魔。熊怪还抢走了死者的财物。",al={"灰谷遇害的巨魔","蓟皮袭击巨魔"}},{q="巨魔符咒为何对米苏瓦如此重要？",a="这些符咒对黑暗之矛有着精神与文化上的意义。让这些神圣的遗物留在蓟皮熊怪手中，是对遇害者灵魂的亵渎。",al={"巨魔符咒为何重要","巨魔符咒任务缘由"}},{q="符咒在哪里？",a="蓟皮熊怪把符咒带回了他们位于灰谷北部、佐拉姆海岸以东的村落和巢穴。",al={"巨魔符咒在哪里","蓟皮村位置"}}},fp="7,156,23.350.0,15.170.0,51.161.0,49.158.0,29.116.0"}
P.entries["npc:monte-gazlowe"] = {n="Monte Gazlowe",s="在棘齿城，蒙特·加兹鲁维 经营着一座向各方商人开放的中立港口。他曾在杜隆塔尔和奥格瑞玛的建设期间担任部落首席工程师，并用那时赚来的财富建立了这座城镇。",h="在棘齿城，蒙特·加兹鲁维 经营着一座向各方商人开放的中立港口。他曾在杜隆塔尔和奥格瑞玛的建设期间担任部落首席工程师，并用那时赚来的财富建立了这座城镇。",kw={"贫瘠之地","杜隆塔尔","海盗","加兹鲁维","蒙特","奥格瑞玛","普兹克","棘齿城","热砂"},ang={["faction:Alliance"]="加兹鲁维不怎么关心暴风城的王位，也不在乎你从东部王国带来的纷争。只要你的金币货真价实，刀剑留在鞘中，棘齿城就欢迎你。",["faction:Horde"]="加兹鲁维和其他地精一样，张口就向你要钱，但自第三次战争以来，他始终是萨尔坚定的盟友。他曾协助挖掘你们都城的地基。",["profession:Engineering"]="加兹鲁维是卡利姆多顶尖的地精工程师之一。从城市供水管网到沙漠赛道上的高速赛车，各类工程都由他协调。",["race:Orc"]="奥格瑞玛的水源来自加兹鲁维麾下工兵挖掘的隧道。他至今仍在杜隆塔尔派驻地精技师，协助大型工程建设。"},sec={{t="棘齿城的主事者",b="在棘齿城，蒙特·加兹鲁维 经营着一座隶属热砂港的港口，敌对双方也能在此交易。他为新生的部落提供工程服务，赚取了丰厚的报酬，随后在荒凉的海岸上建立了这座城镇。部落、联盟和独立商人都可以在这里做买卖，只要他们收起武器，带足钱币。"},{t="部落的工程师",b="第三次战争后，大酋长萨尔雇用 蒙特·加兹鲁维 担任杜隆塔尔的首席工程师，为新建的兽人都城解决紧迫的问题。加兹鲁维承担了为奥格瑞玛寻找淡水的危险工作。他挖掘的隧道通入了地下的狗头人巢穴，但四处游历的兽王雷克萨及时赶到，帮助炸塌洞穴，封住了入口。加兹鲁维完成了任务，至今仍是萨尔信赖的承包商和朋友。他甚至派出了自己的工头雷兹拉克，继续协助杜隆塔尔各地的兽人开展建设。"},{t="商旅海岸的麻烦",b="贸易为棘齿城带来了可观的收入，但海上的对手和盗贼也给 蒙特·加兹鲁维 的生意添了不少麻烦。南海海盗在附近的商旅海岸沿线设有营地，劫掠运往棘齿城的货物，从原矿到加兹鲁维专门订制的靴子都不放过。为了保住利润，这位港口老板经常雇用路过的佣兵，不问他们效忠哪一方，让他们清剿海盗营地、追回被劫的货物，并找码头上的闹事者算账。"}},faq={{q="加兹鲁维是谁？",a="蒙特·加兹鲁维 掌管着棘齿城，那是贫瘠之地海岸上的主要贸易港口。他曾担任首席工程师，监督奥格瑞玛的建设，由此积累了一笔财富，随后建立了棘齿城，使其成为热砂港旗下一座开放的中立港口。",al={"蒙特·加兹鲁维 是谁","加兹鲁维背景故事","棘齿城老板"}},{q="加兹鲁维效忠部落还是联盟？",a="蒙特·加兹鲁维 在热砂港旗下经营棘齿城，向联盟和部落的旅人开放码头。他还与大酋长萨尔交情深厚，曾负责杜隆塔尔各处定居点的关键工程，并从这段合作中获利颇丰。",al={"加兹鲁维属于部落吗","棘齿城是中立的吗","加兹鲁维阵营"}},{q="加兹鲁维在杜隆塔尔建造了什么？",a="杜隆塔尔初建时，大酋长萨尔雇用 蒙特·加兹鲁维 担任首席工程师。加兹鲁维监督隧道挖掘，为奥格瑞玛寻找地下水源。矿工挖出了充满敌意的狗头人后，加兹鲁维雇用雷克萨，协助工兵封闭隧道。",al={"加兹鲁维 奥格瑞玛","加兹鲁维 萨尔","加兹鲁维供水"}},{q="加兹鲁维为什么在棘齿城雇用冒险者？",a="蒙特·加兹鲁维 雇用私人打手对付南海海盗，这些海盗在商旅海岸沿线扎营，劫掠运往棘齿城码头的货物。他付钱给赏金猎人，让他们消灭海盗、夺回被盗的货物清单，并找回失踪的货物。",al={"加兹鲁维任务","南海海盗 棘齿城","加兹鲁维的麻烦"}},{q="加兹鲁维与沙漠赛道有什么联系？",a="蒙特·加兹鲁维 热衷于工程技术与速度。他赞助地精车队，在千针石林的闪光平原与侏儒竞速，曾协助打造他们的赛车，如今还在设法寻找燃油调节器原型。",al={"加兹鲁维 闪光平原","加兹鲁维 千针石林","加兹鲁维赛车"}}},fp="13,198,25.325.0,22.523.0,29.470.0,15.227.0,46.240.0,34.264.0,45.262.0,51.208.0"}
P.entries["npc:moon-priestess-amara"] = {n="哨兵阿玛拉·夜行者",s="在多兰纳尔以西，哨兵阿玛拉·夜行者守望着泰达希尔通往达纳苏斯的道路。她守望林间小径时，有两名女猎手护卫在侧。",h="在多兰纳尔以西，哨兵阿玛拉·夜行者守望着泰达希尔通往达纳苏斯的道路。她守望林间小径时，有两名女猎手护卫在侧。",kw={"阿玛拉·夜行者","多兰纳尔","艾兰娜瑞","哨兵阿玛拉·夜行者","奈迈","泰达希尔","通往达纳苏斯的道路","耶利尤拉"},ang={["class:Priest"]="身为The Sisterhood of Elune的牧师，你与祭司阿玛拉一样，虔诚地信奉月神。她为从幽影谷启程的年轻侍僧指引道路。",["race:NightElf"]="身为暗夜精灵，你会在从多兰纳尔向西的旅途中遇见阿玛拉。她的指引与任务将引领你前往达纳苏斯。"},sec={{t="枝间道路的守护者",b="哨兵阿玛拉·夜行者与两名女猎手同伴奈麦和雅莉乌拉一同守望着多兰纳尔以西的道路。身为艾露恩姐妹会的祭司，她在岗哨上为人们提供精神指引，同时守护泰达希尔道路的安全。向西行进的旅人可以向她问明前往达纳苏斯的方向。心灵背负重担的人也可以向她寻求救赎之路。"}},faq={{q="哨兵阿玛拉·夜行者是谁？",a="哨兵阿玛拉·夜行者也被称为阿玛拉·夜行者，是艾露恩姐妹会的一名祭司。她守望着泰达希尔上多兰纳尔与达纳苏斯之间的道路，照料旅人的安全与心灵。",al={"阿玛拉是谁","祭司阿玛拉","哨兵阿玛拉·夜行者"}},{q="在哪里可以找到哨兵阿玛拉·夜行者？",a="你可以在泰达希尔多兰纳尔西边不远处的铺石道路旁找到她，她身边有两名哨兵女猎手。",al={"阿玛拉在哪里","阿玛拉位置","祭司阿玛拉地图"}},{q="站在她身边的女猎手是谁？",a="女猎手妮麦和女猎手雅里瑞拉陪伴并护卫着阿玛拉。这两名暗夜精灵哨兵协助守护道路，抵御野兽与敌对的腐化力量。",al={"阿玛拉的同伴","奈麦和雅里乌拉","阿玛拉的护卫"}}},fp="20,162,25.354.0,28.212.0,38.134.0,41.150.0"}
P.entries["npc:mor-rogal"] = {n="摩罗加尔",s="在烈日石居，摩罗加尔为旅人指引方向，前去探寻石爪山脉的险境与机遇。",h="在烈日石居，摩罗加尔为旅人指引方向，前去探寻石爪山脉的险境与机遇。",kw={"滚岩峡谷","土灵的觉醒","摩罗加尔","石爪山脉","烈日石居","牛头人"},ang={["faction:Horde"]="作为一名来到烈日石居的部落成员，你可以向摩罗加尔打听聚落外峭壁间的威胁。",["race:Tauren"]="作为一名牛头人，你或许会将卡利姆多幽深的岩洞视为圣地，在那里，肉体与心灵的试炼能够证明你的价值。"},sec={{t="峭壁间的守望者",b="摩罗加尔在烈日石居守望着石爪山脉深邃的裂隙与洞窟。那些蜿蜒的通道中蕴藏着财富，也潜伏着致命的危险。他派遣勇敢的部落旅人前往滚岩峡谷等危机四伏的地方。在摩罗加尔看来，对任何遵循内心与灵魂的指引、追寻荣耀的人而言，直面那些深处的险境都是对心灵的考验。"}},faq={{q="摩罗加尔是谁？",a="摩罗加尔是石爪山脉烈日石居的一位牛头人向导。他鼓励部落旅人深入散布在群山间的危险洞窟与峡谷，考验自己的勇气。",al={"摩罗加尔","摩罗加尔是谁","摩罗加尔的故事"}},{q="在哪里可以找到摩罗加尔？",a="你可以在烈日石居找到摩罗加尔，那里是部落在石爪山脉中部群峰间的主要据点。",al={"摩罗加尔的位置","摩罗加尔在哪里","摩罗加尔的地点"}},{q="摩罗加尔提供什么任务？",a="摩罗加尔派遣有能力的勇士前往滚岩峡谷的洞穴，那里有狗头人在开采共鸣水晶，随后又要求他们杀死高戈罗克，一个被狗头人挖出的沉睡土灵。",al={"摩罗加尔的任务","摩罗加尔想要什么"}},{q="摩罗加尔为什么关注洞窟和峡谷？",a="摩罗加尔相信，石爪山脉危机四伏的洞窟既能带来冒险，也能考验心灵的意志，而愿意冒生命危险的人将有机会获得荣耀与财富。",al={"为什么是洞窟","摩罗加尔的洞窟"}}},fp="9,112,20.352.0,17.190.0,27.119.0,32.182.1,46.158.0"}
P.entries["npc:morgan-pestle"] = {n="摩根·匹斯特",s="在暴风城的匹斯特的药剂店，摩根·匹斯特负责首都的物资供应和炼金术研究。他与在闪金镇工作的兄弟威廉·匹斯特相互协作。",h="在暴风城的匹斯特的药剂店，摩根·匹斯特负责首都的物资供应和炼金术研究。他与在闪金镇工作的兄弟威廉·匹斯特相互协作。",kw={"炼金师","摩根·匹斯特","匹斯特药剂店","运往暴风城的货物","暴风城","贸易区","威廉·匹斯特"},ang={["faction:Alliance"]="作为一名从艾尔文来到暴风城的联盟冒险者，你可以在摩根的店铺找到实用的炼金用品，也可以接到城内送货的差事。",["profession:Herbalism"]="摩根依靠从艾尔文森林各处及更远地区采集的新鲜材料，为他在暴风城贸易区的药剂店补充货源。"},sec={{t="城中的药剂师",b="摩根·匹斯特在暴风城贸易区的匹斯特的药剂店出售炼金用品、材料和药剂。他的兄弟威廉在闪金镇的狮王之傲旅店设有工坊，而摩根则在首都照管家族生意。物资来自腹地乡间，其中包括威廉向北运送的蜡烛。"}},faq={{q="在哪里可以找到摩根·匹斯特？",a="摩根·匹斯特就在暴风城贸易区的匹斯特的药剂店内。",al={"摩根·匹斯特位置","摩根·匹斯特在哪里","暴风城匹斯特药剂店"}},{q="摩根·匹斯特与威廉·匹斯特是什么关系？",a="摩根·匹斯特和威廉·匹斯特是兄弟，两人都在艾尔文从事炼金术工作。摩根经营着他们在暴风城的店铺，而威廉则在闪金镇工作。",al={"威廉·匹斯特的兄弟","威廉和摩根有亲属关系吗","匹斯特兄弟"}},{q="他在艾尔文的任务中扮演什么角色？",a="摩根接收威廉从闪金镇向北运到匹斯特的药剂店的蜡烛。他会付给送货的信使丰厚的报酬。",al={"运往暴风城的货物摩根","摩根·匹斯特任务"}}},fx={["2e5b0856"]={q="摩根·匹斯特是谁？",a="摩根·匹斯特是一名人类炼金师，也是在暴风城贸易区经营店铺的商人。他拥有并经营着匹斯特的药剂店，为城中居民出售材料、药品和各种炼金合剂。",al={"摩根·匹斯特是谁","摩根·匹斯特背景故事","匹斯特 是谁"}},ae642a6d={q="摩根·匹斯特效忠哪一方？",a="摩根·匹斯特是联盟的忠诚公民。他在暴风城贸易区的中心经营生意，为当地居民和整个王国提供支持。",al={"摩根·匹斯特阵营","摩根·匹斯特是否属于联盟","摩根·匹斯特效忠对象"}},["2ef8a55a"]={q="摩根·匹斯特为何在这里？",a="摩根·匹斯特住在暴风城，经营着自己的店铺匹斯特的药剂店。他在繁华的贸易区出售药水与饰品，并接收兄弟威廉从闪金镇发来的货物。",al={"摩根·匹斯特为何在暴风城","摩根·匹斯特 贸易区"}}},fp="13,161,19.325.0,31.81.0,47.155.0,40.128.0"}
P.entries["npc:morgan-the-collector"] = {n="收货人莫根",s="在布莱克威尔南瓜田，收货人莫根指挥迪菲亚的敲诈活动，收拢从艾尔文森林各处掠来的赃物。他坐镇农舍，协调盗窃行动，闪金镇的卫兵则在附近监视。",h="在布莱克威尔南瓜田，收货人莫根指挥迪菲亚的敲诈活动，收拢从艾尔文森林各处掠来的赃物。他坐镇农舍，协调盗窃行动，闪金镇的卫兵则在附近监视。",kw={"布莱克威尔","兄弟会","迪菲亚","杜汉","追捕","莫根","南瓜田","徽记","收货人"},ang={["class:Rogue"]="作为潜行者，你能看出莫根如何用严明的纪律，将零散的盗贼组织成一个资助叛乱的地下团伙。",["race:Human"]="作为人类，击败莫根就是反击那些叛徒，他们把暴风城宁静的农场变成了戒备森严的匪巢。"},sec={{t="艾尔文的什一税",b="收货人莫根为迪菲亚潜行者收取从艾尔文森林矿井中掠来的黄金。普通匪徒在路上骚扰旅人，莫根则指挥有组织的勒索。他收拢赃款和物资，供给兄弟会更广泛的网络。他的总部设在布莱克威尔南瓜田的农舍，身边有忠心的打手，包括苏伦娜·凯尔东和埃尔兰·杜德摩尔。"},{t="往昔的印记",b="莫根随身携带一枚独特的徽记之戒，象征着他的权威。在闪金镇，调查人员认为这枚戒指是证据，将肆虐腹地的蒙面盗贼与声名扫地的石匠行会联系起来。这个公会曾在第二次战争后重建暴风城。夺回这枚戒指，就能查明是谁在指挥林中的匪徒。"}},faq={{q="收货人莫根是谁？",a="莫根是迪菲亚潜行者的一名高级头目。他收取从艾尔文森林矿井中掠来的黄金，并协调这一带的匪徒活动。",al={"莫根是谁","莫根背景故事","艾尔文的收货人"}},{q="在哪里能找到莫根？",a="莫根把赃物存放在艾尔文森林东部布莱克威尔南瓜田的农舍里。",al={"莫根位置","收货人莫根在哪里","布莱克威尔南瓜田农舍"}},{q="暴风城为什么追捕他？",a="治安官杜汉和当地官员希望除掉莫根，切断迪菲亚在艾尔文的指挥体系，并取得证据，查明是谁在组织乡间的叛乱。",al={"为什么杀莫根","追捕目标"}},{q="他携带的戒指有什么特别之处？",a="莫根随身携带一枚徽记之戒，为当局调查他在艾尔文森林的活动提供了证据。",al={"收货人的戒指","收货人的徽记之戒","莫根戒指背景故事"}}},fx={["8321821e"]={q="收货人莫根效忠哪一方？",a="收货人莫根是迪菲亚潜行者的一名忠实干员。他并非普通的拦路强盗，而是这个犯罪组织中的头目，直接与暴风城王国作对，并在艾尔文森林腹地组织兄弟会的活动。",al={"收货人莫根阵营","摩根 属于哪个阵营","摩根 是否属于 迪菲亚"}},["5f1d52ce"]={q="收货人莫根想要什么？",a="摩根是统管艾尔文森林各地迪菲亚行动的匪首。他有着“收货人”的绰号，意在为兄弟会的叛乱聚敛财富、资源与势力，在暴风城卫兵的眼皮底下，将南瓜田变成一处设防据点。",al={"摩根 想做什么","收货人莫根的目标","收货人莫根的动机"}},["2a29f808"]={q="收货人莫根为何在艾尔文森林？",a="摩根已在布莱克威尔南瓜田站稳脚跟，亲自指挥迪菲亚潜行者在当地的行动。他与副手苏伦娜·凯尔东和埃尔兰·杜德摩尔一同藏身于农舍，严密协调着遍布这一地区的匪徒。",al={"摩根 为何在布莱克威尔南瓜田","摩根 为何来到这里"}},ceb85f69={q="收货人莫根与谁有关联？",a="他的徽记之戒成为调查证据，用来追查侵扰艾尔文森林的不法之徒及其背后的联系。",al={"摩根 与谁共事","收货人莫根的同伙","摩根 石匠"}}},fp="20,209,19.394.0,20.330.1,28.156.0,22.103.0,29.152.0,42.113.1"}
P.entries["npc:morin-cloudstalker"] = {n="摩林·云行者",s="在血蹄村向东延伸的道路旁，摩林·云行者守望着莫高雷。这位牛头人斥候留意着商路，调查威胁旅人安全的隐患。",h="在血蹄村向东延伸的道路旁，摩林·云行者守望着莫高雷。这位牛头人斥候留意着商路，调查威胁旅人安全的隐患。",kw={"血蹄村","巨门","摩林·云行者","莫高雷","被破坏的货车","菲兹普罗克主管","荆棘谷地精"},ang={["faction:Horde"]="摩林让部落的勇士们在早期就有机会保护新结识的牛头人盟友的补给和圣地。",["race:Tauren"]="作为一名从血蹄村出发的牛头人，你能看到摩林守护着你的家园，抵御强盗和公司的亵渎者。"},sec={{t="南方小径的守望者",b="摩林·云行者守望着向东通往贫瘠之地的小径。他巡视道路，保护途经莫高雷的旅人。这片平原通常很宁静，但商路往来与领地变迁让投机之徒和强盗逼近了牛头人的家园。"},{t="调查商队",b="摩林的斥候袭击了石牛湖北岸的一支荆棘谷地精商队，并将货车焚毁。地精回收者出现在烧毁的货车附近，于是他派冒险者检查残存的补给箱，查明荆棘谷地精运送的是什么。"},{t="抵御荆棘谷地精",b="荆棘谷地精已在莫高雷开展活动，让摩林除了普通匪徒的威胁之外，又多了一重忧虑。他派部落冒险者打击其伐木和采矿据点，包括对付菲兹普罗克主管，以遏制他们对这片神圣平原的破坏。"}},faq={{q="在哪里能找到摩林·云行者？",a="摩林·云行者站在血蹄村以东的土路旁，那条路通往贫瘠之地。",al={"摩林位置","摩林在哪里","摩林·云行者地图"}},{q="摩林在莫高雷承担什么职责？",a="摩林留意莫高雷南部的旅途安全，组织防御，抵御强盗和公司的入侵者。",al={"摩林·云行者是谁","摩林职责"}},{q="摩林为什么要调查被毁的商队？",a="摩林的斥候袭击了石牛湖附近的一支荆棘谷地精商队，并将货车焚毁。地精回收者出现在残骸附近后，他请冒险者检查残存的货箱，查明荆棘谷地精运送的是什么。",al={"被破坏的货车任务","莫高雷商队遇袭"}},{q="摩林为什么想阻止荆棘谷地精？",a="荆棘谷地精使用机械、砍伐森林，掠夺莫高雷的自然资源。摩林希望阻止他们的监工，包括菲兹普罗克主管。",al={"莫高雷荆棘谷地精","为什么杀死菲兹普罗克"}},{q="摩林向谁汇报？",a="摩林代表血蹄村的长者和酋长，以及莫高雷各地的牛头人领袖行事。",al={"摩林效忠对象","谁派来了摩林"}},{q="摩林会向联盟玩家提供任务吗？",a="不会。摩林忠于部落，只与部落冒险者打交道。",al={"联盟能和摩林交谈吗","摩林阵营"}}},fp="18,168,29.263.0,25.252.0,29.246.1,36.109.0,32.107.0,46.221.0,48.157.0,25.112.0,44.71.0"}
P.entries["npc:motega-firemane"] = {n="莫特加·火鬃",s="莫特加·火鬃是一位牛头人学者，驻扎在千针石林的白沙岗哨。他致力于记录峡谷中危险的野生生物，却因一个寻仇的风蛇之魂和年轻助手鲁莽惹出的麻烦而屡屡中断研究。",h="莫特加·火鬃是一位牛头人学者，驻扎在千针石林的白沙岗哨。他致力于记录峡谷中危险的野生生物，却因一个寻仇的风蛇之魂和年轻助手鲁莽惹出的麻烦而屡屡中断研究。",kw={"阿利卡拉","凯恩·血蹄","卡纳提·灰云","玛加萨·野性图腾","莫特加·火鬃","波卡·雨山","千针石林","白沙岗哨"},ang={["class:Hunter"]="猎人与莫特加志趣相投，他依靠技艺娴熟的追踪者采集峡谷植物、追踪风巢的双足飞龙，并寻猎强大的灵魂阿利卡拉。",["faction:Horde"]="莫特加代表着部落向卡利姆多荒野地区的拓展，他维持着一处处境艰难的研究哨站，同时保护The High Chieftain凯恩·血蹄免受灵魂的威胁。",["race:Tauren"]="莫特加敬畏自然，忠心追随凯恩·血蹄，体现了牛头人的精神：研究Earth Mother的生灵，同时保卫部族，抵御古老的灵魂。"},sec={{t="峡谷中的学者",b="第三次战争结束四年后，莫特加·火鬃南下千针石林，观察并记录那些在高耸台地之间生存的独特野兽。年轻的助手波卡·雨山与他同行，尽管波卡的父亲出于爱护，很不情愿让儿子离开莫高雷，莫特加还是带着他在白沙岗哨与卡纳提·灰云一同扎营。他原本只想静静观察自然，但峡谷底部的重重险境不断迫使他拿起武器求生。"},{t="阿利卡拉之怒",b="乱风岗传来消息，传说中凶猛的有翼巨蛇之魂阿利卡拉重返峡谷，要向凯恩·血蹄复仇，莫特加平静的研究生活就此被打破。莫特加不明白这样的生灵为何会与大酋长结仇，但他迅速采取行动，保护部落。他指示斥候从峡谷盆地采集火岩龙舌兰，送往雷霆崖，交给玛加萨·野性图腾长者施法制成神圣的粉末。猎人们用这粉末召唤并杀死了巨蛇之魂，将它的皮带回白沙岗哨，证明凯恩已脱离危险。"},{t="白沙岗哨的守护者",b="莫特加驻留白沙岗哨期间，面对的威胁并不只有阿利卡拉。当地的加拉克半人马不断试探营地的防御，甚至密谋刺杀卡纳提·灰云和他的追随者。更糟的是，年轻的波卡离开了安全的营火旁，消失在双足飞龙盘踞的风巢高地。莫特加虽对这位年轻勇士的鲁莽感到恼火，但当部落旅人将他活着护送回来时，仍如释重负。"}},faq={{q="莫特加·火鬃是谁？",a="莫特加·火鬃是一位牛头人研究者，驻扎在千针石林的白沙岗哨。他与其他勇士及助手波卡·雨山一同来到峡谷，研究当地的野生生物。",al={"莫特加·火鬃背景故事","莫特加是谁","白沙岗哨莫特加"}},{q="在哪里可以找到莫特加·火鬃？",a="他位于白沙岗哨，那是千针石林的一处部落小营地，坐落在该地区西北部的道路旁，靠近伊索克营地。",al={"莫特加位置","莫特加·火鬃在哪里","莫特加·火鬃地图"}},{q="莫特加为何担忧阿利卡拉？",a="阿利卡拉是一个怀恨寻仇的巨蛇之魂，现身千针石林，意图向凯恩·血蹄复仇。莫特加虽不明白这个灵魂为何怨恨大酋长，却仍认真对待这一威胁，指引猎人召唤并消灭它。",al={"阿利卡拉是谁","为何杀死阿利卡拉","阿利卡拉凯恩"}},{q="玛加萨·野性图腾在莫特加的计划中起什么作用？",a="莫特加委托冒险者采集火岩龙舌兰，将其送到雷霆崖的长者高地，交给玛加萨·野性图腾。玛加萨运用萨满知识，对这种植物施法，将其制成能够召唤行踪难觅的阿利卡拉的神圣粉末。",al={"玛加萨火岩粉","莫特加与玛加萨","神圣之火任务背景故事"}},{q="莫特加的同伴波卡出了什么事？",a="波卡·雨山误入风巢危险的双足飞龙巢穴，迷失了方向。莫特加为这个年轻人的安危忧心不已，尤其想到波卡的父亲原本就很不情愿让儿子远行，不过旅人们最终成功将他护送回白沙岗哨。",al={"波卡·雨山","风巢失踪的牛头人","回家的路任务"}},{q="白沙岗哨还面临哪些危险？",a="除了作乱的灵魂和猛兽，附近的加拉克半人马也在不断袭扰营地，策划伏击，并密谋刺杀卡纳提·灰云和其他驻守岗哨的牛头人。",al={"白沙岗哨的威胁","白沙岗哨的半人马","加拉克半人马的阴谋"}}},fx={ca68f68f={q="莫特加·火鬃效忠于哪一方？",a="莫特加·火鬃效忠于牛头人和部落。他与卡纳提·灰云一同驻扎在白沙岗哨，与部落旅者密切合作，并维护凯恩·血蹄及雷霆崖旗下各部族的利益。",al={"莫特加·火鬃的阵营","莫特加·火鬃属于部落还是联盟","莫特加是部落成员吗"}},["8b7dc2d8"]={q="莫特加·火鬃想要什么？",a="莫特加主要致力于研究千针石林独特的野生动物，同时照看年轻的同伴波卡·雨山。不过，凡是威胁雷霆崖的事都会立刻成为优先事项。得知复仇心切的风蛇阿利卡拉后，他想召唤并消灭这头野兽，以免它危及凯恩·血蹄。",al={"莫特加想要什么","莫特加·火鬃的目标","莫特加想做什么"}},["12cba981"]={q="莫特加·火鬃为什么在这里？",a="莫特加深入千针石林，观察并研究峡谷谷底及周边台地的奇异野兽。白沙岗哨是他的研究营地，不过当地麻烦——从同伴失踪到凶险的神话巨蛇——常常让他不得不放下学术研究。",al={"莫特加为什么在千针石林","是什么让莫特加来到白沙岗哨","莫特加·火鬃的目的"}}},fp="15,174,22.445.0,20.572.1,22.354.1,23.160.0,35.134.0,38.221.1,56.185.1,44.252.1,45.185.0"}
P.entries["npc:mountaineer-barleybrew"] = {n="巡山人维拉特·麦酒",s="巡山人维拉特·麦酒在南门哨岗守望着从丹莫罗通往洛克莫丹的山口。矮人酿制的美酒帮助哨兵抵御严寒。",h="巡山人维拉特·麦酒在南门哨岗守望着从丹莫罗通往洛克莫丹的山口。矮人酿制的美酒帮助哨兵抵御严寒。",kw={"麦酒","丹莫罗","巡山人","微光酒","南门哨岗","维拉特"},ang={["race:Dwarf"]="身为矮人，你深知边境执勤的艰辛，也了解烈酒如何帮助守卫卡兹莫丹的安宁。"},sec={{t="东部山口的守望",b="巡山人维拉特麦酒在南门哨岗守望着通往洛克莫丹的积雪道路。他在铁炉堡的边境守卫部队服役。如同其他在丹莫罗凛冽寒风中执勤的巡山人一样，他也珍视上好的矮人美酒。他的姓氏表明他来自声名远扬的麦酒氏族。他还协助将烈性的微光酒送到守卫手中，让他们在山口漫长的轮值中保持温暖和体力。"}},faq={{q="在哪里可以找到巡山人维拉特·麦酒？",a="你可以在南门哨岗找到巡山人维拉特·麦酒，这座矮人防御工事守卫着丹莫罗与洛克莫丹之间的东部山口。",al={"麦酒位置","巡山人维拉特·麦酒在哪","麦酒在哪里"}},{q="他在南门哨岗负责什么？",a="他在南门哨岗监视道路，并协助安排补给。其中包括供应给驻守各处山口的巡山人的微光酒。",al={"麦酒职责","麦酒做什么"}},{q="他与其他麦酒家族成员有亲属关系吗？",a="有。酿酒师雷杰德·麦酒是他的兄弟。他也可能与马莱斯、马尔金和犹鲁斯·麦酒有亲属关系。",al={"麦酒家族","犹鲁斯 麦酒亲属"}}},fx={["583559ff"]={q="巡山人维拉特·麦酒是谁？",a="巡山人维拉特麦酒是一名驻守丹莫罗东部边境的矮人哨兵。与铁炉堡的所有巡山人一样，他时刻警惕着威胁山路的野兽、穴居人和冰霜巨魔劫掠者，在履行严苛的边境职责之余，也保有矮人对优质麦酒特有的喜爱。",al={"巡山人维拉特·麦酒是谁","麦酒 是谁","巡山人维拉特·麦酒背景故事"}},["399d0350"]={q="巡山人维拉特·麦酒效忠哪一方？",a="他是铁炉堡坚定的战士，忠于联盟。他遵从铜须氏族和麦格尼国王的命令，确保王国各地旅人和重要山口的安全。",al={"巡山人维拉特·麦酒阵营","麦酒 为谁效力","麦酒 是否属于联盟"}},fc186c57={q="巡山人维拉特·麦酒想要什么？",a="除了守卫道路、抵御入侵者，巡山人维拉特·麦酒也喜欢用一杯烈酒驱散山间的严寒。他依靠过往旅人在驻地与附近盟友之间传递消息、运送补给，其中就包括一份浓烈的微光酒。",al={"麦酒 想要什么","维拉特 麦酒 需要什么","麦酒 在寻找什么"}},b2269341={q="巡山人维拉特·麦酒为何在这里？",a="他驻守在南门哨岗的山口，守卫连接丹莫罗与洛克莫丹的重要通道。游荡的野兽和凶悍的穴居人战团时常威胁这些高山隘口，需要纪律严明的巡山人维持关隘的防御与安全。",al={"麦酒 为何在 南门","巡山人维拉特·麦酒为何驻守在这里","麦酒 驻留原因"}}},fp="22,147,27.390.0,40.145.0,39.151.0,39.116.0"}
P.entries["npc:mountaineer-kadrell"] = {n="巡山人卡德雷尔",s="在塞尔萨玛的烈酒旅店对面，巡山人卡德雷尔守望着洛克莫丹。",h="在塞尔萨玛的烈酒旅店对面，巡山人卡德雷尔守望着洛克莫丹。",kw={"卡德雷尔","洛克莫丹","巡山人","罗克加","卡尔·雷矛","烈酒旅店","塞尔萨玛"},ang={["faction:Alliance"]="作为途经塞尔萨玛的联盟旅人，你可以传递消息，援助那些面临当地威胁的偏远巡山人哨站。",["race:Dwarf"]="身为矮人，你知道卡德雷尔隶属于巡山人部队。他们的守望保护着铁炉堡的东部领地，使其免受荒野中危险的侵袭。"},sec={{t="塞尔萨玛的哨兵",b="巡山人卡德雷尔守卫着塞尔萨玛，统筹洛克莫丹的矮人防务。穴居人、豺狼人和当地野兽不断威胁着山谷边缘的哨站。卡德雷尔在镇中心派遣援军、传达命令，并研判前线斥候送来的报告。"},{t="保持联络",b="巡山人卡德雷尔与塞尔萨玛远处的前哨保持着联系。他与巡山人卡尔·雷矛协调行动，并派冒险者向巡山人罗克加等哨兵报到。这些哨站守卫着山间隘口，因此卡德雷尔协助运送补给、增派人手，并传递有关威胁的消息。"}},faq={{q="在哪里可以找到巡山人卡德雷尔？",a="在洛克莫丹起伏的群山之间，塞尔萨玛的烈酒旅店马路对面可以找到巡山人卡德雷尔。",al={"卡德雷尔位置","卡德雷尔在哪","寻找卡德雷尔"}},{q="卡德雷尔在洛克莫丹担任什么职责？",a="巡山人卡德雷尔隶属于矮人巡山人部队，在塞尔萨玛的当地领袖与远处的岗哨之间传递消息。他负责协调巡逻、补给和边境报告的传递。",al={"卡德雷尔做什么","卡德雷尔的作用","卡德雷尔的职责"}},{q="为什么其他巡山人会派信使去找卡德雷尔？",a="巡山人卡德雷尔驻守在塞尔萨玛的旅店和主干道旁，便于接收前线送来的消息。远方斥候的紧急报告经由他传达给镇上的守军。",al={"向卡德雷尔报告","为什么向卡德雷尔报告"}},{q="卡德雷尔与谁协调行动？",a="巡山人卡德雷尔与在外驻守的其他巡山人合作，其中包括巡山人卡尔·雷矛和巡山人罗克加。他们共享侦察报告，部署防御，应对当地的威胁。",al={"卡德雷尔的联系人","卡德雷尔认识谁"}}},fx={fc9aa592={q="巡山人卡德雷尔是谁？",a="巡山人卡德雷尔是一名驻守在塞尔萨玛的矮人守卫。作为铁炉堡专职领土守卫 巡山人 的一员，他协助负责洛克莫丹地区的防御，组织当地侦察行动，并确保补给线与哨站的安全。",al={"卡德雷尔 是谁","巡山人卡德雷尔","卡德雷尔 的身份"}},["24c7e32d"]={q="巡山人卡德雷尔效忠哪一方？",a="卡德雷尔坚定地支持铁炉堡王国与联盟。他奉命为国王麦格尼·铜须效力，与其他巡山人、城镇治安官和当地矮人并肩守卫卡兹莫丹的边境，抵御不断逼近的威胁。",al={"卡德雷尔 阵营","卡德雷尔是联盟吗","卡德雷尔 效忠"}},["3819644d"]={q="巡山人卡德雷尔想要什么？",a="卡德雷尔希望确保塞尔萨玛及洛克莫丹周边荒野的安全。当地兵力捉襟见肘，他因此寻找有能力的旅人，帮助清剿在西部山麓肆虐的坑道鼠狗头人、四处游荡的豺狼人群，以及威胁道路和偏远哨站的其他祸害。",al={"卡德雷尔想要什么","卡德雷尔 目标","卡德雷尔 任务目标"}},["56ea1ebe"]={q="巡山人卡德雷尔为什么在塞尔萨玛？",a="卡德雷尔驻守在烈酒旅店正对面，担任塞尔萨玛的主要联络人。塞尔萨玛是洛克莫丹的主要枢纽，留在这里便于他接收偏远哨所的报告，并派遣旅人前往最需要援助的地方。",al={"卡德雷尔为什么在塞尔萨玛","卡德雷尔为什么在这里","卡德雷尔 岗位"}},f9923f59={q="巡山人卡德雷尔与谁有联系？",a="卡德雷尔与在山谷中巡逻的铁炉堡巡山人联系紧密，其中包括巡山人卡尔·雷矛和巡山人罗克加。他与洛克莫丹各处前哨的斥候协调，在边境哨站遭受压力时，将情报和援军送往需要的地方。",al={"卡德雷尔 人际关系","卡德雷尔与谁共事","卡德雷尔 联系"}}},fp="19,93,23.291.0,22.311.0,39.122.0,37.199.0,50.198.0,33.192.0"}
P.entries["npc:mountaineer-stormpike"] = {n="巡山人卡尔·雷矛",s="巡山人卡尔·雷矛在奥加兹岗哨守望着洛克莫丹通往湿地的北部道路。他是铁炉堡雷矛氏族的一员，对此深感自豪，并守护着铁炉堡的补给线，抵御穴居人和狗头人的侵扰。",h="巡山人卡尔·雷矛在奥加兹岗哨守望着洛克莫丹通往湿地的北部道路。他是铁炉堡雷矛氏族的一员，对此深感自豪，并守护着铁炉堡的补给线，抵御穴居人和狗头人的侵扰。",kw={"奥加兹","丹","狗头人","洛克","莫丹","巡山人","岗哨","巡山人卡尔·雷矛","湿地"},ang={["faction:Alliance"]="奥加兹岗哨守卫着铁炉堡与湿地的米奈希尔港之间的陆路。巡山人卡尔·雷矛的守望帮助联盟维持着这条道路的畅通。",["race:Dwarf"]="身为铁炉堡的矮人，你帮助巡山人卡尔·雷矛守卫卡兹莫丹的内陆边界，抵御四处搜掠的害兽，以此向这位巡山人同胞致敬。"},sec={{t="奥加兹岗哨的守卫",b="巡山人卡尔·雷矛驻守奥加兹岗哨，守卫着北部道路，这里正是洛克莫丹与丹奥加兹的交界处。道路穿过山口，向下延伸至湿地，沿途怪石嶙峋，荒野中危机四伏。巡山人卡尔·雷矛维持着通信畅通，并为穿越山口的旅人和补给车队清理道路。"},{t="应对当地威胁",b="附近挖掘场的狗头人和地下的穴居人侵扰着洛克莫丹北部。巡山人卡尔·雷矛召集过路的冒险者，遏制这些威胁。狗头人已经闯入银泉矿洞，夺走了矿工联盟储存的矮人工具。"}},faq={{q="在哪里可以找到巡山人卡尔·雷矛？",a="巡山人卡尔·雷矛位于洛克莫丹北部的奥加兹岗哨。他守望着向北穿过丹奥加兹、通往湿地的山路。",al={"巡山人卡尔·雷矛位置","巡山人卡尔·雷矛在哪里"}},{q="巡山人卡尔·雷矛是谁？",a="巡山人卡尔·雷矛属于铁炉堡的雷矛氏族。他在洛克莫丹北部的山口站岗巡查，防范荒野中的危险。",al={"巡山人卡尔·雷矛是谁","巡山人卡尔·雷矛背景故事"}},{q="他在奥加兹岗哨应对哪些威胁？",a="穴居人和狗头人威胁着奥加兹岗哨附近的山坡与采石场。巡山人卡尔·雷矛致力于驱逐它们，让信使和商队能够安全通行。",al={"奥加兹岗哨的危险","什么在袭击奥加兹岗哨","洛克莫丹北部的威胁"}},{q="奥加兹岗哨有什么用途？",a="奥加兹岗哨是铁炉堡的一处前哨，监视着洛克莫丹与丹奥加兹崎岖隧道之间的边界。巡山人在边境巡逻、保障商路畅通时，会将这里用作中转站。",al={"奥加兹岗哨是什么","奥加兹岗哨背景故事","奥加兹岗哨的用途"}},{q="他与奥特兰克山谷的雷矛卫队有关吗？",a="巡山人卡尔·雷矛的姓氏来自显赫的雷矛氏族，这个矮人家族以勇猛的战士和勘探者闻名于铁炉堡。他奉命驻守洛克莫丹的各处山口。",al={"奥特兰克的雷矛","雷矛氏族关联","他属于雷矛卫队吗"}},{q="巡山人卡尔·雷矛会交给冒险者哪些任务？",a="巡山人卡尔·雷矛派遣冒险者前往银泉矿洞，找回矿工联盟的装备。他还请冒险者将他订购新盾牌的订单送给暴风城的矮人护甲锻造师弗伦·长须。",al={"巡山人卡尔·雷矛任务","巡山人卡尔·雷矛的任务","肮脏的爪子任务"}}},fx={["21d9c7b3"]={q="巡山人卡尔·雷矛效忠哪一方？",a="巡山人卡尔·雷矛是矮人巡山人中自豪的一员，对铁炉堡和铜须氏族忠心耿耿。他代表国王麦格尼·铜须守卫山口，坚定地支持联盟，对黑铁氏族则怀有深深的不信任。",al={"巡山人卡尔·雷矛 阵营","巡山人卡尔·雷矛为谁效力","雷矛 效忠"}},["1b65a761"]={q="巡山人卡尔·雷矛想要什么？",a="雷矛驻守在崎岖的北方道路沿线，希望保护山口，抵御石腭怪、狗头人以及从山中涌来的其他威胁。他寻找可靠的信使和能干的战士，帮助递送物资、清剿逼近的害物，并维持奥加兹岗哨与洛克莫丹其他地区之间的联络。",al={"雷矛想要什么","雷矛 目标","巡山人卡尔·雷矛 职责"}},["60d9a34d"]={q="巡山人卡尔·雷矛为什么在奥加兹岗哨？",a="奥加兹岗哨守卫着从洛克莫丹通往湿地的重要北方通道。雷矛奉命驻守此处，监视山口、协调巡逻，并确保物资和报告能在分散的山地前哨与铁炉堡更广泛的防御体系之间安全传递。",al={"巡山人卡尔·雷矛为什么在这里","雷矛为什么在奥加兹岗哨","雷矛 驻守原因"}}},fp="21,201,25.307.0,29.246.0,39.141.0,29.143.0,48.152.0,32.213.0,55.200.0,58.212.0"}
P.entries["npc:mountaineer-thalos"] = {n="巡山人萨鲁斯",s="巡山人萨鲁斯在寒脊山小径守卫着通往卡拉诺斯的道路，信使们从这里带去紧急报告。穴居人已占据隧道，由他判断谁能安全通过。",h="巡山人萨鲁斯在寒脊山小径守卫着通往卡拉诺斯的道路，信使们从这里带去紧急报告。穴居人已占据隧道，由他判断谁能安全通过。",kw={"寒脊山小径","寒脊山谷","丹莫罗","铁炉堡巡山人","卡拉诺斯","巡山人萨鲁斯","森内尔·白须","穴居人"},ang={["faction:Alliance"]="身为联盟的一员，你依靠萨鲁斯维持山谷守军与铁炉堡中央指挥部之间的通信。",["race:Dwarf"]="作为一名年轻矮人，你离开家园的摇篮时遇见了萨鲁斯，他的存在提醒着你，穴居人的威胁已逼近铁炉堡的门户。",["race:Gnome"]="作为一名从诺莫瑞根难民庇护所出发的侏儒，你发现萨鲁斯守卫着通往卡拉诺斯和铁炉堡的主要陆路。"},sec={{t="寒脊山小径的守卫",b="穴居人从地下钻出，让寒脊山小径变得危机四伏。在白雪覆盖的入口处，寒脊山谷与丹莫罗更深处的险峻山地相接，萨鲁斯劝返尚未准备好的旅人。他考验信使是否有勇气面对穴居人盘踞的隧道。如果他们无法通过，手中的报告也许永远无法传到王国的其他地方。"},{t="信使的关卡",b="格瑞林·白须报告了这片偏僻山谷中霜鬃巨魔的动向。一名信使将他的报告送往卡拉诺斯，交给他的兄弟森内尔，但途中必须先与巡山人萨鲁斯交谈。萨鲁斯让有能力的旅人穿过小径，前往卡拉诺斯，那里的地方指挥官负责协调丹莫罗的防务。重要情报必须送到铁炉堡的军事领袖手中，不能消失在风雪里。"}},faq={{q="巡山人萨鲁斯是谁？",a="巡山人萨鲁斯为铁炉堡守卫寒脊山小径的南端入口。他看守着寒脊山谷与丹莫罗其他地区之间的交界。",al={"萨鲁斯的故事","萨鲁斯是谁","巡山人萨鲁斯"}},{q="巡山人萨鲁斯为什么警告旅人不要靠近？",a="石腭穴居人已占据寒脊山小径。萨鲁斯警告平民和初出茅庐的战士不要靠近，但有能力的信使和身经百战的战士可以进入。",al={"小径为何关闭","小径中的穴居人","寒脊山小径的危险"}},{q="巡山人萨鲁斯让冒险者去哪里？",a="萨鲁斯让旅人穿过寒脊山小径，前往卡拉诺斯，那是通往铁炉堡的道路上最近的定居点。",al={"见过萨鲁斯后去哪里","萨鲁斯指引的目的地","下一个城镇"}},{q="萨鲁斯收到森内尔·白须的什么报告？",a="萨鲁斯并未收到森内尔本人送来的报告。一名信使将格瑞林·白须关于寒脊山谷中霜鬃巨魔威胁的报告，送给他在卡拉诺斯的兄弟森内尔。萨鲁斯提醒信使小心穴居人，并让信使穿过隧道。",al={"森内尔的观察","森内尔的急报","萨鲁斯读什么"}},{q="巡山人萨鲁斯属于哪个阵营？",a="萨鲁斯隶属于铁炉堡巡山人，这些边境游骑兵为联盟巡逻丹莫罗的边界、隧道和山间小径。",al={"萨鲁斯的阵营","萨鲁斯属于铁炉堡吗","巡山人与联盟"}},{q="不与萨鲁斯交谈就无法通过寒脊山小径吗？",a="任何人都可以进入寒脊山小径，但与萨鲁斯交谈后，旅人便能将重要的侦察情报送往卡拉诺斯，并了解前方的危险。",al={"是否需要与萨鲁斯交谈","绕过萨鲁斯"}}},fx={["37207617"]={q="巡山人萨鲁斯想要什么？",a="巡山人萨鲁斯希望保障旅人的安全，警告他们远离危机四伏的寒脊山小径。隧道已被充满敌意的石腭怪占据，毫无准备的人贸然通过会十分危险。遇到身负急务的冒险者时，他会叮嘱他们小心穿过隧道，将格瑞林·白须的报告安全送交他的兄弟森内尔，后者住在矮人城镇卡拉诺斯。",al={"萨鲁斯想要什么","萨鲁斯 目标","巡山人萨鲁斯 职责"}},ae07b8df={q="巡山人萨鲁斯与谁有联系？",a="萨鲁斯是铁炉堡巡山人的一名哨兵，守卫着离开寒脊山谷的道路。信使若要将格瑞林·白须关于霜鬃巨魔的报告送交他在卡拉诺斯的兄弟森内尔·白须，就会被指引先与萨鲁斯交谈，再冒险穿过石腭怪盘踞的隧道。",al={"萨鲁斯 盟友","萨鲁斯与谁共事","萨鲁斯 森内尔·白须"}}},fp="18,176,26.347.0,22.404.0,26.156.0,49.148.0,47.111.0,54.263.0,47.144.0,56.141.0"}
P.entries["npc:mr-smite"] = {n="重拳先生",s="在铁甲湾，重拳先生看守着迪菲亚的船只和船员。这位牛头人担任绿皮队长的大副，守卫着艾德温·范克里夫的无畏舰正在进行舾装的码头。任何闯入者一旦遭遇他，就得面对他不断更换的武器和惊人的力量。",h="在铁甲湾，重拳先生看守着迪菲亚的船只和船员。这位牛头人担任绿皮队长的大副，守卫着艾德温·范克里夫的无畏舰正在进行舾装的码头。任何闯入者一旦遭遇他，就得面对他不断更换的武器和惊人的力量。",kw={"绿皮队长","死亡矿井","大副","铁甲湾","重拳先生","重拳先生的战斧","牛头人海盗","潜行者之刃","盗贼之刃"},ang={["class:Warrior"]="重拳先生展现出训练有素的战斗技巧，从迅捷的单手攻击，转为挥舞双斧，再以双手锤施展沉重打击。",["faction:Alliance"]="重拳先生阻挡联盟探员接近跳板，以及跳板后方的绿皮队长和艾德温·范克里夫。",["race:Tauren"]="对来自莫高雷的旅人来说，在东部王国看到一位牛头人在海上亡命之徒中担任大副，实在令人错愕。"},sec={{t="海湾的大副",b="重拳先生是地精绿皮队长的大副，负责维持铁甲湾码头的秩序。迪菲亚潜行者主要由心怀不满的人类和地精工匠组成，重拳先生却是一位身经百战、远离卡利姆多平原的牛头人。他管束着一群吵闹的海盗，监督他们为艾德温·范克里夫的秘密无畏舰进行舾装，不容任何人干扰这项工作。"},{t="致命的武器大师",b="重拳先生作战靠的不只是蛮力；他既爱炫耀，也是精通多种武器的大师。他戏耍挑战者，拖长战斗，让他们误以为有望获胜。受到紧逼时，他会猛踏地面，将敌人震昏，然后从附近的箱子里翻找另一件武器。他先使用一把轻快的决斗用剑，接着换上两把劈砍用的利斧，被逼到一定地步时便会取出一柄巨大的双手战锤。"}},faq={{q="为什么会有牛头人在西部荒野与人类匪徒共事？",a="大多数牛头人与部落盟友一同生活在卡利姆多，但流落在外的雇佣兵和游荡者偶尔也会东行。重拳先生是绿皮队长的大副，在铁甲湾管束船员，督促他们为无畏舰出海做好准备。",al={"死亡矿井为什么有牛头人","重拳先生的故事","牛头人海盗"}},{q="重拳先生的上司是谁？",a="重拳先生听命于绿皮队长，这位地精是停泊在铁甲湾的海盗船的船长。艾德温·范克里夫领导着迪菲亚潜行者，在这个组织更大的阴谋中，他的地位高于两人。",al={"重拳先生的上司是谁","重拳先生为谁效力"}},{q="重拳先生在战斗中使用哪些武器？",a="重拳先生起初使用潜行者之刃，随后退到箱子旁，取出一对重拳先生的战斧。被逼到极限时，他便会拔出重拳先生的大锤。",al={"重拳先生的武器","重拳先生从箱子里取出什么"}},{q="在哪里能找到重拳先生？",a="重拳先生看守着铁甲湾的木制码头，这里是死亡矿井的最后一处洞穴。他守卫着通往迪菲亚巨型无畏舰的跳板。",al={"重拳先生的位置","重拳先生在哪里"}},{q="重拳先生独自作战吗？",a="重拳先生有两名迪菲亚潜行者藏在附近，随时准备伏击沿码头向船只靠近的闯入者。",al={"重拳先生的小怪","重拳先生的护卫"}},{q="为什么重拳先生在近身战中如此危险？",a="他的牛头人技能战争践踏会让冲击波席卷木制码头，将整支小队震昏，为重拳先生争取时间，从储物箱中换上更重的武器，再次投入战斗。",al={"重拳先生的昏迷效果","重拳先生的战争践踏"}}},fp="9,259,22.364.0,21.393.0,55.249.0,28.197.0,49.156.0,29.143.0,27.125.0,52.177.0"}
P.entries["npc:mull-thunderhorn"] = {n="穆尔·雷角",s="在血蹄村，穆尔·雷角守护着莫高雷的神圣水井。他侍奉大地母亲，维护这片土地的平衡。外来者的掠夺威胁着水源，他指引年轻的牛头人净化先祖的泉水。",h="在血蹄村，穆尔·雷角守护着莫高雷的神圣水井。他侍奉大地母亲，维护这片土地的平衡。外来者的掠夺威胁着水源，他指引年轻的牛头人净化先祖的泉水。",kw={"血蹄村","莫高雷","穆尔·雷角","水源中毒","雷角图腾","荆棘谷地精","水井","蛮鬃净化","冰蹄净化"},ang={["class:Druid"]="身为德鲁伊，受到污染的水井正在毒害莫高雷野生生灵的平衡，你与穆尔有着同样的忧虑。",["class:Shaman"]="身为萨满祭司，你明白穆尔对元素和谐的倚重。他的净化图腾呼唤先祖之灵，修复因机械作业背后的贪婪而受损的水源。",["faction:Horde"]="身为部落的一员，你能看到部落民众与荆棘谷地精这类中立组织之间的紧张关系，后者未经允许便攫取卡利姆多的财富。",["race:Tauren"]="对牛头人而言，穆尔·雷角承载着部族的记忆与先祖的职责。他指引年轻勇士，保护神圣的草原免遭贪婪的外来者侵害。"},sec={{t="圣水守护者",b="穆尔·雷角在血蹄村守护着莫高雷的灵性安宁。游牧部族在大酋长凯恩·血蹄的领导下聚集于此，建立永久的家园，但贪婪与肆意扩张已开始威胁他们的土地。穆尔指引着从纳拉其营地出发的年轻勇士，号召他们保护先祖留下的命脉资源。"},{t="受污染的水井与荆棘谷地精",b="穆尔·雷角正面对冰蹄、雷角和蛮鬃水井遭到污染的危机。污染源自荆棘谷地精的地精，这个商业组织正在开凿周围的山丘，并将毒物排入当地的地下水层。穆尔派遣年轻的牛头人准备净化图腾，净化每一口先祖水井，以免污染蔓延至整片土地及其野生生灵。"}},faq={{q="穆尔·雷角是谁？",a="穆尔·雷角守护着莫高雷血蹄村的神圣水井。他主持仪式，保持大地与水源的纯净。",al={"穆尔·雷角的故事","穆尔是谁","血蹄村的穆尔"}},{q="穆尔·雷角为何担忧水井的状况？",a="冰蹄、雷角和蛮鬃等先祖水井，为莫高雷的各个部族和野生生灵提供维系生命的水源。附近作业产生的径流和污染物已经污染了泉水，威胁着草原的平衡。",al={"水井为何中毒","莫高雷水井","冰蹄水井中毒"}},{q="谁在污染莫高雷的水井？",a="荆棘谷地精的地精正在污染莫高雷的水井。这个商业组织正在莫高雷边缘开展采矿和伐木作业，将毒素排入当地的地下水层。",al={"谁在水中下毒","莫高雷的荆棘谷地精","谁污染了水井"}},{q="为何穆尔的净化任务只有牛头人参与？",a="对雷角、冰蹄和蛮鬃等牛头人氏族而言，莫高雷的水井承载着先祖的传承与精神意义。净化水井既是神圣的成年仪式，也是逐渐成年的牛头人肩负的职责。",al={"牛头人专属任务","为何仅限牛头人","穆尔·雷角任务条件"}},{q="如何净化水井？",a="穆尔请旅行者收集图腾，这些图腾以大地的馈赠祝圣，例如莫高雷野兽的足掌、利爪、兽爪和牙齿。将图腾带到受污染的水井，便可引导灵性净化的力量，洗去违背自然的毒素。",al={"如何净化水井","净化图腾","净化水源"}},{q="幻象仪祭是什么？",a="幻象仪祭是年轻牛头人与先祖及动物之灵沟通的精神之旅。参加仪式的年轻人前往血蹄村寻找扎尔曼·双月，接受这场幻象试炼，这是大地之母仪祭之一。",al={"幻象仪祭任务","幻象仪祭是什么"}}},fp="16,203,29.368.0,37.384.1,24.140.0,54.241.0,44.211.0,54.211.0,33.248.0,27.228.0"}
P.entries["npc:mupsi-shacklefridd"] = {n="穆普斯·沙克菲德",s="在贫瘠之地的棘齿城外，穆普斯·沙克菲德帮助旅者修复与热砂港的关系。",h="在贫瘠之地的棘齿城外，穆普斯·沙克菲德帮助旅者修复与热砂港的关系。",kw={"贫瘠之地","地精","穆普斯","棘齿城","声望","沙克菲德","热砂港"},sec={{t="棘齿城郊外",b="穆普斯·沙克菲德在棘齿城外的沿海道路旁工作。热砂港的卫兵在这座港口城镇的边缘巡逻，商人们来来往往。与地精关系不睦的旅者可以通过穆普斯寻求重新赢得热砂港认可的办法，只要他们带来所需的物资，并付出相应的劳力。"}},faq={{q="穆普斯·沙克菲德是谁？",a="穆普斯·沙克菲德是一名驻守在贫瘠之地棘齿城外的地精。她帮助旅者恢复在热砂港的声望。",al={"穆普斯","穆普斯是谁","棘齿城穆普斯"}},{q="在哪里能找到她？",a="你可以在贫瘠之地的棘齿城外找到穆普斯，港口卫兵和巡逻队有时会从那里经过。",al={"穆普斯位置","穆普斯·沙克菲德在哪里","寻找穆普斯"}},{q="为什么要找穆普斯·沙克菲德交谈？",a="如果你激怒了热砂港，穆普斯可以帮助你通过交纳物资来恢复声望。这种情况往往发生在与地精起了冲突，或选择站在海盗一方之后。",al={"重修旧好 棘齿城","棘齿城声望交纳","穆普斯任务"}}},fp="18,112,27.339.0,26.150.0,21.104.0,45.163.0"}
P.entries["npc:mutanus-the-devourer"] = {n="吞噬者穆坦努斯",s="吞噬者穆坦努斯是直接从翡翠梦魇中显现的苍白鱼人，形貌骇人。它潜伏在沉睡的德鲁伊纳拉雷克斯心灵最幽暗的深处，任何人试图打破梦魇对哀嚎洞穴的控制，都会引它现身吞噬。消灭这个扭曲的畸变怪物，是将纳拉雷克斯从饱受折磨的沉睡中解救出来的最后一步。",h="吞噬者穆坦努斯是直接从翡翠梦魇中显现的苍白鱼人，形貌骇人。它潜伏在沉睡的德鲁伊纳拉雷克斯心灵最幽暗的深处，任何人试图打破梦魇对哀嚎洞穴的控制，都会引它现身吞噬。消灭这个扭曲的畸变怪物，是将纳拉雷克斯从饱受折磨的沉睡中解救...",kw={"白化鱼人","贫瘠之地","深渊之戒","吞噬者","翡翠梦魇","鱼人","穆坦努斯","纳拉雷克斯","哀嚎洞穴"},ang={["class:Druid"]="Mutanus揭示了毫无防护地深入翡翠梦境会带来何等可怕的危险，一位德鲁伊同胞的心灵就这样被腐化彻底吞没。",["faction:Horde"]="部落不能容许Mutanus和Nightmare腐化贫瘠之地的腹地，威胁到维系杜隆塔尔与莫高雷生存的宝贵绿洲水源。",["race:NightElf"]="对kaldorei而言，Mutanus是一场化为实体的悲剧，体现了纳拉雷克斯治愈贫瘠之地的高尚志向如何扭曲成了骇人的噩梦。"},sec={{t="梦者最深的恐惧",b="暗夜精灵德鲁伊纳拉雷克斯引动贫瘠之地的地下泉水时，本想将它们与翡翠梦境相连，让干旱的荒原重获生机。然而，一种名为翡翠梦魇的古老腐化却侵入了他的思想。纳拉雷克斯被困在痛苦的幻象中，潜意识里的恐惧化为了实体。腐化赋予了那个噩梦一副庞大白化鱼人的形体。"},{t="清醒世界的噩梦",b="盘踞在纳拉雷克斯心中的黑暗力量将穆坦努斯派往清醒的世界，确保这位德鲁伊永远无法醒来。当纳拉雷克斯的信徒举行仪式，唤醒自己的导师时，穆坦努斯便会突破梦境与现实的边界。只要穆坦努斯尚未倒下，纳拉雷克斯就仍是自己那遭到腐化的幻想的囚徒。"}},faq={{q="吞噬者穆坦努斯是什么？",a="吞噬者穆坦努斯是诞生于翡翠梦魇的庞大畸变怪物，形似苍白的鱼人。它并非艾泽拉斯的寻常生灵，而是从沉睡的德鲁伊纳拉雷克斯遭到腐化的心灵中被召入现实的活体噩梦。",al={"穆坦努斯是谁","穆坦努斯是什么生物","穆坦努斯是鱼人吗"}},{q="穆坦努斯为什么看起来像一只巨型鱼人？",a="穆坦努斯是纳拉雷克斯噩梦的具象，腐化赋予了它一副巨型白化鱼人的形体。梦魇为何选择这种形态，至今无人知晓。",al={"为什么是鱼人","穆坦努斯为什么是鱼人","纳拉雷克斯对鱼人的恐惧"}},{q="穆坦努斯为什么会在仪式结束时出现？",a="腐化翡翠梦境的黑暗存在命令穆坦努斯阻止任何人唤醒纳拉雷克斯。当纳拉雷克斯的信徒开始唤醒仪式时，穆坦努斯便会跨入现实中的洞穴，吞噬前来营救的人。",al={"穆坦努斯何时出现","为什么召唤穆坦努斯","纳拉雷克斯仪式首领"}},{q="穆坦努斯来自哪里？",a="穆坦努斯来自翡翠梦魇，那个困住纳拉雷克斯的腐化领域。",al={"穆坦努斯的起源","穆坦努斯来自噩梦吗","翡翠梦魇 穆坦努斯"}},{q="杀死穆坦努斯就能救出纳拉雷克斯吗？",a="是的。穆坦努斯一旦被消灭，噩梦对纳拉雷克斯心灵的直接控制便会瓦解，让他的信徒得以成功唤醒这位德鲁伊，并打破笼罩洞穴的黑暗迷梦。",al={"纳拉雷克斯获救了吗","穆坦努斯死后会发生什么","唤醒纳拉雷克斯"}},{q="穆坦努斯为什么免疫暗影魔法？",a="穆坦努斯是由黑暗噩梦能量编织而成的畸变怪物，因此天生就能抵御那些足以伤害普通野兽的死灵与暗影法术。",al={"穆坦努斯暗影免疫","暗影法术穆坦努斯","穆坦努斯免疫暗影吗"}}},fx={["1d17d2ec"]={q="吞噬者穆坦努斯效忠于哪一方？",a="穆坦努斯听命于某种侵染翡翠梦境、将纳拉雷克斯困在噩梦中的黑暗腐化力量。他并非随心行事，也不是为贫瘠之地的本土野兽效力，而是服从噩梦本身的意志，被派往清醒世界，只为确保这名德鲁伊继续沉睡并遭受腐化。",al={"谁控制着穆坦努斯","穆坦努斯的阵营","穆坦努斯的效忠对象"}},["93f250d8"]={q="吞噬者穆坦努斯想要什么？",a="穆坦努斯存在的目的，就是阻止任何唤醒纳拉雷克斯的尝试。他要吞噬任何试图将沉睡的德鲁伊从噩梦掌控中解救出来的人，确保纳拉雷克斯无力反抗，让黑暗腐化继续在哀嚎洞穴中蔓延。",al={"穆坦努斯的目标","穆坦努斯为什么战斗","穆坦努斯想要做什么"}},c0fe9c52={q="吞噬者穆坦努斯与谁有关？",a="吞噬者穆坦努斯与暗夜精灵德鲁伊纳拉雷克斯有直接关联。他并非贫瘠之地自然诞生的野兽，而是纳拉雷克斯遭到腐化的心灵深处最黑暗角落所化为的实体，体现了这位德鲁伊潜意识中的恐惧，如同扭曲的噩梦降临于现实世界。",al={"穆坦努斯与纳拉雷克斯的关联","穆坦努斯和纳拉雷克斯的关系","穆坦努斯与谁有关"}}},fp="20,194,22.279.0,20.260.1,29.174.0,42.110.0,49.213.0,29.88.0,34.149.1,38.117.0"}
P.entries["npc:mux-manascrambler"] = {n="穆克斯·玛纳斯卡波",s="穆克斯·玛纳斯卡波是一位性情古怪的地精工程师，住在沙漠哨站加基森。他的许多同行只专注于炸药或采矿设备，穆克斯却对超自然力量与神秘能量有着异乎寻常的痴迷。",h="穆克斯·玛纳斯卡波是一位性情古怪的地精工程师，住在沙漠哨站加基森。他的许多同行只专注于炸药或采矿设备，穆克斯却对超自然力量与神秘能量有着异乎寻常的痴迷。",kw={"灵质","加基森","幽灵","地精工程师","玛纳斯卡波","穆克斯","塔纳利斯"},ang={["profession:Engineering"]="穆克斯是地精工匠中的异类，他利用机械齿轮和能量电池捕获并提炼无形的超自然力量，而非仅仅把东西炸得粉碎。"},sec={{t="探究无形之物的工匠",b="在加基森中心的一栋建筑内，Driz Plunkbow和他那些叮当作响的Butcherbots后面，坐着穆克斯·玛纳斯卡波。热砂港大举经营石油、枪械和回收物资的买卖，穆克斯却将才智投入更为玄奥的领域：灵体与超自然异象。他凭借精湛的技术，设计出能够探测、提炼并与幽魂残迹互动的古怪装置，将粗犷的地精工艺与亡者的无形世界连接起来。"}},faq={{q="在哪里能找到穆克斯·玛纳斯卡波？",a="穆克斯住在塔纳利斯北部的加基森。你可以在这座沙漠贸易枢纽中心附近的一栋建筑内找到他，就在德里兹·普伦克波和那些切割肉块的屠宰机器人后面。",al={"穆克斯位置","穆克斯在哪","穆克斯·玛纳斯卡波地图"}},{q="穆克斯从事什么工作？",a="穆克斯是一位痴迷于幽魂与无形力量的工程师。他不从事常规的爆破或运输工作，而是制造专门的机械装置，用来显现灵体、提炼灵质，并驾驭玄奥的超自然力量。",al={"穆克斯工作","穆克斯卖什么","穆克斯研究"}},{q="穆克斯属于某个阵营吗？",a="穆克斯隶属于在加基森开展业务的热砂港。作为一名独立行事的地精，他严格奉行商业中立，愿意帮助部落或联盟的冒险者。",al={"穆克斯是部落吗","穆克斯是中立的吗","穆克斯联盟"}}},fp="17,129,24.397.0,35.161.0,30.163.0,29.179.0"}
P.entries["npc:mydrannul"] = {n="迈德兰努尔",s="在达纳苏斯的战士区，迈德兰努尔为哨兵、士兵和访客备好了基本补给。",h="在达纳苏斯的战士区，迈德兰努尔为哨兵、士兵和访客备好了基本补给。",kw={"弹药","达纳苏斯","杂货","迈德兰努尔","泰达希尔","商人","战士区"},ang={["faction:Alliance"]="作为一名抵达泰达希尔的联盟旅人，你可以在战士区向迈德兰努尔这样的商人购买基本背包、弹药和野外口粮。",["race:NightElf"]="作为一名在达纳苏斯受训的暗夜精灵，你可以从迈德兰努尔那里购买日常装备和箭矢，为Sentinels提供补给。"},sec={{t="战士区的补给",b="迈德兰努尔在战士区的军事营帐与训练场之间经营着一个补给摊位。达纳苏斯的守卫和旅人可以在这里找到日常野外装备，包括供弓箭手和火枪手使用的弹药、飞刀、燧石、小袋和简易口粮。他的摊位为准备在泰达希尔执勤的哨兵和受训者提供所需的基本杂货。"}},faq={{q="在哪里可以找到迈德兰努尔？",a="迈德兰努尔位于战士区，这片军事区域坐落在泰达希尔树冠上的达纳苏斯东南部。",al={"迈德兰努尔位置","迈德兰努尔在哪","迈德兰努尔地图"}},{q="迈德兰努尔出售哪些货物？",a="迈德兰努尔出售容器、简易口粮、饮料、燧石和火绒、投掷武器、箭矢以及子弹。",al={"迈德兰努尔货物","迈德兰努尔卖什么","迈德兰努尔出售物品"}},{q="迈德兰努尔提供任务吗？",a="是的。迈德兰努尔会派冒险者去找他的朋友尼莎·影歌，她是鲁瑟兰村的一位渔具商人，需要有人将一个包裹送往黑海岸。",al={"迈德兰努尔任务","迈德兰努尔提供的任务"}}},fp="9,114,33.355.0,29.118.0,31.107.0,32.147.0"}
P.entries["npc:nalpak"] = {n="纳尔帕克",s="纳尔帕克是一名牛头人德鲁伊学徒，守望着贫瘠之地饱受侵扰的哀嚎洞穴。他驻守在洞穴入口上方的高处崖洞中，请求过往的冒险者协助遏制扭曲地下生态的梦魇。",h="纳尔帕克是一名牛头人德鲁伊学徒，守望着贫瘠之地饱受侵扰的哀嚎洞穴。他驻守在洞穴入口上方的高处崖洞中，请求过往的冒险者协助遏制扭曲地下生态的梦魇。",kw={"贫瘠之地德鲁伊","变异生物的皮","纳拉雷克斯的门徒","纳尔帕克","纳拉雷克斯","牛头人","哀嚎洞穴"},ang={["class:Druid"]="对其他德鲁伊而言，纳尔帕克是一个沉重的警示：当黑暗在原本旨在复苏大地的仪式中扎根时，接触翡翠梦境会变得多么危险。",["race:Tauren"]="纳尔帕克体现了牛头人治愈卡利姆多干涸土地的决心，即使灾难降临到入梦者身上，他也不肯放弃使命。"},sec={{t="洞穴上方的守望者",b="纳尔帕克栖身于哀嚎洞穴入口正上方的一处隐秘洞穴，始终忠于纳拉雷克斯的愿景。他的导师被困在地下深处遭到腐化的沉睡中，纳尔帕克则努力阻止腐化蔓延。他请冒险者收集变异生物的皮，用作皮革。"}},faq={{q="纳尔帕克在哪里？",a="纳尔帕克位于贫瘠之地中部的一处高崖洞穴中，就在通往哀嚎洞穴的天然岩石构造正上方。",al={"纳尔帕克位置","纳尔帕克在哪","寻找纳尔帕克"}},{q="纳尔帕克是谁？",a="他是一名牛头人德鲁伊，也是纳拉雷克斯的门徒之一，负责监视从哀嚎洞穴中涌出的扭曲生物，而他的导师正试图通过翡翠梦境让贫瘠之地恢复生机。",al={"纳尔帕克是谁","纳尔帕克背景故事"}},{q="纳尔帕克为什么需要变异生物的皮？",a="纳尔帕克想要检查盘踞在哀嚎洞穴中的变异生物的皮。尽管这些生物本性邪恶，他仍相信它们奇特的皮可以在制皮中派上用场。",al={"为何需要变异生物的皮","变异生物的皮任务"}},{q="纳尔帕克与纳拉雷克斯是什么关系？",a="纳尔帕克是德鲁伊纳拉雷克斯忠诚的学生和追随者，也是被派去协助那项宏大计划的门徒之一，试图重新唤醒贫瘠之地的泉水。",al={"纳尔帕克是纳拉雷克斯的门徒吗","纳尔帕克与纳拉雷克斯"}}},fx={a6c930b7={q="纳尔帕克支持哪一方？",a="纳尔帕克是纳拉雷克斯的门徒，为那些寻求治愈贫瘠之地的德鲁伊效力。他是一名牛头人，欢迎进入洞穴助其一臂之力的人，但他最效忠的仍是纳拉雷克斯的愿景，以及恢复遭到腐化的地下泉水。",al={"纳尔帕克的阵营","纳尔帕克为谁效力","纳尔帕克属于部落吗"}},ddc6c0b5={q="纳尔帕克为什么在哀嚎洞穴？",a="纳尔帕克与纳拉雷克斯及其他门徒一同来到哀嚎洞穴，试图将翡翠梦境的力量引入干旱的贫瘠之地。仪式惨遭失败后，他留守在洞穴入口附近，招募冒险者收集遭到腐化的材料，并对付洞穴中的扭曲野兽。",al={"纳尔帕克为什么在这里","纳尔帕克在哀嚎洞穴的缘由","是什么让纳尔帕克来到这里"}}},fp="6,159,25.272.0,24.139.0,14.185.0,35.165.0,41.166.0"}
P.entries["npc:nara-meideros"] = {n="娜拉·梅德隆",s="在暴风城的花园区，娜拉·梅德隆引导年轻的求道者学习艾露恩的教诲。身为居于人类首都的暗夜精灵女祭司，她让同胞感受到熟悉的信仰。",h="在暴风城的花园区，娜拉·梅德隆引导年轻的求道者学习艾露恩的教诲。身为居于人类首都的暗夜精灵女祭司，她让同胞感受到熟悉的信仰。",kw={"艾露恩","娜拉·梅德隆","暗夜精灵牧师","牧师训练师","暴风城","花园区"},ang={["class:Priest"]="作为一名在东部王国旅行的暗夜精灵牧师，你可以向纳拉请教重要的种族祈祷法术，无须返回卡利姆多。",["race:NightElf"]="远离灰谷和泰达希尔，在暴风城的石墙之内，你仍能在花园区的娜拉·梅德隆身边找到一份慰藉人心的故乡情怀。"},sec={{t="暴风城的女祭司",b="远离卡利姆多，隔着无尽之海，娜拉·梅德隆在暴风城侍奉艾露恩。暗夜精灵德鲁伊和牧师在花园区照料着一处绿意盎然的庇护所，她在那里引导年轻的求道者虔诚侍奉月亮女神。附近，人类牧师在教堂广场侍奉圣光。纳拉让到访或定居东部王国的暗夜精灵与自己的信仰保持紧密联系。"}},faq={{q="在哪里可以找到娜拉·梅德隆？",a="娜拉·梅德隆位于暴风城的花园区区，周围的月亮井和参天大树让暗夜精灵旅人想起故乡。",al={"娜拉·梅德隆位置","娜拉·梅德隆在哪里","花园区牧师训练师"}},{q="娜拉·梅德隆担任什么职责？",a="纳拉训练牧师，指引初学者和尚在信仰之路上成长的人。她会指引人类牧师前往光明大教堂，学习绝望祷言等祈祷法术。",al={"纳拉做什么","娜拉·梅德隆的作用","娜拉·梅德隆是谁"}},{q="为什么一位暗夜精灵女祭司会居住在暴风城？",a="暗夜精灵与大联盟的联系日益紧密。来自达纳苏斯的使者、德鲁伊和牧师在花园区积极活动，帮助同胞，并传承他们的精神传统。",al={"她为什么在暴风城","暴风城的暗夜精灵"}}},fx={["07f550b7"]={q="娜拉·梅德隆是谁？",a="娜拉·梅德隆是一位效力于艾露恩姐妹会的暗夜精灵月之女祭司。她远驻异乡，与联盟的凡人盟友相处，教导虔诚的侍僧学习族人的信仰传统与神圣教义。",al={"娜拉·梅德隆是谁","娜拉是谁","娜拉·梅德隆的背景故事"}},["6f64ae70"]={q="娜拉·梅德隆效忠哪一方？",a="她全心效忠于卡多雷与联盟，作为暗夜精灵信仰的使者，为寻求与神圣的圣光沟通、研习艾露恩教诲的牧师提供指引。",al={"娜拉·梅德隆的阵营","娜拉·梅德隆为谁效力","娜拉·梅德隆 联盟"}}},fp="13,172,24.363.0,31.129.0,35.179.0,51.202.0"}
P.entries["npc:narain-soothfancy"] = {n="纳瑞安",s="纳瑞安是个古怪的侏儒，住在塔纳利斯热砂港以北一间僻静的海滩小屋里。他大肆宣称自己是能预知未来的占卜大师，但熟悉他的人都认为，他的通灵本领纯属装腔作势，真正天才的是他的工程学造诣。",h="纳瑞安是个古怪的侏儒，住在塔纳利斯热砂港以北一间僻静的海滩小屋里。他大肆宣称自己是能预知未来的占卜大师，但熟悉他的人都认为，他的通灵本领纯属装腔作势，真正天才的是他的工程学造诣。",kw={"艾索雷葛斯","工程师","纳瑞安","柔想","占卜师","热砂港","塔纳利斯"},ang={["profession:Engineering"]="工程师们会被纳瑞安异想天开的发明深深吸引，即便他更喜欢把自己的机械杰作说成是神秘的幻象。",["race:Gnome"]="纳瑞安将侏儒的奇思妙想发挥到了古怪的极致，既能以卓越的技术解决难题，又沉迷于稀奇古怪的爱好。"},sec={{t="通灵幻象与实用机械",b="纳瑞安住在塔纳利斯东海岸、地精码头以北，是一位退休后自封占卜大师的工程师。他迎接访客时，常把未拆封的信封贴在额头上，或是胡乱猜测对方的来意，比如猜他们是不是来寻找传说中的灰烬使者。尽管总爱装神弄鬼，纳瑞安却拥有深厚的技术知识。就连蓝龙艾索雷葛斯这样的古老生灵也承认，虽然纳瑞安的通灵本领糟糕透顶，但他的工程学天赋无疑出类拔萃。附近放着一本名为《傻瓜预言书》的手册。"},{t="海岸坠机",b="在热砂港附近定居之前，纳瑞安曾在遥远的南方、天涯海滩一带遭遇一次惨烈的飞行器坠毁事故。一次意外的救援让他从事故中生还，但古怪的性情与奇异的癖好使他一直独居在沙漠海岸，摆弄与奥术沾边的技术，向过路的人兜售可疑的预言。"}},faq={{q="纳瑞安是谁？",a="纳瑞安是一位退休的侏儒工程师，住在塔纳利斯的热砂港以北。他自称占卜大师，占卜结果却出了名地不准。",al={"纳瑞安背景故事","纳瑞安是谁","塔纳利斯通灵侏儒"}},{q="纳瑞安真的会通灵吗？",a="不会。像巨龙艾索雷葛斯这样强大的熟人，都公开说他的通灵本领糟糕透顶。无论他如何煞有介事地表演读心术，他真正的天赋始终在于精湛的工程技艺和机械制作。",al={"纳瑞安能预知未来吗","纳瑞安会通灵吗","索斯法恩占卜师"}},{q="他身旁的《傻瓜预言书》是什么书？",a="那是一本放在纳瑞安小屋里的手册，与专业技能有关。纳瑞安会指引寻求这类知识的旅行者去查阅这本书。",al={"傻瓜预言书","纳瑞安专业技能书"}},{q="纳瑞安是怎么认识艾索雷葛斯的？",a="纳瑞安与游荡在艾萨拉的蓝龙艾索雷葛斯是旧识。尽管纳瑞安总爱古怪地装神弄鬼，这条巨龙仍敬重他无与伦比的工程与制造技艺。",al={"纳瑞安与艾索雷葛斯","蓝龙纳瑞安"}}},fp="17,220,37.467.0,17.352.0,25.186.0,29.143.0,54.161.0,30.180.0"}
P.entries["npc:naralex"] = {n="纳拉雷克斯",s="纳拉雷克斯是一位暗夜精灵德鲁伊，他曾试图借助翡翠梦境的力量，让干旱的贫瘠之地重归葱郁的森林。然而，黑暗的梦魇侵占了他的沉眠，扭曲了地下的哀嚎洞穴，也将他的追随者变成了身怀剧毒的怪物。",h="纳拉雷克斯是一位暗夜精灵德鲁伊，他曾试图借助翡翠梦境的力量，让干旱的贫瘠之地重归葱郁的森林。然而，黑暗的梦魇侵占了他的沉眠，扭曲了地下的哀嚎洞穴，也将他的追随者变成了身怀剧毒的怪物。",kw={"塞纳里奥议会","变异","纳拉雷克斯的信徒","尖牙德鲁伊","翡翠梦境","翡翠梦魇","纳拉雷克斯","贫瘠之地","哀嚎洞穴"},ang={["class:Druid"]="纳拉雷克斯的遭遇给德鲁伊留下了严峻的警示：盲目干预原初的自然状态，或是不加谨慎地过度深入梦境，都可能让荒野发生灾难性的扭曲。",["faction:Horde"]="一位暗夜精灵失败的神秘实验污染了贫瘠之地的腹地，迫使十字路口的部落军队应对从洞穴中蜂拥而出的狂暴野兽。",["race:NightElf"]="纳拉雷克斯本想治愈卡利姆多，但他在部落领土深处肆意膨胀的野心却让塞纳里奥议会蒙羞，还催生了背信弃义的尖牙德鲁伊。",["race:Tauren"]="贫瘠之地下方遭到扭曲的水体，正直接威胁着绿洲水池和野生生物，而莫高雷与草原上的部族正是依靠它们维持生计。"},sec={{t="绿意之愿",b="早在大灾变之前，贫瘠之地上烈日炙烤的平原曾是一片生机盎然的森林。纳拉雷克斯视这片森林的消失为一场悲剧，于是带着一群忠诚的弟子来到贫瘠之地，试图扭转这里的干旱。在草原深处的地下，他发现了由地下泉水和喷涌的间歇泉构成的复杂水系，便根据风与蒸汽穿过岩石时发出的哀号，将这里命名为哀嚎洞穴。他相信，只要进入深度冥想，将翡翠梦境的纯净能量引入这些地下水中，滋养生命的水流就能抵达地表，让整片荒原重新绽放生机。"},{t="苏醒的梦魇",b="纳拉雷克斯在地下洞穴深处盘坐冥想，但当他的意识触及梦境领域的那一刻，这个崇高的计划便彻底崩溃。他的心灵未能找到宁静的荒野自然之源，反而被一种恶毒而不断蔓延的腐化所困——那便是翡翠梦魇。不断滋长的腐化占据了这位沉睡德鲁伊的身体，将他变成一道敞开的通道，让黑暗能量渗入生者的世界。纯净的泉水变得污浊，滋生出变异的菌丛，也将洞穴中的本土野兽扭曲成了贪婪嗜食的变异怪物。"},{t="堕落的弟子",b="梦魇的侵蚀并未止于野生生物。从纳拉雷克斯冥想中外溢的精神反噬让他的弟子彻底陷入疯狂，背弃了塞纳里奥议会的传统。他们抛弃了对平衡的敬畏，化身为蛇，并将自己改称为尖牙德鲁伊。他们坚信，自己扭曲的生长必须蔓延至整个卡利姆多，如今便守护着纳拉雷克斯沉睡的身躯，确保他永远不会醒来，只剩少数忠诚的弟子仍在寻找有勇气打破冥想的盟友。"}},faq={{q="纳拉雷克斯是谁？",a="纳拉雷克斯是塞纳里奥议会的一位暗夜精灵德鲁伊。他率领一支探险队深入哀嚎洞穴，希望借助翡翠梦境的力量，让干旱的贫瘠之地恢复成大分裂之前那片葱郁的森林。",al={"纳拉雷克斯的故事","沉睡的精灵是谁","哀嚎洞穴的沉睡者"}},{q="纳拉雷克斯为何沉睡在哀嚎洞穴中？",a="他进入冥想，试图将翡翠梦境的能量直接引入贫瘠之地下方的地下含水层。然而，一场强大的梦魇占据了他的心灵，将他困在狂乱的沉眠中，无法自行醒来。",al={"纳拉雷克斯为何沉睡","纳拉雷克斯在做什么","纳拉雷克斯的冥想"}},{q="尖牙德鲁伊是如何产生的？",a="他们原本是纳拉雷克斯忠诚的弟子。当翡翠梦魇腐化了纳拉雷克斯与梦境的联系时，外泄的恶意让他的追随者陷入了疯狂。他们背弃了塞纳里奥议会，转而崇奉蛇类图腾，如今守护着他的沉眠，让腐化继续蔓延。",al={"尖牙德鲁伊的起源","尖牙德鲁伊是谁","纳拉雷克斯的弟子"}},{q="是什么导致哀嚎洞穴发生变异？",a="纳拉雷克斯沉睡的身体成了翡翠梦魇的一道敞开的通道。污秽的梦境能量直接渗入地下河流系统，将洞穴中的植物、鳄鱼、迅猛龙和蛇扭曲成了极具攻击性的变异生物。",al={"哀嚎洞穴为何遭到腐化","变异野兽的起源","哀嚎洞穴的真菌"}},{q="纳拉雷克斯能被唤醒吗？",a="可以，但需要外界的帮助。一位忠诚的纳拉雷克斯的信徒正与愿意深入洞穴的冒险者合作，击杀扭曲的尖牙德鲁伊，并举行仪式，解除梦魇对纳拉雷克斯心灵的控制。",al={"如何拯救纳拉雷克斯","唤醒纳拉雷克斯","纳拉雷克斯的任务"}},{q="纳拉雷克斯为何想要改变贫瘠之地？",a="纳拉雷克斯得知，在大灾变撕裂卡利姆多之前，贫瘠之地曾是一片繁茂的森林。他将这里如今的干旱视为生态的创伤，希望恢复那片古老而苍翠的林冠。",al={"为何让贫瘠之地重现森林","纳拉雷克斯在贫瘠之地的目标","为何选择贫瘠之地"}}},fx={ec55d9d1={q="纳拉雷克斯支持哪一方？",a="纳拉雷克斯属于塞纳里奥议会，因此对联盟和部落都保持中立。他效忠于自然的平衡，而非卡利姆多的政治纷争。遗憾的是，他被困的心灵已彻底失控，沉睡的躯体由扭曲的昔日侍僧守护，他们会攻击任何闯入者。",al={"纳拉雷克斯属于联盟还是部落","纳拉雷克斯的阵营","纳拉雷克斯为谁效力"}},["4a5a8c9e"]={q="纳拉雷克斯与谁有关？",a="纳拉雷克斯是一名德高望重的塞纳里奥议会暗夜精灵德鲁伊，曾带领一队忠诚的门徒来到贫瘠之地。他的大多数追随者都屈服于笼罩其心灵的黑暗噩梦，变成了凶猛的尖牙德鲁伊。仍有少数人忠于他，例如守在入口上方洞穴中的纳尔帕克和厄布鲁，以及在洞穴内部等候的纳拉雷克斯的门徒。",al={"纳拉雷克斯的盟友","纳拉雷克斯的门徒","纳拉雷克斯的追随者有哪些"}}},fp="7,246,17.424.0,20.370.0,16.418.1,15.219.0,49.188.0,36.263.0,42.223.0,24.193.1,43.187.0"}
P.entries["npc:nat-pagle"] = {n="纳特·帕格",s="纳特·帕格被广泛誉为艾泽拉斯最负盛名的钓鱼大师，尽管他声称钓鱼只是为了找个借口痛饮。他住在尘泥沼泽一处僻静的海湾，教导那些证明了自己耐心的联盟和部落钓鱼高手。",h="纳特·帕格被广泛誉为艾泽拉斯最负盛名的钓鱼大师，尽管他声称钓鱼只是为了找个借口痛饮。他住在尘泥沼泽一处僻静的海湾，教导那些证明了自己耐心的联盟和部落钓鱼高手。",kw={"大师级钓鱼","尘泥沼泽","加兹兰卡","格瑞诺尔·石印","鲁玛克","纳特·帕格","帕格","帕格渔点"},ang={["faction:Alliance"]="铁炉堡的格瑞诺尔·石印等矮人钓鱼大师十分敬重纳特，会派经验丰富的联盟渔夫南下尘泥沼泽，学习垂钓之道最后的奥秘。",["faction:Horde"]="鲁玛克是奥格瑞玛荣誉谷的钓鱼训练师，他视纳特·帕格为挚友，并派有潜力的部落渔夫南下向他求教。"},sec={{t="钓鱼大师",b="尽管纳特·帕格的名字在已知世界各地都是高超钓技的代名词，他本人对这门技艺却格外随意。他垂钓已有数十年，却常常坦言自己对钓鱼这项活动并无多少敬意，还曾说钓鱼不过是找个方便的借口，坐下来开怀畅饮，这句话广为人知。尽管纳特言语粗直、态度漫不经心，他对水生生物和垂钓之道的了解却无人能及，甚至还有经他授权、备受专业钓手追捧的渔具。"},{t="沼泽隐士",b="帕格在尘泥沼泽东海岸的一小片岬地上扎营，远离东部王国喧闹的酒馆。他始终坚持独来独往，对阵营间的政治毫无兴趣，既欢迎格瑞诺尔·石印等训练师派来的联盟旅人，也接纳奥格瑞玛的鲁玛克指点而来的部落求学者。在纳特看来，凡是愿意踏遍世界各个角落寻找稀有鱼种的人，都值得学上一课真正的垂钓之道。"},{t="往事与海怪",b="帕格曾涉足凶险的水域，其中一次深入祖尔格拉布的废墟，将心爱的卷尺和钓具箱遗落在巨型多头蛇加兹兰卡出没的水域附近。"}},faq={{q="纳特·帕格是谁？",a="纳特·帕格是艾泽拉斯最著名的渔夫。他垂钓已有数十年，如今在尘泥沼泽沿海过着平静的生活，教导那些技艺已超出普通训练师所能传授范围的资深钓手。",al={"纳特是谁","纳特·帕格背景故事","钓鱼的那个人是谁"}},{q="在哪里能找到纳特·帕格？",a="他住在卡利姆多尘泥沼泽东海岸的一小片岬地上，位于塞拉摩岛西南方。",al={"纳特·帕格在哪","纳特·帕格位置","寻找纳特·帕格"}},{q="纳特·帕格既然说不喜欢钓鱼，为什么还要钓鱼？",a="帕格曾坦率地承认，在他看来，钓鱼主要是个体面的借口，让他能不受打扰地坐在水边，一连痛饮数个小时。",al={"纳特喜欢钓鱼吗","纳特为什么钓鱼","纳特·帕格喝酒"}},{q="纳特·帕格会教导部落成员吗？",a="会。纳特对阵营之间的争斗完全保持中立。部落钓手的技艺达到普通训练所能传授的上限后，他在奥格瑞玛的朋友鲁玛克就会直接派他们去找他。",al={"纳特只教联盟吗","部落纳特·帕格","部落能和纳特交谈吗"}},{q="纳特·帕格与祖尔格拉布有什么联系？",a="纳特曾在古老的巨魔城市祖尔格拉布中钓鱼，将钓具箱和珍爱的卷尺遗落在巨型多头蛇加兹兰卡栖身的水域附近。",al={"纳特在zg","纳特·帕格钓具箱","纳特·帕格祖尔格拉布"}}},fp="9,188,17.271.0,18.366.0,26.164.0,17.206.0,29.119.0,50.101.0,42.157.0,49.165.0"}
P.entries["npc:natalia-mar-alith"] = {n="Natalia Mar'alith",s="纳塔莉亚玛尔利斯女士是一位暗夜精灵女祭司，也是塞纳里奥议会的研究员，在雷戈虫巢的异种虫巢穴深处失踪。她曾随丈夫指挥官玛尔利斯深入希利苏斯的荒野，随后出发前往虫巢探险。",h="纳塔莉亚玛尔利斯女士是一位暗夜精灵女祭司，也是塞纳里奥议会的研究员，在雷戈虫巢的异种虫巢穴深处失踪。她曾随丈夫指挥官玛尔利斯深入希利苏斯的荒野，随后出发前往虫巢探险。",kw={"布莱恩·铜须","塞纳里奥要塞","雷戈虫巢","深入疯狂之口","玛尔利斯","纳塔莉亚","希利苏斯"},ang={["faction:Alliance"]="在铜须营地，鲁特加尔·雕石和弗兰卡·石桥向追寻布莱恩探险足迹的联盟探险者讲述了她堕落的可怕细节。",["race:NightElf"]="纳塔莉亚的悲惨堕落给kaldorei留下了沉重的警示：即使是他们最虔诚的女祭司，也难以抵挡埋藏在希利苏斯沙漠之下的古老恐怖。"},sec={{t="悲剧性的沉沦",b="塞纳里奥议会在塞纳里奥要塞建立据点，监视沙漠中苏醒的动静时，纳塔莉亚随丈夫指挥官玛尔利斯来到了荒野。为了揭开异种虫再度活跃和古老其拉虫人遗迹背后的谜团，她加入了著名探险家布莱恩·铜须率领的探险队，同行的还有矮人研究员鲁特加尔·雕石和弗兰卡·石桥。"},{t="雷戈虫巢的水晶",b="探险队循着奇异的能量波动，进入了雷戈虫巢的南部。在虫巢的核心深处，他们发现了一块刻有古老其拉虫人符文的巨型水晶。纳塔莉亚被水晶低语般的共鸣吸引，凑近仔细研究那些符文。水晶中的黑暗魔法顷刻间便吞噬了她的心智，摧毁了她的理智，将她的意志束缚于克苏恩。矮人同伴将她抬回塞纳里奥要塞，德鲁伊在那里唤醒了她，但几周后，遭到附身的她突然闯回他们的营地，强求返回虫巢，众人不得不将她击退。如今，她已成为虫巢那位恐怖主人的狂热守卫。"},{t="指挥官的痛苦",b="在塞纳里奥要塞，指挥官玛尔利斯仍拼命守着妻子尚能获救的希望，不肯接受她的心智已被彻底摧毁、无法挽回的事实。然而，任何冒险深入雷戈虫巢的人，找到的都不是等待救援的俘虏，而是一个冷酷无情的疯狂仆从，施展着被上古之神恶意扭曲的神圣牧师魔法。"}},faq={{q="纳塔莉亚玛尔利斯是谁？",a="纳塔莉亚玛尔利斯是塞纳里奥议会的一位暗夜精灵女祭司，也是指挥官玛尔利斯的妻子。她加入了布莱恩·铜须深入雷戈虫巢的侦察队，研究异种虫再度活跃的原因，却在那里遭到古老黑暗魔法的侵害。",al={"纳塔莉亚·玛尔利斯","纳塔莉亚是谁","指挥官玛尔利斯的妻子"}},{q="在哪里能找到纳塔莉亚玛尔利斯？",a="她位于希利苏斯南部雷戈虫巢的虫类隧道深处，守在一块布满符文、散发光芒的水晶前。",al={"纳塔莉亚位置","纳塔莉亚在哪里","雷戈虫巢女祭司"}},{q="纳塔莉亚为什么敌视冒险者？",a="在研究一块其拉水晶时，纳塔莉亚被上古之神克苏恩的低语彻底腐化，心智也随之崩溃。如今，她狂热地守护着水晶，攻击任何进入虫巢的人。",al={"纳塔莉亚为什么攻击我","纳塔莉亚为什么疯了","纳塔莉亚被洗脑"}},{q="纳塔莉亚失踪时和谁在一起？",a="她与布莱恩·铜须、鲁特加尔·雕石和弗兰卡·石桥一同深入雷戈虫巢。鲁特加尔和弗兰卡在这场劫难中幸存下来，撤回希利苏斯南部的铜须营地，讲述了这段经历。",al={"纳塔莉亚探险","谁和纳塔莉亚同行","布莱恩和纳塔莉亚"}},{q="她为什么在战斗中如此危险？",a="纳塔莉亚仍保有强大的牧师力量，不断用心灵尖啸驱散攻击者，并通过几乎不消耗法力的强效治疗术恢复自身状态，若不持续打断她的施法，就很难将她击败。",al={"纳塔莉亚战斗","如何击败纳塔莉亚","纳塔莉亚治疗"}}},fp="17,238,16.372.0,25.584.1,23.306.1,25.230.1,35.129.0,38.179.1,43.211.0,34.207.0"}
P.entries["npc:nathanos-blightcaller"] = {n="纳萨诺斯·凋零者",s="纳萨诺斯·凋零者曾名为纳萨诺斯·玛瑞斯，如今作为希尔瓦娜斯·风行者女王麾下的致命勇士，驻守在东瘟疫之地已成废墟的故居。生前，他是奎尔萨拉斯第一位，也是唯一一位人类游侠领主；死后，他训练被遗忘者猎人，守卫东部边境，对所有来者都报以刻薄的蔑视。",h="纳萨诺斯·凋零者曾名为纳萨诺斯·玛瑞斯，如今作为希尔瓦娜斯·风行者女王麾下的致命勇士，驻守在东瘟疫之地已成废墟的故居。生前，他是奎尔萨拉斯第一位，也是唯一一位人类游侠领主；死后，他训练被遗忘者猎人，守卫东部边境，对所有来...",kw={"凋零者","旅行者","猎人训练师","玛瑞斯","玛瑞斯农场","纳萨诺斯","瘟疫之地","希尔瓦娜斯"},ang={["class:Hunter"]="纳萨诺斯是被遗忘者中地位最高的猎人训练师，将奎尔萨拉斯的旅行者严苛而富有传奇色彩的射术传授给洛丹伦的亡灵。",["faction:Alliance"]="一位功勋卓著的洛丹伦英雄、一位声名显赫的旅行者，如今却在被遗忘者的旗帜下作战，这对暴风城而言是莫大的羞辱，也是在战术上足以致命的难题。",["faction:Horde"]="纳萨诺斯在瘟疫之地为部落提供关键的战术指导和猎人训练，尽管他对来访者总是报以尖刻的鄙夷。",["race:Undead"]="作为黑暗女王麾下的勇士，纳萨诺斯体现了被遗忘者饱含怨恨却坚韧不屈的意志，但他对同僚的无能几乎毫无耐心。"},sec={{t="唯一的人类旅行者",b="第三次战争前，纳萨诺斯·玛瑞斯是一位出身洛丹伦乡野的神射手，也是一位战术奇才。他接受过奎尔萨拉斯高等精灵的训练，与希尔瓦娜斯·风行者关系密切，成为唯一获授游侠领主这一崇高军衔的人类。他的家始终是位于洛丹伦的家族庄园——玛瑞斯农场。"},{t="陨落与重生",b="斯坦索姆遭到清洗后，阿尔萨斯王子率天灾军团横扫洛丹伦，瘟疫吞噬了整个王国。纳萨诺斯在自己的庄园拼死抵抗，却倒在了可怖的憎恶吞咽者拉姆斯登手下。他被复活为没有心智的亡灵奴仆，游荡在染疫的田野间，以巫妖王之名杀戮。希尔瓦娜斯挣脱天灾军团的精神控制，在幽暗城建立被遗忘者之后，便前来寻找他，而他似乎早已知道她会来；她将他的意识从巫妖王的意志中解放出来，让他带着卓越的战术才华和炽烈的忠诚重归她的麾下。"},{t="女妖之王的勇士",b="纳萨诺斯以凋零者为名，在破败的玛瑞斯农场长住下来。他在战火纷争的东瘟疫之地担任Sylvanas麾下的勇士、猎人训练师和当地的间谍首领，由污秽的瘟疫犬护卫。联盟情报部门发现他仍然存在，深感不安；伯瓦尔·弗塔根公爵认为，像纳萨诺斯这样出色的战术大师统领亡灵部队，对人类的生存构成了无法容忍的威胁，因此派出突击队，刺杀这位陨落的游侠领主。"}},faq={{q="纳萨诺斯·凋零者是谁？",a="纳萨诺斯·凋零者曾名为纳萨诺斯·玛瑞斯，是一位著名的人类神射手，也是唯一获授奎尔萨拉斯游侠领主军衔的非精灵。他在第三次战争中死去并被复活，随后希尔瓦娜斯将他的心智从天灾军团的控制中解放出来。如今，他在东瘟疫之地的祖宅担任她麾下的勇士和猎人训练师。",al={"纳萨诺斯是谁","纳萨诺斯背景故事","玛瑞斯农场的人是谁"}},{q="纳萨诺斯为什么在玛瑞斯农场？",a="玛瑞斯农场是纳萨诺斯生前的家，他也正是在这里为保卫洛丹伦而战死。成为亡灵后，他选择回到已成废墟的庄园，将其改为前哨，训练被遗忘者猎人，并监视联盟与天灾军团的动向。",al={"纳萨诺斯在哪里","纳萨诺斯为什么在瘟疫之地","玛瑞斯农场纳萨诺斯"}},{q="纳萨诺斯是如何变成亡灵的？",a="第三次战争期间，纳萨诺斯在自己的家园被天灾军团的憎恶吞咽者拉姆斯登杀死。他被复活为巫妖王麾下毫无心智、唯命是从的奴仆，直到希尔瓦娜斯前来寻找他，解放了他的心智，让他得以加入被遗忘者。",al={"纳萨诺斯怎么死的","谁杀了纳萨诺斯","纳萨诺斯之死"}},{q="联盟为什么要杀他？",a="暴风城的联盟高层发现，纳萨诺斯·玛瑞斯这位联盟最杰出的军事头脑和战术奇才之一，并未就此长眠，而是加入了被遗忘者。伯瓦尔·弗塔根公爵认为他的战术才华构成了巨大威胁，因此下令将他除掉。",al={"为什么杀纳萨诺斯","联盟任务纳萨诺斯","重铸秩序"}},{q="他与希尔瓦娜斯是什么关系？",a="纳萨诺斯生前便与希尔瓦娜斯关系密切，当时奎尔萨拉斯的精灵授予他游侠领主军衔，使他成为其中唯一的人类，如今他则是她麾下的勇士。成为亡灵后，他对女妖之王的忠诚依然绝对，毫不动摇。",al={"希尔瓦娜斯和纳萨诺斯","希尔瓦娜斯爱过纳萨诺斯吗","纳萨诺斯与希尔瓦娜斯的恋情"}},{q="他身旁的猎犬是什么？",a="那些是纳萨诺斯亲自训练的凶恶瘟疫犬。它们留在他身边，守卫玛瑞斯农场的废墟，攻击任何胆敢擅闯他领地的愚蠢入侵者。",al={"纳萨诺斯的狗","玛瑞斯农场猎犬","凋零者的宠物"}}},fp="21,258,25.292.0,20.607.0,29.380.1,29.318.0,36.197.0,34.221.0,39.257.0,39.198.0,37.159.0"}
P.entries["npc:nida"] = {n="希拉里",s="在湖畔镇的码头，希拉里正为掉进止水湖的项链哭泣。",h="在湖畔镇的码头，希拉里正为掉进止水湖的项链哭泣。",kw={"孩子","希拉里","止水湖","湖畔镇","项链","尼达","赤脊山","肖恩"},ang={["faction:Alliance"]="赤脊山面临着更大的麻烦，而帮助希拉里，能为湖畔镇带来一丝温暖与纯真。"},sec={{t="孩子丢失的纪念物",b="希拉里在湖畔镇的码头边流着泪等候，害怕父亲会生气。她把父亲送给她的项链掉进了止水湖，希望有勇敢的人能潜入水中找到它。豺狼人的入侵和黑石兽人的战团威胁着湖畔镇，但镇上的孩子们仍有自己的烦恼。"}},faq={{q="希拉里是谁？",a="希拉里是湖畔镇的一个人类小女孩，经常能看见她在码头附近哭泣。",al={"妮达是谁","妮达 湖畔镇","湖畔镇哭泣的女孩"}},{q="希拉里为什么哭泣？",a="希拉里哭泣，是因为父亲给她买的项链滑落进了止水湖，她害怕父亲得知项链丢失后会生气。",al={"她为什么哭泣","妮达为什么伤心","妮达的哭声"}},{q="谁在设法帮她寻找项链？",a="她的玩伴肖恩看到她伤心，便请路过的冒险者潜入止水湖，帮她寻找项链。",al={"谁帮助妮达","妮达的朋友","谁给妮达任务"}},{q="丢失的项链在哪里？",a="项链沉在止水湖的水下，就在湖畔镇码头附近，希拉里弄丢它的地方。",al={"妮达的项链在哪里","止水湖项链位置"}}},fp="6,82,23.311.0,14.77.0,21.138.0,44.116.0,35.97.0"}
P.entries["npc:nikova-raskol"] = {n="尼科瓦·拉斯克",s="在旧城区，尼科瓦·拉斯克为惨遭杀害的孙子寻求公道。迪菲亚潜行者的暴徒仍被关在监狱里，这位年迈的暴风城市民向冒险者求助。",h="在旧城区，尼科瓦·拉斯克为惨遭杀害的孙子寻求公道。迪菲亚潜行者的暴徒仍被关在监狱里，这位年迈的暴风城市民向冒险者求助。",kw={"迪菲亚面罩","麦克","尼科瓦·拉斯克","旧城区","监狱","暴风城","血的颜色"},ang={["faction:Alliance"]="对于身在暴风城的联盟勇士而言，帮助尼科瓦会让你想起，保卫王国意味着保护那些因内乱而家破人亡的普通市民。"},sec={{t="祖母的悲痛",b="尼科瓦·拉斯克走在旧城区的街道上，心中满是对爱孙麦克的哀思。迪菲亚潜行者的匪徒杀害了他。王国面临大规模的叛乱，而尼科瓦独自承受着兄弟会肆意横行带来的丧亲之痛。"},{t="监狱中的复仇",b="许多四处作乱的罪犯被捕后关进了监狱。如今，囚犯发动的暴乱已使整座监狱陷落，守卫未能恢复秩序。尼科瓦向准备进入监狱的冒险者求助。她请他们带回红色迪菲亚面罩，证明杀害她孙子的凶手已得到报应。"}},faq={{q="尼科瓦·拉斯克是谁？",a="尼科瓦·拉斯克是一位年迈的暴风城居民，常沿着旧城区的椭圆形道路行走。她哀悼着被迪菲亚暴徒杀害的孙子麦克。",al={"尼科瓦是谁","尼科瓦·拉斯克的身份","尼科瓦·拉斯克的故事"}},{q="她的孙子麦克遭遇了什么？",a="麦克当时十四岁。军队开赴前线后，他拿起武器，在关押迪菲亚囚犯的监狱里担任守卫。囚犯们把羊毛毯撕成帮派围巾，他训斥了他们，随后便遭到他们从背后捅刺。",al={"麦克是谁","麦克遭遇了什么","麦克是怎么死的"}},{q="她为什么想要监狱里的红色面罩？",a="红色面罩是迪菲亚潜行者的标志。尼科瓦请进入暴乱中的监狱的战士带回这些头巾，证明那些残害无辜的罪犯已受到惩处。",al={"血的颜色","为什么要红色面罩","迪菲亚面罩"}},{q="在哪里能找到尼科瓦·拉斯克？",a="尼科瓦沿着旧城区的主干道来回踱步，就在猪和哨声旅店和暴风城的训练场附近。",al={"尼科瓦在哪里","尼科瓦的位置","尼科瓦·拉斯克的行走路线"}}},fx={dc3813b4={q="尼科瓦·拉斯克效忠哪一方？",a="尼科瓦·拉斯克坚定地支持暴风城与联盟。她是一位住在都城中心的老妇人，满腔仇恨全都指向迪菲亚潜行者，因为她认定他们杀害了自己的家人。",al={"尼科瓦属于联盟吗","尼科瓦·拉斯克的阵营","尼科瓦效忠哪一方"}},cb2616e5={q="尼科瓦·拉斯克为什么在旧城区？",a="尼科瓦在旧城区的石板街道上徘徊，因为暴风城是她的家。悲痛与对伸张正义的渴望占据了她的心，她在城中来回踱步，寻找有能力的英雄，向那些被关押在街道下方的犯罪阴谋者还击。",al={"尼科瓦为什么在这里","尼科瓦·拉斯克为什么在暴风城","尼科瓦·拉斯克为什么在旧城区"}}},fp="13,186,21.224.0,25.326.0,21.133.0,34.241.0,49.204.0,33.119.0"}
P.entries["npc:nissa-firestone"] = {n="尼莎·火石",s="在铁炉堡的Great Forge上方，尼莎·火石向旅人和士兵传授战地医疗知识。",h="在铁炉堡的Great Forge上方，尼莎·火石向旅人和士兵传授战地医疗知识。",kw={"联盟外科医疗队","绷带","急救","大锻炉","医者","铁炉堡医师协会","尼莎·火石"},ang={["faction:Alliance"]="身为途经卡兹莫丹的联盟冒险者，你可以向尼莎这样的训练师学习必备的求生方法，无须借助神圣或奥术魔法。",["race:Dwarf"]="身为一名刚与穴居人或冰霜巨魔交战归来的矮人，你能在尼莎身上看到铁炉堡医学务实、干练的传统。"},sec={{t="铁砧上方的医者",b="尼莎·火石在铁炉堡医师协会店铺的楼上照料伤者。她为伤者包扎伤口时，Great Forge的铿锵声与热浪依然传到这里。矮人战士十分坚韧，但刀刃和利爪依旧能划破他们的皮肤。在旅人和士兵踏入丹莫罗的雪地或前往更远的地方之前，尼莎会教他们基本的绷带包扎与战地伤口处理。这些技能能帮助他们和盟友保住性命。"},{t="伤员分诊与重伤救治",b="尼莎·火石教战地医护人员使用布料和绒布。当她已将所知倾囊相授，便会指引他们前往遥远的哨站，向专门负责伤员分诊的军官求教。熟练的医者会前往联盟伤亡最惨重的地方。"}},faq={{q="尼莎·火石是谁？",a="尼莎·火石是一名矮人，在大锻炉南侧外围的铁炉堡医师协会店铺教授急救。",al={"尼莎·火石是谁","尼莎·火石职责","铁炉堡急救训练师"}},{q="在哪里可以找到尼莎·火石？",a="尼莎·火石在铁炉堡大锻炉环形区域南缘的铁炉堡医师协会店铺楼上工作。",al={"尼莎·火石位置","尼莎在哪里","铁炉堡医师协会位置"}},{q="尼莎·火石教授什么？",a="尼莎·火石向联盟冒险者教授急救，包括如何制作绷带和解毒剂，以应对野外的伤情。",al={"尼莎教授什么","铁炉堡急救","铁炉堡学习绷带制作"}},{q="尼莎能教授大师级伤员分诊吗？",a="不能。当医护人员达到较高的熟练程度时，尼莎会通过联盟外科医疗队任务指引他们前往别处，寻找活跃战区附近经验丰富的战地外科医师。",al={"联盟外科医疗队任务","铁炉堡大师级急救","急救超过225"}}},fx={f16b91f7={q="尼莎·火石效忠哪一方？",a="尼莎·火石坚定地支持铁炉堡与联盟。她驻守在都城的高处，运用自己的医学知识，通过战地包扎和创伤救治，保障铁炉堡守卫与联盟旅人的生命。",al={"尼莎·火石的阵营","尼莎属于联盟吗","尼莎为谁效力"}},bc93403c={q="尼莎·火石为什么在铁炉堡？",a="尼莎在大锻炉上方的铁炉堡医师协会店铺工作。这里位于矮人都城的中心，她既能照料城中的病患与伤员，也能训练勇于冒险的战地医护人员，让他们在奔赴战场前学会包扎伤口与止血。",al={"尼莎为什么在这里","尼莎·火石在此的原因","尼莎为何来到铁炉堡"}},["2ef2db38"]={q="尼莎·火石想要什么？",a="身为医师与训练师，尼莎最希望确保联盟战士懂得如何在野外为自己包扎疗伤。当有潜力的医护人员学有所成，超出她能教授的范围时，她便会指引他们去寻找更高明的战地外科医师，学习战时伤员分诊。",al={"尼莎想要什么","尼莎·火石的目标","尼莎·火石的动机"}}},fp="15,98,25.423.0,26.224.0,23.123.0,33.122.0,32.130.0,36.169.0"}
P.entries["npc:nogg"] = {n="诺格",s="在奥格瑞玛的荣誉谷，诺格以自己的技艺为部落效力。他研究从诺莫瑞根深处回收的奇异机械残骸。",h="在奥格瑞玛的荣誉谷，诺格以自己的技艺为部落效力。他研究从诺莫瑞根深处回收的奇异机械残骸。",kw={"诺莫瑞根","地精工程师","机械工坊","诺格","奥格瑞玛","归还戒指"},ang={["faction:Horde"]="身为一名从东部王国的危险行动中归来的部落战士，你可以把粗陋的回收物件交给诺格。他能将它们制成经过精密调校的作战装备。",["profession:Engineering"]="身为工程师，你可以到荣誉谷的诺格工坊购买零件，聊上几句。你也可以观看他如何轻松地改造精密的侏儒装置，使其另作他用。"},sec={{t="诺格的工坊",b="诺格在奥格瑞玛的荣誉谷经营着一家独立的工程学工坊。在这座以兽人的钢铁与力量闻名的城市里，冒险者和工匠前来寻求一位地精的机械技艺。他热衷于检视从联盟领地或地下遗迹带来的奇特装置与小玩意。"},{t="侏儒装置与回收零件",b="从诺莫瑞根回收的物件格外引起诺格的兴趣。部落特工从这座陷落的侏儒首都带回精密的戒指和其他残存物件。在杜隆塔尔，鲜有人能拆解这些奇异的发条装置，弄懂其原理，再加以改造供部落使用。"}},faq={{q="在哪里可以找到诺格？",a="诺格在奥格瑞玛荣誉谷的工程学工坊里工作。",al={"诺格位置","诺格在哪里","诺格的机械工坊"}},{q="诺格与诺莫瑞根有什么联系？",a="部落冒险者从卡兹莫丹境内诺莫瑞根遭受辐射的隧道中回收精密装置。诺格检视并改装他们带回的侏儒戒指。",al={"诺格为何关注诺莫瑞根","诺格戒指","戒指归来"}},{q="诺格属于部落吗？",a="诺格是奥格瑞玛的一名独立地精工匠，凭借技术为部落冒险者提供服务。",al={"诺格属于部落吗","诺格阵营"}},{q="诺格能改造或重铸戒指吗？",a="能。把一枚从诺莫瑞根经超级清洁器提取的戒指交给诺格，他就能将其拆解并重新组装，赋予它不同的附魔或机械特性。",al={"戒指重铸","改造诺莫瑞根戒指"}}},fx={["81166680"]={q="诺格是谁？",a="诺格是一位富有进取心的地精工程师，在奥格瑞玛的荣誉谷经营诺格机械店。和许多居住在部落都城的地精一样，他向机械工匠与冒险者提供机械方面的服务，始终以敏锐的商业眼光和务实态度，关注有趣的装置与可回收的技术物资。",al={"诺格是谁","诺格的背景故事","诺格的身份"}},c0d235dc={q="诺格想要什么？",a="诺格想要新颖的工程零件、奇特的机械造物，以及能带来丰厚利润的机会。他有兴趣研究冒险者回收的精巧戒指，也关注诺莫瑞根的钻探机之战等冲突造成的技术混乱，以促进店铺的生意。",al={"诺格想要什么","诺格的目标","诺格任务的目的"}},["0ba8fca5"]={q="诺格为什么在奥格瑞玛？",a="诺格在奥格瑞玛的荣誉谷经营生意，繁华的都城为他源源不断地带来顾客、原材料，以及愿意执行危险差事的冒险佣兵。部落对工程技术的持续需求，让他的机械店生意兴隆。",al={"诺格为什么在这里","诺格为什么在奥格瑞玛","诺格在此的原因"}}},fp="4,141,15.288.0,27.262.0,22.72.0,40.161.0,26.105.0,32.152.0"}
P.entries["npc:nori-pridedrift"] = {n="诺里斯·激流",s="在寒脊山谷，诺里斯·激流将温热的晨酒送到那些抵御严寒的人手中。他调制并出售这种饮品，雇用脚程快的信使，趁热将它送达。",h="在寒脊山谷，诺里斯·激流将温热的晨酒送到那些抵御严寒的人手中。他调制并出售这种饮品，雇用脚程快的信使，趁热将它送达。",kw={"酿造","寒脊山谷","丹莫罗","矮人","晨酿杯子","诺里斯·激流","热酒"},ang={["profession:Cooking"]="身为丹莫罗的一名厨师，你能体会诺里斯的用心：即使空气冰冷，他也要让自己的特色饮品滚烫地送到客人手中。",["race:Dwarf"]="身为矮人，你知道在冰冷的天气里，一杯烈酒能带来怎样的慰藉。诺里斯的热Mornbrew在山间哨所很受欢迎。"},sec={{t="雪中的一杯热饮",b="诺里斯·激流将热酒送往寒脊山谷各处冰封的地带。寒风刺骨，一杯热饮能为巡山人和冻得发抖的哨兵带来暖意。诺里斯调制这种类似咖啡的饮品，再交给信使送出，信使必须赶在山间冷风将它吹凉之前送达。他的结实杯子数量有限，因此他希望跑腿的人及时将杯子带回。"}},faq={{q="诺里斯·激流是谁？",a="诺里斯·激流是寒脊山谷的一名矮人小贩。他调制并出售热酒，这是一种供当地卫兵和矿工饮用的热饮，类似咖啡。",al={"诺里斯是谁","诺里斯·激流的故事","热酒商人"}},{q="热酒是什么？",a="热酒是诺里斯·激流调制的一种热饮。山谷居民喜欢靠它取暖，抵御丹莫罗的酷寒。",al={"热酒","诺里斯卖什么饮品"}},{q="为什么送货如此紧急？",a="热酒最受欢迎的时候，就是它滚烫的时候。寒脊山谷的山风很快就会把杯中的饮品吹凉，因此诺里斯的信使必须赶快送到顾客手中。",al={"为什么要赶着送货","热酒紧急配送","饮品为什么会变凉"}},{q="为什么诺里斯如此在意归还杯子？",a="诺里斯在山谷里可用的饮用杯数量有限。如果顾客把杯子留下，或是在雪地里摔碎，他早晨的生意很快就会难以为继。",al={"为什么要带回杯子","诺里斯的杯子","归还杯子"}}},fx={ddac60d5={q="诺里斯·激流效忠哪一方？",a="诺里斯坚定地支持铁炉堡矮人与联盟。他是在寒脊山谷独立经营的当地商人，为守卫并居住在山谷中的巡山人、受训者和居民提供服务。",al={"诺里斯·激流的阵营","诺里斯为谁工作","诺里斯·激流 联盟"}},["26ccfe8e"]={q="诺里斯·激流想要什么？",a="诺里斯想在寒脊山谷经营一门有利可图的酿酒生意。他最关心的是，确保招牌热酒送到口渴的顾客手中时仍然滚烫，并让每一个空酒杯都回到自己的库存中。",al={"诺里斯·激流的目标","诺里斯想要什么","诺里斯的动机"}},["10ad6fd1"]={q="诺里斯·激流为什么在这里？",a="诺里斯在寒脊山谷四处走动，因为他那些口渴的顾客都在那里。严酷冰冷的山地气候，让他滚烫的晨间饮品格外受到当地守卫和受训者的欢迎，为他带来了稳定的生意。",al={"诺里斯为什么在寒脊山谷","诺里斯为什么在这里","诺里斯·激流的位置"}}},fp="15,175,26.385.0,23.151.0,26.130.0,29.157.0,48.144.0"}
P.entries["npc:novice-elreth"] = {n="新兵艾尔雷斯",s="在丧钟镇的礼拜堂内，新兵艾尔雷斯指引着刚刚复生的被遗忘者。她派他们对抗坟墓附近无意识的天灾军团，并帮助他们面对瘟疫留下的悲惨余波。",h="在丧钟镇的礼拜堂内，新兵艾尔雷斯指引着刚刚复生的被遗忘者。她派他们对抗坟墓附近无意识的天灾军团，并帮助他们面对瘟疫留下的悲惨余波。",kw={"礼拜堂","教堂","丧钟镇","被遗忘者","玛拉的遗愿","新兵艾尔雷斯","被诅咒者","提瑞斯法林地"},ang={["class:Priest"]="身为牧师，你在洛丹伦昔日的圣地遇见新兵艾尔雷斯。她的工作展现了亡灵严酷而现实的需求。",["race:Undead"]="作为刚刚复生的被遗忘者，你可以在新兵艾尔雷斯的指引下，迈出生存所需的最初几步。她将你冰冷的仇恨引向无意识的Scourge。"},sec={{t="诅咒教堂中的引路人",b="新兵艾尔雷斯在丧钟镇遭到亵渎的礼拜堂内，指引着刚刚复生的亡灵。他们竭力理解自己可怕的苏醒，而被遗忘者必须迅速组织起来，确保领地安全。艾尔雷斯派他们南下，收集狼爪和蝙蝠翅膀。她还引导他们了解洛丹伦遭遇悲剧后的境况，其中就有她的朋友玛拉·菲普斯的悲惨遭遇：玛拉的丈夫塞缪尔沦为无意识的天灾军团成员后，杀死了她。"}},faq={{q="新兵艾尔雷斯在哪里？",a="新兵艾尔雷斯位于丧钟镇的礼拜堂内。丧钟镇是提瑞斯法林地的一座破败村庄，新生的被遗忘者在这里苏醒。",al={"艾尔雷斯位置","艾尔雷斯在哪","新兵艾尔雷斯教堂"}},{q="新兵艾尔雷斯在丧钟镇承担什么职责？",a="新兵艾尔雷斯指引着刚刚复生的被遗忘者，向他们下达最初的指令。她教导他们打击在村庄墓地游荡的无意识天灾军团。",al={"艾尔雷斯做什么","艾尔雷斯职责","新兵艾尔雷斯作用"}},{q="新兵艾尔雷斯提供哪些任务？",a="新兵艾尔雷斯派冒险者收集食腐狼爪和夜行蝙蝠的翅膀，并击败失去意识的塞缪尔·菲普斯，将他的遗骸安葬在妻子玛拉的墓旁。",al={"新兵艾尔雷斯任务","艾尔雷斯任务"}},{q="为什么她的头衔是“新兵”？",a="新兵艾尔雷斯的头衔以及她在礼拜堂中的位置，表明她可能是被遗忘者宗教或民政体系中的一名新人。她正在学习如何遵循被遗忘者的秩序，管理提瑞斯法刚刚复生的亡灵。",al={"为何叫新兵","艾尔雷斯新兵含义","艾尔雷斯是牧师吗"}}},fp="13,181,35.454.0,31.122.0,43.163.0,37.183.0,27.199.0"}
P.entries["npc:oben-rageclaw"] = {n="奥本·怒爪",s="在班奈希尔兽穴中，奥本·怒爪的灵魂徘徊不去，既无法苏醒，也无法安息。他沉睡的躯体仍被瘤背熊怪控制着。",h="在班奈希尔兽穴中，奥本·怒爪的灵魂徘徊不去，既无法苏醒，也无法安息。他沉睡的躯体仍被瘤背熊怪控制着。",kw={"班奈希尔兽穴","利爪德鲁伊","翡翠梦境","瘤背","奥本·怒爪","泰达希尔","沉睡的德鲁伊"},ang={["class:Druid"]="身为德鲁伊，奥本的命运让你看到，当神圣的兽穴无人守护时，陷入冥想、与翡翠梦境沟通的德鲁伊是多么脆弱。",["race:NightElf"]="身为暗夜精灵，你看到瘤背熊怪的腐化已经深深侵蚀了泰达希尔的原生居民和神圣庇护之地。"},sec={{t="遭亵渎的沉眠",b="奥本·怒爪进入班奈希尔兽穴，与自然沟通，漫游翡翠梦境，许多利爪德鲁伊都会这样做。当瘤背熊怪堕入腐化、占据兽穴时，奥本仍在冥想中，对外界毫无防备。一名腐化的瘤背萨满祭司利用黑暗仪式，控制了他昏迷的躯体。他的灵魂被留在外面，成了痛苦的幽灵，既无法苏醒，也无法安息。"},{t="摧毁躯壳",b="奥本·怒爪无法从萨满祭司的控制中夺回自己的躯体。穿行于危险隧道中的旅人，可以找到并摧毁萨满祭司操控的躯体，终结他的折磨。当那具躯壳倒下，奥本饱受折磨的幽灵便能摆脱地下的幽暗，在翡翠梦境中安息。"}},faq={{q="奥本·怒爪是谁？",a="奥本·怒爪是一名暗夜精灵利爪德鲁伊，他的灵魂被腐化的熊怪与躯体分离，如今徘徊在泰达希尔的班奈希尔兽穴中。",al={"奥本是谁","奥本·怒爪的故事","兽穴中的灵魂"}},{q="奥本·怒爪为什么会变成幽灵？",a="奥本·怒爪在德鲁伊的冥想中沉睡，与翡翠梦境沟通时，变成了幽灵。瘤背熊怪萨满祭司进入兽穴，用邪恶的魔法控制了他的躯体，将他的灵魂困在躯体之外。",al={"奥本为什么死了","奥本怎么死的","奥本为什么是幽灵"}},{q="奥本的躯体在哪里？",a="奥本的躯体位于班奈希尔兽穴蜿蜒通道的深处，受那些腐化了兽穴的瘤背萨满祭司控制。",al={"寻找奥本的躯体","奥本的躯体在哪里","沉睡的德鲁伊位置"}},{q="奥本的躯体被摧毁后会发生什么？",a="奥本的躯体被摧毁后，瘤背萨满祭司对他的控制便会解除。他的灵魂得以离开泰达希尔，在翡翠梦境中安息。",al={"奥本的命运","奥本的灵魂会怎样","拯救奥本"}}},fp="13,139,20.397.0,19.309.1,21.149.0,29.213.0,30.134.0,44.146.1"}
P.entries["npc:oggleflint"] = {n="奥格弗林特",s="在奥格瑞玛地下，奥格弗林特统领着怒焰裂谷的穴居人部族。他的族群从遍布熔岩的隧道向地表攀行，他则在洞穴入口附近指挥他们，威胁着上方的部落都城。",h="在奥格瑞玛地下，奥格弗林特统领着怒焰裂谷的穴居人部族。他的族群从遍布熔岩的隧道向地表攀行，他则在洞穴入口附近指挥他们，威胁着上方的部落都城。",kw={"奥格弗林特","奥格瑞玛","怒焰裂谷","灼热之刃","穴居人"},ang={["class:Warrior"]="身为战士，你面对的是一个身形壮硕的蛮横对手，他依靠的是蛮力与原始的怒火，而非护甲或纪律。",["faction:Horde"]="在萨尔的堡垒下方，奥格弗林特的穴居人在杜隆塔尔腹地构成了一股狂暴而难以预测的安全威胁。",["race:Orc"]="作为一名在武力试炼中证明自己的年轻兽人，在Drag下方迎战这位酋长，将考验你的战斗纪律。"},sec={{t="深处的酋长",b="在奥格瑞玛的地下深处，奥格弗林特和他的穴居人从烈焰隧道中爬出，进入了怒焰裂谷。他们在熔岩之间开辟了一片原始领地，并以残暴的武力守卫着它。穴居人的文明十分落后，奥格弗林特全凭力量统治自己的族群。"},{t="使者之死",b="老妪玛加萨·野性图腾派遣使者进入裂谷，试图与穴居人讲和。穴居人却向他们发难，将他们杀害。玛尔·恐怖图腾也是使者之一，他的尸体躺在奥格弗林特看守的洞穴中。酋长在洞穴入口附近守候，袭击那些冒险踏入黑暗的外来者。"},{t="奥格瑞玛地下的威胁",b="奥格弗林特的部族就住在萨尔都城的正下方，这是部落无法容忍的隐患。穴居人正悄然逼近地表，若放任不管，他们暴躁的天性可能会驱使他们闯入暗巷区和暗影裂口。"}},faq={{q="奥格弗林特是谁？",a="奥格弗林特是一名强大的穴居人酋长，在奥格瑞玛地下的怒焰裂谷中统领着自己的族群。",al={"奥格弗林特","奥格弗林特是谁","怒焰裂谷穴居人首领"}},{q="在哪里能找到奥格弗林特？",a="奥格弗林特在怒焰裂谷上层的洞穴中守候，位置靠近入口隧道。他的族群占据着最接近地表的隧道。",al={"奥格弗林特在哪里","奥格弗林特位置","寻找奥格弗林特"}},{q="穴居人为何会在怒焰裂谷？",a="穴居人天生就栖居在地下深处的火山洞穴网络中。奥格弗林特的族群从奥格瑞玛地下遍布熔岩的隧道中爬出，向地表靠近。",al={"奥格瑞玛地下为何有穴居人","怒焰裂谷穴居人背景"}},{q="奥格弗林特为何敌视部落？",a="穴居人极其凶暴，领地意识强烈。随着奥格弗林特和他的追随者不断逼近地表，他们威胁着部落的隧道和上方的城市。",al={"为何杀死奥格弗林特","为何与奥格弗林特战斗"}},{q="奥格弗林特与灼热之刃有什么关系？",a="奥格弗林特的穴居人与灼热之刃的教徒同处裂谷，但并无迹象表明双方是盟友。穴居人占据着入口附近的隧道，教徒则在更深处的洞室中活动。",al={"灼热之刃与奥格弗林特","穴居人与教派是一伙的吗"}}},fp="10,178,21.284.0,15.314.0,28.240.0,18.96.0,30.127.0,37.173.0,39.154.0,57.195.0"}
P.entries["npc:ogtinc"] = {n="奥汀克",s="奥汀克是一位独来独往的熊怪猎人，栖身于艾萨拉的一处高岭，俯瞰着埃达拉斯废墟。他离开自己的部族，投身于维护自然平衡的事业，成为塞纳里奥议会信赖的盟友与导师。技艺娴熟的猎人若想挑战卡利姆多最凶猛的野兽，检验自己的本领，往往会前来寻求他的指点。",h="奥汀克是一位独来独往的熊怪猎人，栖身于艾萨拉的一处高岭，俯瞰着埃达拉斯废墟。他离开自己的部族，投身于维护自然平衡的事业，成为塞纳里奥议会信赖的盟友与导师。技艺娴熟的猎人若想挑战卡利姆多最凶猛的野兽，检验自己的本领，往往会...",kw={"艾萨拉","塞纳里奥","埃达拉斯","熊怪","猎人","奥汀克","木喉"},ang={["class:Druid"]="作为塞纳里奥议会坚定的伙伴，奥汀克是一道罕见的桥梁，将未受腐化的熊怪的荒野智慧与德鲁伊守护自然的职责联系在一起。",["class:Hunter"]="奥汀克为经验丰富的猎人提供深入精神与实践的试炼，让他们面对卡利姆多最致命的生物，检验自己的射术与生存本领。"},sec={{t="离群的熊怪",b="卡利姆多的大多数熊怪依然与自己的部族紧密相连，或是在第三次大战之后沦于腐化，奥汀克却选择了一条截然不同的道路。他离开族人，以自己的弓箭和野外生存知识帮助塞纳里奥议会。他在木喉要塞东南方的一处高崖上扎营，警惕地守望着艾萨拉这片古老而破碎的土地。"},{t="狩猎大师",b="奥汀克深谙卡利姆多的荒野，因此在经验丰富的追踪者中享有盛名。他考验那些已在各片大陆磨炼过技艺的猎人，派他们收集稀有的狩猎战利品，诸如奔鹿的鹿角、饱受海浪冲击的海蛇的鳞片，以及绿色龙类的身体部位。通过这些试炼，他教导猎人，真正的狩猎应当尊重自然、维护平衡，而非盲目杀生。"}},faq={{q="奥汀克是谁？",a="奥汀克是一位技艺精湛的熊怪猎人，驻留在艾萨拉的悬崖之上。他的同胞大多与世隔绝或已遭腐化，他却离开了祖辈所属的部族，为塞纳里奥议会的德鲁伊献上自己的追踪本领与智慧。",al={"奥汀克是谁","奥汀克背景故事","艾萨拉的熊怪"}},{q="在哪里可以找到奥汀克？",a="他位于艾萨拉，在木喉要塞东南方不远处的悬崖边扎营，俯瞰着古老的埃达拉斯废墟。",al={"奥汀克在哪里","奥汀克位置","如何找到奥汀克"}},{q="奥汀克为什么离开自己的部族？",a="奥汀克离开族人，正是为了协助塞纳里奥议会保护自然。虽然他究竟出自哪个部族尚不明确，但他清醒的神志与平和的举止，与卡利姆多北部其他地方遭到腐化的部族形成了鲜明对比。",al={"奥汀克为何离开","奥汀克的部族","奥汀克是木喉成员吗"}},{q="奥汀克对猎人而言有何作用？",a="奥汀克是一位大师级导师，指引那些训练已臻巅峰的老练猎人。他要求他们追踪卡利姆多各地的凶猛野兽，从迅捷的奔鹿到绿龙军团的子嗣，以此证明他们驾驭荒野的本领。",al={"奥汀克猎人任务","猎人训练师奥汀克","为何拜访奥汀克"}},{q="奥汀克隶属于木喉要塞吗？",a="虽然奥汀克在木喉要塞附近扎营，但他独立行动，直接与塞纳里奥议会合作。对于和平接近的旅人，他一向友善，无论他们与木喉部族的关系如何。",al={"奥汀克 木喉","木喉声望 奥汀克","奥汀克友善吗"}},{q="奥汀克为什么守望着埃达拉斯废墟？",a="他身处废墟上方的高处，可以毫无遮挡地观察下方动荡的荒野，那里有娜迦、元素生物和残留的魔法回响，威胁着海岸森林脆弱的平衡。",al={"奥汀克为何在艾萨拉","埃达拉斯 奥汀克","奥汀克悬崖"}}},fp="6,228,15.307.0,18.372.0,14.136.0,26.99.0,31.209.0,39.196.0,41.170.0,49.187.0"}
P.entries["npc:ogunaro-wolfrunner"] = {n="奥古纳罗",s="在奥格瑞玛的荣誉谷，奥古纳罗在猎手大厅旁照料着部落最重要的狼舍。他为兽人勇士及其信赖的盟友繁育并训练凶猛的战狼。",h="在奥格瑞玛的荣誉谷，奥古纳罗在猎手大厅旁照料着部落最重要的狼舍。他为兽人勇士及其信赖的盟友繁育并训练凶猛的战狼。",kw={"恐狼","奥古纳罗","奥格瑞玛坐骑","森林狼","荣誉谷","狼坐骑"},ang={["faction:Horde"]="巨魔、牛头人和被遗忘者必须向奥格瑞玛证明自己的忠诚与荣誉，奥古纳罗才会将狼托付给他们。",["race:Orc"]="对兽人而言，骑狼是祖辈传下的传统，可以追溯到德拉诺的氏族时代。奥古纳罗让这份战斗中的纽带延续至今。"},sec={{t="狼群之主",b="奥古纳罗在奥格瑞玛荣誉谷的猎手大厅旁照料着城中的战狼。从德拉诺的平原到杜隆塔尔的荒野，兽人与狼之间的纽带已延续了数代。这份纽带建立在相互尊重之上，而非单纯的驯养。无论是恐狼还是敏捷的森林猎狼，奥古纳罗只会将最强健的野兽托付给那些已向大酋长证明自身实力与价值的勇士。"}},faq={{q="奥古纳罗是谁？",a="奥古纳罗是部落首屈一指的狼类繁育师兼坐骑商人，就在奥格瑞玛荣誉谷的猎手大厅外。",al={"奥古纳罗","奥格瑞玛狼坐骑商人","兽人坐骑商人"}},{q="任何人都能从他那里买到狼吗？",a="兽人接受适当训练后，便可凭借族群传承获得狼坐骑。其他部落成员则必须将声望提升至崇拜，赢得奥格瑞玛的充分信任，奥古纳罗才会交出一头狼。",al={"非兽人能否购买狼","狼坐骑声望要求"}},{q="他提供哪些种类的狼？",a="奥古纳罗提供黑狼、棕狼、恐狼和森林狼，还有适合久经沙场的老兵骑乘的迅捷披甲品种。",al={"狼坐骑种类","奥古纳罗出售哪些狼"}}},fp="18,200,18.420.0,26.126.0,36.181.0,37.115.0"}
P.entries["npc:old-murk-eye"] = {n="老瞎眼",s="老瞎眼在西部荒野灯塔附近的南部海岸徘徊。同族敬畏他，水手们则惧怕他给所有靠近灯塔的人带来的致命威胁。",h="老瞎眼在西部荒野灯塔附近的南部海岸徘徊。同族敬畏他，水手们则惧怕他给所有靠近灯塔的人带来的致命威胁。",kw={"葛瑞森船长","海岸威胁","老瞎眼","鱼人","西部荒野","西部荒野灯塔"},ang={["faction:Alliance"]="对于清剿西部荒野的联盟冒险者来说，老瞎眼是个臭名昭著的猎食者，专门袭击受困的旅人和船员。"},sec={{t="海岸的恐怖",b="老瞎眼在西部荒野灯塔周围的浪涛中捕猎。他远比西部荒野沿岸常见的鱼人强韧，也更具攻击性。他的袭击让当地水手饱受苦难，因此幽灵葛瑞森船长想要除掉他。葛瑞森船长悬赏收取老瞎眼完好无损的鳞片，希望打破他对浅滩的控制。"}},faq={{q="老瞎眼在哪里游荡？",a="老瞎眼在西部荒野西南部的沙滩和浅水中巡游，活动范围就在西部荒野灯塔附近的海岸。",al={"老瞎眼位置","哪里能找到老瞎眼","老瞎眼在哪里"}},{q="葛瑞森船长为什么想要除掉老瞎眼？",a="葛瑞森船长认为，老瞎眼一直威胁着沿岸水域。他悬赏收取一片鳞片，作为击杀的凭证，希望遏制海滩上的暴行。",al={"葛瑞森船长 老瞎眼","为什么要杀老瞎眼"}},{q="老瞎眼和普通鱼人有什么不同？",a="有。老瞎眼比身边的滩行者和猎潮者喽啰更强壮、更耐打，也更具攻击性。他是当地沿岸鱼人群落中的部族勇士。",al={"老瞎眼有多强","老瞎眼是精英吗"}}},fx={["0038f035"]={q="老瞎眼是谁？",a="老瞎眼是一个臭名昭著、体魄强健的鱼人，在西部荒野灯塔附近的西部荒野海岸巡游。当地居民和水手都视他为沿海的一大祸患，他比同类格外顽强狡诈，时刻威胁着任何行走在西部海岸上的人。",al={"老瞎眼是谁","老瞎眼背景故事"}},["295d9e5f"]={q="老瞎眼站在哪一边？",a="老瞎眼只为自己和沿岸的鱼人同胞而战。他不效忠任何王国、公会或阵营，将呼吸空气、栖居陆地的生物都视为领地入侵者，要么赶走，要么杀死。",al={"老瞎眼阵营","老瞎眼为谁效力","老瞎眼是否属于联盟"}},["48ac0465"]={q="老瞎眼为什么在西部荒野？",a="老瞎眼将西部荒野灯塔周围的近海和岩石海滩据为自己的猎场。这片偏僻的海岸有丰富的鱼类，也为他提供了据点，方便他袭击疏于戒备的旅人，或是在崎岖海岸遭遇海难的水手。",al={"老瞎眼为什么在这里","老瞎眼为什么在西部荒野","老瞎眼所在地背景"}},["5afdb8dc"]={q="老瞎眼为什么出名或令人畏惧？",a="老瞎眼在水手和当地居民中恶名远扬，是西部荒野海滨的一大威胁。他比寻常的沿海鱼人更强壮、更凶暴，从无数次冲突中存活下来，恐吓着所有靠近灯塔海岸的人，最终连葛瑞森船长这样的幽灵也悬赏取他的性命。",al={"老瞎眼为什么令人畏惧","老瞎眼为什么臭名昭著","老瞎眼传说"}}},fp="12,178,23.354.0,31.128.0,48.177.0,48.182.0"}
P.entries["npc:old-serra-kis"] = {n="瑟拉吉斯",s="在Moonshrine Sanctum下方，瑟拉吉斯潜伏于黑暗深渊被水淹没的深处。这头庞大的蛇颈龙藏身于一处水下洞穴，任何前去寻找他的人都会面临致命危险。",h="在Moonshrine Sanctum下方，瑟拉吉斯潜伏于黑暗深渊被水淹没的深处。这头庞大的蛇颈龙藏身于一处水下洞穴，任何前去寻找他的人都会面临致命危险。",kw={"黑暗深渊","遗忘之池","月神圣地","瑟拉吉斯","蛇颈龙","暮光之锤","水下首领"},ang={["class:Druid"]="身为荒野中的德鲁伊，水栖形态能帮助你潜入不见光亮的水池，直面这头史前掠食者。",["class:Shaman"]="身为萨满祭司，你可以施放通过与元素沟通而获得的Water Breathing法术，帮助同伴在与这头古老蛇颈龙搏斗时免于溺水。",["class:Warlock"]="身为术士，你可以施加Unending Breath，让没有空气的地下伏击也能从容应对。"},sec={{t="深处的不屈之兽",b="暮光之锤已在沉入水中的月光神殿废墟安营扎寨。在Moonshrine Sanctum下方，幽暗的水域中藏着更古老、更狂野的生物。瑟拉吉斯是这座沉没的神庙中最大的蛇颈龙，潜伏在Forgotten Pool中，那是遗迹下方一处被水淹没的洞穴，鲜有人会想到去那里寻找。"},{t="暗藏的威胁",b="要找到瑟拉吉斯，你必须潜入神庙地板下方深处的一座水下洞穴。洞中没有可供换气的空间，使这处洞穴与其中的野兽一样致命。被逼入幽暗水域的角落时，瑟拉吉斯展现出异乎寻常的顽强生命力。他用暗影能量吸取攻击者的生命，在黑暗中维持自身的生机。"}},faq={{q="瑟拉吉斯是什么生物？",a="瑟拉吉斯是一头体型庞大、年代久远的蛇颈龙，这种长颈水生爬行动物原生于艾泽拉斯的湖泊和近海水域。",al={"瑟拉吉斯是什么","瑟拉吉斯是多头蛇吗","瑟拉吉斯生物类型"}},{q="暮光之锤为什么没有杀死他？",a="没有任何记载表明这个教派曾猎杀过他。瑟拉吉斯藏身于遗忘之池，那是遗迹下方一处被水淹没、没有空气的洞穴，任何潜入其中追寻他的人都会面临致命危险。",al={"瑟拉吉斯为什么还活着","暮光之锤 瑟拉吉斯"}},{q="瑟拉吉斯在哪里？",a="瑟拉吉斯潜伏在黑暗深渊中月神圣地周围水域下方的一座水下洞穴里。你必须潜入遗迹下方没有空气的水池，才能遇到他。",al={"如何找到瑟拉吉斯","瑟拉吉斯位置","瑟拉吉斯在哪里"}},{q="与他战斗的危险在哪里？",a="战斗在水下进行，周围没有天然的换气空间。瑟拉吉斯会在整场战斗中从附近的敌人身上吸取暗影能量，治疗自己的伤势。",al={"瑟拉吉斯技能","如何击败瑟拉吉斯"}},{q="瑟拉吉斯效忠于暮光之锤吗？",a="不。与那些被教派腐化或驯养的野兽不同，瑟拉吉斯仍是一头未被驯服的野生掠食者，守卫着自己的地下巢穴。",al={"瑟拉吉斯是教徒的宠物吗","谁控制瑟拉吉斯"}},{q="与瑟拉吉斯战斗时能呼吸吗？",a="这座封闭洞穴的顶部附近没有可供换气的空间。在水下作战的人必须控制憋气时间，借助水下呼吸魔法，或将野兽引向开阔水域。",al={"瑟拉吉斯溺水","瑟拉吉斯水下呼吸"}}},fp="13,184,25.298.0,15.326.0,39.123.0,42.171.0,31.180.0,34.157.0,43.137.0,49.170.0"}
P.entries["npc:onyxia"] = {n="奥妮克希亚",s="奥妮克希亚是黑龙的龙母，也是死亡之翼诡计多端的女儿。她潜藏在尘泥沼泽的巨龙巢穴中，照料着日益壮大的龙群，同时与邪恶的同族密谋，企图主宰凡人的国度。",h="奥妮克希亚是黑龙的龙母，也是死亡之翼诡计多端的女儿。她潜藏在尘泥沼泽的巨龙巢穴中，照料着日益壮大的龙群，同时与邪恶的同族密谋，企图主宰凡人的国度。",kw={"安度因·乌瑞恩国王","黑龙","伯瓦尔·弗塔根","死亡之翼","奈法利安","奥妮克希亚","暴风城"},sec={{t="宫廷中的龙母",b="当她的兄长奈法利安在黑石塔内整编大军时，奥妮克希亚却凭借诡计谋取权力。她化身为女伯爵卡特拉娜·普瑞斯托，钻营进入了暴风城贵族的最高阶层。她假扮成贵族信赖的顾问，有计划地破坏王国的军事行动，蓄意扣下本应派往西部荒野、赤脊山和燃烧平原各处前哨的士兵与物资，让凡人的国度无力自卫。"},{t="毁灭的幕后主使",b="普瑞斯托女士虚伪的笑容背后，隐藏着一个凶残的阴谋家。瓦里安国王在前往塞拉摩参加和平峰会的途中失踪后，普瑞斯托便对年幼的国王安度因施加深远的影响，并将伯瓦尔·弗塔根公爵笼络于掌中，让王位摇摇欲坠，几乎落入她的利爪。"}},faq={{q="女伯爵卡特拉娜·普瑞斯托是谁？",a="女伯爵卡特拉娜·普瑞斯托是暴风城的一名女贵族，也是宫廷中备受信赖的顾问。瓦里安国王失踪后，她在暴风要塞陪伴着年幼的国王安度因与伯瓦尔·弗塔根公爵，她的意见在贵族中举足轻重。",al={"普瑞斯托身份","普瑞斯托是谁","卡特拉娜·普瑞斯托真实身份"}},{q="奥妮克希亚为何盯上暴风城？",a="奥妮克希亚企图让暴风城王国受黑龙支配，瓦解其军事力量，并协助兄长奈法利安统治这片地区。",al={"奥妮克希亚的目标","为何进攻暴风城","普瑞斯托的动机"}},{q="奥妮克希亚住在哪里？",a="奥妮克希亚的家是尘泥沼泽深处的一座地下巢穴，她在那里照料着黑龙的一窝窝龙卵。",al={"奥妮克希亚在哪里","奥妮克希亚的位置","奥妮克希亚巢穴位置"}},{q="她与奈法利安和死亡之翼有何关系？",a="奥妮克希亚是守护巨龙死亡之翼的女儿。她也是奈法利安的妹妹，与他紧密合作，企图恢复黑龙在艾泽拉斯各地的霸权。",al={"奥妮克希亚的兄长","奥妮克希亚的父亲","奥妮克希亚的家族"}}},fx={fd0ec0c3={q="奥妮克希亚站在哪一方？",a="奥妮克希亚只效忠于黑龙军团，奉行家族的黑暗谋划。她与兄长奈法利安关系密切，共同致力于重建腐化的黑龙军团并奴役凡人种族。她不效忠于联盟或部落；凡人的王国不过是供她操纵、削弱并摧毁的对象，以确保黑龙称霸。",al={"奥妮克希亚所属阵营","奥妮克希亚效忠于谁","奥妮克希亚的阵营","奥妮克希亚属于联盟还是部落"}},d77da3f3={q="奥妮克希亚想要什么？",a="奥妮克希亚企图让暴风城王国受黑龙军团摆布。她暗中削弱其军队，使其疆域毫无防备，好让自己的龙裔和兄长奈法利安的军队得以崛起，无人能挡。",al={"奥妮克希亚想要什么","奥妮克希亚的目标","奥妮克希亚的动机","奥妮克希亚的计划是什么"}},ba62a202={q="奥妮克希亚为何如此令人畏惧？",a="作为死亡之翼之女、黑龙军团的育母，奥妮克希亚既拥有强大的力量，也诡计多端。尽管与成年巨龙相比，她的体型相对较小，但她出击迅捷如电，喷吐的烈焰片刻之间便能熔化铁器。再加上她擅长在凡人之间散布欺骗与谎言，足以对艾泽拉斯构成生死存亡的威胁。",al={"奥妮克希亚为何令人畏惧","奥妮克希亚强大吗","奥妮克希亚的名声"}}},fp="6,206,28.397.1,17.296.2,28.253.2,33.156.2,23.126.2,49.156.0"}
P.entries["npc:orendil-broadleaf"] = {n="奥雷迪尔·阔叶",s="在灰谷西部的迈斯特拉岗哨，暗夜精灵奥雷迪尔·阔叶照料着病患。他熟知森林中的植物，用它们配制药剂，救治这片动荡林地中的幼小生命。",h="在灰谷西部的迈斯特拉岗哨，暗夜精灵奥雷迪尔·阔叶照料着病患。他熟知森林中的植物，用它们配制药剂，救治这片动荡林地中的幼小生命。",kw={"灰谷","阿斯特兰纳","巴斯兰的头发","迈斯特拉岗哨","奥雷迪尔·阔叶","奥雷迪尔的药剂","蕾拉·怀特姆恩"},ang={["profession:Herbalism"]="奥雷迪尔依靠巴斯兰的头发等稀有植物，在野外调配强效解毒剂，展现了当地植物如何挽救生命。",["race:NightElf"]="作为守卫灰谷的暗夜精灵，你可以向奥雷迪尔求取药剂，或许连病危的孩子也能因此获救。"},sec={{t="森林边境的医者",b="在灰谷西部边境的迈斯特拉岗哨，奥雷迪尔·阔叶照料着病患。这位技艺精湛的医者熟悉当地的草药，也懂得如何用它们配制恢复健康的药剂。他依靠过往的旅者采集稀有植物和其他天然原料。紧张局势与冲突日益逼近森林，但奥雷迪尔依然专注于保护同胞，减轻他们的病痛。"},{t="与疾病争分夺秒",b="奥雷迪尔·阔叶在救治阿斯特兰纳患病的孩子蕾拉·怀特姆恩一事中发挥着关键作用。他研究灰谷的植物，包括巴斯兰的头发，并研制强效药剂，遏制这种致命的疾病。蕾拉的病情仍然危险，奥雷迪尔配制的药剂旨在控制病情。"}},faq={{q="奥雷迪尔·阔叶是谁？",a="奥雷迪尔·阔叶是灰谷西部迈斯特拉岗哨的一位暗夜精灵草药师兼医者。他以精通草药和医术而闻名。",al={"奥雷迪尔·阔叶","奥雷迪尔是谁","奥雷迪尔 灰谷"}},{q="在哪里可以找到奥雷迪尔·阔叶？",a="可以在迈斯特拉岗哨找到奥雷迪尔·阔叶。这座暗夜精灵哨站位于灰谷西部的主路旁，靠近黑海岸边境。",al={"奥雷迪尔·阔叶的位置","寻找奥雷迪尔","奥雷迪尔在哪里"}},{q="奥雷迪尔想要治愈什么病？",a="奥雷迪尔配制治疗药剂，救治阿斯特兰纳患病的暗夜精灵孩子蕾拉·怀特姆恩。他使用的是从灰谷荒野中采集的稀有草药。",al={"奥雷迪尔 治疗","奥雷迪尔在救治谁","蕾拉·怀特姆恩 治疗"}}},fp="17,174,27.364.0,23.287.1,25.131.0,37.143.0,31.162.0"}
P.entries["npc:orenthil-whisperwind"] = {n="奥雷希尔·语风",s="在泰达希尔的枝叶下，奥雷希尔·语风与幽影谷的暗夜精灵一同生活。",h="在泰达希尔的枝叶下，奥雷希尔·语风与幽影谷的暗夜精灵一同生活。",kw={"奥雷希尔","幽影谷","泰达希尔","语风"},sec={{t="泰达希尔的友善面孔",b="奥雷希尔·语风生活在幽影谷，与泰达希尔树冠下的暗夜精灵为伴。关于他的过往，人们所知甚少。"}},faq={{q="奥雷希尔·语风是谁？",a="奥雷希尔·语风是一名暗夜精灵，身处泰达希尔的幽影谷。他欢迎那些即将踏入世界之树枝叶间的冒险者。",al={"奥雷希尔","奥雷希尔·语风资料","这个精灵是谁"}},{q="在哪里可以找到奥雷希尔·语风？",a="你可以在幽影谷找到奥雷希尔·语风，那是泰达希尔境内的暗夜精灵新手村。",al={"奥雷希尔位置","奥雷希尔在哪里","奥雷希尔地图"}}},fp="20,94,29.123.0,28.130.0,38.92.0"}
P.entries["npc:orgnil-soulscar"] = {n="奥戈尼尔·魂痕",s="在剃刀岭，奥戈尼尔·魂痕时刻留意杜隆塔尔内部的威胁。他收集情报，协调防御，应对危及这个新生兽人国度的危险，尤其是藏身峡谷的火刃氏族教派。",h="在剃刀岭，奥戈尼尔·魂痕时刻留意杜隆塔尔内部的威胁。他收集情报，协调防御，应对危及这个新生兽人国度的危险，尤其是藏身峡谷的火刃氏族教派。",kw={"火刃氏族","杜隆塔尔","玛高兹","奥戈尼尔·魂痕","剃刀岭","暗影议会","骷髅石"},ang={["class:Warlock"]="身为术士，你在奥戈尼尔面前必须谨慎行事，因为他一心要铲除杜隆塔尔境内失控的恶魔腐化。",["faction:Horde"]="身为部落的一员，在部落建设新国度之际，你可以信赖奥戈尼尔，守护部落腹地免受内部教徒的侵害。",["race:Orc"]="身为年轻兽人，你可以将奥戈尼尔视为抵御恶魔污染的守卫，这种污染曾奴役各个氏族。他的工作提醒新兵保持警惕，守护家园的纯净。"},sec={{t="剃刀岭的守望者",b="在剃刀岭，奥戈尼尔·魂痕追查着杜隆塔尔各地潜藏的威胁。步兵巡逻队警戒联盟军队和半人马劫掠者时，他则留意兽人内部的危险。斥候将各地的报告带给他，他从中寻找腐化仪式和秘密集会的迹象。"},{t="追猎暗影议会残党",b="奥戈尼尔·魂痕追猎着火刃氏族教派，其术士藏身于骷髅石等洞穴。邪能魔法曾给过去数代兽人带来深重灾难，他绝不容许恶魔崇拜在奥格瑞玛附近蔓延。他派遣可信的新兵对付教徒，收集仪式护符。他也派他们向当地的隐士和萨满祭司请教，例如玛高兹，以了解正在肆虐的黑暗魔法。"}},faq={{q="奥戈尼尔·魂痕是谁？",a="奥戈尼尔·魂痕是剃刀岭的一名兽人官员，负责调查威胁并协调杜隆塔尔的防御。他指挥战士和斥候，应对危及兽人新定居地的危险。",al={"奥戈尼尔是谁","奥戈尼尔·魂痕的故事","剃刀岭任务给予者"}},{q="奥戈尼尔最担心什么威胁？",a="奥戈尼尔·魂痕致力于铲除火刃氏族教派。这个教派潜伏在杜隆塔尔隐蔽的洞穴中，其腐化的邪能魔法威胁着萨尔为部落构想的全新开端。",al={"奥戈尼尔想要什么","奥戈尼尔的敌人","奥戈尼尔与谁作战"}},{q="奥戈尼尔为何派旅人去找玛高兹？",a="玛高兹是一位博学的隐士，住在剃刀岭以北，熟悉火刃氏族的标记和仪式。奥戈尼尔派斥候前去向他请教，以查明教派的动向，调查不断蔓延的魔法腐化。",al={"为何找玛高兹","奥戈尼尔与玛高兹","玛高兹与奥戈尼尔的关系"}},{q="在哪里可以找到奥戈尼尔·魂痕？",a="奥戈尼尔·魂痕驻守在剃刀岭的露天区域，靠近杜隆塔尔中部的道路交汇处。",al={"奥戈尼尔的位置","奥戈尼尔在哪里","寻找奥戈尼尔·魂痕"}},{q="杜隆塔尔的火刃氏族是什么组织？",a="火刃氏族是一个效忠于恶魔主人和暗影议会的教派。其成员藏身于骷髅石和尘风洞穴等沟壑之中，企图毒害杜隆塔尔的野生动物，并诱使年轻兽人再次为恶魔效力。",al={"杜隆塔尔火刃氏族","火刃氏族教派","火刃氏族是谁"}},{q="奥戈尼尔直接为萨尔效力吗？",a="奥戈尼尔·魂痕隶属于驻扎在剃刀岭的地区防御部队，奉大酋长之命，保护杜隆塔尔免受叛乱和恶魔势力的侵害。",al={"奥戈尼尔与萨尔","奥戈尼尔是大酋长的卫兵吗"}}},fp="15,191,21.310.0,37.407.1,23.150.0,41.191.0,41.220.0,35.87.0,37.226.1,37.163.0"}
P.entries["npc:orgrim-doomhammer"] = {n="Orgrim Doomhammer",s="奥格瑞姆·毁灭之锤在整个 第二次兽人战争 期间担任 旧部落 的最高大酋长，被后世铭记为历史上最伟大的兽人战士之一。他在解放阿拉希高地收容所的战斗中牺牲，但他的遗志长存于都城奥格瑞玛，也由继承了他那柄强大战锤与黑色板甲的萨尔延续。",h="奥格瑞姆·毁灭之锤在整个 第二次兽人战争 期间担任 旧部落...",kw={"黑手","黑石","毁灭之锤","落锤镇","奥格瑞姆","奥格瑞玛","萨尔","大酋长"},ang={["faction:Alliance"]="对联盟而言，毁灭之锤至今仍是 Second War 期间东部王国险遭毁灭的可怕象征，在黑石塔战败之前，他曾屠戮无数勇士。",["race:Orc"]="兽人尊崇奥格瑞姆·毁灭之锤，将他视为使族人摆脱消沉与囚禁奴役的解放者，他选择了荣誉，拒绝屈从于恶魔。"},sec={{t="大酋长的崛起",b="奥格瑞姆最初是黑石氏族首领黑手的副手，他拒绝了古尔丹提供的恶魔之血，却以坚定的忠诚掩藏心中的疑虑。第一次兽人战争临近结束时，出于对 暗影议会 背叛行径的憎恶，以及对儿时挚友 杜隆坦 遇害的愤怒，奥格瑞姆在荣誉决斗中杀死了黑手。接任大酋长后，他无情地清洗了古尔丹麾下的术士，并在 第二次兽人战争 期间率领部落征战东部王国。他的战略令敌人损失惨重，一度将人类诸国逼至毁灭边缘，但古尔丹的背叛分裂了他的军队，他最终在黑石塔外战败被俘。"},{t="陨落与传承",b="逃离人类的囚禁后，毁灭之锤一直隐姓埋名，直到遇见 杜隆坦 的遗孤萨尔。年轻萨满的愿景让奥格瑞姆重燃斗志，他召集兽人氏族的残部，向收容所发起猛攻，解救被囚禁的族人。在阿拉希高地一处营地的激战中，这位大酋长被一杆长枪从背后击倒。弥留之际，他将自己的黑色板甲、祖传武器毁灭之锤，以及大酋长之位一并传给了萨尔。为纪念他，获解放的哨站更名为落锤镇，而杜隆塔尔新建的都城则被命名为奥格瑞玛。"}},faq={{q="奥格瑞姆·毁灭之锤是谁？",a="他是黑石氏族的酋长，也是在 第二次大战 期间统率部落的大酋长。多年后，他逃离了人类的囚禁，与萨尔并肩作战，解救被囚禁的同胞，直至在阿拉希高地牺牲。",al={"毁灭之锤 是谁","奥格瑞姆·毁灭之锤 背景","大酋长 毁灭之锤 是谁"}},{q="奥格瑞姆·毁灭之锤是怎么死的？",a="奥格瑞姆在进攻阿拉希高地一座人类收容所时，被一名骑士从背后用长枪刺杀。萨尔继承了他的位置，那场胜利的发生地则被命名为落锤镇，以纪念他的牺牲。",al={"奥格瑞姆·毁灭之锤 之死","毁灭之锤 怎么死的","谁杀了 毁灭之锤"}},{q="部落的都城为什么叫奥格瑞玛？",a="萨尔为杜隆塔尔这座设防的城市取名，以纪念自己的导师与前任大酋长。奥格瑞姆看到了萨尔的潜力，任命他为新任大酋长，确保部落以荣誉为根基重建，摆脱恶魔的腐化。",al={"为什么叫奥格瑞玛","奥格瑞玛名称由来","以 奥格瑞姆 命名的城市"}},{q="奥格瑞姆喝过恶魔之血吗？",a="没有。奥格瑞姆拒绝饮下恶魔之血，同时以对黑手的忠诚掩藏自己的疑虑，这让他得以保持清醒，并最终从内部摧毁了古尔丹的 暗影议会。",al={"毁灭之锤 喝过血吗","奥格瑞姆 被腐化了吗","奥格瑞姆 恶魔之血"}}},fp="17,305,20.674.0,15.604.0,26.221.0,30.206.0,41.222.0,33.158.0"}
P.entries["npc:ormak-grimshot"] = {n="奥玛克",s="在奥格瑞玛的荣誉谷，奥玛克训练猎人，教他们在荒野中生存。他的狼Grimfang陪伴在侧，他则教导部落猎人追踪、射击和驯服野兽。",h="在奥格瑞玛的荣誉谷，奥玛克训练猎人，教他们在荒野中生存。他的狼Grimfang陪伴在侧，他则教导部落猎人追踪、射击和驯服野兽。",kw={"野兽训练","格里姆方","猎人训练师","猎人大厅","奥格瑞玛","奥玛克","荣誉谷"},ang={["class:Hunter"]="作为部落猎人，你可以向奥玛克学习如何驯服和照料忠实的动物伙伴。",["race:Orc"]="作为兽人，你可以借鉴奥玛克与Grimfang的伙伴关系，学习如何与狼及本土的掠食野兽并肩保卫杜隆塔尔。"},sec={{t="狩猎大师",b="奥玛克在猎人大厅训练部落的追踪者和射手。他的狼Grimfang陪伴在侧，他则传授在卡利姆多荒野中生存所需的技巧。完成杜隆塔尔试炼的兽人和巨魔猎人，会向他学习如何驯服和指挥野兽，并与动物伙伴建立长久的羁绊。"}},faq={{q="奥玛克是谁？",a="奥玛克在奥格瑞玛的荣誉谷训练部落猎人。他传授远程战斗技巧，以及驾驭野兽的方法。",al={"奥玛克是谁","奥玛克的故事","奥玛克猎人训练师"}},{q="在哪里可以找到奥玛克？",a="奥玛克就在奥格瑞玛荣誉谷的猎人大厅内。他的狼恐牙就在附近。",al={"奥玛克位置","奥玛克在哪里","寻找奥玛克"}},{q="他身旁的狼是谁？",a="奥玛克身旁的狼是恐牙，他忠实的伙伴。他们之间的羁绊展现了猎人与动物伙伴如何协同作战。",al={"奥玛克的狼","恐牙","奥玛克的宠物"}},{q="他对新手猎人有什么作用？",a="兽人和巨魔新手猎人完成杜隆塔尔的基础试炼后，奥玛克会教他们训练、喂养和管理已经驯服的野兽。",al={"奥格瑞玛猎人宠物任务","奥玛克驯服任务","训练野兽 奥玛克"}}},fp="14,165,18.333.0,22.118.0,32.107.0,27.133.0,39.138.0"}
P.entries["npc:ormer-ironbraid"] = {n="奥莫尔·铁衣",s="在维尔加挖掘场，奥莫尔·铁衣正面对迅猛龙的威胁，矮人工人已被它们赶走。他仍守在挖掘场，寻找盟友夺回此地。",h="在维尔加挖掘场，奥莫尔·铁衣正面对迅猛龙的威胁，矮人工人已被它们赶走。他仍守在挖掘场，寻找盟友夺回此地。",kw={"矮人","挖掘","探险者协会","铁衣","奥莫尔","迅猛龙","湿地","维尔加"},ang={["class:Hunter"]="身为猎人，你可以运用追踪和猎杀野兽的本领，帮助奥莫尔对抗卡兹莫丹最凶猛的一些迅猛龙。",["faction:Alliance"]="帮助奥莫尔能保障湿地南部道路的安全，也能支持铁炉堡的考古工作。",["race:Dwarf"]="身为矮人，奥莫尔不肯将这片古老的土地让给一群大得出奇的蜥蜴，这份坚持体现了矮人的坚韧。"},sec={{t="受阻的挖掘",b="奥莫尔·铁衣随矮人考古队来到湿地，在维尔加挖掘场发掘泰坦遗物，探寻远古历史。挖掘惊动了湿地成群的凶猛迅猛龙，至少也将它们引到了挖掘场。如今，野兽在废墟间游荡，而奥莫尔的队伍原本希望在这里研究古代陶器和石板。迅猛龙打断了他们的工作，奥莫尔对它们满怀怒火。"},{t="利爪结下的深仇",b="奥莫尔不肯放弃挖掘场，尽管他无法独自赶走迅猛龙。他请求过往的旅人杀死这些野兽，先从较小的下手，再逐步对付更大、更凶猛的迅猛龙。夺回挖掘场意味着找回文物，但这场战斗已成了私人恩怨：迅猛龙打断了挖掘工作，也践踏了矮人的自尊，奥莫尔要为此复仇。"}},faq={{q="奥莫尔·铁衣是谁？",a="奥莫尔·铁衣负责监督矮人在湿地维尔加挖掘场的研究工作。挖掘场研究的是埋藏在沼泽中的古代遗迹。",al={"奥莫尔是谁","奥莫尔·铁衣","奥莫尔 湿地"}},{q="在哪里可以找到奥莫尔·铁衣？",a="奥莫尔站在湿地南部峭壁上、维尔加挖掘场上方的眺望台，就在通往洛克莫丹的大路东侧。",al={"奥莫尔位置","奥莫尔在哪里","寻找奥莫尔·铁衣"}},{q="奥莫尔为什么如此痛恨迅猛龙？",a="成群的迅猛龙占据了挖掘场，赶走了矮人工人，迫使考古工作停了下来。奥莫尔将这场变故视为对自己的侮辱，决心报复。",al={"为什么是迅猛龙","奥莫尔 迅猛龙","奥莫尔的复仇 背景故事"}},{q="维尔加挖掘场是什么地方？",a="维尔加挖掘场是铁炉堡矮人建立的考古挖掘场，旨在发掘湿地之下古老的泰坦和土灵遗迹。凶猛的野生动物让这里成了危险的战场。",al={"维尔加挖掘场","这处挖掘场是什么","湿地挖掘场"}},{q="奥莫尔提供哪些任务？",a="奥莫尔提供名为“奥莫尔的复仇”的三阶段系列任务，请求旅人杀死挖掘场中体型越来越大的迅猛龙。",al={"奥莫尔任务","击打大地","奥莫尔的复仇 任务"}},{q="奥莫尔隶属于探险者协会吗？",a="是的。奥莫尔为铁炉堡的考古事业效力，探寻矮人源自泰坦的传承，就像许多在卡兹莫丹各地发掘古代遗迹的矮人一样。",al={"奥莫尔 探险者协会","奥莫尔是考古学家吗"}}},fp="15,155,14.351.0,24.349.0,23.138.0,33.139.0,36.169.0,34.208.0,29.114.0,47.166.0"}
P.entries["npc:orokk-omosh"] = {n="奥罗克·沃姆什",s="在奥格瑞玛的荣誉谷，奥罗克·沃姆什传承着家族的锻造技艺。这位年迈的兽人没有子女继承手艺，因此他正在寻找资质出众的部落学徒，传授沃姆什家族的护甲锻造秘法。",h="在奥格瑞玛的荣誉谷，奥罗克·沃姆什传承着家族的锻造技艺。这位年迈的兽人没有子女继承手艺，因此他正在寻找资质出众的部落学徒，传授沃姆什家族的护甲锻造秘法。",kw={"野蛮护甲","锻造","欢乐之舞","沃姆什","兽人铁匠","奥格瑞玛","奥罗克·沃姆什","荣誉谷"},ang={["faction:Horde"]="身为部落的一员，你可以帮助传承兽人传统的板甲和锁甲锻造技艺，让保卫新生部落的战士们继续受益。",["profession:Blacksmithing"]="身为部落铁匠，你可以向奥罗克·沃姆什学习，帮助传承他家族祖传的手艺。"},sec={{t="后继无人的传承",b="在荣誉谷，奥罗克·沃姆什是沃姆什家族最后一位铁匠。他没有子女继承手艺，也不愿让家族的技艺随自己一同消逝。有本领的部落铁匠可以接受他严苛的金属锻造试炼。证明自己潜心钻研的人，便能学到备受推崇的沃姆什护甲锻造秘法。"},{t="熔炉之魂",b="在工匠同行眼中，奥罗克以见到精湛技艺时那份豪放的喜悦而闻名。完成他技艺试炼的人，常能看到他跳起沃姆什的喜悦之舞，以欢快的舞步庆贺传统锻造技艺，让欢庆之声回荡在奥格瑞玛的厅堂间。"}},faq={{q="奥罗克·沃姆什是谁？",a="奥罗克·沃姆什是奥格瑞玛荣誉谷的一位年迈兽人铁匠。他是沃姆什家族最后一位铁匠，正在寻找资质出众的部落学徒，延续家族的手艺。",al={"奥罗克是谁","奥罗克·沃姆什的故事","奥格瑞玛兽人铁匠"}},{q="在哪里可以找到奥罗克·沃姆什？",a="你可以在奥格瑞玛东北部的荣誉谷找到奥罗克·沃姆什，他就在锻造熔炉和铁砧旁。",al={"奥罗克·沃姆什的位置","奥罗克在哪里","寻找奥罗克·沃姆什"}},{q="奥罗克·沃姆什为什么要将家族秘法传授给外人？",a="奥罗克没有子女继承家族的手艺。他将技艺传授给那些通过试炼、证明自身本领的熟练部落铁匠，以免沃姆什家族的技艺随自己一同消逝。",al={"奥罗克为什么发布任务","沃姆什的传承","为什么教导铁匠"}},{q="什么是“沃姆什的喜悦之舞”？",a="沃姆什的喜悦之舞是奥罗克在工匠证明自身实力并掌握他家族的锻造技艺时跳起的欢快舞蹈。他以这充满活力的舞步向这门手艺致敬。",al={"喜悦之舞","沃姆什舞蹈","沃姆什的喜悦"}}},fp="11,203,20.315.0,23.250.0,19.170.0,31.107.0,57.170.0,33.175.0"}
P.entries["npc:orphan-matron-battlewail"] = {n="孤儿监护员巴特维尔",s="在奥格瑞玛的荣誉谷，孤儿监护员巴特维尔照料着因战争失去家人的孩子。她与托萨米纳一起为他们提供庇护，抚养年幼的兽人。",h="在奥格瑞玛的荣誉谷，孤儿监护员巴特维尔照料着因战争失去家人的孩子。她与托萨米纳一起为他们提供庇护，抚养年幼的兽人。",kw={"巴特维尔","儿童周","奥格瑞玛","孤儿监护员巴特维尔","孤儿院","托萨米纳","荣誉谷","部落的监护人"},ang={["faction:Horde"]="巴特维尔为部落中因战争而失去依靠的孩子提供指引与庇护，帮助守护族人的未来。",["race:Orc"]="作为一名在杜隆塔尔寻求长久家园的兽人，你能从巴特维尔的孤儿院中看到族人承受的牺牲。"},sec={{t="部落幼子的守护者",b="孤儿监护员巴特维尔照料着在暴力中失去亲人的孩子。在奥格瑞玛，战争的创伤甚至波及了这座年轻的都城，她和托萨米纳在这里庇护并养育着部落的下一代。荣誉谷的孤儿院向过往的冒险者敞开大门。每逢儿童周，旅人们便会受邀引导这些孩子。"}},faq={{q="孤儿监护员巴特维尔是谁？",a="孤儿监护员巴特维尔是一位兽人女性，负责管理奥格瑞玛的孤儿院。她庇护并抚养那些父母在战斗中丧生的孩子。",al={"巴特维尔的职责","巴特维尔是谁","监护员巴特维尔"}},{q="在奥格瑞玛哪里可以找到她？",a="巴特维尔和托萨米纳在奥格瑞玛东部的荣誉谷照料孩子们。",al={"巴特维尔的位置","孤儿院在哪里","寻找巴特维尔"}},{q="她在儿童周期间承担什么职责？",a="在儿童周期间，巴特维尔会让自愿相助的勇士带着一名孤儿出行，向孩子展示部落的奇观与传承。",al={"儿童周 巴特维尔","部落的监护人","孤儿任务"}},{q="谁在孤儿院协助巴特维尔？",a="托萨米纳与巴特维尔一同生活和工作，帮助照料并保护她们收养的孩子。",al={"托萨米纳","孤儿监护员的助手"}}},fp="24,142,30.356.0,32.119.0,36.104.0,40.129.0,40.107.0"}
P.entries["npc:orphan-matron-nightingale"] = {n="孤儿监护员奈丁加尔",s="在教堂广场，孤儿监护员奈丁加尔照料着暴风城的孤儿。她与监护员瑟伦尼一起为孩子们提供庇护和指引，并在儿童周期间迎接联盟冒险者的到来。",h="在教堂广场，孤儿监护员奈丁加尔照料着暴风城的孤儿。她与监护员瑟伦尼一起为孩子们提供庇护和指引，并在儿童周期间迎接联盟冒险者的到来。",kw={"教堂广场","儿童周","瑟伦尼修女","奈丁加尔","孤儿监护员奈丁加尔","暴风城","暴风城孤儿院"},ang={["class:Priest"]="身为牧师，你能体会到奈丁加尔在光明大教堂外展现的仁慈与奉献。这些正是圣光的牧师所秉持的美德。",["faction:Alliance"]="身为联盟的勇士，你从奈丁加尔身上看到了战争无声的代价。你也肩负着保护王国后世子孙的职责。"},sec={{t="流离失所者的守护人",b="在光明大教堂东南方的孤儿院外，孤儿监护员奈丁加尔照料着失去家园或父母的孩子。近来的战争、豺狼人的袭击，以及迪菲亚潜行者的崛起，让许多孩子来到了她的门前。在圣光教会的看护下，奈丁加尔与监护员瑟伦尼为他们提供庇护、基本照料和指引。"},{t="儿童周的支持者",b="监护员奈丁加尔知道，孩子们不仅需要食物和住所，也需要希望。每逢儿童周，她都会请联盟英雄带上一名孤儿，踏上游历艾泽拉斯的旅程。她希望，与声名远扬的勇士见面能让孩子们树立信心，也让他们见识城墙外更广阔的世界。最重要的是，她想让他们知道，他们并未被遗忘。"}},faq={{q="在哪里可以找到孤儿监护员奈丁加尔？",a="孤儿监护员奈丁加尔就在教堂广场的暴风城孤儿院外，位于光明大教堂的东南方。",al={"监护员奈丁加尔位置","暴风城孤儿院位置","奈丁加尔在哪里"}},{q="为什么暴风城有这么多孤儿？",a="暴风城有许多孤儿，是因为包括第三次大战在内的惨烈战争，以及与迪菲亚潜行者、兽人残部和凶猛野兽之间持续不断的冲突，夺去了许多城市居民和边境农民的生命。他们的孩子因此无家可归。",al={"为什么会有孤儿","暴风城孤儿的由来","这些孩子是谁"}},{q="儿童周是什么？",a="儿童周是由监护员奈丁加尔组织的暴风城年度庆典。联盟冒险者会陪伴一名孤儿踏上旅程，去见识广阔世界中的奇观与英雄。",al={"暴风城儿童周","儿童周是什么","孤儿活动"}},{q="谁帮助监护员奈丁加尔管理孤儿院？",a="保育员瑟伦尼帮助奈丁加尔抚养孤儿院内外的孩子，为他们提供食物和住所。",al={"另一位孤儿监护员","谁管理孤儿院","孤儿监护员瑟伦尼"}}},fx={["9dba66e4"]={q="孤儿监护员奈丁加尔是谁？",a="孤儿监护员奈丁加尔是一位富有同情心的看护者，与监护员瑟伦尼共同管理暴风城的孤儿院。她在教堂广场的中心地带，日复一日地收留和抚育那些因威胁王国的连年战乱与苦难而失去家人的孩子。",al={"奈丁加尔监护员是谁","孤儿监护员奈丁加尔的故事","谁管理暴风城孤儿院"}},e8925ab2={q="孤儿监护员奈丁加尔效忠哪一方？",a="她全心效忠大联盟与暴风城人民。她在光明大教堂的庇护下履行职责，不知疲倦地照顾王国中最需要保护的年幼公民，并依靠联盟英雄来丰富孩子们的生活。",al={"奈丁加尔的阵营","奈丁加尔是否属于联盟","奈丁加尔监护员效忠谁"}},["1cac5069"]={q="孤儿监护员奈丁加尔想要什么？",a="她最关心的是所照料孤儿的福祉、快乐与成长。她努力在动荡的岁月中为他们提供一处安全的庇护所，甚至会在儿童周期间招募经验丰富的旅人，为孩子们带来希望，让他们见识城墙之外更广阔的世界。",al={"奈丁加尔监护员的目标","奈丁加尔想要什么","奈丁加尔的目的"}},e192fa2f={q="孤儿监护员奈丁加尔为什么会在这里？",a="她守在教堂广场的孤儿院台阶外，照看托付给她的孩子，并迎接来访者。在城中这个繁忙而神圣的角落，她安排孤儿院的日常事务，并联络愿意帮助这些孩子的善心冒险者。",al={"奈丁加尔监护员为何在教堂广场","奈丁加尔为何在孤儿院外","奈丁加尔在此的原因"}}},fp="25,206,25.357.0,22.348.0,45.129.0,43.261.0,24.186.0,47.100.0"}
P.entries["npc:osric-strang"] = {n="奥斯瑞克·斯图恩",s="在暴风城的旧城区，经验丰富的护甲商人奥斯瑞克·斯图恩为疲惫的旅人和联盟守卫提供坚固的装备。他的店铺有限防护出售厚重的锁甲和板甲，以及盾牌。",h="在暴风城的旧城区，经验丰富的护甲商人奥斯瑞克·斯图恩为疲惫的旅人和联盟守卫提供坚固的装备。他的店铺有限防护出售厚重的锁甲和板甲，以及盾牌。",kw={"杜加尔·朗德瑞克","重型护甲","暂时的免疫","旧城区","奥斯瑞克·斯图恩","盾牌","暴风城商人"},ang={["class:Warrior"]="作为一名造访旧城区的战士，你可以从奥斯瑞克那里购得可靠的锁甲、鳞甲、板甲和盾牌，以厚重的装备获得可靠的防护。",["faction:Alliance"]="作为联盟的一员，你可以信赖暴风城居民奥斯瑞克，他为王国的守卫提供装备，并帮助信使维系暴风城与偏远城镇之间的补给联系。"},sec={{t="有限防护的店主",b="奥斯瑞克·斯图恩经营着有限防护，战士们可以在这里找到重型护甲和盾牌。他还为来自附近城镇的信使提供帮助，充当他们在首都的联络人，其中也包括来自西部荒野哨兵岭的信使。"}},faq={{q="奥斯瑞克·斯图恩出售什么？",a="奥斯瑞克出售防护厚重的护甲，包括强化锁甲、抛光鳞甲、坚固的板甲套装，以及小圆盾和鸢形盾。",al={"奥斯瑞克物品","奥斯瑞克·斯图恩有什么","有限防护货物"}},{q="在哪里可以找到奥斯瑞克·斯图恩？",a="你可以在有限防护里找到奥斯瑞克，这家护甲店位于旧城区，靠近暴风城南部城区。",al={"奥斯瑞克位置","奥斯瑞克·斯图恩在哪里","有限防护位置"}},{q="为什么任务会派我去找奥斯瑞克·斯图恩？",a="在王国各地运送货物的信使，会将货物送到奥斯瑞克位于旧城区的店铺，并领取回信，其中也包括经由狮鹫管理员从西部荒野运来的货物。",al={"为什么要和奥斯瑞克交谈","奥斯瑞克·斯图恩任务","送货给奥斯瑞克"}}},fx={a4d8c3b8={q="奥斯瑞克·斯图恩是谁？",a="奥斯瑞克·斯图恩是一名护甲商人，在暴风城繁华的旧城区里一家名为有限防护的店铺经营生意。他靠向冒险者和城市卫兵出售厚重的锁甲、板甲以及坚固的盾牌谋生。",al={"奥斯瑞克是谁","奥斯瑞克·斯图恩的故事","奥斯瑞克·斯图恩的背景"}},["66b236b5"]={q="奥斯瑞克·斯图恩效忠哪一方？",a="奥斯瑞克·斯图恩是暴风城王国的忠诚公民，坚定地支持联盟，并以向保卫王国的人们供应防护装备为荣。",al={"奥斯瑞克·斯图恩的阵营","奥斯瑞克·斯图恩效忠谁","奥斯瑞克是否属于联盟"}},["9aee9a9e"]={q="奥斯瑞克·斯图恩为什么在暴风城？",a="奥斯瑞克·斯图恩在旧城区中心经营着有限防护，这片城区以老练的战士、工匠和军械库闻名。暴风城为他带来源源不断的客人，新兵、旅人和守卫都来寻找可靠的重甲。",al={"奥斯瑞克·斯图恩为何在这里","奥斯瑞克·斯图恩的商店","奥斯瑞克·斯图恩 有限防护"}}},fp="12,209,30.228.0,28.131.0,30.105.0,41.175.0"}
P.entries["npc:overlord-mok-morokk"] = {n="莫格穆洛克大王",s="莫格穆洛克大王是石槌食人魔的蛮横酋长，统治着尘泥沼泽的蕨墙村。雷克萨起初因他的力量而任命他为首领，但他后来变成了一个残暴而怯懦的统治者，拒绝保卫氏族，对抗黑龙军团。",h="莫格穆洛克大王是石槌食人魔的蛮横酋长，统治着尘泥沼泽的蕨墙村。雷克萨起初因他的力量而任命他为首领，但他后来变成了一个残暴而怯懦的统治者，拒绝保卫氏族，对抗黑龙军团。",kw={"蕨墙村","德拉兹辛比","尘泥沼泽","莫格穆洛克","食人魔","大王","雷克萨","石槌"},ang={["class:Warrior"]="莫格穆洛克是空有武力却缺乏荣誉与勇气的典型，表明蛮力是多么容易沦为怯懦与暴政。",["faction:Horde"]="自雷克萨率军征战以来，石槌食人魔便宣誓效忠部落，是宝贵的盟友，但莫格穆洛克无能而怯懦的统治，正使蕨墙村面临彻底失去防卫的危险。"},sec={{t="沼泽中的暴君",b="雷克萨击败前任酋长科尔加尔，率领石槌氏族保卫杜隆塔尔后，看中了莫格穆洛克强悍的武力，将统领氏族的重任交给了他。事实证明，这份信任所托非人。莫格穆洛克很快便被至高无上的权力腐蚀，靠恐吓维持统治，只顾自己享乐，无心照管氏族。他不但不关心同胞，反而索取不劳而获的贡品，在蕨墙村游手好闲，欺凌任何质疑他命令的人。"},{t="蕨墙村的懦夫",b="黑龙军团袭击了石槌氏族世代居住的石槌村，杀死许多食人魔，将幸存者赶入蕨墙村的泥沼，莫格穆洛克的领导也随之彻底崩溃。莫格穆洛克没有组织反击，夺回家园或为死者复仇，反而畏惧巨龙的怒火，禁止族人采取任何行动。食人魔法师德拉兹辛比等顾问心中的不满日益滋长，他们暗中寻找愿意挑战大王可耻统治的外来勇士。"}},faq={{q="莫格穆洛克大王是谁？",a="莫格穆洛克是石槌食人魔的酋长，如今居住在尘泥沼泽的蕨墙村。他由雷克萨任命为首领，却很快堕落成了自私而贪得无厌的暴君。",al={"莫格穆洛克是谁","蕨墙村首领","石槌食人魔首领"}},{q="莫格穆洛克是如何成为石槌氏族首领的？",a="杜隆塔尔建立期间，部落的勇士雷克萨击败了氏族的前任首领，接掌了石槌氏族。雷克萨离开氏族，前往荒野游历时，因莫格穆洛克强大的蛮力而任命他为大王。",al={"莫格穆洛克如何掌权","雷克萨选择莫格穆洛克","他为何成为酋长"}},{q="石槌食人魔为什么会住在蕨墙村？",a="石槌食人魔原本住在石槌村，但黑龙袭击并夷平了他们的聚居地。幸存者向北逃入沼泽，建立了蕨墙村，作为难民的据点。",al={"食人魔为何迁往蕨墙村","石槌村发生了什么","黑龙袭击食人魔"}},{q="莫格穆洛克为什么不愿对抗黑龙军团？",a="莫格穆洛克虽然身躯庞大，凶名在外，却对巨龙怕得要命。他没有率领族人反击，夺回氏族的祖地，而是在蕨墙村无所作为，囤积贡品，对族人的呼声置若罔闻。",al={"莫格穆洛克为何不对抗巨龙","莫格穆洛克是懦夫吗","夺回石槌"}},{q="其他石槌食人魔尊敬莫格穆洛克吗？",a="族人对他的懒惰、怯懦和横行霸道越来越不满。他的顾问们担忧石槌氏族在他统治下的未来。",al={"食人魔喜欢莫格穆洛克吗","德拉兹辛比 莫格穆洛克","石槌叛乱"}}},fp="19,211,21.372.0,25.401.1,27.147.0,55.206.0,51.173.0,50.235.0,48.144.1"}
P.entries["npc:overlord-ramtusk"] = {n="主宰拉姆塔斯",s="在剃刀沼泽深处，主宰拉姆塔斯率领野猪人战士投入战斗。他高呼为了胜利，为了阿迦玛甘，而他的倒下将瓦解沼泽守军的战力。",h="在剃刀沼泽深处，主宰拉姆塔斯率领野猪人战士投入战斗。他高呼为了胜利，为了阿迦玛甘，而他的倒下将瓦解沼泽守军的战力。",kw={"贫瘠之地","亡首","主宰拉姆塔斯","野猪人","拉姆塔斯","剃刀沼泽"},ang={["class:Warrior"]="身为战士，你能从Ramtusk雷霆般的打击和威严的战吼中，看出他凶悍的武艺，而非萨满的地卜术或荆棘魔法。",["race:Orc"]="身为兽人，你知道，自杜隆塔尔和贫瘠之地的前哨建立以来，野猪人就一直袭击部落的定居点。摧毁Ramtusk的指挥体系，就能确保贫瘠之地南部的安全。",["race:Tauren"]="身为牛头人，你知道，贫瘠之地的游牧部族世世代代都与沼泽野猪人进行着惨烈的交锋。击倒Ramtusk，便能为阵亡的勇士复仇。"},sec={{t="沼泽的督军",b="主宰拉姆塔斯统领着贫瘠之地南部、剃刀沼泽深处的野猪人要塞。他高呼野猪半神阿迦玛甘之名投入战斗，以不容违抗的权威统御沼泽中的战士。"},{t="沼泽的指挥官",b="拉姆塔斯指挥野猪人战士穿行于沼泽蜿蜒的荆棘丛中。这些浑身鬃毛的战士守卫着部族的圣所，而他以严明的军纪约束他们。他在前线作战时，精锐射手护卫在他两侧，他则咆哮着鼓舞士气，施展猛击，顷刻间便能击溃敌方战线。"}},faq={{q="主宰拉姆塔斯是谁？",a="主宰拉姆塔斯统领着剃刀沼泽深处的野猪人战士。他身躯庞大，威势逼人，高呼为了胜利，为了阿迦玛甘，冲入战场。",al={"拉姆塔斯是谁","拉姆塔斯背景故事","主宰拉姆塔斯"}},{q="在哪里可以找到主宰拉姆塔斯？",a="拉姆塔斯在贫瘠之地最南端、剃刀沼泽荆棘密布的腹地指挥他的精锐卫兵。",al={"拉姆塔斯位置","拉姆塔斯在哪里","主宰拉姆塔斯地图"}},{q="拉姆塔斯过去曾与哪些敌人交战？",a="没有任何记载提及拉姆塔斯过去的战斗。在沼泽中，他高呼为了胜利，为了阿迦玛甘，率领精锐卫兵迎击一切闯入荆棘丛的外来者。",al={"拉姆塔斯的敌人","谁给拉姆塔斯留下了伤疤","拉姆塔斯战斗经历"}},{q="拉姆塔斯属于哪个部族？",a="拉姆塔斯属于剃刀野猪人部族，他们盘踞在贫瘠之地南部的剃刀沼泽，尊崇野猪半神阿迦玛甘。",al={"拉姆塔斯阵营","拉姆塔斯部族","拉姆塔斯属于哪个野猪人部族"}},{q="冒险者为何要对付拉姆塔斯？",a="拉姆塔斯率领着沼泽中的战士。他的死会重创野猪人的军事指挥体系，让他们的防线彻底陷入混乱。",al={"为何杀死拉姆塔斯","干掉他们任务","拉姆塔斯悬赏"}},{q="拉姆塔斯如何作战？",a="拉姆塔斯是一名身经百战的战士。他用令敌人胆寒的呐喊鼓舞麾下战士，用强劲的冲击波震得敌人踉跄，并与精锐的远程护卫并肩作战。",al={"拉姆塔斯战术","拉姆塔斯战斗风格","拉姆塔斯技能"}}},fp="16,177,20.218.0,22.320.0,24.152.0,36.110.0,44.169.0,34.128.0,39.144.0,23.180.0"}
P.entries["npc:ozzie-togglevolt"] = {n="奥齐·电环",s="在卡拉诺斯，奥齐·电环与拉兹·滑链一同寻找治愈诺莫瑞根麻风侏儒的方法。他们在丹莫罗白雪覆盖的群山间继续研究。",h="在卡拉诺斯，奥齐·电环与拉兹·滑链一同寻找治愈诺莫瑞根麻风侏儒的方法。他们在丹莫罗白雪覆盖的群山间继续研究。",kw={"丹莫罗","诺恩","诺莫瑞根","卡拉诺斯","麻风侏儒","奥齐","辐射","拉兹","滑链","电环"},ang={["faction:Alliance"]="身为联盟旅者，你可以在铁炉堡城外的卡拉诺斯找到奥齐。联盟在丹莫罗寒冷的群山中守住据点，而他则为旅者提供帮助。",["profession:Engineering"]="对工程师而言，奥齐的工作展现了侏儒工艺不断试错的过程。装置可能在战斗中适得其反，也可能为生化净化技术带来突破。",["race:Gnome"]="对侏儒冒险者而言，奥齐体现了诺莫瑞根幸存者的悲痛与决心。他不肯抛弃受辐射侵害的同胞，任由他们听天由命。"},sec={{t="逃离深处",b="灾难降临时，奥齐·电环正在诺莫瑞根深处。为了阻止穴居人入侵，有毒的放射性尘埃充斥着通道。奥齐当时站在诺恩身旁，一次突如其来的辐射释放永远改变了诺恩。奥齐逃到了地表，活着抵达丹莫罗，但那场灾难始终萦绕在他心头。"},{t="卡拉诺斯的工坊",b="在卡拉诺斯，奥齐每天都与拉兹·滑链一起钻研发明。他们的研究关乎切身之痛。他们希望找到办法，逆转故乡放射性尘埃造成的变异，治愈饱受折磨的麻风侏儒。"}},faq={{q="奥齐·电环是谁？",a="奥齐·电环是丹莫罗卡拉诺斯的一名侏儒工程师。他从遭受辐射摧残的诺莫瑞根逃了出来，如今正运用自己的技艺，寻找治愈受难同胞的方法。",al={"奥齐是谁","奥齐·电环的故事","卡拉诺斯侏儒奥齐"}},{q="奥齐想要治愈什么？",a="奥齐与拉兹·滑链正在研究清除有毒辐射的方法，这种辐射将他们的许多同胞变成了陷入疯狂的麻风侏儒。",al={"奥齐在研究什么","奥齐治愈麻风侏儒","治愈麻风侏儒的方法"}},{q="诺恩与奥齐有什么关系？",a="诺莫瑞根的通风口释放有毒气体时，诺恩就在奥齐身旁。奥齐亲眼看见一道辐射能量击中诺恩，这让他决心消除污染带来的影响。",al={"奥齐与诺恩","诺恩遭遇了什么","诺恩是谁"}},{q="谁在卡拉诺斯与奥齐共事？",a="奥齐在卡拉诺斯与拉兹·滑链共事。他们一起钻研发明、调配药剂，并采集受污染的野外样本，研究放射性尘埃。",al={"奥齐的搭档","拉兹是谁","拉兹·滑链"}},{q="奥齐提供哪些任务？",a="奥齐通过“灾难之后”、“诺恩”和“更多的辐射尘！”这些任务，请丹莫罗的旅者从诺莫瑞根周边收集受辐射污染的残留物和零件。",al={"奥齐的任务","电环的任务","奥齐提供哪些任务"}}},fx={["86f7524c"]={q="奥齐·电环效忠哪一方？",a="奥齐坚定地站在诺莫瑞根流亡者和联盟一边。与许多从诺莫瑞根陷落的浩劫中幸存下来的人一样，他在丹莫罗的矮人中寻得庇护，全心运用自己的才智和技艺，帮助流离失所的侏儒同胞。",al={"奥齐·电环的阵营","奥齐·电环属于联盟还是部落","奥齐·电环为谁效力"}},["3c84fab0"]={q="奥齐·电环为什么在丹莫罗？",a="诺莫瑞根遭到污染的惨剧发生后，奥齐逃到了卡拉诺斯。他逃过了侵害众多同胞的致命辐射，与其他工匠一起开设工坊，建立了一处安全据点，既方便就近研究辐射污染，也能帮助幸存者。",al={"奥齐·电环为何在卡拉诺斯","奥齐为何在这里","奥齐·电环在此的原因"}}},fp="16,173,20.310.0,21.201.0,24.176.0,29.155.0,23.174.0,38.167.0,29.179.0"}
P.entries["npc:pao-ka-swiftmountain"] = {n="波卡·雨山",s="波卡·雨山是一位年轻的牛头人博物学者，被困在千针石林风巢的野生双足飞龙之间。他在莫特加·火鬃的指导下南下游历，却因年少好奇，冒险靠近了一处巢穴，最终被逼入悬崖间，无路可逃。",h="波卡·雨山是一位年轻的牛头人博物学者，被困在千针石林风巢的野生双足飞龙之间。他在莫特加·火鬃的指导下南下游历，却因年少好奇，冒险靠近了一处巢穴，最终被逼入悬崖间，无路可逃。",kw={"风巢","回家的路","莫特加·火鬃","波卡·雨山","千针石林","白沙岗哨","双足飞龙"},ang={["faction:Horde"]="波卡代表着探索卡利姆多的新一代牛头人学者；保住他的性命，就能维系与白沙岗哨长者们的牢固关系。",["race:Tauren"]="牛头人将双足飞龙视为盟友和忠实的坐骑，对它们深怀敬意，因此波卡这次贸然闯入的举动既令人难堪，又十分危险。"},sec={{t="博物学者的困境",b="波卡随莫特加·火鬃来到千针石林的峡谷地带，渴望记录并研究峡谷中的危险野兽。他的父亲原本不愿让儿子踏上如此凶险的旅途，而波卡最近的遭遇证明，这些担忧并非多余。栖息在风巢的雄伟双足飞龙令这位年轻学者着迷，他从一根孤立的牛头人图腾后方，悄悄沿山路向上攀去。不出所料，这些领地意识极强的野兽被他的闯入激怒，将他一路赶进嶙峋的山岩深处；他被困在那里，惊恐万分，无法绕过俯冲而下的掠食者返回白沙岗哨。"}},faq={{q="波卡·雨山是谁？",a="波卡是一位年轻的牛头人学者，随莫特加·火鬃来到千针石林研究当地野生动物，却被领地意识极强的双足飞龙困在了风巢。",al={"波卡是谁","波卡·雨山","风巢的牛头人是谁"}},{q="在哪里能找到波卡·雨山？",a="他被困在千针石林的风巢顶上。要找到他，得先在悬崖附近找到一根高耸的牛头人图腾，图腾后方有条狭窄的小路，沿着山坡通往双足飞龙的巢穴。",al={"波卡在哪里","风巢小路","如何找到波卡"}},{q="他为什么躲在风巢？",a="他对双足飞龙的痴迷，让他靠得离一处巢穴太近。愤怒的野兽将他赶走，又截断了他的退路，迫使他躲藏了好几天。",al={"波卡为何被困","双足飞龙为何攻击波卡"}},{q="帮助他逃脱后会发生什么？",a="被安全护送出巢穴区域后，波卡便逃回白沙岗哨的莫特加·火鬃身边，满心盼着导师不要把这次闯祸的事告诉父亲。",al={"回家的路结局","波卡能否平安返回"}}},fx={["3733bdd0"]={q="波卡·雨山效忠哪一方？",a="波卡属于部落。他是一名年轻的牛头人博学者，在族中长老的指引下进入峡谷，并依靠部落勇士帮助自己应对千针石林的危险。",al={"波卡·雨山的阵营","波卡是部落吗","波卡·雨山属于哪一方"}},ca840f79={q="波卡·雨山想要什么？",a="波卡想要有人护送他安全离开风巢，回到白沙岗哨，免受导师的责罚。他满怀热情地爬上峭壁，想要研究野生双足飞龙；但惊扰巢穴后，他被追得躲藏起来，如今只想保住性命逃出去，并避免蒙羞地被送回父亲身边。",al={"波卡的目标","波卡想要什么","波卡·雨山的动机"}},["29fbd111"]={q="波卡·雨山与谁有关联？",a="波卡师从白沙岗哨的莫特加·火鬃。莫特加说服了波卡那位犹豫不决的父亲，让他同意孩子外出荒野研究当地野兽。波卡害怕让莫特加失望，也害怕自己无法完成远征，从而证明保护欲强烈的父亲是对的。",al={"波卡·雨山的人际关系","波卡认识谁","波卡的导师"}}},fp="20,188,23.426.0,28.165.0,40.171.0,30.175.0,39.163.1"}
P.entries["npc:parqual-fintallas"] = {n="帕科瓦·芬塔拉斯",s="帕科瓦·芬塔拉斯是一位被遗忘者学者，生前是洛丹伦的人类历史学家，如今居住在幽暗城的炼金房。尽管亡灵生活的环境阴森可怖，他依然彬彬有礼，对古老学识的热情也从未消退，时常帮助那些受指引前来请教历史的旅人。",h="帕科瓦·芬塔拉斯是一位被遗忘者学者，生前是洛丹伦的人类历史学家，如今居住在幽暗城的炼金房。尽管亡灵生活的环境阴森可怖，他依然彬彬有礼，对古老学识的热情也从未消退，时常帮助那些受指引前来请教历史的旅人。",kw={"炼金房","芬塔拉斯","历史学家","洛丹伦","帕科瓦","学者","知识试炼","幽暗城"},ang={["faction:Horde"]="当部落冒险者面对考验心智而非刀剑的试炼时，帕科瓦会以渊博的历史学识，帮助他们揭开艾泽拉斯的古老真相。",["race:Undead"]="帕科瓦让人得以窥见洛丹伦王国昔日的学术风貌，这样的人已不多见；在炼金房的阴郁之中，他仍默默坚持治学，保持着文雅的谈吐。"},sec={{t="失落的洛丹伦的学者",b="帕科瓦生前是洛丹伦一位受人尊敬的人类学者，潜心研读史籍，对这个王国了如指掌。亡灵瘟疫来袭时，帕科瓦与许多居民一样遇害，随后被复活为亡灵，直到后来才在希尔瓦娜斯·风行者女士的领导下挣脱控制。被遗忘者大多奉行冷酷的实用主义，抛却生前的生活，但帕科瓦依然保持着治学的热情与温和有礼的举止，继续寻求启迪，只是所求已与生前不同。"},{t="古老学识的守护者",b="帕科瓦住在幽暗城的炼金房，周围尽是冒泡的大缸和炼金师。尽管身处这般阴森的环境，他仍是了解艾泽拉斯历史的宝贵知识源泉。当冒险者接受严苛的智力试炼时，例如那难以寻得的“知识试炼”，他们便会被指引来找帕科瓦；他会派他们前往血色修道院的图书馆取一本书，然后提出自己的问题。"}},faq={{q="在哪里可以找到帕科瓦·芬塔拉斯？",a="帕科瓦·芬塔拉斯就站在幽暗城的炼金房里，幽暗城是被遗忘者的首都，坐落于洛丹伦废墟之下。",al={"帕科瓦·芬塔拉斯位置","帕科瓦在哪里","帕科瓦幽暗城"}},{q="帕科瓦·芬塔拉斯因何闻名？",a="帕科瓦生前是一位成就卓著的历史学家，几乎通晓洛丹伦王国的一切。即使成为亡灵，他仍是一位学识权威，帮助冒险者寻找鲜为人知的历史文献与古老知识。",al={"帕科瓦是谁","帕科瓦做什么","帕科瓦·芬塔拉斯背景故事"}},{q="帕科瓦为何参与知识试炼？",a="知识试炼要求冒险者既要展现力量，也要证明自己的学识。凭借治学的背景，帕科瓦负责其中一项试炼：他派冒险者前往血色修道院，取回《亡灵的起源》，随后就书中的内容向他们提问。",al={"帕科瓦知识试炼","知识试炼幽暗城","帕科瓦·芬塔拉斯任务"}},{q="帕科瓦是否也像大多数被遗忘者一样充满敌意？",a="日常交谈时，他十分友善，还会说起每当有人愿意抽空与他交谈，他都会感到多么高兴。但面对那些声称通过了布劳格·幽魂试炼的人，他会表现出尖锐的质疑，而对血色十字军，他更是满怀鄙夷。",al={"帕科瓦友善吗","帕科瓦性格"}}},fx={["8cab13a3"]={q="帕科瓦·芬塔拉斯是谁？",a="帕科瓦·芬塔拉斯曾是一位声名卓著的人类历史学家，对洛丹伦王国的一切了如指掌。他被瘟疫侵袭，死后化为亡灵，如今居住在幽暗城的炼金房，与被遗忘者为伍。尽管身为亡灵，他仍对历史知识、典籍和静心治学怀有深厚热情。",al={"帕科瓦是谁","帕科瓦·芬塔拉斯","芬塔拉斯是谁"}},d8934933={q="帕科瓦·芬塔拉斯效忠于哪一方？",a="帕科瓦支持被遗忘者和部落，平静地居住在幽暗城。与许多心怀怨恨的同族不同，他对旅行者几乎没有敌意，也乐于与寻求知识的部落旅人分享自己的历史专长。",al={"帕科瓦为谁效力","帕科瓦的阵营","帕科瓦是部落的吗"}},["5af35229"]={q="帕科瓦·芬塔拉斯想要什么？",a="帕科瓦希望保存洛丹伦的历史，并在亡灵之身继续治学；对他而言，知识远比力量重要。前来寻求失落记录和历史智慧的人，他都会欣然相助，不过他会先让他们去血色修道院找回《亡灵的起源》等珍贵书籍。",al={"帕科瓦想要什么","帕科瓦·芬塔拉斯的目标","帕科瓦的动机"}},["03c3b7bf"]={q="帕科瓦·芬塔拉斯为什么在炼金房？",a="帕科瓦以幽暗城的炼金房为家，周围都是研究者和学者。尽管身处阴暗的炼金术研究之中，他仍利用城中僻静的角落研究并保存历史记录，为探寻失落知识的人提供帮助。",al={"帕科瓦为什么在这里","帕科瓦为什么在幽暗城","帕科瓦在炼金房做什么"}}},fp="17,220,25.426.0,22.365.0,35.124.0,36.191.0,44.203.0,57.224.0"}
P.entries["npc:pelturas-whitemoon"] = {n="皮尔图拉斯·怀特姆恩",s="在阿斯特兰纳，皮尔图拉斯·怀特姆恩竭力挽救病重的女儿蕾拉。他向当地的草药师奥雷迪尔·阔叶和联盟旅者求助，在灰谷寻找神圣的疗愈之物。",h="在阿斯特兰纳，皮尔图拉斯·怀特姆恩竭力挽救病重的女儿蕾拉。他向当地的草药师奥雷迪尔·阔叶和联盟旅者求助，在灰谷寻找神圣的疗愈之物。",kw={"灰谷","阿斯特兰纳","月神之泪","坠星湖","月亮石","奥雷迪尔·阔叶","皮尔图拉斯","蕾拉","星尘废墟","怀特姆恩"},ang={["class:Priest"]="Elune的净化仪式与神圣材料，体现了The Sisterhood of Elune为暗夜精灵文化带来的治愈力量与虔敬之心。",["faction:Alliance"]="帮助皮尔图拉斯救治蕾拉，体现了联盟保卫和援助卡利姆多Kaldorei聚居地的承诺。",["profession:Herbalism"]="蕾拉使用的饮剂、敷剂和植物酊剂，体现了草药知识在Kaldorei医术中的地位。",["race:NightElf"]="皮尔图拉斯的挣扎表明，腐化与地区冲突正威胁着普通Kaldorei家庭和古老的林间空地。"},sec={{t="阿斯特兰纳一位父亲的困境",b="皮尔图拉斯·怀特姆恩与年幼的女儿蕾拉住在阿斯特兰纳。他们常常一起到坠星湖采集月亮石。蕾拉因不明疾病而病危后，皮尔图拉斯平静的生活变成了争分夺秒的救治。尽管阿斯特兰纳面临着来自各方的威胁，他心中牵挂的只有女儿。"},{t="古老疗法与腐化林地",b="普通草药无法缓解蕾拉的病情，皮尔图拉斯只得向奥雷迪尔·阔叶求助。治疗她需要与大地和月亮女神息息相关的稀有神圣材料。要退去蕾拉的高烧，需要一颗月神之泪，以及来自古老卡多雷遗迹的闪光星尘粉末。每一种疗愈之物都只能勉强让她免于死亡，灰谷土壤与水中的腐化已波及这里的居民。"},{t="坠星湖",b="皮尔图拉斯需要从坠星湖的沼泽兽智者那里取得一颗月亮石，帮助蕾拉恢复体力。父女俩曾在这片宁静的湖畔一起采集石头，如今腐化的沼泽兽却让这里危机四伏。皮尔图拉斯将取回的月亮石碾碎，泡成恢复体力的茶，蕾拉久久未愈的虚弱终于消退。她恢复了健康。"}},faq={{q="皮尔图拉斯·怀特姆恩是谁？",a="皮尔图拉斯·怀特姆恩住在灰谷中部的阿斯特兰纳。他向过往的联盟旅者求助，为病重的女儿蕾拉收集神圣的材料。",al={"皮尔图拉斯","皮尔图拉斯·怀特姆恩是谁","皮尔图拉斯 阿斯特兰纳"}},{q="他的女儿蕾拉得了什么病？",a="蕾拉突患恶疾，高烧不退，身体极度虚弱。这种反常的疾病似乎与灰谷荒野中蔓延的腐化有关，普通药物无法奏效，需要神圣的疗愈之物。",al={"蕾拉病情","蕾拉为何生病","蕾拉疾病"}},{q="谁帮助皮尔图拉斯治疗疾病？",a="皮尔图拉斯向当地的暗夜精灵草药师奥雷迪尔·阔叶寻求指点。奥雷迪尔开出了传统的卡多雷疗法，其中包括净化石和草药敷剂。",al={"皮尔图拉斯 草药师","谁帮助蕾拉","奥雷迪尔·阔叶 皮尔图拉斯"}},{q="治愈蕾拉需要哪些材料？",a="蕾拉需要奥雷迪尔的草药饮剂、具有净化之力的月神之泪，以及来自古老遗迹的闪光星尘粉末，才能退去高烧。将坠星湖的月亮石泡成茶，可以让她恢复体力。",al={"皮尔图拉斯 治疗材料","蕾拉治疗材料","什么能治愈蕾拉"}},{q="坠星湖对皮尔图拉斯有何意义？",a="皮尔图拉斯与蕾拉过去常在坠星湖一起采集月亮石。如今，敌对的沼泽兽沼泽兽威胁着这片湖泊，因此皮尔图拉斯请旅者取回蕾拉康复所需的月亮石。",al={"坠星湖 皮尔图拉斯","月亮石 坠星湖"}},{q="皮尔图拉斯是塞纳里奥议会或哨兵的成员吗？",a="不是。皮尔图拉斯是阿斯特兰纳的一名平民，他的家庭只是生活在灰谷重重危机之中的众多卡多雷家庭之一。",al={"皮尔图拉斯是哨兵吗","皮尔图拉斯 阵营身份"}}},fp="18,198,30.354.0,34.400.1,15.369.1,26.175.0,40.237.0,38.174.0,40.225.0,47.214.0,61.113.0"}
P.entries["npc:pilot-bellowfiz"] = {n="驾驶员贝隆·风箱",s="在钢架补给站，驾驶员贝隆·风箱让铁炉堡的战争机器时刻待命。攻城坦克旅称他为“菲兹”，而他负责照料自己驾驶的矮人重型机械贝尔丁。",h="在钢架补给站，驾驶员贝隆·风箱让铁炉堡的战争机器时刻待命。攻城坦克旅称他为“菲兹”，而他负责照料自己驾驶的矮人重型机械贝尔丁。",kw={"贝隆·风箱","丹莫罗","菲兹尔","贝尔丁","驾驶员贝隆·风箱","驾驶员迪恩·石轮","攻城坦克旅","钢架补给站"},ang={["profession:Engineering"]="作为矮人或侏儒工匠，你可以从贝隆·风箱的工作中看到野外工程技术的运用。他让强大的攻城机械在严寒的山区天气中持续运转。",["race:Dwarf"]="作为矮人，你可以为铁炉堡的机械化旅团感到自豪。他们凭借工程技艺和重型火力守卫着卡兹莫丹。"},sec={{t="贝尔丁的主人",b="就在铁炉堡城外，贝隆·风箱调校着贝尔丁，并收集这台机械在野外所需的物资。他的驾驶员同伴驾驶员迪恩·石轮会与他一同探讨载具设计、装甲板和引擎输出功率。他们的工作让卡兹莫丹的机械化部队在王国各地随时待命。"}},faq={{q="驾驶员贝隆·风箱是谁？",a="驾驶员贝隆·风箱在铁炉堡的攻城坦克旅服役。在丹莫罗的钢架补给站，他维护并操作重型攻城机械，保卫卡兹莫丹。",al={"驾驶员贝隆·风箱","菲兹尔","菲兹尔是谁"}},{q="贝隆·风箱驾驶什么机械？",a="贝隆·风箱驾驶的是矮人攻城机械贝尔丁。在攻城坦克旅长途行军前，他会为它备好一个月的物资，其中包括野猪肉和熊皮。他还会随身备着雷杰德·麦酒的艾沃沙酒，投入它的熔炉，让它迸发出强劲动力。",al={"贝隆·风箱的坦克","贝尔丁","贝隆·风箱驾驶什么攻城机械"}},{q="在哪里能找到驾驶员贝隆·风箱？",a="你可以在丹莫罗的钢架补给站找到驾驶员贝隆·风箱，沿卡拉诺斯向东的道路走就能到达。补给站是一处工程作业和集结场地。",al={"贝隆·风箱的位置","驾驶员贝隆·风箱在哪里","寻找贝隆·风箱"}},{q="他和驾驶员迪恩·石轮一起做什么？",a="驾驶员贝隆·风箱和驾驶员迪恩·石轮都是攻城坦克旅的驾驶员。不用照料载具时，他们会互相打趣，探讨攻城机械的设计、装甲和机械原理。",al={"石轮和贝隆·风箱","贝隆·风箱的对话"}}},fx={["8ff6759c"]={q="驾驶员贝隆·风箱效忠哪一方？",a="贝隆·风箱是铁炉堡攻城坦克旅的一名现役驾驶员，为铁炉堡王国和大联盟效力。他坚定地效忠于国王麦格尼·铜须，以及守护丹莫罗的矮人防卫部队。",al={"驾驶员贝隆·风箱的阵营","贝隆·风箱为谁效力","贝隆·风箱是否属于联盟"}},["292f21ec"]={q="驾驶员贝隆·风箱想要什么？",a="贝隆·风箱一心确保自己的攻城坦克贝尔丁随时能够作战，并备足燃料。他依靠旅人收集物资，为攻城坦克旅的一次长期任务做好准备——野猪肉用来充饥，熊皮用来铺床，还需要一桶雷杰德·麦酒酿制的艾沃沙酒，既能御寒，也能让贝尔丁的熔炉猛增一股动力。",al={"贝隆·风箱需要什么","驾驶员贝隆·风箱的目标","贝隆·风箱为何需要补给"}},["53346562"]={q="驾驶员贝隆·风箱为什么在钢架补给站？",a="钢架补给站是铁炉堡重型装甲车辆的集结地和试验场。贝隆·风箱驻扎在这里，与其他技师和驾驶员一起调校、测试自己的攻城坦克，并备足物资，准备驶入雪地执行任务。",al={"贝隆·风箱为何在钢架补给站","驾驶员贝隆·风箱为何在丹莫罗","贝隆·风箱在丹莫罗的目的"}}},fp="15,177,22.282.0,23.163.0,34.254.0,35.143.0,37.177.0"}
P.entries["npc:pilot-hammerfoot"] = {n="驾驶员塞克·锤足",s="驾驶员塞克·锤足在北门哨岗守望山口，寻找一名失踪的驾驶员同伴。攻城坦克旅的攻城坦克守卫着这条道路，但山间丘陵危机四伏。",h="驾驶员塞克·锤足在北门哨岗守望山口，寻找一名失踪的驾驶员同伴。攻城坦克旅的攻城坦克守卫着这条道路，但山间丘陵危机四伏。",kw={"丹莫罗","铁炉堡","洛克莫丹","癞爪","莫特","北门哨岗","驾驶员塞克·锤足","穴居人"},ang={["faction:Alliance"]="援助锤足，也是在帮助守护丹莫罗与洛克莫丹之间主干道沿线的重要侦察哨岗。",["race:Dwarf"]="身为矮人，你与铁炉堡的巡山人有着同样深厚的战友情谊。你绝不会让杀害同胞的凶手逍遥法外。"},sec={{t="群山中的哨兵",b="驾驶员塞克·锤足在北门哨岗守望着丹莫罗与洛克莫丹之间的山口。他为攻城坦克旅看守铁炉堡的攻城坦克。崎岖的山地让驾驶这些坦克变得十分危险。如今，一名驾驶员失踪了，附近的山丘间还有凶猛的野兽游荡。找到他至关重要。"},{t="为战友复仇",b="驾驶员塞克·锤足与另一名攻城坦克驾驶员莫里·铁钻是挚友。他们一起寻找稀有矿石时，铁钻的坦克在一处陡坡上损坏了，于是他独自继续前行。锤足得知，一头名叫癞爪的巨大冰爪熊咬死了铁钻。如今，他要向杀害朋友的野兽复仇。"}},faq={{q="驾驶员塞克·锤足是谁？",a="驾驶员塞克·锤足是一名为铁炉堡效力的矮人攻城坦克驾驶员。他驻守在丹莫罗与洛克莫丹之间山道旁的北门哨岗，守望边境，留意这一带和其他驾驶员的情况。",al={"锤足背景故事","锤足是谁","驾驶员塞克·锤足资料"}},{q="在哪里可以找到驾驶员塞克·锤足？",a="驾驶员塞克·锤足就在北门哨岗，位于丹莫罗与洛克莫丹之间的山间大道和隧道通路旁。",al={"锤足位置","驾驶员塞克·锤足在哪里","锤足在哪里"}},{q="锤足的搭档，驾驶员铁钻遭遇了什么？",a="驾驶员莫里·铁钻在寻找稀有矿石时，攻城坦克在一处陡坡上损坏了，随后他便徒步继续前行。锤足一直没有收到他的消息，于是请旅人寻找他的下落。",al={"驾驶员莫特的命运","莫特遭遇了什么","莫特之死"}},{q="锤足为什么担心他的搭档？",a="锤足与莫里·铁钻是挚友，也同为攻城坦克旅的驾驶员。铁钻在危险的山区失踪了，锤足需要有人查明发生了什么。",al={"驾驶员为何复仇","为何替莫特复仇","癞爪的仇怨"}}},fx={["9955f46b"]={q="驾驶员塞克·锤足效忠哪一方？",a="驾驶员塞克·锤足是忠于铁炉堡的矮人，为联盟效力。他驻扎在守卫丹莫罗与洛克莫丹之间隘口的哨岗，负责保障巡山人的补给，并清除侵扰当地山口的威胁。",al={"塞克·锤足的阵营","驾驶员塞克·锤足为谁效力","塞克·锤足是否属于联盟"}},["4a134edc"]={q="驾驶员塞克·锤足为什么驻扎在这里？",a="塞克·锤足在北门哨岗看守攻城坦克，这里靠近丹莫罗与洛克莫丹之间的隘口。他与莫里·铁钻来到山中寻找稀有矿石，但铁钻的坦克发生故障后，便徒步继续前进，至今未归。",al={"塞克·锤足为何在这里","塞克·锤足的驻地","驾驶员塞克·锤足为何在哨岗"}}},fp="16,182,21.308.0,18.335.1,24.218.0,36.131.0,54.188.0,44.188.0"}
P.entries["npc:pilot-longbeard"] = {n="飞行员比罗·长须",s="飞行员比罗·长须是铁炉堡攻城坦克旅的矮人攻城坦克驾驶员，驻守在铁炉堡军事区的武器大厅。虽然驻扎在这座山中之城，他仍与远在闪光平原的侏儒工匠和赛车同好保持着密切联系。",h="飞行员比罗·长须是铁炉堡攻城坦克旅的矮人攻城坦克驾驶员，驻守在铁炉堡军事区的武器大厅。虽然驻扎在这座山中之城，他仍与远在闪光平原的侏儒工匠和赛车同好保持着密切联系。",kw={"铜栓","武器大厅","铁炉堡","军事区","飞行员比罗·长须","闪光深渊","千针石林"},ang={["profession:Engineering"]="作为一名与侏儒工匠有往来的攻城坦克驾驶员，长须很欣赏让机械持续运转并驰骋赛场所需的巧思。",["race:Dwarf"]="飞行员比罗·长须体现了矮人的冒险精神，将铁炉堡传统的军旅职责与攻城坦克及侏儒机械带来的激情联系在一起。"},sec={{t="攻城旅的驾驶员",b="在铁炉堡军事区的军事陈列与武器锻造师之间，可以找到飞行员比罗·长须，他代表着卡兹莫丹引以为傲的攻城坦克部队。虽然职责让长须留在这座堡垒城市，他仍热切地留意大陆各地机械师同行的创新与消息，其中就包括在卡利姆多盐碱平原上钻研机械的铜栓兄弟。"},{t="跨越大陆的联系",b="长须是那些南下前往卡利姆多的冒险旅者的联络人。他经常指引有潜力的新兵和信使前往千针石林的闪光平原，那里有侏儒发明家与地精对手一道不断突破机械技术的极限。"}},faq={{q="在哪里可以找到飞行员比罗·长须？",a="他在铁炉堡军事区的武器大厅内，站在训练师和军事陈列附近。",al={"飞行员比罗·长须位置","长须 在铁炉堡哪里","如何找到飞行员比罗·长须"}},{q="飞行员比罗·长须的职责是什么？",a="飞行员比罗·长须是一名任务给予者，指引联盟冒险者前往远方开展冒险，尤其会帮助旅者联系他在千针石林的朋友铜栓兄弟。",al={"长须 做什么","飞行员比罗·长须任务","为什么与 长须 交谈"}},{q="铜栓兄弟与长须是什么关系？",a="他们是在闪光平原活动的侏儒工匠，也是长须的伙伴，对工程学和实验机械的共同热情将他们联系在一起。",al={"与 铜栓 的联系","长须 为什么认识 铜栓","长须 闪光深渊"}},{q="飞行员比罗·长须与弗伦·长须有亲属关系吗？",a="他们都拥有铁炉堡显赫的长须氏族姓氏，这暗示着两人同属一个氏族，不过飞行员比罗·长须专注于攻城坦克和工程学方面的人脉，而非锻造。",al={"弗伦·长须兄弟","长须 矮人家族","他与 弗伦 有亲属关系吗"}}},fx={e17c59b9={q="飞行员比罗·长须效忠于哪一方？",a="飞行员比罗·长须坚定地支持铁炉堡的矮人和联盟。他是铁炉堡攻城旅的飞行员，驻扎在铁炉堡军事区的武器大厅。他以攻城旅的攻城引擎为荣，也会帮助联盟各地的朋友和同行飞行员。",al={"飞行员比罗·长须的阵营","飞行员比罗·长须是联盟的吗","长须效忠哪一方"}},["97d29847"]={q="飞行员比罗·长须想要什么？",a="飞行员比罗·长须想帮助朋友和同行飞行员，不过职责让他必须留在铁炉堡。他会让旅人把攻城引擎头盔送给他的朋友黄铜螺栓兄弟——他们的火箭赛车驾驶员总是在闪光平原坠毁——也会请人帮驾驶员迪恩·石轮寻找一种稀有矿石。",al={"飞行员比罗·长须的目标","长须需要什么","飞行员比罗·长须的任务"}},["5f9eba76"]={q="飞行员比罗·长须为什么在这里？",a="作为铁炉堡攻城旅的飞行员，长须驻扎在铁炉堡军事区内的武器大厅。他的职责让他留在城中，因此需要旅人把援助送给远方的朋友，例如黄铜螺栓兄弟和他们的侏儒赛车队。",al={"飞行员比罗·长须为什么在铁炉堡","长须在军事区的原因","长须为什么在这里"}}},fp="15,215,28.219.0,29.179.0,33.109.0,31.156.0,45.165.0,46.210.0"}
P.entries["npc:pilot-stonegear"] = {n="驾驶员迪恩·石轮",s="在钢架补给站，驾驶员迪恩·石轮正为巨魔犁做好战斗准备。这位被称为“石头”的矮人机械师兼驾驶员隶属于铁炉堡攻城坦克旅。他正在寻找稀有材料，以改进这台战车的引擎和装甲，丹莫罗的旅人们也在帮他搜寻。",h="在钢架补给站，驾驶员迪恩·石轮正为巨魔犁做好战斗准备。这位被称为“石头”的矮人机械师兼驾驶员隶属于铁炉堡攻城坦克旅。他正在寻找稀有材料，以改进这台战车的引擎和装甲，丹莫罗的旅人们也在帮他搜寻。",kw={"丹莫罗","铁炉堡攻城坦克旅","驾驶员贝隆·风箱","驾驶员塞克·锤足","驾驶员迪恩·石轮","攻城战车","钢架补给站","石轮","特罗普"},ang={["profession:Engineering"]="作为工程师，你能领会石轮如何在战地改装Trollplow，兼顾战斗力与驾驶员的舒适。",["profession:Mining"]="作为矿工，你可以提供石轮所需的原矿和性质不稳定的地下矿物，用来制造加固装甲板和弹药。",["race:Dwarf"]="作为矮人，你能与石轮一样，热爱厚重的钢铁、轰鸣的引擎，以及用钢铁履带碾碎山中敌人的感觉。",["race:Gnome"]="作为与攻城坦克旅并肩作战的侏儒，你或许会发现石轮与你志趣相投。他热衷于改进设计，追求更强的动力。"},sec={{t="Trollplow的主人",b="在钢架补给站，驾驶员迪恩·石轮为铁炉堡的攻城坦克旅驾驶战车。他引以为傲的是巨魔犁，一辆为突破敌军阵线而打造的重型攻城坦克。石头深知，驾驶员在战场上的性命取决于运转良好的齿轮、坚固的装甲板和稳定的蒸汽压力。因此，他不断提升坦克的战斗力，也让狭窄的驾驶舱住得更舒适。"},{t="机械改造与冶金",b="闲暇时，驾驶员迪恩·石轮会与驾驶员贝隆·风箱等同行探讨工程设计。补给站的标准设计从来无法令他满意。他寻找罕见的矿石和不稳定的矿物，用来改进Trollplow的装甲和弹药。旅人们穿越丹莫罗的雪原荒野和危险洞穴，寻找他需要的物资。"}},faq={{q="驾驶员迪恩·石轮是谁？",a="驾驶员迪恩·石轮常被称为“石头”，是铁炉堡攻城坦克旅的一名矮人。他在丹莫罗的钢架补给站维护并驾驶自己的攻城战车巨魔犁。",al={"驾驶员迪恩·石轮的故事","石轮是谁","驾驶员石轮"}},{q="驾驶员迪恩·石轮在哪里？",a="驾驶员迪恩·石轮位于丹莫罗卡拉诺斯城外的钢架补给站。在那里，他周围都是攻城坦克、备用零件和其他驾驶员。",al={"驾驶员迪恩·石轮的位置","石轮在哪里","寻找石轮"}},{q="巨魔碾压者是什么？",a="巨魔碾压者是驾驶员迪恩·石轮的专属攻城战车。他致力于提升它的可靠性、装甲防护和内部舒适度，以应对前线作战。",al={"巨魔推土机是什么","巨魔推土机坦克","石轮的坦克"}},{q="石轮需要冒险者做什么？",a="石轮请旅人侦察附近的威胁，并收集包括火岩矿石在内的稀有矿物。他用这些物资维护和改进攻城坦克旅的重型战争机器。",al={"驾驶员迪恩·石轮的任务","石轮为什么有任务","石轮的搜寻"}},{q="驾驶员迪恩·石轮与谁共事？",a="驾驶员迪恩·石轮与驾驶员贝隆·风箱、驾驶员塞克·锤足等驾驶员一同在铁炉堡攻城坦克旅服役。在补给站，他经常与贝隆·风箱讨论机械改进和机器设计。",al={"石轮的朋友","攻城坦克旅驾驶员","贝隆·风箱与石轮"}},{q="铁炉堡攻城坦克旅是什么？",a="铁炉堡攻城坦克旅是矮人军队的机械化装甲部队。它的蒸汽坦克、攻城战车和重型火炮保卫着丹莫罗，并将铁炉堡的军威延伸至整个卡兹莫丹。",al={"铁炉堡攻城坦克旅","攻城坦克旅的故事","矮人坦克旅"}}},fx={["6ae24a1f"]={q="驾驶员迪恩·石轮效忠哪一方？",a="驾驶员迪恩·石轮是铁炉堡攻城坦克旅的一名尽职驾驶员，为铁炉堡和联盟效力。他驻扎在钢架补给站，全心效忠矮人王国，守卫丹莫罗白雪覆盖的山岭，并努力让城中的重型战争机器保持良好状态，随时应对危及同胞的威胁。",al={"驾驶员迪恩·石轮的阵营","迪恩·石轮效忠谁","驾驶员迪恩·石轮为谁效力"}},["5e3743ba"]={q="驾驶员迪恩·石轮为什么在钢架补给站？",a="迪恩·石轮驻扎在钢架补给站，测试、维护并改进自己的攻城坦克巨魔碾压者。他与旅里的其他驾驶员一起，利用补给站的工坊监督维修、交流引擎技术，并获取稀有矿石和矿物，提高坦克在野外的耐用性。",al={"迪恩·石轮为何在丹莫罗","驾驶员迪恩·石轮为何在这里","迪恩·石轮 钢架补给站"}}},fp="15,276,23.348.0,24.328.0,23.174.0,33.142.0,22.141.0,41.188.0,35.205.0,36.208.0"}
P.entries["npc:pixel"] = {n="皮克希尔",s="在碎木岗哨，皮克希尔收取报酬，为战歌运送货物，穿行于险地。收到报酬之前，她会扣下锯条，同时也在寻找其他值得运送的货物。",h="在碎木岗哨，皮克希尔收取报酬，为战歌运送货物，穿行于险地。收到报酬之前，她会扣下锯条，同时也在寻找其他值得运送的货物。",kw={"灰谷","信使","地精","皮克希尔","萨特的角","碎木岗哨","战歌锯条"},ang={["faction:Horde"]="作为协助部落在灰谷站稳脚跟的勇士，你可以依靠皮克希尔供应战歌氏族所需的工业器材，让氏族的伐木机械持续运转。"},sec={{t="密林中的生意",b="皮克希尔从碎木岗哨出发，为战歌氏族运送货物，部落在灰谷的这处据点筑有防御工事。她穿越战火纷飞的地区运送物资，支援氏族的伐木作业，但她做事看的是金币和契约。收到报酬之前，锯条都会留在她手里。运送这批货物，她想要一把致命的短枪，用来在路上防身。皮克希尔还出钱向旅人收购萨特的角，因为棘齿城对此需求旺盛。"}},faq={{q="皮克希尔是谁？",a="皮克希尔是一名地精信使，在灰谷东部的碎木岗哨承接生意。她穿行于险地运送货物，手头有一批供战歌伐木作业使用的锯条。",al={"这个地精是谁","皮克希尔背景故事","碎木岗哨地精"}},{q="皮克希尔为什么不立刻交出锯条？",a="皮克希尔会扣下锯条，直到收到报酬，或是能抵付运费的货物。即使部落在灰谷急需物资，她也坚持自己的交易条件。",al={"皮克希尔为什么要报酬","战歌锯条运送","锯条任务"}},{q="她为什么想要萨特的角？",a="皮克希尔想要萨特的角，因为她接下来要去的棘齿城对此需求旺盛。她无法独自对付夜道谷、萨提纳尔和萨维亚的萨特，因此出钱请旅人为她收集角，以便转售。",al={"为什么要萨特的角","皮克希尔萨特","碎木岗哨萨特任务"}},{q="皮克希尔是部落的正式成员吗？",a="皮克希尔通过为战歌伐木作业服务的有利可图的契约，与碎木岗哨的部落合作。她最看重的是贸易、利润，以及履行自己的送货协议。",al={"皮克希尔属于部落吗","皮克希尔阵营","皮克希尔是中立的吗"}}},fp="5,162,26.429.0,13.174.0,53.170.0,30.222.0,42.190.0"}
P.entries["npc:piznik"] = {n="匹兹尼克",s="在狂风矿洞深处，匹兹尼克注视着荆棘谷地精的作业。他曾是二把手，却遭到格雷苏的排挤，如今正密谋对付这位昔日的上司。",h="在狂风矿洞深处，匹兹尼克注视着荆棘谷地精的作业。他曾是二把手，却遭到格雷苏的排挤，如今正密谋对付这位昔日的上司。",kw={"格雷苏","匹兹尼克","石爪山脉","荆棘谷地精","狂风峭壁","狂风矿洞","菲兹克斯"},ang={["profession:Mining"]="身为矿工，你可能会在狂风矿洞里遇到匹兹尼克，他在那里监视着将自己降职的公司。"},sec={{t="失势之后",b="在格雷苏掌控狂风峭壁之前，匹兹尼克在整个作业区位居第二。格雷苏夺权后，荆棘谷地精将匹兹尼克排挤出去，把他打发到了狂风矿洞深处。匹兹尼克并没有默默接受降职。在地下，他监视着矿洞里的动静，等待机会向那个将他降职的上司复仇。"},{t="商业谍报",b="匹兹尼克与菲兹克斯结盟，开始了反抗，后者也是被格雷苏赶走的荆棘谷地精前雇员。匹兹尼克身处矿洞内部，尽力搜集有关格雷苏计划的情报。他将一份神秘的金绿色矿石样本偷偷送给了菲兹克斯，那正是格雷苏下令大量开采的矿石。他们联手破坏荆棘谷地精的伐木和采矿作业，让格雷苏的管理屡遭挫折。"}},faq={{q="在哪里可以找到匹兹尼克？",a="匹兹尼克就在狂风矿洞深处，那里是石爪山脉狂风峭壁中开凿出的矿道。附近有荆棘谷地精的工人。",al={"匹兹尼克位置","匹兹尼克在哪","石爪山脉寻找匹兹尼克"}},{q="匹兹尼克与格雷苏有什么恩怨？",a="匹兹尼克曾在狂风峭壁的整个作业区位居第二。格雷苏接管伐木和采矿项目后，将匹兹尼克降了职，如今匹兹尼克对他怀恨在心，想看到他身败名裂。",al={"匹兹尼克为什么恨 格雷苏","匹兹尼克与 格雷苏 的恩怨"}},{q="匹兹尼克在菲兹克斯的计划中扮演什么角色？",a="菲兹克斯被格雷苏解雇，而匹兹尼克则被降了职。匹兹尼克利用身处狂风矿洞内部的便利，打探格雷苏的计划，并将一份神秘矿石的样本送到菲兹克斯手中。",al={"匹兹尼克与 菲兹克斯","匹兹尼克与谁合作"}},{q="匹兹尼克还忠于荆棘谷地精吗？",a="匹兹尼克仍是荆棘谷地精的雇员，这样他就能继续留在矿洞里。他为自己的利益行事，一心想破坏格雷苏的计划。",al={"匹兹尼克是荆棘谷地精的人吗","匹兹尼克阵营"}}},fp="6,164,17.367.0,19.386.1,24.144.0,54.208.0,44.170.0,45.134.0"}
P.entries["npc:pozzik"] = {n="普兹克",s="普兹克是一位备受推崇的地精工匠兼赛车手，驻扎在千针石林闪光平原的沙漠赛道。他曾是安德麦最受尊敬的工程师之一，如今将自己的技术天赋倾注于制造试验型火箭赛车，并与侏儒对手一决高下，为工程技术孰优孰劣的争论定下结论。",h="普兹克是一位备受推崇的地精工匠兼赛车手，驻扎在千针石林闪光平原的沙漠赛道。他曾是安德麦最受尊敬的工程师之一，如今将自己的技术天赋倾注于制造试验型火箭赛车，并与侏儒对手一决高下，为工程技术孰优孰劣的争论定下结论。",kw={"菲兹尔·铜栓","沙漠赛道","普兹克","火箭赛车","闪光平原","千针石林","工匠","安德麦"},ang={["profession:Engineering"]="对于地精和侏儒两派的工程师而言，普兹克都代表着高风险、高速度应用机械学的巅峰。",["race:Gnome"]="前来赛道的侏儒会发现，普兹克正是他们最喜欢的那种对手：一个吵吵嚷嚷的地精工程师，坚信强劲的推力胜过精细的校准。"},sec={{t="安德麦的大师",b="在退隐至千针石林环境严酷的盐碱平原之前，普兹克就已在地精中赢得了传奇般的声望。作为出身安德麦、最受尊敬的工匠之一，他精通复杂的内燃技术、推进技术以及危险的底盘制造技术。然而，普兹克并未选择安逸地淡出人们的视野，而是带着精湛的机械技艺来到荒漠，要让高速机械远远突破自身的极限。"},{t="盐碱平原上的对决",b="在沙漠赛道，普兹克与多年来的侏儒对手菲兹尔·铜栓携手合作。尽管地精爆破技术与侏儒精密校准技术之间的较量由来已久，两人仍合力在干涸的湖床上建起了这条广阔的赛道。他们各自组建车队，测试火箭赛车原型，要彻底证明究竟哪个种族的设计理念能称霸赛道。当然，普兹克总在寻找足智多谋的冒险者，帮他收集零件，为他的设计减轻重量。"}},faq={{q="普兹克是谁？",a="普兹克是一位来自安德麦的资深地精工匠，如今在千针石林的沙漠赛道率领一方车队，参与火箭赛车竞赛。",al={"普兹克","普兹克是谁","普兹克背景故事"}},{q="普兹克为什么来到千针石林？",a="从安德麦的正式工作中退休后，普兹克来到闪光平原，制造试验型火箭赛车，并让它们在辽阔无阻的盐碱平原上竞速。",al={"普兹克为什么在这里","普兹克闪光平原"}},{q="他与菲兹尔·铜栓是什么关系？",a="菲兹尔·铜栓是普兹克多年的侏儒对手，也是赛道的共同创办者。尽管两人并肩维护着沙漠赛道，却始终较量不休，要证明地精工程学优于侏儒工艺。",al={"普兹克与菲兹尔","普兹克的侏儒对手"}},{q="普兹克为部落还是联盟效力？",a="普兹克完全保持中立，以独立地精企业家的身份在赛道经营事业。他愿意与联盟和部落的旅人做生意，也会向双方提供任务。",al={"普兹克是否中立","普兹克阵营"}},{q="普兹克眼下在忙些什么项目？",a="普兹克一心想让自己的火箭赛车跑得更快。他研制多引擎赛车底盘，收集稀有的轻质矿石，还派遣探险者外出搜寻可回收利用的零件和组件。",al={"普兹克任务","普兹克制造什么"}}},fx={["186dfe38"]={q="普兹克为何出名？",a="在闪光平原定居之前，普兹克就以安德麦最受尊敬的技工之一而闻名。他传奇般的工程技艺也延续到了他的火箭赛车设计中；他研发出强劲的双引擎赛车，革新了这项运动。",al={"普兹克为何出名","普兹克出名吗","普兹克为何广为人知"}}},fp="6,212,21.325.0,26.392.0,14.146.0,38.135.0,48.200.0,47.99.0,53.178.0"}
P.entries["npc:priestess-a-moora"] = {n="女祭司艾茉拉",s="在达纳苏斯，女祭司艾茉拉于月神殿侍奉Elune。她主持仪式，照管神圣的祭品，其中一项祭献关乎萨丝拉的命运。",h="在达纳苏斯，女祭司艾茉拉于月神殿侍奉Elune。她主持仪式，照管神圣的祭品，其中一项祭献关乎萨丝拉的命运。",kw={"艾茉拉","达纳苏斯","艾露恩","女祭司","萨丝拉","月神的泪水","泰达希尔","月神殿"},ang={["class:Priest"]="月神殿的祭司可以将艾茉拉视为虔诚信仰的榜样，她将神殿的仪式与城门外的自然世界联系在一起。",["faction:Alliance"]="女祭司艾茉拉帮助联盟旅人探索达纳苏斯，了解The Sisterhood of Elune的神圣习俗。",["race:NightElf"]="对暗夜精灵而言，女祭司艾茉拉延续着Elune的古老传统，将泰达希尔年轻的枝桠与族人古老的精神传承联系在一起。"},sec={{t="Elune的侍奉者",b="女祭司艾茉拉在达纳苏斯主持祭奉Elune的仪式。在月神殿内，她照料城中居民的精神需求，延续古老的信仰仪式。The Sisterhood of Elune的其他成员负责防御或外交事务，艾茉拉则照管与泰达希尔自然之灵有关的神圣事务。"},{t="月神之泪",b="萨丝拉曾是一只深受Elune喜爱的巨型蜘蛛，神殿珍藏着她的银色露珠，用于治疗伤痛。萨丝拉陷入疯狂后，艾茉拉派遣年轻的冒险者前往泰达希尔北部边缘的涌泉湖附近，结束她的痛苦，并带回她的银色丝囊。在神殿的喷泉处，这些丝囊被献给Elune，让萨丝拉得以在安宁中重生。"}},faq={{q="在哪里可以找到女祭司艾茉拉？",a="女祭司艾茉拉位于达纳苏斯的月神殿内，这座主城坐落在泰达希尔的树冠之中。她与其他侍奉艾露恩祭坛的女祭司一同站在那里。",al={"艾茉拉位置","女祭司艾茉拉在哪里","艾茉拉 达纳苏斯"}},{q="女祭司艾茉拉在达纳苏斯担任什么职责？",a="女祭司艾茉拉隶属于艾露恩姐妹会，负责宗教仪式和神圣的祭献。她引导旅人在泰达希尔完成净化与祭献仪式。",al={"艾茉拉做什么","女祭司艾茉拉职责"}},{q="女祭司艾茉拉提供哪些任务？",a="女祭司艾茉拉派遣冒险者前往涌泉湖附近，结束陷入疯狂的蜘蛛萨丝拉的痛苦。随后，他们在神殿的喷泉处，将萨丝拉的银色丝囊献给艾露恩。",al={"艾茉拉任务","女祭司艾茉拉任务线"}},{q="女祭司艾茉拉与月神殿有什么关系？",a="女祭司艾茉拉在月神殿供职，那里是暗夜精灵文化的精神核心，由高阶女祭司泰兰德·语风掌管。她协助教导信仰，并参与神殿的仪式。",al={"艾茉拉是神殿女祭司吗","艾露恩姐妹会 艾茉拉"}},{q="萨丝拉是谁，艾茉拉为何提起她？",a="萨丝拉是一只曾深受艾露恩喜爱的巨型蜘蛛，栖居在泰达希尔北部边缘的涌泉湖附近。自萨丝拉陷入疯狂后，艾茉拉便请求冒险者结束她的痛苦，并将她的丝囊献给艾露恩，让她得以在安宁中重生。",al={"萨丝拉祭献","萨丝拉是谁"}},{q="艾茉拉属于联盟吗？",a="是的。女祭司艾茉拉是达纳苏斯的一位暗夜精灵女祭司，效忠于联盟。她不会帮助部落成员。",al={"艾茉拉属于联盟吗","部落能与艾茉拉交谈吗"}}},fx={["05fd0978"]={q="女祭司艾茉拉是谁？",a="女祭司艾茉拉是一名虔诚的暗夜精灵，是艾露恩的侍奉者，驻守在达纳苏斯宏伟的月神殿中。作为神殿中尽心侍奉的女祭司之一，她为族人的精神需求提供祈祷、劝导与指引，承蒙月之女神的恩泽。",al={"女祭司艾茉拉是谁","艾茉拉是谁","女祭司艾茉拉的背景故事"}},["4daa0bfc"]={q="女祭司艾茉拉想要什么？",a="女祭司艾茉拉致力于维护月神殿的神圣仪式与圣洁。她寻求值得信赖的冒险者协助处理信仰与仪式相关的事务，请你帮忙准备月之泪等神圣供品，以此向艾露恩致敬，并维系神殿的圣礼。",al={"女祭司艾茉拉的目标","艾茉拉想要什么","艾茉拉的动机"}},e929c23e={q="女祭司艾茉拉为什么在达纳苏斯？",a="艾茉拉居住在月神殿，因为它是暗夜精灵族人敬奉艾露恩的中心。她照料圣所的日常祈祷，协助高阶女祭司泰兰德·语风的祭司团，并确保首都的精神和谐不受玷污。",al={"艾茉拉为什么在达纳苏斯","女祭司艾茉拉与月神殿","艾茉拉为什么在这里"}}},fp="17,165,18.309.0,17.388.0,35.163.0,46.185.0,41.194.0,59.197.0,50.261.0,36.133.0"}
P.entries["npc:priestess-alathea"] = {n="女祭司阿兰希雅",s="在达纳苏斯，女祭司阿兰希雅在月神殿中指引暗夜精灵牧师。她虔诚地信奉Elune，传授神圣仪式，帮助侍僧为掌握治疗、防护和星辰魔法做好准备。",h="在达纳苏斯，女祭司阿兰希雅在月神殿中指引暗夜精灵牧师。她虔诚地信奉Elune，传授神圣仪式，帮助侍僧为掌握治疗、防护和星辰魔法做好准备。",kw={"阿兰希雅","达纳苏斯","艾露恩","艾露恩的赐福","牧师训练师","女祭司阿兰希雅","艾露恩之星","月神殿"},ang={["class:Priest"]="身为达纳苏斯的联盟牧师，你可以向女祭司阿兰希雅寻求技能等级的提升，以及运用kaldorei星辰之力的指引。",["faction:Alliance"]="身为研习牧师技艺的联盟成员，你可以在月神殿向女祭司阿兰希雅学习。",["race:NightElf"]="身为暗夜精灵，你能在达纳苏斯的女祭司阿兰希雅身上，见到The Sisterhood of Elune延续至今的传统。"},sec={{t="月神殿中的虔诚信仰",b="女祭司阿兰希雅在达纳苏斯的月神殿中教导并指引The Sisterhood of Elune。离开幽影谷后，暗夜精灵新晋牧师来到神殿，加深与女神的联系。阿兰希雅向那些献身于治疗、防护和神圣之光的人传授神圣的知识。"},{t="白女士的祝福",b="暗夜精灵牧师借助Elune的恩典施法，而人类和矮人牧师则遵循圣光的传统。阿兰希雅传授暗夜精灵的祝福，例如艾露恩之星和艾露恩的赐福。在她的指引下，侍僧学会将星光迅速凝成防护盾，抵御卡利姆多面临的危险。"}},faq={{q="女祭司阿兰希雅是谁？",a="女祭司阿兰希雅在达纳苏斯的月神殿中训练卡多雷牧师，指引侍僧完成神圣的试炼。",al={"阿兰希雅是谁","阿兰希雅 达纳苏斯","阿兰希雅 牧师训练师"}},{q="她传授哪些技能？",a="阿兰希雅传授常规牧师法术和暗夜精灵试炼，包括星辰碎片和艾露恩的赐福，借此引导月亮女神的力量与庇护。",al={"阿兰希雅 技能","阿兰希雅 法术","牧师法术 达纳苏斯"}},{q="在哪里可以找到女祭司阿兰希雅？",a="女祭司阿兰希雅位于达纳苏斯南部月神殿的一层，身边是圣所中泛着光辉的池水和其他女祭司。",al={"阿兰希雅在哪里","阿兰希雅 位置"}},{q="暗夜精灵牧师为何专程拜访她？",a="随着卡多雷牧师逐渐成长，泰达希尔各地的新手导师会派他们前往阿兰希雅处，接受艾露恩之星和艾露恩的赐福等仪式，标志着他们开始以成熟牧师的身份侍奉女神。",al={"牧师任务 阿兰希雅","艾露恩之星 任务"}},{q="她也训练暗夜精灵以外的种族吗？",a="是的。任何到访达纳苏斯的联盟牧师都能向阿兰希雅学习通用法术，但她只向暗夜精灵提供卡多雷种族试炼。人类和矮人牧师隶属于圣光教会。",al={"人类能向阿兰希雅学习吗","阿兰希雅 矮人牧师"}},{q="她的信仰与人类和矮人牧师有何不同？",a="暴风城和铁炉堡的牧师祈求圣光的力量，而阿兰希雅和她的姐妹们则将艾露恩奉为一位真实存在的神祇。她们既施展治疗魔法，也运用星光和月光结界。",al={"艾露恩与圣光","暗夜精灵牧师背景故事"}}},fp="17,194,34.283.0,27.276.0,25.125.0,30.155.0,35.139.0,48.199.0,44.211.0,57.185.0"}
P.entries["npc:priestess-anetta"] = {n="女牧师安妮塔",s="在北郡修道院内，女牧师安妮塔教导新晋牧师学习圣光的基础仪式。她是一位人类牧师，也是北郡兄弟会的一员。",h="在北郡修道院内，女牧师安妮塔教导新晋牧师学习圣光的基础仪式。她是一位人类牧师，也是北郡兄弟会的一员。",kw={"安妮塔","北郡兄弟会","艾尔文森林","圣光","图书馆侧翼","北郡修道院","牧师训练师","女牧师安妮塔"},ang={["class:Priest"]="作为一名在北郡踏上旅途的年轻人类牧师，你遇到的第一位导师就是女牧师安妮塔。她肯定你的神圣使命，并教你直接与Light沟通。",["faction:Alliance"]="女牧师安妮塔训练年轻的牧师，让他们能够支援北郡山谷的守卫者。"},sec={{t="信徒的守护者",b="女牧师安妮塔常驻北郡修道院一层安静的图书馆侧翼。迪菲亚强盗和狗头人侵扰着山谷。她提醒过往的人们，圣光或许会在某一天成为拯救他们的唯一力量。"},{t="指引新晋牧师",b="新晋的人类牧师带着作为介绍信的神圣信件，来到回廊中拜见女牧师安妮塔。她教导他们念诵神圣之言，治愈伤口，召下光辉惩击邪恶。在她的指导下，年轻的侍僧们准备将圣光带到北郡幽静的围墙之外。"}},faq={{q="女牧师安妮塔是谁？",a="女牧师安妮塔是一位信奉圣光的人类牧师，也是北郡兄弟会的一员。她在北郡修道院一层指导初来乍到的牧师，教他们学习最初的神圣仪式。",al={"安妮塔是谁","女牧师安妮塔的故事","女牧师安妮塔 北郡"}},{q="在哪里可以找到女牧师安妮塔？",a="女牧师安妮塔位于艾尔文森林北部的北郡修道院内。从正门进入，走进主厅。她就在图书馆侧翼的一层。",al={"女牧师安妮塔在哪里","安妮塔的位置","寻找安妮塔"}},{q="她在修道院的防御中承担什么职责？",a="暴风城的治安官和新兵奋力作战，试图从迪菲亚强盗和狗头人手中夺回山谷。女牧师安妮塔训练牧师，让他们以圣光治愈并保护同伴。",al={"安妮塔做什么","安妮塔的职责"}},{q="她提供哪些训练？",a="女牧师安妮塔教导年轻的牧师学习入门的祷言和牧师法术。他们学习以圣光之名施展治疗，惩击敌人。",al={"安妮塔能教法术吗","安妮塔的牧师法术"}}},fx={d2501181={q="女牧师安妮塔效忠于谁？",a="女牧师安妮塔坚定地支持暴风城王国、圣光和北郡兄弟会。她在北郡修道院任职，致力于帮助王国的守卫者，抵御周边的威胁，守护这片宁静的圣地。",al={"安妮塔的阵营","安妮塔为谁效力","女牧师安妮塔的效忠对象"}},bbb44d1e={q="女牧师安妮塔想要什么？",a="女牧师安妮塔希望培养新一代驾驭圣光的人。她的使命是指引初出茅庐的牧师修习信仰，教会他们运用圣光治疗和保护他人的基础知识。",al={"安妮塔的目标","安妮塔想做什么","安妮塔的目的"}},["00624d11"]={q="女牧师安妮塔为什么在这里？",a="女牧师安妮塔是北郡兄弟会中受过圣职的成员，居住在北郡修道院。她驻守在修道院的图书馆侧翼，向响应暴风城号召的学徒传授圣光的基础知识。",al={"安妮塔为什么在北郡","安妮塔在这里的目的","女牧师安妮塔为什么在修道院"}},["1b4a2e6e"]={q="女牧师安妮塔与谁有联系？",a="安妮塔是北郡兄弟会的虔诚成员，与修道院的神职人员和守卫并肩效力。她立下的神圣誓言与承担的训练职责，使她始终与圣光教会及暴风城的防务紧密相连。",al={"安妮塔的联系","安妮塔隶属于谁","安妮塔的阵营关系"}}},fp="16,158,22.221.0,22.289.0,24.200.0,34.173.0,47.175.0,29.147.0"}
P.entries["npc:priestess-josetta"] = {n="女牧师洁塞塔",s="在闪金镇，女牧师洁塞塔指引着已在北郡通过最初试炼的年轻牧师。她教导他们坚守信仰、虔诚奉献，并为他人服务。",h="在闪金镇，女牧师洁塞塔指引着已在北郡通过最初试炼的年轻牧师。她教导他们坚守信仰、虔诚奉献，并为他人服务。",kw={"绝望祷言","艾尔文森林","闪金镇","圣光","洁塞塔","狮王之傲旅店","牧师训练师","女牧师洁塞塔"},ang={["class:Priest"]="作为一名离开北郡的牧师，你可以向洁塞塔学习基础法术，并践行救死扶伤的誓言。",["faction:Alliance"]="作为一名身在艾尔文的联盟成员，你可以向洁塞塔寻求心灵上的支持，并为当地守卫寻求治疗援助。",["race:Human"]="作为一名人类牧师，你会从洁塞塔的教诲中听到Church of the Light的教义，并学习源自族人传统的祷文。"},sec={{t="闪金镇的明灯",b="女牧师洁塞塔在狮王之傲旅店楼上的一间房里照料艾尔文森林的居民。旅人、卫兵和当地工匠都能在那里得到她的帮助。她抚慰普通民众的心灵，在人们需要慰藉的地方践行圣光之道。"},{t="指引年轻学徒",b="年轻牧师在北郡修道院完成最初的学业后，会来向女牧师洁塞塔寻求指引。她派他们前往乡间，救助受伤的卫兵，抚慰受苦的人们。这些工作让他们明白，牧师的职责远不止熟记祷文。他们必须运用圣光的力量，帮助修复这个破碎的世界。"},{t="深藏心底的遗憾",b="女牧师洁塞塔遗憾自己年轻时没有去更远的地方旅行。她选择留在熟悉的土地上，没有踏上艾泽拉斯更广阔的道路。虽然她满足于在闪金镇从事神圣的侍奉，仍鼓励年轻弟子更加勇敢，将信仰带到遥远的边疆。"}},faq={{q="在哪里能找到女牧师洁塞塔？",a="女牧师洁塞塔住在闪金镇狮王之傲旅店二楼的一间房里，就在米歇尔·贝利旁边。",al={"洁塞塔位置","女牧师洁塞塔在哪里","闪金镇牧师训练师位置"}},{q="女牧师洁塞塔担任什么职责？",a="女牧师洁塞塔为离开北郡的联盟牧师传授神圣法术、戒律，以及身为牧师应尽的职责。",al={"洁塞塔做什么","女牧师洁塞塔职责"}},{q="洁塞塔为什么在旅店里，而不是在教堂里履行职责？",a="闪金镇没有独立的礼拜堂，而狮王之傲旅店是镇子的中心。洁塞塔在楼上的房间里照料疲惫的旅人、受伤的卫兵和当地居民。",al={"为什么在旅店里","为什么在狮王之傲旅店"}},{q="洁塞塔向弟子们讲述了什么个人遗憾？",a="女牧师洁塞塔遗憾自己年轻时缺乏离家远行的勇气。她鼓励年轻冒险者到艾尔文之外探索。",al={"洁塞塔背景故事","洁塞塔旅行遗憾"}},{q="洁塞塔会给新牧师安排什么职责？",a="女牧师洁塞塔派学徒去野外救助受伤的守卫。他们学习治疗祷文，也明白了圣光必须照耀那些需要帮助的人。",al={"洁塞塔任务","圣光之衣任务"}},{q="洁塞塔会传授牧师的种族专属法术吗？",a="会。身为艾尔文的一名人类女牧师，洁塞塔向人类牧师传授族人推崇的祷文，其中包括绝望祷言。",al={"绝望祷言训练师","人类牧师法术"}}},fx={["41d8cc17"]={q="女牧师洁塞塔效忠于谁？",a="女牧师洁塞塔坚定地支持圣光、教会和大联盟。她在暴风城的旗帜下于闪金镇任职，致力于指导王国中有志成为牧师的人，确保他们恪守神圣誓言，为人民与盟友服务。",al={"女牧师洁塞塔的阵营","女牧师洁塞塔属于联盟吗","洁塞塔为谁效力"}},["165cad46"]={q="女牧师洁塞塔想要什么？",a="女牧师洁塞塔希望培养下一代神圣修行者的虔诚与自律。尽管她私下里遗憾自己年轻时没有勇气游历艾泽拉斯，她仍将心力投入到指引你和其他见习者之中，让你们救助伤者，将圣光带到远离闪金镇的地方。",al={"洁塞塔有什么目标","女牧师洁塞塔想要什么","洁塞塔的动机"}}},fp="17,150,21.267.0,22.335.0,14.272.0,35.106.0,39.120.0,59.174.0,55.152.0,55.148.0,40.127.0"}
P.entries["npc:prospector-ironband"] = {n="勘察员基恩萨·铁环",s="在铁环挖掘场，勘察员基恩萨·铁环带领众人探寻卡兹莫丹深埋地下的往事。他在洛克莫丹东南部指挥矮人探险者协会的工作，寻找矮人一族的历史遗产。尽管遭遇挫折和敌对生物的威胁，他仍不断向铁炉堡送去报告和文物。",h="在铁环挖掘场，勘察员基恩萨·铁环带领众人探寻卡兹莫丹深埋地下的往事。他在洛克莫丹东南部指挥矮人探险者协会的工作，寻找矮人一族的历史遗产。尽管遭遇挫折和敌对生物的威胁，他仍不断向铁炉堡送去报告和文物。",kw={"阿戈莫德","基恩萨?铁环","挖掘进度报告","挖掘场","探险者公会","铁环","洛克莫丹","勘察员","保护货物"},ang={["faction:Alliance"]="身为联盟旅人，你可以帮助铁环的挖掘场运送补给、抵御袭击，保护洛克莫丹东南部免遭穴居人侵扰，并为联盟保存珍贵的文物。",["profession:Mining"]="身为矿工，你熟悉铁环挖掘场使用的矿镐和开沟作业。凭借敏锐的目光，你能在岩石间发现经过加工的石块和深埋的地层。",["race:Dwarf"]="身为矮人，你可以为勘察员基恩萨·铁环探寻矮人祖先的工作感到自豪，这也是麦格尼国王了解族人往昔的努力之一。"},sec={{t="发掘往昔",b="勘察员基恩萨·铁环负责洛克莫丹东南部铁环挖掘场的挖掘工作。与探险者协会的其他野外研究员一样，他相信卡兹莫丹的土地中埋藏着矮人起源的真相。他的营地开挖沟渠，筛查碎石，寻找古代文物、石板和土灵遗物。工作进展缓慢，但铁环始终坚定不移，也欢迎有能力保护挖掘工作的旅人前来相助。"},{t="边地的困扰",b="在洛克莫丹崎岖的荒野中，穴居人和野兽威胁着挖掘工作。它们危及挖掘场的补给和设备，文物或勘测工具可能还没来得及交给公会检验，就已遭到盗窃或损毁。铁环依靠途经此地的联盟旅人护送货物，抵御袭击者。他还请他们前往邻近的荒芜地带，调查失联的公会联络人。"}},faq={{q="勘察员基恩萨·铁环是谁？",a="勘察员基恩萨·铁环负责矮人探险者协会在洛克莫丹东南部的考古挖掘。他指挥野外工作，发掘与泰坦和土灵历史有关的文物。",al={"铁环背景故事","基恩萨 铁环是谁","勘察员基恩萨·铁环"}},{q="在哪里可以找到勘察员基恩萨·铁环？",a="你可以在铁环挖掘场找到勘察员基恩萨·铁环，那里位于洛克莫丹东南部的丘陵中，就在通往南部边界的主路东侧。",al={"铁环位置","铁环在哪里","铁环挖掘场位置"}},{q="探险者协会在这里挖掘什么？",a="探险者协会在卡兹莫丹各地的古代石砌遗迹中挖掘，探寻矮人一族的起源，并发掘泰坦留下的遗物。",al={"铁环为何挖掘","他们在挖掘什么","铁环挖掘目标"}},{q="铁环为什么需要冒险者保护货物？",a="铁环的挖掘工作依赖从塞尔萨玛穿过洛克莫丹运来的爆破火药和补给。此前有一批火药始终未能送达，黑铁矮人在路上威胁搬运工，穴居人也不断骚扰营地。",al={"保护货物背景故事","为何保护货物","铁环补给"}},{q="阿戈莫德是谁，铁环为什么打听他的消息？",a="阿戈莫德是一名矮人勘测员，曾南下勘察挖掘地点。失去联系后，铁环请旅人前往荒芜之地搜寻，查明他的下落。",al={"寻找阿戈莫德","阿戈莫德是谁","阿戈莫德的命运"}},{q="勘察员基恩萨·铁环与巴尔丁·铁环有亲属关系吗？",a="基恩萨?铁环和巴尔丁·铁环姓氏相同，也都与矮人在边地的行动有着密切联系，因此他们可能是亲属。基恩萨仍专注于考古工作和公会报告。",al={"巴尔丁·铁环亲属","铁环家族","基恩萨与巴尔丁"}}},fx={["8f75b961"]={q="勘察员基恩萨·铁环效忠于谁？",a="铁环通过矮人的探险者协会为铁炉堡和联盟效力。他听命于公会领袖和国王麦格尼·铜须，致力于在卡兹莫丹各地发掘先祖的泰坦知识与古代文物，为矮人族增添财富。",al={"铁环的阵营","铁环为谁工作","铁环 联盟"}}},fp="19,300,19.437.0,17.385.0,27.173.0,37.159.0,46.156.0,56.211.0,50.169.0,50.196.0"}
P.entries["npc:prospector-remtravel"] = {n="勘察员雷姆塔维尔",s="在黑海岸南部，勘察员雷姆塔维尔带领探险者协会在古老遗物间开展挖掘。这个矮人总是心不在焉，营地周围又危机四伏，让他的工作险象环生。",h="在黑海岸南部，勘察员雷姆塔维尔带领探险者协会在古老遗物间开展挖掘。这个矮人总是心不在焉，营地周围又危机四伏，让他的工作险象环生。",kw={"心不在焉的勘察员","黑海岸","探险者协会","化石","铁炉堡","勘察员雷姆塔维尔","雷姆塔维尔","雷姆塔维尔的挖掘场"},ang={["race:Dwarf"]="身为矮人，Remtravel体现了探险者协会探寻矮人起源的决心，即便身处卡利姆多寒冷潮湿的林地，也不例外。",["race:NightElf"]="身为暗夜精灵，你或许会发现，探险者协会喧闹的挖掘声和被翻动的古老土壤，正考验着当地哨兵与德鲁伊的耐心。"},sec={{t="精灵领地上的矮人挖掘场",b="探险者协会派遣勘察员雷姆塔维尔远渡重洋，在黑海岸南部建立挖掘场。暗夜精灵守护着祖先的土地，但为了揭开艾泽拉斯的起源，探险者协会的勘察员仍不断深入被遗忘的地方。雷姆塔维尔挖掘化石中的历史与古老的石块，而凶猛的野生动物和当地的敌对威胁，让这个心不在焉的矮人难以独自照管营地。"},{t="心不在焉的学者",b="勘察员雷姆塔维尔总是沉浸在思考和研究笔记中。他离开营地寻找化石或失落的文物时，可能会被捕食者和敌对生物困住。在野外发现他的人，往往得保护他那些易碎的发现，还得将他从黑海岸的险境中救出来。"}},faq={{q="勘察员雷姆塔维尔是谁？",a="勘察员雷姆塔维尔是来自铁炉堡的考古学家兼测量员，由探险者协会派遣而来。他在黑海岸南部的小型挖掘营地中寻找古老遗物与化石。",al={"雷姆塔维尔是谁","雷姆塔维尔的背景故事","黑海岸的矮人是谁"}},{q="为什么铁炉堡的矮人会在黑海岸挖掘？",a="探险者协会在已知世界各地寻找泰坦神器、失落的历史和古老化石。黑海岸的废墟及其与遥远过去的联系，使这里成为矮人开展考古研究的地方。",al={"矮人为什么在黑海岸","探险者协会在黑海岸做什么","为什么在这里挖掘"}},{q="为什么说他心不在焉？",a="雷姆塔维尔一旦埋首学问，就会忘记周围的环境和自己的装备。他常常在毫无察觉的情况下走入险境，根本没注意到附近的捕食者与野兽。",al={"为什么心不在焉","雷姆塔维尔疯了吗","雷姆塔维尔出了什么事"}},{q="勘察员雷姆塔维尔与探险者协会中的谁有亲属关系吗？",a="据信，勘察员雷姆塔维尔就是卡尔纳·雷塔维提到的那位热爱冒险的叔叔。她说，正是他激发了自己对探索和广阔世界的热情。",al={"雷姆塔维尔的家人","卡尔纳·雷塔维的叔叔","卡尔纳·雷塔维是谁"}}},fp="20,169,28.389.0,25.300.1,28.188.0,47.178.0,31.160.0,56.164.0"}
P.entries["npc:prospector-ryedol"] = {n="勘察员雷杜尔",s="勘察员雷杜尔是探险者协会的一名勘察员，驻守在一处尘土飞扬的高地上，俯瞰着荒芜之地东部。他看守着下方危机四伏的挖掘场，努力找回失落的矮人遗物，在穴居人和野兽横行的贫瘠荒野中守住希望。",h="勘察员雷杜尔是探险者协会的一名勘察员，驻守在一处尘土飞扬的高地上，俯瞰着荒芜之地东部。他看守着下方危机四伏的挖掘场，努力找回失落的矮人遗物，在穴居人和野兽横行的贫瘠荒野中守住希望。",kw={"荒芜之地","挖掘场","探险者协会","铁趾","铁炉堡","勘察员雷杜尔","雷杜尔"},ang={["faction:Alliance"]="对于穿越荒芜之地危险荒野的联盟冒险者来说，雷杜尔是一位友善的伙伴，也带来了一系列支援探险者协会的紧急任务。",["race:Dwarf"]="雷杜尔代表着铁炉堡探寻矮人起源的坚定意志，即使挖掘工作深入卡兹莫丹最严酷的地区，也不曾动摇。"},sec={{t="守望挖掘场",b="勘察员雷杜尔驻守在铁趾挖掘场以南一座崎岖的山丘上，代表着铁炉堡的探险者协会在荒芜之地持续开展的探索工作。这片干旱的山谷蕴藏着古老的泰坦秘密和土灵遗产，但这里的野外考察队不断受到野蛮的穴居人、饥饿的郊狼和守卫领地的幼龙侵扰。雷杜尔协调人手，找回被黑铁矮人偷走的矮人装备，并在残破的哨站间寻找希望的迹象，决心不让探险者协会在荒野中的牺牲付诸东流。"}},faq={{q="勘察员雷杜尔是谁？",a="雷杜尔是探险者协会的一名矮人野外研究员。他在荒芜之地东部一座俯瞰铁趾挖掘场的高丘上扎营，协助指挥搜救与回收任务。",al={"雷杜尔","雷杜尔是谁","勘察员雷杜尔的位置"}},{q="雷杜尔在荒芜之地做什么？",a="他驻守荒芜之地，为探险者协会的考古行动提供支援。附近几处挖掘场遭到黑铁矮人和穴居人的侵扰或占据，他便与过往的旅人合作，确保寻回的遗物安全，追查遗失的工具，并查明矮人同伴的下落。",al={"雷杜尔在做什么","雷杜尔的任务","雷杜尔为何在这里"}},{q="雷杜尔的铁锤是什么？",a="雷杜尔的铁锤是找回他的好运锄后获得的奖励，那把镐被袭击铁趾挖掘场的黑铁矮人夺走了。被偷走的是他的镐，而不是作为奖励的铁锤。",al={"雷杜尔的铁锤","矮人和他的工具"}}},fp="17,182,22.410.0,25.193.0,37.260.0,24.160.0"}
P.entries["npc:prospector-stormpike"] = {n="勘察员塔伯斯·雷矛",s="在铁炉堡，勘察员塔伯斯·雷矛为远方的考古挖掘提供援助。这位出身于著名的雷矛氏族的矮人说话直率，脾气急躁，也能凭借敏锐的头脑破译密信。",h="在铁炉堡，勘察员塔伯斯·雷矛为远方的考古挖掘提供援助。这位出身于著名的雷矛氏族的矮人说话直率，脾气急躁，也能凭借敏锐的头脑破译密信。",kw={"阿古斯之影","探险者协会","探险者大厅","铁炉堡","乔伦·铁环","图书馆","勘察员塔伯斯·雷矛","雷矛氏族"},ang={["faction:Alliance"]="作为联盟的一员，你在北方地区对抗Argus Wake等行事隐秘的人类教派时，可以依靠勘察员塔伯斯·雷矛破译密码的本领。",["race:Dwarf"]="作为一名矮人，你能从勘察员塔伯斯·雷矛干劲十足、务实干练的作风中看到探险者协会的精神。他将古代历史研究与后勤工作都视为关乎矮人荣耀的大事。"},sec={{t="探险者大厅的学者",b="勘察员塔伯斯·雷矛在探险者大厅的图书馆中，协调卡兹莫丹及更远地区的挖掘工作。他向远方的挖掘地点运送补给，甚至包括爆破火药。闲聊会让他失去耐心，但他一心致力于发掘矮人的历史。他头脑敏锐，能够破解复杂的密码，帮助斥候应对暗中的威胁。"}},faq={{q="勘察员塔伯斯·雷矛是谁？",a="勘察员塔伯斯·雷矛是一位考古学家兼后勤协调员，出身于著名的雷矛氏族。他在铁炉堡探险者大厅的图书馆工作。",al={"勘察员塔伯斯·雷矛是谁","勘察员塔伯斯·雷矛的故事","勘察员塔伯斯·雷矛非玩家角色"}},{q="在哪里可以找到勘察员塔伯斯·雷矛？",a="你可以在铁炉堡探险者大厅东部的图书馆内找到勘察员塔伯斯·雷矛。",al={"勘察员塔伯斯·雷矛的位置","勘察员塔伯斯·雷矛在哪里"}},{q="他从事什么工作？",a="勘察员塔伯斯·雷矛负责管理考古挖掘的补给和报告。他为野外的勘察员运送爆破火药，例如在洛克莫丹工作的勘察员基恩萨·铁环，也帮助斥候破解复杂的密信。",al={"勘察员塔伯斯·雷矛的任务","勘察员塔伯斯·雷矛做什么"}},{q="南海镇为什么需要他的帮助？",a="南海镇的联盟当局需要勘察员塔伯斯·雷矛破译截获的信件，这些信件出自神秘的阿古斯复苏教派。",al={"阿古斯 复苏会密码","南海镇 勘察员塔伯斯·雷矛"}}},fx={["676ebbc6"]={q="勘察员塔伯斯·雷矛效忠于谁？",a="勘察员塔伯斯·雷矛忠于铁炉堡王国和联盟。作为矮人探险者协会的成员，他的野外工作和考古研究直接为国王麦格尼·铜须及矮人王国的利益服务。",al={"雷矛的阵营","勘察员塔伯斯·雷矛 联盟","雷矛为谁效力"}},b4a2ac01={q="勘察员塔伯斯·雷矛想要什么？",a="勘察员塔伯斯·雷矛希望破译重要情报，协调考古探险，免受无谓的干扰。他负责监督洛克莫丹铁环挖掘场等挖掘项目的研究，并运用密码分析专长破解加密信息，要求绝对专注，对无关紧要的打扰毫无耐心。",al={"雷矛需要什么","勘察员塔伯斯·雷矛的目标","雷矛的动机"}},["1b565b81"]={q="勘察员塔伯斯·雷矛为什么在铁炉堡？",a="你可以在铁炉堡探险者大厅的图书馆找到勘察员塔伯斯·雷矛，因为这里是探险者协会的行动中枢。他在这里审阅野外报告，翻译出土遗物上的文字，并破译需要学者研究的截获信件。",al={"雷矛为什么在这里","勘察员塔伯斯·雷矛 图书馆","雷矛为什么在探险者大厅"}},dbd365e1={q="勘察员塔伯斯·雷矛与谁有联系？",a="他是颇具影响力的雷矛氏族的一员，这个备受尊敬的矮人世家在卡兹莫丹各地享有盛名。除了氏族关系，他还与勘察员基恩萨·铁环等野外勘察员同僚直接合作，并通过破解敌方密码来协助南海镇的联盟领袖。",al={"雷矛的氏族关系","勘察员塔伯斯·雷矛的盟友","雷矛与联盟组织的联系"}},d5ca9c54={q="勘察员塔伯斯·雷矛为何出名或令人畏惧？",a="勘察员塔伯斯·雷矛以破译复杂加密文件的卓越才能闻名，他那火爆的脾气也同样声名在外。很少有学者既拥有他那敏锐的密码分析头脑，又像他一样，对任何浪费自己时间的人都毫无耐心，动辄大发雷霆。",al={"雷矛的名声","勘察员塔伯斯·雷矛为何出名","雷矛的火爆脾气"}}},fp="20,191,32.336.0,28.156.0,38.110.0,29.199.0,34.122.0"}
P.entries["npc:prospector-whelgar"] = {n="勘察员维尔加",s="在维尔加挖掘场，勘察员维尔加寻找泰坦遗物的工作陷入了停滞。凶猛的迅猛龙占据了挖掘场，他正在寻找坚韧的冒险者，帮忙找回古代文物。",h="在维尔加挖掘场，勘察员维尔加寻找泰坦遗物的工作陷入了停滞。凶猛的迅猛龙占据了挖掘场，他正在寻找坚韧的冒险者，帮忙找回古代文物。",kw={"矮人","挖掘场","探险者协会","戈阿兹之石","勘察员维尔加","发现历史","湿地","维尔加"},ang={["profession:Mining"]="作为一名矿工，你可以在维尔加挖掘场周围崎岖的山脊间找到丰富的矿脉。迅猛龙也在这一带游荡，侵扰着他的队伍。",["race:Dwarf"]="身为矮人，维尔加肩负的使命，是协助探险者协会和国王麦格尼·铜须探寻矮人一族的泰坦起源。"},sec={{t="受困的挖掘场",b="勘察员维尔加在湿地主持一处矮人挖掘场。他的营地维尔加挖掘场位于米奈希尔港以东，他在那里探寻矮人一族的历史。山谷中曾遍布古老的石制遗物，但领地意识极强的迅猛龙迫使他的队伍躲藏起来。维尔加不愿在职责未尽时离去。他仍希望在猛兽或觊觎此地的恶徒毁掉挖掘场之前，找回包括戈阿兹之石在内的珍贵遗物。"}},faq={{q="勘察员维尔加是谁？",a="勘察员维尔加率领一支铁炉堡矮人探险队，在湿地开展探索。他在米奈希尔港以东主持一处挖掘场，研究矮人历史初期的遗物。",al={"维尔加","维尔加是谁","勘察员维尔加背景故事"}},{q="在哪里可以找到勘察员维尔加？",a="你可以在维尔加挖掘场上方的山脊找到正在避难的勘察员维尔加，那里位于湿地的米奈希尔港以东、丹莫德西南方。",al={"维尔加位置","维尔加在哪里","维尔加湿地地图"}},{q="维尔加为什么在挖掘场遇到了麻烦？",a="当地凶猛的迅猛龙占据了挖掘场，杀死或驱散了维尔加的队员，迫使他退守一隅。没有保护，他就无法继续发掘遗物。",al={"迅猛龙挖掘场","维尔加挖掘场发生了什么","维尔加挖掘场迅猛龙"}},{q="戈阿兹之石是什么？",a="戈阿兹之石是在维尔加挖掘场的废墟中发现的一件古代文物。维尔加正在努力翻译上面的铭文，以进一步了解矮人一族被遗忘的起源与古老历史。",al={"戈阿兹之石","戈阿兹之石是什么","发现历史遗物"}}},fp="18,194,17.434.0,26.172.0,36.167.0,46.178.0,23.227.0"}
P.entries["npc:quartermaster-lewis"] = {n="军需官刘易斯",s="在西部荒野的哨兵岭，军需官刘易斯不断为人民军调拨补给。他为抵御迪菲亚潜行者、坚守边境的守军和旅人提供物资。",h="在西部荒野的哨兵岭，军需官刘易斯不断为人民军调拨补给。他为抵御迪菲亚潜行者、坚守边境的守军和旅人提供物资。",kw={"刘易斯","人民军","军需官刘易斯","哨兵岭","哨兵塔","商人","西部荒野"},ang={["class:Hunter"]="身为猎人，你可以在西部荒野中部向刘易斯获取野外补给，包括用于远程防御的弹丸和箭矢。",["faction:Alliance"]="身为西部荒野的联盟新兵，你可以在这片王室物资匮乏、危机四伏的土地上向刘易斯补充物资。"},sec={{t="高塔物资的管理者",b="军需官刘易斯在Sentinel Tower为人民军供应物资。暴风城的王室领袖几乎不向贫困的西部荒野提供援助，因此哨兵岭只能依靠当地志愿者，以及他们能够筹集到的补给。刘易斯分发干粮、清水、箭矢、弹丸和投掷飞刀。值守的战士需要这些基本物资，才能撑过迪菲亚潜行者的袭击。"}},faq={{q="军需官刘易斯是谁？",a="军需官刘易斯在西部荒野的哨兵塔任职。他为人民军和协助保卫这片地区的冒险者经管日常物资、口粮与武器。",al={"军需官刘易斯背景故事","刘易斯是谁","哨兵岭军需官"}},{q="军需官刘易斯出售什么？",a="军需官刘易斯出售基本的生存物资，包括面包、牛奶、水、背包、燧石、箭矢、子弹和投掷匕首。",al={"刘易斯出售什么","刘易斯商品","西部荒野商人物品"}},{q="他在当地任务中起什么作用？",a="由于暴风城几乎不提供援助，刘易斯让冒险者借助狮鹫管理员索尔的帮助，将一封信送给他在暴风城旧城区的护甲供应商奥斯瑞克·斯图恩。他们再将装有护甲的奥斯瑞克的箱子带回哨兵岭。",al={"刘易斯任务","快递消息","返回刘易斯"}},{q="刘易斯是暴风城军队的一员吗？",a="刘易斯与哨兵岭的大多数守军一样，为人民军效力，并不隶属于暴风城王室派遣的正规军。西部荒野基本只能独自抵御迪菲亚潜行者。",al={"刘易斯属于军队吗","暴风城卫兵刘易斯","人民军刘易斯"}}},fx={f4ce3c2d={q="军需官刘易斯为什么驻扎在这里？",a="军需官刘易斯驻扎在西部荒野的哨兵岭，为人民军和途经此地的联盟冒险者提供补给。西部荒野几乎已被王室抛弃，又遭迪菲亚潜行者盘踞，驻守高塔的防御者依靠刘易斯提供重要的口粮、弹药和生存物资。",al={"刘易斯为什么在这里","军需官刘易斯为什么在西部荒野","军需官刘易斯为什么在 哨兵塔"}}},fp="19,187,28.366.0,27.176.0,35.133.0,36.225.0,36.212.0"}
P.entries["npc:quinn-yorick"] = {n="奎恩·尤瑞克",s="在伊瓦农场，奎恩·尤瑞克正躲避那只打伤他的食尸鬼。这名被遗忘者斥候藏身于一间破败的农舍，既无法完成任务，也无法独自撤离。",h="在伊瓦农场，奎恩·尤瑞克正躲避那只打伤他的食尸鬼。这名被遗忘者斥候藏身于一间破败的农舍，既无法完成任务，也无法独自撤离。",kw={"被遗忘者斥候","食尸鬼","伊瓦农场","邪恶的伊瓦","奎恩·尤瑞克","银松森林"},ang={["race:Undead"]="奎恩身为亡灵，他的困境表明，食尸鬼和野兽威胁着那些试图确保银松森林北部安全的被遗忘者部队。"},sec={{t="岌岌可危的藏身处",b="奎恩·尤瑞克身负重伤，躺在伊瓦农场一间破败农舍的楼上。邪恶的伊瓦是一只潜伏在银松森林北部农场谷仓里的食尸鬼，在一场凶狠的交锋中打伤了他。奎恩和他的姐妹兰妮受命侦察银松森林，并向高级执行官哈德瑞克汇报。他伤势过重，既无法完成任务，也无法独自安全撤离，只能继续躲藏。为被遗忘者效力的过路旅人为他送来治疗，并对付那只险些将他撕碎的怪物。"}},faq={{q="奎恩·尤瑞克在哪里？",a="奎恩·尤瑞克藏在银松森林瑟伯切尔以北的伊瓦农场，位于一间破败农舍的楼上。",al={"奎恩·尤瑞克位置","奎恩在哪里","奎恩·尤瑞克的房子"}},{q="是谁打伤了奎恩·尤瑞克？",a="潜伏在农场谷仓里的食尸鬼邪恶的伊瓦重伤了奎恩·尤瑞克。",al={"谁袭击了奎恩","奎恩·尤瑞克怎么了","奎恩受伤"}},{q="奎恩对部落冒险者有什么作用？",a="奎恩的姐妹、亡灵哨兵兰妮·尤瑞克派旅人为他送去一瓶治疗药水。他服下药水后，她请旅人杀死邪恶的伊瓦，好让奎恩有时间恢复。",al={"奎恩·尤瑞克任务","奎恩任务给予者"}}},fp="12,150,19.470.0,30.113.0,25.80.0,49.170.0"}
P.entries["npc:raene-wolfrunner"] = {n="莱恩·狼行者",s="在阿斯特兰纳，莱恩·狼行者指挥哨兵保卫灰谷。面对部落军队和堕落的熊怪部族时，她的狼与刃豹伙伴始终伴随左右。",h="在阿斯特兰纳，莱恩·狼行者指挥哨兵保卫灰谷。面对部落军队和堕落的熊怪部族时，她的狼与刃豹伙伴始终伴随左右。",kw={"灰谷","阿斯特兰纳","达戈里","达图尔","库尔拉","莱恩","哨兵","泰洛尼斯","蓟皮","狼行者"},ang={["class:Hunter"]="身为猎人，你或许能看出莱恩对荒野的了解，以及她与野兽之间的羁绊。她指挥着一匹狼和一只刃豹。",["faction:Alliance"]="对于从黑海岸前来的联盟旅人而言，莱恩统筹着灰谷的军事防御与生态保护。",["race:NightElf"]="身为暗夜精灵，你能从莱恩保卫灰谷林地圣所的行动中，看出她对Elune的虔诚，以及对卡利姆多荒野的热爱。"},sec={{t="阿斯特兰纳的守护者",b="莱恩·狼行者与她的刃豹库尔拉和狼达戈里一同驻守阿斯特兰纳。身为哨兵的军官，她统管灰谷各地的巡逻，并统筹来自森林之外的情报。她派遣凯拉·影矛等斥候前往邻近地区，其中就包括石爪山脉。"},{t="遏制森林的腐化",b="莱恩也致力于遏制侵害灰谷原生生灵的腐化。她指挥针对敌对熊怪部族的行动，包括打击骚扰旅人的污林营地，以及铲除日渐崛起的蓟皮首领。她的斥候密切留意熊怪行为的变化。在莱恩的指挥下，他们保护当地聚落和过往旅人，抵御有组织的伏击。"},{t="达图尔的变形杖",b="莱恩心中牵挂的是达图尔的变形魔棒，一件与净化熊怪有关的古老圣物。她的老友泰洛尼斯在寻找圣物遗失的宝石时遭到杀害。莱恩下令寻回他的遗体，并誓言完成他的研究。她与树妖莎尔蒂恩一起，帮助勇士们将圣物重新组装完整。它能让冒险者化身熊怪，与酋长克罗格交谈，继而击败遭到腐化的首领兰恩·血牙，清除这一地区的威胁。"}},faq={{q="在哪里可以找到莱恩·狼行者？",a="莱恩·狼行者位于阿斯特兰纳，这座暗夜精灵城镇坐落在灰谷中部。她与两位动物伙伴一同站在户外。",al={"莱恩·狼行者位置","莱恩在哪","莱恩阿斯特兰纳位置"}},{q="站在莱恩身旁的动物是谁？",a="莱恩的伙伴是刃豹库尔拉和狼达戈里。在阿斯特兰纳，它们始终伴随她左右。",al={"莱恩·狼行者宠物","莱恩的狼和刃豹","莱恩的伙伴"}},{q="莱恩在哨兵中担任何种职务？",a="莱恩是驻守灰谷中部的一名哨兵高级军官。她向斥候下达命令，管理哨站，并协调应对当地威胁的行动。",al={"莱恩军衔","莱恩是军官吗","莱恩在哨兵中的职务"}},{q="莱恩的朋友泰洛尼斯遭遇了什么？",a="泰洛尼斯在野外寻找达图尔的魔棒所需的宝石时遭到杀害。莱恩安排人手寻回他的遗骸，并完成他的使命。",al={"泰洛尼斯是谁","莱恩的朋友泰洛尼斯","泰洛尼斯之死"}},{q="莱恩为何如此关注熊怪？",a="污林和蓟皮等遭到腐化的熊怪部族变得愈发凶暴。它们在林间道路上伏击旅人，威胁着阿斯特兰纳的安宁。",al={"莱恩熊怪任务","为何对抗蓟皮","污林灰谷祸患"}},{q="达图尔的变形魔棒在她的任务线中有何用途？",a="达图尔的变形魔棒能让冒险者化身熊怪，与克罗格交谈。这为迎战堕落的酋长兰恩·血牙铺平了道路。",al={"达图尔的魔棒用途","达图尔的魔棒有何作用","莱恩的净化法杖"}}},fp="16,189,21.308.0,32.393.0,12.503.1,36.134.0,43.98.0,42.144.0,40.166.1,49.165.0,53.142.1"}
P.entries["npc:ragnar-thunderbrew"] = {n="拉格纳·雷酒",s="在卡拉诺斯的雷酒酿制厂，拉格纳·雷酒负责为家族酒馆补充物资，为客人准备饭菜。在丹莫罗各地，这位矮人酿酒师因家族的啤酒烤猪排而闻名。",h="在卡拉诺斯的雷酒酿制厂，拉格纳·雷酒负责为家族酒馆补充物资，为客人准备饭菜。在丹莫罗各地，这位矮人酿酒师因家族的啤酒烤猪排而闻名。",kw={"麦酒","啤酒烤猪排","丹莫罗","矮人","葛瑞姆·雷酒","卡拉诺斯","拉格纳·雷酒","雷酒酿制厂"},ang={["profession:Cooking"]="身为厨师，你可以向拉格纳请教雷酒家族的啤酒烤猪排配方，以及丰盛的矮人酒馆菜肴的做法。",["race:Dwarf"]="身为途经丹莫罗的矮人，你可以在拉格纳的酒馆里品尝氏族的麦酒和猪排，找到家乡的滋味。"},sec={{t="卡拉诺斯待客之道的支柱",b="拉格纳·雷酒在卡拉诺斯的雷酒酿制厂负责厨房和酿酒工作。巡山人、旅人和逃离诺莫瑞根的侏儒难民都聚集在这里。他用矮人麦酒制作的啤酒烤猪排是丹莫罗的一道特色菜。\n\n自从常年为他供应肉食的人加入后方军队，食材就变得难以采购。如今，拉格纳依靠四处行走的巡山人和猎人为厨房送来新鲜的峭壁野猪肋肉。"},{t="雷酒家族的传承",b="在铁炉堡的领地上，雷酒这个姓氏以矮人美酒和酒馆生活而闻名。几个收获季前，他的哥哥葛瑞姆·雷酒在醉酒后失踪，此后一直是拉格纳在维持酿制厂的运转。\n\n他守护着家族的酿酒传承，提防那些窃贼，譬如曾偷走雷霆啤酒配方的黑铁矮人。客人焦躁不安，物资短缺，酒馆里又争执不断，拉格纳仍在卡拉诺斯为旅人供应酒食。"}},faq={{q="拉格纳·雷酒是谁？",a="拉格纳·雷酒在卡拉诺斯的雷酒酿制厂酿酒并照看酒馆。他还会烹制氏族著名的麦酒烤猪排。",al={"拉格纳是谁","拉格纳·雷酒的职责","拉格纳 卡拉诺斯"}},{q="拉格纳为什么在寻找猪排？",a="常年为拉格纳供应肉食的人加入了麦格尼国王的军队，厨房因此缺少食材。他向路过的猎人和旅人购买新鲜肋肉，为酒馆的客人准备饭菜。",al={"为什么需要野猪肉","麦酒烤猪排任务","猪排供应"}},{q="拉格纳和葛瑞姆·雷酒是什么关系？",a="葛瑞姆是拉格纳的哥哥。他们的父亲阿基鲁斯创办了雷酒酿制厂。几个收获季前，葛瑞姆在醉酒后失踪，此后一直是拉格纳在维持酿制厂的运转。",al={"拉格纳和葛瑞姆","葛瑞姆·雷酒的关系"}},{q="拉格纳·雷酒在哪里？",a="拉格纳在卡拉诺斯的雷酒酿制厂内工作，那里位于丹莫罗中部白雪覆盖的丘陵地带。",al={"拉格纳的位置","在哪里找到拉格纳·雷酒"}}},fx={a4e8a35c={q="拉格纳·雷酒效忠哪一方？",a="拉格纳坚定地支持铁炉堡和 大联盟。他在卡拉诺斯经营生意，自豪地招待常来酿酒厂的矮人旅客、巡山人和当地巡逻队。",al={"拉格纳·雷酒阵营","拉格纳联盟","拉格纳是否对联盟友好"}},["6e9b3705"]={q="拉格纳·雷酒为什么在卡拉诺斯？",a="拉格纳在卡拉诺斯经营雷酒酿制厂。作为共同所有者，他在当地旅店酿造矮人麦酒，准备丰盛的饭菜，并打理家族在丹莫罗的繁忙生意。",al={"拉格纳为什么在卡拉诺斯","拉格纳·雷酒在此的原因","拉格纳在卡拉诺斯做什么"}},["6804fc69"]={q="拉格纳·雷酒为什么出名？",a="拉格纳以掌握啤酒烤猪排的家传秘方而闻名，这道菜是丹莫罗最著名、最受喜爱的矮人传统美食之一。",al={"拉格纳因何出名","拉格纳·雷酒名声","雷酒为什么出名"}}},fp="18,202,32.449.0,22.503.0,26.145.0,36.189.0,47.188.0,36.101.0"}
P.entries["npc:rahauro"] = {n="拉哈罗",s="在雷霆崖的长者高地，拉哈罗派遣部落战士对抗奥格瑞玛地下的威胁。他效命于玛加萨·野性图腾，安排人手应对怒焰裂谷的穴居人，并寻回一名遇难密使的遗物。",h="在雷霆崖的长者高地，拉哈罗派遣部落战士对抗奥格瑞玛地下的威胁。他效命于玛加萨·野性图腾，安排人手应对怒焰裂谷的穴居人，并寻回一名遇难密使的遗物。",kw={"长者高地","恐怖图腾","玛加萨","玛尔","怒焰裂谷","拉哈罗","背包","雷霆崖","穴居人"},ang={["faction:Horde"]="身为部落的一员，你可以在雷霆崖接下拉哈罗的早期地下城任务。这些任务旨在为牛头人领袖效力，并保卫兽人的都城奥格瑞玛。",["race:Tauren"]="身为一名置身雷霆崖台地上的牛头人，你可以看到玛加萨的影响力如何延伸至长者高地之外。拉哈罗就在她的核心圈子里办事。"},sec={{t="老妪的代言人",b="拉哈罗在长者高地的高台上侍奉玛加萨·野性图腾。他代这位老妪传话行事，而她则依靠信任的仆从招募人手。当野生生物在兽人都城地下成群出没时，拉哈罗负责安排，派遣部落佣兵前去应对。"},{t="怒焰裂谷的危机",b="怒焰裂谷洞穴中的穴居人拒绝了玛加萨的求和。她的使者前往奥格瑞玛地下谈判，却遭到穴居人袭击并丧命。玛加萨认为这些生物威胁着部落，拉哈罗便派遣勇士进入洞穴，削减它们的数量，摸清它们的实力。"},{t="遇难使者的背包",b="玛尔·恐怖图腾效命于玛加萨，也是被穴居人杀害的使者之一。玛尔在怒焰裂谷遇难前有所发现，原本打算呈给女主人。拉哈罗派遣探险者穿过火山地带的道路，寻回玛尔遗失的背包，以及其中存放的发现。"}},faq={{q="拉哈罗是谁？",a="拉哈罗在雷霆崖的长者高地侍奉玛加萨·野性图腾。他指派旅者为女主人和部落办事。",al={"拉哈罗是谁","拉哈罗的故事","这个牛头人是谁"}},{q="在哪里可以找到拉哈罗？",a="你可以在雷霆崖的长者高地找到拉哈罗，他就在玛加萨·野性图腾附近。",al={"拉哈罗的位置","拉哈罗在哪里","寻找拉哈罗"}},{q="拉哈罗为什么要冒险者前往怒焰裂谷？",a="玛加萨曾派遣使者与奥格瑞玛地下的穴居人谈判，但穴居人杀害了他们。拉哈罗派遣冒险者进入怒焰裂谷，削减穴居人的数量，抵御它们对部落的威胁。",al={"拉哈罗 怒焰裂谷","为什么派人去怒焰裂谷","拉哈罗 穴居人任务"}},{q="玛尔·恐怖图腾是谁？",a="玛尔·恐怖图腾效命于玛加萨，曾作为她的使者进入怒焰裂谷。他在洞穴中有了值得留意的发现，却没能将其带给她，便被穴居人杀害。",al={"玛尔·恐怖图腾","玛尔是谁","寻找遗失背包的人"}},{q="拉哈罗寻找的遗失背包里有什么？",a="遗失的背包里装着玛尔·恐怖图腾生前发现的东西。拉哈罗希望有人从穴居人盘踞的洞穴中找回背包，将它安全带回雷霆崖。",al={"遗失背包的内容","背包里有什么","玛尔的背包"}},{q="拉哈罗属于恐怖图腾部族吗？",a="拉哈罗在长者高地侍奉玛加萨·野性图腾，负责处理与玛尔等密使有关的事务。他在雷霆崖为玛加萨效力，是她的随从之一。",al={"拉哈罗是恐怖图腾成员吗","拉哈罗的部族","拉哈罗的阵营"}}},fp="7,229,24.275.0,25.292.0,26.272.1,15.125.0,25.76.0,58.200.0,23.175.0,46.170.0,43.154.0"}
P.entries["npc:raleigh-andrean"] = {n="拉林夫·安迪恩",s="在幽暗城，拉林夫·安迪恩与被遗忘者生活在一起。他的请求表明，他对自己生前的人类生活和故人已毫不在意。",h="在幽暗城，拉林夫·安迪恩与被遗忘者生活在一起。他的请求表明，他对自己生前的人类生活和故人已毫不在意。",kw={"丈夫的复仇","黛丽娅","被遗忘者","拉林夫·安迪恩","蔑视之戒","贸易区","幽暗城","瓦德雷·莫莱"},ang={["race:Undead"]="身为 Undead，你可以通过拉林夫对待昔日人类羁绊的态度，看出一名被遗忘者如何面对亡灵的存在。"},sec={{t="苦涩的死后生活",b="第三次大战之前，拉林夫·安迪恩还是人类，住在洛丹伦。他娶了黛丽娅，与瓦德雷·莫莱是朋友。天灾军团 席卷王国，杀死了拉林夫，又将他复活为毫无心智的奴仆，为巫妖王效力。巫妖王的控制瓦解后，希尔瓦娜斯·风行者领导了反抗，拉林夫恢复了自由意志，加入幽暗城的被遗忘者。"},{t="复仇胜过悲伤",b="拉林夫·安迪恩的请求表明，亡灵之躯已逐渐磨灭了他的情感。当黛丽娅的婚戒被带到他面前时，他对亡妻既无悲伤，也无眷恋。他对她的死不屑一顾，转而索要瓦德雷·莫莱被砍下的双手，这位昔日的朋友正是杀害她的凶手。拉林夫留下这双手是为了铭记背叛，而非出于对黛丽娅的爱。帮助他的人会得到一枚由纯粹的蔑视铸成的戒指。"}},faq={{q="拉林夫·安迪恩在哪里？",a="拉林夫·安迪恩住在幽暗城的贸易区，与被遗忘者生活在一起。",al={"拉林夫·安迪恩位置","拉林夫在哪里","寻找拉林夫·安迪恩"}},{q="拉林夫生前是什么人？",a="在 天灾军团 席卷洛丹伦之前，拉林夫还是人类，住在那里。他娶了黛丽娅，与瓦德雷·莫莱是朋友。",al={"拉林夫的过往","拉林夫曾是什么人","拉林夫·安迪恩背景故事"}},{q="拉林夫为什么要向瓦德雷·莫莱复仇？",a="拉林夫想要复仇，是因为他昔日的朋友瓦德雷·莫莱杀害了黛丽娅。拉林夫要求砍下瓦德雷的双手。",al={"为什么杀 瓦德雷","拉林夫的妻子","瓦德雷·莫莱 谋杀"}},{q="拉林夫是如何摆脱 天灾军团 控制的？",a="第三次大战期间，天灾军团 杀死了拉林夫，又将他复活为奴仆。巫妖王的控制瓦解后，希尔瓦娜斯·风行者领导了一场反抗，让拉林夫和许多其他人获得自由，他们组成了被遗忘者。",al={"拉林夫如何成为 被遗忘者","拉林夫摆脱 天灾军团 控制"}}},fp="15,158,18.420.0,20.430.1,33.79.0,34.139.0,47.117.1,45.211.0"}
P.entries["npc:randis"] = {n="Randis",s="在教堂广场，兰迪斯渴望看看暴风城之外的土地。每逢儿童周，他都会满怀热情地跟随愿意照顾他的冒险者，游历联盟各地。",h="在教堂广场，兰迪斯渴望看看暴风城之外的土地。每逢儿童周，他都会满怀热情地跟随愿意照顾他的冒险者，游历联盟各地。",kw={"教堂广场","儿童周","人类孤儿","孤儿监护员奈丁加尔","兰迪斯","暴风城"},ang={["faction:Alliance"]="身为联盟的勇士，在儿童周期间照顾兰迪斯会让你想起，你的战斗守护着下一代平民和心怀梦想的孩子。"},sec={{t="暴风城收养的孩子",b="兰迪斯住在暴风城光明大教堂附近的孤儿院里。王国的战乱让许多孩子失去了家人。每年儿童周期间，孤儿监护员奈丁加尔都会将一只哨子交给富有同情心的英雄，托付他们照顾兰迪斯。他满怀好奇，总有问不完的问题，梦想着冒险，也喜欢出谜语。他说，长大后想当暴风城的国王。"},{t="放眼世界",b="兰迪斯平日大多待在教堂广场，因此离开都城对他来说就像一场盛大的冒险。他说，铁炉堡这样的地方闻起来怪怪的。他对世界的惊奇，让人看见联盟英雄奋战所要守护的一切。"}},faq={{q="兰迪斯是谁？",a="兰迪斯是住在教堂广场的暴风城孤儿院里的一名人类孩子。儿童周期间，愿意照顾他的冒险者可以带他游历联盟各地。",al={"兰迪斯 非玩家角色","人类孤儿是谁","暴风城人类孤儿"}},{q="如何见到兰迪斯？",a="儿童周期间，孤儿监护员奈丁加尔会在教堂广场将一只孤儿哨交给冒险者。吹响哨子，兰迪斯就会跟随你踏上旅途。",al={"如何获得兰迪斯","召唤兰迪斯","暴风城孤儿哨"}},{q="兰迪斯想去哪些地方？",a="兰迪斯想跟随带上他的英雄，探访暴风城城墙之外的任何地方。他去过铁炉堡，说那里闻起来怪怪的。",al={"兰迪斯地点","兰迪斯景点","儿童周人类孤儿地点"}},{q="兰迪斯为什么住在孤儿院里？",a="兰迪斯住在孤儿院里，是因为暴风城和艾泽拉斯各地接连不断的战争、入侵与苦难夺走了他的父母。孤儿监护员奈丁加尔照顾的许多孩子都有着同样的遭遇。",al={"兰迪斯父母","兰迪斯为什么是孤儿","暴风城孤儿院背景故事"}}},fx={["5920bd8f"]={q="兰迪斯效忠哪一方？",a="兰迪斯是在暴风城长大的人类小男孩，全心效忠联盟。他的童年在城中孤儿院的照料下度过，仰慕联盟的伟大英雄与领袖，甚至梦想有朝一日长大后能亲自成为暴风城的国王。",al={"兰迪斯 联盟","兰迪斯 属于联盟吗","兰迪斯 的阵营"}},ece316b6={q="兰迪斯为什么在暴风城？",a="兰迪斯住在暴风城，因为他是教堂广场当地孤儿院里的一名孤儿，由孤儿监护员奈丁加尔照料。每逢一年一度的儿童周庆典，他都热切地等待着响应监护员召唤的游历冒险者，带他走出城市，领略广阔世界的奇观。",al={"兰迪斯 为什么在这里","兰迪斯 为什么在暴风城","兰迪斯 在暴风城的位置"}},["33179f48"]={q="兰迪斯与谁有关联？",a="兰迪斯由孤儿监护员奈丁加尔照料，她负责照顾住在暴风城教堂广场的人类孤儿。在儿童周期间，他依靠富有同情心的联盟冒险者，带他一同踏上城墙之外的旅途。",al={"谁照顾 兰迪斯","兰迪斯 的人际关系","兰迪斯 与谁有关联"}}},fp="6,159,19.395.0,17.202.0,14.170.0,23.155.0,38.147.0,37.189.0"}
P.entries["npc:ranger-glynda-nal-shea"] = {n="Ranger Glynda Nal'Shea",s="在奥伯丁的哨所附近，游侠戈琳达·纳希指挥着黑海岸的防御。这位经验丰富的暗夜精灵哨兵派遣旅者应对威胁，调查沿岸的异常迹象。",h="在奥伯丁的哨所附近，游侠戈琳达·纳希指挥着黑海岸的防御。这位经验丰富的暗夜精灵哨兵派遣旅者应对威胁，调查沿岸的异常迹象。",kw={"奥伯丁","黑海岸","戈琳达","莫克迪普","纳尔谢","暗夜精灵","游侠","红色水晶","哨兵"},ang={["class:Hunter"]="身为猎人，你或许能体会戈琳达敏锐的直觉，以及她应对野兽和海岸掠食者时直截了当的作风。",["faction:Alliance"]="作为从泰达希尔或东部王国乘船抵达的联盟旅者，你可以接下戈琳达的悬赏，协助守卫黑海岸周边。",["race:NightElf"]="对暗夜精灵而言，戈琳达·纳希恩体现了守护卡利姆多神圣海岸所需的警觉，以抵御凶猛的野兽与古老的腐化。"},sec={{t="奥伯丁的守护者",b="腐化日益蔓延，敌对势力不断侵入黑海岸，哨兵戈琳达·纳希恩在奥伯丁协调斥候的行动。她监视着镇外的荒野，并依靠有能力的旅者守卫周边，保护沿岸的暗夜精灵领地。"},{t="沿岸的威胁",b="戈琳达警惕着沿岸聚集的危险，尤其是镇南那些愈发猖獗的鱼人。她负责悬赏铲除莫克迪普等威胁，也派遣斥候调查奇异的发现，包括据报出现在黑海岸东部山脉附近的一块深红色水晶。"}},faq={{q="游侠戈琳达·纳希是谁？",a="哨兵戈琳达·纳希恩是一名驻扎在奥伯丁的暗夜精灵，负责组织遍及黑海岸的斥候巡逻与防御。",al={"戈琳达·纳希恩","戈琳达是谁","游侠戈琳达"}},{q="在哪里可以找到戈琳达·纳希恩？",a="在黑海岸的联盟主要定居点奥伯丁，靠近哨兵哨所和城镇入口的地方，可以找到戈琳达·纳希恩。",al={"戈琳达位置","戈琳达在哪","哪里能找到戈琳达"}},{q="游侠戈琳达·纳希恩提供哪些任务？",a="戈琳达提供应对当地危险的任务，包括悬赏铲除莫克迪普，以及调查黑海岸峭壁一带的红色水晶。",al={"戈琳达任务","戈琳达提供什么"}},{q="戈琳达为什么担忧莫克迪普？",a="莫克迪普是一名凶残的鱼人酋长，他袭击暗夜精灵前哨站和旅者，威胁着南部海岸与奥伯丁的安全。",al={"莫克迪普是谁","为什么杀莫克迪普"}},{q="红色水晶任务线是什么？",a="红色水晶调查始于戈琳达派遣斥候攀上黑海岸东部的峭壁，检查一块散发着脉动光芒的奇异水晶，并取回碎片以供研究。",al={"红色水晶 黑海岸","红色水晶任务"}},{q="戈琳达·纳希恩效忠哪个阵营？",a="戈琳达·纳希恩效忠于达纳苏斯的暗夜精灵，并指挥着黑海岸的一处联盟军事前哨站。",al={"戈琳达阵营","戈琳达为谁效力"}}},fp="22,149,21.269.0,23.254.0,30.122.0,35.135.0,46.146.0,39.160.0,35.166.0,40.108.0"}
P.entries["npc:rau-cliffrunner"] = {n="劳恩·峭壁行者",s="劳恩·峭壁行者是一名牛头人斥候兼学者，驻守在千针石林高处的乱风岗。他致力于保护族人免受当地威胁，并通过古老的遗物研究敌对的加拉克半人马的历史与起源。劳恩与雷霆崖的盟友紧密合作，协调深入峡谷各处危险敌方据点的行动。",h="劳恩·峭壁行者是一名牛头人斥候兼学者，驻守在千针石林高处的乱风岗。他致力于保护族人免受当地威胁，并通过古老的遗物研究敌对的加拉克半人马的历史与起源。劳恩与雷霆崖的盟友紧密合作，协调深入峡谷各处危险敌方据点的行动。",kw={"裂开的蹄子","乱风岗","加拉克","劳恩·峭壁行者","神圣火焰","裂蹄峭壁","裂蹄堡","千针石林","赞金·石蹄"},ang={["faction:Horde"]="劳恩的努力有助于保卫乱风岗，这座孤立的部落堡垒对于维持贫瘠之地与塔纳利斯之间的补给线至关重要。",["race:Tauren"]="对牛头人而言，了解半人马关乎自身文化的存续；劳恩研究半人马的起源，是为了深入了解那场几乎让Shu'halo灭绝的世代冲突。"},sec={{t="峡谷守望者",b="劳恩·峭壁行者驻守在乱风岗险峻的崖顶，警惕地注视着千针石林广袤而饱受烈日炙烤的大地。这片危机四伏的土地上遍布凶猛的野兽、野猪人和好战的半人马氏族，而这座牛头人哨站是部落至关重要的庇护所。劳恩既负责哨站的组织事务，也潜心调查，力求在新出现的威胁吞没脆弱的台地聚落之前将其消除。"},{t="加拉克的秘密",b="劳恩最为执着的，是半人马的远古起源——这个种族世世代代与牛头人进行着残酷的战争。得知当地的加拉克部族守护着一件可追溯至半人马诞生之初的神圣遗物后，劳恩开始寻找绕过遗物魔法防护的方法。劳恩与雷霆崖的赞金·石蹄合作，从灰谷取得神圣的月亮井水，浇灭裂蹄堡的永恒火焰，让冒险者能够取回神秘的裂开的蹄子，供他研究。"}},faq={{q="在哪里可以找到劳恩·峭壁行者？",a="劳恩·峭壁行者住在乱风岗顶上，那是位于千针石林中部的一座醒目的台地哨站。",al={"劳恩·峭壁行者位置","劳恩在哪","劳恩·峭壁行者在哪"}},{q="劳恩·峭壁行者在调查什么？",a="劳恩正在调查半人马的起源与神秘传统。他寻找着裂开的蹄子，这件古老的部族遗物由裂蹄峭壁的加拉克半人马保管，希望它奇异的能量能揭示牛头人宿敌的往事。",al={"劳恩·峭壁行者目的","劳恩想要什么","劳恩为什么想要蹄子"}},{q="劳恩为什么需要月亮井水？",a="加拉克半人马用永不熄灭的魔法火焰守护着他们的古老遗物。劳恩得知，从灰谷一处暗夜精灵月亮井中汲取的纯净井水蕴含着神圣的力量，能够熄灭火盆中的火焰，破除其防护。",al={"劳恩月亮井水","神圣火焰月亮井","为什么需要月亮井水"}},{q="雷霆崖有谁在与劳恩·峭壁行者合作？",a="驻守在雷霆崖高地的赞金·石蹄直接与劳恩合作。赞金协调取回灰谷月亮井水的事宜，随后指引值得信赖的部落旅者前往下方的乱风岗寻找劳恩。",al={"劳恩盟友","赞金与劳恩","谁派我去找劳恩"}},{q="裂开的蹄子是什么？",a="裂开的蹄子是一件远古半人马神器，由裂蹄堡的加拉克氏族保存。它的历史可追溯至半人马种族诞生之时，散发着异常的能量，劳恩打算解开其中的奥秘。",al={"裂开的蹄子遗物","蹄子是什么","半人马遗物千针石林"}},{q="劳恩·峭壁行者属于某个特定的牛头人部族吗？",a="没有记载表明劳恩属于哪个特定部族。他是一名来自雷霆崖、驻守在乱风岗的牛头人战士，也没有任何线索将他的姓氏与某个已知部族联系起来。",al={"劳恩·峭壁行者部族","劳恩属于哪个部族"}}},fx={c4ebc959={q="劳恩·峭壁行者是谁？",a="劳恩·峭壁行者是一名牛头人学者和斥候，驻扎在千针石林峡谷上方的乱风岗。他致力于揭开当地加拉克半人马的历史，与雷霆崖的其他研究者合作，寻找并研究与卡利姆多半人马部族起源有关的古代神器。",al={"劳恩·峭壁行者是谁","劳恩·峭壁行者的背景"}},dfeb320c={q="劳恩·峭壁行者站在哪一方？",a="劳恩坚定地与雷霆崖的牛头人和部落站在一起。他驻扎在乱风岗，与部落的旅人协调行动，守卫台地，并寻找可能揭示部落宿敌半人马重要情报的遗物。",al={"劳恩·峭壁行者的阵营","劳恩属于部落吗","劳恩·峭壁行者的效忠对象"}},["3af393e1"]={q="劳恩·峭壁行者想要什么？",a="劳恩想揭开一种名为裂开的蹄子的古代半人马遗物背后的秘密，据说它自半人马种族诞生以来便保存至今。为了取得它，他需要月亮井水熄灭守护它的圣火，而这圣火位于裂蹄堡。他希望遗物的奇异能量能让他深入了解半人马的历史。",al={"劳恩·峭壁行者的目标","劳恩想要什么","劳恩的动机"}},["66929801"]={q="劳恩·峭壁行者为何在乱风岗？",a="乱风岗是部落在千针石林的核心据点，高踞峡谷之上，毗邻加拉克半人马的聚居地。劳恩留在这里负责监督对裂蹄峭壁的调查，并解读峭壁中保存的古代遗物之谜。",al={"劳恩·峭壁行者为何在这里","劳恩为何在千针石林","劳恩为何在乱风岗"}}},fp="15,188,22.258.0,20.394.1,33.88.0,38.219.0,33.226.0,53.201.0,24.184.0,55.164.0"}
P.entries["npc:razzle-sprysprocket"] = {n="拉兹·滑链",s="在卡拉诺斯，拉兹·滑链寻找着诺莫瑞根沦陷时遗失的机械。他与奥齐·电环一起，收集散落在丹莫罗雪山间的零件。",h="在卡拉诺斯，拉兹·滑链寻找着诺莫瑞根沦陷时遗失的机械。他与奥齐·电环一起，收集散落在丹莫罗雪山间的零件。",kw={"丹莫罗","工程师","卡拉诺斯","奥齐·电环","拉兹","重新组合","滑链"},ang={["profession:Engineering"]="工程师们或许会觉得拉兹是个志趣相投的人。他的项目表明，侏儒的发明离计算失误和爆炸往往只有一步之遥。",["race:Gnome"]="作为流亡丹莫罗的侏儒，拉兹展现了创造精神，以及在诺莫瑞根沦陷后重建家园、找回失物的决心。"},sec={{t="卡拉诺斯的工匠",b="诺莫瑞根沦陷后，拉兹来到丹莫罗避难，并在卡拉诺斯开了一间工坊。他擅长摆弄精密机械，与同为工程师的奥齐·电环并肩工作。他们一起寻找逃离遭受辐射的家园时遗失或被拾荒者取走的陀螺仪和齿轮装置。"},{t="保卫工坊",b="野兽游荡在丹莫罗冰封的山脊上，霜鬃巨魔也在这一带劫掠。它们的出没让拉兹的工作充满危险。即便如此，他仍努力维持侏儒装置的运转，找回诺莫瑞根遗失的奇妙造物。"}},faq={{q="拉兹·滑链是谁？",a="拉兹·滑链与奥齐·电环一起，在丹莫罗的卡拉诺斯摆弄机械。",al={"拉兹·滑链","拉兹是谁","拉兹 卡拉诺斯"}},{q="拉兹·滑链需要什么帮助？",a="拉兹需要旅人们在丹莫罗寻找遗失的小玩意、齿轮装置，以及侏儒工程项目所需的零件。",al={"拉兹任务","自动净化装置帮助","拉兹想要什么"}},{q="在哪里可以找到拉兹·滑链？",a="拉兹在丹莫罗中部的卡拉诺斯工作，就在旅店和铁匠铺外、工匠站附近的露天场地上。",al={"拉兹位置","拉兹在哪里","拉兹·滑链地图"}},{q="拉兹·滑链与其他姓滑链的人有亲属关系吗？",a="没有提及拉兹的任何亲属。瑞兹尔滑链与他同姓，但两人似乎没有亲属关系。",al={"滑链家族","拉兹亲属"}}},fx={b527298b={q="拉兹·滑链效忠哪一方？",a="拉兹·滑链效忠诺莫瑞根流亡者与联盟。他与其他难民一同驻留在卡拉诺斯，与奥齐·电环等侏儒发明家密切合作，帮助丹莫罗流离失所的同胞。",al={"拉兹·滑链的阵营","拉兹属于联盟吗","拉兹·滑链效忠谁"}},fcfe3829={q="拉兹·滑链为什么在卡拉诺斯？",a="诺莫瑞根悲惨陷落后，拉兹·滑链和许多侏儒一样，在卡拉诺斯避难。他在这座白雪覆盖的小镇开设店铺，继续钻研机械，并寻找材料，支持侏儒持续进行的复兴工作。",al={"拉兹为什么在这里","拉兹·滑链为什么在卡拉诺斯","拉兹为何来到卡拉诺斯"}}},fp="19,172,21.298.0,23.228.0,27.80.0,45.120.0,37.111.0,54.111.0"}
P.entries["npc:red-jack-flint"] = {n="红衣弗林特",s="在米奈希尔城堡，红衣弗林特为准备横渡大海的旅人牵线，引荐水手。他是一位经验丰富的人类海员，也是少女之爱号的船员，帮助旅人寻找前往卡利姆多的船只和接头人。",h="在米奈希尔城堡，红衣弗林特为准备横渡大海的旅人牵线，引荐水手。他是一位经验丰富的人类海员，也是少女之爱号的船员，帮助旅人寻找前往卡利姆多的船只和接头人。",kw={"菲欧拉·长耳","少女的贞洁号","米奈希尔港","米奈希尔城堡","红衣弗林特","湿地"},ang={["faction:Alliance"]="作为从卡兹莫丹乘船出发的联盟旅人，你可以依靠红衣弗林特这样的水手，与卡利姆多北部沿岸的前哨站取得联系。"},sec={{t="米奈希尔城堡的水手",b="红衣弗林特是米奈希尔城堡里一位经验丰富的水手。身为少女之爱号的船员，他熟知从卡兹莫丹通往遥远海岸的航线。他也会指引有本领的旅人去拜访无尽之海彼岸的盟友，其中就包括卡利姆多的菲欧拉·长耳。"}},faq={{q="红衣弗林特是谁？",a="红衣弗林特是少女之爱号上的一名人类水手。他在米奈希尔港的米奈希尔城堡里，帮助旅人与东部王国和卡利姆多各地的接头人取得联系。",al={"弗林特是谁","红衣弗林特的故事","弗林特做什么"}},{q="在哪里可以找到红衣弗林特？",a="红衣弗林特就在米奈希尔城堡内，这座石砌堡垒守卫着湿地的米奈希尔港。",al={"红衣弗林特的位置","弗林特在哪里","寻找红衣弗林特"}},{q="红衣弗林特在哪艘船上航行？",a="红衣弗林特在少女之爱号上任职，这是一艘从米奈希尔港出航的商船。",al={"弗林特的船","红衣弗林特在哪艘船上","少女之爱号"}},{q="红衣弗林特让旅人去见谁？",a="红衣弗林特会指引旅人去见菲欧拉·长耳，她是他在大海彼岸的塞拉摩港的搭档。",al={"弗林特的任务","与菲欧拉·长耳的关系","弗林特让人去哪里"}}},fp="14,192,25.260.0,22.199.0,34.111.0,38.96.0,46.104.0"}
P.entries["npc:rejold-barleybrew"] = {n="雷杰德·麦酒",s="在烈酒村，雷杰德·麦酒一直致力于酿出完美的高山烈酒。他从丹莫罗西部收集原料，逐一试验各种配方。",h="在烈酒村，雷杰德·麦酒一直致力于酿出完美的高山烈酒。他从丹莫罗西部收集原料，逐一试验各种配方。",kw={"麦酒","酿酒师","烈酒村","丹莫罗","微光酒","黑啤酒"},ang={["faction:Alliance"]="身为联盟旅者，你可以指望雷杰德的黑啤酒为丹莫罗各地的人们提振精神。面对穴居人的袭击和猛烈的暴风雪，它能为守卫和旅者增添力量。",["profession:Cooking"]="身为厨师，你能体会雷杰德对原料和配方的用心。他将酿酒视为一门严谨而古老的技艺。",["race:Dwarf"]="身为矮人，你知道雷杰德的酿酒事业承袭了卡兹莫丹的登山传统。烈性麦酒带来温暖和力量，抵御冬日刺骨的严寒。"},sec={{t="酿酒大师",b="丹莫罗的矮人对酿酒十分认真。雷杰德在烈酒村酿酒，那里靠近涌冰河结冰的湖面。他不断用稀有的啤酒花、山中的矿物和纯净的冰水改良配方。他想酿出一种醇厚的黑啤酒，让最强壮的矮人战士也能暖和起来。"},{t="寻觅完美的黑啤酒",b="雷杰德正在为微光酒等酒品寻找恰到好处的风味。他派旅者走遍丹莫罗收集原料，也与钢架补给站的攻城坦克驾驶员互相帮忙。他还安排人手为口渴的顾客送酒。就这样，醇厚的麦酒不断送往丹莫罗寒冷且饱受穴居人侵扰的道路沿线。"}},faq={{q="雷杰德·麦酒是谁？",a="雷杰德·麦酒在丹莫罗的烈酒村酿造麦酒。他努力完善配方，并派旅者收集原料、递送试酿的酒。",al={"雷杰德","雷杰德是谁","雷杰德·麦酒资料"}},{q="在哪里可以找到雷杰德·麦酒？",a="雷杰德·麦酒就在丹莫罗西部的烈酒村，位于涌冰湖结冰的水域旁。",al={"雷杰德位置","雷杰德·麦酒在哪里","雷杰德·麦酒 烈酒村"}},{q="雷杰德正在忙什么？",a="雷杰德正在完善烈性高山酒的配方，其中包括微光酒和其他试酿的麦酒。他需要生长在寒冷山地的植物，以及散布在积雪丘陵各处的酿酒材料。",al={"雷杰德任务","完美的黑啤酒任务","雷杰德在酿什么"}},{q="雷杰德为什么派旅者去找侏儒？",a="雷杰德托人办的差事联系的是矮人同胞，而非侏儒。钢架补给站的驾驶员贝隆·风箱会派旅者向雷杰德索取艾沃沙酒，而雷杰德的微光酒则会送到他的兄弟巡山人维拉特·麦酒手中。",al={"雷杰德 侏儒","雷杰德 艾沃沙酒","贝隆·风箱 雷杰德"}},{q="微光酒是什么？",a="微光酒是雷杰德·麦酒酿造的一种矮人烈酒。它采用山中的原料，在严寒的冬日里喝来别有一番烈劲。",al={"微光酒是什么","微光酒背景故事"}}},fx={["86e90b5e"]={q="雷杰德·麦酒效忠哪一方？",a="雷杰德是一位自豪的铁炉堡矮人，坚定地效忠联盟。与丹莫罗的许多同胞一样，他每天钻研矮人工艺，为途经烈酒村的旅人提供服务，并与钢架补给站的驾驶员贝隆·风箱等矮人同胞保持友好往来。",al={"雷杰德的阵营","雷杰德属于联盟还是部落","雷杰德·麦酒属于联盟吗"}},ede674a2={q="雷杰德·麦酒为什么在烈酒村这里？",a="雷杰德驻留在烈酒村，追求毕生的热爱：酿造卡兹莫丹最上乘的麦酒。烈酒村为他提供清冽的山泉水和当地原料，助他实现酿酒的雄心。",al={"雷杰德为什么在这里","雷杰德为什么在烈酒村","雷杰德为何来到烈酒村"}}},fp="17,158,21.287.0,32.302.0,25.167.0,37.120.0,26.179.0,41.212.0,22.148.0"}
P.entries["npc:rema-schneider"] = {n="雷玛·施涅德",s="在暴风城，雷玛·施涅德在运河裁缝店打理贸易往来。她是一位人类市民，常常帮助当地店主和工匠递送货物。",h="在暴风城，雷玛·施涅德在运河裁缝店打理贸易往来。她是一位人类市民，常常帮助当地店主和工匠递送货物。",kw={"运河裁缝店","哈兰的供货","萨尔曼的包裹","雷玛·施涅德","暴风城 运河"},ang={["faction:Alliance"]="作为暴风城的旅人或新兵，你可以在熟悉这座都城的同时，为雷玛递送一些简单的货物。",["profession:Tailoring"]="雷玛在运河裁缝店内工作，是暴风城日常布料加工贸易的一分子。"},sec={{t="运河 的店主",b="雷玛·施涅德在运河裁缝店管理日常贸易。这家店坐落在暴风城的运河旁，就在通往教堂广场的石桥西侧。布料和成衣在当地工匠之间流转，雷玛则依靠信使将物资从一间作坊送往另一间。"}},faq={{q="雷玛·施涅德在哪里？",a="雷玛·施涅德在暴风城的运河裁缝店内工作。店铺位于 运河 沿岸，就在通往教堂广场的桥西侧。",al={"雷玛·施涅德位置","雷玛在哪","寻找雷玛·施涅德"}},{q="雷玛在暴风城负责什么？",a="雷玛负责协调暴风城各处商人与工匠之间的贸易跑腿事务、物资包裹递送和补给订单。",al={"雷玛·施涅德是谁","雷玛做什么","雷玛·施涅德的作用"}},{q="雷玛教授裁缝技能吗？",a="不。雷玛在运河裁缝店工作，负责裁缝货品的运输。她既不是专业训练师，也不是主要的商贩。",al={"雷玛是裁缝训练师吗","雷玛裁缝训练"}}},fx={["080a82f0"]={q="雷玛·施涅德是谁？",a="雷玛·施涅德是一名人类市民，在暴风城从事裁缝工作。你可以在运河裁缝店里找到忙于生意的她，这家店位于 运河 沿岸，就在通往教堂广场的桥梁西侧。",al={"雷玛·施涅德是谁","雷玛·施涅德的身份","雷玛·施涅德"}},["37d985b5"]={q="雷玛·施涅德效忠哪一方？",a="雷玛·施涅德是暴风城王国的忠诚臣民，坚定地拥护 大联盟。她在都城经营裁缝生意，并协助王国各地的信使与商人。",al={"雷玛·施涅德的阵营","雷玛·施涅德属于联盟吗","雷玛·施涅德效忠谁"}},c7f62ca5={q="雷玛·施涅德想要什么？",a="雷玛专心经营裁缝生意，维系遍布王国的贸易往来。她依靠过路的信使和冒险者运送包裹，为需要她所供材料的当地工匠补充物资。",al={"雷玛想要什么","雷玛·施涅德的目标","雷玛·施涅德的任务"}},d4111a95={q="雷玛·施涅德为什么在这里？",a="雷玛是运河裁缝店的常驻裁缝。运河 是暴风城各城区之间繁忙的商贸通道，因此这里是她管理货物和配送的理想地点。",al={"雷玛为什么在暴风城","雷玛·施涅德为什么在这里","雷玛·施涅德 运河裁缝"}}},fp="14,169,24.299.0,32.149.0,38.127.0,26.146.0"}
P.entries["npc:remulos"] = {n="Remulos",s="守护者雷姆洛斯是塞纳留斯的半神之子，也是月光林地德高望重的保护者。父亲陨落、玛法里奥·怒风沉睡期间，他与大德鲁伊范达尔·鹿盔和哈缪尔·符文图腾一同协助指引塞纳里奥议会。与鹿盔不同，雷姆洛斯将整个自然界的平衡置于暗夜精灵的孤立主义之上。",h="守护者雷姆洛斯是塞纳留斯的半神之子，也是月光林地德高望重的保护者。父亲陨落、玛法里奥·怒风沉睡期间，他与大德鲁伊范达尔·鹿盔和哈缪尔·符文图腾一同协助指引塞纳里奥议会。与鹿盔不同，雷姆洛斯将整个自然界的平衡置于暗夜精灵的...",kw={"塞纳里奥议会","塞纳留斯","范达尔·鹿盔","林地","哈缪尔·符文图腾","月光林地","雷姆洛斯","扎尔塔"},ang={["class:Druid"]="每一位德鲁伊，无论是暗夜精灵还是牛头人，都会前往月光林地，与守护者雷姆洛斯交流，接受掌握动物形态和完成神圣试炼的指引。",["race:Tauren"]="牛头人德鲁伊敬仰雷姆洛斯，因为他不顾范达尔·鹿盔的反对，准许他们的族人加入塞纳里奥议会，并接受完整的教导。"},sec={{t="圣林之主",b="守护者雷姆洛斯是一位不朽的丛林守护者，下半身是一头雄壮的牡鹿，上半身则是一位头生鹿角的古老树妖之父。他守望着月光林地，这片坐落于海加尔山以北的林地是艾泽拉斯德鲁伊的神圣庇护所。玛法里奥·怒风仍被困在翡翠梦境中，雷姆洛斯以神圣的权威为塞纳里奥议会的凡人提供指引。他始终致力于抚平艾泽拉斯的创伤，为在月神湖周围进行神圣仪式的德鲁伊提供援助。"},{t="议会中的裂痕",b="雷姆洛斯时常与大德鲁伊范达尔·鹿盔在理念上发生冲突。鹿盔鼓吹暗夜精灵至上，试图借泰达希尔恢复族人失去的永生，而雷姆洛斯则强烈反对种下这棵新的世界之树，认为此举出于傲慢。雷姆洛斯不顾鹿盔麾下孤立派的反对，接纳哈缪尔·符文图腾和牛头人加入塞纳里奥议会，向这些由萨满祭司转为德鲁伊的成员传授严守的自然奥秘，共同修复大地。"}},faq={{q="守护者雷姆洛斯是谁？",a="他是塞纳留斯的不朽之子，也是已故扎尔塔的兄弟。雷姆洛斯居住在月光林地的雷姆洛斯神殿，担任林地的守护者，也是塞纳里奥议会的高层领袖。",al={"雷姆洛斯背景故事","雷姆洛斯是谁","守护者雷姆洛斯背景"}},{q="雷姆洛斯为何支持牛头人德鲁伊？",a="雷姆洛斯认为，自然的平衡超越了凡人种族之间的隔阂。他认识到牛头人与大地母亲之间深厚的联系，因此力排大德鲁伊范达尔·鹿盔的反对，接纳大德鲁伊哈缪尔·符文图腾及其族人加入塞纳里奥议会。",al={"雷姆洛斯牛头人","牛头人为何有德鲁伊","雷姆洛斯 哈缪尔"}},{q="雷姆洛斯如何看待泰达希尔？",a="雷姆洛斯曾强烈反对创造泰达希尔。他认为，种下这棵新的世界之树是暗夜精灵为夺回失去的永生而做出的自私之举，并非真正为了治愈艾泽拉斯。",al={"雷姆洛斯世界之树","雷姆洛斯范达尔之树"}},{q="雷姆洛斯与玛拉顿有何关系？",a="他的兄弟扎尔塔曾深入凄凉之地，与瑟莱德丝公主交配，在死前成为半人马之父。雷姆洛斯曾警告扎尔塔不要与她结合，而玛拉顿留存着他兄弟与半人马的遗产。",al={"雷姆洛斯 扎尔塔","雷姆洛斯 瑟莱德丝","雷姆洛斯的兄弟"}}},fp="7,213,24.409.0,20.526.0,22.192.0,43.265.0,40.202.0,44.245.1"}
P.entries["npc:remy-two-times"] = {n="雷米",s="雷米在闪金镇买卖货物，收购原材料。他来自赤脊山，因说话时总把句尾重复两遍而得名。",h="雷米在闪金镇买卖货物，收购原材料。他来自赤脊山，因说话时总把句尾重复两遍而得名。",kw={"艾尔文森林","金砂","闪金镇","商人","鱼人","赤脊山","雷米","两次"},ang={["faction:Alliance"]="作为来到闪金镇的联盟新兵，你可以接下雷米那些简单明了的差事，帮助清除当地的威胁，顺便赚些快钱。",["profession:Mining"]="如果你在法戈第或玉石矿井干活，或许会遇见雷米，他收购从那里的狗头人身上收集来的金砂。"},sec={{t="有个怪习惯的商人",b="途经闪金镇的旅人可以和雷米做买卖。他在动荡的艾尔文森林谋求利润，旅人也能通过与他交易赚些钱。他独特的说话方式或许会让他们忍俊不禁。"},{t="乱局中的生意",b="狗头人占据了当地的金矿，凶悍的鱼人盘踞在河岸，艾尔文森林的贸易因此受阻。雷米出钱收购旅人从矿井里的狗头人身上收集来的一袋袋金砂。在水晶湖附近，他留意着鱼人的可疑动向。"}},faq={{q="他为什么被称为“两次”？",a="雷米说话时习惯把句尾的词重复两遍，因此得了这个绰号。",al={"雷米 两次 名字","雷米为什么重复词语","两次 含义"}},{q="雷米原本来自哪里？",a="雷米从赤脊山来到闪金镇，在艾尔文森林做生意。",al={"雷米来历","雷米来自哪里"}},{q="雷米收购那么多金砂做什么？",a="雷米收集从当地矿井里的狗头人身上得来的金砂，用来熔炼、交易或转售获利。",al={"雷米为什么要金砂","金砂交易背景"}},{q="在闪金镇哪里能找到雷米？",a="雷米就在闪金镇的狮王之傲旅店附近的露天处，随时准备与过往的旅人以物易物。",al={"雷米在哪里","雷米闪金镇位置"}}},fx={["99a83a18"]={q="雷米是谁？",a="雷米是一名在闪金镇开店的人类商人。他来自赤脊山，在艾尔文森林一带以古怪的口头习惯闻名，总会把句子末尾的话重复两遍。",al={"雷米是谁","雷米的身份"}},e326d54d={q="雷米效忠哪一方？",a="雷米效忠 大联盟 和暴风城王国。他在闪金镇公开经营生意，与当地官员、镇民和过路冒险者和平往来。",al={"雷米的阵营","雷米属于联盟吗","雷米为谁效力"}},["85133ed8"]={q="雷米想要什么？",a="作为一名有进取心的商人，雷米想要有利可图的商品，也希望当地平安。他热切地与旅人交易，收购从附近矿洞采集的金砂，也急于消除附近任何威胁闪金镇商贸的危险。",al={"雷米想要什么","雷米的目标","雷米为什么需要冒险者"}},["7f55543c"]={q="雷米为什么在闪金镇？",a="雷米离开赤脊山的家乡后，在闪金镇定居，做起了生意。这个繁忙的交通要道村庄总有矿工、旅人和冒险者往来，他们愿意买卖货物，也愿意帮人跑腿。",al={"雷米为什么在闪金镇","雷米为什么离开赤脊山","雷米为什么在这里"}}},fp="16,170,28.203.0,27.253.0,29.103.0,37.77.0,49.99.0,37.106.0"}
P.entries["npc:renato-gallina"] = {n="雷纳多·加林纳",s="在暴风城的贸易区，雷纳多·加林纳吆喝着，招呼旅人光顾自家的酒庄。",h="在暴风城的贸易区，雷纳多·加林纳吆喝着，招呼旅人光顾自家的酒庄。",kw={"运河","加林纳酒店","雷纳多·加林纳","暴风城葡萄酒","贸易区","葡萄酒店广告"},ang={["faction:Alliance"]="作为来到首都的联盟旅人，你可以看到雷纳多为暴风城的本地商业和城内各行各业招揽生意。"},sec={{t="加林纳酒店的吆喝声",b="雷纳多·加林纳在贸易区的摊位间向路人吆喝。他宣称自家的葡萄酒是暴风城最好的。加林纳家族沿运河经营着一家酒庄，雷纳多用传单为它招揽生意。把传单带给店里他的妹妹苏泽塔，她就会送你一瓶免费的葡萄酒。"}},faq={{q="雷纳多·加林纳是谁？",a="雷纳多·加林纳在暴风城的贸易区向当地居民和来访的旅人吆喝。他在为自家的酒庄招揽生意。",al={"雷纳多·加林纳","雷纳多是谁","暴风城葡萄酒叫卖人"}},{q="加林纳酒店在哪里？",a="加林纳酒店位于暴风城的运河沿岸，就在主要商业区附近。",al={"加林纳酒店在哪里","暴风城葡萄酒店位置","加林纳酒店"}},{q="雷纳多请冒险者做什么？",a="雷纳多给旅人一张自家葡萄酒店的传单，请他们带给运河沿岸酒庄里的妹妹苏泽塔·加林纳。凭这张传单，他们可以免费领取一瓶葡萄酒。",al={"雷纳多·加林纳任务","葡萄酒店广告任务","雷纳多想要什么"}}},fx={fce75f2a={q="雷纳多·加林纳效忠哪一方？",a="雷纳多是暴风城的忠诚公民，也是联盟的一员。他心系自己的城市和生意，而最看重的，还是加林纳家族商业抱负的实现。",al={"雷纳多·加林纳阵营","雷纳多·加林纳效忠对象","雷纳多是联盟吗"}},c03f1140={q="雷纳多·加林纳为什么在贸易区？",a="雷纳多站在熙熙攘攘的贸易区广场上，为家族的葡萄酒生意招揽顾客。他没有坐在柜台后面，而是每天直接向途经暴风城的旅人和市民宣传加林纳酒店。",al={"雷纳多为什么在这里","雷纳多·加林纳 贸易区","雷纳多在这里做什么"}},["9e1708f4"]={q="雷纳多·加林纳与谁有关联？",a="雷纳多与加林纳家族关系密切，这个家族经营着位于暴风城运河沿岸的加林纳酒店。他每天都全心投入于推销家族的葡萄酒，并在全城拓展客源。",al={"雷纳多·加林纳的关联","雷纳多·加林纳家族","雷纳多与谁共事"}}},fp="14,85,27.303.0,22.126.0,36.93.0,39.197.0"}
P.entries["npc:renee-lauer"] = {n="旅店老板瑞尼",s="旅人们可以在布瑞尔的恐惧之末旅店找到旅店老板瑞尼，获得食物、饮品和住处。",h="旅人们可以在布瑞尔的恐惧之末旅店找到旅店老板瑞尼，获得食物、饮品和住处。",kw={"布瑞尔","恐惧之末旅店","旅店老板瑞尼","瑞尼·劳尔","血色十字军","提瑞斯法林地"},ang={["race:Undead"]="身为被遗忘者的一员，你可以在瑞尼的旅店里找回往日的慰藉：一炉暖火、一顿饭，还有一处休息的地方。"},sec={{t="恐惧之末的掌柜",b="旅店老板瑞尼在布瑞尔的主要旅店——恐惧之末旅店，迎接疲惫的新来者。她在柜台后出售食物、饮品和日用杂货，还说被遗忘者的胃口大得惊人。当瘟疫的受害者们在世间寻找出路时，她的旅店为提瑞斯法的亡灵提供了一处舒适的休憩之所。"},{t="信件与俘虏",b="初到布瑞尔的人往往会先在瑞尼的旅店停留。丧钟镇的卡尔文·蒙泰古让初出茅庐的冒险者带着一封笔迹潦草的信件去找她，那正是她翘首以盼的消息。旅店地板下的地窖里，还关着一名被俘的血色十字军狂热者。"}},faq={{q="旅店老板瑞尼是谁？",a="旅店老板瑞尼在布瑞尔的恐惧之末旅店迎接旅人。她向途经提瑞斯法林地的人出售食物、饮品和日常补给。",al={"瑞尼·劳尔","布瑞尔旅店老板","布瑞尔的旅店老板是谁"}},{q="瑞尼与卡尔文·蒙泰古有什么联系？",a="在任务“潜行者的交易”中，为卡尔文·蒙泰古跑腿的冒险者受命前往恐惧之末旅店，将一封信直接交给瑞尼。",al={"盗贼的交易 瑞尼","卡尔文·蒙泰古的信"}}},fp="15,94,22.289.0,20.277.0,23.166.0,46.123.0"}
P.entries["npc:renzik-the-shiv"] = {n="“剃刀”雷吉克",s="在暴风城的旧城区，“剃刀”雷吉克负责指导SI:7新招募的潜行者。这名地精是间谍大师马迪亚斯·肖尔信赖的副手，负责接收从联盟各地派来的优秀特工。",h="在暴风城的旧城区，“剃刀”雷吉克负责指导SI:7新招募的潜行者。这名地精是间谍大师马迪亚斯·肖尔信赖的副手，负责接收从联盟各地派来的优秀特工。",kw={"地精","卢修斯","马迪亚斯·肖尔","旧城区","雷吉克","潜行者","si:7","暴风城","剃刀"},ang={["class:Rogue"]="作为联盟潜行者，你从街头使刀的打手成长为SI:7成员的过程中，会经由雷吉克之手。他将新兵派往赤脊山的卢修斯那里，学习实地行动的技巧和生存之道。",["faction:Alliance"]="尽管身为地精，雷吉克仍是暴风城最能干的情报官之一，在SI:7中的地位仅次于马迪亚斯·肖尔。",["race:Human"]="在旧城区的间谍大师肖尔身旁，雷吉克是王国军方精英中罕见的地精。他的地位表明，在暗影中的战争里，忠诚与本领至关重要。"},sec={{t="SI:7中的地精",b="雷吉克对自己的过去守口如瓶。在暴风城，人们知道这名地精已晋升为SI:7间谍大师马迪亚斯·肖尔的副手。他没什么耐心听客套话。新兵到来时，他会问他们是否准备好干活，还是得先打个盹。"},{t="马迪亚斯·肖尔的左膀右臂",b="雷吉克在旧城区的SI:7秘密堡垒中工作，担任马迪亚斯·肖尔的副手。从铁炉堡到达纳苏斯，联盟各地的潜行者导师都把最有潜力的特工派到他这里。他再将他们派往赤脊山的卢修斯等实地教官那里，让他们磨炼在实地行动中生存所需的技巧。"}},faq={{q="为什么一名地精会为暴风城的SI:7效力？",a="雷吉克对自己如何来到暴风城一事守口如瓶。这名地精如今已成为马迪亚斯·肖尔在SI:7的副手。",al={"雷吉克为何加入联盟","暴风城的地精","si7为何有地精"}},{q="他为什么被称为“剃刀”？",a="雷吉克从未向暴风城的人透露自己绰号的来历。在旧城区，人们只知道这个名号，而对一名间谍来说，这或许正是用意所在。",al={"为何叫剃刀","雷吉克的绰号","“剃刀”雷吉克的含义"}},{q="雷吉克为潜行者玩家做些什么？",a="联盟潜行者证明自己的本领后，训练师便会派他们去暴风城找雷吉克。他负责安排他们加入SI:7，并将新兵派往赤脊山的卢修斯等教官那里，学习如何在实地行动中生存。",al={"雷吉克潜行者任务","雷吉克给予什么","与“剃刀”雷吉克交谈"}},{q="雷吉克通常在哪里活动？",a="雷吉克驻守在暴风城旧城区的SI:7总部内，联盟的潜行者新兵会到这里向他报到。",al={"雷吉克的位置","哪里能找到雷吉克","雷吉克在哪里"}},{q="雷吉克与暴风城以外的人有联系吗？",a="有。铁炉堡和达纳苏斯的潜行者训练师会把有潜力的学徒派到雷吉克这里，再由他将新兵转交给卢修斯。卢修斯是SI:7的协作人员，身处赤脊山的湖畔镇。",al={"雷吉克的关系网","雷吉克的人脉","雷吉克的盟友"}}},fp="17,201,16.257.0,26.328.0,45.135.0,28.135.0,38.234.0,34.118.0,44.172.0"}
P.entries["npc:rethiel-the-greenwarden"] = {n="绿色守卫者雷希耶尔",s="在湿地，绿色守卫者雷希耶尔召唤旅者前往绿带草地。他寻求援助，对抗那些扰乱沼泽脆弱平衡的威胁。",h="在湿地，绿色守卫者雷希耶尔召唤旅者前往绿带草地。他寻求援助，对抗那些扰乱沼泽脆弱平衡的威胁。",kw={"沼泽兽","绿色守卫者","藓皮","自然","雷希耶尔","湿地"},ang={["class:Druid"]="身为德鲁伊，你或许能看出，雷希耶尔是艾泽拉斯荒野平衡的一种独特体现。他直接为受伤的生态系统发声，与卡利姆多的远古保护者颇为相似。",["class:Shaman"]="身为萨满祭司，你或许能感知到，雷希耶尔与沼泽的共鸣让他察觉了这里元素与物质的失调。这片土地在污染与烈火中呻吟，而他的声音正呼应着土地本身的苦痛。"},sec={{t="抚平创伤",b="雷希耶尔请求心怀同情的旅者减轻湿地的痛苦。他敦促他们猎杀肆意残害野生生灵的藓皮豺狼人，并收走它们用来焚烧沼泽活树的粗制燧石。他还呼吁削减那些在沼泽水中滋生的染病沼泽爬行者的数量。雷希耶尔希望这些努力能让这片受伤的土地重归安宁。"},{t="沼泽的守护者",b="雷希耶尔在绿带草地潮湿的灌木丛中守望着沼泽。他高大的身躯由苔藓、泥炭和原始植物构成。其他沼泽兽是凶猛的捕食者，在沼泽中游荡，而雷希耶尔拥有意识，言语中透着悲伤。他能感受到湿地是一个活生生的生态系统，正遭受外来掠食者与腐化的折磨。"}},faq={{q="绿色守卫者雷希耶尔是谁？",a="雷希耶尔是一头拥有智慧的沼泽兽，栖身于湿地的绿带草地。与那些浑浑噩噩的同类不同，他能与凡人交谈，并守护着沼泽。",al={"雷希耶尔是谁","雷希耶尔的故事","湿地沼泽兽非玩家角色"}},{q="在哪里可以找到雷希耶尔？",a="雷希耶尔位于湿地的绿带草地，在丹奥加兹东北方。",al={"雷希耶尔位置","雷希耶尔在哪里"}},{q="雷希耶尔为何希望旅者帮助他？",a="雷希耶尔察觉到沼泽正因外来威胁而受苦。他请求旅者对抗四处破坏的藓皮豺狼人团伙，收走它们用来点燃沼泽树木的粗制燧石，并削减染病沼泽爬行者的数量，缓解这片土地的痛苦。",al={"雷希耶尔为何发布任务","雷希耶尔的目标","雷希耶尔想要什么"}},{q="所有沼泽兽都像雷希耶尔一样拥有智慧吗？",a="艾泽拉斯各地的大多数沼泽兽都受敌对本能驱使，缺乏高等智慧。雷希耶尔是个例外：他与自然的深切共鸣赋予了他智慧和言语能力。",al={"沼泽兽会说话吗","有智慧的沼泽兽","雷希耶尔为何会说话"}},{q="雷希耶尔着重应对哪些威胁？",a="雷希耶尔着重遏制凶暴的藓皮豺狼人，收走它们用来焚烧活树的粗制燧石，并清除在沼泽中滋生的染病沼泽爬行者。",al={"雷希耶尔的任务","雷希耶尔的敌人","湿地的威胁与雷希耶尔"}},{q="雷希耶尔属于联盟还是部落？",a="雷希耶尔对联盟友善，对部落敌视。他关爱这片土地，并向愿意修复沼泽的联盟旅者发出呼唤。",al={"雷希耶尔属于联盟吗","雷希耶尔的阵营","部落能与雷希耶尔交谈吗"}}},fp="23,143,18.392.0,21.324.1,31.152.1,25.79.0,44.235.0,41.164.1,35.159.0,50.142.0"}
P.entries["npc:rezlak"] = {n="雷兹拉克",s="在奥格瑞玛以南的杜隆塔尔道路旁，雷兹拉克正等待有人帮他维持补给线。这位地精商人隶属于技工协会，雇用旅人找回遗失的货物，赶走鹰身人。",h="在奥格瑞玛以南的杜隆塔尔道路旁，雷兹拉克正等待有人帮他维持补给线。这位地精商人隶属于技工协会，雇用旅人找回遗失的货物，赶走鹰身人。",kw={"杜隆塔尔","尘风鹰身人","雷兹拉克","保卫商路","工匠协会","沙漠之风"},ang={["faction:Horde"]="作为部落的一员，你会在奥格瑞玛城外遇见雷兹拉克，他的生意往来体现了中立地精公会与初建的部落之间以利益交换为基础的关系。",["profession:Engineering"]="作为工程师，你能理解雷兹拉克为何如此看重机械效率、实用工具和回收的零件。"},sec={{t="务实的技工协会代理人",b="雷兹拉克在剃刀岭与奥格瑞玛之间的峡谷道路旁等候。他代表技工协会，这是一个专注于工程、补给线和务实经营的地精商业组织。只要贸易顺畅，卡利姆多各阵营之间的紧张局势对他就无关紧要。尘风鹰身人袭击了他的运货商队，让沿途变得危机四伏。雷兹拉克仍坚守岗位，雇用愿意通过找回货物、对付鹰身人来赚取报酬的过路人。"}},faq={{q="雷兹拉克是谁？",a="雷兹拉克是技工协会的一名地精商人兼工程师。他是加兹鲁维的手下，被派来帮助杜隆塔尔的兽人。他在北方主干道旁等候援手，帮助他保障补给线的安全，并从当地的害兽手中夺回装备。",al={"雷兹拉克背景故事","雷兹拉克是谁","雷兹拉克 杜隆塔尔"}},{q="雷兹拉克在杜隆塔尔做什么？",a="雷兹拉克在中部平原与通往奥格瑞玛的峡谷隘口之间的商路上做生意。尘风鹰身人伏击了他的商队，使货物散落在干旱的峡谷各处，也让商路变得危机四伏。",al={"雷兹拉克为何在杜隆塔尔","雷兹拉克的目的","雷兹拉克的使命"}},{q="雷兹拉克提供哪些任务？",a="雷兹拉克提供两项任务：“沙漠之风”要求你找回散落在峡谷底部的一袋袋遗失的货物，而“保卫商路”要求你削减附近尘风鹰身人的数量。",al={"雷兹拉克的任务","雷兹拉克提供哪些任务"}},{q="技工协会是什么？",a="技工协会是一个从事机械、发明和后勤工作的地精贸易组织。与其他地精财团和公会一样，它的成员将有利可图的贸易和切实可行的解决办法置于政治忠诚之上。",al={"技工协会","雷兹拉克的阵营"}}},fp="6,202,32.452.0,14.239.0,32.206.0,31.198.0,27.221.0"}
P.entries["npc:rhahk-zor"] = {n="拉克佐",s="在死亡矿井深处，拉克佐用武力推动工程。身为总工头，他管束着迪菲亚劳工和矿工，督促他们修建艾德温·范克里夫的地下堡垒。",h="在死亡矿井深处，拉克佐用武力推动工程。身为总工头，他管束着迪菲亚劳工和矿工，督促他们修建艾德温·范克里夫的地下堡垒。",kw={"死亡矿井","迪菲亚","工头","战锤","食人魔","拉克佐","范克里夫"},ang={["class:Warrior"]="身为战士，与拉克佐交锋会考验你在前线的耐力，你要面对一名挥舞大锤的巨型食人魔，那锤子足以击碎岩石与骨头。",["faction:Alliance"]="对进入月溪镇的联盟冒险者来说，拉克佐的存在表明，迪菲亚潜行者已从拦路抢劫的小股匪徒，发展成了一支拥有坚固防御工事的军队。",["profession:Mining"]="身为矿工，你看到拉克佐以粗暴残忍的手段驱使工人，将西部荒野历史悠久的古老金矿仓促改造成一台工业战争机器。"},sec={{t="矿井深处的工头",b="迪菲亚潜行者将月溪镇废弃的金矿改造成了一座地下堡垒。拉克佐被任命为总工头，负责协调工程。他监督挖掘队和劳工，督促他们开凿隧道，建造范克里夫的秘密工程。"},{t="蛮力驱使",b="拉克佐靠蛮力和一柄巨大的石头战锤维持秩序。迪菲亚挖掘工和地精工程师都知道，违抗命令或拖延工期，都可能招来这名高大工头的致命重击。"}},faq={{q="拉克佐是谁？",a="拉克佐是一名食人魔，也是迪菲亚潜行者在死亡矿井中的工头和打手。他看守着最初的几条挖掘隧道，督促工人不停挖掘，服从管束。",al={"拉克佐","死亡矿井的食人魔首领是谁","死亡矿井首个首领"}},{q="为什么一名食人魔会为迪菲亚潜行者效力？",a="艾德温·范克里夫的叛乱依赖于他能招揽到的武力和雇佣兵。拉克佐的力量和威慑力，使他很适合担任工头，督促繁重的矿井挖掘工作。",al={"死亡矿井为什么有食人魔","拉克佐 迪菲亚"}},{q="拉克佐在矿井中负责什么工作？",a="拉克佐负责监督矿井中的建设。他督促矿工、地精和迪菲亚建筑工人挖空洞穴、维护设备，并为兄弟会修筑防御工事。",al={"拉克佐做什么","拉克佐职责"}},{q="拉克佐位于死亡矿井的什么地方？",a="穿过最初的几条采矿隧道，就能在前段的采掘洞室中找到拉克佐。他站在第一道通往矿井深处的厚重大门前。",al={"拉克佐位置","拉克佐在哪里"}},{q="拉克佐与第一次兽人战争时期的食人魔有关联吗？",a="第一次兽人战争期间，食人魔曾在死亡矿井中生活，后来被黑手的部落消灭。拉克佐究竟属于那些早期氏族，还是范克里夫雇来的蛮横打手，至今仍无定论。",al={"第一次兽人战争 食人魔 死亡矿井","食人魔背景 死亡矿井"}},{q="击败拉克佐后会发生什么？",a="击败拉克佐，就能打破迪菲亚对外围采掘场的控制，打通他所看守的加固防爆门。道路通向更深处的秘密造船厂和工坊。",al={"拉克佐大门","击败拉克佐之后"}}},fp="9,178,23.244.0,16.206.0,17.184.0,50.198.0,37.188.0,44.145.0,67.193.0,40.195.0"}
P.entries["npc:rhinag"] = {n="林纳格",s="在杜隆塔尔西北边界附近的岩石间，林纳格正虚弱地等待着，蝎毒已让他体力不支。这位黑暗之矛巨魔指望路过的旅人及时为他找到解药。",h="在杜隆塔尔西北边界附近的岩石间，林纳格正虚弱地等待着，蝎毒已让他体力不支。这位黑暗之矛巨魔指望路过的旅人及时为他找到解药。",kw={"解毒剂","杜隆塔尔","救命如救火","林纳格","毒尾蝎"},ang={["race:Troll"]="身为巨魔，你或许会看到一位同胞被杜隆塔尔本土的野兽所伤。黑暗之矛部族与部落一同建立家园，也面临着重重考验。"},sec={{t="毒液之危",b="林纳格被一只毒尾蝎蜇伤后，躲在杜隆塔尔西北边界附近的岩石间。毒液让这位黑暗之矛巨魔虚弱不堪，孤立无援。他需要一份毒尾蝎解毒剂，能否活下来，就看路过的旅人能否在毒发之前找到解药。"}},faq={{q="林纳格是谁？",a="林纳格是一位黑暗之矛丛林巨魔旅人，被蝎子蜇伤后，虚弱地困在杜隆塔尔西北边界附近。",al={"林纳格是谁","林纳格的故事","石牙农场的巨魔"}},{q="在哪里能找到林纳格？",a="林纳格在杜隆塔尔西北边界附近的岩石间歇息。",al={"林纳格的位置","林纳格在哪里","石牙农场的巨魔"}},{q="他遭遇了什么？",a="林纳格穿越杜隆塔尔时，被一只毒尾蝎蜇伤。毒液让他动弹不得，他需要在毒发身亡前得到解毒剂。",al={"林纳格为何生病","林纳格中了什么毒","救命如救火背景故事"}}},fp="6,191,16.265.0,14.131.0,26.66.0,21.142.0"}
P.entries["npc:ringo"] = {n="林格",s="林格是一名倒霉的地精探险者，他冒险登上了安戈洛环形山中火羽山灼热的高处。火山令人窒息的高温和有毒气体让他支撑不住，倒在一处洞穴里，急切地盼望有人能帮他下山。他的好友斯普拉格·弗劳克还在马绍尔营地，担心得寝食难安。",h="林格是一名倒霉的地精探险者，他冒险登上了安戈洛环形山中火羽山灼热的高处。火山令人窒息的高温和有毒气体让他支撑不住，倒在一处洞穴里，急切地盼望有人能帮他下山。他的好友斯普拉格·弗劳克还在马绍尔营地，担心得寝食难安。",kw={"火羽山","地精","热衰竭","马绍尔营地","林格","斯普拉格·弗劳克","安戈洛环形山"},sec={{t="离烈焰太近的冒险",b="地精向来以敢于深入险境、搜寻财富或奇珍异物而闻名，但即使对他们来说，火羽山的环境也太过严酷。这座活火山耸立在安戈洛环形山中央，喷吐着火山灰、岩浆和滚烫的蒸汽。林格沿着南坡爬到半山腰，终于再也无法忍受令人窒息的高温。他把随身物品散落在洞外，爬进洞穴躲避外面的酷热，却因热衰竭而完全无法动弹。"},{t="艰难的下山路",b="把林格带下山本身就是一场磨难。脱水和中暑让这个地精虚弱不堪，下山途中一次又一次地昏倒。要让他站稳脚步继续前行，就得用水壶里的水使劲泼醒他，或者偶尔利落地扇他一巴掌，让他恢复意识。护送他避开山上狂暴的元素生物和掠食者，一路回到安全的马绍尔营地，必须时刻保持警惕，直到他与好友斯普拉格团聚。"}},faq={{q="林格是谁？",a="林格是安戈洛环形山的一名地精探险者，他爬上火羽山的火山坡，却因严重的热衰竭倒在了一处洞穴里。",al={"林格","林格是谁","地精林格"}},{q="林格在哪里？",a="他正在安戈洛环形山中央的火羽山半山腰处，一座朝南的洞穴里休息。",al={"林格位置","林格在哪里","寻找林格"}},{q="谁在寻找林格？",a="他的好友斯普拉格·弗劳克驻留在安戈洛环形山北部的马绍尔营地，对林格的失踪深感忧虑。",al={"斯普拉格是谁","林格的朋友","斯普拉格·弗劳克"}},{q="为什么下山时总是昏倒？",a="火羽山活火山的高温和烟气让林格严重热衰竭并脱水。每次他昏过去，都需要用斯普拉格的水壶把他弄醒。",al={"林格为什么昏倒","林格昏迷","林格倒下"}},{q="林格的袋子是什么？",a="那是林格的随身背包，他因酷热倒下时，把它丢在了洞口外，随后才退进洞里。",al={"林格的袋子","林格背包","林格遗失的背包"}},{q="林格需要去哪里？",a="他需要有人安全地护送他离开火山，穿过环形山底部，前往马绍尔营地，他的好友斯普拉格·弗劳克正在那里等他。",al={"林格要带到哪里","林格目的地","林格护送终点"}}},fp="5,223,32.412.0,31.346.1,13.123.0,23.101.0,25.119.0,35.157.0,21.119.0,28.130.0"}
P.entries["npc:rivern-frostwind"] = {n="雷沃·霜翼",s="雷沃·霜翼是一位暗夜精灵骑术训练师，驻守在冬泉谷北部的霜刀石顶。他与霜刃虎伙伴冰川一同守护当地的冬刃豹，并训练那些得到他所属组织认可的骑手。唯有最为坚定不懈的联盟勇士，才有幸骑上他珍视的坐骑。",h="雷沃·霜翼是一位暗夜精灵骑术训练师，驻守在冬泉谷北部的霜刀石顶。他与霜刃虎伙伴冰川一同守护当地的冬刃豹，并训练那些得到他所属组织认可的骑手。唯有最为坚定不懈的联盟勇士，才有幸骑上他珍视的坐骑。",kw={"霜刀石","冰川","坐骑训练师","雷沃·霜翼","冬刃豹训练师","冬泉谷霜刃豹"},ang={["faction:Alliance"]="对联盟而言，雷沃·霜翼是稀有坐骑Winterspring Frostsaber的唯一提供者，让达纳苏斯以外的骑手也能凭借坚持不懈的努力，驯服卡利姆多最凶猛的野兽之一。",["race:NightElf"]="夜刃豹与Elune的祭司和卡利姆多的哨兵有着深厚的联系，而雷沃·霜翼的霜刃豹则属于适应了环境的独居血脉，专为冬泉谷严酷的冰雪环境培育而成。"},sec={{t="霜刃豹之主",b="雷沃·霜翼身处霜刀石冰封的高崖，负责繁育和照料传说中的冬泉谷霜刃豹。夜刃豹漫步于泰达希尔和灰谷的葱郁森林，而它们生活在亚寒带的近亲则被培育得能够抵御卡利姆多北部的严寒。雷沃·霜翼为这些威严的掠食者把关。他要求外来者证明自己愿意守护这些野兽——从苔原采集鲜肉，清剿冬泉熊怪，击退肆虐的冰霜巨人——之后，他才会考虑将一头霜刃豹托付给他们。"}},faq={{q="雷沃·霜翼是谁？",a="雷沃·霜翼是一位暗夜精灵骑术大师，也是冬刃豹训练师阵营的看护者，驻守在冬泉谷北部的霜刀石。他与忠诚的老虎冰川一起，确保当地这些强大的大型猫科猛兽得到保护和妥善养育。",al={"雷沃·霜翼背景故事","霜刃豹训练师","雷沃·霜翼是谁"}},{q="他为什么会在冬泉谷？",a="他住在霜刀石，训练并保护这一带稀有的白色霜刃豹。这些掠食者不断受到凶暴的冬泉熊怪、步步进逼的巨人和恶劣环境的威胁，因此雷沃·霜翼在此维持秩序，照料它们。",al={"雷沃·霜翼为何在此","霜刀石的用途"}},{q="部落玩家能与雷沃·霜翼合作吗？",a="不能。雷沃·霜翼只忠于暗夜精灵和联盟。来到霜刀石的部落旅者会发现，他完全不愿与他们打交道，只将信任和坐骑训练留给联盟勇士。",al={"部落能否获得冬刃豹","雷沃·霜翼是否对部落友善"}},{q="他身旁的老虎是谁？",a="在雷沃·霜翼身旁休息的霜刃虎名叫冰川，是他的伙伴，也是冬泉谷苔原上土生土长的强健猫科猛兽中的佼佼者。",al={"冰川是谁","雷沃·霜翼的老虎"}}},fp="16,206,25.452.0,24.212.0,26.247.0,35.191.0,28.147.0"}
P.entries["npc:roetten-stonehammer"] = {n="罗顿·石锤",s="在铁炉堡的探险者大厅，罗顿·石锤为寻物公司.组织远征。他雇用冒险者，前往凄凉之地等遥远的土地回收物资。",h="在铁炉堡的探险者大厅，罗顿·石锤为寻物公司.组织远征。他雇用冒险者，前往凄凉之地等遥远的土地回收物资。",kw={"凄凉之地","探险者大厅","铁炉堡","图书馆","寻物公司","罗顿·石锤","回收"},ang={["faction:Alliance"]="身为联盟的一员，你可以去铁炉堡找罗顿，参加跨海远征，前往卡利姆多的凄凉之地。",["race:Dwarf"]="身为矮人，你可以在铁炉堡宏伟的档案馆里找到罗顿，那里将考古求知与商业回收结合在一起。"},sec={{t="图书馆里的生意",b="罗顿·石锤在探险者大厅的图书馆里，为寻物公司.处理回收事务。他为雇佣兵牵线，安排遍及卡利姆多的回收工作。他的同伴在凄凉之地等危险地区搜寻贵重货物、残骸和稀有材料。"}},faq={{q="罗顿·石锤是谁？",a="罗顿·石锤在铁炉堡探险者大厅的图书馆里工作。他协调远征事宜，并雇用冒险者，为寻物公司.在海外开展回收工作。",al={"罗顿是谁","罗顿·石锤是谁","罗顿·石锤的故事"}},{q="寻物公司.是什么？",a="寻物公司.在凄凉之地等危险地区回收遗失的货物，收集稀有材料，并调查有价值的残骸。",al={"寻物公司是什么","寻物公司","寻物公司的生意"}},{q="罗顿派冒险者去哪里？",a="罗顿派旅人渡海前往卡利姆多西部的凄凉之地。他的伙伴在当地崎岖的海岸和荒芜的旷野中搜寻沉船物资和材料。",al={"罗顿·石锤的任务","罗顿派人去哪里","寻物公司在凄凉之地的生意"}}},fx={c52b1d4d={q="罗顿·石锤效忠哪一方？",a="罗顿·石锤与铁炉堡和联盟结盟，在探险者大厅公开开展业务。他的商业活动，尤其是代表寻物公司.开展的业务，通过雇用可靠的旅人前往遥远而危险的土地回收遗失的资产和补给，为联盟的利益服务。",al={"罗顿·石锤是联盟还是部落","罗顿·石锤为谁效力","罗顿·石锤阵营"}},["4b23d3f4"]={q="罗顿·石锤想要什么？",a="罗顿正在寻找能干的冒险者，协助寻物公司.进行海外打捞和回收作业。他将雇来的人手派往凄凉之地荒芜海岸等危险的荒野，希望找回失落货物中的物资，并收集同伴工作所需的奇异试剂。",al={"罗顿·石锤在寻找什么","罗顿·石锤的动机","罗顿·石锤为什么需要帮助"}},f41f4afa={q="罗顿·石锤为什么在这里？",a="你可以在铁炉堡探险者大厅内宏伟的图书馆中找到四处踱步的罗顿。他以此为据点，查阅古代档案，与其他学者和勘探员保持密切联系，并招募途经矮人首都的勇敢探险者。",al={"罗顿为什么在铁炉堡","罗顿在探险者大厅做什么","罗顿·石锤 图书馆"}}},fp="19,170,23.264.0,27.167.0,24.133.0,36.166.0"}
P.entries["npc:rorian-the-dayseeker"] = {n="Rorian the Dayseeker",s="Rorian the Dayseeker是泽风岛森达尔村的一位Skyborne长者。他负责引导年轻的雏鸟入门，帮助他们发现自己的使命，迈向成年，并与故乡的自然元素建立共鸣。在他的悉心指导下，新人学习生存的基本技能、传统以及为族群服务的职责。",h="Rorian the...",kw={"逐日者","雏鸟","导师","罗瑞安","天行者","森达尔","泽弗拉斯"},ang={["class:Mage"]="初学奥术的人能在Rorian这里找到一位善解人意的引路人，他会指引初出茅庐的奥术学者，去寻找能够磨炼其魔法潜能的老师。",["class:Shaman"]="Rorian十分重视岛屿的和谐，会派雏鸟去安抚躁动的元素生物，并与祖先的传统建立联系。",["class:Warrior"]="Rorian认可那些立志投身战斗者在体魄锻炼上的付出，会为有志成为战士的人指明导师，让他们学习战场上的纪律。",["race:Skyborne"]="对每一位Skyborne雏鸟而言，Rorian the Dayseeker都是迈入职责与传统的第一道门槛，在森达尔村引导你走向成年。"},sec={{t="森达尔村的长者",b="在泽风岛宁静的森达尔村，Rorian the Dayseeker是Skyborne雏鸟的主要导师之一。Rorian凭借丰富的阅历和沉稳的智慧备受敬重，引导年轻人度过迈向成年的关键时期。在他的教导下，初学者完成传统的成年试炼，证明自己已准备好守护和支持这片海岛家园。"},{t="指引新的使命",b="除了基础试炼，Rorian还会根据有潜力的初学者各自的天赋，为他们指明专精之路。无论立志成为战士、猎人、潜行者、法师、萨满祭司还是德鲁伊，雏鸟都会在Rorian的指引下，前往岛上各处寻找相应的训练师。他也会提醒他们留意扰乱岛屿和谐的元素异动，让他们牢记守护这些疾风吹拂的高地之平衡的长久职责。"}},faq={{q="逐日者罗里安是谁？",a="逐日者罗里安是一位翔天者长者领袖，位于泽风岛的森达尔村。他是新手冒险者和翔天者雏鸟的主要导师，指引他们踏上最初的试炼之路。",al={"罗瑞安是谁","罗瑞安的职责","罗瑞安做什么"}},{q="在哪里可以找到逐日者罗里安？",a="他位于森达尔村，那是翔天者在泽风岛的起始聚居地。",al={"罗瑞安在哪里","罗瑞安位置","寻找罗瑞安"}},{q="罗里安在翔天者的成年过程中扮演什么角色？",a="罗里安负责主持最初的成年试炼，标志着雏鸟迈入成年。他会考验他们的勇气与毅力，以及对岛上生活的适应程度，然后指引他们走出去，为聚居地的更多居民服务。",al={"罗瑞安成年礼","天裔试炼导师"}},{q="罗里安如何引导新学员选择职业道路？",a="新手证明自己的能力后，罗里安便会告知他们可以到哪里接受进阶训练，指引他们走上战士、猎人、潜行者、法师、萨满祭司或德鲁伊的道路。",al={"罗瑞安职业任务","罗瑞安职业选择"}},{q="罗里安为什么派冒险者去应对元素生物？",a="泽风岛周围的自然平衡很容易受到扰动。罗里安会派遣有能力的初学者调查并平息元素骚动，让森达尔村与周围的荒野保持和谐。",al={"罗瑞安元素骚动","为什么与塞弗拉斯的元素生物战斗"}},{q="疾风者艾希恩是谁？",a="疾风者艾希恩是泽风岛上的一位人物，雏鸟在逐步承担岛上职责并接受训练的过程中，会得到罗里安的指引前去拜访。",al={"艾瑟恩 罗瑞安","疾风艾瑟恩"}}},fx={["60e564c2"]={q="逐日者罗瑞安支持哪一方？",a="罗瑞安为自己的族人——泽风岛的天翔者效力。他驻扎在森达尔村，坚定地忠于岛上的居民，并致力于培养新一代天翔者，让他们走向世界，面对任何威胁家园的危险。",al={"罗瑞安的阵营","罗瑞安为谁效力","罗瑞安的效忠对象"}},ec1df735={q="逐日者罗瑞安想要什么？",a="罗瑞安一心引导初出茅庐的天翔者完成传统成年礼。他希望每位年轻学徒都能投身自己的使命——无论是武技、奥术还是自然之道，同时确保村庄免受危险的元素动乱侵扰。",al={"罗瑞安的目标","罗瑞安想做什么","逐日者罗瑞安的使命"}},c3a8f075={q="逐日者罗瑞安为何在森达尔村？",a="罗瑞安留在森达尔村，负责监督天翔者见习者的成年试炼。他在此处理岛上的事务，引导新手寻找专门的训练师，并在附近出现元素躁动时派遣能干的人手恢复平衡。",al={"罗瑞安为何在这里","罗瑞安为何在森达尔村","罗瑞安为何在此地"}}},fp="20,165,24.245.0,24.301.0,28.137.0,40.79.0,52.165.0,55.130.0,57.158.0,28.143.0"}
P.entries["npc:royal-historian-archesonus"] = {n="皇家历史学家阿克瑟努斯",s="在王座厅，皇家历史学家阿克瑟努斯为铁炉堡王室记录灾难。她是一位效力于国王麦格尼·铜须的矮人学者，记述人类北方诸王国的灾祸，也主持对矮人古代悲剧的研究，其中包括黑铁王国被烈火焚毁的遗迹。",h="在王座厅，皇家历史学家阿克瑟努斯为铁炉堡王室记录灾难。她是一位效力于国王麦格尼·铜须的矮人学者，记述人类北方诸王国的灾祸，也主持对矮人古代悲剧的研究，其中包括黑铁王国被烈火焚毁的遗迹。",kw={"阿克瑟努斯","王座厅","历史学家","铁炉堡","洛丹伦","皇家历史学家阿克瑟努斯","索瑞森"},ang={["faction:Alliance"]="身为联盟的一员，你可以阅读阿克瑟努斯对洛丹伦陷落的沉痛记述。她的著作为南方的盟友保存了这段历史，让他们了解瘟疫，以及摧毁人类北方诸王国的势力。",["race:Dwarf"]="身为矮人，你的族人在War of the Three Hammers中留下的惨痛教训，至今仍保存在铁炉堡的史料中。这些记录旨在防止铜须氏族重蹈黑铁矮人狂妄自大的覆辙。"},sec={{t="灾难的编年史家",b="皇家历史学家阿克瑟努斯在王座厅中、国王麦格尼·铜须的王座附近保管铁炉堡的史料。她的研究范围远及卡兹莫丹群山之外。她撰写了《洛丹伦的沦陷和东谷的毁灭》和《论瘟疫、诅咒和荒芜》。在这些著作中，她追溯了天灾军团对人类北方国度的摧残。她细致地记录着毁灭性魔法与政权崩溃的真相。"},{t="索瑞森的余烬",b="皇家历史学家阿克瑟努斯主持对三锤之战以及索瑞森毁灭往事的研究。她寻找燃烧平原上索瑞森废墟中的遗物与烧焦的石板，并派遣冒险者前去搜寻。她的研究探究了那场烧焦燃烧平原、令黑铁氏族受制于火焰之王的浩劫。"}},faq={{q="在哪里可以找到皇家历史学家阿克瑟努斯？",a="皇家历史学家阿克瑟努斯位于铁炉堡的王座厅，就在国王麦格尼·铜须的王座厅附近。",al={"阿克瑟努斯位置","皇家历史学家阿克瑟努斯在哪里","阿克瑟努斯铁炉堡"}},{q="皇家历史学家阿克瑟努斯写过哪些书？",a="皇家历史学家阿克瑟努斯撰写了《洛丹伦的沦陷与东部原野的肃清》和《关于瘟疫、诅咒与凋零》。她的著作记录了人类北方诸国的覆灭，以及天灾军团传播的死灵疫病。",al={"阿克瑟努斯著作","阿克瑟努斯写过什么","阿克瑟努斯背景书籍"}},{q="阿克瑟努斯为什么对索瑞森废墟感兴趣？",a="皇家历史学家阿克瑟努斯研究矮人的古代历史，并派遣斥候深入燃烧平原，从索瑞森废墟找回失落的遗物。她希望拼凑出摧毁黑铁古都的那场灾难的始末。",al={"阿克瑟努斯的索瑞森任务","她为什么要寻找索瑞森废墟","索瑞森废墟"}},{q="她在铁炉堡担任什么职务？",a="皇家历史学家阿克瑟努斯是铁炉堡的官方皇家历史学家，也是国王麦格尼·铜须的首席编年史家和档案管理员。她编纂矮人古代历史的记录，也记载威胁联盟的各地大事。",al={"阿克瑟努斯头衔","皇家历史学家做什么","阿克瑟努斯是谁"}}},fx={d5335835={q="皇家历史学家阿克瑟努斯效忠哪一方？",a="皇家历史学家阿克瑟努斯为国王麦格尼·铜须和铁炉堡王国效力，坚定地站在联盟一方。她驻留在王座厅内，通过学术研究和档案考证，帮助王室了解矮人的古代历史、周边土地，以及始终威胁着王国的隐患。",al={"阿克瑟努斯 阵营","阿克瑟努斯为谁效力","阿克瑟努斯属于联盟吗"}},["48b31094"]={q="皇家历史学家阿克瑟努斯为什么在王座厅？",a="阿克瑟努斯留在王座厅，是因为这里是铁炉堡的政务中心，也是国王麦格尼·铜须的王座所在。身为皇家历史学家，她在矮人领袖身旁研究档案，为王室提供建议，并委托冒险者寻找遗物和被遗忘的历史。",al={"阿克瑟努斯为什么在王座厅","阿克瑟努斯 所在地点 原因","皇家历史学家阿克瑟努斯为什么在这里"}},["3b340abe"]={q="皇家历史学家阿克瑟努斯与谁有关联？",a="阿克瑟努斯直接隶属于国王麦格尼·铜须在铁炉堡的王室。凭借学者的身份，她跻身国王信赖的顾问和史官之列，记录东部王国各地发生的重大灾难，并从黑铁氏族遗迹等古代废墟中寻找实物证据。",al={"阿克瑟努斯 关联","阿克瑟努斯为谁工作","阿克瑟努斯 关系"}}},fp="26,303,25.415.0,23.362.0,44.107.0,48.230.0,56.243.0,30.214.0"}
P.entries["npc:ruga-ragetotem"] = {n="鲁迦·狂暴图腾",s="在陶拉祖营地，鲁迦·狂暴图腾为部落训练战士。他让战士们在南贫瘠之地对抗异种虫，接受考验，再指引通过考验的人去获取量身打造的护甲。",h="在陶拉祖营地，鲁迦·狂暴图腾为部落训练战士。他让战士们在南贫瘠之地对抗异种虫，接受考验，再指引通过考验的人去获取量身打造的护甲。",kw={"陶拉祖营地","巨人旷野","鲁迦·狂暴图腾","异种虫","陶拉祖","索恩格瑞姆·火眼","战士的考验"},ang={["class:Warrior"]="身为战士，你要迎战异种虫，证明自己的本领，然后鲁迦才会派你去找索恩格瑞姆·火眼锻造护甲。",["race:Tauren"]="身为牛头人，你在陶拉祖营地找到鲁迦·狂暴图腾，他以Earthmother子嗣的力量与警觉守卫着南方的原野。"},sec={{t="陶拉祖营地的导师",b="在陶拉祖营地，鲁迦·狂暴图腾训练着那些想在卡利姆多证明自身实力的战士。异种虫突然出现在南方，在巨人旷野挖掘虫巢。鲁迦派年轻的战士去猎杀这些虫类生物，割下它们的触角。经受住考验的人会赢得他的尊重，并获得他的推荐，前去拜访著名的铸甲师索恩格瑞姆·火眼。"}},faq={{q="鲁迦·狂暴图腾是谁？",a="鲁迦·狂暴图腾在南贫瘠之地的陶拉祖营地训练战士。他考验那些希望向部落证明自己的战士。",al={"鲁迦是谁","鲁迦·狂暴图腾的故事","鲁迦 陶拉祖"}},{q="鲁迦会给战士什么考验？",a="鲁迦派战士南下巨人旷野，与新近出现的异种虫作战。他们必须杀死这些凶猛的虫类生物，带回触角，以证明自己的勇气和战斗技巧。",al={"鲁迦的考验","巨人旷野的考验","鲁迦想要什么"}},{q="通过考验后，鲁迦会派你去找谁？",a="战士在与异种虫的战斗中证明自己后，鲁迦便会派他们北上，去找兽人铸甲师索恩格瑞姆·火眼。他为配得上这份荣誉的战士打造专用护甲。",al={"鲁迦之后去哪里","鲁迦的后续任务","索恩格瑞姆 鲁迦"}},{q="鲁迦为什么关注巨人旷野？",a="异种虫最近入侵了巨人旷野，在地下挖掘虫巢。鲁迦利用近在咫尺的威胁，考验那些将来可能保卫部落的战士。",al={"为什么是巨人旷野","鲁迦 虫子","异种虫 陶拉祖"}}},fp="14,160,24.362.0,22.132.0,38.200.0,42.168.0,46.155.0"}
P.entries["npc:rutgar-glyphshaper"] = {n="鲁特加尔·雕石",s="鲁特加尔·雕石是一位矮人考古学家，驻扎在希利苏斯南部的铜须营地。作为布莱恩·铜须探险队的一员，他研究古老的异种虫遗物和符文，即使布莱恩独自走入沙漠后，他仍努力揭开虫巢的秘密。",h="鲁特加尔·雕石是一位矮人考古学家，驻扎在希利苏斯南部的铜须营地。作为布莱恩·铜须探险队的一员，他研究古老的异种虫遗物和符文，即使布莱恩独自走入沙漠后，他仍努力揭开虫巢的秘密。",kw={"布莱恩","铜须","水晶","符文","雕石","玛尔利斯","雷戈","鲁特加尔","希利苏斯"},ang={["faction:Alliance"]="联盟冒险者能在这片严酷的南部沙漠中找到一处难得的友善据点，尽管鲁特加尔的队伍没有得到铁炉堡王室的正式支持。",["race:Dwarf"]="矮人们会认同鲁特加尔对探险者协会的执着奉献，他为了探寻古老知识，不惜冒着生命危险深入敌意重重的虫巢。"},sec={{t="铜须探险队",b="鲁特加尔·雕石在布莱恩·铜须的带领下来到希利苏斯，调查庞大的异种虫虫巢，发掘埋藏在荒漠之下的失落遗物。鲁特加尔和同伴们在塞纳里奥要塞以南的铜须营地建立据点，经常直接深入虫巢，采集刻有铭文的石块和符文器物，并时常与塞纳里奥的暗夜精灵研究者合作。"},{t="虫巢中的变故",b="在与暗夜精灵女祭司纳塔莉亚玛尔利斯一同深入雷戈虫巢的探险中，队伍发现了一块刻有奇异符文的水晶。这件遗物让纳塔莉亚陷入恍惚，矮人们不得不将她抬出虫巢，送往塞纳里奥要塞接受治疗。后来，她狂乱地返回矮人营地，执意要求重返虫巢，鲁特加尔和探险队被迫在一场拼死的混战中将她击退，随后她逃回了沙丘。"},{t="解读异种虫符文",b="布莱恩·铜须又像往常一样，神秘地消失在荒漠中，鲁特加尔则留在营地继续研究。他专注于收集水晶拓片，解读散布在异种虫虫巢中的虫形符文，试图拼凑出虫巢的历史，并追查布莱恩可能去了哪里。"}},faq={{q="鲁特加尔·雕石是谁？",a="他是一位探险家和学者，曾随布莱恩·铜须前往希利苏斯进行考古探险，目前驻扎在铜须营地。",al={"鲁特加尔","鲁特加尔是谁","鲁特加尔·雕石资料"}},{q="布莱恩·铜须在哪里？",a="布莱恩又一次像往常那样独自外出侦察，走进了希利苏斯的荒漠，留下鲁特加尔和其余队员维持营地并研究虫巢。",al={"布莱恩在哪里","布莱恩去了哪里","布莱恩失踪"}},{q="纳塔莉亚玛尔利斯在营地发生了什么事？",a="受到雷戈虫巢中一块古老水晶的影响后，纳塔莉亚玛尔利斯狂怒地返回铜须营地，袭击了鲁特加尔、布莱恩和其他队员，随后再次消失在沙漠中。",al={"纳塔莉亚发生了什么事","纳塔莉亚袭击","女祭司袭击营地"}},{q="鲁特加尔为什么研究异种虫水晶？",a="鲁特加尔正试图解读虫巢内水晶上刻着的古老符文，希望了解异种虫的起源，并找到有关布莱恩下落的线索。",al={"为什么研究符文","鲁特加尔在研究什么","符文水晶"}},{q="铁炉堡向探险队派出援军了吗？",a="没有。探险队曾请求铁炉堡提供军事支援，但矮人王国拒绝了，声称现有兵力在保卫王国上已捉襟见肘。",al={"铁炉堡援军","铁炉堡军队希利苏斯"}},{q="铜须营地在哪里？",a="铜须营地位于希利苏斯南部，坐落在塞纳里奥要塞以南、雷戈虫巢以西不远处的沙漠中。",al={"铜须营地在哪里","营地位置"}}},fp="18,286,26.377.0,20.360.1,24.281.1,26.153.0,27.173.0,47.203.1,45.166.0,41.161.0,44.105.0"}
P.entries["npc:ruul-eagletalon"] = {n="卢尔·鹰爪",s="在血蹄村，卢尔·鹰爪守望着村落的边界。他留意着莫高雷的野生动物，尤其是那些不断侵入牛头人领地、好勇斗狠的风怒鹰身人。",h="在血蹄村，卢尔·鹰爪守望着村落的边界。他留意着莫高雷的野生动物，尤其是那些不断侵入牛头人领地、好勇斗狠的风怒鹰身人。",kw={"血蹄","鹰爪","鹰身人","莫高雷","卢尔","风怒"},ang={["race:Tauren"]="身为牛头人，你知道，要保护莫高雷免受领地意识强烈的掠食者和有翼袭击者的侵扰，就必须时刻保持警惕。"},sec={{t="血蹄村的守望者",b="年轻的勇士们从纳拉其营地来到血蹄村，卢尔·鹰爪负责守护这里的安全。莫高雷是一片宁静的家园，毗邻贫瘠之地的干旱荒野，但领地意识强烈的掠食者和充满敌意的生物仍在不断逼近这里的牧场。卢尔留意着附近平原上的危险，并指引有能力的旅者对付凶残的风怒鹰身人，它们会捕杀疏于防备的游牧者和猎物。"}},faq={{q="卢尔·鹰爪是谁？",a="卢尔·鹰爪守护着血蹄村，并指引旅者应对莫高雷各处的威胁。",al={"卢尔是谁","卢尔·鹰爪非玩家角色","血蹄村卢尔"}},{q="卢尔·鹰爪请旅者应对什么威胁？",a="卢尔提醒旅者提防莫高雷那些好勇斗狠的风怒鹰身人，并请有能力的勇士削减它们的数量，以免它们危害村庄。",al={"卢尔任务","风怒的危险","莫高雷鹰身人任务"}},{q="在哪里可以找到卢尔·鹰爪？",a="卢尔·鹰爪就在莫高雷中部、石牛湖畔的血蹄村内。",al={"卢尔·鹰爪位置","寻找卢尔","卢尔在哪"}}},fp="15,171,20.362.0,23.100.0,60.140.0,35.117.0"}
P.entries["npc:ruul-snowhoof"] = {n="鲁尔·雪蹄",s="在灰谷北部深处，鲁尔·雪蹄正等待救援。这位牛头人德鲁伊以熊形态被困在蓟皮要塞的一只简陋牢笼里，只能指望部落冒险者将他释放，并护送他脱离险境。",h="在灰谷北部深处，鲁尔·雪蹄正等待救援。这位牛头人德鲁伊以熊形态被困在蓟皮要塞的一只简陋牢笼里，只能指望部落冒险者将他释放，并护送他脱离险境。",kw={"熊形态","释放鲁尔","鲁尔·雪蹄","碎木岗哨","蓟皮熊怪","蓟皮要塞","雅玛·雪蹄"},ang={["class:Druid"]="身为德鲁伊，发现鲁尔以熊形态被囚禁在笼中，便能看出腐化正在灰谷的野生动物和熊怪部族间蔓延。",["race:Tauren"]="身为牛头人，救出鲁尔·雪蹄，就能让雪蹄家族的一员活着回到碎木岗哨，与妹妹雅玛团聚。"},sec={{t="笼中之熊",b="鲁尔·雪蹄进入灰谷北部后，落入了堕落的蓟皮熊怪手中。他变成了一头熊，俘虏他的熊怪误以为他是野兽。它们没有杀他，而是把他关进了蓟皮要塞深处的一只木笼。如今，鲁尔身体虚弱，既无法安全地解除变形，也无法独自杀出重围，只能等待部落盟友打开牢笼，赶走俘虏他的熊怪，并在巢穴中清出一条道路。他希望回到碎木岗哨，与妹妹雅玛·雪蹄团聚。"}},faq={{q="鲁尔·雪蹄为什么变成熊被关在笼子里？",a="鲁尔·雪蹄遭遇蓟皮熊怪时，变成了熊形态。它们误以为这位牛头人德鲁伊是野兽，把他关进了据点深处的一只牢笼。",al={"鲁尔为什么是熊","鲁尔·雪蹄熊形态","他为什么被关在笼中"}},{q="熊怪为什么不直接杀死鲁尔？",a="蓟皮熊怪将熊形态的鲁尔囚禁起来，任由他在笼中慢慢挨饿。它们为何选择这样做，而不是杀死他，原因尚不清楚。",al={"为什么让鲁尔挨饿","熊怪想对鲁尔做什么"}},{q="鲁尔逃出蓟皮要塞后会去哪里？",a="鲁尔逃出蓟皮要塞后，请求救援者告诉妹妹雅玛·雪蹄，他还活着。她就在碎木岗哨。",al={"鲁尔去哪里","鲁尔·雪蹄目的地"}},{q="联盟玩家能与鲁尔·雪蹄互动吗？",a="不能。鲁尔·雪蹄效忠部落，只会向找到他牢笼的部落冒险者寻求脱身的帮助。",al={"鲁尔是否仅限部落","联盟鲁尔·雪蹄"}}},fp="13,173,16.495.0,38.168.0,38.134.0,50.136.0,49.109.0"}
P.entries["npc:rwag"] = {n="鲁瓦格",s="在大兽穴，鲁瓦格传授潜行者技艺的入门知识。这位兽人在部落的监管下，在杜隆塔尔的试炼谷训练初来乍到的兽人和巨魔，教他们潜行、诡计和卑鄙的战斗手段。",h="在大兽穴，鲁瓦格传授潜行者技艺的入门知识。这位兽人在部落的监管下，在杜隆塔尔的试炼谷训练初来乍到的兽人和巨魔，教他们潜行、诡计和卑鄙的战斗手段。",kw={"杜隆塔尔","纳托克","潜行者","鲁瓦格","大兽穴","训练师","试炼谷"},ang={["class:Rogue"]="作为试炼谷中一名年轻的兽人或巨魔潜行者，你会遇见鲁瓦格，他是你学习诡诈手段的第一位导师。他传授基础的进攻技巧，也教你如何破译秘密暗码。",["race:Orc"]="身为兽人，你能从鲁瓦格身上看到求生之道中务实的一面。即便在萨尔崇尚荣誉的新部落中，暗影与冰冷的利刃依然至关重要。"},sec={{t="谷中暗影",b="在大兽穴深处，鲁瓦格训练初出茅庐的潜行者、扒手和窃贼，之后他们才会走出洞穴，踏入杜隆塔尔。新生的部落崇尚武者的荣誉和战场上的勇气，但鲁瓦格知道，在这片严酷的沙漠中，诡计、毒药和刺向要害的匕首依然是求生的利器。他留意着谷中的动向，不信任那些栖身洞中的黑暗法术修习者，尤其是术士纳托克。"}},faq={{q="鲁瓦格是谁？",a="鲁瓦格在试炼谷的大兽穴内训练兽人和巨魔潜行者。他在他们刚开始于杜隆塔尔接受训练时传授技艺。",al={"鲁瓦格是谁","鲁瓦格 试炼谷","兽人潜行者训练师"}},{q="在哪里能找到鲁瓦格？",a="鲁瓦格就在大兽穴深处，这座洞穴位于杜隆塔尔试炼谷的岩壁之中。那里还有几位其他职业的训练师。",al={"鲁瓦格位置","鲁瓦格在哪里","寻找鲁瓦格"}},{q="鲁瓦格如何看待大兽穴里的术士？",a="鲁瓦格不信任同住大兽穴的术士，尤其是纳托克。他密切监视着这名术士。",al={"鲁瓦格 纳托克","鲁瓦格为何不信任术士","鲁瓦格 密文羊皮纸"}},{q="鲁瓦格训练哪些职业？",a="鲁瓦格向潜行者传授刺骨等入门技巧。应碎手氏族的要求，他留意着新兵，并将碎手氏族可能需要了解的情况传递过去。",al={"鲁瓦格教什么","鲁瓦格能训练我吗"}}},fp="4,214,21.421.0,12.141.0,22.148.0,48.97.0,30.181.0"}
P.entries["npc:saelienne"] = {n="Saelienne",s="在达纳苏斯的工匠区，塞琳尼为旅人与工匠经营着一家旅店。她在这座暗夜精灵都城提供食物、饮品，以及绑定 炉石 的地方。",h="在达纳苏斯的工匠区，塞琳尼为旅人与工匠经营着一家旅店。她在这座暗夜精灵都城提供食物、饮品，以及绑定 炉石 的地方。",kw={"工匠区","达纳苏斯","万圣节","炉石","旅店老板","塞琳尼","泰达希尔"},ang={["faction:Alliance"]="作为前往泰达希尔的联盟使者或工匠，你可以在塞琳尼的旅店找到食物、饮品，以及温暖的炉边栖身之所。",["race:NightElf"]="作为从泰达希尔荒野归来的暗夜精灵冒险者，你可以在达纳苏斯工匠们聚集的塞琳尼旅店找到熟悉的炉火。"},sec={{t="工匠区的款待",b="旅店老板塞琳尼欢迎居民和访客光临她位于达纳苏斯工匠区的旅店。她为旅人提供安静的休憩之所，供应暗夜精灵的茶点和经由城市港口运来的货物。工匠们在熔炉或织机旁忙碌许久后，会来到这里。塞琳尼的旅店为他们提供了相聚和恢复精力的地方。"}},faq={{q="在哪里可以找到旅店老板塞琳尼？",a="你可以在达纳苏斯的工匠区找到塞琳尼，她就在专业训练师和工艺店铺之间。",al={"塞琳尼 位置","塞琳尼 在哪里","达纳苏斯旅店老板位置","工匠区旅店"}},{q="塞琳尼提供哪些服务？",a="塞琳尼提供食物和饮品，还能让你将 炉石 绑定在达纳苏斯。",al={"塞琳尼 做什么","塞琳尼 商人","绑定 炉石 达纳苏斯"}},{q="塞琳尼提供季节性任务吗？",a="在万圣节期间，塞琳尼向联盟冒险者提供跳跳舞，换糖果任务，让他们换取节日糖果。",al={"塞琳尼 任务","万圣节 塞琳尼","跳跳舞，换糖果"}}},fp="9,180,26.280.0,37.108.0,37.81.0,40.111.0"}
P.entries["npc:sally-whitemane"] = {n="大检察官怀特迈恩",s="怀特迈恩是血色十字军的大检察官，执掌血色修道院的大教堂。她是一位强大的圣光女祭司，对亡灵刻骨铭心的仇恨推动着十字军毫不妥协的狂热行径。她与血色指挥官雷诺莫格莱尼一同领导着教团在洛丹伦各地的军事行动与思想斗争。",h="怀特迈恩是血色十字军的大检察官，执掌血色修道院的大教堂。她是一位强大的圣光女祭司，对亡灵刻骨铭心的仇恨推动着十字军毫不妥协的狂热行径。她与血色指挥官雷诺莫格莱尼一同领导着教团在洛丹伦各地的军事行动与思想斗争。",kw={"大教堂","大检察官","虔诚的莱雷恩","雷诺·莫格莱尼","莎莉·怀特迈恩","血色十字军","血色修道院","怀特迈恩"},ang={["class:Paladin"]="在白银之手的圣骑士看来，怀特迈恩的统治体现了洛丹伦守护者令人痛心的堕落，他们抛弃了仁慈与正义，转而进行不分青红皂白的清洗。",["class:Priest"]="怀特迈恩展现了圣光与顽固的狂热结合时所具有的可怕力量，警示着人们，坚定的信念也可能化为狂热的残忍。",["faction:Alliance"]="尽管怀特迈恩曾是洛丹伦的联盟子民，如今她麾下的十字军却会攻击任何接近其领地的外来者，迫使南海镇的忠诚之士直面昔日同胞化作的怪物。",["race:Undead"]="在被遗忘者看来，怀特迈恩体现了十字军拒绝区分无脑的 Scourge 与拥有自由意志的亡灵的立场，因此，消灭她对幽暗城的存续至关重要。"},sec={{t="十字军的大检察官",b="怀特迈恩在血色十字军中迅速晋升，成为大检察官，并接管了血色修道院宏伟的大教堂。她以对神圣魔法令人畏惧的掌控力闻名，凭借绝对坚定的信念，成为十字军最重要的象征之一，将圣光化为毫不留情的武器，对付一切被视为不洁的存在。"},{t="大教堂中的目标",b="到了 黑暗之门开启后二十五年，怀特迈恩的狂热已为她招来了双方阵营的敌人。在南海镇，虔诚的莱雷恩认为十字军已深陷腐化与疯狂，无可挽回，因此呼吁除掉怀特迈恩和莫格莱尼，恢复教团创立时的美德。与此同时，在幽暗城内，恐惧魔王瓦里玛萨斯正策划对修道院的袭击，要粉碎这群在被遗忘者家门口活动的狂热分子。"}},faq={{q="大检察官怀特迈恩是谁？",a="怀特迈恩是血色十字军的大检察官。她坐镇提瑞斯法林地血色修道院内的大教堂，统领教团的精神教化与审判事务，并与指挥官雷诺莫格莱尼并肩作战。",al={"怀特迈恩 背景故事","大检察官怀特迈恩是谁","血色修道院首领"}},{q="怀特迈恩为何如此憎恨亡灵？",a="她的仇恨正是血色十字军自身信条的体现。教团由洛丹伦沦陷于亡灵瘟疫后的幸存者建立，将所有亡灵都视为必须净化的怪物，无论其毫无心智还是拥有自由意志。在这场战争中，怀特迈恩挥动圣光，使之成为教团最无情的武器。",al={"怀特迈恩 为何憎恨 天灾军团","怀特迈恩 身世","怀特迈恩 家族"}},{q="联盟为何想要怀特迈恩死？",a="南海镇的虔诚的莱雷恩曾是十字军的一员，他认为血色十字军已堕入猜忌与疯狂之中。他请求联盟的勇士除掉怀特迈恩和莫格莱尼，让教团有机会重拾最初的荣耀。",al={"虔诚的莱雷恩 怀特迈恩","联盟为何要杀 怀特迈恩","以圣光之名 任务"}},{q="部落为何想要怀特迈恩死？",a="幽暗城的瓦里玛萨斯和被遗忘者将血色十字军视为一股就在首都之外积极活动的敌对势力。这位恐惧魔王下令杀死她，以摧毁修道院的领导层，消除对被遗忘者领地的直接威胁。",al={"瓦里玛萨斯 怀特迈恩 任务","深入血色修道院","部落为何要杀 怀特迈恩"}},{q="怀特迈恩与雷诺莫格莱尼是什么关系？",a="怀特迈恩与雷诺莫格莱尼是血色修道院的两位领袖。他们在大教堂中并肩作战，彼此关系亲密，也同样献身于十字军对亡灵的征伐。",al={"怀特迈恩 与 莫格莱尼","指挥官 莫格莱尼 与 怀特迈恩"}}},fx={f63bdc05={q="大检察官怀特迈恩站在哪一方？",a="怀特迈恩是血色十字军狂热的领袖，担任大检察官一职。她不效忠于联盟或部落，对外来者抱有极度的猜疑和狂热的敌意。怀特迈恩坚定地信奉十字军的教条，与指挥官雷诺·莫格莱尼并肩作战，肃清所有挡在他们道路上的人。",al={"怀特迈恩的阵营","怀特迈恩为谁而战","怀特迈恩效忠谁"}},["89d62c4b"]={q="大检察官怀特迈恩想要什么？",a="怀特迈恩渴望彻底根除亡灵。和血色十字军的其他成员一样，她把每个亡灵都视为憎恶之物，无论是没有心智的天灾亡灵，还是拥有自由意志的被遗忘者。只有肃清天灾以及她认定受到亡灵污染的人，她才能找到使命。",al={"怀特迈恩的目标","怀特迈恩想要什么","怀特迈恩的动机"}},["04c4cc89"]={q="大检察官怀特迈恩为什么在这里？",a="作为大检察官，怀特迈恩在血色修道院大教堂深处指挥血色十字军的行动。她在那里统领他们对洛丹伦北部庇护所的防御，鼓舞十字军战士，并肃清所有擅闯圣地要塞的人。",al={"怀特迈恩为什么在修道院","怀特迈恩在大教堂的原因","怀特迈恩为什么在这里"}},["7daae460"]={q="大检察官怀特迈恩为何声名远扬或令人畏惧？",a="怀特迈恩因其毫不动摇的狂热信念和强大的神圣魔法造诣而令人畏惧。身为血色十字军的大检察官，她以残酷肃清疑似腐化者而声名可怖，还能在战斗中复活倒下的盟友，包括指挥官莫格莱尼。",al={"怀特迈恩为何令人畏惧","怀特迈恩的名声","怀特迈恩为何声名远扬"}}},fp="25,304,30.321.0,24.417.1,33.228.0,43.280.0,42.235.0,39.252.0,55.195.0"}
P.entries["npc:salma-saldean"] = {n="萨尔玛·萨丁",s="在萨丁农场，萨尔玛·萨丁欢迎旅人到来，并为帮忙料理农庄的人提供饭食。她和丈夫农夫萨丁照料着他们在西部荒野的农场，而匪徒正威胁着各处农场，暴风城也已撤离这片地区。",h="在萨丁农场，萨尔玛·萨丁欢迎旅人到来，并为帮忙料理农庄的人提供饭食。她和丈夫农夫萨丁照料着他们在西部荒野的农场，而匪徒正威胁着各处农场，暴风城也已撤离这片地区。",kw={"农夫萨丁","猪肝馅饼","萨丁农场","萨尔玛·萨丁","炖菜","西部荒野","杂味炖肉"},ang={["faction:Alliance"]="萨尔玛展现了联盟农户的顽强意志，即使遭到王室忽视，仍坚守着自己的生计。",["profession:Cooking"]="萨尔玛·萨丁为途经西部荒野的厨师提供实用食谱，包括用当地野生动物制作的杂味炖肉和猪肝馅饼。",["race:Human"]="身为人类旅者，可以从萨尔玛的农场窥见暴风城平民在都城坚固城墙之外所承受的艰辛。"},sec={{t="艰苦之地的热情款待",b="萨尔玛·萨丁在农场迎接旅人，周围的农庄有的被烧毁，有的落入迪菲亚潜行者之手，这座农场却坚持了下来。炉上炖着满满一锅食物，她也在寻找能干的人手，帮忙料理农庄。"},{t="让餐桌上有饭吃",b="萨尔玛用西部荒野出产的食材招待家人和来客。她教旅人用野猪、秃鹫、鱼人和零星采得的秋葵，制作猪肝馅饼和杂味炖肉。"}},faq={{q="萨尔玛·萨丁是谁？",a="萨尔玛·萨丁和丈夫在西部荒野中部的萨丁农场务农。在这片地区陷入衰败之际，她为旅人提供饭食与慰藉，同时努力维持农场的运转。",al={"萨尔玛是谁","萨尔玛·萨丁的故事","萨丁农场的妻子"}},{q="萨尔玛·萨丁在哪里？",a="萨尔玛就在萨丁农场的农舍外，农场位于西部荒野中部的道路旁，就在通往哨兵岭的十字路口以北不远处。",al={"萨尔玛的位置","萨尔玛·萨丁在哪里","萨丁农场在哪里"}},{q="萨尔玛·萨丁教授哪些食谱？",a="萨尔玛教旅人用西部荒野的野生动物提供的食材，制作猪肝馅饼和杂味炖肉。",al={"杂味炖肉食谱","萨尔玛的食物","猪肝馅饼"}},{q="为什么萨丁一家很难找到帮手？",a="帮手难寻，是因为农夫和劳工为了躲避四处劫掠的匪徒、失控的收割傀儡，以及暴风城王家军队缺席的局面，纷纷逃离了这里。少数留下的农户都缺乏人手。",al={"农场为何被遗弃","萨丁为何需要帮手","西部荒野农场被遗弃"}},{q="萨丁一家如何在迪菲亚潜行者的威胁下生存？",a="萨丁一家依靠过路的冒险者和自身的坚韧守护家产。尽管四周危机重重，他们仍不肯离开自己的土地与家园。",al={"萨丁与迪菲亚潜行者","农场为何没有被烧毁"}},{q="萨尔玛的丈夫是谁？",a="萨尔玛的丈夫是农夫萨丁，他与她并肩应对故障的收割看守和失控的野兽。",al={"萨尔玛的丈夫","农夫萨丁"}}},fx={["4311c40a"]={q="萨尔玛·萨丁站在哪一边？",a="萨尔玛坚定地站在西部荒野那些正直的居民和苦苦挣扎的农夫一边。她和丈夫心中忠于联盟，却得不到暴风城的援助，只能自谋生路，将全部希望寄托在邻近农户的相互扶持上。",al={"萨尔玛·萨丁阵营","萨尔玛支持谁","萨尔玛·萨丁立场"}},["31948cda"]={q="萨尔玛·萨丁想要什么？",a="萨尔玛希望维持自家农场的运转，让每个路过的人都能吃上一顿热饭，也有人愿意倾听他们的心声。困苦和匪患迫使大多数劳力离去，她急需有人帮忙收集血牙野猪的肝等食材，好养活那些仍坚守在西部荒野的人。",al={"萨尔玛想要什么","萨尔玛·萨丁目标","萨尔玛需要什么"}},f65c3c8f={q="萨尔玛·萨丁为什么在这里？",a="萨尔玛留在萨丁农场，因为这里是她的家。即便当地日益动荡，法纪荡然无存，邻近的定居者纷纷逃离，她和丈夫仍不愿放弃土地，决心继续耕作，为需要栖身之所的人带来慰藉。",al={"萨尔玛为何在西部荒野","为何留在萨丁农场","萨尔玛·萨丁为何在此"}}},fp="13,229,26.225.0,25.182.0,21.174.0,31.146.0,38.111.0,48.185.0,51.163.0,23.117.0"}
P.entries["npc:sara-balloo"] = {n="萨拉·巴鲁",s="在铁炉堡的军事区，萨拉·巴鲁哀悼着苏利，紧紧守着他留下的话语。",h="在铁炉堡的军事区，萨拉·巴鲁哀悼着苏利，紧紧守着他留下的话语。",kw={"丹莫罗","铁炉堡","麦格尼·铜须","军事区","萨拉·巴鲁","苏利·巴鲁","寡妇"},ang={["faction:Alliance"]="身为联盟士兵，你能看到消息如何为阵亡将士的家人带来慰藉。艾泽拉斯各地的战火，也伤痛着留在家中的人们。",["race:Dwarf"]="身为一名途经铁炉堡军事区的矮人，你能从萨拉·巴鲁身上看到，那些亲人守卫着卡兹莫丹的家庭承受了怎样的代价。"},sec={{t="寡妇的守候",b="萨拉·巴鲁在铁炉堡的军事区守候，那里兵器铿锵，士兵们操练不息。她的丈夫苏利·巴鲁在远离家乡的战场上阵亡，留给她的只有悲痛与回忆。一封最后的来信从他殒命之地越过群山，送到了她手中。苏利在生命最后几日写下的话语，让萨拉多少得到了一些慰藉。"},{t="祈求铭记",b="萨拉·巴鲁希望苏利的牺牲能被铭记。她恳请国王麦格尼·铜须在王座上表彰苏利和其他阵亡将士。她希望普通矮人家庭付出的代价能被铭记。"}},faq={{q="萨拉·巴鲁是谁？",a="萨拉·巴鲁住在铁炉堡的军事区。她的丈夫苏利·巴鲁是一名在战斗中阵亡的矮人士兵。",al={"萨拉·巴鲁","萨拉·巴鲁是谁","萨拉·巴鲁 铁炉堡"}},{q="在哪里可以找到萨拉·巴鲁？",a="你可以在铁炉堡的军事区找到萨拉·巴鲁，就在训练场和兵营附近。",al={"萨拉·巴鲁在哪里","萨拉·巴鲁位置","寻找萨拉·巴鲁"}},{q="她的丈夫遭遇了什么？",a="苏利·巴鲁在服役期间身亡。一名冒险者找回了他遗失的物品，以及一封被水浸透的最后来信。",al={"萨拉·巴鲁的丈夫","苏利 巴鲁是谁","苏利遭遇了什么"}},{q="萨拉如何处理苏利的信？",a="读过苏利真挚的话语后，萨拉写信给国王麦格尼·铜须，请求他表彰并铭记苏利的牺牲。",al={"苏利 巴鲁的信","萨拉·巴鲁的恳求","萨拉·巴鲁想要什么"}}},fx={["736253da"]={q="萨拉·巴鲁站在哪一边？",a="萨拉·巴鲁是铁炉堡的忠诚公民，也是联盟的拥护者。她已故的丈夫苏利·巴鲁在为矮人王国效力时牺牲，当时他的部队正在守卫萨多尔大桥，而她仍与族人一起生活在国王麦格尼·铜须的统治之下。",al={"萨拉·巴鲁阵营","萨拉·巴鲁联盟","萨拉·巴鲁为谁效力"}},["658d468d"]={q="萨拉·巴鲁为什么在军事区？",a="萨拉住在铁炉堡的军事区，与王国的士兵和老兵为邻。战争夺去了她的丈夫苏利，她仍留在这座山中城市的政务与军事中心附近，这里的人们缅怀着那些为保卫王国而牺牲的人。",al={"萨拉·巴鲁为何在铁炉堡","萨拉·巴鲁为何在此","萨拉·巴鲁军事区"}}},fp="11,98,15.322.0,21.219.1,19.119.0,29.94.0,29.138.1,38.134.1"}
P.entries["npc:sara-timberlain"] = {n="萨拉·迪博雷恩",s="在东谷伐木场，萨拉·迪博雷恩为暴风城的士兵缝制装备。她用回收的布料和皮革制作实用的军需装备。",h="在东谷伐木场，萨拉·迪博雷恩为暴风城的士兵缝制装备。她用回收的布料和皮革制作实用的军需装备。",kw={"东谷","亚麻布","伐木场","萨拉·迪博雷恩","女裁缝","暴风城军队","裁缝"},ang={["faction:Alliance"]="东谷这样的偏远定居点也在协助保卫王国。当地工匠为物资匮乏的Stormwind Army供应基础护甲。",["profession:Tailoring"]="萨拉展示了边地裁缝如何将粗糙的亚麻布碎料和强盗的布料制成实用衣物，完成军方的委托。"},sec={{t="边地的针线活",b="在东谷伐木场的西边，萨拉·迪博雷恩坐在一间小屋外做针线活。工人们砍伐树木，斧声在营地里回荡。这里远离其他有人定居的地方，附近却有狼和鱼人在游荡。萨拉依然欢迎旅人到来。\n\n她把零碎的亚麻布和回收的头巾缝成结实的装备。她的手艺得到了官方认可。暴风城的军队委托她供应布料和皮革制成的军需装备。"}},faq={{q="萨拉·迪博雷恩是谁？",a="萨拉·迪博雷恩是艾尔文森林东谷伐木场的一位熟练女裁缝。她用回收的布料制作实用的装备，并签有向暴风城军队供货的合约。",al={"萨拉·迪博雷恩是谁","萨拉·迪博雷恩","东谷裁缝"}},{q="在哪里能找到萨拉·迪博雷恩？",a="萨拉·迪博雷恩坐在东谷伐木场西侧的一间屋子外。营地位于艾尔文森林东部，坐落在通往赤脊山的道路旁。",al={"萨拉·迪博雷恩位置","萨拉·迪博雷恩在哪","迪博雷恩的房子"}},{q="萨拉为什么要为军队收集布料？",a="暴风城军队依靠当地工匠维持装备储备。萨拉用回收的布料，包括旅人收集的亚麻布，为王国的士兵制作结实的衣物和护甲内衬。",al={"萨拉为什么需要亚麻布","暴风城军队护甲","布甲和皮甲任务"}}},fx={["693a4fc8"]={q="萨拉·迪博雷恩站在哪一边？",a="萨拉效忠于暴风城王国和联盟。她驻留在东谷伐木场，直接为王国的防务出力，承接暴风城军队的裁缝订单，为士兵制作结实的护甲。",al={"萨拉·迪博雷恩阵营","萨拉·迪博雷恩为谁效力","萨拉·迪博雷恩联盟"}},["94680b13"]={q="萨拉·迪博雷恩想要什么？",a="萨拉需要制作材料，尤其是从当地匪徒手中收缴的亚麻布卷，以便继续从事裁缝工作。她将收缴来的布料制成衣物和护甲，为王国的军队提供补给，同时酬谢那些为她送来物资的旅人。",al={"萨拉·迪博雷恩需要什么","萨拉·迪博雷恩材料","萨拉为何需要亚麻布"}},["414da08e"]={q="萨拉·迪博雷恩为什么在伐木场？",a="萨拉住在东谷伐木场西侧，远离暴风城拥挤的街道，在那里经营自己的裁缝生意。这处边境哨站让她有个安静的地方做针线活，也方便她接触旅人和当地的供货者，收集她赖以谋生的回收材料。",al={"萨拉为何在东谷","萨拉·迪博雷恩东谷伐木场","萨拉·迪博雷恩为何在此"}},["59756f86"]={q="萨拉·迪博雷恩与谁有联系？",a="萨拉与暴风城军队关系密切，军方正式委托她为士兵制作布甲和皮甲。她也与驻留在东谷伐木场的当地林地居民和伐木工一起工作。",al={"萨拉·迪博雷恩关系","萨拉·迪博雷恩为谁工作","萨拉·迪博雷恩暴风城军队"}},["42dfe0df"]={q="萨拉·迪博雷恩为什么出名？",a="萨拉凭借出色的裁缝手艺闻名当地，尤其擅长将收集来的粗糙碎布制成精美的衣物和坚实的护甲，足以供王国的常备军使用。",al={"萨拉·迪博雷恩名声","萨拉·迪博雷恩是否出名","萨拉·迪博雷恩因何出名"}}},fp="15,137,26.462.0,23.178.0,33.149.0,41.212.0"}
P.entries["npc:scarlet-commander-mograine"] = {n="血色十字军指挥官莫格莱尼",s="血色十字军指挥官莫格莱尼是驻守血色修道院大教堂的军事领袖。他是血色十字军的一名狂热圣骑士，与大检察官怀特迈恩一同守卫礼拜堂。部落和联盟都将他视为目标，意图打击那些威胁提瑞斯法林地及周边地区的狂热分子。",h="血色十字军指挥官莫格莱尼是驻守血色修道院大教堂的军事领袖。他是血色十字军的一名狂热圣骑士，与大检察官怀特迈恩一同守卫礼拜堂。部落和联盟都将他视为目标，意图打击那些威胁提瑞斯法林地及周边地区的狂热分子。",kw={"大教堂","十字军礼拜堂","莫格莱尼","圣骑士","血色十字军指挥官莫格莱尼","血色十字军","血色修道院","怀特迈恩"},ang={["class:Paladin"]="莫格莱尼体现了圣骑士使命遭到腐化的悲剧，将守护与正义的神圣誓言扭曲成了冷酷而顽固的狂热。",["faction:Alliance"]="尽管血色十字军曾与联盟有过共同立场，南海镇和暴风城的领袖们已经意识到，像莫格莱尼这样的狂热指挥官早已陷入暴虐的疯狂。",["race:Undead"]="对被遗忘者而言，指挥官莫格莱尼代表着血色十字军最锋利的刀刃，这股势力就盘踞在幽暗城边境，威胁着他们在提瑞斯法的生存。"},sec={{t="礼拜堂的守卫者",b="血色十字军指挥官莫格莱尼驻守在血色修道院中心宏伟的十字军礼拜堂，统领血色十字军的常驻守军。他怀着狂热的信念，挥使圣骑士的神圣力量，依靠惩戒、神圣护盾和令人昏迷的重击，击溃一切被血色十字军视为腐化或不洁的生灵。"},{t="奇迹般的羁绊",b="莫格莱尼对礼拜堂的防守与大检察官怀特迈恩密不可分。如果进攻者将这位指挥官击倒，怀特迈恩便会从后方的内殿现身，扭转战局。她呼唤圣光，瞬间令入侵者失去行动能力，并让莫格莱尼死而复生，迫使敌人在一场殊死搏斗中同时对抗两位指挥官。"}},faq={{q="在哪里可以找到血色十字军指挥官莫格莱尼？",a="他位于提瑞斯法林地东北部的血色修道院大教堂区。你会发现他正等候在十字军礼拜堂的祭坛前。",al={"莫格莱尼位置","莫格莱尼在哪里","血色修道院莫格莱尼房间"}},{q="莫格莱尼在血色十字军中担任什么职务？",a="他是血色十字军驻修道院部队的军事指挥官，与大检察官怀特迈恩一同指挥那里的圣骑士和士兵。",al={"指挥官莫格莱尼是谁","莫格莱尼军衔","莫格莱尼的职责"}},{q="他如何作战？",a="莫格莱尼是一名重装近战圣骑士。他使用制裁之锤击昏对手，发动十字军打击，以惩戒光环护身，并在濒临绝境时依靠圣盾术自保。",al={"莫格莱尼技能","莫格莱尼战斗","如何对抗莫格莱尼"}},{q="大检察官怀特迈恩为什么要复活他？",a="怀特迈恩与莫格莱尼之间有着深厚的羁绊，两人作为修道院的领袖并肩作战。当莫格莱尼在战斗中倒下时，怀特迈恩便会出手干预，用魔法使进攻者陷入沉睡，并复活莫格莱尼，让他恢复全部力量。",al={"怀特迈恩复活莫格莱尼","莫格莱尼会复活吗","复活莫格莱尼"}},{q="联盟和部落为什么要与他作战？",a="血色十字军将所有外来者，无论生者还是亡灵，都视为腐化的传播者。联盟和被遗忘者都派出勇士进攻大教堂，处决其中的领袖，以消除血色十字军在洛丹伦的狂热势力。",al={"为什么要杀莫格莱尼","血色指挥官任务","以圣光之名"}},{q="莫格莱尼会在战斗中治疗自己吗？",a="会，在危急时刻。除了圣盾术和近战攻击，他还能施展圣疗术，将自己的生命值恢复至全满，而大检察官怀特迈恩参战后还会提供额外的治疗。",al={"莫格莱尼能治疗吗","莫格莱尼治疗"}}},fx={a3e1ab86={q="血色十字军指挥官莫格莱尼支持哪一方？",a="莫格莱尼指挥官只为血色十字军而战。血色十字军最初由洛丹伦的幸存守军和白银之手骑士团成员组成，如今却已彻底孤立。在莫格莱尼的军事指挥下，他们视所有外人——无论部落还是联盟——为染疫的污秽之物和圣光的敌人。",al={"莫格莱尼为谁而战","血色十字军指挥官莫格莱尼阵营","莫格莱尼是联盟吗"}},["741d495f"]={q="血色十字军指挥官莫格莱尼为什么在修道院？",a="血色修道院是血色十字军在提瑞斯法林地的重要据点之一。莫格莱尼驻守在大教堂内的十字军礼拜堂，与大检察官怀特迈恩一同指挥驻军防务，守卫他们神圣堡垒的核心。",al={"莫格莱尼为什么在血色修道院","莫格莱尼在此的原因","莫格莱尼在这里做什么"}}},fp="26,241,22.264.0,17.285.1,46.159.0,47.145.0,18.192.0,46.200.0,44.225.0,48.156.0"}
P.entries["npc:scooty"] = {n="斯库提",s="在繁忙的海盗港口藏宝海湾，斯库提维持着通往诺莫瑞根的传送通道。这位地精工程师信赖自己的技术和传送器，尽管那座实验性传送平台位于已经沦陷的侏儒城市中。对部落而言，他的装置开辟了一条深入丹莫罗的险路。",h="在繁忙的海盗港口藏宝海湾，斯库提维持着通往诺莫瑞根的传送通道。这位地精工程师信赖自己的技术和传送器，尽管那座实验性传送平台位于已经沦陷的侏儒城市中。对部落而言，他的装置开辟了一条深入丹莫罗的险路。",kw={"藏宝海湾","诺莫瑞根","地精","斯库提","荆棘谷","传送装置","传送器"},ang={["faction:Horde"]="身为部落的一员，你可以利用斯库提这条不可或缺的捷径进入诺莫瑞根，绕过联盟在丹莫罗的防线。",["profession:Engineering"]="身为工程师，你能欣赏斯库提对传送器物理原理的大胆运用，尽管地精对安全的漠视让每次启动都成了一场赌博。"},sec={{t="藏宝海湾的传送专家",b="在藏宝海湾的码头和工坊之间，斯库提为热砂港钻研着雄心勃勃的工程发明。许多地精偏爱火药和炸药，他却致力于将物质传送到遥远的地方。他的传送器与诺莫瑞根内部的一座传送平台保持着稳定的连接。部落军队依靠他的技术抵达这座地下侏儒要塞，无须穿越危险的联盟领土。"},{t="侏儒装置与地精的冒险",b="实验性的地精传送装置很少能顺利运转。听说诺莫瑞根里出现了一套新的侏儒装置后，斯库提和搭档索维克制造了 捷运器 6000。斯库提乐呵呵地承认，这台机器已经爆炸了十来次。以分散的物质形态跨越大陆，显然会危及身体，但斯库提依然对自己的才智深信不疑。在他看来，每次机械故障都只是创新之路上的小小阻碍。"}},faq={{q="斯库提是谁？",a="斯库提是藏宝海湾的一位地精工程师，自称是工程学大师。他负责维护和校准地精传送器网络，将港口与诺莫瑞根深处的一座实验性传送平台连接起来。",al={"斯库提是谁","斯库提背景故事","斯库提 非玩家角色","藏宝海湾斯库提"}},{q="斯库提为什么有通往诺莫瑞根的传送装置？",a="斯库提将藏宝海湾与诺莫瑞根内部的一座实验性传送平台连接起来，让人们能够直接进入这座侏儒城市。对部落而言，这是一条不可或缺的通道，能让他们无须穿越防御森严的联盟腹地，就能进入丹莫罗。",al={"为何有诺莫瑞根传送装置","斯库提传送装置的原理","斯库提传送至 诺莫瑞根"}},{q="斯库提在哪里？",a="斯库提在藏宝海湾工作，那是位于荆棘谷最南端的中立地精港口。",al={"斯库提在哪里","斯库提位置","寻找斯库提"}},{q="使用斯库提的传送装置安全吗？",a="斯库提的传送装置能够成功将冒险者送入诺莫瑞根，但运转时也可能出岔子。机械故障和传送器的校准偏差，让每次传送都充满危险。",al={"斯库提安全吗","传送装置安全吗","传送装置风险"}}},fx={["6ce6cf89"]={q="斯库提站在哪一边？",a="斯库提在藏宝海湾经营业务，是中立地精商业的一员。他向任何愿意做生意的旅人提供工程服务和实验性传送装置，无论对方属于哪个阵营。",al={"斯库提阵营","斯库提属于部落还是联盟","斯库提效忠对象"}},["04182db4"]={q="斯库提为什么在藏宝海湾？",a="在藏宝海湾经营，让斯库提能够接触独立的贸易网络和充满好奇心的冒险者，远离大陆当局的干涉与监管。在这里，他可以随心所欲地管理自己的应答器网络，钻研地精远距离传送技术。",al={"斯库提为何在此","斯库提为何在藏宝海湾","斯库提为何来到这里"}}},fp="6,264,32.405.0,31.423.0,14.224.0,48.245.0,24.93.0,34.174.0"}
P.entries["npc:scout-riell"] = {n="哨兵瑞尔",s="在哨兵岭，哨兵瑞尔从石砌哨塔的塔顶监视着西部荒野。她效力于人民军，追踪迪菲亚潜行者的动向，请旅人带回这些亡命之徒的红色丝质头巾。",h="在哨兵岭，哨兵瑞尔从石砌哨塔的塔顶监视着西部荒野。她效力于人民军，追踪迪菲亚潜行者的动向，请旅人带回这些亡命之徒的红色丝质头巾。",kw={"迪菲亚潜行者","人民军","红色丝质头巾","瑞尔","哨兵瑞尔","哨兵岭","哨塔","西部荒野"},ang={["faction:Alliance"]="对联盟的勇士而言，哨兵瑞尔揭示了西部荒野的残酷现实。这里遭到遗弃的人民必须雇用佣兵，对抗迪菲亚潜行者日益壮大的威胁。",["profession:Tailoring"]="裁缝或许能认出，迪菲亚标志性的红色面罩是用真丝制成的。对乡间普通的拦路强盗来说，这种布料十分昂贵。"},sec={{t="俯瞰西部荒野",b="强盗和收割傀儡威胁着西部荒野。暴风城的皇家军队不见踪影，王室也拒绝提供援助。因此，人民军只能独自保卫这片地区。旅人带回的头巾为瑞尔提供了迪菲亚潜行者罪行的证据。"}},faq={{q="在哪里可以找到哨兵瑞尔？",a="哨兵瑞尔在西部荒野哨兵岭的石砌哨塔顶上放哨。沿楼梯上去就能找到她。",al={"瑞尔位置","哨兵瑞尔在哪里","寻找瑞尔"}},{q="哨兵瑞尔请冒险者做什么？",a="瑞尔请旅人从西部荒野和死亡矿井的迪菲亚扒手、拦路强盗和走私者身上收集红色丝质头巾。这些头巾能证明那些亡命之徒已被击杀。",al={"瑞尔任务","瑞尔提供什么任务","红色丝质头巾任务"}},{q="瑞尔为什么收集红色丝质头巾？",a="红色丝质头巾是迪菲亚潜行者成员的标志。收集这些头巾，既能证明那些恐吓西部荒野农户的强盗正在减少，也能夺走他们团结一致的象征。",al={"为什么收集头巾","为什么收集红色丝质头巾","迪菲亚面罩"}},{q="哨兵瑞尔为谁效力？",a="瑞尔效力于人民军，这是一支由格里安·斯托曼组建的志愿防卫部队。暴风城的贵族对西部荒野的困境视而不见，于是他组建了这支部队，保护这片地区。",al={"瑞尔阵营","瑞尔属于暴风城军队吗","瑞尔为谁效力"}}},fx={c25141c7={q="哨兵瑞尔是谁？",a="哨兵瑞尔是一名人类斥候，为哨兵岭效力，守护西部荒野。她驻守在俯瞰这片地区的高塔顶端，监视周围乡野，留意迪菲亚潜行者的动向，并与当地守军协调行动，击退威胁农田的匪徒。",al={"瑞尔是谁","哨兵瑞尔背景","哨兵瑞尔是谁"}},["2f6a5f48"]={q="哨兵瑞尔为什么驻守在这里？",a="瑞尔驻守在哨兵岭的塔顶，负责瞭望西部荒野。从这处高地，她可以巡视平原上的匪徒活动，追踪迪菲亚潜行者势力的扩张，并招募过往的冒险者，直接向那些为祸当地的盗贼发起进攻。",al={"哨兵瑞尔为何在此","瑞尔为何在西部荒野","瑞尔位置与目的"}},f57d6b81={q="哨兵瑞尔与谁有联系？",a="瑞尔与格里安·斯托曼以及驻扎在哨兵岭的人民军并肩效力。她和其他斥候、哨兵同属西部荒野处境艰难的地方守军，在王国军队缺席的情况下，依靠志愿民兵和勇敢的冒险者守卫王国边境。",al={"哨兵瑞尔认识谁","瑞尔阵营关系","瑞尔盟友"}}},fp="11,215,18.247.0,29.118.0,44.177.1,41.185.0,30.206.0"}
P.entries["npc:scout-thaelrid"] = {n="银月守卫塞尔瑞德",s="银月守卫塞尔瑞德在Pool of Ask'ar附近负伤，被困在黑暗深渊中。这位暗夜精灵斥候为银色黎明进入了沉没的废墟，如今已亲眼见到下方聚集的势力。",h="银月守卫塞尔瑞德在Pool of Ask'ar附近负伤，被困在黑暗深渊中。这位暗夜精灵斥候为银色黎明进入了沉没的废墟，如今已亲眼见到下方聚集的势力。",kw={"阿库麦尔","银色黎明","灰谷","黑暗深渊","阿斯卡之池","斥候塞尔瑞德","塞尔瑞德","梦游者克尔里斯"},ang={["faction:Alliance"]="联盟斥候正在灰谷追查塞尔瑞德失踪的下落，力求保障佐拉姆海岸的安全，并支持银色黎明的中立行动。",["faction:Horde"]="塞尔瑞德是一名暗夜精灵，但他效力于银色黎明。任何愿意打击暮光之锤并净化洞穴的冒险者都能帮助他。",["race:NightElf"]="对暗夜精灵而言，纳迦和末日教派亵渎黑暗深渊这样的古老神殿，令人悲愤难平。塞尔瑞德代表着他的族人，守望着卡利姆多最深的创伤。"},sec={{t="银色黎明的耳目",b="海底举行邪恶仪式的消息从佐拉姆海岸传到了银色黎明。这个组织监视着艾泽拉斯各地滋生的邪恶与违背自然的腐化，因此派斥候塞尔瑞德进入黑暗深渊。他的任务是评估威胁，监视被淹没的神殿，并返回报告。这样，银色黎明就能决定何处最需要援助。"},{t="蔓延的黑暗",b="塞尔瑞德发现，威胁远比传闻所说的可怕。凶残的纳迦与暮光之锤教派在沉没的废墟中缔结了邪恶的盟约。在梦游者克尔里斯的带领下，教徒们献上鲜血祭品，喂养多头蛇阿库麦尔，并与古老的恐怖存在交易，换取黑暗力量。塞尔瑞德还未来得及将警告带回地面，就被黑暗深渊中的生物打成重伤。他在Pool of Ask'ar附近与外界断绝了联系，至今仍被困在那里。"}},faq={{q="银月守卫塞尔瑞德是谁？",a="银月守卫塞尔瑞德是银色黎明的一名暗夜精灵密探。他进入灰谷沿海的黑暗深渊，收集下方势力的情报。",al={"塞尔瑞德是谁","塞尔瑞德传说","塞尔瑞德背景"}},{q="塞尔瑞德为何被困在黑暗深渊？",a="塞尔瑞德侦察神殿时，被黑暗深渊中的生物发现并打成重伤。他无法独自杀回地面，只得在阿斯卡之池附近藏身。",al={"他为何被困","他如何受伤","塞尔瑞德为何濒死"}},{q="塞尔瑞德在深处发现了什么？",a="塞尔瑞德发现，纳迦与暮光之锤教派在黑暗深渊缔结了邪恶的盟约。教徒们以鲜血献祭，喂养阿库麦尔，并与古老的恐怖存在交易，换取黑暗力量。",al={"塞尔瑞德发现了什么","教徒在做什么","黑暗深渊的秘密"}},{q="塞尔瑞德为谁效力？",a="塞尔瑞德效力于银色黎明，这是一个不受阵营界限束缚的中立组织，在艾泽拉斯各地对抗腐化、邪恶与灭世威胁。",al={"塞尔瑞德阵营","塞尔瑞德属于银色黎明吗","塞尔瑞德属于联盟吗"}},{q="塞尔瑞德请求冒险者做什么？",a="塞尔瑞德无法离开藏身之处，便请求冒险者杀死梦游者克尔里斯，并带回这位教派首领的头颅，以证明威胁已被消除。",al={"塞尔瑞德任务","黑暗深渊中的邪恶任务","他想要什么"}},{q="在哪里能找到塞尔瑞德？",a="塞尔瑞德负伤倒在阿斯卡之池附近一处隐蔽的凹穴中，就在黑暗深渊入口处被淹没的洞穴后方。",al={"塞尔瑞德在哪里","塞尔瑞德位置","阿斯卡之池斥候"}}},fp="21,198,23.334.0,19.436.1,29.163.0,49.186.0,41.193.0,27.146.0,41.149.0,28.127.0"}
P.entries["npc:searn-firewarder"] = {n="希尔恩·火结",s="在索尔的堡垒，希尔恩·火结指引部落萨满祭司探寻元素之道。",h="在索尔的堡垒，希尔恩·火结指引部落萨满祭司探寻元素之道。",kw={"天空的召唤","火焰的召唤","水之召唤","黑暗之矛","索尔的堡垒","奥格瑞玛","希尔恩·火结","萨满祭司训练师"},ang={["class:Shaman"]="身为萨满祭司，你可以向纳姆寻求指引，找到将元素之力束缚于图腾所需的导师与试炼。",["race:Troll"]="身为黑暗之矛巨魔，你可以从纳姆身上看到，你的精神传统如何与兽人和牛头人盟友的传统并肩而立。"},sec={{t="元素之道的引路人",b="在索尔的堡垒内，希尔恩·火结指引着探寻元素之道的萨满祭司。许多黑暗之矛巨魔通过巫医和巫毒仪式与灵魂沟通。纳姆指引初学者前往远方的导师处，参与火焰的召唤、水之召唤和天空的召唤的仪式，学习如何与火、水和空气的元素之灵沟通。他身处奥格瑞玛的部落最高指挥层之中。"}},faq={{q="希尔恩·火结是谁？",a="希尔恩·火结在奥格瑞玛的索尔的堡垒内训练丛林巨魔萨满祭司。他引导部落各地正在成长的萨满祭司踏上各自的灵性之旅。",al={"希尔恩·火结背景故事","纳姆是谁","纳姆奥格瑞玛"}},{q="希尔恩·火结提供哪些任务？",a="纳姆指引萨满祭司完成火焰的召唤、水之召唤和天空的召唤，引导他们前往各片大陆上遥远的圣坛，寻找精神导师。",al={"纳姆任务","希尔恩·火结任务线"}},{q="为什么一位巨魔萨满祭司会驻守在索尔的堡垒内？",a="索尔的堡垒是奥格瑞玛的领导核心，大酋长萨尔与各盟友种族的重要代表在此聚集。纳姆身处此地，体现了兽人与黑暗之矛氏族之间的紧密团结，以及萨满之道在新部落中的核心地位。",al={"纳姆为什么在索尔的堡垒","纳姆 格罗玛什要塞"}}},fp="16,76,23.421.0,24.154.0,40.162.0,53.270.0"}
P.entries["npc:seer-graytongue"] = {n="灰舌先知",s="在红云台地，灰舌先知引导年轻的牛头人完成最初的部族试炼。在莫高雷的纳拉其营地附近，他教导他们在踏入更广阔的世界之前，先学会敬奉大地母亲。",h="在红云台地，灰舌先知引导年轻的牛头人完成最初的部族试炼。在莫高雷的纳拉其营地附近，他教导他们在踏入更广阔的世界之前，先学会敬奉大地母亲。",kw={"纳拉其营地","灰舌","莫高雷","红云台地","力量仪祭","大地之母仪祭","灰舌先知"},ang={["class:Shaman"]="身为萨满祭司，你可以向灰舌这样的长者求教，了解神圣的仪式与试炼如何将战士的力量与先祖的指引相连。",["race:Tauren"]="身为年轻的牛头人，拜访灰舌先知意味着经历一场神圣的成年仪式，将自身的力量与Earthmother永恒的祝福融为一体。"},sec={{t="台地上的引路人",b="年轻的牛头人勇士和施法者在红云台地顶上找到灰舌先知。他在那里引导从纳拉其营地出发的年轻人完成神圣的仪式，其中包括大地之母仪祭。他们的试炼以莫高雷严酷的平原环境和危险的野兽考验其意志。通过这些试炼，灰舌教导他们荣誉、耐心与敬畏，这些都是每个牛头人成年后应当秉持的美德。"}},faq={{q="灰舌先知是谁？",a="灰舌先知是一位年迈的牛头人先知，住在莫高雷红云台地顶上的小屋里。他引导年轻的英雄完成传统仪式，向部族证明自己的价值。",al={"灰舌","灰舌先知的职责","红云台地上的先知是谁"}},{q="灰舌先知主持哪些试炼？",a="灰舌先知引导年轻的牛头人完成大地之母仪祭中的部分仪式，其中包括力量仪祭。这些仪式考验勇士的坚韧，以及他们对平原自然平衡的尊重。",al={"灰舌的任务","灰舌想要什么","大地之母仪祭 灰舌"}},{q="在哪里可以找到灰舌先知？",a="灰舌先知住在莫高雷纳拉其营地外、红云台地边缘的一间皮革小屋里。",al={"灰舌先知的位置","灰舌在哪里","灰舌的小屋"}}},fp="15,195,19.390.0,23.183.0,41.202.0,33.112.0"}
P.entries["npc:seer-ravenfeather"] = {n="鸦羽先知",s="在红云台地的纳拉其营地，鸦羽先知指引年轻的牛头人了解灵魂之道与莫高雷的大地。",h="在红云台地的纳拉其营地，鸦羽先知指引年轻的牛头人了解灵魂之道与莫高雷的大地。",kw={"大地的召唤","纳拉其营地","大地灵契","莫高雷","鸦羽","红云台地","鸦羽先知","萨满"},ang={["class:Shaman"]="作为一名年轻的牛头人萨满，你可以将鸦羽先知视为最初的引路人，向她学习如何与元素沟通、凝聚大地之力。",["race:Tauren"]="作为牛头人，你可以在纳拉其营地找到鸦羽先知，由她指引你了解族人的精神传统。你的族人在祖居之地安顿下来时，正是这一传统支撑着他们。"},sec={{t="台地上的引路人",b="在纳拉其营地，鸦羽先知教导选择了萨满之道的年轻牛头人。红云台地是一处神圣的试炼之地，在初学者深入莫高雷之前，她会帮助他们为履行职责做好准备。她传授的仪式让他们得以与元素之力沟通，并向大地母亲表达敬意。"},{t="元素的召唤",b="鸦羽先知引导新晋萨满迈出灵修的第一步，并完成传统的大地的召唤仪式。在她的指导下，初学者准备仪式用的灵契，并在台地的嶙峋岩石间寻求与大地之灵沟通。他们建立的纽带为自身的元素魔法奠定了根基。"}},faq={{q="鸦羽先知是谁？",a="鸦羽先知在红云台地的纳拉其营地指引年轻的牛头人萨满。",al={"鸦羽先知背景故事","鸦羽是谁","纳拉其营地先知"}},{q="她在萨满训练中担任什么角色？",a="她带领萨满新手完成最初的仪式，包括大地的召唤以及与大地之灵沟通。",al={"鸦羽萨满任务","大地的召唤训练师","鸦羽传授什么"}},{q="在哪里可以找到鸦羽先知？",a="鸦羽先知位于莫高雷西南部红云台地的纳拉其营地，就在营地的帐篷与小屋之间。",al={"鸦羽位置","鸦羽在哪里","纳拉其营地位置"}}},fp="17,119,19.324.0,24.292.0,25.80.0,43.126.0,35.107.0"}
P.entries["npc:seereth-stonebreak"] = {n="希雷斯·碎石",s="在巨木谷附近，希雷斯·碎石密切关注着这片土地上的异动。这位兽人萨满祭司在石爪山脉与贫瘠之地的交界处扎营，指引旅人应对环境破坏、失控的机械，以及卡利姆多日益紧张的局势。",h="在巨木谷附近，希雷斯·碎石密切关注着这片土地上的异动。这位兽人萨满祭司在石爪山脉与贫瘠之地的交界处扎营，指引旅人应对环境破坏、失控的机械，以及卡利姆多日益紧张的局势。",kw={"老巫婆","地精","希雷斯","萨满祭司","伐木机","灵魂","碎石","石爪山脉"},ang={["class:Shaman"]="身为萨满祭司，你与希雷斯肩负着同样的职责：治愈石爪山脉环境遭受的创伤，安抚躁动的灵魂。",["faction:Horde"]="身为部落的一员，你协助保护重要的陆路通道和资源，抵御联盟军队和肆无忌惮的地精作业带来的威胁。",["race:Orc"]="身为兽人，你与希雷斯一样，重归萨满之道，敬畏自然世界，反对盲目的破坏。"},sec={{t="警觉的萨满祭司",b="希雷斯·碎石在巨木谷附近的营地里守望着部落的土地。身为兽人萨满祭司，她遵循元素的和谐之道，守护部落的领土。大地之灵因地精的掠夺而哀号，部落便派她前往石爪山脉。在那里，她关注着大地的变化，指引旅人应对威胁这片荒野边疆的危险。"},{t="石爪山脉的动荡",b="希雷斯·碎石为石爪山脉各处的动荡深感忧虑。地精肆无忌惮的开发，以及不断砍伐古老林地的机械伐木机，严重破坏了群山的灵性平衡。她派遣部落使者对抗入侵者，并向年长的博学者寻求指点，希望能减轻大地的痛苦。"}},faq={{q="希雷斯·碎石是谁？",a="希雷斯·碎石是一位为部落效力的兽人萨满祭司。她指引前往石爪山脉的旅人，应对危及这片土地和部落在当地立足的威胁。",al={"希雷斯","希雷斯是谁","希雷斯·碎石的故事"}},{q="希雷斯为何担忧石爪山脉？",a="石爪山脉正遭受滥伐、肆虐的地精伐木机械，以及日益激烈的冲突之苦。希雷斯感受到了当地灵魂的躁动，正努力阻止这场浩劫。",al={"为何是石爪山脉","希雷斯的困扰","石爪山脉的动荡"}},{q="她原先的驻地怎么样了？",a="希雷斯原先的驻地仍在巨木谷附近，位于石爪山脉与贫瘠之地的交界处。部落派她前往石爪山脉，而她的营地就在十字路口以西的道路旁。",al={"希雷斯的过去","荣耀岗哨 希雷斯","希雷斯为何迁移"}},{q="希雷斯会向冒险者提供哪些任务？",a="希雷斯派部落冒险者深入石爪山脉，对抗荆棘谷地精旗下的地精，拆毁破坏性的伐木机，与受困扰的灵魂沟通，并向玛加萨·野性图腾等备受敬重的长者请教。",al={"希雷斯的任务","希雷斯想要什么","希雷斯·碎石的任务"}},{q="她提到的长者是谁？",a="长者就是玛加萨·野性图腾，一位居住在雷霆崖长者高地、力量强大且颇具影响力的牛头人长者。希雷斯向她请教，以应对深层的灵性动荡。",al={"长者","长者是谁","长者任务"}},{q="她为何关心地精的作业？",a="希雷斯对此深感忧虑，因为地精的伐木作业使用机械伐木机摧残神圣的森林，污染水道，还激怒了她誓要安抚的自然之灵。",al={"希雷斯与地精","地精入侵者","为何憎恨地精"}}},fp="18,221,17.351.0,21.319.0,26.164.0,56.196.0,35.202.0,45.213.0,36.182.0,44.184.0"}
P.entries["npc:senani-thunderheart"] = {n="塞娜尼·雷心",s="在灰谷的碎木岗哨，塞娜尼·雷心考验着猎人们。她派旅行者追猎森林中最凶猛的掠食者，为部落效力，这既是对技艺的试炼，也能减少部落领地附近的野兽。",h="在灰谷的碎木岗哨，塞娜尼·雷心考验着猎人们。她派旅行者追猎森林中最凶猛的掠食者，为部落效力，这既是对技艺的试炼，也能减少部落领地附近的野兽。",kw={"灰谷","灰谷狩猎","密斯特拉湖","塞娜尼","萨杜布拉","沙普塔隆","雷心","乌萨苟斯"},ang={["class:Hunter"]="身为猎人，你要追踪灰谷中行踪难觅的野兽乌萨苟斯、萨杜布拉和沙普塔隆，接受塞娜尼的考验。",["faction:Horde"]="身为部落的一员，你会发现碎木岗哨是你在灰谷的立足之地，塞娜尼在这里帮助斥候证明自己的价值，并保障荒野的安全。",["race:Tauren"]="身为牛头人旅行者，在远离莫高雷的地方遇见塞娜尼，会让你想起Earth Mother的试炼，以及猎人与猎物之间古老的平衡。"},sec={{t="狩猎大师",b="在碎木岗哨，塞娜尼·雷心延续着牛头人在灰谷的狩猎传统。远离莫高雷开阔的平原，她派部落猎人迎战森林中的巨兽，考验他们的追踪和战斗技巧。对塞娜尼而言，狩猎是一场光荣的挑战，也是在这片纷争不断的荒野中生存的方式。"},{t="灰谷的野兽",b="塞娜尼指引猎人追猎三只令人畏惧的掠食者：巨熊乌萨苟斯、猎豹萨杜布拉和角鹰兽沙普塔隆。它们的信物分别是一只熊掌、一颗头颅和一只利爪。取得这些信物，标志着猎人通过了试炼，也表明他们敬重这片土地，并有能力降服其中最凶猛的野兽。"}},faq={{q="塞娜尼·雷心是谁？",a="塞娜尼·雷心是驻留在灰谷碎木岗哨的一名牛头人女猎手。她派猎人追猎森林中最危险的野兽，为部落效力。",al={"塞娜尼是谁","塞娜尼·雷心的故事","银风避难所任务给予者"}},{q="在哪里可以找到塞娜尼·雷心？",a="你可以在碎木岗哨找到塞娜尼，那是位于贫瘠之地正北方、灰谷境内的部落前哨。",al={"塞娜尼位置","塞娜尼在哪里","银风避难所在哪里"}},{q="灰谷狩猎是什么？",a="灰谷狩猎是塞娜尼交给猎人的一系列挑战。他们要追踪并杀死三只著名的掠食者：巨熊乌萨苟斯、夜刃豹萨杜布拉和角鹰兽沙普塔隆。",al={"灰谷狩猎","塞娜尼想要什么","灰谷狩猎任务"}},{q="塞娜尼要求带回哪些狩猎战利品？",a="塞娜尼要求猎人带回乌萨苟斯的爪子、萨杜布拉的头颅和尖爪之爪，以证明他们战胜了这三只野兽。",al={"狩猎战利品","灰谷狩猎物品","塞娜尼需要什么"}},{q="塞娜尼与当地的熊怪有什么联系吗？",a="塞娜尼的狩猎与熊怪无关。她负责的是灰谷狩猎，而污林和其他熊怪部族则是森林中的危险之一。",al={"污林任务","污林熊怪之王","塞娜尼熊怪"}},{q="塞娜尼隶属于塞纳里奥议会吗？",a="不。塞娜尼为部落和牛头人各部族效力，她以传统猎人的身份踏入林地，而非以塞纳里奥议会德鲁伊守护者的身份。",al={"塞娜尼是德鲁伊吗","塞娜尼塞纳里奥议会"}}},fp="19,186,22.339.0,23.277.0,27.161.0,37.103.0,27.163.0,48.146.0,60.158.0,46.145.0"}
P.entries["npc:senator-mehr-stonehallow"] = {n="参议员梅尔·圣石",s="参议员梅尔·圣石已抵达古博拉采掘场的前线，应对穴居人的侵扰。这位铁炉堡政界人士也是探险者协会的成员，负责遏制穴居人的蔓延，并号召跃跃欲试的冒险者消灭这些野兽，以免它们占领采掘场。",h="参议员梅尔·圣石已抵达古博拉采掘场的前线，应对穴居人的侵扰。这位铁炉堡政界人士也是探险者协会的成员，负责遏制穴居人的蔓延，并号召跃跃欲试的冒险者消灭这些野兽，以免它们占领采掘场。",kw={"丹莫罗","探险者协会","古博拉","铁炉堡参议院","梅尔","采掘场","石腭","参议员","圣石","穴居人"},ang={["faction:Alliance"]="圣石让年轻的联盟英雄得以一窥矮人领袖的风范：斩杀怪物，保护辛勤劳作的民众。",["race:Dwarf"]="在矮人看来，一位参议员站在采掘场的泥泞中，而非坐在铁炉堡的王座厅里喝麦酒，展现了他们期望领袖具备的坚毅。"},sec={{t="矿坑中的政客",b="参议员梅尔·圣石离开了铁炉堡的参议院大厅，来到古博拉采掘场。身为矮人，他致力于政务与探险者协会的历史探索，深知王国面临的危险。当石腭穴居人从岩层深处挖出通道、涌上地面时，圣石亲自来到了矿坑。他认为，仅凭辩论无法保护工人。因此，他向有能力的旅人提供赏金，请他们击退凶暴的穴居人，夺回采掘场。"}},faq={{q="参议员梅尔·圣石是谁？",a="参议员梅尔·圣石在铁炉堡的参议院任职，也是探险者协会的成员。他来到古博拉采掘场，组织这里的防御。",al={"圣石的职责","参议员是谁","梅尔·圣石"}},{q="为什么一位参议员会驻守古博拉采掘场？",a="参议员梅尔·圣石来到古博拉采掘场，负责处理一场危机。石腭穴居人从地下挖出通道，入侵了采矿区，威胁着矮人工人和珍贵的发掘成果。圣石不愿将这个问题留给远方的官员处理。",al={"圣石为何在这里","他为何在采掘场","丹莫罗的参议员"}},{q="参议员圣石希望冒险者做什么？",a="参议员梅尔·圣石雇用初来乍到的冒险者，消灭古博拉采掘场内外的石腭穴居人。清理下层区域有助于保障发掘现场的安全，保护留下的矿工。",al={"公众之仆任务","圣石的任务","采掘场任务"}},{q="除了参议院，圣石还属于什么组织？",a="梅尔·圣石既是铁炉堡参议院的成员，也属于探险者协会。他对地下发掘的兴趣，也有助于解释他为何离开首都、来到这里。",al={"圣石的阵营","圣石是否属于探险者协会","圣石所属组织"}}},fx={["67284ec7"]={q="参议员梅尔·圣石效忠哪一方？",a="参议员梅尔·圣石坚定地支持铁炉堡王国与大联盟。作为铁炉堡参议院的现任议员和探险者协会的活跃成员，他直接效忠于国王麦格尼·铜须，并致力于守护矮人家园的安全。",al={"圣石参议员阵营","圣石为谁效力","圣石属于联盟吗"}}},fp="24,266,24.449.0,32.148.0,47.275.0,53.204.0,64.173.0"}
P.entries["npc:senior-surveyor-fizzledowser"] = {n="高级勘探员菲兹杜瑟",s="高级勘探员菲兹杜瑟是一名地精研究员，在塔纳利斯的加基森开展工作。他调查当地供水受到干扰的原因，并派冒险者查明谢申克失踪的下落。",h="高级勘探员菲兹杜瑟是一名地精研究员，在塔纳利斯的加基森开展工作。他调查当地供水受到干扰的原因，并派冒险者查明谢申克失踪的下落。",kw={"探水装置","菲兹杜瑟","加基森","大裂口","匹斯特苏格","谢申克","异种蝎","塔纳利斯","水务公司"},ang={["profession:Engineering"]="菲兹杜瑟依靠地精工程技术定制的探水装置，精确定位流沙之下隐藏的水源。"},sec={{t="寻水行动的变故",b="高级勘探员菲兹杜瑟以加基森为据点，主要致力于解决这座沙漠城镇长期面临的资源短缺问题。当地的水井和水塘不断被敌对的废土强盗占据，加基森水业公司不得不到更远的地方寻找尚未开发的地下蓄水层。为此，菲兹杜瑟派出配备探水装置的斥候，前往沙丘各处，包括流沙岗哨一带。然而，他的勘探非但没有找到洁净的泉水，反而一次次探入地下虫巢，让一场物资供应危机变成了迫在眉睫的生态灾难。"},{t="揭开异种蝎的真面目",b="当勘探队开始遭到身披甲壳、能够掘地的昆虫伏击，损失惨重时，菲兹杜瑟便与炼金师匹斯特苏格合作，研究这些昆虫的标本。此后接连发生的惨剧，包括初级勘探员谢申克在大裂口中失踪，证明了它们并非普通的沙漠害虫，而是被称为异种蝎、协同行动的先锋部队。调查结果表明，这股威胁足以吞没卡利姆多南部，令菲兹杜瑟深感不安，于是他越过地精的中立立场，向部落和联盟双方的学者传递消息。"}},faq={{q="高级勘探员菲兹杜瑟是谁？",a="他是加基森水业公司的工程师兼野外主管。他的职责是在塔纳利斯沙漠各处勘察可用的水井，保障加基森的供水。",al={"菲兹杜瑟是谁","菲兹杜瑟 塔纳利斯","加基森勘探员"}},{q="加基森水业公司是什么？",a="这是一家以加基森为据点的商业企业，负责在干旱的塔纳利斯沙漠中获取、处理和分配水源，在这里，水是最宝贵的商品。",al={"加基森水业公司","菲兹杜瑟为谁工作"}},{q="初级勘探员谢申克出了什么事？",a="谢申克是一名失踪的勘探员，菲兹杜瑟请冒险者调查他的下落。",al={"谢申克在哪里","谢申克的救赎","谢申克出了什么事"}},{q="菲兹杜瑟为什么担忧沙漠中的昆虫？",a="他的调查始于令人不安的昆虫活动，以及加基森供水受到的干扰，这促使他收集证据，以便进一步研究。",al={"为什么调查虫子","腐化之巢调查","异种虫威胁 塔纳利斯"}}},fp="28,193,29.427.1,23.479.1,36.138.0,36.155.0,44.102.1,55.135.0"}
P.entries["npc:senir-whitebeard"] = {n="森内尔·白须",s="在卡拉诺斯的雷酒酿制厂外，森内尔·白须密切关注着丹莫罗各地日益加剧的威胁。铁炉堡参议院派他前来评估霜鬃巨魔的攻势，并向矮人领袖报告他们的动向。",h="在卡拉诺斯的雷酒酿制厂外，森内尔·白须密切关注着丹莫罗各地日益加剧的威胁。铁炉堡参议院派他前来评估霜鬃巨魔的攻势，并向矮人领袖报告他们的动向。",kw={"丹莫罗","霜鬃","铁炉堡","卡拉诺斯","报告","参议院","森内尔","白须"},ang={["faction:Alliance"]="作为丹莫罗的联盟新兵，你可以帮助森内尔·白须保护铁炉堡的腹地，防止巨魔的暴动切断这里与外界的联系。",["race:Dwarf"]="身为矮人，你可以看到森内尔·白须如何将边境守军与铁炉堡的统治机构联系起来。"},sec={{t="参议院的使者",b="森内尔·白须代表铁炉堡参议院在卡拉诺斯行使职权。丹莫罗各地的动荡日益加剧，城中的议事厅也在关注。森内尔将冰雪边境斥候传来的消息，送交铁炉堡石门后的议员。"},{t="监视霜鬃",b="霜鬃巨魔流离失所，陷入绝境，他们从冰封的峭壁间出击，步步逼近矮人的定居点和道路，攻势愈发猛烈。森内尔为铁炉堡的军事指挥官收集巨魔的部署情报，尤其关注他们的要塞周边。他的职责是收集情报，而非冲锋陷阵。"}},faq={{q="森内尔·白须是谁？",a="森内尔·白须是铁炉堡参议院的使者，驻扎在卡拉诺斯外，负责收集丹莫罗境内威胁的情报，尤其是霜鬃巨魔的动向。",al={"这个矮人是谁","森内尔·白须背景故事","森内尔是谁"}},{q="森内尔在卡拉诺斯做什么？",a="森内尔·白须在卡拉诺斯观察巨魔的活动，并统筹斥候的报告。卡拉诺斯是丹莫罗的一处交通要道，他在这里接收前线情报，再送往铁炉堡参议院。",al={"森内尔为何在这里","森内尔在卡拉诺斯的职责","森内尔做什么"}},{q="铁炉堡参议院为什么需要在这里派驻使者？",a="铁炉堡参议院需要森内尔·白须收集前线的第一手报告。他负责评估霜鬃的威胁是否需要首都立即采取军事行动。",al={"为何派遣使者","铁炉堡参议院卡拉诺斯","参议院事务"}},{q="森内尔在丹莫罗最关心什么？",a="森内尔·白须最关心的是霜鬃巨魔的入侵。巨魔正从营地向矮人的领地推进，威胁着卡拉诺斯等附近的定居点。",al={"森内尔的主要难题","森内尔关注什么威胁","森内尔巨魔"}},{q="森内尔会亲自与巨魔作战吗？",a="不会。森内尔·白须负责收集情报，依靠当地斥候、巡山人和过往的冒险者进入霜鬃巨魔要塞等敌方据点，为他带回报告。",al={"森内尔会参战吗","森内尔是战士吗","森内尔战斗"}},{q="森内尔的报告送往何处？",a="森内尔·白须将有关巨魔部署和兵力的报告沿山路送往铁炉堡，交给参议院和城中的领袖。",al={"报告送往何处","森内尔报告的去向","谁接收报告"}}},fx={["40f66e19"]={q="森内尔·白须效忠哪一方？",a="森内尔·白须为铁炉堡王国和大联盟效力。他是受 铁炉堡参议院 直接管辖的正式使节，全心效忠于矮人政府，并致力于保卫王国的腹地。",al={"森内尔·白须效忠对象","森内尔为谁效力","森内尔阵营"}}},fp="16,238,19.232.0,22.327.0,24.167.0,32.206.0,52.190.0,46.183.0,36.174.0,28.127.0"}
P.entries["npc:sentinel-arynia-cloudsbreak"] = {n="哨兵阿瑞尼亚·碎云",s="在泰达希尔的神谕林地，哨兵阿瑞尼亚·碎云守望着北方的树林。她守护着蕴含魔力的泉水和林间的野生动物。",h="在泰达希尔的神谕林地，哨兵阿瑞尼亚·碎云守望着北方的树林。她守护着蕴含魔力的泉水和林间的野生动物。",kw={"阿瑞尼亚·碎云","魔法林地","卡多雷","迷雾","暗夜精灵","神谕林地","哨兵","泰达希尔"},ang={["faction:Alliance"]="身为联盟的一员，你会看到阿瑞尼亚坚守 Kaldorei Sentinels 的职责，守望联盟在卡利姆多的重要林地据点。",["race:NightElf"]="作为一名在泰达希尔逐渐成年的年轻暗夜精灵，帮助 Sentinel Cloudsbreak 能让你积累实践经验，守护新家园的荒野平衡。"},sec={{t="神谕林地的守望者",b="哨兵阿瑞尼亚·碎云驻守在神谕林地，这里是泰达希尔最幽僻的地方之一。远离达纳苏斯，她在古树与空灵的泉水之间为哨兵部队效力，守护荒野免受侵扰。"},{t="林地中的异动",b="尽管泰达希尔的诞生神圣非凡，树上的生灵之间仍有不和谐的迹象。阿瑞尼亚请路过的冒险者和年轻的暗夜精灵调查当地的异状，从反常的野生动物到魔法泉水周围的神秘征兆。"}},faq={{q="哨兵阿瑞尼亚·碎云是谁？",a="哨兵阿瑞尼亚·碎云是一名暗夜精灵哨兵，守卫着泰达希尔北部的神谕林地。她守望这片林地，并请旅人帮助维护这里的自然和谐。",al={"阿瑞尼亚·碎云","阿瑞尼亚 是谁","哨兵 阿瑞尼亚"}},{q="在哪里能找到阿瑞尼亚·碎云？",a="阿瑞尼亚·碎云在神谕林地的露天区域守望，这里位于泰达希尔西北部、多兰纳尔以北。",al={"阿瑞尼亚 位置","阿瑞尼亚 在哪里","阿瑞尼亚·碎云 地图"}},{q="她在 哨兵 中承担什么职责？",a="阿瑞尼亚巡逻于外围的林间枝干，留意当地的灵体、野生动物和自然现象，寻找腐化或失衡的迹象。",al={"阿瑞尼亚 职责","阿瑞尼亚 做什么"}},{q="她与泰达希尔上的其他人有亲属关系吗？",a="阿瑞尼亚·碎云与玛沃里斯·裂云有着相同的姓氏，这暗示着这两位居住在世界之树上的暗夜精灵可能有亲属关系。",al={"阿瑞尼亚 家族","玛沃里斯·裂云"}},{q="她会交给冒险者什么任务？",a="阿瑞尼亚请旅人调查这片魔法林地，处理附近的神秘异动和游荡的野兽，并帮助陷入困境的生灵。",al={"阿瑞尼亚 任务","神谕林地任务"}},{q="神谕林地为何对暗夜精灵意义重大？",a="暗夜精灵将神谕林地奉为泰达希尔上的神圣庇护所，这里以宁静的池水闻名。德鲁伊和哨兵守护着这里，寻求自然的指引与预兆。",al={"神谕林地为何重要","神谕林地背景故事"}}},fp="27,147,27.250.0,20.245.0,35.181.0,38.106.0,46.138.0,44.139.0,40.149.0,55.167.0"}
P.entries["npc:sentinel-aynasha"] = {n="哨兵阿娜莎",s="在黑海岸荒野的边界，哨兵阿娜莎侦察着威胁暗夜精灵领地的危险。她监视敌人的动向，并穿行于边境，传递紧急情报。",h="在黑海岸荒野的边界，哨兵阿娜莎侦察着威胁暗夜精灵领地的危险。她监视敌人的动向，并穿行于边境，传递紧急情报。",kw={"弓箭手","阿娜莎","黑海岸","卡多雷","暗夜精灵","斥候","哨兵"},ang={["faction:Alliance"]="作为一名在卡利姆多旅行的联盟旅者，你可能会在危险的荒野道路上遇见像阿娜莎这样的哨兵斥候，她们是重要的联络人。",["race:NightElf"]="身为暗夜精灵，你眼中的哨兵阿娜莎是一位警觉的古老森林守卫，保护着林地，抵御外来势力与荒野中的腐化。"},sec={{t="身处前线",b="在暗夜精灵领地遭受敌人入侵的边境，哨兵阿娜莎与哨兵一同侦察、作战。她穿越崎岖的荒野，传递紧急消息，并留意敌方巡逻队。精湛的弓术和野外生存知识帮助她穿越双方争夺的地带。"}},faq={{q="哨兵阿娜莎是谁？",a="哨兵阿娜莎是暗夜精灵哨兵中的一名弓箭手，负责侦察和作战。这支部队守卫着卡利姆多北部及其边境。",al={"阿娜莎是谁","阿娜莎的职责","哨兵阿娜莎的故事"}},{q="她在黑海岸监视哪些威胁？",a="在黑海岸边缘，哨兵阿娜莎监视着敌方营地、叛乱的熊怪部族，以及威胁暗夜精灵荒野的外来入侵者。",al={"阿娜莎的敌人","黑海岸的威胁","她在与谁作战"}},{q="她为何经常独自行路？",a="哨兵阿娜莎和其他哨兵经常独自或两人结伴行动，在哨所之间传递紧急情报，避免引起敌对势力的注意。",al={"她为何独自行动","阿娜莎的单独任务","哨兵斥候的职责"}}},fp="16,177,18.262.0,24.126.0,43.151.0,38.175.0"}
P.entries["npc:sentinel-elissa-starbreeze"] = {n="哨兵艾莉萨·星风",s="在奥伯丁，哨兵艾莉萨·星风守望着黑海岸雾气弥漫的海滨。她在桥对面一座屋舍的楼上，追踪日益加剧的威胁，指引旅人前去应对荒野中的危险。",h="在奥伯丁，哨兵艾莉萨·星风守望着黑海岸雾气弥漫的海滨。她在桥对面一座屋舍的楼上，追踪日益加剧的威胁，指引旅人前去应对荒野中的危险。",kw={"奥萨拉克斯","奥伯丁","黑海岸","艾莉萨·星风","暗夜精灵","哨兵"},ang={["faction:Alliance"]="作为来自泰达希尔的联盟旅人，你可以向哨兵艾莉萨·星风寻求指引，前去应对黑海岸深处的危险。",["race:NightElf"]="作为暗夜精灵，你可以看到哨兵们在卡利姆多北部各处哨站展现出的警觉与纪律，奥伯丁也在其中。"},sec={{t="奥伯丁的警戒之眼",b="哨兵艾莉萨·星风在桥对面协调奥伯丁的防务。其他哨兵在黑海岸的海滨与林地巡逻时，她在镇上旅店东北方一座建筑的楼上守望。她时刻留意着这片地区的异常动静。她指引旅人前往远方，包括北面遥远的奥萨拉克斯之塔，以免暗处的威胁让奥伯丁措手不及。"}},faq={{q="在哪里能找到哨兵艾莉萨·星风？",a="哨兵艾莉萨·星风在黑海岸的奥伯丁执勤。穿过旅店东北方的小桥，再登上桥对面那座建筑的二楼。",al={"艾莉萨·星风位置","艾莉萨·星风在哪","奥伯丁星风"}},{q="她在黑海岸的职责是什么？",a="哨兵艾莉萨·星风追踪黑海岸各地的危险，协助守卫奥伯丁。她指引斥候和冒险者前往遥远的哨站，调查奇异的威胁，奥萨拉克斯之塔也在其中。",al={"艾莉萨做什么","艾莉萨·星风职责"}},{q="她在暗夜精灵中有亲人吗？",a="没有关于哨兵艾莉萨·星风亲属的记载。她在奥伯丁守望着小镇，并派遣旅人前往奥萨拉克斯之塔。",al={"星风家人","艾莉萨的亲属"}}},fp="26,184,27.402.0,44.149.0,30.204.0,43.151.0"}
P.entries["npc:sentinel-farsong"] = {n="哨兵艾蒂亚·轻歌",s="在银翼树林，哨兵艾蒂亚·轻歌协助守卫灰谷的南部边境。她召集勇士，在战歌峡谷对抗战歌氏族。",h="在银翼树林，哨兵艾蒂亚·轻歌协助守卫灰谷的南部边境。她召集勇士，在战歌峡谷对抗战歌氏族。",kw={"灰谷","哨兵艾蒂亚·轻歌","银翼树林","银翼要塞","战歌峡谷","战歌氏族"},ang={["faction:Alliance"]="哨兵艾蒂亚·轻歌指挥联盟志愿者，在灰谷对抗战歌氏族。",["race:NightElf"]="作为Elune神圣森林的守护者，哨兵艾蒂亚·轻歌体现了kaldorei驱逐亵渎古老林地之人的决心。"},sec={{t="银翼树林的守护者",b="当战歌氏族砍伐树木、向暗夜精灵的领地推进时，哨兵艾蒂亚·轻歌在银翼树林保持警戒。她号召联盟勇士打击战歌氏族，并向银翼指挥部递交战地报告。她的工作有助于遏制部落的扩张，保护森林。"}},faq={{q="哨兵艾蒂亚·轻歌是谁？",a="哨兵艾蒂亚·轻歌是灰谷银翼要塞的一名暗夜精灵哨兵。她驻守在战歌峡谷入口附近的银翼树林，在那里招募联盟冒险者并收集战场情报。",al={"轻歌","哨兵艾蒂亚·轻歌的故事","轻歌是谁"}},{q="在哪里可以找到她？",a="哨兵艾蒂亚·轻歌位于灰谷东南部的银翼树林，联盟在此集结力量，投入战歌峡谷的战斗。",al={"哨兵艾蒂亚·轻歌的位置","轻歌在哪里","轻歌灰谷地图"}},{q="她为何与战歌氏族作战？",a="战歌氏族正在采伐木材，亵渎灰谷的神圣森林。哨兵艾蒂亚·轻歌协助守卫森林，夺回被部落占据的领土。",al={"为何对抗战歌氏族","轻歌的动机","灰谷冲突"}}},fp="16,145,28.284.0,24.213.0,23.122.0,42.161.0"}
P.entries["npc:sentinel-onaeya"] = {n="哨兵奥奈雅",s="哨兵奥奈雅在迈斯特拉岗哨守卫着灰谷的北部边缘。这位暗夜精灵守卫召集联盟冒险者保护森林，并援助其他哨兵。",h="哨兵奥奈雅在迈斯特拉岗哨守卫着灰谷的北部边缘。这位暗夜精灵守卫召集联盟冒险者保护森林，并援助其他哨兵。",kw={"灰谷","黑海岸","迈斯特拉岗哨","暗夜精灵","奥奈雅","哨兵"},ang={["faction:Alliance"]="作为联盟旅人，当你离开沿海荒野，进入灰谷饱受争夺的森林时，可以协助奥奈雅开展防御工作。",["faction:Horde"]="作为部落旅人，你将面对奥奈雅，她是一名守卫迈斯特拉岗哨和灰谷北部通路的哨兵。",["race:NightElf"]="作为从黑海岸南下的暗夜精灵，你会在前线遇到奥奈雅，她正守护灰谷林地，抵御外来威胁。"},sec={{t="边境上的守卫",b="迈斯特拉岗哨是从黑海岸通往灰谷的道路旁的一处哨站。哨兵奥奈雅守卫着聚落外的屋舍，并协调此地的防御。凶猛的野兽、腐化的力量和边境上的紧张局势威胁着这一带的暗夜精灵聚落。"},{t="坚守岗哨",b="哨兵奥奈雅听说，哨兵阿娜莎在途经黑海岸传递重要消息时遭到了熊怪袭击。奥奈雅会奖赏那些保护中毒的哨兵、直到解毒剂生效的人。"}},faq={{q="哨兵奥奈雅是谁？",a="哨兵奥奈雅是驻守灰谷西北部迈斯特拉岗哨的一名暗夜精灵守卫。她指引旅人协助保卫哨站。",al={"奥奈雅","哨兵奥奈雅","奥奈雅是谁"}},{q="哨兵奥奈雅在哪里？",a="哨兵奥奈雅站在迈斯特拉岗哨的主建筑外。岗哨位于灰谷北部的道路旁，就在与黑海岸交界处的南面。",al={"奥奈雅位置","哨兵奥奈雅在哪里","寻找奥奈雅"}},{q="哨兵奥奈雅属于哪个阵营？",a="哨兵奥奈雅隶属于暗夜精灵哨兵，效忠联盟。她一见到部落冒险者就会表现出敌意。",al={"奥奈雅阵营","奥奈雅属于联盟吗","奥奈雅对部落友好吗"}},{q="奥奈雅与哨兵阿娜莎有什么联系？",a="冒险者保护哨兵阿娜莎抵御熊怪的袭击后，阿娜莎会派他们前往迈斯特拉岗哨，向奥奈雅报告。奥奈雅会奖赏他们，并为阿娜莎幸存而感到欣慰。",al={"奥奈雅 阿娜莎","哨兵阿娜莎奖励"}},{q="哨兵奥奈雅提供什么样的任务？",a="冒险者在黑海岸保护哨兵阿娜莎抵御熊怪，并将她平安的消息带到迈斯特拉岗哨后，奥奈雅会给予他们奖赏。",al={"奥奈雅任务","奥奈雅有哪些任务"}},{q="迈斯特拉岗哨为何对哨兵如此重要？",a="迈斯特拉岗哨是一处关卡，将黑海岸的补给路线与灰谷腹地连接起来。守住这里，就能防止敌对势力截断暗夜精灵旅人南下的道路。",al={"为何是迈斯特拉岗哨","迈斯特拉岗哨的重要性"}}},fp="15,191,23.266.0,16.246.0,23.134.0,33.142.0,44.123.0,44.175.0,45.130.0,49.169.0"}
P.entries["npc:sentinel-selarin"] = {n="哨兵塞拉伊",s="在奥伯丁，哨兵塞拉伊正为灰谷的守卫寻求援助。森林危机四伏，她将莱恩·狼行者的求援消息带到了这座海滨聚落。",h="在奥伯丁，哨兵塞拉伊正为灰谷的守卫寻求援助。森林危机四伏，她将莱恩·狼行者的求援消息带到了这座海滨聚落。",kw={"灰谷","奥伯丁","黑海岸","莱恩·狼行者","塞拉伊","哨兵塞拉伊","哨兵","特伦希斯"},ang={["faction:Alliance"]="身为联盟的勇士，你遇见塞拉伊时，她正在帮助旅人从黑海岸南下，进入灰谷战火纷争的荒野。",["race:NightElf"]="身为暗夜精灵，你与Sentinels肩负着共同的职责，守卫kaldorei世代相传的疆界。"},sec={{t="请求增援",b="哨兵塞拉伊将莱恩·狼行者的求援消息从灰谷带到了奥伯丁。灰谷各处的威胁日益增多，驻军已捉襟见肘。塞拉伊沿着林间道路向北进入黑海岸，寻找特伦希斯，向驻守海岸的哨兵和斥候求援。"},{t="召集旅人",b="特伦希斯无法亲自响应塞拉伊的求援，因此她留在奥伯丁，招募途经黑海岸的旅人。她派遣有实力的冒险者南下前往阿斯特兰纳，用刀剑和法术支援莱恩·狼行者陷入困境的部队。"}},faq={{q="哨兵塞拉伊是谁？",a="哨兵塞拉伊是哨兵的一名暗夜精灵战士。她在黑海岸的奥伯丁传递消息，为灰谷的守卫寻求援助。",al={"塞拉伊的故事","塞拉伊是谁","哨兵塞拉伊"}},{q="塞拉伊为什么来到奥伯丁？",a="莱恩·狼行者命令塞拉伊前往奥伯丁寻找特伦希斯，请求增援，以应对灰谷日益加剧的危机。",al={"塞拉伊为什么在黑海岸","塞拉伊的使命","塞拉伊在做什么"}},{q="特伦希斯为什么没有和她一起去灰谷？",a="特伦希斯忙于当地事务，无法前往灰谷。塞拉伊招募自行行动的联盟旅人，代替他南下。",al={"特伦希斯为什么不帮忙","特伦希斯与塞拉伊","特伦希斯忙于事务"}},{q="她派冒险者去哪里？",a="塞拉伊派冒险者向南越过边界，进入灰谷，到阿斯特兰纳向莱恩·狼行者报到。",al={"塞拉伊派我去哪里","塞拉伊任务目的地","塞拉伊之后"}}},fp="16,166,25.278.0,22.268.0,24.135.0,34.129.0,46.146.0,32.108.0"}
P.entries["npc:sentinel-thenysil"] = {n="哨兵塞恩希尔",s="在阿斯特兰纳，哨兵塔拉·塞恩希尔密切关注着灰谷和向南通往石爪山脉的道路。她追踪军队动向，派斥候监视邻近地区，尤其留意南下的盟军。",h="在阿斯特兰纳，哨兵塔拉·塞恩希尔密切关注着灰谷和向南通往石爪山脉的道路。她追踪军队动向，派斥候监视邻近地区，尤其留意南下的盟军。",kw={"灰谷","阿斯特兰纳","凯拉·影矛","哨兵","石爪山脉","塔拉·塞恩希尔","塞恩希尔","泰兰德·语风"},ang={["faction:Alliance"]="作为联盟冒险者，你或许会发现，塞恩希尔是联系灰谷与石爪山脉的纽带，也能让你有机会赢得达纳苏斯领袖们的好感。",["race:Gnome"]="作为侏儒，看到塞恩希尔因一位侏儒法师被派往石爪山脉而感到不安，你或许会想起，你的族人仍能让暗夜精灵感到意外。",["race:NightElf"]="作为暗夜精灵，你能从塞恩希尔身上看到Sentinels对卡利姆多神圣林地的始终守望，以及她们对境外盟友人员的关切。"},sec={{t="守望边境",b="随着敌意日渐加剧，驻守阿斯特兰纳的哨兵塞恩希尔协助守卫着灰谷。这一带的暗夜精灵领地不断遭到蚕食，因此各个哨站必须保持联络。大部分驻军守卫着林间道路，而塞恩希尔则派遣联盟志愿者走出灰谷，支援远方的盟友。"},{t="与石爪山脉的联系",b="哨兵塞恩希尔与凯拉·影矛既是挚友，也是并肩作战的同袍，后者奉命南下，前往石爪山脉执行任务。得知凯拉与一位古怪的侏儒法师一同被派往那里，塞恩希尔认为，这种奇特的组合意味着群山之中出了大麻烦。出于对战友的担忧，她派遣能干的旅行者南下支援，并请他们汇报任务的进展。"},{t="树冠之上的接见",b="斥候从石爪山脉归来，带回消息：他们的打击已经迫使荆棘谷地精收敛了玷污大地的行径。哨兵塞恩希尔知道，阻止这家公司的机械化掠夺，也是在保护邻近的荒野。她赞扬了这些英雄，并派他们前往达纳苏斯的月神殿，女祭司泰兰德·语风将在那里接见他们。"}},faq={{q="在哪里可以找到哨兵塞恩希尔？",a="哨兵塞恩希尔驻守在阿斯特兰纳，那是灰谷中央道路沿线的暗夜精灵主要据点。",al={"塞恩希尔位置","哨兵塞恩希尔在哪里","塞恩希尔阿斯特兰纳"}},{q="塞恩希尔为什么派旅行者前往石爪山脉？",a="塞恩希尔派遣旅行者南下，是因为她的朋友凯拉·影矛与一位侏儒法师一同被派往了石爪山脉。她认为这种不寻常的组合预示着危险，于是派可靠的旅行者去支援凯拉的任务。",al={"为何前往石爪山脉","塞恩希尔石爪山脉任务","石爪山的困境原因"}},{q="凯拉·影矛是谁？",a="凯拉·影矛是一名暗夜精灵斥候，也是哨兵塞恩希尔的挚友。她驻扎在石爪山脉，调查威胁这片土地的事物。",al={"凯拉是谁","凯拉·影矛关系","塞恩希尔的朋友"}},{q="石爪山脉正在对抗什么威胁？",a="荆棘谷地精在石爪山脉开展了侵占土地、破坏环境的工业活动，进行露天采矿并砍伐森林。",al={"石爪山脉威胁","石爪山脉发生了什么","荆棘谷地精石爪山脉"}},{q="塞恩希尔为什么派冒险者去见泰兰德·语风？",a="旅行者帮助凯拉·影矛阻止荆棘谷地精的阴谋后，塞恩希尔便派他们前往达纳苏斯。女祭司泰兰德·语风将亲自表彰他们为暗夜精灵所做的贡献。",al={"泰兰德接见","为何拜见泰兰德","塞恩希尔引荐达纳苏斯"}},{q="哨兵塞恩希尔在阿斯特兰纳负责什么？",a="塞恩希尔在阿斯特兰纳关注当地情报和边境动向，并派遣可靠的联盟新兵支援远方的驻军。",al={"塞恩希尔军衔","塞恩希尔做什么","哨兵塞恩希尔职责"}}},fp="17,197,20.302.0,18.388.0,22.377.1,37.105.0,57.220.0,25.144.0,44.133.0,58.196.1,46.138.0"}
P.entries["npc:sentinel-tysha-moonblade"] = {n="哨兵坦莎·月刃",s="哨兵坦莎·月刃守望着黑海岸道路旁动荡不安的海岸。这位暗夜精灵斥候驻守在亚米萨兰以西，为旅人指路，并寻求援手，平息附近废墟中徘徊不散的亡魂。",h="哨兵坦莎·月刃守望着黑海岸道路旁动荡不安的海岸。这位暗夜精灵斥候驻守在亚米萨兰以西，为旅人指路，并寻求援手，平息附近废墟中徘徊不散的亡魂。",kw={"亚米萨兰","奥伯丁","黑海岸","上层精灵","暗夜精灵","哨兵","坦莎·月刃"},ang={["faction:Alliance"]="作为从奥伯丁南下前往灰谷的联盟旅人，你可以在这条怪物出没、危机四伏的道路上，找到为数不多的友方哨所之一。",["race:NightElf"]="作为暗夜精灵，你可以让受诅咒的先祖安息，帮助Sentinels维护这片饱受古老的Sundering摧残的土地上的安宁。"},sec={{t="道路上的守望",b="哨兵坦莎·月刃守望着穿过黑海岸的道路。她的东面是亚米萨兰废墟，受诅咒的上层精灵幽魂与恶毒的女妖在古老的石柱间徘徊。沿海的重重危险让奥伯丁的防御力量捉襟见肘，因此坦莎请求有能力的旅人查明亚米萨兰陷落的往事，并消灭那里不得安息的亡者。"}},faq={{q="哨兵坦莎·月刃是谁？",a="哨兵坦莎·月刃在黑海岸中部的主路上巡逻，就在亚米萨兰以西。她守卫着这条道路，抵御游荡的野兽和不得安息的幽魂。",al={"坦莎是谁","坦莎·月刃背景故事","哨兵坦莎"}},{q="在哪里可以找到哨兵坦莎·月刃？",a="你可以在黑海岸贯通南北的道路旁找到哨兵坦莎·月刃，她就在亚米萨兰的正西方。",al={"坦莎·月刃位置","坦莎在哪里","哨兵坦莎在哪里"}},{q="她会交给冒险者什么任务？",a="坦莎派旅人前往亚米萨兰，调查摧毁这座古老暗夜精灵聚落的惨剧，并让倒塌石柱间饱受折磨的幽魂安息。",al={"坦莎·月刃任务","亚米萨兰陷落任务发布者","坦莎想要什么"}},{q="她在黑海岸有亲人吗？",a="目前没有关于坦莎亲属的消息。她独自守望着亚米萨兰以西的道路，守护着闹鬼废墟旁的通路。",al={"坦莎·月刃家人"}}},fp="24,188,19.326.0,32.159.0,42.103.0,40.164.0,43.125.0"}
P.entries["npc:sentinel-velene-starstrike"] = {n="哨兵维尔莉妮·星坠",s="在银风避难所，哨兵维尔莉妮·星坠守卫着灰谷中部。她保护着这处庇护所及附近的水域，抵御失控的元素和邪恶的巫师，防止他们的魔法腐蚀这片古老的林地。",h="在银风避难所，哨兵维尔莉妮·星坠守卫着灰谷中部。她保护着这处庇护所及附近的水域，抵御失控的元素和邪恶的巫师，防止他们的魔法腐蚀这片古老的林地。",kw={"灰谷","元素护腕","法师召唤者","密斯特拉湖","哨兵","银风避难所","星击","维尔莉妮"},ang={["class:Mage"]="身为法师，你或许会发现，维尔莉妮对鲁莽的施法者缺乏耐心，因为他们的召唤法术会激起当地元素的躁动，污染自然水域。",["faction:Alliance"]="身为联盟旅人，你可以在危险的旅途中到银风避难所寻求庇护。维尔莉妮协调各方力量，保护灰谷中部。",["race:NightElf"]="身为暗夜精灵，你能看到维尔莉妮守护灰谷的决心，她抵御鲁莽施用的魔法，维护森林的平衡。"},sec={{t="银风的守护者",b="在密斯特拉湖畔，哨兵维尔莉妮·星坠驻守银风避难所，警戒四周。遍布灰谷的暗夜精灵哨兵致力于维护森林的平衡，保卫精灵的庇护所。银风避难所为穿行于森林中部的旅人提供歇脚之处，维尔莉妮则协助守护这一带的安全。"},{t="密斯特拉湖的骚动",b="银风避难所周围的安宁很容易被打破。维尔莉妮监视着密斯特拉湖，桀骜不驯的元素之灵和鲁莽的法师召唤者正在那里扰乱荒野。她指引勇士们对抗失控的水元素，以及那些惊扰大地之灵的莽撞施法者。"}},faq={{q="哨兵维尔莉妮·星坠在哪里？",a="哨兵维尔莉妮·星坠驻守在灰谷中部的银风避难所，靠近密斯特拉湖东南岸。",al={"维尔莉妮·星坠位置","维尔莉妮在哪","银风避难所任务发布者"}},{q="哨兵维尔莉妮会指派什么任务？",a="维尔莉妮派冒险者收集躁动元素的护腕，并阻止那些在密斯特拉湖周围水域制造事端的失控召唤者。",al={"维尔莉妮·星坠任务","维尔莉妮发布什么任务"}},{q="密斯特拉湖面临什么威胁？",a="凶暴的水元素在密斯特拉湖肆虐，凡人的法师召唤者煽动并利用它们，施法时全然不顾森林的平衡。",al={"密斯特拉湖的问题","密斯特拉湖为什么有元素"}},{q="维尔莉妮与卡利姆多的其他人有亲属关系吗？",a="维尔莉妮与莱耶·星击有着相同的姓氏星击，后者是一名驻守在遥远南方希利苏斯的暗夜精灵。他们可能出自同一血脉或家族。",al={"星击家族","莱耶·星击亲属"}},{q="银风避难所是什么地方？",a="银风避难所是灰谷密斯特拉湖畔的一处暗夜精灵休憩地。它为哨兵以及穿越森林腹地荒野的盟友旅人提供庇护，也是一处战术前哨。",al={"银风避难所是什么","银风避难所背景故事"}},{q="哨兵为什么关心元素的活动？",a="暗夜精灵将荒野视为神圣而充满生机的生态系统。狂暴或堕落的元素会扰乱野生生灵和水道，因此哨兵会出手干预，恢复平衡。",al={"暗夜精灵为什么对抗元素","哨兵与元素"}}},fp="26,223,22.289.0,28.283.0,44.121.0,39.144.0,35.146.0,45.156.0,26.197.0,51.175.0"}
P.entries["npc:serge-hinott"] = {n="瑟尔格·希诺特",s="在塔伦米尔，瑟尔格·希诺特调制药剂，支援被遗忘者的战事。这位被遗忘者炼金师与药剂师林度恩共事，为皇家药剂师学会配制药剂、解毒剂和试剂。",h="在塔伦米尔，瑟尔格·希诺特调制药剂，支援被遗忘者的战事。这位被遗忘者炼金师与药剂师林度恩共事，为皇家药剂师学会配制药剂、解毒剂和试剂。",kw={"药剂师林度恩","希尔斯布莱德丘陵","希诺特","皇家药剂师学会","瑟尔格·希诺特","塔伦米尔"},ang={["class:Rogue"]="身为潜行者，你可以向希诺特求取解药，治疗毒性猛烈的赞吉尔之触。常规疗法无效时，他会配制解毒剂。",["race:Undead"]="身为亡灵，你能在希尔斯布莱德看到皇家药剂师学会的实际工作：调制化学药剂，为前线的被遗忘者部队提供支援。"},sec={{t="塔伦米尔的药剂师助手",b="瑟尔格·希诺特在塔伦米尔为被遗忘者配制治疗药物和其他药剂。他与药剂师林度恩共事，后者的工作包括开发化学制剂，以及针对南海镇等附近人类定居点的瘟疫研究。希诺特负责配制专用药剂，包括供外勤人员和斥候使用的治疗药膏和解毒剂，以应对中毒或其他毒物事故。"}},faq={{q="在哪里可以找到瑟尔格·希诺特？",a="瑟尔格·希诺特在塔伦米尔的室外工作，这座城镇位于希尔斯布莱德丘陵中部偏北。他就在药剂师林度恩附近，周围摆放着制药材料和炼金设备。",al={"瑟尔格·希诺特位置","希诺特在哪","寻找瑟尔格·希诺特"}},{q="瑟尔格·希诺特担任什么职务？",a="瑟尔格·希诺特是塔伦米尔的一名炼金师，为被遗忘者效力。他配制当地所需的药剂和治疗药物，也应外勤人员和信使的要求调制专用药剂。",al={"希诺特做什么","瑟尔格·希诺特职责"}},{q="希诺特与药剂师林度恩有什么关系？",a="瑟尔格·希诺特在塔伦米尔与药剂师林度恩共事。访客打断他的工作时，希诺特会叫他们去烦那位“高高在上的先生”。",al={"希诺特与林度恩","希诺特与谁共事"}}},fp="12,187,32.358.0,32.166.0,34.188.0,48.150.0"}
P.entries["npc:shadow-priest-allister"] = {n="暗影牧师奥利斯特",s="在瑟伯切尔，暗影牧师奥利斯特指挥着被遗忘者在银松森林各地的行动。他监视附近的威胁，协助黑暗女王巩固洛丹伦的边界。",h="在瑟伯切尔，暗影牧师奥利斯特指挥着被遗忘者在银松森林各地的行动。他监视附近的威胁，协助黑暗女王巩固洛丹伦的边界。",kw={"奥利斯特","安伯米尔","达拉然","被遗忘者","神圣香肠","瑟伯切尔","暗影牧师","银松森林"},ang={["class:Priest"]="身为牧师，你能从《Holy Bologna》的作者奥利斯特身上，看出被遗忘者牧师群体对Light的幻灭。",["faction:Horde"]="身为部落的一员，你与奥利斯特共同致力于保卫银松森林，确保部落盟友能安全往来于提瑞斯法林地与南方地区之间。",["race:Undead"]="身为Undead，你与奥利斯特一样奉行冷酷的实用主义，保护自己的族人免受生者侵害。"},sec={{t="瑟伯切尔的守望者",b="暗影牧师奥利斯特在银松森林的瑟伯切尔指挥被遗忘者斥候。他以这座定居点为据点，监视叛逆的人类、野兽，以及达拉然周边的奥术活动。"},{t="紧盯安伯米尔与达拉然",b="奥利斯特最关心的是达拉然幸存的法师，尤其是那些在安伯米尔越境试探的法师。他绝不允许肯瑞托在被遗忘者的土地上站稳脚跟。他的探员截下信使，破译奥术符文，探查这些法师的长远意图。"},{t="异端之思",b="除了履行战略家的职责，奥利斯特还潜心研究暗影。他撰写了《神圣的胡扯: 光明不会告诉你的事情》，尖锐抨击传统的神圣教义。书中探讨了亡灵生存的残酷现实，以及圣光未能援助那些被生命抛弃之人的事实。不知何故，这本书竟流传到了卡利姆多的厄运之槌废墟。"}},faq={{q="暗影牧师奥利斯特是谁？",a="暗影牧师奥利斯特是银松森林瑟伯切尔的一名被遗忘者牧师。他协调针对附近威胁的监视与打击行动，尤其关注达拉然的势力。",al={"奥利斯特","暗影牧师奥利斯特","银松森林奥利斯特是谁"}},{q="在哪里能找到暗影牧师奥利斯特？",a="你可以在瑟伯切尔找到暗影牧师奥利斯特，那是贯穿银松森林的道路上最主要的被遗忘者定居点。",al={"奥利斯特位置","暗影牧师奥利斯特在哪","寻找奥利斯特"}},{q="奥利斯特为何关注达拉然和安伯米尔？",a="安伯米尔的肯瑞托法师威胁着被遗忘者的领土。奥利斯特致力于破译他们的通信，查明他们的意图，并遏制他们的影响。",al={"奥利斯特达拉然","为何攻击安伯米尔","达拉然对银松森林的威胁"}},{q="奥利斯特写过什么书？",a="奥利斯特撰写了《神圣的胡言乱语: 光明不会告诉你的事情》，尖锐批判圣光，这本书还传入了大洋彼岸厄运之槌的古老图书馆。",al={"奥利斯特的书","神圣的胡扯","圣光不会告诉你的事"}},{q="奥利斯特提供哪些任务？",a="奥利斯特在银松森林提供多项情报收集任务，包括越境、地图与符记、调查安伯米尔，以及对付达拉然探员的行动。",al={"奥利斯特任务","瑟伯切尔暗影牧师任务"}},{q="奥利斯特为何修习暗影魔法，而非信奉圣光？",a="许多被遗忘者牧师死后感到自己被圣光抛弃，奥利斯特也像他们一样转向了暗影。他从接纳亡灵之身的修行中找到了力量与决心。",al={"为何成为暗影牧师","被遗忘者暗影魔法奥利斯特"}}},fp="22,173,24.217.0,29.293.0,17.353.0,30.175.0,40.121.0,49.163.0,29.163.0,32.180.0,66.169.0"}
P.entries["npc:shadow-priest-sarvis"] = {n="暗影牧师萨维斯",s="在丧钟镇破败的礼拜堂里，暗影牧师萨维斯指引着刚刚苏醒的被遗忘者。他为他们指明目标，派他们对付无意识的亡灵和当地的威胁。",h="在丧钟镇破败的礼拜堂里，暗影牧师萨维斯指引着刚刚苏醒的被遗忘者。他为他们指明目标，派他们对付无意识的亡灵和当地的威胁。",kw={"丧钟镇","被遗忘者","新兵艾尔雷斯","萨维斯","暗影牧师萨维斯","提瑞斯法林地"},ang={["class:Priest"]="身为牧师，你会看到萨维斯作为被遗忘者的导师，在一座失去圣光的礼拜堂中使用暗影魔法。",["race:Undead"]="身为 Undead，你从坟墓中苏醒后，最先听到的几个声音中就有萨维斯的声音。他引领你走上为黑暗女王效力的道路。"},sec={{t="初醒者的引路人",b="暗影牧师萨维斯指引着那些刚从丧钟镇的坟墓中爬出的被遗忘者。苏醒的过程可能令人惊恐不安，有些会陷入狂乱或绝望，失去理智。萨维斯为这些新生者指明目标。他派他们消灭在墓地游荡的无意识尸体，并保卫丧钟镇的边界，抵御 天灾军团。"},{t="保卫丧钟镇",b="暗影牧师萨维斯也指挥着丧钟镇的防御，应对提瑞斯法林地中的威胁。天灾军团 部队试探着镇子的外围防线，萨维斯则派新手收集重要情报，接受战斗的试炼。被遗忘者必须守住丧钟镇，抵挡这些部队。"}},faq={{q="暗影牧师萨维斯是谁？",a="萨维斯是丧钟镇的一名被遗忘者暗影牧师。他指引刚刚苏醒的亡灵，向他们下达最初的命令，并协助保卫镇子，抵御 天灾军团。",al={"萨维斯","萨维斯 是谁","丧钟镇牧师"}},{q="在哪里可以找到暗影牧师萨维斯？",a="暗影牧师萨维斯在提瑞斯法林地丧钟镇中央的破败教堂内等候。",al={"萨维斯 位置","萨维斯 在哪里","寻找 萨维斯"}},{q="萨维斯为什么让玩家杀死无意识的僵尸？",a="有些从坟墓中复生的尸体失去了自由意志和理智。被遗忘者视他们为定居点的威胁，在他们危及其他活死人之前将其消灭。",al={"为什么杀死 无脑的僵尸","无脑的僵尸"}}},fp="20,108,30.341.0,19.262.0,28.165.0,38.95.0,51.178.0"}
P.entries["npc:shael-dryn"] = {n="莎尔蒂恩",s="在纯净月亮井旁，莎尔蒂恩注视着腐化在灰谷蔓延。她在伊瑞斯湖以东，帮助暗夜精灵斥候和阿斯特兰纳的哨兵处理受到恶魔与邪恶力量污染的遗物。",h="在纯净月亮井旁，莎尔蒂恩注视着腐化在灰谷蔓延。她在伊瑞斯湖以东，帮助暗夜精灵斥候和阿斯特兰纳的哨兵处理受到恶魔与邪恶力量污染的遗物。",kw={"灰谷","塞纳留斯","净化","树妖","伊莉亚娜","莱恩·狼行者","林歌","莎尔蒂恩"},ang={["class:Druid"]="作为德鲁伊，你能体会莎尔蒂恩与卡利姆多诸灵之间的天然联系，也能珍视她在帮助受黑暗力量扭曲的动植物恢复原貌方面的见解。",["faction:Alliance"]="作为联盟的一员，你可以将Moonwell of Purity视为灰谷中的庇护所。莎尔蒂恩协助联盟部队抵抗腐化与敌对势力的侵扰。",["race:NightElf"]="作为Kaldorei，你可以将莎尔蒂恩视为森林中的姐妹。她与塞纳留斯的天然联系，让她在净化受污染的林地遗物时不可或缺。"},sec={{t="月亮井的守护者",b="在纯净月亮井旁，莎尔蒂恩与暗夜精灵哨兵一同守望着森林东面的通路。当腐化侵染当地的野生动物，或受污染的遗物威胁这片土地的和谐时，她便凭借对自然的深刻理解，指引冒险者恢复灵魂的平衡。"},{t="净化森林",b="莎尔蒂恩与阿斯特兰纳的莱恩·狼行者携手合作。当哨兵寻回受污染的器物，包括被腐化的发光宝石和达图尔的变形魔棒遗失的部件时，她知道净化它们所需的隐秘仪式、月亮井水和自然信物。这些器物由此成为联盟强大的净化工具。"}},faq={{q="莎尔蒂恩是谁？",a="莎尔蒂恩是一位树妖，居于灰谷的纯净月亮井旁。她向联盟冒险者传授林地知识与自然魔法，也会讲些双关语和笑话。",al={"她是谁","莎尔蒂恩背景故事","莎尔蒂恩身份"}},{q="在哪里可以找到莎尔蒂恩？",a="莎尔蒂恩在灰谷伊瑞斯湖以东的纯净月亮井旁等候。",al={"莎尔蒂恩位置","莎尔蒂恩在哪里","林中树居树妖"}},{q="莎尔蒂恩与莱恩·狼行者有什么联系？",a="莱恩·狼行者指引冒险者前去请教莎尔蒂恩的灵性知识。她帮助调查并净化从森林各处寻回的腐化宝石和遗物。",al={"莱恩·狼行者与莎尔蒂恩","莱恩·狼行者的净化树妖","为何派我去找莎尔蒂恩"}},{q="莎尔蒂恩的外貌有什么独特之处？",a="莎尔蒂恩与同为树妖的伊莉亚娜有着相同的罕见体色，这让她们有别于卡利姆多各地的大多数树妖。",al={"树妖模型","独特肤色","莎尔蒂恩体色"}},{q="莎尔蒂恩对部落友好吗？",a="不友好。莎尔蒂恩驻守在纯净月亮井旁，与阿斯特兰纳哨兵关系密切。她对部落成员抱有敌意。",al={"部落能否与莎尔蒂恩交谈","部落声望","莎尔蒂恩是否仅限联盟"}}},fp="10,201,24.270.0,25.319.1,18.162.0,28.79.0,52.179.0,45.142.0,36.147.0"}
P.entries["npc:shanda"] = {n="珊达",s="在奥达希尔，珊达指引年轻的暗夜精灵牧师研习Elune之道。她在幽影谷为The Sisterhood of Elune效力，传授祷言、结界与仪式，让学生们为保卫泰达希尔做好准备。",h="在奥达希尔，珊达指引年轻的暗夜精灵牧师研习Elune之道。她在幽影谷为The Sisterhood of Elune效力，传授祷言、结界与仪式，让学生们为保卫泰达希尔做好准备。",kw={"奥达希尔","艾露恩","暗夜精灵","牧师训练师","幽影谷","珊达","艾露恩姐妹会","泰达希尔"},ang={["class:Priest"]="作为一名在幽影谷起步的暗夜精灵牧师，你可以向珊达求教神圣的祷言，在Elune的恩泽中获得指引。",["race:NightElf"]="身为暗夜精灵，你继承了The Sisterhood of Elune的传统。珊达关怀着那些刚在泰达希尔迈出第一步的Kaldorei年轻人的精神福祉。"},sec={{t="月亮母亲的侍僧",b="珊达在奥达希尔指引信奉艾露恩的年轻暗夜精灵。德鲁伊照料泰达希尔的根须与枝干，女祭司则维系着卡多雷与白女士之间的联系。珊达教导新入门的学徒祈求月光的恩泽，用以治疗伤痛、施放防护结界，让他们准备好面对正悄然侵入世界之树枝干的腐化。"},{t="指引新晋学徒",b="在幽影谷感召之下踏上牧师之路的年轻人，会来找珊达证明自己的虔诚，学习最初的祷言。她通过月神的恩赐等仪式考验他们的决心，赐予他们受过祝福的法衣，并传授基础咒语。她的学生学习以温柔的双手照料伤者，并在阴影面前坚守阵地。"}},faq={{q="珊达是谁？",a="珊达在奥达希尔内训练暗夜精灵牧师，这处中空巨树中的聚落位于泰达希尔的幽影谷中心。她向刚刚觉醒的牧师传授艾露恩姐妹会之道。",al={"这个非玩家角色是谁","珊达的故事","奥达希尔牧师训练师"}},{q="珊达对新晋牧师有何作用？",a="珊达向牧师学徒传授基础祷言、治疗法术，以及艾露恩赐予的防护魔法。新晋牧师将神圣符记带给她，她则通过月神的恩赐引导他们进入下一阶段的训练。",al={"牧师训练师的作用","珊达教什么","珊达做什么"}},{q="在哪里可以找到珊达？",a="珊达位于泰达希尔的幽影谷，在奥达希尔中空树干内部的底层。",al={"珊达在哪里","珊达的位置","如何找到珊达"}},{q="珊达属于什么组织？",a="珊达属于艾露恩姐妹会，这个古老的暗夜精灵女祭司组织，数千年来一直指引着卡多雷的精神与文化生活。",al={"珊达的阵营","艾露恩姐妹会","珊达是月之女祭司吗"}}},fp="6,204,26.335.0,21.353.0,14.185.0,43.222.0,24.88.0,40.162.0"}
P.entries["npc:shandris-feathermoon"] = {n="珊蒂斯·羽月",s="珊蒂斯·羽月是哨兵军队的将军，一万年来始终是泰兰德·语风的左膀右臂。如今，她坐镇菲拉斯近海萨尔多岛上的羽月要塞，指挥遍布卡利姆多的暗夜精灵部队。",h="珊蒂斯·羽月是哨兵军队的将军，一万年来始终是泰兰德·语风的左膀右臂。如今，她坐镇菲拉斯近海萨尔多岛上的羽月要塞，指挥遍布卡利姆多的暗夜精灵部队。",kw={"羽月","菲拉斯","将军","卡多雷","萨尔多岛","哨兵","珊蒂斯","泰兰德"},ang={["class:Hunter"]="猎人和游侠尊崇珊蒂斯，视她为Sentinels中最出色的神射手之一，一位守护暗夜精灵长达一万年的将军。",["faction:Alliance"]="对于深入卡利姆多南部的联盟部队而言，羽月将军提供了至关重要的海军力量、战略指挥，以及萨尔多岛上一处防御森严的庇护所。",["faction:Horde"]="部落视羽月将军为危险而狡猾的军事战略家，她位于菲拉斯近海的堡垒威胁着他们在这一地区的扩张。",["race:NightElf"]="在Kaldorei眼中，羽月将军是哨兵纪律与职责的最高典范，自漫长守望开始之初便一直守护着族人。"},sec={{t="泰兰德的左膀右臂",b="珊蒂斯·羽月是暗夜精灵最年长的守护者之一。一万年来，她始终在泰兰德·语风身边效力，作为大祭司在哨兵中的左膀右臂，度过了大灾变之后的漫长守望。"},{t="哨兵的崛起",b="大灾变之后，随着哨兵的建立，珊蒂斯成为暗夜精灵军中不可或缺的指挥官。"},{t="菲拉斯的堡垒",b="如今，羽月将军担任哨兵军队的最高战地指挥官。她驻守萨尔多岛，统领羽月要塞，这座宏伟的精灵堡垒守望着菲拉斯的原始荒野。从这座海岛前哨，她监视着不断逼近的威胁：野蛮的豺狼人、盘踞不去的戈杜尼食人魔、满怀仇恨的萨特，以及部落在卡利姆多南部不断扩张的势力。"}},faq={{q="珊蒂斯·羽月是谁？",a="珊蒂斯·羽月是哨兵的将军，这支部队是暗夜精灵的常备军。作为一名年长的暗夜精灵，她一万年来始终是大祭司泰兰德·语风的左膀右臂，并在菲拉斯的羽月要塞指挥哨兵。",al={"珊蒂斯是谁","珊蒂斯的背景故事","菲拉斯的暗夜精灵将军是谁"}},{q="在哪里可以找到珊蒂斯·羽月？",a="她在羽月要塞发号施令，要塞坐落于卡利姆多南部、菲拉斯西海岸外的萨尔多岛上。",al={"珊蒂斯的位置","珊蒂斯·羽月在哪里","羽月要塞的领袖"}},{q="珊蒂斯与泰兰德·语风是什么关系？",a="一万年来，珊蒂斯始终是泰兰德·语风在哨兵中的左膀右臂。泰兰德在达纳苏斯领导暗夜精灵，而珊蒂斯则从羽月要塞指挥哨兵军队在前线作战。",al={"珊蒂斯是泰兰德的女儿吗","泰兰德与珊蒂斯","泰兰德收养的孩子"}},{q="珊蒂斯曾与燃烧军团交战吗？",a="这里讲述的历史没有记载她与燃烧军团交战的事迹。已知的是，她一万年来始终在哨兵中追随泰兰德·语风，如今则从羽月要塞指挥哨兵军队。",al={"上古之战中的珊蒂斯","珊蒂斯曾与阿克蒙德交战吗"}},{q="她为什么驻守菲拉斯，而非泰达希尔？",a="身为哨兵的将军，珊蒂斯必须指挥卡利姆多各地的前线军事行动。羽月要塞是联盟在南方蛮荒森林中的主要集结地和堡垒，监视着敌对食人魔、萨特以及部落的动向。",al={"珊蒂斯为什么在菲拉斯","为什么是羽月要塞"}}},fp="20,181,20.229.0,21.124.0,22.330.0,28.242.0,40.111.0,55.232.0,46.213.0,54.250.0"}
P.entries["npc:shari-stilwell"] = {n="Shari Stilwell",s="在布瑞尔，Shari Stilwell 教导被遗忘者踏上圣骑士之路。她驻守在提瑞斯法林地，能忍受圣光之痛的亡灵在这里学习神圣之道与战斗技艺。",h="在布瑞尔，Shari Stilwell 教导被遗忘者踏上圣骑士之路。她驻守在提瑞斯法林地，能忍受圣光之痛的亡灵在这里学习神圣之道与战斗技艺。",kw={"布瑞尔","被遗忘者","圣光","圣骑士","莎莉","斯迪威尔","提瑞斯法","训练师"},ang={["class:Paladin"]="作为一名在提瑞斯法林地起步的被遗忘者圣骑士，你可以在布瑞尔找到你的主要训练师和导师 Shari Stilwell。",["race:Undead"]="作为一名亡灵旅者，你从 Shari Stilwell 身上看到了第三次战争如何拆散家庭：她教导着被遗忘者，而可能与她有亲缘关系的人却生活在遥远的南方。"},sec={{t="布瑞尔的明灯",b="在布瑞尔，Shari Stilwell 指引着那些寻求成为神圣战士的被遗忘者。圣光会给亡灵带来剧痛，但她仍教导那些愿意忍受痛苦的人。她通过初步训练，帮助新来者适应被遗忘者的生活，在提瑞斯法林地站稳脚跟。接受她指引的人，都在寻求自己在被遗忘者王国中的一席之地。"},{t="斯迪威尔姓氏的纽带",b="莎莉 与达芙妮、梅里萨以及乔丹·斯迪威尔同姓，乔丹是南方诸王国生者之中一位著名的铁匠。究竟是洛丹伦的陷落使 莎莉 与这些亲族失散，还是他们本就只是远亲，在 天灾军团 造成的浩劫中，这仍是未知之事。"}},faq={{q="莎莉·斯迪威尔 是谁？",a="莎莉·斯迪威尔 是提瑞斯法林地布瑞尔的一位亡灵圣骑士训练师。她为被遗忘者圣骑士提供初步的战斗与神圣之道训练，指引他们学会在洛丹伦生存。",al={"莎莉·斯迪威尔 是谁","莎莉·斯迪威尔 的故事","布瑞尔圣骑士训练师"}},{q="在哪里可以找到 莎莉·斯迪威尔？",a="可以在提瑞斯法林地的布瑞尔镇找到 莎莉，就在首都废墟和幽暗城以北不远处。",al={"莎莉·斯迪威尔 的位置","莎莉·斯迪威尔 在哪里","寻找 莎莉·斯迪威尔"}},{q="莎莉 与乔丹·斯迪威尔有亲属关系吗？",a="莎莉 与著名的人类铁匠乔丹·斯迪威尔同姓，也与达芙妮和梅里萨·斯蒂维尔同姓。他们确切的亲属关系尚不清楚，不过，摧毁洛丹伦的瘟疫可能已切断了这份联系。",al={"与乔丹·斯迪威尔的关系","斯迪威尔 家族关系","莎莉·斯迪威尔 的亲属"}},{q="被遗忘者能以圣骑士的身份运用圣光吗？",a="圣光会给亡灵带来强烈的痛苦与灼烧。莎莉·斯迪威尔 指引意志坚定的被遗忘者培养所需的虔诚与精神韧性，以便在施展战斗技艺的同时运用圣光之力。",al={"被遗忘者 圣骑士","亡灵如何成为圣骑士","亡灵圣骑士的故事"}}},fp="14,196,17.337.0,25.265.0,22.166.0,34.98.0,36.212.0,41.190.0"}
P.entries["npc:shelene-rhobart"] = {n="舍伦尼·洛巴尔特",s="舍伦尼·洛巴尔特在提瑞斯法道路旁的一处亡灵卫兵驿站训练制皮师。她提供熟化毛皮和制皮训练，支援被遗忘者在这片枯萎土地上的军事与后勤行动。",h="舍伦尼·洛巴尔特在提瑞斯法道路旁的一处亡灵卫兵驿站训练制皮师。她提供熟化毛皮和制皮训练，支援被遗忘者在这片枯萎土地上的军事与后勤行动。",kw={"布瑞尔","被遗忘者的皮革","制皮","舍伦尼·洛巴尔特","提瑞斯法林地"},ang={["race:Undead"]="身为Undead，你可以看到，在提瑞斯法的腐朽与荒凉之中，实用的手艺如何帮助当地守军置办装备。"},sec={{t="为被遗忘者制作装备",b="在布瑞尔东南方的一处亡灵卫兵驿站，舍伦尼·洛巴尔特沿着通往洛丹伦废墟的大路劳作。即使成为亡灵，实用的手艺对生存和战争依然重要。她将提瑞斯法游荡野兽的皮毛制成坚韧的皮革、护甲、皮带和野外装备，供对抗天灾军团和血色十字军的被遗忘者巡逻队使用。"}},faq={{q="在哪里可以找到舍伦尼·洛巴尔特？",a="舍伦尼·洛巴尔特位于提瑞斯法林地布瑞尔东南方的一处被遗忘者小哨站，就在通往幽暗城的道路旁。",al={"舍伦尼·洛巴尔特位置","舍伦尼·洛巴尔特在哪里","舍伦尼·洛巴尔特地图"}},{q="舍伦尼·洛巴尔特负责什么？",a="舍伦尼·洛巴尔特训练制皮师熟化毛皮、缝制服装，并为被遗忘者制作防护皮具。",al={"舍伦尼·洛巴尔特做什么","舍伦尼·洛巴尔特训练师","舍伦尼专业"}},{q="她为什么需要野兽的皮？",a="被遗忘者用动物皮修补受损的身体，因为亡灵的皮肤无法愈合。舍伦尼的储备日渐短缺，她需要夜行蝙蝠翼膜、黑暗犬的皮和邪鳍鱼人的皮肤；不同的厚度适合身体的不同部位。",al={"被遗忘者的皮革任务","为什么在提瑞斯法收集毛皮"}}},fp="15,206,25.347.0,33.117.0,37.124.0,30.267.0"}
P.entries["npc:shenthul"] = {n="申苏尔",s="在奥格瑞玛的暗影裂口，申苏尔训练潜行者，并为碎手氏族效力。他指挥着遍及卡利姆多的秘密行动，将有潜力的潜行者招入其中。",h="在奥格瑞玛的暗影裂口，申苏尔训练潜行者，并为碎手氏族效力。他指挥着遍及卡利姆多的秘密行动，将有潜力的潜行者招入其中。",kw={"暗影裂口","丛林巨魔","奥格瑞玛","潜行者训练师","碎手氏族","申苏尔","荆棘谷地精","狂风峭壁"},ang={["class:Rogue"]="作为奥格瑞玛的潜行者，你可以向申苏尔学习，接受入会试炼，并承担秘密任务。",["faction:Horde"]="在奥格瑞玛地下，申苏尔指挥着部落的秘密情报行动，应对来自内部与外部的威胁。",["race:Troll"]="作为巨魔，你可以了解丛林巨魔申苏尔是如何加入曾为兽人氏族的碎手氏族的。"},sec={{t="洞穴中的耳目",b="申苏尔在奥格瑞玛的暗影裂口训练潜行者。当战士和萨满祭司在杜隆塔尔公开行军时，他传授的却是潜行、伏击与诡计。他的学生学习野外行动技巧与致命技艺，以便在卡利姆多严酷的荒野和冷酷的政治斗争中执行任务。"},{t="破碎之手",b="申苏尔代表碎手氏族发言，这个组织曾是一个兽人氏族，如今则是部落的情报网络和特务机构。他将其描述为遍布卡利姆多的警觉力量，负责调查、裁决，并亲自执行判决。申苏尔行事务实，不受政治风向左右，他提醒外人，碎手氏族在大酋长萨尔掌权之前就已存在，在他之后也将延续下去。"},{t="秘密外勤",b="申苏尔指挥着争夺中领土上的秘密行动。他派出特工潜入敌对势力，并让他们用狂风峭壁一带荆棘谷地精上锁的补给箱练习开锁。新成员必须面对严苛的试炼，而当外勤特工身中剧毒时，申苏尔会确保他们在毒发身亡之前找到解药。"}},faq={{q="申苏尔是谁？",a="申苏尔在奥格瑞玛地下的暗影裂口训练丛林巨魔潜行者，并为碎手氏族效力。",al={"申苏尔职责","申苏尔是谁","奥格瑞玛巨魔潜行者训练师"}},{q="在哪里可以找到申苏尔？",a="申苏尔位于暗影裂口，那是一片洞穴群，穿过奥格瑞玛较为阴暗的隧道便可抵达。",al={"申苏尔位置","申苏尔在哪里","申苏尔 暗影裂口"}},{q="申苏尔与碎手氏族有什么关系？",a="申苏尔为碎手氏族效力，这是部落的秘密情报组织和刺客公会，他也负责招募潜行者加入其中。",al={"碎手氏族 申苏尔","申苏尔属于碎手氏族吗","申苏尔属于什么阵营"}},{q="申苏尔如何看待大酋长萨尔？",a="申苏尔说，碎手氏族在萨尔掌权之前就已存在，在他之后也将延续下去。他将公会的事务与部落的安危置于变幻不定的政治局势之上。",al={"申苏尔对萨尔的看法","申苏尔喜欢萨尔吗","申苏尔的忠诚"}},{q="申苏尔为潜行者提供哪些任务？",a="申苏尔引导潜行者完成入会试炼和秘密潜入任务。他还指引他们前往石爪山脉的狂风峭壁一带，用荆棘谷地精上锁的补给箱练习开锁。",al={"申苏尔任务","潜行者任务 申苏尔"}},{q="申苏尔会协助潜行者处理毒药问题吗？",a="会。当外勤特工身中致命剧毒时，申苏尔会指引他们向希诺特寻求解药。",al={"申苏尔毒药任务","希诺特援助 申苏尔"}}},fp="8,160,17.268.0,18.361.0,16.339.1,16.110.0,26.106.0,52.126.0,44.167.0,44.215.0,40.89.0"}
P.entries["npc:shindrell-swiftfire"] = {n="辛德瑞尔·速火",s="阿斯特兰纳的防务延伸到了灰谷的森林之外。辛德瑞尔·速火是一名暗夜精灵哨兵兼斥候，她在这座城镇中保持警戒，这里是暗夜精灵在灰谷的行动中心。她密切关注卡利姆多西部不断变化的危险，指引干练的联盟冒险者应对海岸和附近山口的威胁，协助协调当地防务，抵御来自海洋与荒野的危险。",h="阿斯特兰纳的防务延伸到了灰谷的森林之外。辛德瑞尔·速火是一名暗夜精灵哨兵兼斥候，她在这座城镇中保持警戒，这里是暗夜精灵在灰谷的行动中心。她密切关注卡利姆多西部不断变化的危险，指引干练的联盟冒险者应对海岸和附近山口的威胁，...",kw={"灰谷","阿斯特兰纳","娜迦","巨翼雄兽","哨兵","辛德瑞尔","石爪山脉","速火","佐拉姆海岸"},ang={["class:Hunter"]="身为猎人，你或许能理解追踪pridewings和勘察荒僻海岸的价值，这些工作适合懂得如何在荒野中生存的斥候与游侠。",["faction:Alliance"]="作为初到阿斯特兰纳的联盟成员，你可以依靠辛德瑞尔协调行动，指引你深入卡利姆多中部纷争不断、危机四伏的地区。",["race:NightElf"]="身为暗夜精灵，你眼中的辛德瑞尔是警惕的哨兵之一，在大部分兵力对抗部落时，守护灰谷边陲，抵御娜迦这样的古老仇敌。"},sec={{t="阿斯特兰纳的警戒者",b="辛德瑞尔·速火在阿斯特兰纳蜿蜒的步道上，注视着灰谷之外的边地。哨兵们抵御着部落从东面和南面发起的伐木入侵，而辛德瑞尔则留意着林地之外的动静。旅人从黑海岸来到这里，或启程前往石爪山脉嶙峋的山岭，她协助确保阿斯特兰纳面对侧翼的危险时仍有防备。"},{t="海岸上的威胁",b="灰谷西北海岸的佐拉姆海岸危机四伏，引起了辛德瑞尔的注意。敌对的娜迦从深海中涌现，这既是一个令人不安的谜团，也直接威胁着卡多雷的聚居地。辛德瑞尔派遣身经百战的勇士调查海岸，并与沿海的斥候协调行动，力图在这些蛇形入侵者于暗夜精灵的古老土地上站稳脚跟之前遏制他们。"}},faq={{q="在哪里可以找到辛德瑞尔·速火？",a="辛德瑞尔·速火驻守在阿斯特兰纳，这座城镇是暗夜精灵在灰谷的中心。她在镇中的木制步道间协调侦察工作，接待往来的旅人。",al={"辛德瑞尔·速火位置","辛德瑞尔在哪","寻找辛德瑞尔·速火"}},{q="辛德瑞尔在阿斯特兰纳担任什么职责？",a="辛德瑞尔在阿斯特兰纳协调斥候的行动，并指引联盟冒险者应对城镇之外的威胁。这些威胁包括西部海岸的娜迦，以及附近山脉中的野兽。",al={"辛德瑞尔做什么","辛德瑞尔·速火是谁","辛德瑞尔职责"}},{q="她为何派斥候前往佐拉姆海岸？",a="敌对的娜迦涌上灰谷西部海岸，占据废墟，威胁着暗夜精灵的边境。辛德瑞尔派遣冒险者侦察海滩，协助前线的哨兵遏制这些蛇形敌人带来的威胁。",al={"为何前往佐拉姆海岸","辛德瑞尔娜迦任务","佐拉姆海岸任务"}},{q="辛德瑞尔与石爪山脉有什么联系？",a="塞拉摩的秘密线人报告说，兽人刺客正在石爪山脉暗色湖附近从巨翼双足飞龙身上采集毒液，用于针对联盟的秘密袭击。辛德瑞尔派遣冒险者收集毒囊，阻止部落获取这种毒药。",al={"石爪山脉任务","风巢双足飞龙任务","为何前往石爪山脉"}},{q="辛德瑞尔与黑暗深渊有联系吗？",a="辛德瑞尔与黑暗深渊没有直接联系。她派遣冒险者对付佐拉姆海岸的怒尾娜迦，黑暗深渊就位于这片西北海岸，但她并不派人进入黑暗深渊。",al={"辛德瑞尔黑暗深渊","黑暗深渊联系"}},{q="凯尼斯·静风是谁，辛德瑞尔为何提起他？",a="凯尼斯·静风是一名德鲁伊，驻守在灰谷东部的林歌神殿。他担忧腐化正在森林中蔓延，便请辛德瑞尔提供一份关于海岸和阿斯特兰纳的报告；她派遣冒险者将报告送到他手中。",al={"凯尼斯是谁","凯尼斯·静风任务","凯尼斯联系"}}},fp="19,255,27.351.0,23.416.0,37.153.0,38.186.0,45.211.0,48.273.0,46.205.0,61.230.0"}
P.entries["npc:shoni-the-shilent"] = {n="沉默的舒尼",s="在暴风城的矮人区，沉默的舒尼派出一支队伍，深入西部荒野的地下。她领导侏儒夺回诺莫瑞根，并为那些准备打通重返城内道路的机器寻找动力。",h="在暴风城的矮人区，沉默的舒尼派出一支队伍，深入西部荒野的地下。她领导侏儒夺回诺莫瑞根，并为那些准备打通重返城内道路的机器寻找动力。",kw={"死亡矿井","矮人区","挖掘机","侏儒","自动旋钻机","沉默","舒尼","暴风城"},ang={["profession:Engineering"]="身为工程师，你能领会舒尼的gyrodrillmatic excavationators在机械构造上的精妙，她希望用从月溪镇地下回收的切割机核心为它们提供动力。",["race:Gnome"]="身为侏儒，帮助舒尼能让你的同胞离重返诺莫瑞根、夺回沦陷的家园更近一步。"},sec={{t="地下指挥官",b="沉默的舒尼在暴风城的矮人区指挥着一支侏儒突击队。诺莫瑞根被穴居人占据，她计划夺回这座城市，并派遣特工进入西部荒野下方的隧道，寻找队伍所需的零件。"},{t="地下收复行动",b="舒尼的计划依靠侏儒的回旋式挖掘机，这些重型机器旨在突破诺莫瑞根的地下边界，为突击开辟道路。这些机器缺乏动力，因此她想从死亡矿井深处一台仍在运转的地精切割机上，取得完好的小型高能发动机。她还派遣冒险者进入诺莫瑞根，拆解那里的机器人，获取备用零件来修复她的机群。"}},faq={{q="沉默的舒尼是谁？",a="沉默的舒尼在暴风城的矮人区领导诺莫瑞根地下突击队。她负责协调夺回这座城市的行动。",al={"舒尼是谁","舒尼的故事","沉默的舒尼非玩家角色"}},{q="在哪里可以找到舒尼？",a="你可以在暴风城矮人区的铁砧与工坊之间找到舒尼，就在锻造和工程学区域附近。",al={"舒尼在哪里","舒尼位置","寻找舒尼"}},{q="舒尼为什么对死亡矿井感兴趣？",a="死亡矿井深处有一台仍在运转的地精切割机。舒尼想取得其中完好的小型高能发动机，为陀螺钻掘机提供动力，突破诺莫瑞根的地下边界。",al={"舒尼 死亡矿井","为什么派人去死亡矿井","旋转式挖掘机任务"}},{q="她为什么被称为“沉默的舒尼”？",a="无人知晓舒尼这个称号的由来。她指挥着诺莫瑞根地下突击队。",al={"舒尼的绰号","为什么叫沉默","沉默的侏儒"}}},fp="17,185,21.232.0,24.396.0,25.148.0,23.125.0,41.215.0,32.98.0"}
P.entries["npc:sicco-thermaplugg"] = {n="麦克尼尔·瑟玛普拉格",s="在诺莫瑞根的废墟中，麦克尼尔·瑟玛普拉格身披庞大的机械战甲，统治着这座城市。他曾是大工匠格尔宾·梅卡托克信任的顾问，却为了夺权，让整座城市遭受了辐射污染。放射性尘埃将他变成了麻风侏儒，也让他精神错乱，如今仍统治着残破的厅堂。",h="在诺莫瑞根的废墟中，麦克尼尔·瑟玛普拉格身披庞大的机械战甲，统治着这座城市。他曾是大工匠格尔宾·梅卡托克信任的顾问，却为了夺权，让整座城市遭受了辐射污染。放射性尘埃将他变成了麻风侏儒，也让他精神错乱，如今仍统治着残破的厅...",kw={"群体打击者","诺莫瑞根","麻风侏儒","梅卡托克","瑟科","瑟玛普拉格","工匠的宫廷","石腭怪"},ang={["faction:Alliance"]="瑟玛普拉格的背叛让诺莫瑞根未能响应第三次战争的征召。在人类最黑暗的时刻，这场背叛重创了联盟的补给线和工程支援。",["profession:Engineering"]="瑟玛普拉格展现了草率的配方和毫无准则的设计会带来怎样的致命危险。他驱使危险的步行战争机器和剧毒炸弹投放器，对付所有踏入他工坊的人。",["race:Dwarf"]="你在铁炉堡的同胞收留了那些逃离瑟玛普拉格毒害的幸存者。铁炉堡的守卫严密把守着丹莫罗的关口，防范他麾下那些遭受辐射的游荡者。",["race:Gnome"]="瑟玛普拉格身上凝聚着你的族人所有的悲痛与憎恶。他的虚荣和背叛让你们失去了家园，也让你们的同胞变成了疾病缠身的怪物。"},sec={{t="剧毒的野心",b="多年来，麦克尼尔·瑟玛普拉格一直辅佐大工匠格尔宾·梅卡托克，深得他的信任。然而，瑟玛普拉格暗中觊觎着大工匠之位。就连梅卡托克也说不清，究竟是什么驱使自己的顾问背叛了这份信任。他只能猜想，瑟玛普拉格追求的究竟是权力还是财富，而这两样东西，他迟早都能得到。"},{t="诺莫瑞根的毒灾",b="第三次战争期间，石腭怪从地下涌入诺莫瑞根，侏儒们在黑暗中与它们交战。为了寻找解围之策，格尔宾向瑟玛普拉格征求意见。瑟玛普拉格力劝他向全城释放放射性毒气，声称这能消灭石腭怪，却不会伤害侏儒。他真正的意图，是利用这场危机推翻梅卡托克，夺取大权。"},{t="废墟之王",b="瑟玛普拉格的豪赌酿成了惨剧。放射性尘埃席卷了诺莫瑞根的每一层，夺走了八成侏儒的性命，还将许多幸存者扭曲成了野蛮、病态的麻风侏儒。辐射也让瑟玛普拉格的身体发生畸变，使他彻底陷入疯狂。\n\n瑟玛普拉格自封为侏儒之王，在遭受辐射的机械与变异奴仆之间发号施令。他的部队既与入侵的石腭怪作战，也对抗那些试图夺回失落家园的地表侏儒。"}},faq={{q="麦克尼尔·瑟玛普拉格是谁？",a="在石腭怪入侵期间背叛族人之前，麦克尼尔·瑟玛普拉格曾是大工匠格尔宾·梅卡托克的首席顾问。他力劝梅卡托克向诺莫瑞根释放放射性毒气，以便趁机夺权。毒气几乎灭绝了城中的侏儒，而瑟玛普拉格如今则以疯狂国王的身份，统治着遭受辐射的废墟。",al={"瑟玛普拉格是谁","瑟玛普拉格的传说","诺莫瑞根的首领是谁","瑟玛普拉格的过往"}},{q="瑟玛普拉格为什么背叛格尔宾·梅卡托克？",a="就连梅卡托克也无法确定瑟玛普拉格为何背叛自己。大工匠猜想，瑟玛普拉格追求的或许是权力或财富，而这两样东西，他迟早都能得到。瑟玛普拉格早已觊觎大工匠之位，并利用石腭怪危机将诺莫瑞根据为己有。",al={"他为何背叛诺莫瑞根","瑟玛普拉格的动机","瑟 瑟科为何憎恨格尔宾"}},{q="石腭怪入侵是瑟玛普拉格造成的吗？",a="石腭怪从奥达曼这座古老的泰坦宝库中被挖掘出来，随后首次闯入了诺莫瑞根的下层。传言称，瑟玛普拉格知道这处突破口，甚至曾出手促成入侵，借此制造危机。梅卡托克始终未能证实，瑟玛普拉格究竟是发动了入侵，还是仅仅利用了它。",al={"他召唤了石腭怪吗","是瑟科引来了石腭怪吗","诺莫瑞根石腭怪入侵的起因"}},{q="毒气释放后，瑟玛普拉格发生了什么？",a="瑟玛普拉格和其他数千名侏儒一同遭受了致命的辐射。放射性尘埃使他的血肉枯萎，皮肤变成病态的绿色，心智也随之崩溃。他没有随幸存的难民逃往铁炉堡，而是留下来，自封为侏儒之王，统治这片废墟。",al={"瑟玛普拉格是麻风侏儒吗","他如何变成麻风侏儒","瑟玛普拉格为何变绿"}},{q="群体打击者9-60是什么？",a="群体打击者9-60是一台庞大的侏儒战争机器，至今仍迈着沉重的步伐穿行于诺莫瑞根的工程实验室。守卫瑟玛普拉格那片辐射领地的机械卫士为数众多，它便是其中之一。",al={"群体打击者的起源"}},{q="大工匠梅卡托克希望如何处置瑟玛普拉格？",a="梅卡托克将瑟玛普拉格视为自己最大的失败，也是族人中最大的叛徒。他在铁炉堡侏儒区的临时宫廷中，委托勇敢的联盟冒险者深入诺莫瑞根遭受辐射的区域，处决瑟玛普拉格。他要为死难者讨回公道。",al={"格尔宾的瑟玛普拉格任务","击杀瑟玛普拉格的任务","梅卡托克想让他死吗"}}},fx={["83ef33e1"]={q="麦克尼尔·瑟玛普拉格效忠哪一方？",a="瑟玛普拉格只为自己和他扭曲的野心效命。他让放射性毒气充斥诺莫瑞根，迫使幸存者流亡，背叛了联盟和自己的同胞。如今，他与外界隔绝，深受辐射侵蚀，统领着留在废城中的麻风侏儒，以疯狂暴君的姿态统治他们，同时对抗入侵的穴居人，以及任何胆敢闯入他领地的外来者。",al={"瑟玛普拉格阵营","瑟玛普拉格为谁效力","瑟科 瑟玛普拉格效忠对象"}},["4bd94cd3"]={q="麦克尼尔·瑟玛普拉格想要什么？",a="瑟玛普拉格想保住他夺来的王冠。他自封侏儒之王，在这座沦为废墟的都城深处统治着残存的麻风侏儒和机器，拒绝放弃王权，尽管梅卡托克称他是个一无所有的国王。",al={"瑟玛普拉格目标","瑟玛普拉格在谋划什么","瑟科 瑟玛普拉格动机"}},["7e175e39"]={q="麦克尼尔·瑟玛普拉格为什么在这里？",a="瑟玛普拉格仍盘踞在诺莫瑞根工程区的深处，因为他在灾难期间夺取了这座沦陷的城市。他没有随幸存的侏儒逃往铁炉堡，而是留下来占据空荡的大厅，统领那些与他一同发生变异的麻风侏儒。他以工匠议会为据点，继续在这场城市灾难的中心指挥防御工事、机器和扭曲的追随者。",al={"瑟玛普拉格为何在诺莫瑞根","瑟玛普拉格为何留下","瑟玛普拉格在此原因"}},cac8a4d9={q="麦克尼尔·瑟玛普拉格为何出名，又为何令人畏惧？",a="瑟玛普拉格是侏儒历史上最大的叛徒，因而臭名昭著。他曾是大工匠梅卡托克备受赞誉的首席顾问，但他的背叛直接导致诺莫瑞根遭受辐射污染，绝大多数居民丧生。侏儒们对他的背叛深感恐惧，既害怕他掌控的致命机器，也害怕如今支配他暴虐统治的彻底疯狂。",al={"瑟玛普拉格为何令人畏惧","瑟玛普拉格名声","侏儒为何憎恨瑟玛普拉格"}}},fp="21,290,16.343.0,27.366.1,17.460.1,29.333.0,46.288.0,41.306.0,56.295.0,32.199.0,61.289.0"}
P.entries["npc:sida"] = {n="塞达",s="塞达住在米奈希尔港，与感情不和的丈夫埃纳尔·石钳分居。她平日在这座湿地港口度日，偶尔也会深入沼泽，最近一次外出时，她在铁须之墓附近丢失了背包。",h="塞达住在米奈希尔港，与感情不和的丈夫埃纳尔·石钳分居。她平日在这座湿地港口度日，偶尔也会深入沼泽，最近一次外出时，她在铁须之墓附近丢失了背包。",kw={"埃纳尔·石钳","铁须之墓","米奈希尔港","软泥怪","塞达","湿地"},ang={["faction:Alliance"]="作为抵达米奈希尔港码头的联盟旅人，你可以从塞达那里接取当地的差事，沿路深入内陆，前往铁须之墓一带。",["race:Dwarf"]="身为矮人，你能在米奈希尔港见到日常的城镇生活，也能看到家庭纷争，以及城门外荒野中的种种危险。"},sec={{t="港口居民",b="塞达住在湿地的联盟港口米奈希尔港，与埃纳尔·石钳分居。两人的婚姻关系紧张，只要塞达还住在那里，埃纳尔就不肯前往米奈希尔。她有时仍会离开这座沿海城镇，深入湿地。最近一次前往铁须之墓时，她丢失了随身的背包。"}},faq={{q="塞达是谁？",a="塞达是一名矮人女性，住在湿地的米奈希尔港。她会向途经港口的冒险者发布任务。",al={"塞达是谁","塞达非玩家角色","湿地塞达"}},{q="塞达的背包出了什么事？",a="塞达探访铁须之墓时丢失了背包，那是湿地的一处古老墓地。污秽的软泥怪遍布那里，吞掉了她的物品。",al={"塞达的背包在哪里","丢失的背包","铁须之墓背包"}},{q="埃纳尔·石钳为什么不肯去米奈希尔港？",a="埃纳尔·石钳是与塞达感情不和的丈夫。两人之间的积怨让他一直避开米奈希尔港，只要塞达还住在那里，他就不肯前往。",al={"埃纳尔和塞达","塞达的丈夫","埃纳尔·石钳的纷争"}},{q="在哪里可以找到塞达？",a="你可以在湿地西海岸的米奈希尔港，沿着码头和道路找到塞达。",al={"塞达的位置","塞达在哪里"}}},fp="4,216,17.307.0,12.123.0,28.153.0,48.127.0,24.95.0"}
P.entries["npc:sirra-von-indi"] = {n="希拉·沃宁迪",s="在夜色镇，希拉·沃宁迪研究着记载暮色森林历史的档案。这位镇上的历史学家通晓古代语言，帮助解读神秘文献，探寻这片地区的往昔。",h="在夜色镇，希拉·沃宁迪研究着记载暮色森林历史的档案。这位镇上的历史学家通晓古代语言，帮助解读神秘文献，探寻这片地区的往昔。",kw={"亚伯克隆比","夜色镇","暮色森林","历史学家","摩根·拉迪莫尔","希拉","镇公所","翻译","沃宁迪","饱经风霜的墓碑"},ang={["class:Mage"]="作为一名到访夜色镇的法师，你或许能看出希拉·沃宁迪治学的严谨。他对古代语言和历史的研究，与肯瑞托开展的档案研究颇为相似。",["faction:Alliance"]="作为一名联盟旅人，你能看到希拉·沃宁迪在这片被黑暗吞噬的行省中，帮助维系夜色镇的市镇生活，保存暴风城王国的历史传承。"},sec={{t="镇上的历史学家",b="在夜色镇大厅，希拉·沃宁迪保管着镇上的档案。当镇上的卫兵应对林中的威胁时，他研读古籍，保存着阴影笼罩这片地区之前Grand Hamlet的历史。"},{t="解读隐士的文字",b="当夜色镇的领袖开始怀疑住在暮色森林山丘上的隐士亚伯克隆比时，他们请希拉·沃宁迪翻译他的笔记。他的语言知识帮助议会理解那些来自闹鬼森林的古怪要求。"},{t="往昔的悲剧",b="希拉·沃宁迪知道夜色镇墓地中一座风化坟墓背后的悲伤往事。他是少数还记得圣骑士摩根·拉迪莫尔如何堕落的人之一，并向旅人讲述相关往事，帮助他们让不安的灵魂安息。"}},faq={{q="希拉·沃宁迪是谁？",a="希拉·沃宁迪是夜色镇的人类学者，也是镇上的官方历史学家。他在镇公所研究古老技艺，翻译晦涩的语言，并保管镇上的历史档案。",al={"希拉是谁","希拉·沃宁迪背景故事","夜色镇历史学家"}},{q="在哪里可以找到希拉·沃宁迪？",a="在暮色森林中部的夜色镇大厅可以找到希拉·沃宁迪。他站在书桌与书架之间，查阅历史文献。",al={"希拉在哪里","希拉·沃宁迪位置","夜色镇寻找希拉"}},{q="他在处理亚伯克隆比的便笺时起什么作用？",a="当隐士亚伯克隆比的一张古怪便笺送到艾尔罗·埃伯洛克公爵手中，而镇公所里无人能读懂时，希拉·沃宁迪便负责翻译。他的工作帮助议会理解亚伯克隆比的古怪要求。",al={"亚伯克隆比信件译者","翻译亚伯克隆比便笺","希拉便笺翻译"}},{q="希拉知道摩根·拉迪莫尔的哪些往事？",a="希拉·沃宁迪知道埋葬在饱经风霜的墓碑中的堕落圣骑士摩根·拉迪莫尔的完整经历。他讲述了拉迪莫尔在第三次大战之后陷入疯狂与悲剧的经过。",al={"希拉 饱经风霜的墓碑","摩根·拉迪莫尔背景故事 希拉","饱经风霜的墓碑的故事"}},{q="希拉为什么在翻译时让旅人等待？",a="希拉·沃宁迪翻译时，常常请旅人给他一些时间。解读晦涩的方言和陈旧的手迹需要细心，他还会交叉核对参考资料，确保译文可靠。",al={"希拉为何忙碌","等待希拉完成","希拉翻译等待"}}},fp="14,189,18.226.0,30.257.1,21.245.1,22.181.0,34.140.0,47.211.0,43.184.0,53.203.0"}
P.entries["npc:sister-aquinne"] = {n="艾奎恩妮",s="在达纳苏斯，艾奎恩妮在月神殿随艾露恩祭司团修习。这位初入门的侍僧在神殿花园服侍。",h="在达纳苏斯，艾奎恩妮在月神殿随艾露恩祭司团修习。这位初入门的侍僧在神殿花园服侍。",kw={"艾奎恩妮","达纳苏斯","神殿花园","月神殿"},ang={["class:Priest"]="身为牧师，你能在艾奎恩妮接受基础训练时感受到她的虔诚，这是服侍月神殿的侍僧必修的功课。",["race:NightElf"]="身为来到达纳苏斯的暗夜精灵，你可以在神殿花园遇见艾奎恩妮，初步了解神殿的祭司群体。"},sec={{t="达纳苏斯的侍僧",b="艾奎恩妮在暗夜精灵的首都随艾露恩祭司团修习。她驻守在月神殿下方的神殿花园，向高阶女祭司和年长的姐妹们学习。当一只曾经强大的森林生灵需要帮助时，艾奎恩妮指引热心的旅行者前往神殿内，向女祭司艾茉拉了解该如何行动。"}},faq={{q="在哪里可以找到艾奎恩妮？",a="艾奎恩妮位于达纳苏斯的神殿花园，就在月神殿外。",al={"艾奎恩妮位置","艾奎恩妮在哪里","艾奎恩妮坐标"}},{q="艾奎恩妮有着怎样的背景？",a="艾奎恩妮是一位初入门的艾露恩的女祭司，在达纳苏斯的月神殿修习。她进入神殿服侍之前的生活鲜为人知。",al={"艾奎恩妮故事","艾奎恩妮是谁","艾奎恩妮背景"}}},fp="14,149,20.342.0,34.100.0,36.164.0"}
P.entries["npc:skorn-whitecloud"] = {n="斯考恩·白云",s="在血蹄村，年迈的牛头人猎人斯考恩·白云指引着年轻猎人，并帮助旅人应对莫高雷的危险。",h="在血蹄村，年迈的牛头人猎人斯考恩·白云指引着年轻猎人，并帮助旅人应对莫高雷的危险。",kw={"血蹄村","平原徘徊者","莫高雷","斯考恩","牛头人","猎人之道","白云"},ang={["class:Hunter"]="作为一名年轻的牛头人猎人，你可以向斯考恩·白云学习如何潜行追踪flatland prowler这类敏捷的捕食者，并尊重狩猎中的灵性和谐。",["race:Tauren"]="作为牛头人，你可以从斯考恩身上看到长者的职责：传承狩猎的荣耀，以及在平原上度过漫长岁月所积累的实用智慧。"},sec={{t="金色平原上的引路人",b="斯考恩·白云住在莫高雷的血蹄村，在那里教导年轻猎人狩猎之道。他教导他们尊重平原上的野生生灵。立志成为猎人的年轻人要挑战狡猾的平原徘徊者，证明自己，再将利爪带给雷霆崖的梅洛·石蹄。斯考恩希望那些拿起弓矛的人能理解捕食者与猎物之间的平衡。"},{t="警惕异常之兆",b="斯考恩·白云留意着莫高雷草原上的异常动静。平原上的野生动物和野兽身上可能出现恶魔腐化的迹象。每当这些迹象出现，斯考恩便会协助查明事情的来龙去脉，让各部族警惕侵入祖居之地的邪恶力量。"}},faq={{q="在哪里可以找到斯考恩·白云？",a="斯考恩·白云就在血蹄村，那是位于莫高雷南部草原的牛头人聚落。",al={"斯考恩·白云位置","斯考恩在哪","斯考恩·白云地图"}},{q="斯考恩对年轻猎人起着什么作用？",a="斯考恩·白云通过猎人之道教导年轻猎人狩猎的准则。他派他们去挑战狡猾的平原徘徊者，证明自己的追踪与战斗本领，再指引他们前往雷霆崖寻找梅洛·石蹄。",al={"斯考恩做什么","斯考恩猎人任务","猎人之道"}},{q="斯考恩出售什么货物？",a="猎人若能带来巨狼鬼嚎已被击杀的证据，斯考恩·白云便会给予斯考恩的战锤或斯考恩的火枪。他亲自狩猎的日子已经结束了。",al={"斯考恩商人","斯考恩卖什么","斯考恩武器"}},{q="斯考恩·白云与莫高雷的其他牛头人有亲属关系吗？",a="莫高雷没有提及斯考恩·白云的任何亲属。人们只知道他是血蹄村的一位老猎人，狩猎生涯早已结束。",al={"白云家族","斯考恩亲属"}}},fp="16,105,28.391.0,31.285.1,36.86.0,44.237.0,27.158.0,59.133.0"}
P.entries["npc:skuerto"] = {n="斯奎尔图",s="斯奎尔图是一名矮人斥候，驻扎在阿拉希高地的避难谷地。他奉大法师马林之命，与学徒克里汀一同来到这里，在野外协助联盟，为马林收回魔法遗物。",h="斯奎尔图是一名矮人斥候，驻扎在阿拉希高地的避难谷地。他奉大法师马林之命，与学徒克里汀一同来到这里，在野外协助联盟，为马林收回魔法遗物。",kw={"阿拉希高地","大法师马林","铁炉堡","避难谷地","斥候","斯奎尔图","特雷莱恩"},ang={["race:Dwarf"]="斯奎尔图体现了在联盟荒野边疆服役的矮人所具有的坚韧，不过，他身为斥候的自尊很容易受到伤害。"},sec={{t="高地上的斥候",b="斯奎尔图是一名来自铁炉堡的矮人，在危机四伏的阿拉希高地担任斥候。他与学徒克里汀一同驻扎在避难谷地，听从大法师马林的指示，找回奥术材料和强大的魔法物品，这些东西曾属于马林的昔日导师 大法师特雷莱恩。"},{t="自傲与险境",b="尽管高地的环境恶劣，斯奎尔图仍对自己的野外侦察本领颇为自豪，谁若质疑他的能力，他便会心生不快。他在执行任务时经常遭遇当地的种种危险，从充满敌意的辛迪加和石拳食人魔，到与这片土地有着联系的危险远古存在。"}},faq={{q="斯奎尔图为何驻扎在阿拉希，而不是铁炉堡？",a="是大法师马林派他来的。斯奎尔图和学徒克里汀被派往避难谷地，收集材料，并找回马林的昔日导师 大法师特雷莱恩 留下的物品；这位法师在激流堡遭到围攻时逃离了那里。",al={"斯奎尔图为何在这里","斯奎尔图的过往"}},{q="斯奎尔图在避难谷地的任务是什么？",a="大法师马林派斯奎尔图和学徒克里汀前往阿拉希高地，收集奥术材料，并找回曾属于马林昔日导师 大法师特雷莱恩 的强大魔法物品。",al={"斯奎尔图的使命","斯奎尔图做什么","斯奎尔图 马林"}},{q="斯奎尔图在这一带有哪些盟友？",a="他直接与学徒克里汀以及驻守避难谷地的联盟守军合作，学徒克里汀是他执行大法师马林所托任务的搭档。",al={"斯奎尔图的朋友"}}},fx={["9a7bedf3"]={q="斯奎尔图是谁？",a="斯奎尔图是驻扎在阿拉希高地避难谷地的铁炉堡矮人斥候。他以侦察本领为傲，也格外经不起批评；他代表联盟在野外行动，与学徒克里汀并肩工作。",al={"斯奎尔图是谁","斯奎尔图的身份","矮人斯奎尔图是谁"}},["1cc8a254"]={q="斯奎尔图属于哪一方？",a="斯奎尔图坚定地效忠联盟和铁炉堡。他以避难谷地的联盟营地为据点，与达拉然法师及当地联盟部队协同行动，对抗笼罩阿拉希高地的威胁。",al={"斯奎尔图的阵营","斯奎尔图是联盟的吗","斯奎尔图效忠于谁"}},["5f13d7e3"]={q="斯奎尔图想要什么？",a="斯奎尔图想完成大法师马林交给他的任务：获取魔法试剂，并找回曾属于马林昔日导师、大法师特雷兰的强大失落神器，同时维护自己作为能干斥候的声誉。",al={"斯奎尔图想要什么","斯奎尔图的目标","斯奎尔图的动机"}},["44066d31"]={q="斯奎尔图与谁有关联？",a="除了在大法师马林手下、与学徒克里汀并肩工作，斯奎尔图还与驻守阿拉希高地避难谷地的联盟守军站在一起。",al={"斯奎尔图的关系","斯奎尔图的关联","斯奎尔图认识谁"}}},fp="7,228,24.264.0,15.226.0,56.206.0,43.146.0,39.130.0"}
P.entries["npc:smith-argus"] = {n="铁匠阿古斯",s="在闪金镇的熔炉旁，铁匠阿古斯为旅人与当地铁匠提供补给。他修理装备，教导新手铁匠，向赤脊山运送马蹄铁，并与暴风城的工匠协调供货。",h="在闪金镇的熔炉旁，铁匠阿古斯为旅人与当地铁匠提供补给。他修理装备，教导新手铁匠，向赤脊山运送马蹄铁，并与暴风城的工匠协调供货。",kw={"铁匠","艾尔文森林","熔炉","闪金镇","马蹄铁","狮王之傲","铁匠阿古斯","训练师","弗纳·奥斯古"},ang={["profession:Blacksmithing"]="对于从艾尔文起步的联盟角色来说，阿古斯可能是他们的第一位锻造老师。他教授粗制铜装备和实用物品的入门配方。",["profession:Mining"]="矿工将金属带到闪金镇的熔炉旁，阿古斯在那里教新手铁匠将其打造成实用的工具。",["race:Human"]="阿古斯体现了艾尔文手艺人在政务疏忽与匪患动荡之中依然辛勤劳作的生活。"},sec={{t="闪金镇的铁砧",b="铁匠阿古斯在闪金镇狮王之傲旅店附近的熔炉旁工作。豺狼人、狗头人和迪菲亚匪徒威胁着这一带，但阿古斯仍为当地民兵和过往冒险者提供装备。他修补护甲，打造结实的工具。身为锻造训练师，他教新手铁匠加工铜和青铜。"},{t="城镇间的贸易与需求",b="闪金镇地处要冲，使铁匠阿古斯成为暴风城地区物资供应的一环。附近聚落的工匠会找他获取专用装备和原材料。赤脊山的蹄铁匠弗纳·奥斯古依靠阿古斯为驮畜和骑兵打造马蹄铁。暴风城矮人区的金属工匠也通过他安排货物运送。"}},faq={{q="在哪里可以找到铁匠阿古斯？",a="铁匠阿古斯在艾尔文森林中部的闪金镇工作，就在护甲店后方的露天铁砧与熔炉旁，靠近狮王之傲旅店。",al={"阿古斯位置","铁匠阿古斯在哪里","铁匠阿古斯 艾尔文"}},{q="铁匠阿古斯提供哪些服务？",a="阿古斯向新手铁匠传授基础技艺。他在经典旧世中的头衔是中级铁匠。",al={"阿古斯教什么","阿古斯训练师","闪金镇锻造训练师"}},{q="为什么赤脊山的铁匠会让我去找铁匠阿古斯？",a="湖畔镇的工匠弗纳·奥斯古需要马蹄铁，确保补给车队和坐骑在应对黑石兽人的威胁时能够继续行进。他委托闪金镇的阿古斯打造并供应这些马蹄铁。",al={"马掌任务","弗纳马蹄铁","为什么阿古斯供应马蹄铁"}},{q="阿古斯与暴风城有什么联系？",a="阿古斯与暴风城的矮人铁匠协调物资运送，其中包括矮人区的格瑞曼德·艾尔默。",al={"艾尔默的任务","暴风城狮鹫 阿古斯"}},{q="铁匠阿古斯能教授进阶或高级锻造吗？",a="阿古斯教授锻造的入门技艺。更高深的技术需要向较大聚落中经验更丰富的大师学习。",al={"阿古斯高级铁匠","阿古斯能训练到多高"}},{q="铁匠阿古斯属于某个特定的公会吗？",a="阿古斯是暴风城王国的忠诚臣民，也是艾尔文森林当地为联盟效力的工匠群体的一员。",al={"阿古斯阵营","阿古斯公会"}}},fp="11,190,22.303.0,28.347.0,29.136.0,39.91.0,57.189.0,45.118.0,55.124.0,48.136.0"}
P.entries["npc:sneed"] = {n="斯尼德",s="在死亡矿井深处，斯尼德指挥着迪菲亚潜行者的木材作业。他在Mast Room驾驶着自己设计的重型伐木机，为艾德温·范克里夫的秘密巨舰采伐木材。",h="在死亡矿井深处，斯尼德指挥着迪菲亚潜行者的木材作业。他在Mast Room驾驶着自己设计的重型伐木机，为艾德温·范克里夫的秘密巨舰采伐木材。",kw={"死亡矿井","艾德温·范克里夫","地精","巨舰","伐木主管","桅杆室","伐木机","斯尼德","斯尼德的伐木机"},ang={["faction:Alliance"]="作为联盟的一员，你可以切断斯尼德运往铁甲湾的木材供应，重创迪菲亚潜行者的造船计划。",["profession:Engineering"]="斯尼德的定制伐木机展现了地精工艺的特点：高效、火力强大，而且为了速度，运转强度远超常规安全限度。",["race:Gnome"]="作为侏儒，你或许一眼就能看出斯尼德的机器体现了地精的巧思：噪声震耳、危险重重，建造时全然不顾舒适性和结构的耐久性。"},sec={{t="迪菲亚伐木主管",b="迪菲亚潜行者的成员大多是人类石匠和劳工，但建造铁甲战舰需要各行各业的熟练工匠。艾德温·范克里夫看中了斯尼德的工程学知识和冷酷高效的作风，将他招入麾下。斯尼德在地下铁路网旁的Mast Room工作。他在那里指挥木材的采伐、切割和加工，为范克里夫的庞大无畏舰提供木料。"},{t="残酷的生产",b="斯尼德只在乎削减成本和完成定额，丝毫不顾后果。他驾驶一台装有超大圆锯的定制伐木机，指挥作业。机器的锯刃能在几秒内将原木加工成造船用的木料。当入侵者将他逼入绝境时，斯尼德便凭借机器的装甲与他们周旋，逐步将其击溃。如果机器被毁，他就从残骸中爬出来，赤手空拳地继续战斗。"}},faq={{q="斯尼德是谁？",a="斯尼德是一名为艾德温·范克里夫效力的地精工程师兼伐木主管。他负责死亡矿井中的木材作业，为迪菲亚巨舰提供木料。",al={"斯尼德是谁","斯尼德背景故事","斯尼德是什么"}},{q="在哪里能找到斯尼德？",a="斯尼德在桅杆室工作，那是月溪镇地下的死亡矿井中，一间位于矿道铁轨旁的锯木室。",al={"斯尼德位置","斯尼德在哪里","斯尼德房间"}},{q="为什么一个地精会为迪菲亚潜行者效力？",a="艾德温·范克里夫需要专业的工业知识，也需要尽快造好他的秘密战舰。他雇用了像斯尼德这样唯利是图的地精，只要报酬丰厚，他们就很少在乎政治或道德。",al={"斯尼德为何加入迪菲亚","死亡矿井中的地精","迪菲亚为何雇用地精"}},{q="斯尼德在战斗中驾驶什么？",a="斯尼德驾驶着斯尼德的伐木机，这是一台配有锯刃的重型双足机器，由他亲手打造，能以极快的速度采伐和切割木材。",al={"斯尼德机器人","斯尼德机甲","斯尼德的伐木机"}},{q="他的伐木机被摧毁后会发生什么？",a="摧毁伐木机并不意味着战斗结束。斯尼德会从残骸中爬出来，徒步继续与入侵者战斗。",al={"斯尼德第二阶段","斯尼德离开伐木机","斯尼德会随伐木机一起死吗"}},{q="斯尼德加工的木材用来建造什么？",a="斯尼德加工的木材顺流而下，运往铁甲湾，兄弟会正在那里建造一艘巨型战舰，准备反击暴风城。",al={"斯尼德为何伐木","桅杆室用途","死亡矿井木材"}}},fp="5,199,23.370.0,20.360.0,13.134.0,25.111.0,51.197.0,33.123.0,44.116.0,34.136.0"}
P.entries["npc:sneed-s-shredder"] = {n="斯尼德的伐木机",s="在死亡矿井深处，斯尼德的伐木机既砍伐木材，也守卫工场。地精工头斯尼德驾驶这台机器，为艾德温·范克里夫的造船工匠效力，并用它的刀刃对付入侵者。",h="在死亡矿井深处，斯尼德的伐木机既砍伐木材，也守卫工场。地精工头斯尼德驾驶这台机器，为艾德温·范克里夫的造船工匠效力，并用它的刀刃对付入侵者。",kw={"圆锯","死亡矿井","迪菲亚","地精","木材","遥控器","伐木机","斯尼德","范克里夫"},ang={["faction:Alliance"]="身为联盟的一员，你可以击败斯尼德和他的机器，瘫痪为艾德温·范克里夫的秘密战争舰队提供支援的伐木场。",["profession:Engineering"]="身为工程师，你可以用侏儒通用遥控器短暂接管伐木机。",["race:Gnome"]="身为侏儒，你知道沉默的舒尼想要这台地精制造的机器里的动力装置，用来驱动钻机，进攻诺莫瑞根。"},sec={{t="工业恐怖",b="在死亡矿井的铸造厂里，地精伐木机砍伐木材，为艾德温·范克里夫秘密建造的巨型战舰提供材料。它们也凭借装甲之躯迎击入侵者。斯尼德监管伐木场，亲自驾驶这台改装过的机器，用巨大的圆锯抵御来敌。"},{t="致命驾驶舱",b="斯尼德坐在旋转刀刃上方的开放式驾驶舱里，受到厚重铁甲的保护。机器的轰鸣声能让他的敌人四散奔逃。当伐木机损坏，在火花中倒塌时，斯尼德会从残骸中跳出，继续战斗。"}},faq={{q="斯尼德的伐木机在死亡矿井里有什么用途？",a="迪菲亚潜行者使用地精机械凿开岩石、加工木材，为秘密建造的巨型战舰提供材料。斯尼德的伐木机负责锯木，并维持地下工场的秩序。",al={"死亡矿井为什么有伐木机","死亡矿井伐木机用途"}},{q="伐木机被摧毁后会发生什么？",a="伐木机损坏后，斯尼德仍会活下来。这位地精驾驶员会带着自己的武器从残骸中现身，猛烈攻击入侵者。",al={"斯尼德会和伐木机一起死吗","斯尼德的伐木机第二阶段"}},{q="迪菲亚潜行者为什么拥有地精技术？",a="艾德温·范克里夫雇用了地精工程师、工匠和受雇的劳工，负责运转西部荒野地下的机械工场，包括蒸汽驱动的熔炉、火炮铸造厂和锯木厂。",al={"迪菲亚地精","死亡矿井为什么有地精"}},{q="工程师能侵入或控制伐木机吗？",a="侏儒通用遥控器可以短暂接管伐木机的控制系统，从斯尼德手中夺取控制权。",al={"控制斯尼德的伐木机","侏儒通用遥控器斯尼德"}},{q="斯尼德的伐木机上有什么贵重物品吗？",a="有。暴风城的沉默的舒尼正在寻找那件完好的动力装置，也就是小型高能发动机。她需要用它为侏儒的陀螺钻掘机提供动力，以便进攻诺莫瑞根。",al={"斯尼德的伐木机任务物品","斯尼德的伐木机掉落什么"}},{q="谁在驾驶伐木机？",a="地精监工斯尼德驾驶这台机器，并指挥死亡矿井深处的伐木和木工作业。",al={"谁驾驶斯尼德的伐木机","斯尼德驾驶员"}}},fp="16,147,17.267.0,16.225.0,51.173.0,44.142.0,53.186.0,54.101.0,46.197.0,24.103.0"}
P.entries["npc:solm-hargrin"] = {n="索姆·哈格林",s="在寒脊山谷的安威玛尔，索姆·哈格林教导年轻的矮人和侏儒，为他们成为盗贼做准备。随着艾泽拉斯各地的局势日趋紧张，他相信秘密行动人员将发挥至关重要的作用。",h="在寒脊山谷的安威玛尔，索姆·哈格林教导年轻的矮人和侏儒，为他们成为盗贼做准备。随着艾泽拉斯各地的局势日趋紧张，他相信秘密行动人员将发挥至关重要的作用。",kw={"安威玛尔","寒脊山谷","丹莫罗","密文备忘录","密文符文","盗贼训练师","索姆·哈格林"},ang={["class:Rogue"]="作为刚开始接受盗贼训练的矮人或侏儒，你可以向索姆·哈格林学习基础本领。他也会破译你收到的第一份公会指令。",["race:Dwarf"]="作为矮人，你可以在丹莫罗走上一条更隐秘的道路，在那里，潜行与智谋和铠甲与战斧一样，都有用武之地。"},sec={{t="暗影中的导师",b="索姆·哈格林教导学徒破译密信，并使用剔骨等技巧。铁炉堡倚重巡山人和战士，但有些威胁需要用更隐秘的手段应对。因此，他教导学徒忠于自己的技艺，忠于彼此，让他们准备好面对更加动荡的世界。"}},faq={{q="索姆·哈格林是谁？",a="索姆·哈格林在寒脊山谷的安威玛尔训练年轻的矮人和侏儒，让他们掌握盗贼的本领。他教导他们潜行与刀刃技艺。",al={"索姆是谁","索姆·哈格林的故事","安威玛尔盗贼训练师"}},{q="索姆·哈格林对盗贼之道有何理念？",a="索姆·哈格林教导学徒，盗贼之间也要讲信义。他相信，即便手段并不光彩，忠于自己的技艺、忠于彼此仍然十分重要。",al={"索姆的信念","盗贼之间的信义","索姆的看法"}},{q="索姆·哈格林提供或接受哪些任务？",a="矮人盗贼新手会给索姆·哈格林带来密文符文，而侏儒盗贼新手则会带来密文备忘录。他破译其中的指令，然后派学徒到野外掌握进攻招式。",al={"索姆的任务","密文符文 索姆","密文备忘录 索姆"}},{q="索姆·哈格林也训练矮人以外的种族吗？",a="是的。索姆·哈格林在寒脊山谷同时训练侏儒和矮人。",al={"侏儒能跟索姆学习吗","侏儒盗贼训练师 安威玛尔"}}},fx={["3b6a2fc5"]={q="索姆·哈格林属于哪一方？",a="索姆·哈格林忠于铁炉堡和联盟。他驻守在寒脊山谷，训练初出茅庐的密探保卫矮人的领土，并坚信在政治动荡日益加剧之际，暗影技艺是守护王国不可或缺的手段。",al={"索姆·哈格林阵营","索姆·哈格林效忠对象","索姆·哈格林属于联盟吗"}},["7da5d6e5"]={q="索姆·哈格林想要什么？",a="哈格林希望向有潜力的盗贼新人传授潜行、精准出击与个人荣誉的基本准则。眼看世界各地的局势日趋紧张，他相信精通隐秘技艺的人很快就会发挥关键作用，因此希望学生们技艺精湛、严守纪律。",al={"索姆·哈格林的目标","索姆·哈格林想要什么","索姆·哈格林的动机"}},d84d95b0={q="索姆·哈格林为什么在寒脊山谷？",a="他驻守在安威玛尔，指导那些初来乍到、踏上暗影之路的冒险者。作为训练师，他会查验秘密联络人送来的密信，并引领年轻的矮人和侏儒掌握无声战斗的技艺。",al={"索姆·哈格林为什么在这里","索姆·哈格林在安威玛尔的目的","索姆·哈格林为什么在安威玛尔"}}},fp="12,182,23.291.0,20.131.0,48.143.0,49.208.0,49.70.0"}
P.entries["npc:sprite-darter"] = {n="小精龙",s="小精龙是一种体型娇小、泛着虹彩的精龙，原生于菲拉斯繁茂的树冠间。它们因与生俱来的灵性和魔法特质而备受敬重，轻盈地穿梭于古树之间。近来，这些罕见的生灵成了当地恐怖图腾牛头人的目标，后者企图捕捉并利用它们。",h="小精龙是一种体型娇小、泛着虹彩的精龙，原生于菲拉斯繁茂的树冠间。它们因与生俱来的灵性和魔法特质而备受敬重，轻盈地穿梭于古树之间。近来，这些罕见的生灵成了当地恐怖图腾牛头人的目标，后者企图捕捉并利用它们。",kw={"精龙的蛋","精龙","菲拉斯","恐怖图腾","辛达尔·月纹","灵魂精华","小精龙","巫医尤克里"},ang={["class:Druid"]="德鲁伊将精龙视为自然之灵的近亲，对它们十分敬重，认为粗暴的偷猎者捕捉精龙的行为严重破坏了森林的平衡。",["faction:Alliance"]="辛达尔·月纹的盟友集结起来，援救菲拉斯被囚禁的幼龙，阻止敌对的恐怖图腾部族不断扩张势力。",["faction:Horde"]="莫沙彻营地的巫医尤克里等巨魔灵术师，将小精龙视为采集灵性muisek、驾驭菲拉斯古老精华的上佳对象。",["race:NightElf"]="暗夜精灵尊奉神圣的精龙，视其为森林的天然守护者，因此，从恐怖图腾手中解救被捕的小精龙，也成了维护生态的职责。"},sec={{t="荒野中的精龙",b="小精龙是栖息于林地的有翼野兽，行踪隐秘，原生于菲拉斯的古老森林。它们拥有闪烁着虹彩的双翼和神秘的灵性本质，体现了卡利姆多密林中奇幻而又强悍的魔法生态。它们通常温和而羞怯，但天生的魔法抗性与自然之力，使它们对那些与荒野心意相通的人意义非凡。"},{t="恐怖图腾的囚笼",b="近来，深居林间的小精龙面临着前所未有的威胁。居住在菲拉斯的恐怖图腾牛头人氏族生性好斗，开始大肆搜捕这些罕见的生灵，将它们关入笼中，目的不明。辛达尔·月纹等心怀忧虑的暗夜精灵正积极招募盟友，破坏牢笼，赶在恐怖图腾迫使这些幼龙屈服之前将它们解救出来。"},{t="对灵性的探求",b="除了致力于保护它们的暗夜精灵，小精龙也引起了研究原始力量的外来观察者的注意。巫医尤克里是一位以莫沙彻营地为据点的巨魔灵术师，他对小精龙体内蕴藏的自然能量和魂精十分感兴趣，希望获取它们的精华，揭开遍布菲拉斯的独特魔法之谜。"}},faq={{q="小精龙是什么？",a="小精龙是栖息于菲拉斯荒野中的微型精龙。它们以闪烁的双翼、与自然的联系，以及神出鬼没的魔法习性而闻名。",al={"小精龙资料","小精龙是什么","小精龙是龙吗"}},{q="恐怖图腾牛头人为什么要捕捉它们？",a="确切原因仍不为人知，但恐怖图腾氏族一直在林中大批网捕小精龙，将它们关入笼中，很可能是想利用它们罕见的灵性与魔法特质。",al={"恐怖图腾为何设笼","恐怖图腾小精龙","小精龙为何被关"}},{q="谁在设法保护小精龙？",a="辛达尔·月纹是一位居住在菲拉斯的精灵，她积极保护小精龙，派遣心怀同情的冒险者去砸毁恐怖图腾的牢笼，救出被囚禁的小精龙。",al={"谁保护小精龙","辛达尔·月纹小精龙","联盟小精龙任务"}},{q="巫医尤克里为什么对小精龙感兴趣？",a="巫医尤克里研究菲拉斯的原始灵性力量。他寻求小精龙的精华，也就是灵魂精华，以进一步了解这片地区天生具有魔力的野生生灵。",al={"巫医尤克里小精龙","尤克里小精龙任务"}},{q="能养育一只小精龙吗？",a="帮助辛达尔·月纹解救被囚幼龙并守护巢穴的人，最终可能会获赠一枚罕见的精龙的蛋，受托将其孵化养大并加以保护。",al={"精龙的蛋","小精龙宠物","能获得小精龙吗"}},{q="小精龙有敌意吗？",a="野生小精龙通常胆小易惊，不会主动攻击旅人，但和所有野生生灵一样，受到威胁或挑衅时，它们也会迸发自然魔法来保护自己。",al={"小精龙危险吗","小精龙会攻击吗"}}},fp="13,173,26.233.0,19.263.0,18.254.0,24.146.0,44.179.0,44.133.0,56.138.0,30.147.1,27.151.0"}
P.entries["npc:sprite-jumpsprocket"] = {n="斯普莱特",s="在暴风城的矮人区，斯普莱特与侏儒和矮人工匠并肩工作。和许多在诺莫瑞根沦陷后前来避难的侏儒一样，她在工匠同伴之间学习工程学。",h="在暴风城的矮人区，斯普莱特与侏儒和矮人工匠并肩工作。和许多在诺莫瑞根沦陷后前来避难的侏儒一样，她在工匠同伴之间学习工程学。",kw={"学徒","矮人区","工程师","侏儒","跳链","斯普莱特","暴风城","工匠"},ang={["faction:Alliance"]="身为联盟的一员，你可以在矮人区看到人类、矮人和侏儒如何携手合作。他们的工作帮助维持着都城的运转。",["profession:Engineering"]="身为工程师，你可以在暴风城工业最发达的城区，与斯普莱特一同学习，身边围绕着链轮、铜管和不稳定的混合物。",["race:Gnome"]="身为侏儒，你与诺莫瑞根的流亡者有着同样的坚韧。尽管远离失去的家园，他们仍热爱工艺，精通机械。"},sec={{t="暴风城的工匠",b="在暴风城的矮人区，斯普莱特作为工程学徒接受训练。侏儒和矮人在这里并肩工作，锻造金属，制作精密的装置。这座都城为工匠学徒提供了向资深大师学习的空间。他们的工作让联盟的日常机械和奇妙造物保持良好运转。"},{t="流亡中的侏儒巧思",b="诺莫瑞根沦陷后，流离失所的侏儒将制造、化学和机械方面的技艺带到了联盟各地。在暴风城，矮人区为他们提供了安身之所，熔炉和工作台近在手边。尽管族人历经苦难，斯普莱特仍和他们一样，决心精通工程学。"}},faq={{q="斯普莱特是谁？",a="斯普莱特是一名女性侏儒工程学徒，在暴风城的矮人区生活和工作。",al={"斯普莱特","斯普莱特是谁","斯普莱特的故事"}},{q="在哪里可以找到斯普莱特？",a="你可以在暴风城的矮人区找到斯普莱特，她身边是作坊、铁砧和其他工程学爱好者。",al={"斯普莱特的位置","斯普莱特在哪里","寻找斯普莱特"}},{q="她在暴风城担任什么角色？",a="斯普莱特在暴风城作为工程学徒接受训练。她是在联盟都城磨炼技艺的侏儒工匠之一。",al={"斯普莱特的角色","她做什么","斯普莱特的作用"}},{q="为什么斯普莱特这样的侏儒会住在暴风城？",a="诺莫瑞根沦陷后，许多侏儒前往铁炉堡，投奔他们的矮人近亲，也有人到人类各地寻求庇护。许多侏儒在暴风城定居，那里对他们的工业技艺有着很大的需求。",al={"侏儒为何在暴风城","侏儒 矮人区","侏儒难民"}},{q="斯普莱特与什么知名任务有关吗？",a="斯普莱特是矮人区工程学界的一员。",al={"斯普莱特任务","斯普莱特的任务"}},{q="她与西部荒野有关吗？",a="斯普莱特驻留在暴风城的矮人区。这一带的工程造物往往采用侏儒的设计。",al={"斯普莱特 西部荒野","西部荒野工程师"}}},fx={b9758f03={q="斯普莱特属于哪一方？",a="斯普莱特坚定地站在联盟和诺莫瑞根流亡者一方。诺莫瑞根沦陷后，许多流离失所的侏儒投奔了矮人同胞和人类盟友，她也是其中之一，如今在暴风城繁忙的矮人区从事自己的行当，以工程技艺为王国和联盟同胞效力。",al={"斯普莱特阵营","斯普莱特属于联盟还是部落","斯普莱特为谁效力"}}},fp="19,198,21.331.0,26.338.0,27.115.0,37.135.0,38.146.0,47.192.0,50.76.0,32.139.0"}
P.entries["npc:sputtervalve"] = {n="斯布特瓦夫",s="在棘齿城，斯布特瓦夫顶着压力，争分夺秒地为技工协会完成伐木机研究。主管雷德沃克斯定下的期限让他喘不过气，于是他雇用冒险者，从竞争对手荆棘谷地精那里窃取设计图。",h="在棘齿城，斯布特瓦夫顶着压力，争分夺秒地为技工协会完成伐木机研究。主管雷德沃克斯定下的期限让他喘不过气，于是他雇用冒险者，从竞争对手荆棘谷地精那里窃取设计图。",kw={"棘齿城","雷德沃克斯","什么什么平衡器","伐木机","淤泥沼泽","斯布特瓦夫","工匠协会","荆棘谷地精","维兹克兰克"},ang={["faction:Horde"]="棘齿城保持中立，但斯布特瓦夫依靠穿越贫瘠之地的部落旅人，破坏荆棘谷地精的作业，并走私机械零件。",["profession:Engineering"]="斯布特瓦夫展现了地精工程学不择手段的一面：发明陷入停滞时，就从竞争对手那里夺取设计图。"},sec={{t="工业重压",b="在棘齿城，斯布特瓦夫听命于技工协会的主管雷德沃克斯。这位地精工程师负责伐木机的研发，深感这份工作艰苦不堪。现代机械化发展迅速，荆棘谷地精步步紧逼，而他自己的原型机却寥寥无几。期限日益临近，斯布特瓦夫害怕向技工协会承认失败。他转而采用地精惯用的手段：从先行者那里窃取更好的设计。"},{t="盯上荆棘谷地精",b="荆棘谷地精在西北方淤泥沼泽的钻探作业，是斯布特瓦夫的首要目标。那里最新的伐木机配有可更换的机械手、改良的操纵握柄和先进的内部机构，其中就包括难以到手的什么什么平衡器。斯布特瓦夫派同伴维兹克兰克前往沼泽进行实地研究，但维兹克兰克却被困在那里。如今，斯布特瓦夫雇用四处游荡的佣兵，取回窃得的技术，并救出他的搭档。"},{t="棘齿城的能人",b="对于流入贫瘠之地的奇异物件，斯布特瓦夫也能帮上忙。冒险者有时会带来一些沾染了哀嚎洞穴腐化之力的古怪器物，比如发光的碎片。他熟悉当地的地形，知道该让他们放下机械方面的念头，转而去找驻扎在洞穴上方、离群索居的德鲁伊。"}},faq={{q="斯布特瓦夫是谁？",a="斯布特瓦夫是棘齿城的一名地精工程师，也是技工协会的成员。主管雷德沃克斯让他负责伐木机的研究与开发，他正为赶上严苛的期限而忙得不可开交。",al={"斯布特瓦夫是谁","斯布特瓦夫 棘齿城","斯布特瓦夫 背景故事"}},{q="斯布特瓦夫为何盯上荆棘谷地精？",a="荆棘谷地精正在淤泥沼泽制造先进的伐木机，配有可更换的机械手和改良的操纵握柄。斯布特瓦夫无法拿出与之匹敌的设计，于是转而通过间谍手段窃取他们的图纸和机械。",al={"为何攻击荆棘谷地精","斯布特瓦夫 淤泥沼泽","斯布特瓦夫 荆棘谷地精"}},{q="什么什么平衡器是什么？",a="什么什么平衡器是荆棘谷地精伐木机内部的一种先进机构。斯布特瓦夫雇用冒险者取回一个进行研究，好掌握他们的技术。",al={"研究设备是什么","研究设备任务","研究设备有什么用"}},{q="维兹克兰克是谁？",a="维兹克兰克是斯布特瓦夫的同伴，也为他执行任务。维兹克兰克奉命前往淤泥沼泽进行实地研究，却被困在那里，因此斯布特瓦夫雇人去救他，并取回窃得的技术。",al={"维兹克兰克","维兹克兰克是谁","斯布特瓦夫的搭档"}},{q="斯布特瓦夫为何关心发光的碎片？",a="斯布特瓦夫不研究与生物有关的奇异物件，但他很熟悉贫瘠之地。冒险者拿出从哀嚎洞穴带回的碎片时，他指引他们去找驻扎在洞穴上方的德鲁伊。",al={"发光的碎片 斯布特瓦夫","发光的碎片 哀嚎洞穴","碎片任务 棘齿城"}},{q="主管雷德沃克斯是谁？",a="主管雷德沃克斯领导着技工协会。他让斯布特瓦夫负责伐木机的革新，并要求他严格遵守生产期限。",al={"雷德沃克斯","主管雷德沃克斯","工匠协会首领"}}},fp="12,209,19.424.0,27.460.0,18.337.0,20.198.0,50.222.0,22.165.0,19.196.1,51.199.0,26.143.0"}
P.entries["npc:sten-stoutarm"] = {n="斯登·粗臂",s="在安威玛尔外，斯登·粗臂为新兵配发装备，并维持寒脊山谷的消息传递。冬日的暴风雪封锁了山谷，附近又危机四伏，保暖、食物和明确的指示都至关重要。",h="在安威玛尔外，斯登·粗臂为新兵配发装备，并维持寒脊山谷的消息传递。冬日的暴风雪封锁了山谷，附近又危机四伏，保暖、食物和明确的指示都至关重要。",kw={"安威玛尔","寒脊","丹莫罗","邮件","装备供应商","斯登","粗臂","石腭怪"},ang={["faction:Alliance"]="身为联盟的一员，你依靠穿过寒脊山小径的消息传递，让铁炉堡的各处训练场保持联系。斯登负责在山谷各处运送邮件。",["race:Dwarf"]="身为矮人，你在丹莫罗可以指望斯登务实的热情款待。在你踏入风雪之前，他会给你厚实的皮革和食物。",["race:Gnome"]="身为在安威玛尔与矮人一同受训的侏儒难民，你也要面对斯登务实的期望。他让你带上邮件和抵御风雪的装备出发。"},sec={{t="雪中援“手”",b="在安威玛尔外的酒馆附近，斯登·粗臂接待初来乍到的矮人和侏儒新兵。冬日的暴风雪封锁了寒脊山谷，危险也近在咫尺。因此，斯登为初出茅庐的学徒提供结实的装备，让他们做好准备再踏入风雪。"},{t="维持通信",b="斯登收集狼皮，用来制作冬衣，也在寒脊山谷中传递消息。他带着公文穿过危险的寒脊山小径，再将正式的符文、备忘录和命令送到盆地各处的职业训练师手中。石腭怪堵住了隧道，但年轻的战士、牧师和法师仍需要得到指示。"}},faq={{q="斯登·粗臂是谁？",a="在寒脊山谷的安威玛尔外，斯登·粗臂为新兵配发装备并传递消息。他帮助新来的人获得保暖衣物，也帮忙送达当地的邮件。",al={"斯登·粗臂","斯登是谁","安威玛尔邮差"}},{q="他在寒脊山谷负责什么？",a="斯登为安威玛尔的学徒配发装备并传递消息。他收集狼肉和狼皮，用于换取防护装备，再将信件和训练备忘录转送到山谷各处。",al={"斯登的工作","斯登做什么","斯登的职责"}},{q="斯登为什么需要人帮忙送信？",a="石腭怪和冬日的恶劣天气让寒脊山小径危机四伏，阻碍了运往山谷的邮件和补给。邮件抵达后，斯登会请可靠的新人将包裹和信件送给塔林·锐眼等居民。",al={"为何递送寒脊邮件","斯登邮件","寒脊山谷邮件递送"}},{q="斯登如何看待山谷中的石腭怪？",a="斯登早已厌烦了周围山丘上的石腭怪。他说，见过一只石腭怪，就等于见过了所有石腭怪。",al={"斯登石腭怪","石腭怪语录","斯登谈石腭怪"}},{q="他为什么要收集狼肉？",a="斯登用保暖耐用的手套换取硬狼肉。狼肉供山谷的守卫充饥，手套则帮他们抵御丹莫罗的严寒。",al={"矮人的交易任务","狼肉任务","斯登狼肉"}},{q="斯登交给新冒险者的符文和备忘录是什么？",a="这些符文和备忘录是铁炉堡及丹莫罗各处的上级寄来的密封信件和训练信物。它们指引年轻的学徒前往安威玛尔内，向各自的职业训练师报到。",al={"神圣符文","简易备忘录","斯登的便笺"}}},fx={be997a27={q="斯登·粗臂属于哪一方？",a="斯登·粗臂是忠于铁炉堡的矮人，坚定地站在联盟一方。他驻守在寒脊山谷的安威玛尔，为当地训练场提供支援，确保新来的矮人和侏儒新兵获得保卫山谷所需的物资与命令。",al={"斯登·粗臂阵营","斯登·粗臂为谁效力","斯登·粗臂 联盟"}},["9084afa8"]={q="斯登·粗臂想要什么？",a="尽管周围危机四伏，斯登仍希望维持寒脊山谷后勤工作的顺畅运转。山谷受到穴居人和野兽的威胁，他因此寻找有能力的新兵，分发从山口送来的重要邮件，收集狼肉以换取结实的装备商手套，并将书面命令送到各自的职业训练师手中。",al={"斯登想要什么","斯登·粗臂的目标","斯登为什么需要帮助"}},d8d60996={q="斯登·粗臂为什么在寒脊山谷这里？",a="斯登驻守在安威玛尔，担任寒脊山谷不可或缺的协调人和邮差。连接山谷与丹莫罗其他地区的山口危险重重，怪物盘踞，因此需要有人在当地协调来往的通信和公文，为初出茅庐的守卫者配发装备，并将消息转交安威玛尔的教官。",al={"斯登为什么在这里","斯登·粗臂为什么在寒脊山谷","斯登·粗臂在此的原因"}}},fp="13,206,26.232.0,22.326.0,21.156.0,43.180.0,34.226.0,52.120.0,30.146.0,63.194.0"}
P.entries["npc:stitches"] = {n="缝合怪",s="缝合怪沿着暮色森林西部的道路向夜色镇进发，碾碎沿途的守夜人和毫无戒备的旅人。",h="缝合怪沿着暮色森林西部的道路向夜色镇进发，碾碎沿途的守夜人和毫无戒备的旅人。",kw={"憎恶","夜色镇","艾尔罗·埃伯洛克公爵","守夜人","乌鸦岭","缝合怪"},ang={["class:Paladin"]="Stitches是通灵术与亵渎的血肉塑造术所造就的畸形产物，正是人们祈求圣光净化的邪物。",["faction:Alliance"]="Stitches威胁着夜色镇饱受困扰的居民，也让暮色森林的大道成了联盟新兵的致命险途。"},sec={{t="大道上的恐怖",b="在乌鸦岭墓地东北方、亚伯克隆比的小屋附近，缝合怪沿着道路向东出发，朝夜色镇前进。这个亡灵憎恶由邪恶的巫术和搜集来的尸体造就，其骇人的力量与恶意令守夜人的哨卡无力抵挡。他冲破沃古尔食人魔山对面的防御营地和烂果园外的哨站，沿途屠戮旅人与城镇守卫。"},{t="藏尸者的扭曲复仇",b="在过路人眼中，亚伯克隆比只是个无害的隐士，却对夜色镇的镇长艾尔罗·埃伯洛克公爵怀着深深的怨恨。他以无害的面目示人，利用毫不知情的冒险者收集秘术试剂、工具和材料，随后完成了他那可怖的造物。亚伯克隆比将缝合怪作为一份嘲弄的礼物送往夜色镇，意图摧毁镇上的防御，惩罚艾尔罗·埃伯洛克公爵。"}},faq={{q="谁创造了缝合怪？",a="缝合怪是在暮色森林通过通灵术拼合而成的。究竟是谁创造了他，仍是乌鸦岭附近亡灵谜团的一部分。",al={"缝合怪的创造者","谁制造了缝合怪","亚伯克隆比 缝合怪"}},{q="缝合怪为什么向夜色镇进发？",a="缝合怪沿着暮色森林的大道向夜色镇进发，攻击守夜人和其他所有挡路的人。他发动袭击的原因会在当地的调查中逐渐揭晓。",al={"缝合怪为何前往夜色镇","缝合怪的袭击目标","缝合怪走向哪里"}},{q="守夜人能独自阻止缝合怪吗？",a="不能。如果无人干预，缝合怪会轻易攻破沃古尔食人魔山和烂果园外的守夜人哨卡，重创守军，随后抵达夜色镇的大门。只有民兵合力防守，再加上过往冒险者的援助，才能将他击倒。",al={"守卫对抗缝合怪","守夜人击败缝合怪","夜色镇守卫能否杀死缝合怪"}},{q="缝合怪在哪里出现？",a="缝合怪出现在亚伯克隆比的小屋后方，位于乌鸦岭墓地东北方的道路旁，随后开始向东横穿暮色森林，踏上漫长而致命的行军之路。",al={"缝合怪在哪里出现","缝合怪的位置","缝合怪的起点"}}},fp="8,129,27.421.0,30.396.1,21.89.2,42.168.2,47.219.0,26.153.1"}
P.entries["npc:strahad-farsan"] = {n="斯坦哈德·法尔杉",s="在棘齿城上方，斯坦哈德·法尔杉教导术士束缚恶魔。这位人类术士住在贫瘠之地的一座石塔中，远离联盟与部落日常的政治纷争。研习邪能魔法的学生从暴风城、奥格瑞玛和幽暗城赶来，向他求教。",h="在棘齿城上方，斯坦哈德·法尔杉教导术士束缚恶魔。这位人类术士住在贫瘠之地的一座石塔中，远离联盟与部落日常的政治纷争。研习邪能魔法的学生从暴风城、奥格瑞玛和幽暗城赶来，向他求教。",kw={"贫瘠之地","秘密结社","法尔杉","地狱猎犬","加科因","棘齿城","斯坦哈德","召唤者","术士"},ang={["class:Warlock"]="身为术士，你可以向斯坦哈德学习如何束缚地狱猎犬，以及从虚空召唤战马。",["faction:Alliance"]="黑暗缚灵者加科因将联盟术士从已宰的羔羊的地下墓穴派往卡利姆多，向斯坦哈德求学。",["faction:Horde"]="斯坦哈德虽然出身于联盟，却在中立的棘齿城与部落的施法者往来。",["race:Human"]="身为人类的斯坦哈德表明，黑暗技艺的大师也会远赴暴风城之外，寻求更强大的力量。"},sec={{t="棘齿城上方的高塔",b="斯坦哈德·法尔杉隐居在棘齿城上方峭壁上的一座石塔中。这座地精港口的中立地位，让他得以避开联盟的治安官和部落的萨满祭司，进行危险的召唤。他研究扭曲虚空时，侍从们聚集在他身边，远离下方的领土争端。"},{t="恶魔束缚大师",b="斯坦哈德亲身体会过束缚恶魔的危险。他第一次尝试束缚地狱猎犬时险些丧命，从此变得谨慎而严苛。尽管身为人类，他仍赢得了暴风城的黑暗缚灵者加科因，以及幽暗城和奥格瑞玛的恶魔学者的尊重。无论属于哪个阵营，想要驾驭地狱猎犬或烈焰战马的术士，都会被指引到他的高塔。"}},faq={{q="斯坦哈德·法尔杉是谁？",a="斯坦哈德·法尔杉在棘齿城上方的一座石塔中教导术士。他是暴风城的黑暗缚灵者加科因核心圈子中的一员，两个阵营的术士都前来向他求教恶魔召唤之术。",al={"斯坦哈德的故事","斯坦哈德是谁","斯坦哈德·法尔杉资料"}},{q="为什么一位人类术士会住在贫瘠之地？",a="斯坦哈德住在棘齿城上方，那是一座由热砂港经营的中立港口。在那片峭壁上，他可以避开联盟的律法和部落的监视，进行危险的召唤仪式。",al={"斯坦哈德为什么在棘齿城","贫瘠之地的人类","斯坦哈德的位置"}},{q="部落术士为什么会拜访斯坦哈德？",a="斯坦哈德驾驭恶魔的本领吸引了部落的术士。奥格瑞玛和幽暗城的导师认可他在束缚地狱猎犬等恶魔方面的学识，派遣有潜力的学生远渡重洋，向他求学。",al={"部落拜访斯坦哈德","部落能与斯坦哈德交谈吗","兽人为什么去找斯坦哈德"}},{q="斯坦哈德第一次召唤地狱猎犬时发生了什么？",a="斯坦哈德第一次尝试束缚地狱猎犬时险些丧命。他勉强活了下来，这番磨难让他懂得，要降伏这种吞噬魔法的掠食者，施法必须精准无误。",al={"斯坦哈德遭遇地狱猎犬","斯坦哈德与地狱猎犬的往事"}},{q="斯坦哈德与高德瑞克·法杉有亲属关系吗？",a="斯坦哈德与高德瑞克·法杉有着同一个少见的姓氏法尔杉，这暗示两人可能存在亲属关系。斯坦哈德对家人只字不提，始终专注于自己的黑暗技艺。",al={"与高德瑞克·法杉的关系","高德瑞克·法杉的亲属","斯坦哈德与高德瑞克有亲属关系吗"}},{q="他高塔周围的侍从是谁？",a="斯坦哈德的侍从包括玛迦兹、芬里克和温图拉。他们协助维持防护结界、准备召唤法阵，并照料高塔中的仪式。",al={"斯坦哈德的侍从","棘齿城高塔中的侍从"}}},fp="14,261,23.302.0,25.395.0,22.194.0,45.173.0,36.217.0,62.178.0,37.174.0,38.151.0"}
P.entries["npc:supervisor-raelen"] = {n="管理员莱琳",s="在东谷伐木场，管理员莱琳确保木材源源不断地运往暴风城。她指挥工人，记录他们每日的定额，并照管木材供应。",h="在东谷伐木场，管理员莱琳确保木材源源不断地运往暴风城。她指挥工人，记录他们每日的定额，并照管木材供应。",kw={"木材危机","东谷","东谷伐木场","艾尔文森林","木材","莱琳","管理员莱琳","木材定额"},ang={["faction:Alliance"]="暴风城的防御工事和建筑工程都需要木材，因此莱琳的木材定额对王国的战事至关重要。"},sec={{t="确保伐木场按期运作",b="管理员莱琳在东谷伐木场指挥伐木工，她就在治安官帕特森和伐木场的货车附近。伐木场位于艾尔文森林东部边缘，靠近赤脊山，在这里伐木常会招来麻烦。尽管周围的林地危机四伏，莱琳仍协调各支队伍，让他们专心完成定额。她确保采集来的木材经过加工、捆扎，再运往暴风城。"}},faq={{q="管理员莱琳是谁？",a="管理员莱琳负责监管艾尔文森林东部东谷伐木场的伐木队。她管理他们的工作，确保他们按期完成木材定额。",al={"莱琳是谁","莱琳 艾尔文森林","东谷管理员"}},{q="在哪里可以找到管理员莱琳？",a="管理员莱琳位于东谷伐木场中央，就在满载木材的货车和治安官帕特森附近。",al={"莱琳在哪里","管理员莱琳位置","寻找莱琳"}},{q="管理员莱琳为什么需要冒险者的帮助？",a="在森林边缘采集木材可能遇到危险。当野兽或其他变故扰乱工人的工作时，砍下的成捆木材可能会被遗弃，或散落在林间。",al={"莱琳任务","木材危机任务","为什么帮助莱琳"}},{q="东谷伐木场在艾尔文森林中起什么作用？",a="东谷伐木场是艾尔文森林东部的主要伐木场。这里的木材用于暴风城及附近定居点的重建和维护。",al={"东谷是什么","东谷伐木的作用","东谷为什么重要"}}},fx={["5e9ae7c9"]={q="管理员莱琳效忠哪一方？",a="管理员莱琳效忠暴风城王国与联盟。她代表王国管理东谷伐木场的木材生产，与暴风城的卫兵和劳工一同工作，确保木材源源不断地运往首都。",al={"莱琳的阵营","管理员莱琳为谁效力","莱琳属于联盟吗"}},["93ff040d"]={q="管理员莱琳为何在东谷？",a="莱琳负责监督东谷伐木场的日常伐木工作。她指挥当地劳工，监管运木车，并确保采集的木材达到暴风城规定的数量，让伐木场在周围荒野的威胁下仍能持续运转。",al={"管理员莱琳为何在这里","莱琳在东谷的目的","莱琳在这里做什么"}},e5fd1368={q="管理员莱琳与谁有关联？",a="莱琳与驻扎在东谷的暴风城地方官员密切合作，尤其是负责营地防务的帕特森元帅。她还指挥着营地内由当地农民和伐木工组成的劳工队伍。",al={"莱琳的关联人物","莱琳与谁合作","管理员莱琳的盟友"}}},fp="17,170,28.407.0,25.161.0,35.111.0,54.181.0,63.161.0"}
P.entries["npc:suzetta-gallina"] = {n="苏泽塔·加林纳",s="在暴风城的加林纳酒店，苏泽塔·加林纳打理着家族的葡萄酒生意。",h="在暴风城的加林纳酒店，苏泽塔·加林纳打理着家族的葡萄酒生意。",kw={"加林纳酒店","暴风城 运河","暴风城葡萄酒","苏泽塔·加林纳","葡萄酒店广告"},ang={["faction:Alliance"]="身为联盟的旅行者，从危机四伏的艾尔文或西部荒野归来时，到苏泽塔的店里稍作停留，便能一窥首都的平静生活。"},sec={{t="运河 的滋味",b="在暴风城的 运河 沿岸，苏泽塔·加林纳协助经营着加林纳酒店。酒架上既有从王国各地运来的葡萄酒，也有酒庄自酿的佳酿。这个家族为酒馆、贵族和平民供应葡萄酒。她的工作让首都的商贸在动荡时期依然运转。"}},faq={{q="苏泽塔·加林纳是谁？",a="苏泽塔·加林纳的家族经营着加林纳酒店，酒庄坐落在暴风城的 运河 沿岸。",al={"苏泽塔·加林纳","苏泽塔 是谁","加林纳酒店 的女人"}},{q="在哪里能找到苏泽塔·加林纳？",a="你可以在暴风城贸易区与教堂广场之间的运河沿岸，在加林纳酒店内找到苏泽塔。",al={"苏泽塔·加林纳位置","苏泽塔 在哪里","加林纳酒店 位置"}},{q="苏泽塔有什么工作交给旅行者吗？",a="苏泽塔不会直接提供工作。她的兄弟雷纳多会发放 酒票。带一张到加林纳酒店交给她，就能免费领取一瓶家族特制的黑皮诺葡萄酒。",al={"苏泽塔 任务","加林纳 葡萄酒任务","葡萄酒店广告"}}},fx={f0d37e75={q="苏泽塔·加林纳效忠哪一方？",a="苏泽塔·加林纳是联盟的忠诚公民。她在暴风城中心安稳地生活和工作，与家人一起为首都的酒馆老板、贵族和平民供应葡萄酒。",al={"苏泽塔·加林纳的阵营","苏泽塔·加林纳属于联盟吗","苏泽塔为谁效力"}},["44c42184"]={q="苏泽塔·加林纳想要什么？",a="苏泽塔希望家族的葡萄酒生意兴隆。她与亲人一起打理加林纳酒店，确保他们的桶装酒与瓶装酒在城中各处都有热切的买家，并向口渴的旅人宣传自家的佳酿。",al={"苏泽塔·加林纳的目标","苏泽塔想要什么","苏泽塔·加林纳在做什么"}},["290e58c2"]={q="苏泽塔·加林纳为何在暴风城？",a="苏泽塔留在运河区，是因为家族生意的中心加林纳酒店就坐落于此。在这里，她协助打理生意，也能就近照应暴风城热闹的酒馆和商贸要道。",al={"苏泽塔·加林纳为何在这里","苏泽塔为何在运河边","苏泽塔·加林纳所在地点的背景"}},c1c3d801={q="苏泽塔·加林纳与谁有关联？",a="苏泽塔来自经营葡萄酒生意的加林纳家族，与亲人在家族店铺中一同酿造陈年佳酿，并销往暴风城各处。",al={"苏泽塔·加林纳的家族","苏泽塔与谁有亲属关系","加林纳酒店的家族"}}},fp="15,87,21.268.0,23.97.0,33.123.0,42.189.0"}
P.entries["npc:sven-yorgen"] = {n="斯温·约根",s="在寂静河岸，斯温·约根哀悼惨遭杀害的家人，誓要复仇。他与同伴拉尔斯在暮色森林西部的寂静河岸北缘扎营，决心查明是谁毁了他的家。",h="在寂静河岸，斯温·约根哀悼惨遭杀害的家人，誓要复仇。他与同伴拉尔斯在暮色森林西部的寂静河岸北缘扎营，决心查明是谁毁了他的家。",kw={"黑暗强盗","暮色森林","寂静河岸","基特斯","拉尔斯","摩本特·费尔","月神镰刀","斯温·约根","约根农场"},ang={["class:Paladin"]="斯温的悲痛与对正义的渴求，呼应着圣骑士的职责：为无辜者讨还血债，净化那些在他家土地上被唤起、至今仍徘徊不去的亡灵。",["faction:Alliance"]="斯温的故事映照出王国边境乡村生活的崩溃，普通子民毫无庇护，只能直面黑暗魔法与潜伏在阴影中的恐怖。"},sec={{t="破碎的人生",b="斯温·约根还记得麦迪文陨落、阴霾笼罩暮色森林之前的模样。他出生于第一次兽人战争之前，多年来一直与妻儿在暮色森林南部的约根农场耕作。他们平静的生活终结于一场袭击，神秘的黑暗强盗趁斯温外出时突袭了农场。他们屠杀了他的家人，将农场变成了一片坟场。"},{t="寂静河岸的复仇之誓",b="斯温无法回到已成废墟的家，便与朋友拉尔斯在寂静河岸建起了一处隐蔽的避难所。他不信任外来者，要求旅人先证明自己的忠诚，才肯向他们倾诉心中的重担。在被毁的农场附近，斯温曾看见一个鬼鬼祟祟的身影。他认定这个陌生人要么是那场屠杀的元凶，要么与毁掉他生活的邪恶骑手有所关联。"},{t="揭开真相",b="那个在斯温的田产上徘徊的可疑身影，是四处流浪的基特斯。他的莽撞之举将寻找月神镰刀的黑暗强盗引入了暮色森林。基特斯并未亲手杀人，但他的所作所为引发了那场噩梦，毁掉了约根一家。如今，斯温的怒火转向了盘踞乌鸦岭的黑暗势力，以及死灵法师摩本特·费尔。"}},faq={{q="斯温·约根是谁？",a="斯温·约根在暮色森林寂静河岸北缘的一处小营地里务农。家人在农场惨遭屠杀后，他便一心向凶手讨还血债。",al={"斯温·约根","斯温是谁","斯温的故事"}},{q="斯温的家人遭遇了什么？",a="趁斯温外出，一群被称为黑暗强盗的黑斗篷人来到了约根农场。他们在寻找一件强大的神器，屠杀了斯温的妻儿，还让亡灵污染了这片土地。",al={"约根农场惨剧","斯温家人遇害","斯温的农场发生了什么"}},{q="斯温为何躲在寂静河岸？",a="屠杀发生后，斯温离开了被毁的农场，与拉尔斯在河岸边搭起了临时营地。他躲避着游荡在暮色森林西部的亡灵，同时筹划复仇。",al={"斯温在哪里","斯温的营地","斯温为何在外扎营"}},{q="斯温看见的可疑身影是谁？",a="斯温不知道那个可疑身影是谁。他看见有人在自家农场的废墟附近鬼鬼祟祟地徘徊，便请值得信赖的旅人查明那人的身份，以及那人是否与家人的死有关。",al={"斯温看见的可疑身影","谁在约根农场","暮色森林的可疑身影"}},{q="黑暗强盗为何袭击斯温的农场？",a="黑暗强盗在暮色森林寻找月神镰刀时，穿过了斯温的土地，那是一件蕴含巨大力量的古老神器。他们追寻这件圣物，沿途只留下死亡。",al={"黑暗强盗为何袭击","黑暗强盗在寻找什么","月神镰刀与斯温"}},{q="斯温在暮色森林住了多久？",a="斯温记得暮色森林陷入黑暗之前的模样，因此他在第一次兽人战争之前就已住在那里。那时的森林依然明亮安宁，夜色镇还叫大村庄。",al={"斯温的年龄","斯温多大","黑暗降临前的斯温"}}},fp="11,196,16.357.0,30.387.0,20.380.1,19.190.0,31.205.0,38.184.0,35.208.1,43.177.1,36.176.0"}
P.entries["npc:sylvanas-windrunner"] = {n="Sylvanas Windrunner",s="希尔瓦娜斯·风行者在幽暗城中统治着被遗忘者，她的领地位于洛丹伦的废墟之下。她曾是银月的游侠将军，被阿尔萨斯·米奈希尔杀死并复活，随后挣脱了巫妖王的控制。她加入了萨尔领导的部落，以保障族人的未来，并寻求向Scourge复仇。",h="希尔瓦娜斯·风行者在幽暗城中统治着被遗忘者，她的领地位于洛丹伦的废墟之下。她曾是银月的游侠将军，被阿尔萨斯·米奈希尔杀死并复活，随后挣脱了巫妖王的控制。她加入了萨尔领导的部落，以保障族人的未来，并寻求向Scourge复仇...",kw={"阿尔萨斯","女妖之王","黑暗女王","被遗忘者","洛丹伦","游侠将军","希尔瓦娜斯","幽暗城","风行者"},ang={["faction:Horde"]="大德鲁伊哈缪尔·符文图腾与萨尔的同情帮助Sylvanas加入了部落，但许多兽人和巨魔仍对她及其宫廷心怀戒备。",["race:Undead"]="在被遗忘者眼中，Sylvanas是解放者和保护者。他们认为，是她赋予了他们自由意志和坚固的家园，没有任由他们毫无意识地为Scourge效命。"},sec={{t="游侠将军的陨落",b="希尔瓦娜斯·风行者曾以银月游侠将军的身份，统领奎尔萨拉斯的防御。当阿尔萨斯·米奈希尔王子率领Scourge侵入高等精灵王国，向太阳之井进军时，她奋力阻挡他的脚步。阿尔萨斯被她的抵抗激怒，杀死了她，却不肯让她就此安息。他将她的灵魂从躯体中撕裂出来，将她变成满怀怨恨的女妖，强迫她为Scourge效命，协助屠杀自己的族人。"},{t="被遗忘者的崛起",b="第三次大战之后，巫妖王的控制逐渐减弱，Sylvanas得以挣脱束缚，夺回了自己保存完好的躯体。她召集了其他重获自由意志的亡灵，随后将恐惧魔王逐出了洛丹伦的废墟。她将自己的族人命名为被遗忘者，并在废墟之下建立幽暗城，作为他们的国度。被遗忘者孤立无援，受到Scourge残部、狂热的血色十字军战士和心怀戒备的人类王国的威胁，亟需盟友。Sylvanas与大酋长萨尔及其领导的部落结成了脆弱的同盟。"}},faq={{q="希尔瓦娜斯·风行者是谁？",a="希尔瓦娜斯·风行者在幽暗城的皇家区统治着被遗忘者。她曾是奎尔萨拉斯的精灵游侠将军，被阿尔萨斯·米奈希尔杀死并复活，随后摆脱了天灾军团的控制，成为拥有自由意志的亡灵的领袖。",al={"女妖之王","黑暗女王是谁","希尔瓦娜斯女士","幽暗城领袖"}},{q="希尔瓦娜斯为何让被遗忘者与部落结盟？",a="希尔瓦娜斯让被遗忘者与部落结盟，是因为联盟的生者诸国将他们视为怪物，深恶痛绝。面对天灾军团和血色十字军在洛丹伦带来的威胁，她为族人的生存寻求强大的盟友，并向大酋长萨尔请求加入部落。",al={"亡灵为何加入部落","被遗忘者与部落结盟","希尔瓦娜斯与萨尔的盟约"}},{q="希尔瓦娜斯如何挣脱了巫妖王的控制？",a="第三次大战之后，巫妖王的精神力量开始衰退，对天灾军团的控制随之瓦解，希尔瓦娜斯趁机挣脱了束缚。她是最早恢复自主意志的强大灵魂之一，夺回了自己的遗体，并将怒火转向阿尔萨斯。",al={"希尔瓦娜斯如何摆脱阿尔萨斯","希尔瓦娜斯自由意志","巫妖王的控制"}},{q="希尔瓦娜斯的首要目标是什么？",a="希尔瓦娜斯寻求向阿尔萨斯·米奈希尔和天灾军团复仇，因为他们摧毁了她的家园，奴役了她的灵魂。她也在努力巩固幽暗城的防御，为被遗忘者在洛丹伦争取一处长久的庇护之所。",al={"希尔瓦娜斯想要什么","希尔瓦娜斯的动机","黑暗女王的目标"}}},fp="19,300,26.405.0,20.483.0,27.240.0,51.280.0,47.248.0,32.216.0"}
P.entries["npc:syral-bladeleaf"] = {n="塞拉尔·刃叶",s="在多兰纳尔，塞拉尔·刃叶为从幽影谷前来的暗夜精灵指引方向。身为泰达希尔的居民，她代表森林议会，引导他们拜访当地的看护者、草药师和守护树冠枝桠的长者。",h="在多兰纳尔，塞拉尔·刃叶为从幽影谷前来的暗夜精灵指引方向。身为泰达希尔的居民，她代表森林议会，引导他们拜访当地的看护者、草药师和守护树冠枝桠的长者。",kw={"刃叶","森林议会","德纳兰","多兰纳尔","刃叶长者","塞拉尔","泰达希尔"},ang={["profession:Herbalism"]="身为草药师，你可以帮助塞拉尔引导旅人前往奥拉密斯湖，协助德纳兰的植物研究，并确保新制的药剂送到长者手中。",["race:NightElf"]="身为一名离开幽影谷幽僻兽穴的年轻暗夜精灵，你会遇见塞拉尔·刃叶，她是你在多兰纳尔最早接触到的村务与自然事务领袖之一。"},sec={{t="多兰纳尔的代言人",b="在泰达希尔的树冠下，塞拉尔·刃叶帮助初来乍到的人在多兰纳尔找到方向。她代表森林议会，派遣暗夜精灵去拜访村中及附近荒野里的社群领袖和草药师。她指引旅人前往奥拉密斯湖，拜访植物学家德纳兰，也帮助他们为村中的长者补充物资。"},{t="与村庄的联系",b="在多兰纳尔，塞拉尔为村庄执行森林议会的工作。她帮助确保药剂送到有需要的人手中，并让扰乱当地生态的情况得到及时处理。"}},faq={{q="塞拉尔·刃叶是谁？",a="塞拉尔·刃叶是多兰纳尔的一名暗夜精灵，负责传达森林议会的指示，并帮助新来者为林地社群出力。",al={"塞拉尔是谁","塞拉尔·刃叶的故事","塞拉尔 多兰纳尔"}},{q="在哪里可以找到塞拉尔·刃叶？",a="塞拉尔·刃叶位于泰达希尔的中心聚落多兰纳尔，就在幽影谷西南方不远处的主路沿线。",al={"塞拉尔·刃叶的位置","塞拉尔在哪里","塞拉尔地图"}},{q="她会给冒险者指派什么任务？",a="塞拉尔派遣旅人帮助奥拉密斯湖的植物学家德纳兰，为长者筹备草药制成的药剂，并协助维系泰达希尔的自然平衡。",al={"塞拉尔·刃叶的任务","塞拉尔想要什么","塞拉尔的任务"}}},fp="15,207,19.308.0,19.187.0,23.110.0,35.124.0,42.146.0"}
P.entries["npc:syurna"] = {n="塞尤娜",s="在达纳苏斯，塞尤娜在塞纳里奥区训练暗夜精灵潜行者。她指导有志成为斥候、间谍和秘密特工的新人，再派初出茅庐的潜行者接受潜行与智谋的考验。",h="在达纳苏斯，塞尤娜在塞纳里奥区训练暗夜精灵潜行者。她指导有志成为斥候、间谍和秘密特工的新人，再派初出茅庐的潜行者接受潜行与智谋的考验。",kw={"塞纳里奥区","达纳苏斯","命运的召唤","卡多雷","潜行者训练师","塞尤娜","泰达希尔"},ang={["class:Rogue"]="作为暗夜精灵潜行者，你可以向塞尤娜学习潜行、用毒和精准的战斗技艺，她是达纳苏斯的主要导师之一。",["race:NightElf"]="作为暗夜精灵，你也传承着Kaldorei斥候默默守护的传统，从阴影中保护林地圣所，而非公开交战。"},sec={{t="林间的斥候",b="塞尤娜训练那些在达纳苏斯来去无踪的人。在塞纳里奥区，她教授潜行者闪避、开锁和致命打击的技巧。哨兵展现着卡多雷的武力，而艾露恩姐妹会承载着他们的精神智慧。卡多雷也倚重阴影与潜行，塞尤娜则磨砺着守护泰达希尔的双眼与利刃。"},{t="智谋的考验",b="塞尤娜对年轻特工的考验，并不止于塞纳里奥区内传授的课程。她派有潜力的新手深入实地执行任务，看看他们是否具备走出世界之树枝桠庇护后生存的本能，并在危机四伏的边疆为联盟效力。"}},faq={{q="塞尤娜是谁？",a="塞尤娜在达纳苏斯的塞纳里奥区训练暗夜精灵潜行者。她传授战斗技巧，并指导为联盟效力的潜行者。",al={"塞尤娜 达纳苏斯","塞尤娜是谁","暗夜精灵潜行者训练师"}},{q="在达纳苏斯的什么地方能找到塞尤娜？",a="塞尤娜就在达纳苏斯的塞纳里奥区，身处林木与亭阁之间，与其他传授暗影技艺的导师为邻。",al={"塞尤娜在哪","塞尤娜位置","达纳苏斯潜行者训练师位置"}},{q="为什么潜行者训练师会在塞纳里奥区？",a="塞纳里奥区主要以德鲁伊之道和自然而闻名，但暗夜精灵斥候与隐秘行动的探路者也在这里的林地边缘受训，远离艾露恩神殿和战士区公开而隆重的仪式。",al={"潜行者训练师为何在塞纳里奥区","塞纳里奥区潜行者"}},{q="塞尤娜提供哪些任务？",a="塞尤娜指导那些已在幽影谷证明自己的新手特工，让他们在更广阔的世界中磨炼本领，其中也包括通过命运的召唤接受历练。",al={"塞尤娜任务","命运的召唤任务"}}},fp="6,160,23.365.0,16.278.0,14.133.0,45.105.0,47.218.0,30.152.0"}
P.entries["npc:tabetha"] = {n="塔贝萨",s="塔贝萨是一位隐居的人类法师，实力强大，住在尘泥沼泽深处泥潭沼泽的一处偏僻农庄里。她远离达拉然和塞拉摩的政治纷争，教导有志求学的施法者，并帮助那些寻求掌控强大奥术与秘术遗物的人。",h="塔贝萨是一位隐居的人类法师，实力强大，住在尘泥沼泽深处泥潭沼泽的一处偏僻农庄里。她远离达拉然和塞拉摩的政治纷争，教导有志求学的施法者，并帮助那些寻求掌控强大奥术与秘术遗物的人。",kw={"尘泥沼泽","法师任务","梅纳拉·沃伦德","奥拉赫宝珠","泥潭沼泽","塔贝萨","塔贝萨的农场"},ang={["class:Mage"]="塔贝萨是中等等级法师不可或缺的导师，她会考验你对奥术仪式的掌握，并派你前往奥达曼等危险之地磨炼技艺。",["class:Warlock"]="虽然塔贝萨修习的是奥术，但她对魔法遗物的深刻理解，使她成为处理地狱火宝珠和奥拉赫宝珠等危险神器时至关重要的向导。"},sec={{t="泥潭沼泽的隐士",b="塔贝萨与她的学徒住在尘泥沼泽湿地深处的一间隐蔽小屋里，位于石槌废墟以北。她与炼金药瓶和古老典籍为伴，主动选择了隐居，远离东部王国学术界的等级秩序。尽管居所偏远，她精通奥术的名声仍足以让卡利姆多各地的施法者冒着野兽与泥沼的危险，前来寻求指点。"},{t="中立的导师",b="塔贝萨鲜明地置身于阵营冲突之外。虽然生为人类，但无论是联盟还是部落，只要初学者展现出求学的意愿，她都不会拒之门外，她既教导法师，也协助术士施行与奥拉赫宝珠等物品有关的危险束缚仪式。她的过往与梅纳拉·沃伦德等人物有所交集，揭示了她在秘术领域的深厚经历，远非单纯的阵营归属所能概括。"}},faq={{q="在哪里可以找到塔贝萨？",a="塔贝萨住在塔贝萨的农场的一间隐蔽小屋里，那里位于尘泥沼泽西部的泥潭沼泽深处，就在石槌废墟以北。",al={"塔贝萨位置","塔贝萨在哪里","塔贝萨农场地图"}},{q="塔贝萨会敌视部落玩家吗？",a="不会。虽然是人类，塔贝萨却保持中立。她教导学徒，并一视同仁地帮助部落和联盟的施法者。",al={"塔贝萨仅限联盟吗","部落能与塔贝萨交谈吗","塔贝萨阵营"}},{q="法师和术士为何前来找她？",a="塔贝萨掌握着有关奥术仪式、魔法聚焦器和束缚仪式的罕见知识。法师向她请教，以精进技艺并接受力量的试炼，而术士则借助她的专长，净化或束缚奥拉赫宝珠之类的强大神器。",al={"为何拜访塔贝萨","塔贝萨职业任务","奥拉赫宝珠 塔贝萨"}},{q="她与梅纳拉·沃伦德有什么联系？",a="塔贝萨与梅纳拉·沃伦德有着长久的交情。虽然两人走上了不同的道路，但她们对强大遗物和束缚魔法的共同理解，仍将隐居各处的二人联系在一起。",al={"塔贝萨与梅纳拉","梅纳拉·沃伦德的过往"}}},fp="7,136,22.263.0,16.263.0,25.137.0,36.121.0,39.241.0,44.183.0"}
P.entries["npc:tai-jin"] = {n="泰金",s="在剃刀岭兵营，泰金引导年轻的黑暗之矛牧师传承他们的精神传统。她教授圣光与暗影的平衡，以及虚弱妖术等仪式。",h="在剃刀岭兵营，泰金引导年轻的黑暗之矛牧师传承他们的精神传统。她教授圣光与暗影的平衡，以及虚弱妖术等仪式。",kw={"黑暗之矛","杜隆塔尔","虚弱妖术","牧师训练师","剃刀岭","泰金"},ang={["class:Priest"]="作为在杜隆塔尔受训的部落牧师，你会先向泰金学习，再前往奥格瑞玛的宏伟厅堂。",["race:Troll"]="作为一名年轻的黑暗之矛巨魔，你可以向泰金学习独特的法术，其中包括虚弱妖术。"},sec={{t="剃刀岭的女牧师",b="泰金在剃刀岭兵营指引年轻的牧师，帮助他们踏上杜隆塔尔的旅途。这里的兽人主要研习萨满之道或术士法术，而黑暗之矛巨魔则将与灵魂和洛阿神灵沟通的传统带入部落。泰金教授牧师之道的基本原则、圣光与暗影的平衡，以及巨魔文化中的精神传承。"}},faq={{q="在哪里可以找到泰金？",a="泰金位于杜隆塔尔中部的剃刀岭兵营内，在底层的其他职业训练师旁边。",al={"泰金位置","泰金在哪里","泰金 剃刀岭"}},{q="泰金教授什么？",a="随着新手牧师积累经验，泰金会教授他们法术、法术等级和技能，也为巨魔新入门者提供初步指导。",al={"泰金训练师","泰金教授什么","剃刀岭牧师法术"}},{q="为什么巨魔牧师会驻留在兽人定居点？",a="剃刀岭训练从试炼谷和森金村出发的年轻部落冒险者。由于兽人并不修习牧师之道，泰金便将黑暗之矛的精神传统带到了这处定居点。",al={"泰金为何在剃刀岭","剃刀岭兵营的巨魔"}},{q="泰金为巨魔牧师提供哪些特殊仪式？",a="泰金引导黑暗之矛牧师完成入门的精神仪式，其中包括引导先祖诅咒的虚弱妖术。",al={"虚弱妖术 任务","泰金任务"}}},fp="7,180,23.330.0,25.120.0,24.140.0,53.195.0,58.137.0"}
P.entries["npc:taiga-wisemane"] = {n="泰迦·慧鬃",s="泰迦·慧鬃守望着凄凉之地的西海岸。他驻足葬影村，留意荒原各处蠢蠢欲动的黑暗巫术。",h="泰迦·慧鬃守望着凄凉之地的西海岸。他驻足葬影村，留意荒原各处蠢蠢欲动的黑暗巫术。",kw={"火刃氏族","恶魔之盒","凄凉之地","埃鲁索斯之手","玛诺洛克集会所","葬影村","泰迦·慧鬃","雷斧堡垒"},ang={["class:Warlock"]="术士或许会留意到泰迦对埃鲁索斯之手的了解。他利用这件圣物的共鸣使恶魔传送门崩塌，而非通过神圣仪式将其驱逐。",["faction:Horde"]="泰迦为途经凄凉之地的部落勇士提供指引。他的忠告帮助葬影村的部落哨站抵御恶魔的侵袭。",["race:Tauren"]="对于牛头人旅人而言，泰迦代表着治愈卡利姆多、保护它免遭非自然恶魔侵蚀的责任。他挺身对抗那给凄凉之地留下累累伤痕的黑暗遗祸。"},sec={{t="葬影村的守望者",b="葬影村是黑暗之矛巨魔在海边建立的渔村。泰迦·慧鬃驻守于此，监视凄凉之地各处蠢蠢欲动的黑暗巫术。他知道灵魂的腐化正渗入土壤，始终注视着东方。暗影教派与恶魔残部在古老的废墟间滋长。"},{t="遏制恶魔之潮",b="火刃氏族以雷斧堡垒为据点，其教徒在那里试验黑暗神器，试图扩大势力。泰迦察觉到凄凉之地的居民面临的危险，便派遣能干的冒险者深入堡垒，夺取装有埃鲁索斯之手的恶魔之盒。\n\n泰迦希望这一击能让教派失去用来撕裂世界间帷幕的法器。"},{t="封闭集会所的传送门",b="取得埃鲁索斯之手只是泰迦计划的第一步。在凄凉之地南部的玛诺洛克集会所，火刃氏族已经打开了恶魔裂隙。\n\n泰迦指引信任的勇士，用这件黑暗法器对付制造它的人。他们将法器的能量注入传送门，在燃烧军团向卡利姆多腹地派遣援军之前将其关闭。"}},faq={{q="泰迦·慧鬃是谁？",a="泰迦·慧鬃是凄凉之地西海岸葬影村的一位牛头人长者。他为旅人提供指引，也委托他们追查并阻止火刃氏族的恶魔仪式。",al={"泰迦是谁","泰迦·慧鬃的故事","泰迦 葬影村"}},{q="为什么一个牛头人会住在葬影村？",a="葬影村主要由巨魔居住，也是部落在凄凉之地沿岸的主要哨站。泰迦留在这里监视荒原，并招募途经此地的部落旅人，应对附近的恶魔威胁。",al={"泰迦为什么在葬影村","泰迦 巨魔村落","巨魔城镇中的牛头人"}},{q="火刃氏族在凄凉之地做什么？",a="火刃氏族是一个教派，其暗影巫术与恶魔残部困扰着凄凉之地。泰迦在葬影村监视着它们的蔓延。",al={"火刃氏族 凄凉之地","教徒在做什么","雷斧堡垒教徒"}},{q="埃鲁索斯之手是什么？",a="埃鲁索斯之手是一件恶魔神器，藏在雷斧堡垒的恶魔之盒中。火刃氏族打算利用它的邪恶力量，开启通往虚空的传送门。",al={"埃鲁索斯之手","恶魔之盒是什么","恶魔之盒 圣物"}},{q="玛诺洛克集会所发生了什么？",a="玛诺洛克集会所位于凄凉之地南部，恶魔的腐化已在那里扎根。泰迦监视着在这片区域蔓延的威胁。",al={"玛诺洛克集会所传送门","玛诺洛克集会所是什么","凄凉之地传送门"}},{q="泰迦属于某个特定的牛头人部族吗？",a="泰迦姓慧鬃，是一位关心灵魂平衡与恶魔腐化的长者。他在联合部族的旗帜下，为整个部落效力。",al={"泰迦的部族","慧鬃部族","泰迦属于血蹄吗"}}},fp="14,140,28.324.0,25.372.1,27.364.1,22.184.0,45.208.0,44.145.0,27.166.0,31.142.0,45.172.0"}
P.entries["npc:takar-the-seer"] = {n="先知塔卡尔",s="在陶拉祖营地以东，先知塔卡尔独自在贫瘠之地扎营。尽管四周都是部落领土，他依然效忠联盟，并向某些旅人传授神秘学知识。",h="在陶拉祖营地以东，先知塔卡尔独自在贫瘠之地扎营。尽管四周都是部落领土，他依然效忠联盟，并向某些旅人传授神秘学知识。",kw={"贫瘠之地隐士","陶拉祖营地","噬魂者","同心树","魅魔任务","先知塔卡尔"},ang={["class:Warlock"]="身为联盟术士，你可以在卡利姆多向塔卡尔寻求指引，完成危险的仪式，召唤并束缚一只魅魔为你效命。",["faction:Alliance"]="身为联盟旅人，你可以在部落领土深处找到一位友善的人类，不过塔卡尔始终独居在卡利姆多中部的营地里。"},sec={{t="草原上的隐士",b="先知塔卡尔独自住在陶拉祖营地以东的一顶简陋帐篷里。牛头人勇士和兽人巡逻队守望着周围的贫瘠之地，却从不打扰他栖身的偏僻空地。他不信任好奇的部落访客，却很少主动挑起战斗，只是独来独往，注视着地平线。他的营地远离暴风城的政治纷争。"},{t="神秘学指引",b="先知塔卡尔向少数来到营地的访客传授知识。来自东部王国的联盟术士试图束缚异界的危险生物时，会向他寻求晦涩的指引。他对隐秘力量和灵魂技艺的理解，吸引着这些施术者前往他偏远而危险的营地。"}},faq={{q="为什么一位人类先知独自住在贫瘠之地？",a="塔卡尔从未说过自己为何独居。他的营地位于陶拉祖营地以东，远离任何联盟哨站，术士们来访是为了他掌握的恶魔知识，而非他的身世。",al={"塔卡尔 为何在贫瘠之地","塔卡尔 在这里做什么","塔卡尔 的身世"}},{q="塔卡尔对部落玩家有敌意吗？",a="是的。塔卡尔效忠联盟，因此部落冒险者会发现他处于敌对状态。除非受到挑衅或有人靠得太近，否则他很少发动攻击。",al={"塔卡尔 是否友善","部落能否与 塔卡尔 交谈","塔卡尔 对部落的反应"}},{q="联盟冒险者为何来到他的营地？",a="联盟的求知者，尤其是术士，会向塔卡尔寻求束缚 魅魔 等强大恶魔的指引。他给出晦涩的指示，并讲解召唤和支配这些恶魔所需的材料。",al={"塔卡尔 的任务","为何拜访 塔卡尔","谁会与 塔卡尔 交谈"}}},fp="14,193,25.327.0,14.308.0,48.172.0,34.140.0,45.210.0"}
P.entries["npc:takata-steelblade"] = {n="塔卡塔·钢刃",s="塔卡塔·钢刃是一名兽人战士，驻守在凄凉之地的幽灵岗哨。科尔丹将他与玛乌林·碎骨一同从奥格瑞玛派往此地，由他率领部落在当地对抗恶魔腐化。他的首要目标是消灭这一带与邪恶的火刃氏族勾结的萨特。",h="塔卡塔·钢刃是一名兽人战士，驻守在凄凉之地的幽灵岗哨。科尔丹将他与玛乌林·碎骨一同从奥格瑞玛派往此地，由他率领部落在当地对抗恶魔腐化。他的首要目标是消灭这一带与邪恶的火刃氏族勾结的萨特。",kw={"碎骨","火刃氏族","凄凉之地","幽灵岗哨","科尔丹","玛乌林","萨特","钢刃","塔卡塔"},ang={["class:Warrior"]="塔卡塔是一位剑术大师，他在作战中注重以果断的武力斩杀恶魔渗透者。",["faction:Horde"]="塔卡塔在凄凉之地统筹部落的地区防御，以幽灵岗哨为据点，清除恶魔渗透者。",["race:Orc"]="塔卡塔奉奥格瑞玛领袖之命行事，践行着兽人的职责，誓要铲除一切奴役于恶魔的残余势力。"},sec={{t="奉命前往凄凉之地",b="塔卡塔·钢刃奉科尔丹的直接命令，从主城前往凄凉之地；科尔丹在奥格瑞玛颇具影响力，致力于揭露并清除恶魔的暗中渗透。塔卡塔以偏远的牛头人营地幽灵岗哨为据点，统筹军事行动，对抗肆虐这片荒芜之地、效忠于燃烧军团的势力。"},{t="萨特的克星",b="同伴玛乌林·碎骨试图直接追踪并铲除秘密活动的火刃氏族教徒，而塔卡塔则将矛头指向他们的恶魔盟友：萨特。塔卡塔策划了针对凄凉之地堕落萨特的猛烈攻势，大量歼灭他们，意图瓦解教派在当地的势力，并遏止他们散播的污秽。"}},faq={{q="塔卡塔·钢刃是谁？",a="塔卡塔·钢刃是一名久经沙场的兽人战士，驻守在凄凉之地的幽灵岗哨。他指挥作战，对抗恶魔势力以及与火刃氏族结盟的萨特。",al={"塔卡塔","塔卡塔的故事","塔卡塔是谁"}},{q="是谁派塔卡塔前往凄凉之地的？",a="科尔丹将他从奥格瑞玛派往此地，消除火刃氏族及其恶魔盟友在整个地区造成的威胁。",al={"谁派遣了塔卡塔","与科尔丹的联系","塔卡塔的命令"}},{q="塔卡塔与玛乌林·碎骨是什么关系？",a="两人由科尔丹一同派遣而来。玛乌林试图直接对付火刃氏族教徒，而塔卡塔则集中兵力，打击与他们结盟的萨特。",al={"塔卡塔与玛乌林","玛乌林·碎骨"}},{q="塔卡塔为何猎杀萨特？",a="凄凉之地的萨特正与火刃氏族教派积极勾结，散播恶魔的污秽，威胁部落在这一地区的立足之地。",al={"为何杀死萨特","塔卡塔与萨特","遭萨特玷污"}},{q="在哪里可以找到塔卡塔·钢刃？",a="他位于幽灵岗哨，那是凄凉之地中北部的一处部落营地。",al={"塔卡塔的位置","塔卡塔·钢刃在哪里"}}},fx={a8c99361={q="塔卡塔·钢刃属于哪一方？",a="塔卡塔·钢刃忠于部落，听命于奥格瑞玛的科尔丹。他致力于在凄凉之地维护部落的利益，清除威胁卡利姆多的恶魔势力，特别针对那些与他的族人敌对的邪恶教派和恶魔。",al={"塔卡塔·钢刃的阵营","塔卡塔的忠诚归属","塔卡塔是部落成员吗"}},["683721f0"]={q="塔卡塔·钢刃为什么在这里？",a="塔卡塔奉科尔丹之命驻守幽灵岗哨，领导当地对抗恶魔腐化的攻势。他的同伴玛乌林·碎骨专门对付火刃氏族教派，而塔卡塔则将怒火倾泻在此地的萨特身上，发动无情的行动，意图将他们彻底铲除。",al={"塔卡塔为何在凄凉之地","塔卡塔·钢刃的职责","塔卡塔在这里做什么"}},a7138bd5={q="塔卡塔·钢刃为何声名狼藉或令人畏惧？",a="凄凉之地那些邪恶的居民都知道塔卡塔恶名昭著，因为他对当地萨特进行了毁灭性、有计划的大屠杀。他在荒凉的废土上大肆杀戮每一个与火刃氏族有关联的萨特，因此声名骇人。",al={"塔卡塔的名声","塔卡塔为何令人畏惧","塔卡塔的声名"}}},fp="17,220,16.248.0,21.263.0,25.155.0,28.97.0,64.137.0,29.144.0,37.82.0"}
P.entries["npc:tal"] = {n="塔尔",s="在莫高雷平原上方的雷霆崖，塔尔照料着部落最主要的驭风者栖息地。他派出经验丰富的双足飞龙，载着旅人穿行于卡利姆多各地。",h="在莫高雷平原上方的雷霆崖，塔尔照料着部落最主要的驭风者栖息地。他派出经验丰富的双足飞龙，载着旅人穿行于卡利姆多各地。",kw={"飞行管理员","莫高雷","栖息地","塔尔","雷霆崖","驭风者管理员","双足飞龙"},ang={["faction:Horde"]="身为部落的一员，你可以利用塔尔的栖息地，往返于牛头人的主城、十字路口和奥格瑞玛之间。",["race:Tauren"]="身为一名走出祖辈牧场的牛头人，你可以依靠塔尔，以最快捷、最安全的方式离开高崖，前往更广阔的世界。"},sec={{t="高崖栖所的看守者",b="塔尔照料着雷霆崖中央台地上的驭风者栖息地，将牛头人的主城与部落其他地区连接起来。他悉心照料这些忠诚的驭风者，也就是双足飞龙，让它们保持健康、吃饱喝足，为穿越卡利姆多的漫长旅程做好准备。他从栖息地派出信使前往陶拉祖营地，也派出斥候穿越贫瘠之地，前往奥格瑞玛。这些航线让这座高耸于台地之上的城市与盟友保持着联系。"}},faq={{q="塔尔在雷霆崖担任什么职务？",a="塔尔是雷霆崖的驭风者管理员。他管理着崖顶的栖息地，照料这些长着双翼的野兽，并为部落成员安排前往卡利姆多各地的飞行。",al={"塔尔是谁","塔尔飞行管理员","塔尔做什么"}},{q="塔尔会将旅人送往何处？",a="塔尔将旅人从雷霆崖送往卡利姆多中部和南部各地，包括陶拉祖营地、十字路口、奥格瑞玛，以及遥远的荒野哨站。",al={"塔尔能飞往哪里","塔尔的目的地","雷霆崖飞行路线"}},{q="为什么使用驭风者，而不是传统坐骑？",a="驭风者是飞行坐骑，能够让旅人迅速、直接地进出雷霆崖。这座城市地势高耸，四周悬崖陡峭，地面路线既缓慢又曲折，而乘坐飞行坐骑则无需使用升降梯。",al={"为何使用双足飞龙","雷霆崖飞行野兽"}}},fp="3,155,24.391.0,41.174.0,30.174.0,55.209.0"}
P.entries["npc:talen"] = {n="塔尔伦",s="塔尔伦驻扎在佐拉姆海岸旁的营地，沿着海岸搜寻 卡多雷 遗物。附近的纳迦和部落哨站让这项工作危机四伏。",h="塔尔伦驻扎在佐拉姆海岸旁的营地，沿着海岸搜寻 卡多雷 遗物。附近的纳迦和部落哨站让这项工作危机四伏。",kw={"古代雕像","考古学家","灰谷","卢泽尔","塔尔伦","佐拉姆海岸"},ang={["faction:Alliance"]="在灰谷北部的争夺地区，迈斯特拉岗哨附近的塔尔伦是联盟旅者的一位野外联络人。",["race:NightElf"]="对 kaldorei 而言，佐拉姆海岸让他们想起了 Sundering。古老的沿海庄园沉入无尽之海时，许多文化遗产随之失落，塔尔伦致力于保护并找回这些遗产。"},sec={{t="海岸上的学者",b="在佐拉姆海岸旁的一处营地里，塔尔伦潜心研究往昔，而非拿起武器。纳迦和部落哨站让这片海岸危机四伏，但他仍在海浪与沙土下的废墟中寻找失落的 卡多雷 遗物。他依靠旅者对付怒尾纳迦，找回文物，包括完好的雕像，以及他们的首领卢泽尔持有的佐拉姆之戒。"}},faq={{q="塔尔伦是谁？",a="在佐拉姆海岸附近的营地里，塔尔伦研究着埋藏在岸边的古代 卡多雷 遗物。他是一名暗夜精灵学者和业余考古学家，并非哨兵或士兵。",al={"这个暗夜精灵是谁","塔尔伦 灰谷","塔尔伦 佐拉姆海岸"}},{q="塔尔伦为什么在佐拉姆海岸附近扎营？",a="塔尔伦在佐拉姆海岸附近扎营，是为了调查沉入水下的废墟，找回古代 卡多雷 文物。凶暴的纳迦在海滩上游荡，部落哨站佐拉姆加也在附近，因此他住在一处远离主要海岸线的小营地里。",al={"塔尔伦为什么在这里","塔尔伦的目的"}},{q="塔尔伦想要哪些文物？",a="塔尔伦请旅者沿着海岸寻找被冲上岸的古代雕像，并猎杀附近离岸小岛上的强大纳迦卢泽尔。卢泽尔持有佐拉姆之戒，这枚戒指能解开雕像。",al={"塔尔伦的任务","塔尔伦需要什么","卢泽尔 任务"}},{q="塔尔伦敌视部落吗？",a="塔尔伦与暗夜精灵站在同一阵营，但他是一名学者。除非部落旅者先挑衅或攻击他，否则他不会主动攻击他们。",al={"塔尔伦会攻击部落吗","塔尔伦对部落友好吗"}}},fp="5,125,20.368.0,13.176.0,43.240.0,31.201.0,30.134.0"}
P.entries["npc:tallonkai-swiftroot"] = {n="塔隆凯·捷根",s="腐化在泰达希尔的枝叶下蔓延，塔隆凯·捷根在多兰纳尔守望着林地。他派遣年轻的冒险者找回魔法圣物，并遏制侵扰森林的邪恶势力。",h="腐化在泰达希尔的枝叶下蔓延，塔隆凯·捷根在多兰纳尔守望着林地。他派遣年轻的冒险者找回魔法圣物，并遏制侵扰森林的邪恶势力。",kw={"多兰纳尔","摄梦符","菲罗斯塔","塔隆凯·捷根","泰达希尔","扭曲的仇恨"},ang={["class:Druid"]="身为德鲁伊，你深知这些圣物在精神层面的重要意义，它们让心智与翡翠梦境保持安全的联系。",["race:NightElf"]="身为暗夜精灵，在腐化于你的新家园扎根之时，你可以帮助守护泰达希尔。"},sec={{t="多兰纳尔的哨兵",b="塔隆凯·捷根在多兰纳尔守望着林地，这处聚落坐落于泰达希尔的树冠之中。和许多生活在新生的世界之树之下的暗夜精灵一样，野生动物的反常举动和家园边缘聚集的阴影令他深感不安。"},{t="树冠中的威胁",b="塔隆凯派遣冒险者对抗扰乱泰达希尔安宁的邪恶生物。被腐化的摄梦符威胁着德鲁伊的睡眠，而瘤背熊怪也在黑暗病症的影响下变得凶暴。噬梦者菲罗斯塔率领着被腐化的瘤背秘术师。塔隆凯力图清除这些威胁，守护卡多雷脆弱的家园。"}},faq={{q="塔隆凯·捷根是谁？",a="塔隆凯·捷根守护着多兰纳尔，努力保护这里免受周边威胁的侵害。他是一名暗夜精灵，居住在泰达希尔枝干上的这处聚落中。",al={"塔隆凯是谁","塔隆凯·捷根","多兰纳尔任务发布者"}},{q="在哪里可以找到塔隆凯·捷根？",a="塔隆凯·捷根位于多兰纳尔，那是泰达希尔中部的一座暗夜精灵村庄，就在幽影谷外。",al={"塔隆凯位置","塔隆凯在哪里","寻找塔隆凯·捷根"}},{q="塔隆凯会交付哪些任务？",a="塔隆凯请旅人从瘤背熊怪手中取回翡翠摄梦符，击败噬梦者菲罗斯塔，并在扭曲的仇恨任务中，前往地狱石的洞穴击杀迈雷纳斯。",al={"塔隆凯的任务","塔隆凯想要什么"}},{q="他为什么关心摄梦符？",a="摄梦符是与翡翠梦境相连的暗夜精灵神圣护符。它们能抵御梦魇和黑暗幻象，因此，摄梦符遭到盗窃和腐化，会危及当地的德鲁伊和泰达希尔的其他居民。",al={"翡翠摄梦符背景故事","为什么关心摄梦符"}},{q="噬梦者菲罗斯塔是谁？",a="噬梦者菲罗斯塔在星风以北率领着被腐化的瘤背秘术师。他偷走了塔隆凯摄梦符上的翡翠，并将它佩戴在一条项链上，到了夜间便会发出绿光。",al={"菲罗斯塔是谁","菲罗斯塔背景故事"}},{q="塔隆凯所对抗的动乱因何而起？",a="日益严重的病症和异常的腐化已在泰达希尔蔓延。它们使包括瘤背熊怪在内、曾经温顺的生物陷入狂暴与疯狂。",al={"熊怪为何发狂","扭曲的仇恨背景故事"}}},fp="19,197,22.264.0,21.345.0,27.155.0,37.114.0,31.189.0,44.209.0,33.187.0,52.167.0"}
P.entries["npc:tallow"] = {n="塔隆",s="在塔伦米尔，Tallow为黑暗女王和部落监视着双方争夺的前线。这名被遗忘者战士协助组织攻势，打击希尔斯布莱德丘陵的联盟威胁。",h="在塔伦米尔，Tallow为黑暗女王和部落监视着双方争夺的前线。这名被遗忘者战士协助组织攻势，打击希尔斯布莱德丘陵的联盟威胁。",kw={"被遗忘者","希尔斯布莱德丘陵","部落战士","塔洛","塔伦米尔","落锤之战"},ang={["faction:Horde"]="作为部落的一员，你可以帮助Tallow削弱人类在希尔斯布莱德丘陵各地的势力。",["race:Undead"]="身为被遗忘者，你与Tallow为同一个目标而战，将幽暗城的统治扩展到奥特兰克山脉以南。"},sec={{t="塔伦米尔的利刃",b="Tallow与被遗忘者及部落军队一同驻守希尔斯布莱德丘陵的塔伦米尔。战火在这片地区蔓延，附近有南海镇的人类，道路上有辛迪加匪徒，镇外还有凶猛的野兽。Tallow派遣有能力的冒险者前往阿拉希高地，对抗石拳食人魔，检验他们的实力。随后，他指引他们前去支援遭到围攻的落锤镇哨站。"}},faq={{q="塔洛是谁？",a="塔洛是塔伦米尔的一名被遗忘者战士，负责组织在这一带作战的部落勇士。",al={"塔洛是谁","塔洛的故事","塔洛 塔伦米尔"}},{q="在哪里可以找到塔洛？",a="塔洛就在塔伦米尔，这座城镇位于希尔斯布莱德丘陵北部，由被遗忘者控制。",al={"塔洛在哪里","塔洛的位置","寻找塔洛"}},{q="塔洛提供哪些任务？",a="塔洛派遣部落冒险者前往阿拉希高地，对抗石拳食人魔以证明自己的实力，随后到遭到围攻的落锤镇向杜拉姆法尔报到。",al={"塔洛的任务","落锤之战任务"}},{q="塔伦米尔在冲突中扮演什么角色？",a="塔伦米尔是部落在希尔斯布莱德丘陵北部的主要据点。它与南方的人类堡垒南海镇之间，既有小规模冲突，也有公开交战。",al={"塔伦米尔为何重要","塔伦米尔的作用"}}},fp="6,176,22.412.0,14.95.0,24.87.0,30.172.0,43.165.0"}
P.entries["npc:talvash-del-kissel"] = {n="塔瓦斯德·基瑟尔",s="在铁炉堡的秘法区，侏儒珠宝匠塔瓦斯德·基瑟尔正时运不济。石腭怪攻陷诺莫瑞根时，他逃了出来，随后又在不光彩交易的传闻中债台高筑。如今，他求助于冒险者，找回遗失的宝物，修复破碎的遗物。他鉴别宝石和古代饰物的眼光，让他成为探索奥达曼的人们看重的联系人。",h="在铁炉堡的秘法区，侏儒珠宝匠塔瓦斯德·基瑟尔正时运不济。石腭怪攻陷诺莫瑞根时，他逃了出来，随后又在不光彩交易的传闻中债台高筑。如今，他求助于冒险者，找回遗失的宝物，修复破碎的遗物。他鉴别宝石和古代饰物的眼光，让他成为探索...",kw={"基瑟尔","诺莫瑞根","铁炉堡","珠宝匠","秘法区","破碎的项链","塔瓦斯德","奥达曼"},ang={["faction:Alliance"]="探索奥达曼或诺莫瑞根废墟的联盟冒险者，可以找塔瓦斯德修复古代珠宝，找回遗失的侏儒传家宝。",["race:Gnome"]="塔瓦斯德的遭遇展现了诺莫瑞根的陷落如何摧毁普通平民的生活，让技艺高超的工匠沦为身无分文的流亡者，在铁炉堡勉强度日。"},sec={{t="从工匠到流亡的债务人",b="塔瓦斯德曾是诺莫瑞根一位受人尊敬的珠宝匠，直到石腭怪攻陷城市，毁掉了他的家园和生计。他与幸存的难民一同逃往铁炉堡，在秘法区安顿下来。然而，迁居并未让他的处境好转多少。\n\n不光彩交易和拖欠债务的传闻缠绕着他，让这位工匠陷入了严重的财务困境。他无法靠常规途径重拾旧业，如今只能依靠自由冒险者找回遗失的财物，挽救自己的声誉。"},{t="奥达曼遗物与侏儒工艺",b="塔瓦斯德仍然精于宝石加工，也保留着鉴定宝石价值的本领。当荒芜之地的探索者在奥达曼深处的泰坦宝库中发现一条古老的破碎项链时，东部王国鲜有工匠能弄懂其复杂的附魔。要恢复它的力量，需要稀有的材料和细致艰苦的修复工作。塔瓦斯德很愿意接下这份活，既能还清债务，也能证明自己的手艺仍在。"}},faq={{q="塔瓦斯德·基瑟尔是谁？",a="塔瓦斯德是一位流亡在外的诺莫瑞根侏儒珠宝匠，如今住在铁炉堡的秘法区。他背负着债务，又受传闻困扰，于是雇用冒险者修复古物，清偿欠账。",al={"塔瓦斯德是谁","塔瓦斯德·基瑟尔","塔瓦斯德"}},{q="在哪里能找到塔瓦斯德？",a="塔瓦斯德住在铁炉堡的秘法区，就在池塘和魔法商店附近。",al={"塔瓦斯德位置","塔瓦斯德在哪里","寻找塔瓦斯德·基瑟尔"}},{q="他在诺莫瑞根的生意出了什么事？",a="石腭怪入侵、城市陷落之前，塔瓦斯德在诺莫瑞根经营珠宝生意。他失去了一切，传闻和厄运又让他在铁炉堡欠下了巨额债务。",al={"塔瓦斯德为何身无分文","塔瓦斯德债务","塔瓦斯德遭遇了什么"}},{q="塔瓦斯德与奥达曼有什么联系？",a="在奥达曼古老的挖掘场找到破碎能量源的探索者，会被指引去找塔瓦斯德。凭借宝石加工和附魔的技艺，他能为集齐缺失碎片的冒险者重新组装那条破碎的项链。",al={"塔瓦斯德奥达曼","奥达曼项链","破碎的项链任务"}},{q="塔瓦斯德与诺莫瑞根的任务有关吗？",a="有。塔瓦斯德会帮忙找回撤离诺莫瑞根时遗落的私人物品，包括丢失的戒指和装置。",al={"塔瓦斯德诺莫瑞根","归还戒指任务"}}},fp="18,367,29.538.0,35.407.0,26.186.0,25.85.0,44.174.0,40.224.0,56.119.0"}
P.entries["npc:tammra-windfield"] = {n="塔姆拉·荒原",s="在烈日石居，塔姆拉·荒原引导部落旅者敬重土地的新生。这位牛头人守望着石爪山脉的荒野，也关心族人的安危。",h="在烈日石居，塔姆拉·荒原引导部落旅者敬重土地的新生。这位牛头人守望着石爪山脉的荒野，也关心族人的安危。",kw={"生生不息","卡雅","新的生命","石爪山脉","烈日石居","塔姆拉","牛头人","荒原"},ang={["class:Druid"]="身为德鲁伊，你会看出塔姆拉对重生与新生命的关怀，正呼应着德鲁伊之道的核心。",["faction:Horde"]="身为部落的一员，你可以帮助塔姆拉，让烈日石居在各方争夺的石爪山脉中，始终成为部落旅者安全而稳固的据点。",["race:Tauren"]="身为牛头人，你能从塔姆拉修复土地的努力中，看见她对Earth Mother的虔诚，即使这里远离莫高雷。"},sec={{t="烈日石居的守望者",b="烈日石居坐落在石爪山脉的峭壁之间，为部落提供庇护。鹰身人、荆棘谷地精的伐木工和猛兽威胁着这处聚落。塔姆拉·荒原守望着山间荒野，也照看着踏入此地的旅者。她性情温和，却有着在这片崎岖山地守护家园所需的决心。"},{t="滋养大地",b="塔姆拉守望着自然生长与衰亡的恒常节律，以此敬奉大地母亲。她请旅者维护重生的循环，孕育新的生命，抵御争斗与掠夺给石爪山脉带来的伤害。对塔姆拉而言，保护土地就意味着治愈土地，让生命能在满目疮痍的山间土壤中蓬勃生长。"},{t="亲情与守望",b="塔姆拉关心的不只是荒野，还有行走在石爪山脉险径上的同伴与亲人。每当传来旅者或家人在峭壁间失踪的消息，她总是最先寻求可靠援助的人之一。烈日石居得以长存，既靠着与自然和谐共处，也靠着忠诚与彼此守护。"}},faq={{q="塔姆拉·荒原是谁？",a="塔姆拉·荒原是石爪山脉烈日石居的一位牛头人。她照料着聚落，维护山间的自然循环，也关心其他旅者的安危。",al={"塔姆拉是谁","塔姆拉·荒原","烈日石居 塔姆拉"}},{q="在哪里可以找到塔姆拉·荒原？",a="你可以在烈日石居内找到塔姆拉，那是位于石爪山脉西部高地的部落营地。一条山路从谷地的主路分出，通往那里。",al={"塔姆拉·荒原位置","塔姆拉在哪里","寻找塔姆拉·荒原"}},{q="塔姆拉提供哪些任务？",a="塔姆拉请旅者帮助土地焕发生机，并关照她的族人，任务包括生生不息、新的生命，以及由旅者回报族人幸存消息的卡雅还活着。",al={"塔姆拉任务","塔姆拉·荒原任务列表"}},{q="塔姆拉在烈日石居承担什么职责？",a="塔姆拉照料着烈日石居的居民，也关怀他们的精神生活。她指引旅者修复周围的荒野，守护维系哨站安全的纽带。",al={"塔姆拉做什么","塔姆拉职责"}},{q="塔姆拉为何关心自然循环？",a="牛头人相信，唯有呵护大地母亲的死亡与再生循环，才能维系平衡。外来势力与山间野兽威胁着这片地区，塔姆拉因此寻求以新生治愈受创的荒野。",al={"生生不息背景","石爪山脉为何需要重生"}},{q="塔姆拉对联盟玩家友好吗？",a="不友好。烈日石居是部落的哨站，塔姆拉效忠于雷霆崖和部落。她对联盟入侵者抱有敌意。",al={"塔姆拉是否敌对","联盟能否与塔姆拉交谈"}}},fp="16,162,20.310.0,18.274.0,21.286.0,24.178.0,34.177.0,30.174.0,42.188.0,45.209.0,39.134.0"}
P.entries["npc:tannok-frosthammer"] = {n="塔诺克·霜锤",s="在卡拉诺斯附近的雷酒酿制厂，塔诺克·霜锤正等待寒脊山谷送来的物资。穴居人的袭击封锁了通往安威玛尔的道路。",h="在卡拉诺斯附近的雷酒酿制厂，塔诺克·霜锤正等待寒脊山谷送来的物资。穴居人的袭击封锁了通往安威玛尔的道路。",kw={"安威玛尔","寒脊","酿制厂","霜锤","卡拉诺斯","塔诺克","雷酒","穴居人"},ang={["faction:Alliance"]="身为联盟的一员，你可以看到，穴居人日益频繁的袭击让卡拉诺斯这样位于腹地的定居点也倍感压力。",["race:Dwarf"]="作为一名离开安威玛尔的矮人，将物资送到雷酒酿制厂的塔诺克手中，是你迈向丹莫罗腹地的最初几步之一。"},sec={{t="中断的补给线",b="在卡拉诺斯的雷酒酿制厂，塔诺克·霜锤一边等候送来的物资，一边打听消息。穴居人涌入寒脊山小径，封锁了从寒脊山谷通往外界的常用路线，也切断了安威玛尔的日常音讯。侏儒技师汉兹·跳链穿过危险的积雪山道，运送物资并传递消息。随着地下的穴居人逐渐逼近家门，塔诺克与许多铜须部族一样忧心忡忡。"}},faq={{q="塔诺克·霜锤在哪里？",a="塔诺克·霜锤在丹莫罗的雷酒酿制厂外等候，就在卡拉诺斯主要十字路口的东边不远处。",al={"塔诺克位置","塔诺克在哪","寻找塔诺克·霜锤"}},{q="塔诺克为什么担心寒脊山谷？",a="穴居人占据了寒脊山小径，切断了安威玛尔与丹莫罗其他地区之间的日常通信和贸易。",al={"塔诺克的担忧","塔诺克为何担忧","寒脊山小径穴居人"}},{q="塔诺克与寒脊山谷的谁合作？",a="塔诺克接收寒脊山谷的侏儒供应商汉兹·跳链送来的物资。汉兹请过路的旅人帮忙，将货物运过危险的山道。",al={"塔诺克的供应商","汉兹·跳链送货","谁给塔诺克供应物资"}}},fx={["22aa1045"]={q="塔诺克·霜锤是谁？",a="塔诺克·霜锤是一名住在卡拉诺斯的铁炉堡矮人，驻守在雷酒酿制厂。他协助监管丹莫罗当地货物和补给的流通，维系着主要城镇与寒脊山谷等偏远哨站之间至关重要的补给联系。",al={"塔诺克是谁","塔诺克·霜锤的故事","塔诺克的身份"}},["93f9fc20"]={q="塔诺克·霜锤效忠哪一方？",a="塔诺克是铁炉堡的忠诚子民，也是联盟的坚定成员。他最关心的是丹莫罗居民的安危，以及如何在雪地中的威胁日益加剧时，确保他们的商路畅通。",al={"塔诺克的阵营","塔诺克属于联盟吗","塔诺克·霜锤的效忠对象"}},eebd916b={q="塔诺克·霜锤为什么在这里？",a="塔诺克在卡拉诺斯的雷酒酿制厂经营生意。他留在这里接收重要货物，并与远方的供货商保持联系，但最近寒脊山小径的变故阻断了货物运送，让他只能焦急地等待消息。",al={"塔诺克为什么在卡拉诺斯","塔诺克为什么在这里","塔诺克·霜锤的目的"}}},fp="18,150,21.437.0,36.111.0,45.124.0,46.165.0"}
P.entries["npc:taragaman-the-hungerer"] = {n="饥饿者塔拉加曼",s="在奥格瑞玛地下，饥饿者塔拉加曼徘徊于怒焰裂谷熔岩翻涌的洞穴中。这个魁梧的恶魔卫士被视为灼热之刃教派背后的恶魔主宰，令人畏惧，部落力图将其消灭，终结城下的恶魔污染。",h="在奥格瑞玛地下，饥饿者塔拉加曼徘徊于怒焰裂谷熔岩翻涌的洞穴中。这个魁梧的恶魔卫士被视为灼热之刃教派背后的恶魔主宰，令人畏惧，部落力图将其消灭，终结城下的恶魔污染。",kw={"巴扎兰","恶魔","恶魔卫士","饥饿者","耶戈什","奥格瑞玛","怒焰裂谷","灼热之刃","塔拉加曼"},ang={["class:Warlock"]="身为术士，你在上方的暗影裂口修习黑暗法术，而塔拉加曼这样狂暴且充满敌意的恶魔卫士，威胁着你所修习技艺的隐秘与安全。",["class:Warrior"]="身为战士，你必须顶住塔拉加曼势大力沉的攻击，并避免被他凶猛的上勾拳抛入熔岩。",["faction:Horde"]="对年轻的部落战士和施法者而言，在奥格瑞玛地下击杀塔拉加曼既是一场试炼，也有助于保护都城免遭恶魔腐化。"},sec={{t="地下的野兽",b="饥饿者塔拉加曼游荡在怒焰裂谷的岩浆池之间，从地下威胁着奥格瑞玛。被派入幽暗洞穴的斥候和年轻勇士将这个恶魔卫士视为灼热之刃教派的首领。他凭借恶魔之力，控制意志薄弱者，腐化萨尔堡垒下方的通道。"},{t="致命的诱饵",b="饥饿者塔拉加曼令教派成员畏惧，但真正的首领是萨特巴扎兰和术士祈求者耶戈什。这些阴谋家将高大的恶魔卫士当作可以牺牲的诱饵，用这个怪物吸引部落守卫深入灼热的火山洞穴，以便在那里将他们屠杀殆尽。"}},faq={{q="饥饿者塔拉加曼是哪一种恶魔？",a="塔拉加曼是一名恶魔卫士，属于燃烧军团凶残的恶魔突击兵。他在怒焰裂谷的岩浆洞穴中，以沉重的近战攻击和烈焰魔法对付入侵者。",al={"塔拉加曼 是什么种族","塔拉加曼 恶魔类型","塔拉加曼 是恶魔吗"}},{q="饥饿者塔拉加曼是灼热之刃教派的首领吗？",a="人们普遍认为塔拉加曼领导着灼热之刃。他是怒焰裂谷中最令人畏惧的恶魔力量，年轻的部落守卫被派去将他作为教派主宰诛杀。这道裂谷中隐藏的秘密，或许远不止一个恶魔卫士。",al={"谁领导 灼热之刃","塔拉加曼 掌权吗","塔拉加曼 教派首领"}},{q="部落为何要杀死塔拉加曼？",a="部落要杀死塔拉加曼，是因为一股活跃的恶魔势力正在都城地下滋生。他的恶魔腐化从内部威胁着奥格瑞玛，要确保街道下方洞穴通道的安全，就必须将他消灭。",al={"为何杀死 塔拉加曼","击杀比斯巨兽 任务背景","塔拉加曼 对奥格瑞玛的威胁"}},{q="在哪里能找到塔拉加曼？",a="塔拉加曼栖身于怒焰裂谷深处的地下火山隧道，从奥格瑞玛城内的暗影裂口可以进入那里。",al={"塔拉加曼 位置","塔拉加曼 在哪里","塔拉加曼 怒焰裂谷"}},{q="塔拉加曼的心脏会如何处置？",a="获胜的冒险者剜出塔拉加曼的心脏，以此证明野兽已死，并完成清剿奥格瑞玛地下恶魔先锋的任务。",al={"塔拉加曼 的心脏","塔拉加曼 之心","击杀比斯巨兽 心脏"}},{q="塔拉加曼如何作战？",a="塔拉加曼会施展势大力沉的物理攻击，以强力的上勾拳将敌人击飞，并偶尔释放 火焰新星，灼烧附近的敌人。",al={"塔拉加曼 技能","塔拉加曼 首领战","塔拉加曼 战斗机制"}}},fp="22,163,15.304.0,12.278.1,45.175.0,63.237.0,39.221.0,29.129.0,34.170.0,35.154.0"}
P.entries["npc:targorr-the-dread"] = {n="可怕的塔格尔",s="在暴风城监狱深处，可怕的塔格尔正混在暴动的囚犯之中。腐败与疏忽让他的死刑迟迟未能执行，而迪菲亚的暴动给了他逃脱的机会。",h="在暴风城监狱深处，可怕的塔格尔正混在暴动的囚犯之中。腐败与疏忽让他的死刑迟迟未能执行，而迪菲亚的暴动给了他逃脱的机会。",kw={"伯尔顿","黑石","可怕","行刑官","加塞尔佐格","湖畔镇","监狱","塔格尔"},ang={["faction:Alliance"]="在监狱暴动中除掉塔格尔，能为湖畔镇阵亡的守卫者伸张迟来的正义，也有助于遏制首都地下的混乱。",["race:Human"]="对暴风城的人类，尤其是那些与赤脊山有联系的人来说，塔格尔让他们想起王国官僚机构失职所付出的代价，以及黑石兽人持续带来的威胁。"},sec={{t="赤脊山的屠夫",b="被捕之前，可怕的塔格尔效力于督军加塞尔佐格，是黑石氏族的最高行刑官。他以赤脊山被占据的废墟为据点，其残忍程度甚至超出了黑暗部落的暴虐行径。守卫边境的暴风城卫兵和民兵在他手中饱受折磨，缓慢死去。整个王国中，鲜有名字比他的更遭人痛恨。"},{t="未能伸张的正义",b="联盟军队生擒塔格尔后，给他戴上镣铐，押往首都，关进了戒备森严的监狱。他的死刑被暴风城司法与政务机构的官僚作风拖延。贪污、无休止的文书手续和疏忽，使法庭迟迟未能执行他应得的死刑。这个嗜血的战犯仍被关在城市中心地下的牢房里。"},{t="牢房中的暴动",b="迪菲亚潜行者强行解救囚犯时，塔格尔抓住了机会。他逃出牢房，加入迪菲亚暴徒，将自己所在的监区变成了屠宰场。典狱官塞尔沃特已经失去了对监狱的控制。塔格尔给湖畔镇守卫者造成的创伤至今未愈，镇上正在寻找愿意深入暴乱、带回这个屠夫首级的冒险者。"}},faq={{q="可怕的塔格尔是谁？",a="可怕的塔格尔是一名黑石兽人，曾作为最高行刑官效力于督军加塞尔佐格。他因折磨被俘的暴风城士兵而臭名昭著，直到被捕，关进暴风城监狱。",al={"塔格尔是谁","塔格尔背景故事","监狱兽人首领"}},{q="塔格尔被捕后为什么没有被处决？",a="暴风城的司法机构低效、臃肿且腐败，无休止的文书手续拖延了对塔格尔的处决。法庭尚未来得及执行判决，监狱就爆发了暴动。",al={"为什么没有处死他","塔格尔为什么还活着","暴风城腐败"}},{q="一个兽人为什么会与迪菲亚潜行者结盟？",a="监狱暴动期间，各类囚犯联合起来反抗狱卒。塔格尔加入迪菲亚暴徒，是为了获得自由，并屠杀任何挡在他面前的卫兵或冒险者。",al={"迪菲亚为什么与兽人合作","塔格尔的迪菲亚盟友","监狱兽人"}},{q="现在谁想要塔格尔的命？",a="驻守在赤脊山湖畔镇的卫兵伯尔顿悬赏征求塔格尔的首级。湖畔镇深受塔格尔的残暴之害，希望执行暴风城法庭未能执行的死刑。",al={"谁发布塔格尔任务","卫兵伯尔顿 塔格尔","塔格尔悬赏"}},{q="在哪里能找到塔格尔？",a="塔格尔就在暴风城监狱内，与其他暴动的囚犯一起待在后方的一处监区。",al={"塔格尔在哪里","塔格尔位置","监狱房间"}},{q="塔格尔属于哪个氏族？",a="塔格尔属于黑石兽人，是盘踞在赤脊山和黑石塔一带、肆意作乱的黑暗部落残部之一。他们不属于萨尔领导的新的部落。",al={"塔格尔氏族","塔格尔属于部落吗","黑石 塔格尔"}}},fp="17,162,23.324.0,14.363.0,21.374.0,25.213.0,49.189.0,49.197.0,27.198.0,27.89.0,33.183.0"}
P.entries["npc:tarindrella"] = {n="塔琳德拉",s="塔琳德拉在幽影谷守护着泰达希尔幽静的林地。这位树妖与暗夜精灵守护者携手，调查世界之树野生生灵遭受腐化的缘由。",h="塔琳德拉在幽影谷守护着泰达希尔幽静的林地。这位树妖与暗夜精灵守护者携手，调查世界之树野生生灵遭受腐化的缘由。",kw={"奥达希尔","树妖","幽影谷","影丝","塔琳德拉","泰达希尔","树林蜘蛛"},ang={["class:Druid"]="身为德鲁伊，你视树妖为志同道合的荒野之灵。塔琳德拉对泰达希尔病患的指引，召唤你为维护平衡贡献力量。",["race:NightElf"]="身为幽影谷中一名年轻的暗夜精灵，你或许会遇见塔琳德拉。这位树妖体现着Kaldorei与塞纳留斯子嗣之间的古老盟约。"},sec={{t="幽影谷的塞纳留斯之女",b="塔琳德拉居住在幽影谷，那是泰达希尔顶端一片受到庇护的林地。树妖是自然的勇猛守护者，诞生于半神塞纳留斯。许多树妖生活在卡利姆多古老森林的深处，比如灰谷，而塔琳德拉守护着这片年轻的林地。她在荒野之灵与初次踏出奥达希尔的年轻暗夜精灵守卫之间架起桥梁。她最担忧的是正在森林中蔓延的污秽。她派遣可靠的冒险者驱除当地的害兽，并搜集线索，追查污秽的源头。"},{t="追查泰达希尔的病患",b="泰达希尔是暗夜精灵一族的新冠冕，然而疾病已侵入它的林地。熊怪曾在自己的家园中平静地生活；如今，他们聚集起来，组成了瘤背部族。受到邪恶魔苔污染的劣魔和小劣魔遍布幽影谷周围的山丘。塔琳德拉怀疑这些变化的根源正是魔苔。她指引初出茅庐的守卫对付劣魔并带回样本，希望在腐化吞噬这片年轻的林地之前将其遏止。"}},faq={{q="塔琳德拉是谁？",a="在泰达希尔顶端的幽影谷，塔琳德拉协助暗夜精灵守望荒野。这位树妖指引年轻的守卫，对抗威胁世界之树枝桠的怪病。",al={"塔琳德拉故事","塔琳德拉是谁","幽影谷树妖"}},{q="树妖是什么？",a="树妖是诞生于半神塞纳留斯的林地生灵。她们上半身如暗夜精灵，下半身如幼鹿，守护着卡利姆多的神圣林地及其平衡。",al={"树妖故事","树妖是什么","塞纳留斯之女"}},{q="塔琳德拉为何担忧幽影谷？",a="违背自然的腐化正在扭曲幽影谷周围的生灵。熊怪聚集起来，组成了充满敌意的瘤背部族，而受到魔苔污染的劣魔遍布山丘。塔琳德拉力图净化污秽，保护这片年轻的林地。",al={"幽影谷腐化","塔琳德拉任务","幽影谷出了什么问题"}},{q="她派冒险者去应对哪些威胁？",a="塔琳德拉派遣冒险者对付幽影谷的劣魔和小劣魔，并收集它们携带的邪恶魔苔。她希望查明魔苔是否就是腐化的根源。",al={"塔琳德拉蜘蛛","黑丝洞任务"}}},fp="11,162,36.513.0,37.461.0,19.180.0,16.176.0,46.228.0,47.176.0"}
P.entries["npc:tarrel-rockweaver"] = {n="塔雷尔·石纹",s="塔雷尔·石纹在米奈希尔港的桥边，焦急地等待妻子麦琳的消息。妻子加入了一支前往内陆的考古探险队，这位矮人十分担心她的安危。",h="塔雷尔·石纹在米奈希尔港的桥边，焦急地等待妻子麦琳的消息。妻子加入了一支前往内陆的考古探险队，这位矮人十分担心她的安危。",kw={"矮人","挖掘队","米奈希尔港","麦琳·石纹","塔雷尔·石纹","湿地"},ang={["faction:Alliance"]="对于抵达米奈希尔港的旅人而言，塔雷尔让他们得以近距离了解驻留在荒野沼泽沿线的联盟民众所面临的艰辛。",["race:Dwarf"]="Explorer’s League执着地探寻矮人的起源，足迹遍布卡兹莫丹的荒野边疆，而塔雷尔的忧虑正揭示了这份追求背后的凶险与代价。"},sec={{t="桥边的守望",b="塔雷尔·石纹守望着米奈希尔港的桥梁，商贸货物与军用物资从这里运过。他的妻子麦琳·石纹加入了勘察员维尔加那支声名显赫的考古探险队，深入湿地。凶暴的迅猛龙占据了挖掘场，日常通信也随之中断。塔雷尔困在镇上，恳求旅人向东前往维尔加挖掘场探查，查明麦琳是否还活着。"}},faq={{q="塔雷尔·石纹是谁？",a="塔雷尔是一名铁炉堡矮人，正在米奈希尔港入口的桥边焦急地等待。他盼望着妻子麦琳的消息，她此前前往内陆参加挖掘工作。",al={"塔雷尔·石纹","这个矮人是谁","米奈希尔港桥边的矮人"}},{q="塔雷尔为什么向旅人求助？",a="麦琳所在的考古队在挖掘场遭遇险情后，塔雷尔便与她失去了联系。他无法离开自己守候的地方，只能请求旅人向东前往维尔加挖掘场寻找她。",al={"塔雷尔任务","寻找挖掘队","塔雷尔·石纹任务"}},{q="麦琳·石纹是谁？",a="麦琳·石纹是塔雷尔的妻子，也是勘察员维尔加挖掘队中的一名考古学家。营地遭到袭击后，她幸存下来，与其他幸存者一同躲进了一处可以俯瞰挖掘场的洞穴。",al={"麦琳·石纹","塔雷尔的妻子","麦琳是谁"}},{q="塔雷尔的妻子去了哪里？",a="麦琳向东深入湿地，研究古老的泰坦与矮人遗物。主要挖掘场遭到袭击后，她与幸存的挖掘者躲进了一处洞穴，从那里可以俯瞰已成废墟的挖掘场。",al={"麦琳在哪里","挖掘队位置","维尔加避难所"}}},fp="17,172,21.432.0,25.144.0,40.198.0,25.217.1,27.203.1"}
P.entries["npc:tatternack-steelforge"] = {n="塔特纳克·钢炉",s="在贫瘠之地的边疆，塔特纳克·钢炉为那些能处理金属原料、应付危险野兽的旅人提供工作。这位兽人铁匠研究当地的矿石，力求为部落军队打造武器，以应对平原各处的威胁。",h="在贫瘠之地的边疆，塔特纳克·钢炉为那些能处理金属原料、应付危险野兽的旅人提供工作。这位兽人铁匠研究当地的矿石，力求为部落军队打造武器，以应对平原各处的威胁。",kw={"贫瘠之地","铁匠","陶拉祖营地","十字路口","矿石","钢炉","塔特纳克"},ang={["faction:Horde"]="塔特纳克帮助部落军队维持武器和物资供应，以应对野猪人和半人马等威胁。",["profession:Blacksmithing"]="对于途经贫瘠之地的铁匠来说，塔特纳克深知，在这片无法无天的边疆，优质矿石和上好钢材不可或缺。"},sec={{t="炉火旁的兽人",b="在贫瘠之地各处，部落哨站需要武器来对抗野兽、半人马劫掠者和敌对的野猪人。塔特纳克·钢炉将族人的冶金技艺带到了边疆。他寻求实用的武器和奇特的地质标本，以巩固部落的立足之地，抵御这些威胁。"}},faq={{q="塔特纳克·钢炉是谁？",a="塔特纳克·钢炉是一位驻扎在贫瘠之地的兽人武器匠。他检验矿物、研究当地矿石，并为附近的战士提供可靠的武器，协助部落守军获得补给。",al={"塔特纳克是谁","塔特纳克·钢炉背景故事","塔特纳克做什么"}},{q="在哪里可以找到塔特纳克·钢炉？",a="塔特纳克在贫瘠之地活动，住在中部草原道路沿线的部落营地中。",al={"塔特纳克在哪里","塔特纳克·钢炉位置","塔特纳克坐标"}},{q="塔特纳克提供什么样的任务？",a="塔特纳克请旅人找回武器，并从贫瘠之地各处带来新的矿石样本，供他锻造之用。",al={"塔特纳克任务","野猪人的武器任务给予者","矿石样本任务"}}},fp="21,208,19.306.0,29.204.0,41.87.0,41.122.0"}
P.entries["npc:tavernkeep-smitts"] = {n="旅店老板斯密茨",s="在夜色镇的血鸦旅店，旅店老板斯密茨听着镇上的闲谈，也听着那些悬而未决的惨案。他记性好，目光敏锐，任何想探寻这片地区黑暗往事的人，都能从他那里得到宝贵的线索。",h="在夜色镇的血鸦旅店，旅店老板斯密茨听着镇上的闲谈，也听着那些悬而未决的惨案。他记性好，目光敏锐，任何想探寻这片地区黑暗往事的人，都能从他那里得到宝贵的线索。",kw={"夜色镇","暮色森林","哈迦德","基特斯","血鸦旅店","斯密茨","斯塔文","旅店老板","僵尸酒"},ang={["class:Rogue"]="作为一名调查陈年悬案和神秘人物的潜行者，你可以指望斯密茨留意客人写了什么、何时惊慌失措，以及留下了什么。",["faction:Alliance"]="作为一名走出幽暗森林的联盟旅人，你可以在斯密茨那里找到庇护和酒水，也能打听到有关暮色森林中潜伏威胁的当地消息。"},sec={{t="夜色镇的中心",b="旅店老板斯密茨让血鸦旅店的炉火常年温暖，为疲惫的旅人、镇民，以及面对暮色森林险境而心神不宁的守夜人守卫供应酒水。多年来，他一直是夜色镇居民熟悉的面孔，每天都有传闻流经他的酒馆。当其他镇民躲在紧锁的百叶窗后时，斯密茨却留意着进出的每一个人。他会注意到古怪的客人、匆忙的离去，以及与镇上格格不入的举动。"},{t="斯塔文的往事",b="多年前，斯密茨曾与治安官哈迦德一同调查一个来访的暴风城贵族家庭惨遭杀害的案件。在现场，斯密茨发现了几张沾满泥污的日记残页，并将它们保存下来。当时，调查者无法正式确认这些笔迹出自斯塔文·密斯特曼托之手。斯密茨将这些褪色的残页保留了多年，坚信那可怕的真相终会大白。"},{t="神秘的客人",b="惶恐不安的隐士基特斯曾在血鸦旅店避难，斯密茨看见他在一本私人日记中疯狂地写着什么。基特斯惊慌失措地逃离酒馆，留下了那本日记。当一名调查者找回日记时，斯密茨认出了它，并指引追踪者前往乌鸦岭，帮助揭开笼罩这片森林的诅咒事件。"}},faq={{q="在哪里可以找到旅店老板斯密茨？",a="斯密茨就在夜色镇广场上血鸦旅店一楼的柜台后面。",al={"斯密茨位置","旅店老板斯密茨在哪","血鸦旅店酒保"}},{q="斯密茨知道哪些关于斯塔文·密斯特曼托的事？",a="多年前，斯密茨曾陪同治安官哈迦德调查来访贵族惨遭杀害的案件。他在现场发现了沾满泥污的日记残页，并将它们保存下来。看到将斯塔文与这起罪行联系起来的新证据后，斯密茨便交出残页，让人送给指挥官阿尔泰娅·埃伯洛克。",al={"斯密茨 斯塔文","斯塔文传说 斯密茨","泥污书页 斯塔文"}},{q="斯密茨知道哪些关于基特斯的事？",a="基特斯曾住在血鸦旅店，斯密茨看见他在一本日记里疯狂地书写，随后惊恐地逃走。将基特斯的日记带回酒馆，斯密茨就会认出它，并指引你向西前往乌鸦岭，追查基特斯的下落。",al={"斯密茨 基特斯","基特斯的日记 斯密茨","旅店里的线索 斯密茨"}},{q="斯密茨会酿制或求取哪些酒？",a="斯密茨帮忙筹集酿制当地酒饮的原料。他会派冒险者前往受诅咒的荒野，采集腐败之花，用来酿制一种当地称为僵尸酒的烈性酒饮。",al={"僵尸酒","斯密茨 腐败之花","斯密茨酿酒"}},{q="治安官哈迦德是谁，斯密茨又是怎么认识他的？",a="治安官哈迦德是一位年迈的暴风城卫队老兵，住在山间一座偏僻的小屋里。多年前，他与斯密茨一同调查贵族遇害的血腥案件，并因这桩悬案结下了交情。",al={"斯密茨 哈迦德","哈迦德的关联"}},{q="斯密茨在夜色镇有已知的家人吗？",a="夜色镇没有人知道斯密茨有任何家人。他独自经营血鸦旅店，那里也没有人知道他有任何亲属。",al={"斯密茨的亲属","玛丽 斯密茨"}}},fp="17,203,18.436.0,21.345.1,18.351.1,35.106.0,47.277.1,36.243.1,40.166.0,53.203.0,47.122.0"}
P.entries["npc:telf-joolam"] = {n="泰尔夫·祖拉姆",s="在眠炎圣殿，泰尔夫·祖拉姆指引部落的入门者接受火焰试炼。这位黑暗之矛萨满教导他们与狂暴易变的火元素沟通，并驾驭它的力量。",h="在眠炎圣殿，泰尔夫·祖拉姆指引部落的入门者接受火焰试炼。这位黑暗之矛萨满教导他们与狂暴易变的火元素沟通，并驾驭它的力量。",kw={"贫瘠之地","火焰的召唤","黑暗之矛","杜隆塔尔","火焰灵契","萨满","眠炎圣殿","泰尔夫·祖拉姆"},ang={["class:Shaman"]="身为萨满，你在泰尔夫·祖拉姆的指引下接受火焰灵契的试炼，学习掌握自己的火焰图腾。",["faction:Horde"]="身为部落的一员，你看到泰尔夫这样的长者守护着边境各处神圣的元素圣殿，巩固部落的精神根基。",["race:Troll"]="身为巨魔，你看到一位黑暗之矛长者指引入门者，学习部落各族共同遵循的萨满之道。"},sec={{t="火焰守护者",b="泰尔夫·祖拉姆照看着眠炎圣殿，圣殿坐落于俯瞰边境的峭壁之间。与大地的沉稳坚定、水的耐心深邃不同，火焰之灵要求严格的自律和毫不动摇的专注。泰尔夫帮助年轻的萨满为试炼做好准备，让他们在狂野的余烬将自己吞噬之前，证明自身的价值。"},{t="火焰之路",b="在泰尔夫的指引下，入门者调制并饮下仪式所用的火焰灵契，让凡人的双眼得以窥见无形的元素位面。他派他们登上岩石嶙峋的山巅，面对燃烧的灵体。赢得火焰认可的人必须敬畏它永不满足的饥渴，并抵制鲁莽的傲慢。"}},faq={{q="泰尔夫·祖拉姆是谁？",a="泰尔夫·祖拉姆是一位黑暗之矛巨魔萨满，负责照看眠炎圣殿。他指导那些寻求与火焰沟通的年轻萨满。",al={"泰尔夫·祖拉姆","泰尔夫是谁","眠炎圣殿巨魔"}},{q="在哪里可以找到泰尔夫·祖拉姆？",a="泰尔夫·祖拉姆位于眠炎圣殿，那里坐落在杜隆塔尔与贫瘠之地之间高耸的岩脊上。",al={"泰尔夫·祖拉姆位置","泰尔夫在哪里","如何找到泰尔夫·祖拉姆"}},{q="他要求的火焰灵契有什么用途？",a="火焰灵契能开启入门者的灵视，让他们感知凡人感官无法察觉的火元素之灵，并与之交谈。",al={"火焰灵契是什么","火焰灵契用途","为什么要喝灵契"}},{q="泰尔夫·祖拉姆传授哪种元素的知识？",a="泰尔夫·祖拉姆传授火元素的知识，考验萨满的力量与意志，让他们驾驭火焰而不被其毁灭本性吞噬。",al={"泰尔夫传授哪种元素","泰尔夫·祖拉姆元素","火焰图腾任务人物"}},{q="为什么由一位巨魔在这里主持萨满仪式？",a="自从加入萨尔的部落，许多黑暗之矛巨魔便与兽人和牛头人一同踏上了萨满之道。像泰尔夫这样经验丰富的萨满负责指引下一代。",al={"为什么是巨魔萨满","黑暗之矛萨满之道"}},{q="完成泰尔夫·祖拉姆的任务后会怎样？",a="在附近的山峰上证明自己能够驾驭火焰之灵后，入门者便会获得铸造永久火焰图腾所需的知识与祝福。",al={"火焰的召唤奖励","泰尔夫给予什么"}}},fp="11,176,19.287.0,16.272.0,19.131.0,31.117.0,50.134.0,36.132.0,46.162.0,50.143.0"}
P.entries["npc:tenaron-stormgrip"] = {n="特纳隆·雷拳",s="在奥达希尔高处，特纳隆·雷拳向年轻的暗夜精灵讲述族人近来的历史。他还让他们去采集月亮井水。",h="在奥达希尔高处，特纳隆·雷拳向年轻的暗夜精灵讲述族人近来的历史。他还让他们去采集月亮井水。",kw={"奥达希尔","塞纳里奥议会","大地之冠","月亮井","幽影谷","雷拳","泰达希尔","特纳隆"},ang={["class:Druid"]="身为德鲁伊，你可以从特纳隆的任务中看出，照看迅速生长的泰达希尔、防范隐蔽的腐化，需要细心呵护。",["race:NightElf"]="对年轻的暗夜精灵来说，特纳隆·雷拳让他们初步了解，为维系泰达希尔的生机与纯净，族人需要承担怎样的共同责任与精神职责。"},sec={{t="奥达希尔的守望者",b="特纳隆·雷拳在奥达希尔蜿蜒的木制平台上指引年轻的暗夜精灵。他从幽影谷中央这棵大树的高处，守望着周围的树林和其中的月亮井。他教导初学者，讲述他们与世界之树之间的精神纽带。"},{t="大地的冠冕",b="特纳隆派初学者前往奥达希尔北面的月亮井，采集一小瓶井水。途中，他向他们讲述海加尔山之战后发生的事情。他们的旅程将继续穿过泰达希尔，进入达纳苏斯。"}},faq={{q="特纳隆·雷拳在哪里？",a="特纳隆·雷拳站在奥达希尔高处的木制平台上，这棵大树位于泰达希尔的幽影谷中央。",al={"特纳隆位置","特纳隆在哪","特纳隆·雷拳位置"}},{q="特纳隆·雷拳在幽影谷担任什么职责？",a="特纳隆·雷拳在幽影谷指引年轻的暗夜精灵，向他们讲述海加尔山之战后的情况。",al={"特纳隆做什么","特纳隆·雷拳的职责","特纳隆是谁"}},{q="大地之冠是什么任务？",a="特纳隆让初学者用小瓶采集月亮井水。这段旅程让他们了解暗夜精灵近来的历史，并带领他们继续走遍泰达希尔。",al={"大地之冠背景故事","为何携带月亮井水"}},{q="特纳隆为什么关心泰达希尔的水源？",a="特纳隆关注泰达希尔的水源，因为这里的月亮井承载着艾露恩的恩泽与自然的纯净。泰达希尔尚且年轻，也未获得守护巨龙的完整祝福，因此看护者们监测着这里的水源，留意是否出现腐化或污染。",al={"为何井水珍贵","泰达希尔水源问题"}},{q="特纳隆会派冒险者前往幽影谷以外的地方吗？",a="会。特纳隆派初学者离开幽影谷，前往多兰纳尔，在那里继续为卡多雷效力。",al={"特纳隆后续任务","特纳隆派往何处"}},{q="特纳隆是德鲁伊还是牧师？",a="特纳隆的职业尚无定论。他讲授暗夜精灵近来的历史，并解释月亮井的意义。",al={"特纳隆·雷拳职业","特纳隆是德鲁伊吗"}}},fp="17,151,20.233.0,18.224.0,35.108.0,47.123.0,37.142.0,51.223.0,48.105.0,31.115.0"}
P.entries["npc:terenthis"] = {n="特伦希斯",s="特伦希斯在奥伯丁监视着黑海岸不断蔓延的腐化。塞纳里奥议会派遣这位暗夜精灵德鲁伊调查腐化从泰达希尔扩散的范围，并向旅人和当地盟友寻求帮助。",h="特伦希斯在奥伯丁监视着黑海岸不断蔓延的腐化。塞纳里奥议会派遣这位暗夜精灵德鲁伊调查腐化从泰达希尔扩散的范围，并向旅人和当地盟友寻求帮助。",kw={"奥伯丁","塞纳里奥议会","黑海岸","魔苔","熊怪","格瑞姆","特伦希斯","沃科尔"},ang={["class:Druid"]="身为塞纳里奥议会的德鲁伊，你与特伦希斯并肩对抗从泰达希尔蔓延至大陆的腐化。",["race:NightElf"]="身为暗夜精灵，你与特伦希斯有着同样的忧虑，希望净化神圣土地上的邪能污染，保护无辜的森林生灵。"},sec={{t="调查腐化",b="特伦希斯正在调查黑海岸的魔苔及其他腐化现象。塞纳里奥议会派他前往奥伯丁，追查从泰达希尔蔓延而来的腐化。暗夜精灵担心，这可能会打破卡利姆多北部的平衡。特伦希斯正在寻找腐化的根源，以及在它吞噬森林之前将其阻止的方法。"},{t="暗爪的求助",b="暗爪独自负伤来到奥伯丁，向特伦希斯求助。这位德鲁伊意识到，这头熊的主人沃科尔遇到了大麻烦。特伦希斯无法离开岗位，便派旅人深入荒野寻找沃科尔，他遭到凶暴的熊怪部族伏击，如今被困在那里。"}},faq={{q="特伦希斯是谁？",a="特伦希斯是塞纳里奥议会的一名暗夜精灵德鲁伊，驻守在黑海岸的奥伯丁。",al={"特伦希斯背景故事","特伦希斯是谁","特伦希斯 奥伯丁"}},{q="特伦希斯为什么在奥伯丁？",a="塞纳里奥议会派特伦希斯前往奥伯丁，调查从泰达希尔蔓延至黑海岸的魔苔与魔法腐化，并寻找阻止它们的方法。",al={"特伦希斯在做什么","特伦希斯的目的","特伦希斯为什么在这里"}},{q="特伦希斯身旁的熊为什么在那里？",a="恐爪的主人、德鲁伊沃科尔遭到凶暴的熊怪伏击并被困住后，恐爪独自负伤来到奥伯丁，向特伦希斯求助。",al={"特伦希斯的熊","暗爪","奥伯丁为什么有一头熊"}},{q="特伦希斯属于什么组织？",a="特伦希斯属于塞纳里奥议会，这是一个致力于在卡利姆多各地维持平衡、保护自然的德鲁伊组织。",al={"特伦希斯的阵营","特伦希斯属于塞纳里奥议会吗"}},{q="特伦希斯最担忧哪些威胁？",a="特伦希斯担心魔苔腐化不断蔓延，以及熊怪部族日益加剧的敌意，这些都威胁着旅人和德鲁伊。",al={"黑海岸腐化","魔苔威胁","特伦希斯的忧虑"}},{q="特伦希斯会向冒险者提供任务吗？",a="会。特伦希斯派旅人评估沿岸的威胁，援助当地盟友，并帮助沃科尔。",al={"特伦希斯的任务","特伦希斯想要什么"}}},fp="9,207,23.304.0,20.296.1,17.92.0,30.163.0,46.141.0,43.124.0,46.117.0,46.99.0"}
P.entries["npc:teronis-corpse"] = {n="泰洛尼斯的尸体",s="泰洛尼斯的尸体躺在灰谷西部法拉希姆湖的一座小岛上。这位暗夜精灵斥候离开阿斯特兰纳，去寻找达图尔的变形魔棒，帮助净化森林。",h="泰洛尼斯的尸体躺在灰谷西部法拉希姆湖的一座小岛上。这位暗夜精灵斥候离开阿斯特兰纳，去寻找达图尔的变形魔棒，帮助净化森林。",kw={"灰谷","阿斯特兰纳","达图尔的魔棒","法拉希姆湖","鱼人","莱恩·狼行者","泰洛尼斯","泰洛尼斯的尸体"},ang={["faction:Alliance"]="纪念阿斯特兰纳牺牲的斥候，就意味着接续他们未竟的事业，清除这片土地上的腐化。",["race:NightElf"]="发现泰洛尼斯倒在荒野中，足以看出灰谷如今有多么危险，即使经验丰富的Sentinels和斥候也难以幸免。"},sec={{t="斥候的悲惨命运",b="泰洛尼斯受命从阿斯特兰纳出发，寻回达图尔的变形魔棒。莱恩·狼行者将这项任务交给了这位暗夜精灵斥候，希望找到一件能净化林地中受污染魔法的古老圣物。泰洛尼斯搜寻了法拉希姆湖的水域，但敌对的鱼人蜂拥上岛，杀死了他。他的日记仍留在那里，而鱼人夺走了法杖上光芒四射的宝石。"}},faq={{q="泰洛尼斯是谁？",a="泰洛尼斯是一位暗夜精灵斥候，由哨兵莱恩·狼行者从阿斯特兰纳派出。他要寻找达图尔的魔棒，这件古老的神器原本用于净化灰谷土壤和水域中的恶魔腐化。",al={"泰洛尼斯是谁","泰洛尼斯的故事","泰洛尼斯的身份"}},{q="泰洛尼斯是怎么死的？",a="泰洛尼斯试图在法拉希姆湖取得法杖的部件时，遭到凶恶的鱼人伏击并杀害。",al={"谁杀了泰洛尼斯","泰洛尼斯的死因","他是怎么死的"}},{q="他遗失的宝石在哪里？",a="泰洛尼斯遇害后，法拉希姆湖周围的鱼人捡走了镶在达图尔的变形魔棒顶端的发光宝石。",al={"宝石在哪里","遗失的宝石","泰洛尼斯的宝石"}},{q="为什么接续他的任务对阿斯特兰纳如此重要？",a="灰谷的野生动物和林间水池正遭受恶魔与邪能的污染。哨兵希望达图尔的变形魔棒能净化这片土地，或遏制腐化的蔓延。",al={"为什么帮助莱恩","达图尔 魔棒的用途"}}},fp="15,157,19.317.0,16.187.0,20.107.0,27.106.0,56.159.0"}
P.entries["npc:thadius-grimshade"] = {n="萨迪斯·格希德",s="萨迪斯·格希德是一位蛮锤矮人占卜师，住在诅咒之地守望堡的法师塔内。虽然他很久以前就离开了鹰巢山，钻研晦涩而黑暗的魔法，但他心中依然忠于自己的同胞。",h="萨迪斯·格希德是一位蛮锤矮人占卜师，住在诅咒之地守望堡的法师塔内。虽然他很久以前就离开了鹰巢山，钻研晦涩而黑暗的魔法，但他心中依然忠于自己的同胞。",kw={"诅咒之地","占卜师","耐克鲁姆","守望堡","沙普比克","萨迪斯·格希德","蛮锤"},ang={["class:Mage"]="造访守望堡的法师会发现，萨迪斯擅长罕见而深奥的占卜术，并愿意研究巨魔遗物，以掌握长寿魔法。",["race:Dwarf"]="矮人同胞会觉得萨迪斯是蛮锤中的异类；他常年埋首于人类要塞中的奥术研究，而非骑着狮鹫翱翔。"},sec={{t="荒原中的蛮锤矮人",b="大多数蛮锤矮人都喜爱辛特兰开阔的天空和呼啸的狂风，萨迪斯·格希德却将家安在了守望堡内。出于对奥术占卜和黑暗秘法知识的渴求，他迁居到遭受污染的诅咒之地边缘，潜心钻研深奥的学问。尽管他终日埋首于阴郁的研究，远离自己的氏族，却仍深深眷恋着故土与狮鹫，并愿意为那些代表鹰巢山前来求助的人施展罕见的占卜之术。"},{t="占卜的代价",b="当狮鹫管理员沙拉克·鹰斧试图寻找被俘的狮鹫沙普比克时，萨迪斯受邀用这只狮鹫的一根羽毛举行占卜仪式。他的魔法洞察并非毫无代价：萨迪斯索要巨魔死灵法师耐克鲁姆佩戴的徽章。他想揭开其中违背自然的长寿奥秘，同时避开它有害的腐蚀，因此收下了这件神器，作为看穿辛萨罗的迷雾、揭示沙普比克囚禁之处的报酬。"}},faq={{q="萨迪斯·格希德是谁？",a="他是一位性情古怪的蛮锤矮人法师兼占卜师，驻留在守望堡。他离开了山中的家园，前往遥远的南方，钻研更为黑暗、偏离正统的魔法。",al={"萨迪斯·格希德","萨迪斯是谁","萨迪斯在哪里"}},{q="在哪里能找到萨迪斯·格希德？",a="他住在守望堡高耸的法师塔内，这座联盟要塞位于诅咒之地北部。",al={"萨迪斯位置","萨迪斯·格希德在哪里","萨迪斯 诅咒之地"}},{q="他为什么想要耐克鲁姆的徽章？",a="萨迪斯想研究耐克鲁姆携带的徽章，弄清它的魔力如何赋予长寿，希望获得这份长寿之力，同时免受其险恶副作用的侵害。",al={"耐克鲁姆的徽章 萨迪斯","萨迪斯为何想要徽章","耐克鲁姆的徽章"}},{q="他如何帮助寻找沙普比克？",a="萨迪斯利用失踪狮鹫掉落的一根羽毛，以及耐克鲁姆的徽章提供的力量，举行占卜仪式，揭示了沙普比克被囚禁在辛特兰的辛萨罗高处。",al={"萨迪斯 尖喙","占卜沙普比克","寻找沙普比克任务"}}},fp="17,149,26.380.0,23.406.1,25.155.0,37.127.0,36.164.0,32.173.1"}
P.entries["npc:thalia-amberhide"] = {n="萨利亚",s="萨利亚是一名牛头人，居住在千针石林崎岖峡谷中的乱风岗。她忠于同胞，正等待拉克塔·风歌平安归来，摆脱恐怖图腾氏族的魔爪，心中的担忧与日俱增。",h="萨利亚是一名牛头人，居住在千针石林崎岖峡谷中的乱风岗。她忠于同胞，正等待拉克塔·风歌平安归来，摆脱恐怖图腾氏族的魔爪，心中的担忧与日俱增。",kw={"阿纳克·恐怖图腾","乱风岗","恐怖图腾","拉克塔·风歌","萨利亚","千针石林"},ang={["faction:Horde"]="乱风岗是部落在千针石林的重要中转站，帮助萨利亚也能保护这座聚落免遭恐怖图腾的侵袭。",["race:Tauren"]="对牛头人旅者而言，协助萨利亚、营救拉克塔，就是直接打击恐怖图腾部族阴险的背叛行径，保护同胞免受氏族纷争的伤害。"},sec={{t="岗哨中的朋友",b="在乱风岗高耸的崖顶上，萨利亚静静地生活在这座繁忙的牛头人聚落中。她的挚友拉克塔·风歌被阿纳克·恐怖图腾和他那些背信弃义的族人俘虏，这让她忧心忡忡。萨利亚寄望于路过的部落冒险者，希望他们勇闯峡谷深处，找到拉克塔，为她解开束缚，再护送她乘升降梯返回台地上的避风港。"}},faq={{q="萨利亚是谁？",a="萨利亚是一名牛头人，住在千针石林的乱风岗。她是拉克塔·风歌的忠实朋友，后者也是一名牛头人，却落入了背信弃义的恐怖图腾氏族手中。",al={"萨利亚","萨利亚是谁"}},{q="在哪里可以找到萨利亚？",a="她就在千针石林中部乱风岗的高耸台地上。旅人必须从谷底乘坐巨大的木制升降梯，才能抵达这座聚落。",al={"萨利亚位置","萨利亚在哪里"}},{q="萨利亚与拉克塔·风歌有什么关系？",a="萨利亚是拉克塔·风歌的挚友。拉克塔被阿纳克·恐怖图腾俘虏后，若有冒险者成功帮助她逃脱，萨利亚便会在乱风岗接应。",al={"萨利亚与拉克塔","拉克塔·风歌是谁"}}},fx={["29deb6ad"]={q="萨利亚支持哪一方？",a="萨利亚忠于部落和她的牛头人族人。她住在千针石林的乱风岗，欢迎途经风蚀高原的部落冒险者，并坚定地抵御威胁当地部族的敌对势力。",al={"萨利亚的阵营","萨利亚是部落的吗","萨利亚属于部落还是联盟"}},["80c269cc"]={q="萨利亚为什么会在这里？",a="萨利亚住在乱风岗顶上，是这座牛头人高原聚居地的一名安居者。她与族人平静地生活，但峡谷下方的威胁正困扰着她那些朋友，让她忧心忡忡。",al={"萨利亚为什么在乱风岗","萨利亚在哪里，为什么","是什么让萨利亚来到千针石林"}},["211f0475"]={q="萨利亚想要什么？",a="萨利亚非常关心亲密伙伴拉克塔·风歌的安危。她最挂心的是保护自己珍视的人，不让他们遭受蛮锤等敌对部族的侵袭。",al={"萨利亚想要什么","萨利亚的动机","萨利亚的目标"}}},fp="16,142,20.262.0,24.146.0,36.158.0,47.172.0"}
P.entries["npc:tharek-blackstone"] = {n="萨雷克·黑石",s="萨雷克·黑石在卡拉诺斯的熔炉旁，为当地工匠制作和修理工具。他平日里生意繁忙，因此会雇用旅人，将装好成品的货箱送到钢架补给站，交给贝尔丁·钢架。",h="萨雷克·黑石在卡拉诺斯的熔炉旁，为当地工匠制作和修理工具。他平日里生意繁忙，因此会雇用旅人，将装好成品的货箱送到钢架补给站，交给贝尔丁·钢架。",kw={"贝尔丁","黑石","丹莫罗","卡拉诺斯","钢架","萨雷克","工具匠"},ang={["profession:Blacksmithing"]="对于途经卡拉诺斯的铁匠来说，萨雷克展现了工具匠的日常工作，为矮人机械制作结实的扳手和铁制配件。",["race:Dwarf"]="身为矮人，你也有着丹莫罗的实干精神。当地的工业依靠那些在铁砧旁辛勤劳作的人。"},sec={{t="卡拉诺斯忙碌的工具匠",b="贝尔丁在镇外经营的机械陆行鸟补给站需要重型扳手、齿轮和替换工具。萨雷克把每箱货物托付给过路的旅人运往那里，这样他就能留在熔炉旁，同时让货物照常送达。卡拉诺斯各处的工匠也都依靠他制作和修理的工具。"},{t="镇上有声望的人物",b="萨雷克凭借在铁砧旁的辛勤劳作，赢得了丹莫罗各地人们的尊重。他没有军衔，但镇上的人会找他安排零活、运送补给，或帮忙协调当地事务。"}},faq={{q="萨雷克·黑石是谁？",a="萨雷克·黑石是丹莫罗卡拉诺斯的一名矮人工具匠。他为当地工人制作和修理重型工具，也会雇用过路的旅人在山谷各处运送补给。",al={"萨雷克·黑石","萨雷克是谁","黑石 丹莫罗"}},{q="他与贝尔丁·钢架是什么关系？",a="贝尔丁·钢架在卡拉诺斯东边不远处经营钢架补给站，那里负责修理机械陆行鸟和攻城器械。他是萨雷克的主要客户，订购的铁器数量很大，因此萨雷克经常雇用旅人，将完工的货物送到补给站。",al={"萨雷克与贝尔丁","钢架 工具","为什么是贝尔丁"}},{q="在哪里能找到萨雷克·黑石？",a="萨雷克·黑石站在丹莫罗卡拉诺斯镇中心附近的户外，从那里步行片刻就能到达镇上的旅店和熔炉。",al={"萨雷克位置","萨雷克·黑石在哪里","萨雷克·黑石位置"}},{q="萨雷克在铁炉堡有正式职衔吗？",a="萨雷克既没有军职，也没有担任任何官职。他是一名忙碌的工具匠，会雇用需要赚些钱的新人替他搬运补给。",al={"萨雷克是领袖吗","萨雷克的职权","黑石的军衔"}}},fx={cb940f84={q="萨雷克·黑石效忠哪一方？",a="萨雷克是一名忠于铁炉堡的矮人，坚定地站在联盟一边。他在卡拉诺斯靠勤恳劳作为乡邻效力，为当地工匠提供装备，每当丹莫罗各地出现麻烦，也会向旅人和邻居伸出援手。",al={"萨雷克·黑石的阵营","萨雷克·黑石为谁效力","萨雷克 联盟"}},eaa270fb={q="萨雷克·黑石想要什么？",a="萨雷克主要想赶上手头源源不断的活计。身为勤劳的工具匠，他总是被订单压得喘不过气，尤其是贝尔丁·钢架这类要求苛刻的客户送来的订单。他希望找到可靠的旅人，帮忙送货和做些零活，让自己的铁匠铺能顺利运转。",al={"萨雷克想要什么","萨雷克·黑石的动机","萨雷克为什么需要帮助"}},fa8e7e80={q="萨雷克·黑石为什么在卡拉诺斯？",a="卡拉诺斯是丹莫罗旅人和手艺人的主要集散地，自然适合萨雷克在此开店。他可以从这里向钢架补给站等附近的据点供应必需的装备。",al={"萨雷克为什么在卡拉诺斯","萨雷克·黑石 卡拉诺斯"}}},fp="17,205,28.280.0,18.197.0,25.184.0,48.253.0,35.132.0,48.142.0"}
P.entries["npc:tharnariun-treetender"] = {n="萨纳瑞恩·绿树",s="萨纳瑞恩·绿树是一位暗夜精灵博物学家，驻扎在黑海岸的沿海定居点奥伯丁。他致力于守护自然界的微妙平衡，监视着侵蚀当地动植物的腐化现象。途经此港口的旅行者经常发现他呼吁盟友医治患病的野兽，保护自然免受进一步的衰败。",h="萨纳瑞恩·绿树是一位暗夜精灵博物学家，驻扎在黑海岸的沿海定居点奥伯丁。他致力于守护自然界的微妙平衡，监视着侵蚀当地动植物的腐化现象。途经此港口的旅行者经常发现他呼吁盟友医治患病的野兽，保护自然免受进一步的衰败。",kw={"奥伯丁","净化","腐化","黑海岸","受感染","卡多雷","瘟疫之地","萨纳瑞恩","绿树"},ang={["class:Druid"]="德鲁伊会发现萨纳瑞恩对枯萎野生动物的关心与他们恢复腐化土地和谐的神圣使命紧密相连。",["faction:Alliance"]="奥伯丁是联盟在卡利姆多北部的核心沿海门户，这使得萨纳瑞恩对周围森林的防御对该前哨的安全至关重要。",["race:NightElf"]="对于卡多雷来说，萨纳瑞恩的警告与他们守护卡利姆多北部自然平衡的古老职责产生了深刻的共鸣。"},sec={{t="奥伯丁的守护者",b="坐落在黑海岸崎岖的海岸线上，奥伯丁港面临着多方面的威胁，从敌对的萨特到邪恶的海岸冲刷怪。萨纳瑞恩·绿树将精力完全集中在村庄周围的自然世界。他坚信忽视自然只会招致毁灭，因此花费时间观察当地树林的衰败，并寻求方法抵御在森林地面蔓延的疾病。"},{t="医治受难者",b="黑海岸的大部分野生动物都成为了奇怪瘟疫和腐化枯萎病的牺牲品，这使得生物变得疯狂，并将和平的动物变成了狂暴的威胁。萨纳瑞恩并非仅仅出于恐惧而屠杀它们，而是寻求一种补救措施。通过精心调制的净化剂和有针对性地消除最严重的传染源，他努力在林地彻底衰败之前拯救残存的荒野。"}},faq={{q="萨纳瑞恩·绿树是谁？",a="萨纳瑞恩是一位暗夜精灵看护者，驻扎在黑海岸沿岸的奥伯丁。他毕生致力于守护森林，并诊断困扰当地野生动物的非自然疾病。",al={"谁是萨纳瑞恩","萨纳瑞恩背景故事","萨纳瑞恩绿树"}},{q="我在哪里可以找到萨纳瑞恩·绿树？",a="他位于黑海岸荒野西缘的暗夜精灵沿海村庄奥伯丁。",al={"萨纳瑞恩在哪里","萨纳瑞恩绿树位置","萨纳瑞恩地图"}},{q="萨纳瑞恩正在黑海岸调查什么问题？",a="他调查感染了土地及其野生动物的腐化蔓延和邪恶瘟疫，并派遣冒险者去净化受感染的野兽以阻止枯萎病。",al={"萨纳瑞恩想要什么","萨纳瑞恩目的","为什么帮助萨纳瑞恩"}},{q="为什么萨纳瑞恩如此关心患病的动物？",a="作为荒野的守护者，萨纳瑞恩认为暗夜精灵如果忽视自然，必将自食其果。他致力于净化病患生物，而不是任由森林腐化。",al={"为什么拯救野兽","萨纳瑞恩野兽任务"}},{q="萨纳瑞恩·绿树提供什么任务？",a="他指导冒险者完成涉及荒芜之地和野生动物的任务，特别是“Plagued Lands”、“Cleansing of the Infected”和“Tharnariun's Hope”。",al={"萨纳瑞恩任务","萨纳瑞恩绿树职责"}},{q="萨纳瑞恩是德鲁伊吗？",a="资料从未明确称呼他为德鲁伊。虽然他在保护野兽和植物方面拥有与塞纳里奥议会相同的博物学家信念，但他主要担任黑海岸荒野的专注看护者和树木管理员。",al={"萨纳瑞恩是德鲁伊吗","萨纳瑞恩职业"}}},fp="21,196,23.335.0,21.293.1,29.157.0,39.90.0,55.170.0,56.159.0,45.147.0,22.168.0"}
P.entries["npc:the-defias-traitor"] = {n="迪菲亚叛徒",s="在哨兵岭，迪菲亚叛徒为了保命，供出了迪菲亚潜行者的秘密基地。人民军在他偷窃农夫萨丁的货车时将他抓获，如今把他关押在哨塔下。",h="在哨兵岭，迪菲亚叛徒为了保命，供出了迪菲亚潜行者的秘密基地。人民军在他偷窃农夫萨丁的货车时将他抓获，如今把他关押在哨塔下。",kw={"迪菲亚藏身处","迪菲亚叛徒","农夫萨丁","月溪镇","人民军","哨兵岭","西部荒野"},ang={["class:Rogue"]="身为盗贼，你知道罪犯之间的忠诚有多么脆弱。被执法者逼入绝境时，小偷和扒手可能会出卖自己人。",["faction:Alliance"]="对人民军和西部荒野的守卫者而言，这名囚犯的出现，让他们对抗肆虐当地的匪徒的斗争迎来了转折。"},sec={{t="引路前往月溪镇",b="叛徒在哨兵岭的哨塔下受到看守，他必须带领联盟勇士穿过危机四伏的地带，找到月溪镇废墟下的隐秘入口。他昔日的同伴憎恨他，俘获他的人也鄙视他。然而，他的背叛让人民军有机会直捣迪菲亚潜行者的腹地。"},{t="求生的交易",b="迪菲亚潜行者并非每个成员都效忠于艾德温·范克里夫。这个小偷企图偷走农夫萨丁的货车时，被格里安·斯托曼的民兵抓获。面对死刑，他选择了自保。他供出了秘密基地的确切位置，以换取活命的机会。"}},faq={{q="迪菲亚叛徒是谁？",a="迪菲亚叛徒曾是迪菲亚潜行者的一员。他企图偷走农夫萨丁的货车时，被人民军抓获。为了免于处决，他答应带领人民军的盟友前往秘密巢穴。",al={"这人是谁","迪菲亚叛徒身份","哨兵岭的叛徒是谁"}},{q="他为什么站在哨兵岭的哨塔外？",a="格里安·斯托曼和人民军将他扣押在据点外，由武装卫兵看守。他会一直待在那里，直到有志愿者护送他前往迪菲亚藏身处。",al={"叛徒位置","他为什么在哨兵岭","叛徒在哪里"}},{q="他会带你去哪里？",a="他带领旅人向西南穿过西部荒野的平原，前往荒废的月溪镇。在那里，他会指出通往迪菲亚藏身处的隐秘入口。",al={"叛徒去哪里","护送叛徒的目的地","迪菲亚 藏身处在哪里"}},{q="他为什么背叛迪菲亚潜行者？",a="他背叛迪菲亚潜行者是为了自保。他偷窃农夫萨丁的财物时被抓，面临处决，于是献出了迪菲亚潜行者最大的秘密，以换取自己的性命。",al={"为什么背叛迪菲亚","叛徒的动机","他为什么倒戈"}}},fx={ad165ef1={q="迪菲亚叛徒效忠哪一方？",a="他主要只为自己打算。他原本是迪菲亚潜行者中的一名盗贼，被人民军俘虏后，便背弃了艾德温·范克里夫。如今，他在看守下配合行动，帮助你和哨兵岭的官员，纯粹是为了逃过绞刑。",al={"迪菲亚叛徒的立场","叛徒为谁效力","迪菲亚叛徒是否属于联盟"}},["9c073637"]={q="迪菲亚叛徒想要什么？",a="他只想活下去。他企图偷走农夫萨丁的货车时被当场抓获，随后孤注一掷，与格里安·斯托曼和人民军达成交易：由他带你直奔兄弟会的秘密藏身处，换取活命、免遭处决的机会。",al={"叛徒想要什么","迪菲亚叛徒的目标","为什么帮助迪菲亚叛徒"}},a1cd0f31={q="迪菲亚叛徒与谁有关联？",a="他过去效忠于艾德温·范克里夫和迪菲亚潜行者，对他们在西部荒野各地的行动了如指掌。目前，他被格里安·斯托曼和哨兵岭的人民军扣押，他们依靠他掌握的第一手情报，准备打击这伙盗贼的总部。",al={"迪菲亚叛徒的人际关系","叛徒认识谁","迪菲亚叛徒的关联人物"}}},fp="18,204,28.306.1,22.287.1,26.201.0,54.163.0,23.155.1,47.165.0"}
P.entries["npc:theldurin-the-lost"] = {n="迷失者塞尔杜林",s="迷失者塞尔杜林是个离群索居、半疯半癫的矮人，游荡在荒芜之地焦灼的旷野上。他曾投身阴险的暮光之锤邪教，察觉他们的可怕图谋后，便带着偷来的神圣遗物逃离了教团。",h="迷失者塞尔杜林是个离群索居、半疯半癫的矮人，游荡在荒芜之地焦灼的旷野上。他曾投身阴险的暮光之锤邪教，察觉他们的可怕图谋后，便带着偷来的神圣遗物逃离了教团。",kw={"荒芜之地","爆破火药","密斯莱尔","瑞恩","密斯莱尔卷轴","塞尔杜林","迷失者塞尔杜林","暮光之锤"},ang={["profession:Engineering"]="塞尔杜林会用一包塞满爆破火药的炸药威胁靠近的陌生人，对不稳定的爆炸物表现出难以预测的依赖。",["race:Dwarf"]="眼看一位同为铁炉堡之子的矮人沦落荒野，疑惧成狂，实在令人悲叹，但他拒绝向黑暗邪教屈服，也显露出矮人骨子里那份不屈的倔强。"},sec={{t="被黑暗撕裂的心智",b="塞尔杜林栖身于荒芜之地的贫瘠山丘，终日疑惧不安，紧攥着一袋袋炸药，远非寻常的疯癫隐士。他曾是暮光之锤邪教的一名新晋教徒。当这个阴险的秘密教团试图唤醒困于地下的原始元素之力时，塞尔杜林惊恐万分，摒弃了他们疯狂的教义，逃进了沙漠。他随身带走了密斯莱尔卷轴，拼命阻止昔日的主人将远古的恐怖存在释放到世间。逃亡虽让他丧失了理智，他的反抗却也重创了邪教的计划。"},{t="绝境中的对策",b="在荒野中求生，滋味苦不堪言。暴怒的土元素伏击了塞尔杜林，将他偷来的卷轴撕得粉碎，碎片散落在尘土之中。如今，这个疯癫的矮人疑惧缠身，眼前不断浮现沉睡于地表之下、即将带来毁灭的存在，于是四处寻觅雷乌纳石板和雅格因的笔记这两部古籍，希望找到埋藏已久的知识。塞尔杜林不愿让邪教在元素公主密斯莱尔怒火最盛之时将她释放，便谋划强行提前召唤她，以便将她击败，再度束缚起来。"}},faq={{q="迷失者塞尔杜林是谁？",a="塞尔杜林是个藏身于荒芜之地的疯癫矮人隐士。他曾是暮光之锤邪教的一员，偷走了他们的仪式秘密，逃入荒野，试图阻止他们释放一股危险的力量。",al={"塞尔杜林 是谁","塞尔杜林 的故事","荒芜之地的疯矮人"}},{q="塞尔杜林为什么藏在荒芜之地？",a="他正在躲避暮光之锤的追捕。从邪教手中偷走密斯莱尔卷轴后，他躲进荒芜之地偏远而烈日炙烤的峡谷，躲避追杀他的邪教徒。",al={"塞尔杜林 为什么在这里","塞尔杜林 为什么躲藏","塞尔杜林 荒芜之地"}},{q="密斯莱尔卷轴是什么？",a="这是一张蕴含奥术力量的羊皮纸，记载着释放密斯莱尔所需的仪式知识。密斯莱尔是一个遭到腐化的远古元素实体，被困在阿拉希的地底深处。塞尔杜林偷走了它，让暮光之锤无法完成召唤，不过当地的元素生物后来将这份文书撕成了碎片。",al={"密斯莱尔卷轴","塞尔杜林 偷了什么卷轴"}},{q="塞尔杜林想对密斯莱尔做什么？",a="塞尔杜林知道束缚这个生物的力量正在减弱，因此想在密斯莱尔恢复全部力量之前，提前将她召唤出来。趁她虚弱时强行将她召出，冒险者就能赶在暮光之锤掌控她的力量之前，将她放逐，重新封印在地壳之下。",al={"塞尔杜林 的计划","为什么召唤 密斯莱尔","召唤公主"}}},fp="18,153,28.516.0,26.414.1,26.214.0,40.174.0,30.300.1,44.230.1"}
P.entries["npc:theocritus"] = {n="塞欧克瑞图斯",s="在艾尔文森林东部的阿祖拉之塔，塞欧克瑞图斯守望着暴风城王国，与莫甘斯抗衡。这位性情古怪的人类大法师独居于此，远离日常琐事，身边有仆从和魔法占卜装置。",h="在艾尔文森林东部的阿祖拉之塔，塞欧克瑞图斯守望着暴风城王国，与莫甘斯抗衡。这位性情古怪的人类大法师独居于此，远离日常琐事，身边有仆从和魔法占卜装置。",kw={"大法师","艾尔文森林","阿祖拉之眼","莫甘斯","莫雷·艾伯雷恩","暗皮","塞欧克瑞图斯","阿祖拉之塔"},ang={["class:Mage"]="塞欧克瑞图斯展现了巫师如何不隶属于任何组织，独立行事。他拥有一处私人圣所，并用魔法占卜远方的景象。",["faction:Alliance"]="尽管性情古怪、孤傲，塞欧克瑞图斯仍利用奥术视野和手中的资源，保护艾尔文森林东部和赤脊山免受不法施法者的侵害。",["race:Human"]="塞欧克瑞图斯与莫甘斯之间的冲突，映照出人类魔法的两条道路：一条潜心钻研，致力于守护；另一条受黑暗野心驱使，走向堕落。"},sec={{t="高塔之主",b="大法师塞欧克瑞图斯在暴风城王国境内拥有自己的据点。他住在阿祖拉之塔，靠近东面通往赤脊山的道路。他习性古怪，有大批仆从照料，生活舒适。其中有侏儒侍从，还有他的裁缝莫雷·艾伯雷恩。虽然远离当地村民的日常琐事，他的魔法仍守护着艾尔文森林东部。"},{t="对抗莫甘斯",b="堕落法师莫甘斯是塞欧克瑞图斯最为忧心的敌人。莫甘斯在附近赤脊山的伊尔加拉之塔中活动。塞欧克瑞图斯既将他视为私敌，也认为他危及暴风城。数月来，塞欧克瑞图斯一直借助奥术研究削弱他的力量。\n\n他利用阿祖拉之眼等占卜装置监视莫甘斯的行动，窥探他的思想。他还研究莫甘斯麾下暗皮豺狼人佩戴的魔法坠饰，希望用一道奥术脉冲，让它们主人的造物反噬其主，并使整群豺狼人无法动弹。"}},faq={{q="塞欧克瑞图斯是谁？",a="大法师塞欧克瑞图斯独居在艾尔文森林东部的阿祖拉之塔。他性情古怪，与外界少有往来，以魔法保护这片地区免受黑暗魔法的威胁。",al={"塞欧克瑞图斯的故事","塔里的法师是谁","阿祖拉之塔的法师"}},{q="塞欧克瑞图斯为何住在艾尔文森林？",a="塞欧克瑞图斯在艾尔文森林东部的阿祖拉之塔中设有自己的圣所。仆从们照料他的起居，而他则潜心研究，监视着与赤脊山接壤的边境，他的对手莫甘斯就住在那里的伊尔加拉之塔中。",al={"塞欧克瑞图斯为何在艾尔文森林"}},{q="塞欧克瑞图斯在与谁交战？",a="塞欧克瑞图斯的主要对手是莫甘斯，一名堕落的人类法师，在边境另一侧赤脊山的伊尔加拉之塔中研习黑暗魔法。塞欧克瑞图斯将莫甘斯视为私敌，也认为他对暴风城构成了严重威胁。",al={"塞欧克瑞图斯的敌人","莫甘斯是谁","塞欧克瑞图斯的对手"}},{q="阿祖拉之眼是什么？",a="阿祖拉之眼是一件安置在塞欧克瑞图斯塔顶的占卜装置。他用它窥视远方的土地，追踪威胁，并尝试读取莫甘斯的思想。",al={"阿祖拉之眼的故事","塞欧克瑞图斯如何监视","塞欧克瑞图斯的水晶球"}},{q="塞欧克瑞图斯为何想要暗皮豺狼人的坠饰？",a="暗皮豺狼人效忠于莫甘斯，佩戴着与他相连的附魔坠饰。塞欧克瑞图斯研究这些坠饰，探究这种联系如何运作，希望借此传送一道奥术攻击，在战斗中麻痹这些豺狼人。",al={"豺狼人坠饰与塞欧克瑞图斯","塞欧克瑞图斯寻回","为何收集豺狼人坠饰"}},{q="谁在塔中侍奉塞欧克瑞图斯？",a="塞欧克瑞图斯的仆从包括照料他日常事务的侏儒，以及打理他衣物的私人裁缝莫雷·艾伯雷恩。",al={"阿祖拉之塔的仆从","谁住在阿祖拉之塔","塞欧克瑞图斯的仆从"}}},fx={ffea707c={q="塞欧克瑞图斯效忠哪一方？",a="大法师塞欧克瑞图斯独立行事，专注于自己的玄奥研究。虽然他不参与暴风城和联盟的日常政务，却仍将保卫王国免受黑暗巫术侵害视为己任。他坚决反对叛变巫师莫甘斯，以及正在侵入艾尔文和赤脊山的黑暗势力。",al={"塞欧克瑞图斯属于联盟还是部落","塞欧克瑞图斯为谁效力","塞欧克瑞图斯的阵营"}},["09c566f6"]={q="塞欧克瑞图斯想要什么？",a="塞欧克瑞图斯将自己强大的奥术力量用于对抗宿敌、堕落法师莫甘斯。他借助名为阿祖拉之眼的魔法占卜装置，以及找回的暗皮豺狼人坠饰，试图窥探莫甘斯的心智，瓦解这名黑暗巫师对肆虐当地的豺狼人的控制。",al={"塞欧克瑞图斯的目标","塞欧克瑞图斯想做什么","塞欧克瑞图斯的目的"}},a72df9dd={q="塞欧克瑞图斯为什么在艾尔文森林？",a="塞欧克瑞图斯在艾尔文森林东部的阿祖拉之塔安顿下来。这座偏僻的高塔为他提供了一处宁静的居所，让他能在侏儒侍从的陪伴下潜心研究，同时监视附近与赤脊山接壤的边境。",al={"塞欧克瑞图斯为什么在艾尔文","塞欧克瑞图斯为什么在这里","塞欧克瑞图斯为什么在阿祖拉之塔"}},f1864285={q="塞欧克瑞图斯与谁有关联？",a="塞欧克瑞图斯虽然性情古怪、离群索居，塔中却有一群忠心的侏儒仆从和私人裁缝莫雷·艾伯雷恩侍奉，而他与叛变法师莫甘斯之间的深仇也始终未解。",al={"塞欧克瑞图斯的人际关系","塞欧克瑞图斯的朋友","塞欧克瑞图斯在达拉然的盟友"}}},fp="10,229,19.375.0,24.549.0,18.195.0,42.219.0,35.218.0,25.159.0,51.219.0,35.150.0"}
P.entries["npc:therylune"] = {n="瑟瑞露尼",s="在黑海岸南部的主宰之剑，瑟瑞露尼正等待机会逃离囚禁。暮光之锤的邪教徒将这位树妖困在了这处古老遗址，她需要一位旅人的帮助才能抵达安全之地。",h="在黑海岸南部的主宰之剑，瑟瑞露尼正等待机会逃离囚禁。暮光之锤的邪教徒将这位树妖困在了这处古老遗址，她需要一位旅人的帮助才能抵达安全之地。",kw={"塞纳留斯","黑海岸","树妖","护送","主宰之剑","瑟瑞露尼","瑟瑞希尔","暮光之锤"},ang={["class:Druid"]="身为德鲁伊，你与塞纳留斯及其亲族有着深厚的渊源。面对一位被邪恶教徒俘虏的树妖，你深感营救她是刻不容缓的职责。",["race:NightElf"]="身为暗夜精灵，你与塞纳留斯的女儿们有着古老而神圣的联系。瑟瑞露尼被暮光之锤囚禁，是对卡利姆多平衡的亵渎。"},sec={{t="邪教的俘虏",b="瑟瑞露尼是一位树妖，是守护自然的塞纳留斯之女。她从卡利姆多北部宁静的林地来到黑海岸南部的主宰之剑。暮光之锤的邪教徒聚集在这处古老的挖掘场，并伏击了她。邪教徒成群结队地包围着她，她无法独自杀出重围。她需要有人护送她穿过邪教徒的包围，抵达安全之地。"}},faq={{q="瑟瑞露尼是谁？",a="瑟瑞露尼是一位树妖，是半神塞纳留斯居于林间的女儿之一。暮光之锤的邪教徒在黑海岸南部的主宰之剑俘虏了她。",al={"瑟瑞露尼是谁","瑟瑞露尼的故事","瑟瑞露尼是什么"}},{q="瑟瑞露尼为什么被困在主宰之剑？",a="瑟瑞露尼遭到暮光之锤邪教徒的伏击，被困住了。他们围绕主宰之剑的巨大石化遗骸建立了一座黑暗营地。",al={"她为什么被俘","瑟瑞露尼如何被俘","主宰之剑邪教徒"}},{q="瑟瑞露尼有家人吗？",a="有。瑟瑞露尼与瑟瑞希尔是姐妹，后者是另一位树妖，居住在卡利姆多北部的林地中。",al={"瑟瑞露尼的姐妹","瑟瑞希尔 瑟瑞露尼","瑟瑞露尼的家人"}},{q="帮助她逃脱后会发生什么？",a="你在充满敌意的邪教徒中清出一条道路后，瑟瑞露尼便逃离主宰之剑，回到周围安全的荒野中。",al={"瑟瑞露尼逃脱","任务945","瑟瑞露尼做什么"}}},fp="9,133,19.366.0,17.166.0,48.159.0,31.105.0,38.139.1"}
P.entries["npc:therysil"] = {n="瑟瑞希尔",s="在灰谷中部的艾森娜神殿，瑟瑞希尔正等候她姐妹的消息。这位树妖一心守护自然，但瑟瑞露尼已被暮光之锤的教徒掳走。",h="在灰谷中部的艾森娜神殿，瑟瑞希尔正等候她姐妹的消息。这位树妖一心守护自然，但瑟瑞露尼已被暮光之锤的教徒掳走。",kw={"灰谷","塞纳留斯","树妖","艾森娜神殿","瑟瑞露尼","瑟瑞希尔","暮光之锤"},ang={["class:Druid"]="身为塞纳留斯的女儿，瑟瑞希尔体现了塞纳里奥议会与灰谷自然之灵之间的紧密联系。对于到访的德鲁伊而言，她的困境尤为迫切。",["race:NightElf"]="长久以来，树妖一直与kaldorei并肩守护灰谷的神圣林地，艾森娜神殿也在其中。"},sec={{t="守护者的守望",b="瑟瑞希尔守望在灰谷古老林地中的艾森娜神殿水边。身为树妖与塞纳留斯的女儿，她肩负着守护荒野及其中精魂的使命。如今，她牵挂着瑟瑞露尼，后者在附近被疯狂的暮光之锤教派俘虏。瑟瑞希尔焦急地等待着一位游历至此的盟友，希望能得到帮助，救出她的姐妹。"}},faq={{q="瑟瑞希尔是谁？",a="瑟瑞希尔是一位居住在灰谷艾森娜神殿的树妖。她是塞纳留斯的女儿，也是瑟瑞露尼的姐妹。",al={"瑟瑞希尔是谁","瑟瑞希尔的故事","艾森娜的树妖"}},{q="瑟瑞希尔在担忧什么？",a="瑟瑞希尔担心她的姐妹瑟瑞露尼的安危，暮光之锤的教徒在黑海岸南部的主宰之剑伏击并俘虏了她。她在神殿等候，希望有人能引领瑟瑞露尼平安归来。",al={"瑟瑞希尔在做什么","瑟瑞希尔为何担忧","瑟瑞希尔任务"}},{q="瑟瑞露尼是谁？",a="瑟瑞露尼是瑟瑞希尔的姐妹，也是灰谷的一位树妖。暮光之锤俘虏了她，她需要有人护送她逃离险境，与瑟瑞希尔团聚。",al={"瑟瑞露尼","瑟瑞希尔的姐妹","瑟瑞露尼是谁"}},{q="在哪里可以找到瑟瑞希尔？",a="瑟瑞希尔位于艾森娜神殿，那是灰谷中部道路旁的一处神圣的自然庇护之地。",al={"瑟瑞希尔位置","瑟瑞希尔在哪里","艾森娜神殿树妖"}}},fp="8,218,18.335.0,16.118.0,27.214.0,17.148.0,28.111.0"}
P.entries["npc:thor"] = {n="索尔",s="在哨兵岭，索尔通过狮鹫航线维系着西部荒野与暴风城的联系。他训练有素的坐骑载着旅人和紧急信件，飞越危机四伏的道路。",h="在哨兵岭，索尔通过狮鹫航线维系着西部荒野与暴风城的联系。他训练有素的坐骑载着旅人和紧急信件，飞越危机四伏的道路。",kw={"信使","飞行管理员","狮鹫","人民军","哨兵岭","索尔","西部荒野"},ang={["faction:Alliance"]="作为协助人民军的联盟勇士，你可以搭乘索尔最快的航线返回首都，递交前线情报并补充物资。"},sec={{t="哨兵岭的狮鹫巢",b="索尔照料着哨兵岭的Gryphon Roost，让西部荒野的守军与王国其他地区保持联系。在地面上，人民军面对着强盗、豺狼人和失控的收割傀儡。他的狮鹫载着旅人和军事急件，从那些险路上空飞过。格里安·斯托曼的报告和紧急求援信件，能比徒步信使更快地送达暴风城的宫廷。"}},faq={{q="索尔是谁？",a="索尔照料着西部荒野哨兵岭的狮鹫栖息处。他训练有素的坐骑载着旅人，往返于西部荒野和包括暴风城在内的其他联盟城镇之间。",al={"此人是谁","哨兵岭飞行管理员","索尔非玩家角色"}},{q="他在西部荒野担负什么职责？",a="索尔维系着哨兵岭的空中交通。他协调信使，在人民军与暴风城最高指挥部之间传递军情，让指挥官们在道路上有迪菲亚活动的情况下仍能掌握消息。",al={"索尔做什么","索尔的作用"}},{q="为什么狮鹫飞行在这里如此重要？",a="狮鹫航线让人们能够迅速、安全地绕过西部荒野、艾尔文森林和暮色森林之间的险路。迪菲亚拦路强盗、河爪豺狼人和危险的野生动物威胁着这些道路，而狮鹫则让补给和消息得以持续运送。",al={"为何在西部荒野乘坐飞行坐骑","西部荒野航线"}}},fx={["5cbb8458"]={q="索尔站在哪一边？",a="索尔忠于联盟，直接支持哨兵岭的人民军。他听命于暴风城的狮鹫管理员网络，运送可靠的信使、士兵和冒险者穿行于王国领空，为王国效力，确保西部荒野与首都保持至关重要的联系。",al={"索尔效忠谁","索尔属于联盟吗","索尔为谁效力"}},a791490a={q="索尔想要什么？",a="索尔致力于维持哨兵岭与暴风城等友方据点之间的空中交通畅通。他专注于照料狮鹫，让它们随时可以起飞，确保紧急军报和旅客能及时避开在西部荒野道路上游荡的匪徒与野兽。",al={"索尔的动机","索尔在做什么","索尔在西部荒野的目的"}},f6f75bde={q="索尔为什么驻守在哨兵岭？",a="哨兵岭是人民军抵御迪菲亚潜行者的堡垒，如今正饱受围困之苦。索尔驻守在这座堡垒顶端，因为穿越西部荒野的陆路处处潜伏着伏击，狮鹫航线便成了通往艾尔文森林和暴风城最快捷、最安全的生命线。",al={"索尔为什么在西部荒野","索尔在哨兵岭的位置","索尔为什么在这里"}},["62307107"]={q="索尔与谁有联系？",a="索尔与暴风城的 狮鹫饲养员 有联系，并与首都的狮鹫管理员杜加尔·朗德瑞克密切合作。在当地，他与格里安·斯托曼及哨兵岭的守军协作，为他们提供通往外界的重要运输和侦察联络。",al={"索尔的人脉","索尔与谁合作","索尔的盟友"}}},fp="4,153,26.409.0,12.168.0,35.217.0,37.247.0"}
P.entries["npc:thorgas-grimson"] = {n="索加斯·格瑞姆森",s="在寒脊山谷的安威玛尔内，索加斯·格瑞姆森教导新手猎人如何面对丹莫罗冰封的荒野。这位经验丰富的野外老手相信，严寒中的亲身历练能教会他们生存之道。",h="在寒脊山谷的安威玛尔内，索加斯·格瑞姆森教导新手猎人如何面对丹莫罗冰封的荒野。这位经验丰富的野外老手相信，严寒中的亲身历练能教会他们生存之道。",kw={"安威玛尔","寒脊山谷","丹莫罗","矮人猎人","猎人训练师","索加斯·格瑞姆森"},ang={["class:Hunter"]="身为矮人猎人，你最初的导师或许就是索加斯·格瑞姆森。他会在追踪野兽和在冰冷山谷中生存方面，为你提供入门指引。",["race:Dwarf"]="身为矮人，你与巡逻于丹莫罗冰封群峰之间的铁炉堡巡山人一样，拥有坚韧、自立的精神。"},sec={{t="严寒中的向导",b="在安威玛尔内，索加斯·格瑞姆森指引着新晋的巡山人和斥候。他抛开枯燥的课程，让年轻的猎人走进凛冽的寒风。他们手持弓箭或枪械，亲自追踪丹莫罗的凶悍野兽。"}},faq={{q="索加斯·格瑞姆森是谁？",a="索加斯·格瑞姆森在安威玛尔内训练猎人，这里是丹莫罗寒脊山谷的中心哨站。他为联盟的新手猎人提供最初的指引，传授基本的野外技能。",al={"索加斯·格瑞姆森","索加斯是谁","安威玛尔猎人训练师"}},{q="索加斯提供哪些训练？",a="索加斯教导新手猎人掌握荒野生存技能，从在雪地上追踪野兽，到提高远程射击的准头。他引领他们踏上成为巡山人的道路。",al={"索加斯教什么","安威玛尔猎人技能"}},{q="他的训练理念是什么？",a="索加斯相信，荒野比理论更能教会猎人本领。猎人必须走进冰冷的积雪，直面丹莫罗的野兽，才能驾驭荒野。",al={"索加斯的性格","索加斯如何训练"}},{q="索加斯·格瑞姆森会与其他职业的人交谈吗？",a="索加斯会礼貌地告诉其他职业的冒险者，他无法训练他们。他建议他们寻找适合自己道路的导师。",al={"其他职业能和索加斯交谈吗","索加斯对话"}}},fx={c3cc0970={q="索加斯·格瑞姆森站在哪一边？",a="索加斯坚定地支持铁炉堡矮人以及整个联盟。他驻守在寒脊山谷的安威玛尔，运用自己的技艺训练新手猎人，让他们能够保卫王国，守护矮人的土地，抵御不断逼近的野兽和敌人。",al={"索加斯·格瑞姆森的阵营","索加斯·格瑞姆森效忠谁","索加斯·格瑞姆森为谁效力"}},["8eae34e9"]={q="索加斯·格瑞姆森想要什么？",a="索加斯想把初出茅庐的新兵培养成能够独当一面的神射手。他相信真正的本领无法仅靠言传，因此力求让新手猎人走进冰雪覆盖的荒野，在实战中磨炼追踪与战斗的本能。",al={"索加斯·格瑞姆森的目标","索加斯想要什么","索加斯·格瑞姆森的目的"}},d81e027b={q="索加斯·格瑞姆森为什么在安威玛尔？",a="他驻守在安威玛尔，指引刚刚踏入寒脊山谷的猎人新兵。恶劣的天气切断了山谷与外界的联系，穴居人和野兽又构成威胁，因此需要索加斯这样的老练追踪者，确保新兵学会生存与战斗。",al={"索加斯为什么在安威玛尔","索加斯·格瑞姆森为何驻留此地","索加斯·格瑞姆森为什么在这里"}}},fp="15,181,19.220.0,23.180.0,33.178.0,32.139.0,44.134.0"}
P.entries["npc:thorgrum-borrelson"] = {n="索格拉姆·伯雷森",s="在塞尔萨玛上方，索格拉姆·伯雷森让旅人得以乘狮鹫飞越洛克莫丹。他的狮鹫栖所将这片山谷与铁炉堡及附近的山口连接起来。",h="在塞尔萨玛上方，索格拉姆·伯雷森让旅人得以乘狮鹫飞越洛克莫丹。他的狮鹫栖所将这片山谷与铁炉堡及附近的山口连接起来。",kw={"丹莫罗","飞行管理员","狮鹫管理员","铁炉堡","洛克莫丹","塞尔萨玛","索格拉姆·伯雷森"},ang={["faction:Alliance"]="身为联盟的一员，你可以依靠索格拉姆的狮鹫栖所，往返于矮人王国与湿地和阿拉希高地的据点之间。",["race:Dwarf"]="身为矮人，你可以指望索格拉姆·伯雷森维持通往铁炉堡巍峨殿堂的空中航线。"},sec={{t="塞尔萨玛上方的栖所",b="索格拉姆·伯雷森掌管着塞尔萨玛上方峭壁上的狮鹫栖所。他训练的狮鹫载着联盟成员飞越洛克莫丹，那里的穴居人和成群的豺狼人威胁着道路安全。它们穿过南门小径，抵达丹莫罗的Great Forge，再继续飞往湿地及更远的地方。"}},faq={{q="索格拉姆·伯雷森是谁？",a="索格拉姆·伯雷森负责塞尔萨玛的联盟狮鹫航线，运送旅人往返洛克莫丹。",al={"索格拉姆","塞尔萨玛飞行管理员","塞尔萨玛的狮鹫管理员是谁"}},{q="索格拉姆能将旅人送往何处？",a="索格拉姆能将旅人从塞尔萨玛送往铁炉堡、湿地的米奈希尔港、阿拉希高地的避难谷地、河林的法霍德要塞，以及邻近地区的哨站。",al={"塞尔萨玛飞行路线","从洛克莫丹能飞往哪里"}},{q="为什么狮鹫飞行在洛克莫丹如此重要？",a="穴居人、豺狼人和黑铁斥候威胁着洛克莫丹的山口。狮鹫让联盟的信使、斥候和冒险者得以迅速穿越这片地区，避开这些危险。",al={"为什么在洛克莫丹乘坐狮鹫","洛克莫丹交通"}}},fx={["30011ebf"]={q="索格拉姆·伯雷森站在哪一边？",a="索格拉姆是铁炉堡的忠诚子民，为联盟效力。作为驻守在塞尔萨玛正上方高地的当地飞行管理员，他负责管理连接这个山中王国首都与周边领地的空中信使和运输网络，确保联盟信使与旅客能迅速穿越卡兹莫丹。",al={"索格拉姆·伯雷森的阵营","索格拉姆为谁效力","索格拉姆与联盟"}},aebc9bb6={q="索格拉姆·伯雷森想要什么？",a="索格拉姆最关心的是保持空中航路畅通，维持洛克莫丹与其他联盟据点之间稳定的空中联系。他照料着栖息在塞尔萨玛上方山脊上的狮鹫，确保信使、冒险者和公文能及时抵达铁炉堡等目的地。",al={"索格拉姆想要什么","索格拉姆·伯雷森的目标","索格拉姆的职责"}},db7b8a65={q="索格拉姆·伯雷森为什么在这里？",a="索格拉姆驻守在俯瞰塞尔萨玛的峭壁上，因为这座城镇是洛克莫丹的中心。穿越山口的陆路交通经常受到穴居人、狗头人和凶猛野兽的威胁，专设的狮鹫栖息地能确保山谷中的聚居地与 大锻炉 之间的联系不被切断。",al={"索格拉姆为什么在洛克莫丹","索格拉姆为什么在塞尔萨玛上方","索格拉姆驻留此地的目的"}}},fp="18,151,25.296.0,26.115.0,34.203.0,46.188.0"}
P.entries["npc:thork"] = {n="索克",s="索克在十字路口负责守卫这座聚居地。他派遣部落冒险者对抗袭击者，并努力保持补给路线畅通。",h="索克在十字路口负责守卫这座聚居地。他派遣部落冒险者对抗袭击者，并努力保持补给路线畅通。",kw={"贫瘠之地","十字路口","卡德拉克","曼科里克","莫尔杉","兽人","补给","索克"},ang={["class:Warrior"]="身为战士，你能体会索克对补给路线、周密巡逻以及在敌人抵达镇子围墙前将其阻截的重视。",["faction:Horde"]="如果你是来自杜隆塔尔或莫高雷的部落成员，向索克报到是证明自己有能力守护卡利姆多的重要一步。",["race:Orc"]="身为兽人，你知道，保卫部落在卡利姆多新征服的土地、抵御周边敌人的侵扰，是一项艰巨的职责。"},sec={{t="十字路口的指挥官",b="索克统领十字路口的防御，这里的道路连接着杜隆塔尔、莫高雷和更远的土地。镇子四面受敌。野猪人的劫掠、半人马的进攻和四处出没的鹰身人让他的兵力捉襟见肘。索克召集有能力的旅人，应对守卫们无法独自处理的危险。"},{t="巩固边境",b="索克的守卫职责并不限于十字路口的围墙之内。他派遣斥候和信使北上前往莫尔杉壁垒，向卡德拉克报告情况。北部和东部的路线承担着穿越贫瘠之地的物资运输。保持这些道路畅通，才能维持部落在这片灌木荒原上的势力。"},{t="内外的威胁",b="索克感谢那些打击钢鬃劫掠行动幕后首领的旅人。被俘的野猪人碎牙背叛了自己的部族，帮助他们攻击部族首领。当旅人将洛克·奥克班恩的头颅带到十字路口时，索克感谢他们削弱了针对部落补给路线的攻势。"}},faq={{q="索克是谁？",a="索克统领贫瘠之地十字路口的防御。他组织镇子的防卫，并努力保障补给商队的安全。",al={"索克背景故事","索克是谁","索克十字路口"}},{q="索克在哪里？",a="索克站在十字路口中央附近的露天处，协调守卫并下达防御命令。",al={"索克位置","寻找索克","索克站在哪里"}},{q="十字路口为什么如此容易遭到攻击？",a="十字路口位于贫瘠之地几条主要商路的开阔交汇处，几乎没有石砌防御工事。敌对的钢鬃野猪人、科卡尔半人马和联盟斥候威胁着它的边界，因此这座聚居地需要时刻保持警戒。",al={"十字路口遭到攻击","十字路口为何危险"}},{q="索克与曼科里克是什么关系？",a="曼科里克请求派遣士兵猎杀野猪人并寻找失踪的妻子时，索克拒绝了。他有限的兵力必须守卫哨站及其补给商队。",al={"曼科里克与索克","索克是否帮助了曼科里克"}},{q="索克如何与其他部落哨站协调？",a="索克派遣信使和战士前往摩尔杉壁垒的卡德拉克那里，报告北部边境的情况，并监视灰谷边界。",al={"索克与卡德拉克","索克摩尔沙农场"}},{q="索克要应对哪些威胁？",a="索克面对的是四处劫掠的野猪人战帮，它们扰乱贸易，抢夺补给箱。他也会感谢那些击败劫掠行动幕后首领的旅人。",al={"十字路口的敌人","索克任务信息"}}},fp="5,143,27.290.0,20.293.0,22.287.1,13.131.0,23.110.0,46.235.0,42.162.0,49.139.0,34.144.0"}
P.entries["npc:thorvald-deepforge"] = {n="索瓦尔德·深炉",s="在国王谷，前往洛克莫丹的旅人会发现索瓦尔德·深炉已备好武器。他协助守卫丹莫罗与洛克莫丹之间的山口。",h="在国王谷，前往洛克莫丹的旅人会发现索瓦尔德·深炉已备好武器。他协助守卫丹莫罗与洛克莫丹之间的山口。",kw={"深炉","丹莫罗","洛克莫丹","巡山人","索瓦尔德·深炉","国王谷","武器锻造师"},ang={["profession:Blacksmithing"]="身为铁匠，你熟悉深炉这个姓氏，也了解矮人铁匠以品质可靠的铁器闻名。",["race:Dwarf"]="身为矮人，你在国王谷的先祖巨碑下找到索瓦尔德，他正协助保障卡兹莫丹边境的补给与安全。"},sec={{t="为东部山口供应武器",b="索瓦尔德·深炉在国王谷供应武器。穴居人和四处游荡的野兽威胁着连接卡兹莫丹腹地与外围地区的山口。来自丹莫罗的旅人，以及准备深入洛克莫丹的人，都能在这里找到刀剑和斧头，随时保卫矮人的领土。"}},faq={{q="索瓦尔德·深炉是谁？",a="索瓦尔德·深炉在国王谷出售武器，通往洛克莫丹的道路从这里离开丹莫罗。他为边境沿线的旅人和守卫供应武器。",al={"索瓦尔德是谁","索瓦尔德·深炉非玩家角色","深炉洛克莫丹"}},{q="他在当地的防御中起什么作用？",a="索瓦尔德·深炉为穿越山口的旅人供应武器。他也帮助装备前往洛克莫丹各处哨站的新兵。",al={"索瓦尔德做什么","索瓦尔德的作用","前线补给"}},{q="他与卡兹莫丹其他姓深炉的矮人有亲属关系吗？",a="索瓦尔德·深炉或许与其他同姓深炉的矮人有亲属关系，包括莫高特和本古斯·深炉，但这些关系都未得到证实。大锻炉的托姆斯·深炉称索瓦尔德是他的同事。",al={"深炉家族","索瓦尔德·深炉的亲属","莫高特 深炉的亲属"}}},fx={["7578ebb9"]={q="索瓦尔德·深炉站在哪一边？",a="索瓦尔德·深炉是一名忠于铁炉堡的矮人，坚定地支持联盟。他驻守在国王谷，为当地对抗穴居人及其他威胁的部队供应武器和装备，以此支援 巡山人，保卫卡兹莫丹。",al={"索瓦尔德·深炉的阵营","索瓦尔德·深炉与联盟","索瓦尔德为谁效力"}},["2f5ea740"]={q="索瓦尔德·深炉想要什么？",a="索瓦尔德专注于让联盟守军装备齐全，随时准备战斗。他在洛克莫丹南部的哨塔任职，为对抗穴居人的 巡山人 持续供应武器和护甲，也欢迎为部队带来新装备的铁匠。",al={"索瓦尔德·深炉的目标","索瓦尔德需要什么","索瓦尔德·深炉的动机"}}},fp="18,158,23.298.0,26.159.0,47.143.0,52.217.0"}
P.entries["npc:thotar"] = {n="索塔尔",s="在剃刀岭，索塔尔教导年轻的部落猎人追踪和驯服野兽的方法。他训练那些离开试炼谷、前来应对杜隆塔尔野生动物的兽人和巨魔。",h="在剃刀岭，索塔尔教导年轻的部落猎人追踪和驯服野兽的方法。他训练那些离开试炼谷、前来应对杜隆塔尔野生动物的兽人和巨魔。",kw={"杜隆塔尔","猎人","猎人训练师","卡普拉克","兽人","剃刀岭","驯服野兽","索塔尔"},ang={["class:Hunter"]="作为部落猎人，你离开新手所在的山谷后，会学习驯服野兽的仪式和荒野生存技能。",["faction:Horde"]="作为部落的一员，你可以在剃刀岭向索塔尔学习，凭借敏锐的目光和与你默契深厚的战斗野兽，巡逻杜隆塔尔的边境。",["race:Orc"]="作为兽人，你遵循索塔尔传授的传统狩猎习俗，秉承先祖对追踪技艺与野兽伙伴关系的敬重。",["race:Troll"]="作为离开Sen’jin Village的黑暗之矛猎人，你会学习部落的生存技能，以应对杜隆塔尔的危险。"},sec={{t="剃刀岭的导师",b="在剃刀岭，索塔尔训练部落猎人，让他们为踏入杜隆塔尔的荒野做好准备。新兵在试炼谷学会基础本领，随后在面对更危险的掠食者时前来向他求教。他遵循兽人世代相传的传统，传授射击技巧，也教导猎人怀着敬意，与卡利姆多最致命的生物共处并指挥它们。"},{t="驯服荒野",b="索塔尔引导年轻猎人掌握驯服野兽的古老技艺。他派他们深入干旱的峡谷，安抚当地生物并与之建立羁绊，其中包括剧毒的蝎子、披甲的潮行蟹和狡猾的野猪。他的教导让部落追踪者学会与自然建立联系，而非依赖武力。"}},faq={{q="索塔尔是谁？",a="索塔尔在剃刀岭训练猎人，传授传统的荒野知识、射击技巧和驯兽技艺。",al={"索塔尔是谁","索塔尔背景故事","索塔尔做什么"}},{q="在哪里可以找到索塔尔？",a="索塔尔位于剃刀岭，这是杜隆塔尔中部的一处部落聚居地，就在试炼谷以北。",al={"索塔尔位置","索塔尔在哪里","寻找索塔尔"}},{q="索塔尔传授哪些传统？",a="索塔尔传授兽人世代相传的狩猎和追踪传统。他注重武器的运用、荒野求生，以及耐心地与动物伙伴建立羁绊。",al={"索塔尔教什么","猎人传统","索塔尔训练"}},{q="索塔尔只训练兽人吗？",a="索塔尔训练前来剃刀岭的部落猎人。他指导黑暗之矛巨魔，也指导途经杜隆塔尔的牛头人旅者。",al={"巨魔能跟索塔尔学习吗","索塔尔 牛头人","索塔尔训练谁"}},{q="索塔尔会给年轻猎人布置什么任务？",a="索塔尔派新手猎人追踪杜隆塔尔本地的野生动物，包括野猪、潮行蟹和蝎子。他们使用驯兽棒，赢得野兽的信任与服从。",al={"索塔尔任务","驯服野兽 索塔尔","索塔尔派人做什么"}},{q="为什么驯服野兽在他的训练中如此重要？",a="野兽伙伴能帮助部落猎人在战斗和荒野中生存。索塔尔教导猎人与野兽建立羁绊，使它们成为部落忠诚的守卫。",al={"为什么驯服野兽","猎人宠物背景故事","驯服野兽的目的"}}},fp="6,172,22.352.0,16.293.0,14.108.0,26.111.0,34.184.0,28.142.0,45.172.0,49.170.0"}
P.entries["npc:thrall"] = {n="萨尔",s="萨尔如今坐镇奥格瑞玛的智慧谷，是部落的大酋长，也是杜隆塔尔的统治者。他曾是人类的奴隶，被培养成角斗士，后来解放了自己的族人，恢复了他们的萨满传统，并带领他们渡过无尽之海，前往新的家园。",h="萨尔如今坐镇奥格瑞玛的智慧谷，是部落的大酋长，也是杜隆塔尔的统治者。他曾是人类的奴隶，被培养成角斗士，后来解放了自己的族人，恢复了他们的萨满传统，并带领他们渡过无尽之海，前往新的家园。",kw={"布莱克摩尔","毁灭之锤","杜隆塔尔","go'el","奥格瑞玛","萨满","萨尔","大酋长"},ang={["class:Shaman"]="萨尔被尊为一代兽人中首位新崛起的萨满。在数十年的恶魔腐化之后，他恢复了族人与元素之灵之间神圣的交流。",["faction:Alliance"]="联盟领袖认为萨尔危险，却也务实。他领导的部落纪律严明，远胜于第一次兽人战争和Second War中那些嗜血的征服者。",["faction:Horde"]="萨尔是你的大酋长，也是最高统帅。他带领部落摆脱奴役与毁灭，在卡利姆多迈向充满荣耀的未来。",["race:Orc"]="对兽人而言，萨尔是在世的救世主。他将族人从人类收容所中的萎靡状态中解救出来，使他们重拾祖先的荣耀。"},sec={{t="从奴隶到萨满",b="萨尔出生时名叫古伊尔，是霜狼氏族酋长杜隆坦与德拉卡的儿子。他尚在襁褓之中时，古尔丹的刺客杀害了他的父母，人类指挥官埃德拉斯·布莱克摩尔发现了他，并给他取名为萨尔，意为奴隶。在敦霍尔德城堡，布莱克摩尔将他培养成角斗士，并教给他人类的战术。在义妹塔蕾莎·福克斯顿的帮助下，萨尔逃了出来。霜狼氏族的流亡者德雷克塔尔引导他远离恶魔的腐化，教他掌握元素之灵的力量。萨尔成为了新一代兽人中的第一位萨满。"},{t="大酋长的重任",b="第二次大战结束后，萨尔与奥格瑞姆·毁灭之锤并肩作战，解救在联盟收容所中受苦的兽人。毁灭之锤在战斗中倒下，将自己的黑色板甲和强大的战锤传给萨尔，任命他为大酋长。神秘的先知麦迪文带来了预示未来的幻象，萨尔便带领族人登上缴获的人类船只，渡过无尽之海。他们抵达卡利姆多，避开了降临东部王国的厄运。"},{t="建立新部落",b="在卡利姆多，萨尔重塑了部落，使这支好战的力量成为以生存与荣耀为纽带的同盟。他救下了沃金的暗矛巨魔，并与凯恩·血蹄的牛头人结盟。这支联军与人类和暗夜精灵部队一同，在海加尔山之巅击败了燃烧军团。随后，萨尔建立了杜隆塔尔及其首都奥格瑞玛，分别以父亲和导师之名为其命名。他与吉安娜·普罗德摩尔的塞拉摩维持着并不稳固的和平，同时保卫着脆弱的国家，并权衡着备受争议的结盟选择，其中就包括洛丹伦的被遗忘者。"}},faq={{q="萨尔是谁？",a="萨尔以部落大酋长的身份领导着兽人。他出生于霜狼氏族，本名Go'el，被人类养大，沦为角斗奴隶，后来挣脱束缚，学会了萨满之道，并带领兽人前往卡利姆多，在那里建立了奥格瑞玛。",al={"大酋长是谁","萨尔的身世","萨尔是谁"}},{q="萨尔的名字从何而来？",a="萨尔出生时名叫古伊尔，这是父母杜隆坦与德拉卡给他取的名字。囚禁他的人类埃德拉斯·布莱克摩尔给他取名为萨尔，这个人类古语词汇意为奴隶。萨尔保留了这个名字，用以铭记自己的过去，以及族人发誓永不再承受的压迫。",al={"为什么叫萨尔","萨尔是什么意思","萨尔的本名"}},{q="萨尔为什么身穿黑色护甲，手持战锤？",a="萨尔身穿黑色板甲，手持毁灭之锤，两者都由前任大酋长奥格瑞姆·毁灭之锤传给他。奥格瑞姆在解救收容所中的兽人时身负致命重伤，临终前将武器和大酋长的重任一并交给了萨尔。",al={"毁灭之锤","萨尔的武器","黑色护甲"}},{q="在游戏中哪里能找到萨尔？",a="萨尔居于杜隆塔尔的部落首都奥格瑞玛，坐镇智慧谷。他与护卫和顾问们一同站在索尔的堡垒内。",al={"萨尔在哪里","萨尔的位置","萨尔的房间"}},{q="萨尔与吉安娜·普罗德摩尔是什么关系？",a="在第三次大战期间，萨尔与吉安娜·普罗德摩尔并肩战于海加尔山，赢得了彼此的尊重，并缔结了合作盟约。他们各自的阵营仍然深深猜忌着对方，但两位领袖都在努力维系奥格瑞玛与塞拉摩之间脆弱的和平。",al={"萨尔与吉安娜","吉安娜与联盟","与塞拉摩的和平"}},{q="萨尔为什么允许被遗忘者加入部落？",a="萨尔虽然对亡灵心存戒备，却也看到了希尔瓦娜斯·风行者麾下被遗忘者的绝境，他们已经摆脱了巫妖王的控制。牛头人相信被遗忘者仍可得到救赎，因此从外交层面劝说萨尔接纳他们。萨尔准许他们加入部落，以便在东部王国取得一个战略立足点。",al={"亡灵为什么加入部落","被遗忘者结盟","希尔瓦娜斯加入部落"}}},fp="6,226,20.554.0,26.423.0,21.537.0,14.237.0,35.254.0,52.262.0,36.147.0,52.282.0,49.317.0"}
P.entries["npc:thran-khorman"] = {n="斯兰·库尔曼",s="在安威玛尔，斯兰·库尔曼训练新晋战士，让他们做好准备，迎接寒脊山谷的危险。",h="在安威玛尔，斯兰·库尔曼训练新晋战士，让他们做好准备，迎接寒脊山谷的危险。",kw={"安威玛尔","寒脊山小径","丹莫罗","铁炉堡","斯兰·库尔曼","战士训练师"},ang={["class:Warrior"]="作为在寒脊山小径苏醒的矮人或侏儒战士，斯兰是第一位考验你勇气的导师。他会交给你初始的符文或命令，并教你在战斗中生存的基本技巧。",["race:Dwarf"]="身为矮人，你能从斯兰身上看到铁炉堡守卫坚定不移的决心。即使在和平时期，他也让他们时刻做好战斗准备，使王国永远不至于措手不及。"},sec={{t="寒脊山谷的教官",b="斯兰·库尔曼在安威玛尔的场地上操练矮人新兵和到访的侏儒。他脾气粗暴，要求严苛，对缺乏前线作战勇气的人没什么耐心。第三次大战已经结束，但穴居人仍在不断涌入寒脊山小径。因此，斯兰要求战士们坚持不懈地练习使用斧、锤和盾牌，让铁炉堡的守卫时刻做好战斗准备。"}},faq={{q="斯兰·库尔曼是谁？",a="斯兰·库尔曼在丹莫罗的安威玛尔训练战士。他为寒脊山谷的新手战士传授最初的战斗知识。",al={"斯兰·库尔曼的职责","斯兰是谁","安威玛尔战士训练师"}},{q="他提供什么训练？",a="斯兰教导新手战士掌握姿态和近战技巧。他让他们做好准备，迎战小径中的穴居人和野兽。",al={"斯兰教什么","斯兰战士技能"}},{q="他为什么会冷落某些旅人，或对他们出言生硬？",a="斯兰对研习奥术、暗影或诡秘技艺的人没什么耐心。如果你不是战士，他会直截了当地告诉你，在他的训练下，你连一天都撑不过去。",al={"斯兰为什么无礼","斯兰闲聊","斯兰对非战士的对话"}}},fx={["97dd6db6"]={q="斯兰·库尔曼效忠哪一方？",a="斯兰·库尔曼以效忠铁炉堡与联盟为荣。他驻守在寒脊山谷的安威玛尔，全力操练新入伍的矮人与侏儒，确保丹莫罗能够抵御任何威胁。",al={"斯兰·库尔曼效忠对象","斯兰·库尔曼阵营","斯兰为谁效力"}},["1baa464c"]={q="斯兰·库尔曼想要什么？",a="他希望有志于战斗的人认真对待军事纪律，时刻保持精湛的战斗技艺。尽管大规模战争暂时停歇，他也绝不容许任何人懈怠，要求每一位立志成为战士的人都全力投入严格的训练。",al={"斯兰·库尔曼的目标","斯兰·库尔曼关心什么","斯兰·库尔曼的动机"}},d4f40481={q="斯兰·库尔曼为什么在这里？",a="斯兰奉命驻守安威玛尔，将缺乏经验的冒险者锻造成纪律严明的战士。寒脊山谷是铁炉堡新一代守卫的试炼之地，他确保每个人都懂得如何持剑披甲，才让他们踏入丹莫罗。",al={"斯兰·库尔曼为什么在安威玛尔","斯兰为什么来到寒脊山谷","斯兰·库尔曼的目的"}}},fp="13,84,31.352.0,21.134.0,28.120.0,51.182.0"}
P.entries["npc:thunderaan"] = {n="Thunderaan",s="桑德兰王子是古老的空气的王子，一位庞大的元素生物，在远古火与风的战争中遭到背叛并被击倒。他的一部分精华被火焰之王拉格纳罗斯吞噬，残存的精华则被封入破碎的桎梏，交由火焰之王的副官保管。找回这些遗物的冒险者可以前往希利苏斯寻找德米提恩，再次将他释放。",h="桑德兰王子是古老的空气的王子，一位庞大的元素生物，在远古火与风的战争中遭到背叛并被击倒。他的一部分精华被火焰之王拉格纳罗斯吞噬，残存的精华则被封入破碎的桎梏，交由火焰之王的副官保管。找回这些遗物的冒险者可以前往希利苏斯寻...",kw={"桎梏","德米提恩","加尔","迦顿","熔火之心","空气的王子","拉格纳罗斯","希利苏斯","桑德兰","雷霆之怒","逐风者"},ang={["class:Rogue"]="追求无可匹敌的速度与闪电般迅捷战斗的潜行者，渴望得到空气的王子陨落后封存在标志性利刃雷霆之怒中的精华。",["class:Shaman"]="作为元素的精神守护者，萨满祭司认为桑德兰是艾泽拉斯上风与闪电最纯粹、最狂怒的化身之一。",["class:Warrior"]="战士追寻着雷霆之怒的传说，那是一把与空气的王子有关、灌注了风暴之力的剑。"},sec={{t="元素分裂",b="很久以前，在元素大灾变期间，火与风的势力在艾泽拉斯深处交战了五千年，拉格纳罗斯企图摧毁并吞噬桑德兰。王子遭到拉格纳罗斯麾下两位强大副官迦顿男爵和加尔的伏击与背叛，随后被火焰之王的战锤萨弗拉斯击倒。尽管战败，桑德兰的精华依然过于强大，拉格纳罗斯无法将其完全吸收。"},{t="破碎的护符",b="拉格纳罗斯无法彻底吞噬空气的王子，便将桑德兰所剩无几的精华封入一枚束缚元素的护符。为了阻止王子重新凝聚形体，火焰之王将护符击碎，分成完美的两半。他将其中一半交给迦顿男爵，另一半交给加尔，把两者都藏在黑石山下熔火之心的火山深处。"},{t="希利苏斯的重生",b="胆敢闯入熔火之心的人，可以从拉格纳罗斯的副官手中夺取桎梏的两半。将这些碎片交给德米提恩，便能启动让空气的王子现身的仪式；这位古怪的隐士与暮光之锤结盟，居于希利苏斯干旱的沙丘中。然而，新生的元素并未心怀感激，而是带着狂暴如旋风的怒火降临，迫使召唤者将他击倒，夺取他的传奇之剑——雷霆之怒，逐风者的祝福之剑。"}},faq={{q="桑德兰是谁？",a="桑德兰就是空气的王子，一位高贵而极具毁灭之力的元素领主，隶属于风的阵营。很久以前，他被火焰之王拉格纳罗斯击败，封入元素牢笼。",al={"桑德兰王子是谁","空气的王子","桑德兰背景故事"}},{q="桑德兰最初是如何被击败的？",a="在元素大灾变期间，拉格纳罗斯与麾下副官迦顿男爵和加尔密谋背叛王子。桑德兰被萨弗拉斯击溃，而拉格纳罗斯虽然大肆吞噬他的精华，却无法将其完全消化，只得将剩余的精华锁入一枚裂成两半的护符。",al={"桑德兰如何死去","拉格纳罗斯对战桑德兰","元素大灾变"}},{q="束缚他的桎梏碎片由谁保管？",a="桑德兰的桎梏分成完美的两半，由加尔和迦顿男爵保管，藏于黑石山下的熔火之心深处。",al={"逐风者的桎梏在哪里","桑德兰桎梏位置","加尔和迦顿的桎梏"}},{q="希利苏斯的德米提恩为何牵涉其中？",a="德米提恩是一名居住在希利苏斯的暮光之锤信徒，掌握着重组破碎护符并将空气的王子召唤到艾泽拉斯所需的奥术与元素知识。",al={"德米提恩是谁","德米提恩 桑德兰","如何召唤桑德兰"}},{q="在希利苏斯召唤桑德兰后会发生什么？",a="德米提恩可以使用找回的桎梏举行一场危险的仪式。仪式完成后，便会揭晓现身的究竟是什么。",al={"桑德兰战斗","召唤后会发生什么"}},{q="哪件武器与桑德兰有关？",a="雷霆之怒，逐风者的祝福之剑，是与空气的王子有关的传说之剑。它的命运将在德米提恩的仪式中揭晓。",al={"雷霆之怒","逐风者之剑","桑德兰之剑"}}},fp="10,225,23.359.0,22.334.0,19.331.1,18.171.0,39.250.0,41.130.0,47.170.0,53.122.1,34.132.1"}
P.entries["npc:thyn-tel-bladeweaver"] = {n="塞恩提尔·刃纹",s="在达纳苏斯的战士区，塞恩提尔·刃纹正在寻找失踪的女祭司维琳德·星歌。她派遣值得信赖的联盟冒险者追查维琳德的下落，探寻月神镰刀的谜团。",h="在达纳苏斯的战士区，塞恩提尔·刃纹正在寻找失踪的女祭司维琳德·星歌。她派遣值得信赖的联盟冒险者追查维琳德的下落，探寻月神镰刀的谜团。",kw={"刃纹","达纳苏斯","月神镰刀","哨兵","星歌","塞恩提尔","维琳德","战士区"},ang={["class:Warrior"]="途经达纳苏斯的联盟战士会在战士区的训练师之间找到塞恩提尔，那是一位面孔熟悉的哨兵。",["faction:Alliance"]="来到战士区的联盟英雄获得塞恩提尔的信任，前往中立地区和争夺中的领土探寻真相。",["race:NightElf"]="对暗夜精灵而言，塞恩提尔的调查牵涉他们自己的族人，因为一位备受尊敬的女祭司在她无法掌控的力量之中失踪了。"},sec={{t="哨兵的调查",b="在达纳苏斯的战士区，暗夜精灵哨兵塞恩提尔·刃纹守望着四周。女祭司维琳德·星歌悄然失踪，塞恩提尔不愿让她的线索就此中断。她相信背后可能牵涉危险的力量，于是派遣值得信赖的冒险者搜查维琳德的遗留物品，查明她的旅程通向何方。"},{t="追寻维琳德的足迹",b="塞恩提尔·刃纹派调查者查看维琳德留在达纳苏斯的物品。线索中有一本日记，记述了维琳德与艾露恩的沟通，以及通过月神镰刀召唤出的可怕狼人野兽。线索向南延伸，途经港口棘齿城，进入贫瘠之地，旅人们在那里寻找这位绝望的女祭司失踪前乘船离开的地方。"}},faq={{q="塞恩提尔·刃纹是谁？",a="塞恩提尔·刃纹是驻守达纳苏斯战士区的暗夜精灵哨兵。她着手调查女祭司维琳德·星歌失踪一事。",al={"塞恩提尔·刃纹","塞恩提尔是谁","塞恩提尔资料"}},{q="在哪里可以找到塞恩提尔·刃纹？",a="塞恩提尔·刃纹在达纳苏斯的战士区守望，身边是卡多雷的战士与哨兵。",al={"塞恩提尔位置","塞恩提尔·刃纹在哪里","塞恩提尔地图"}},{q="塞恩提尔·刃纹提供哪些任务？",a="塞恩提尔·刃纹引导冒险者调查维琳德·星歌的失踪事件，从维琳德的日记开始，经过贫瘠之地的港口，再到回复珊蒂斯。",al={"塞恩提尔任务","她提供什么任务"}},{q="她为什么关注维琳德·星歌？",a="塞恩提尔·刃纹想查明维琳德·星歌的遭遇。这位女祭司曾在灰谷供职，后来突然失踪，留下了未竟的工作。",al={"为什么调查维琳德","维琳德发生了什么"}},{q="她的任务线通向哪里？",a="线索从维琳德留在达纳苏斯的物品开始，向南延伸至贫瘠之地的棘齿城，调查者在那里寻找她航程的记录。",al={"维琳德任务路线","任务通向哪里"}},{q="塞恩提尔·刃纹只接待联盟成员吗？",a="是的。塞恩提尔·刃纹驻守达纳苏斯，为联盟成员提供帮助。",al={"部落能与塞恩提尔交谈吗","她属于联盟吗"}}},fp="20,226,20.325.0,23.399.1,28.154.0,38.114.0,44.172.0,42.172.0,32.138.0,49.98.0"}
P.entries["npc:tirion-fordring"] = {n="提里奥·弗丁",s="提里奥·弗丁是一位传奇圣骑士，也是玛登霍尔德城堡的前领主，如今流亡在东瘟疫之地，过着平静的生活。他曾是白银之手骑士团的一员，却因向一名敌对的兽人偿还荣誉之债，被剥夺了头衔和领地。他住在索多里尔河畔的简陋小屋中，注视着洛丹伦各地上演的悲剧，为自己的儿子忧心。",h="提里奥·弗丁是一位传奇圣骑士，也是玛登霍尔德城堡的前领主，如今流亡在东瘟疫之地，过着平静的生活。他曾是白银之手骑士团的一员，却因向一名敌对的兽人偿还荣誉之债，被剥夺了头衔和领地。他住在索多里尔河畔的简陋小屋中，注视着洛丹...",kw={"阿隆索斯·法奥","伊崔格","流放","弗丁","壁炉谷","玛登霍尔德","白银之手","泰兰","索多里尔","提里奥"},ang={["class:Paladin"]="站在提里奥面前，就如同亲眼见到你所属骑士团初创时的曙光；他是第二次战争时期白银之手的骑士，也是一位精通圣光的大师，证明了真正的正义超越凡人的律法。",["faction:Alliance"]="提里奥体现了联盟建立时所秉持的理想，尽管正是这些王国，因为他将个人荣誉置于种族仇恨之上，而将他定为叛徒。",["race:Human"]="提里奥曾是洛丹伦联盟无与伦比的英雄，公正地统治着壁炉谷；他的存在令人痛苦地想起，那个高贵的王国如何在腐朽与疯狂中崩塌。",["race:Orc"]="尽管提里奥曾是一名在第二次战争中杀敌无数的联盟战士，他仍宁愿放弃一切——领地、家人和名誉——也不愿违背对兽人伊崔格立下的荣誉誓言。"},sec={{t="白银之手的骑士",b="洛丹伦毁灭之前，提里奥·弗丁是王国最负盛名的骑士之一。他是白银之手骑士团的圣骑士，这个组织由大主教阿隆索斯·法奥在第二次战争期间创立，提里奥身披板甲，手持战锤，怀着虔诚的信仰对抗旧部落。他被尊为圣光坚定不移的典范。"},{t="荣誉与流放",b="第二次战争结束后，提里奥与妻子卡兰德拉和年幼的儿子泰兰住在玛登霍尔德城堡，统治着壁炉谷地区。他遇到了一位名叫伊崔格的年迈兽人战士，这位战士独自隐居，而这次相遇终结了他的统治。提里奥看出了这位老兵对荣誉的坚守，许诺保护他。当联盟当局发现伊崔格后，提里奥为恪守誓言，与自己的同胞兵戎相见。因为背叛洛丹伦联盟的罪行，提里奥被剥夺贵族身份，逐出白银之手，并遭到流放；乌瑟尔让他的妻儿免受这一惩罚。"},{t="父亲的煎熬",b="他的家人没有受到流放的牵连，留在了壁炉谷。第三次战争期间，洛丹伦沦陷于天灾军团之手，此后提里奥的儿子泰兰长大成人，加入了血色十字军，最终成为壁炉谷的大领主。提里奥远远注视着十字军一步步陷入疯狂，因儿子成了狂热的傀儡而痛苦绝望。这位索多里尔河畔的隐士紧抓着往日幸福的回忆，比如一家人前往凯尔达隆游玩的时光，试图找到办法，让儿子记起真正的荣誉。"}},faq={{q="提里奥·弗丁是谁？",a="提里奥·弗丁是白银之手骑士团的圣骑士，也是壁炉谷的前任统治者。他因坚守荣誉、保护一名兽人而被同僚流放，如今隐居在东瘟疫之地西部边缘一间僻静的小屋中。",al={"提里奥的故事","老圣骑士是谁","提里奥是谁","隐居的圣骑士"}},{q="提里奥为何被逐出洛丹伦？",a="提里奥发现了一名叫伊崔格的年迈兽人老兵，并了解到两人都始终坚守着战士的荣誉。当联盟军队俘获伊崔格后，提里奥为了履行保护这位隐士的承诺，向自己的战友出手。他被视为叛徒，遭到剥夺头衔、逐出王国的惩罚。",al={"提里奥为何被放逐","提里奥叛国","提里奥为何流亡"}},{q="提里奥与壁炉谷有什么关系？",a="壁炉谷曾是提里奥的领地。他从玛登霍尔德城堡治理这片土地，直到遭到流放。如今，壁炉谷由血色十字军占据，指挥他们的是他的儿子，大领主泰兰·弗丁。",al={"提里奥与壁炉谷","玛登霍尔德城堡的提里奥","壁炉谷领主"}},{q="提里奥还拥有圣骑士的力量吗？",a="尽管教会和白银之手正式剥夺了他的身份，并宣称收回了他的神圣力量，提里奥纯粹的信念仍使他与圣光的联系从未断绝。圣光依然像过去一样，强有力地回应着他的意志。",al={"提里奥失去圣光了吗","提里奥还是圣骑士吗","提里奥使用圣光吗"}},{q="提里奥希望血色十字军发生什么改变？",a="提里奥对血色十字军的狂热毫无好感，但他的儿子泰兰却是他们在壁炉谷的最高指挥官之一。提里奥希望唤醒泰兰的良知，在他的灵魂彻底迷失之前，将他从十字军腐化的掌控中解救出来。",al={"提里奥与血色十字军","提里奥与泰兰","提里奥为何关心十字军"}},{q="其他最初的圣骑士是谁？",a="大主教阿隆索斯·法奥在第二次战争期间创立了白银之手骑士团，光明使者乌瑟尔是其中第一位圣骑士。与提里奥并肩的骑士包括图拉扬，以及他的挚友赛丹·达索汉。",al={"最初的圣骑士","最初的白银之手圣骑士","阿隆索斯·法奥与圣骑士"}}},fp="15,230,27.334.0,27.502.0,18.467.1,23.227.0,37.256.0,42.158.0,42.214.0,47.199.0,36.216.0"}
P.entries["npc:tiza-battleforge"] = {n="蒂萨·热炉",s="在铁炉堡，蒂萨·热炉引导年轻的圣骑士研习圣光之道。她教导他们恪守美德、施行善举、舍己为人，并在他们获准运用复活之力前考验这些新学徒。",h="在铁炉堡，蒂萨·热炉引导年轻的圣骑士研习圣光之道。她教导他们恪守美德、施行善举、舍己为人，并在他们获准运用复活之力前考验这些新学徒。",kw={"矮人","秘法大厅","铁炉堡","穆里顿·热炉","秘法区","圣骑士","救赎","白银之手","蒂萨·热炉","圣洁之书"},ang={["class:Paladin"]="身为矮人圣骑士，你将通过圣洁之书接受蒂萨·热炉的考验。证明自己合格的人，便有机会学会复活阵亡的盟友。",["faction:Alliance"]="从暴风城到卡拉诺斯，蒂萨与各地导师携手，在联盟疆域内维持共同的美德准则与战备标准。",["race:Dwarf"]="蒂萨展现了圣光与白银之手在矮人文化中扎根之深。她引导卡兹莫丹的守卫者抵御黑铁氏族等威胁。"},sec={{t="秘法区的导师",b="蒂萨·热炉在铁炉堡的秘法大厅指导圣骑士。联盟各地的导师将新学徒送到她身边，进一步研习圣光。布兰度尔·铁锤从铁炉堡、阿扎尔·战锤从丹莫罗、格雷森·沙东布瑞克公爵从暴风城派遣学徒前来。\n\n蒂萨教导他们，圣光的要求远不止精通战斗。侍奉它的人必须谦卑地服务他人，心怀怜悯，并坚定抵御天灾军团及其他威胁。"},{t="神性试炼",b="蒂萨将圣洁之书交给年轻的圣骑士研读。随后，她派他们去施行善举，先帮助约翰·特纳这样贫困而有所需的人。接着，她让他们协助自己的丈夫穆里顿·热炉对抗黑铁矮人，以此考验他们的信仰和本领。\n\n通过这些试炼，并用生命符记复活阵亡盟友的人，会赢得蒂萨的信任。此后，他们便可施展神圣的复活之术。"}},faq={{q="蒂萨·热炉是谁？",a="蒂萨·热炉是白银之手骑士团的一名矮人圣骑士。她在铁炉堡的秘法大厅指导圣骑士，帮助他们与圣光建立更深的联系。",al={"蒂萨是谁","蒂萨·热炉的故事","圣骑士训练师蒂萨"}},{q="在哪里可以找到蒂萨·热炉？",a="蒂萨位于铁炉堡秘法区的秘法大厅，那里传授信仰与奥术方面的学问。",al={"蒂萨的位置","蒂萨·热炉在哪里","秘法大厅圣骑士训练师"}},{q="她交给圣骑士的圣洁之书是什么？",a="圣洁之书是一部记载圣光教义与美德的圣典。蒂萨让圣骑士先研读它，再接受有关慈善、勇气和仁慈的试炼。",al={"圣洁之书 蒂萨","蒂萨的书籍任务","圣洁之书是什么"}},{q="蒂萨为何派圣骑士去帮助她的丈夫穆里顿？",a="蒂萨派圣骑士协助她的丈夫穆里顿·热炉对抗黑铁矮人，而他当时正在帮助同伴纳姆·法奥克。这份危险考验着他们的勇气，以及他们是否已准备好运用生命符记复活阵亡的战友。",al={"蒂萨丈夫的任务","与穆里顿·热炉的关系","为何帮助穆里顿"}},{q="蒂萨会向合格的圣骑士传授什么能力？",a="合格的圣骑士完成她的慈善试炼，并救回穆里顿阵亡的同伴后，蒂萨便会向他们传授救赎这一神圣的复活仪式。",al={"蒂萨的圣骑士法术","蒂萨传授什么法术","铁炉堡复活术圣骑士训练师"}},{q="她与布兰度尔·铁锤有什么关系？",a="布兰度尔·铁锤也是铁炉堡秘法大厅的一名矮人圣骑士训练师。蒂萨曾告诉他，嫉妒是他心灵上的弱点，布兰度尔则发誓要克服它。",al={"蒂萨与布兰度尔","布兰度尔·铁锤 蒂萨","布兰度尔的嫉妒"}}},fx={["28fe0e8a"]={q="蒂萨·热炉效忠哪一方？",a="蒂萨以效忠联盟、铁炉堡王国和白银之手骑士团为荣。作为一名虔诚的圣骑士，她最终效忠的是圣光，并致力于保护艾泽拉斯，抵御天灾军团以及阴险的黑铁矮人等邪恶势力。",al={"蒂萨·热炉阵营","蒂萨为谁效力","蒂萨·热炉 联盟"}},["5d20b420"]={q="蒂萨·热炉想要什么？",a="蒂萨希望在圣骑士新兵心中培育真正的美德、仁爱和坚定的信仰。除了通过神圣试炼考验他们的武艺与虔诚，她还收集当地威胁的情报，例如黑铁的入侵，以便警告城市议会，保障铁炉堡的安全。",al={"蒂萨·热炉的目标","蒂萨想要什么","蒂萨的动机"}},["075b45b0"]={q="蒂萨·热炉为什么在秘法大厅？",a="她居于铁炉堡秘法区内的秘法大厅，指引立志成为圣骑士的矮人。她在城中神圣教团的核心之地指导联盟指挥官送来的新兵，考验他们的无私之心与对白银之手的忠诚，之后才引领他们探求圣光更高深的奥秘。",al={"蒂萨为什么在铁炉堡","蒂萨·热炉在此的原因","蒂萨为什么在这里"}},["90c1fa9e"]={q="蒂萨·热炉为什么受到矮人的敬重？",a="蒂萨是铁炉堡最受尊敬的圣骑士之一。联盟各地身经百战的老兵，从暴风城的格雷森·沙东布瑞克公爵到当地的圣骑士训练师，都十分推崇她的智慧，完全信任她在考验新兵品德时的判断。",al={"蒂萨·热炉的声望","蒂萨·热炉出名吗","蒂萨受人敬重"}}},fp="16,206,25.451.0,22.429.1,24.170.0,34.109.0,51.167.0,57.228.0,45.150.0,45.180.0"}
P.entries["npc:tommy-joe-stonefield"] = {n="托米·乔·斯通菲尔德",s="在斯通菲尔德农场西边的河畔，托米·乔·斯通菲尔德思念着梅贝尔·马科伦。两家积怨多年，他只能靠秘密传递的字条和僻静的河岸，守住这段隐秘的恋情。",h="在斯通菲尔德农场西边的河畔，托米·乔·斯通菲尔德思念着梅贝尔·马科伦。两家积怨多年，他只能靠秘密传递的字条和僻静的河岸，守住这段隐秘的恋情。",kw={"艾尔文森林","米莱德·斯通菲尔德","梅贝尔·马科伦","斯通菲尔德农场","托米·乔·斯通菲尔德","年轻恋人"},ang={["faction:Alliance"]="作为一名在艾尔文森林南部冒险的联盟冒险者，托米·乔的秘密恋情或许会让你想起，即使匪患横行、政局动荡，人们平静的日常生活仍在继续。"},sec={{t="世仇下的苦恋",b="托米·乔·斯通菲尔德在斯通菲尔德农场西边的河畔等候，望着河对岸的马科伦家宅。斯通菲尔德家族与马科伦家族家族多年来争执不断，从土地之争、颜面之争，到农家的琐碎纠纷。两家的长辈始终不肯放下仇怨，托米·乔却爱上了梅贝尔·马科伦。两人若是公开见面，就会惹怒双方家人。托米·乔的祖母米莱德·斯通菲尔德同情他们，帮他们暗中传递字条和定情信物。"}},faq={{q="托米·乔·斯通菲尔德是谁？",a="托米·乔·斯通菲尔德是一名年轻的人类，住在艾尔文森林的斯通菲尔德农场。他暗中爱上了梅贝尔·马科伦，而她的家族正是他家的死对头。",al={"托米·乔","托米·乔是谁","斯通菲尔德家的儿子"}},{q="在哪里可以找到托米·乔·斯通菲尔德？",a="托米·乔·斯通菲尔德站在斯通菲尔德农场西边的河岸上，隔水望着梅贝尔居住的马科伦农庄。",al={"托米·乔的位置","托米·乔在哪里","寻找托米·乔"}},{q="斯通菲尔德家族和马科伦家族家族为什么争斗不休？",a="没人说得清这场世仇因何而起。斯通菲尔德家族和马科伦家族家族多年来一直势同水火，谁也不愿让自家的年轻人与对方来往。",al={"家族世仇","他们为何相互仇恨","斯通菲尔德与马科伦的世仇"}},{q="谁在帮助托米·乔和梅贝尔见面？",a="米莱德·斯通菲尔德知道两人情投意合，便帮助他们秘密交往。她托旅人为托米·乔和梅贝尔悄悄传递消息。",al={"米莱德·斯通菲尔德的帮助","帮助秘密相恋的情侣","谁在帮助这对恋人"}}},fx={["3c95bb6e"]={q="托米·乔·斯通菲尔德效忠哪一方？",a="他属于斯通菲尔德家族，却无心参与家族间的深仇大恨。虽然他住在斯通菲尔德农场，但他在对亲人的忠诚与对梅贝尔·马科伦的爱之间左右为难，因为她来自他们的世仇家族。",al={"托米·乔效忠对象","托米·乔属于哪个家族","斯通菲尔德还是马科伦"}},["8a9aad66"]={q="托米·乔·斯通菲尔德想要什么？",a="托米·乔唯一的心愿，就是与梅贝尔·马科伦相守。斯通菲尔德家族与马科伦家族由来已久的仇恨让他们无法团聚，因此他渴望找到与她秘密相会的办法，让两人的爱情在世仇之下延续。",al={"托米·乔想要什么","托米·乔的目标","托米·乔的心愿"}},["96565570"]={q="托米·乔·斯通菲尔德为什么在这里？",a="托米·乔在自家农场附近的河岸边静静等待。这里隐蔽僻静，远离窥探的目光，他可以暂时摆脱农活，盼望有机会避开争斗不休的亲人，与梅贝尔幽会。",al={"托米·乔为什么在河边","托米·乔在这里做什么","托米·乔·斯通菲尔德在此的原因"}},b663afb0={q="托米·乔·斯通菲尔德与谁有关联？",a="他是斯通菲尔德家族的一员，祖母米莱德·斯通菲尔德时常指点他，也积极帮助他。不过，他最重要的牵挂是梅贝尔·马科伦，她是家族死敌的女儿，也是他深爱的人。",al={"托米·乔的人物关系","托米·乔的家族","托米·乔与谁有亲属关系"}}},fp="20,201,19.473.0,28.171.0,38.144.0,46.174.0,37.153.0"}
P.entries["npc:tonga-runetotem"] = {n="图加·符文图腾",s="在十字路口，图加·符文图腾注视着贫瘠之地的绿洲日渐染病。这位从雷霆崖派来的牛头人德鲁伊研究着危害当地野生生物的腐化，力求在脆弱的生态崩溃之前找到源头。",h="在十字路口，图加·符文图腾注视着贫瘠之地的绿洲日渐染病。这位从雷霆崖派来的牛头人德鲁伊研究着危害当地野生生物的腐化，力求在脆弱的生态崩溃之前找到源头。",kw={"贫瘠之地","十字路口","德鲁伊","遗忘之池","绿洲","符文图腾","死水绿洲","图加","哀嚎洞穴"},ang={["class:Druid"]="身为正在研习技艺的牛头人德鲁伊，你可以看到，即使远离月光林地，塞纳里奥的教诲也能帮助查明大地枯败的原因，并将其净化。",["faction:Horde"]="身为部落的一员，你需要依靠图加的研究，帮助贫瘠之地的主干道沿线维持适宜生存的环境，免受地下魔法威胁的侵扰。",["race:Tauren"]="身为牛头人，你与图加同样肩负着对Earth Mother的责任，他正努力保护那些稀缺的水源，干燥平原上的生命全靠它们维系。"},sec={{t="十字路口的守望者",b="在十字路口，图加·符文图腾研究着贫瘠之地不断变化的土地。雷霆崖的长者们派他从莫高雷来到这里，他对这片干燥的草原十分熟悉。旅人眼中只有灌木和捕食者，图加却在观察大地是否安康的迹象。近来，这些迹象变得令人不安。他在寻找能协助调查各处绿洲的旅人，这些绿洲是整片草原的生命之源。"},{t="污水与畸变的野兽",b="贫瘠之地水源稀缺，而遗忘之池和死水绿洲已变得极不稳定。奇异的魔法蒸汽不断冒出，饮用池水的生物也逐渐变得凶暴，形态怪异。图加收集植物和生物样本，以查明这种病变源于自然腐败，还是外来力量。他的发现指向地下深处的裂隙，将遭到污染的水池与哀嚎洞穴的通道联系起来。"},{t="符文图腾的传承",b="图加承袭了符文图腾氏族之名，以及大德鲁伊哈缪尔·符文图腾所倡导的德鲁伊传承。哈缪尔与塞纳里奥议会保持联系，在月光林地的神圣林地中研习，而像图加这样的斥候则在边疆效力。图加运用月光林地的植物学知识，配制疗伤药膏和解毒药剂。他的工作让牛头人新兴的德鲁伊传统在初建的部落中发挥作用。"}},faq={{q="图加·符文图腾是谁？",a="图加·符文图腾是一位牛头人德鲁伊，就在贫瘠之地十字路口的旅店附近。雷霆崖的长者们派他调查正在草原上蔓延的奇异腐化。",al={"图加·符文图腾","图加是谁","十字路口德鲁伊"}},{q="图加在贫瘠之地调查什么？",a="图加调查贫瘠之地各处绿洲中的奇异蒸汽、变异野兽和受污染的水源，其中包括遗忘之池和死水绿洲。",al={"图加在做什么","图加任务目标","为何调查绿洲"}},{q="图加认为腐化来自哪里？",a="通过研究发生异变的生物和水中的裂隙，图加认为这种魔法污染来自哀嚎洞穴的地下深处。",al={"绿洲腐化源头","污染来自哪里","哀嚎洞穴的关联"}},{q="图加与哈缪尔·符文图腾有亲属关系吗？",a="图加和哈缪尔·符文图腾都以符文图腾为姓，但两人是否有亲属关系尚不清楚。图加将贫瘠之地的困境通报给大德鲁伊哈缪尔，这位德鲁伊长者就在雷霆崖的长者高地。",al={"他与哈缪尔有亲属关系吗","符文图腾家族","与哈缪尔的关系"}},{q="图加如何救治中毒的野生动物？",a="图加运用月光林地传授的知识和当地材料，为中毒的瞪羚配制药膏，并解去来自鬼雾峰等地的毒素。",al={"瞪羚的解药","图加救治病兽","鬼雾峰毒素"}},{q="图加为何驻守十字路口，而不是陶拉祖营地或雷霆崖？",a="十字路口是贫瘠之地北部的交通枢纽，靠近受影响的绿洲。在那里，图加能找到愿意为他深入险地的旅人。",al={"为何选择十字路口","图加为何在这里"}}},fp="15,222,25.372.0,32.447.1,21.409.0,23.174.0,43.146.0,55.144.1,37.203.0,45.150.0,82.172.0"}
P.entries["npc:tormus-deepforge"] = {n="托姆斯·深炉",s="在铁炉堡的大锻炉，托姆斯·深炉源源不断地为联盟供应武器。他为年轻的战士锻造武器，并悼念着自己的导师斯塔基·铁环。",h="在铁炉堡的大锻炉，托姆斯·深炉源源不断地为联盟供应武器。他为年轻的战士锻造武器，并悼念着自己的导师斯塔基·铁环。",kw={"铁匠","深炉","矮人","大锻炉","铁炉堡","洛钦弗","托姆斯"},ang={["profession:Blacksmithing"]="在Great Forge，托姆斯将原材料铁条变成供前线使用的武器。",["race:Dwarf"]="身为矮人，你能从托姆斯的工作中看到，当Grand Alliance的盟友求援时，铁炉堡已准备好熔炼金属并运送军备。"},sec={{t="大锻炉的大师",b="在大锻炉的炉火旁，托姆斯·深炉负责监督铜须氏族的金属锻造。他依然亲自锤炼钢铁，同时也悼念着自己的导师斯塔基·铁环。黑铁矮人攻占了斯塔基的锻造营地，那里位于丹莫罗东部的盔枕湖以南。此前，一批奇异的暗影矿石运抵了那里。"}},faq={{q="在哪里可以找到托姆斯·深炉？",a="托姆斯站在铁炉堡中心熔岩池周围的环形步道上。",al={"托姆斯位置","托姆斯在哪","托姆斯·深炉地图"}},{q="托姆斯在联盟的战争中承担什么职责？",a="在大锻炉，托姆斯为前来找他的年轻战士锻造武器。他请他们进入丹莫罗的铁环挖掘场，为他的导师斯塔基·铁环复仇，并取回黑铁矮人为之杀人的暗影矿石。托姆斯将这些矿石锻造成新的灰铁武器。",al={"托姆斯做什么","托姆斯的作用","为什么找托姆斯交谈"}},{q="其他深炉成员是谁？",a="有几位矮人都姓深炉，包括本古斯、莫高特和凯塔·深炉，以及托姆斯在洛克莫丹的同僚索瓦尔德。他们之间的亲属关系从未得到证实。",al={"深炉氏族","深炉家族","托姆斯和莫高特有亲属关系吗"}}},fx={["7c43f5fd"]={q="托姆斯·深炉是谁？",a="托姆斯·深炉是一位矮人锻造大师，在铁炉堡的大锻炉工作。他以锻造钢铁的精湛技艺闻名，在制作装备和管理军备运输方面发挥着关键作用，为东部王国各地的盟军提供支援。",al={"托姆斯是谁","托姆斯·深炉的故事","深炉是谁"}},["43326af9"]={q="托姆斯·深炉效忠于哪一方？",a="托姆斯对国王麦格尼·铜须和联盟忠心耿耿。他驻守在矮人都城的中心，以自己的技艺确保联盟士兵和偏远哨站获得抵御敌人所需的武器与补给。",al={"托姆斯·深炉阵营","托姆斯为谁效力","托姆斯是联盟吗"}},["6189f272"]={q="托姆斯·深炉想要什么？",a="托姆斯希望锻造精良的武器，并为导师斯塔基·铁环报仇。一批奇异的幽暗矿石运抵丹莫罗的铁环营地后，黑铁矮人屠杀了那里所有的人，托姆斯请冒险者反击他们，并把那些矿石带给他，以便研究其特性。",al={"托姆斯想要什么","托姆斯的目标","托姆斯·深炉的任务"}},["14a6c7e2"]={q="托姆斯·深炉为什么在铁炉堡？",a="他在卡兹莫丹的工业中心大锻炉从事锻造。在那里，他与铁炉堡最优秀的铸甲师和武器锻造师并肩工作，运用巨大的炉火与铁砧，为王国的军事行动锻造重型兵器。",al={"托姆斯为什么在铁炉堡","托姆斯为什么在这里","大锻炉的托姆斯"}}},fp="16,162,25.322.0,34.85.0,54.290.0,29.191.0"}
P.entries["npc:torwa-pathfinder"] = {n="托尔瓦·寻路者",s="托尔瓦·寻路者是一位独行的牛头人猎手和追踪者，在安戈洛环形山入口扎营，就在从塔纳利斯向下延伸的坡道下方。他观察盆地中的原始野生动物，研究那些统治丛林地面的危险掠食者。想要挑战环形山中的传奇野兽、检验自身实力的冒险者，常常向他寻求指引。",h="托尔瓦·寻路者是一位独行的牛头人猎手和追踪者，在安戈洛环形山入口扎营，就在从塔纳利斯向下延伸的坡道下方。他观察盆地中的原始野生动物，研究那些统治丛林地面的危险掠食者。想要挑战环形山中的传奇野兽、检验自身实力的冒险者，常常...",kw={"血瓣","拉克维","寻路者","迅猛龙","塔纳利斯","托尔瓦","尤尔查","安戈洛"},ang={["class:Hunter"]="托尔瓦展现出追踪大师的耐心与技巧，表明要诱出顶级掠食者，需要了解它的食性、气味和领地习性，而非单凭蛮力。",["race:Tauren"]="对于四处游历的牛头人而言，在环形山边缘遇见托尔瓦，会令人安心地想起，即使身处安戈洛这片史前荒野的混乱之中，他们的族人依然敬畏着自然。"},sec={{t="入口的守望者",b="在环形山东侧底部，塔纳利斯的沙地与丛林湿热的水汽交汇之处，托尔瓦·寻路者为初来乍到的人们充当着一位非正式的守望者。他敬畏安戈洛的荒野之力，深知粗心的旅人很快就会沦为当地野兽的食物。他的营地让旅人在深入闷热的丛林之前，得以享受片刻难得的喘息。"},{t="猎杀拉克维",b="托尔瓦将大部分注意力都放在拉克维身上，这只迅猛龙以狡猾凶猛著称，在环形山北部游荡。托尔瓦明白，单凭蛮力无法击败这样的顶级掠食者。因此，他指导猎手研究它的进食习性，用新鲜的尸肉和腺体制作气味足够浓烈的诱饵，将这头野兽引到开阔地带。"},{t="原始毒素与野兽",b="除了猎杀环形山中的顶级迅猛龙，托尔瓦还对盆地里的有毒植物和凶暴的猿群怀有浓厚的好奇心。他指引旅人从躁动的血瓣花身上采集毒液，并观察强壮的大猩猩尤尔查等称霸一方的野兽有多强大，不断分析大自然最致命的适应方式如何在与世隔绝的环境中发挥作用。"}},faq={{q="在哪里可以找到托尔瓦·寻路者？",a="托尔瓦在安戈洛环形山东侧边缘附近扎营，就在通往塔纳利斯沙漠的蜿蜒坡道底部。",al={"托尔瓦位置","托尔瓦在哪","寻找托尔瓦·寻路者"}},{q="拉克维是什么？",a="拉克维是一只出没于安戈洛环形山的传奇迅猛龙，行踪难觅。它以凶猛和狡猾著称，很难用常规手段追踪，必须用特制的诱饵将它引出来。",al={"拉克维","拉克维是谁","拉克维是什么"}},{q="托尔瓦只向部落玩家提供任务吗？",a="不是。尽管身为牛头人，托尔瓦·寻路者在荒野中独立行事。他向联盟和部落中有能力的冒险者传授追踪之道，并提供狩猎挑战。",al={"托尔瓦是否仅限部落","联盟能否与托尔瓦交谈","托尔瓦阵营"}},{q="托尔瓦为什么对血瓣花感兴趣？",a="托尔瓦对安戈洛本土植物的致命防御手段十分着迷。他请冒险者采集凶暴的血瓣花的分泌物，以了解并测试其天然毒素的效力。",al={"血瓣花任务","为什么研究血瓣花","托尔瓦毒素"}},{q="尤尔查是谁？",a="尤尔查是一只格外强大的大猩猩，栖息在安戈洛的洞穴和猿群领地中。托尔瓦要求猎手击败尤尔查，以证明自己有实力对抗盆地中最强大的野兽。",al={"强大的尤尔查","安戈洛大猩猩首领","尤尔查任务"}}},fp="16,295,24.291.0,22.297.0,25.302.0,34.105.0,18.167.0,46.129.0,39.193.0,13.175.0"}
P.entries["npc:treshala-fallowbrook"] = {n="塔莎拉·静水",s="在达纳苏斯，塔莎拉·静水在家中等待丈夫的消息。赫尔拉斯·静水远行去了贫瘠之地的剃刀沼泽。",h="在达纳苏斯，塔莎拉·静水在家中等待丈夫的消息。赫尔拉斯·静水远行去了贫瘠之地的剃刀沼泽。",kw={"达纳苏斯","静水","生命消逝","暗夜精灵","剃刀沼泽","贸易区","塔莎拉"},ang={["faction:Alliance"]="作为联盟的勇士，你或许会在远征贫瘠之地深处的野猪人荆棘巢穴后，返回达纳苏斯。塔莎拉就在那里。",["race:NightElf"]="身为暗夜精灵，塔莎拉静静守候丈夫的身影令人想起，自海加尔山之战以来，她的族人已不再拥有无尽的岁月去等待。"},sec={{t="贸易区的守望者",b="在贸易区一间工坊的二楼，塔莎拉·静水等待着丈夫的消息。赫尔拉斯前往了贫瘠之地的剃刀沼泽，那里荆棘丛生，环绕着野猪人的巢穴。一枚结合坠饰见证着他们的婚姻，赫尔拉斯将它带在身边。"}},faq={{q="在哪里可以找到塔莎拉·静水？",a="塔莎拉·静水在达纳苏斯贸易区一间工坊的二楼。沿着武器店内的木坡道上楼，就能到她的房间。",al={"塔莎拉位置","静水在哪里","如何找到塔莎拉"}},{q="塔莎拉在研究什么？",a="塔莎拉并非研究者。她的丈夫赫尔拉斯·静水去了剃刀沼泽，她在达纳苏斯等待他的消息，以及他带去那里的结缔坠饰的下落。",al={"塔莎拉任务","临终遗言背景故事","塔莎拉想要什么"}},{q="她为什么牵挂着剃刀沼泽？",a="塔莎拉牵挂着剃刀沼泽，是因为她的丈夫赫尔拉斯冒险进入了这座位于贫瘠之地、荆棘密布的野猪人要塞，此后便音信全无。",al={"为什么是剃刀沼泽","静水 剃刀","与剃刀沼泽的联系"}},{q="她是店主还是工匠？",a="塔莎拉既不是商人，也不是工匠。她住在贸易区工匠摊位的楼上。",al={"塔莎拉是商人吗","她卖什么"}}},fp="20,149,24.296.0,38.165.0,29.176.0,41.156.0,37.117.0"}
P.entries["npc:tsunaman"] = {n="苏纳曼",s="苏纳曼在烈日石居监视卡利姆多的水流，寻找动荡的迹象。他与部落合作，对抗威胁水域的势力。",h="苏纳曼在烈日石居监视卡利姆多的水流，寻找动荡的迹象。他与部落合作，对抗威胁水域的势力。",kw={"焦炭谷","耐普图隆","石爪山","烈日石居","海潮议会","深渊中的麻烦","苏纳曼","水元素"},ang={["class:Shaman"]="作为一名寻求理解元素并与之沟通的萨满祭司，你可以通过苏纳曼，直接与猎潮者宫廷的使者交谈。",["faction:Horde"]="作为部落的一员，你可以在烈日石居与苏纳曼合作，应对卡利姆多水域中的元素失衡和教徒入侵。"},sec={{t="潮汐的使者",b="在从烈日石居通往焦炭谷的小径附近，苏纳曼为海潮议会效力，其成员是效忠于猎潮者耐普图隆的高阶仆从。他与部落合作，监视卡利姆多各地的元素动荡，尤其关注从黑暗深渊的水下洞穴蔓延而出的骚乱。"},{t="对火焰的憎恨",b="苏纳曼憎恨一切形式的火焰。焦炭谷燃烧的大地和火元素的入侵让他怒火难平。在营地周围，他有时会大步走向附近的炊火和篝火，用沉重的水之拳将它们扑灭。"}},faq={{q="苏纳曼是谁？",a="苏纳曼是石爪山脉烈日石居的一名水元素。他为海潮议会效力，监视卡利姆多的元素冲突，并寻求援助，以平息异常的动荡。",al={"苏纳曼是谁","苏纳曼背景故事","苏纳曼是什么"}},{q="苏纳曼为什么攻击篝火？",a="苏纳曼厌恶火元素，也厌恶火焰本身。在烈日石居，他有时会迈着沉重的步伐走向旅人的篝火，用水流猛击，将其熄灭。",al={"苏纳曼拳击火焰","苏纳曼为什么击打火焰","水元素篝火"}},{q="海潮议会是什么？",a="海潮议会是由强大的元素副官组成的组织，效忠于水元素领主猎潮者耐普图隆。他们监管水域，并应对世界各处水域中的动荡。",al={"海潮议会","苏纳曼为谁效力"}},{q="苏纳曼为什么关注黑暗深渊？",a="黑暗深渊遭到了暮光教徒和黑暗势力的污染，当地的水之灵也受到了腐化。苏纳曼招募部落冒险者进入沉没的神庙，平息水中的混乱。",al={"苏纳曼黑暗深渊","深渊中的麻烦"}}},fp="8,145,18.321.0,15.245.0,16.204.0,38.166.0,34.226.0,48.208.0"}
P.entries["npc:turak-runetotem"] = {n="图拉克·符文图腾",s="在雷霆崖，图拉克·符文图腾引导年轻的牛头人亲近自然，追寻平衡。他在长者高地的长者大厅协助大德鲁伊哈缪尔·符文图腾，并引领学徒经历试炼，与灵魂沟通，掌握动物形态。",h="在雷霆崖，图拉克·符文图腾引导年轻的牛头人亲近自然，追寻平衡。他在长者高地的长者大厅协助大德鲁伊哈缪尔·符文图腾，并引领学徒经历试炼，与灵魂沟通，掌握动物形态。",kw={"水栖形态","熊形态","德迪利特·星焰","德鲁伊","长者高地","长者大厅","哈缪尔","月爪枭兽","月光林地","符文图腾","雷霆崖","图拉克"},ang={["class:Druid"]="作为牛头人德鲁伊，你可以向图拉克·符文图腾求教。他传授前往月光林地的方法，并考验寻求熊形态和水栖形态的学徒。",["faction:Horde"]="作为部落的一员，你可以向图拉克·符文图腾寻求指引。他训练自然的守护者，应对枯萎、环境腐化，以及卡利姆多各地尚未愈合的创伤。",["race:Tauren"]="作为牛头人，你也参与了第三次战争后德鲁伊习俗的复兴。图拉克·符文图腾帮助你的族人重拾与Earthmother之间古老的和谐。"},sec={{t="大地母亲之声",b="在雷霆崖长者高地顶端的长者大厅，图拉克·符文图腾引导着寻求德鲁伊之道的人。他协助大德鲁伊哈缪尔·符文图腾，让古老的德鲁伊技艺在牛头人中复兴。图拉克教导学徒，德鲁伊应当尊崇大地母亲的意志。强健的体魄必须以心怀敬畏、与自然和谐共处为根基。"},{t="利爪之路",b="当初出茅庐的德鲁伊准备好学习动物形态时，图拉克便派他们前往更广阔的世界。他教导他们加入塞纳里奥议会，并通过传送跨越卡利姆多，前往月光林地。图拉克记得，自己初次与巨熊之灵沟通时，既困惑不已，又深受震撼。为了考验学生的勇气，他派他们去面对月爪枭兽，赢得踏上利爪之道所需的体魄与心志。"},{t="平衡的守护者",b="图拉克传授的不只是用于战斗的原始形态。他派弟子前往德迪利特·星焰那里研习毒素，而德迪利特则派他们去帮助十字路口附近中毒的动物。接连发生的中毒事件，连图拉克也感到惊讶。\n\n图拉克还引领学徒在潮水之下经历艰苦的仪式，唤醒他们的水栖形态。这些试炼将他们塑造成守护者，使他们能够治愈艾泽拉斯最深的创伤。"}},faq={{q="在哪里可以找到图拉克·符文图腾？",a="图拉克·符文图腾位于雷霆崖长者高地的长者大厅，就在大德鲁伊哈缪尔·符文图腾身旁。",al={"图拉克位置","图拉克·符文图腾在哪里","图拉克·符文图腾 雷霆崖"}},{q="图拉克对新晋德鲁伊有何作用？",a="图拉克教导年轻的牛头人德鲁伊如何前往月光林地，并引领他们通过获取熊形态和水栖形态的试炼。他还教导他们解除自然毒素。",al={"图拉克教什么","图拉克德鲁伊训练师","图拉克的职责"}},{q="图拉克与月光林地有何联系？",a="图拉克教导德鲁伊学徒传送到月光林地。在那里，德迪利特·星焰通过塞纳里奥议会提供更深入的精神指引。",al={"图拉克 月光林地","图拉克如何认识德迪利特","传送月光林地 图拉克"}},{q="图拉克与大德鲁伊哈缪尔·符文图腾是什么关系？",a="图拉克属于符文图腾部族，在长者大厅担任大德鲁伊哈缪尔·符文图腾信赖的助手和教师。",al={"图拉克与哈缪尔有亲属关系吗","哈缪尔与图拉克"}},{q="图拉克为何派德鲁伊前往十字路口？",a="图拉克派学生前往月光林地的德迪利特·星焰那里研习毒素。德迪利特派他们去协助处理十字路口附近的动物中毒事件。他们归来后，图拉克便授予他们永久掌握解毒之术的力量。",al={"图拉克 十字路口","图拉克毒素任务","解毒之术"}},{q="图拉克与巨熊之灵沟通时有过怎样的亲身经历？",a="图拉克回忆，在成为利爪德鲁伊的道路上，自己初次与巨熊之灵沟通时，既困惑不已，又深受震撼。这段经历加深了他对这一形态的敬畏。",al={"图拉克熊之灵","图拉克 利爪之路"}}},fx={fcca94f0={q="图拉克·符文图腾是谁？",a="图拉克·符文图腾是一位睿智而耐心的牛头人德鲁伊训练师，居住在雷霆崖长者高地的长者大厅。他是大德鲁伊哈缪尔·符文图腾值得信赖的助手，在自然的怀抱中保持着深厚的平衡。图拉克致力于引导年轻的部落德鲁伊完成最初的试炼，帮助他们与荒野之灵建立共鸣，并掌握塞纳里奥议会的古老教义。",al={"图拉克是谁","图拉克·符文图腾的背景","图拉克的身份"}},d36f6346={q="图拉克·符文图腾效忠哪一方？",a="图拉克既忠于部落中的雷霆崖牛头人，也忠于塞纳里奥议会。他代表着牛头人与暗夜精灵之间日益紧密的德鲁伊纽带，在部落的传统忠诚与治愈并守护艾泽拉斯自然平衡的神圣、中立职责之间搭起桥梁。",al={"图拉克的阵营","图拉克侍奉谁","图拉克的忠诚对象"}},b696f0bb={q="图拉克·符文图腾想要什么？",a="图拉克希望培育新一代牛头人德鲁伊，并守护大地免遭腐化。他希望新晋学徒理解自然之力的真正本质，敦促他们与巨熊等灵魂沟通，克服身心的考验，并运用自身天赋净化毒素，让卡利姆多重归和谐。",al={"图拉克的目标","图拉克的职责是什么","图拉克的动机"}},["83600788"]={q="图拉克·符文图腾为什么在这里？",a="图拉克驻守在长者高地的长者大厅，与大德鲁伊哈缪尔·符文图腾并肩效力。哈缪尔负责监督所有牛头人的德鲁伊沟通仪式，图拉克则在高耸的崖地担任他的主要导师，亲自指导初学德鲁伊，再送他们前往月光林地，并承担起在贫瘠之地各处更广泛的职责。",al={"图拉克为何在雷霆崖","图拉克为何在长者高地","图拉克在雷霆崖的职责"}}},fp="15,239,24.347.0,20.423.0,20.421.0,33.112.0,41.163.0,40.143.0,51.132.0,45.218.0,64.203.0"}
P.entries["npc:twilight-lord-kelris"] = {n="梦游者克尔里斯",s="在黑暗深渊，梦游者克尔里斯从沉没的废墟中统领着暮光之锤。这名兽人术士在教派中身居高位，主持Moonshrine Sanctum中的仪式。在那里，他的追随者崇拜阿库麦尔，妄图让宇宙陷入混沌的统治。",h="在黑暗深渊，梦游者克尔里斯从沉没的废墟中统领着暮光之锤。这名兽人术士在教派中身居高位，主持Moonshrine Sanctum中的仪式。在那里，他的追随者崇拜阿库麦尔，妄图让宇宙陷入混沌的统治。",kw={"阿库麦尔","银色黎明","黑暗深渊","克尔里斯","月神圣地","上古之神","暮光领主","暮光之锤"},ang={["class:Warlock"]="寻常术士会与燃烧军团的恶魔交易。克尔里斯展现的暗影魔法则源于屈从上古之神的低语，能够使人陷入恍惚。",["faction:Alliance"]="银色黎明以达纳苏斯为据点，力图终结克尔里斯在卡利姆多北部煽动黑暗教派、散播恐怖而又屡屡逃脱追捕的生涯。",["faction:Horde"]="在长者和萨满祭司眼中，克尔里斯是一个引以为戒的可憎之徒，这个兽人抛弃了元素与先祖之灵，转而向宇宙中古老的恐怖存在卑躬屈膝。",["race:NightElf"]="克尔里斯亵渎的仪式玷污了Moonshrine Sanctum，这座古老的精灵神殿原本供奉着Elune。"},sec={{t="虚空先驱",b="梦游者克尔里斯指挥着占据黑暗深渊沉没废墟的教徒。多年来，他躲过了达纳苏斯警惕的目光，也避开了银色黎明的追捕。每当古老的邪恶在卡利姆多各地蠢动，人们便怀疑克尔里斯是幕后主使。他效忠于上古之神，而非军阀或氏族。他企图摧毁凡人的文明，让艾泽拉斯重归原始的混沌。"},{t="巨兽的看守者",b="在Moonshrine Sanctum，克尔里斯主持教派对阿库麦尔的崇拜。这头凶残的三头蛇颈龙侍奉着一位上古之神。暮光之锤与纳迦结盟，占据了这座淹没在水中的神殿。克尔里斯主持教派的仪式，将无辜者献祭给阿库麦尔，以换取力量。"},{t="黑暗恍惚与沉眠",b="梦游者克尔里斯掌握着强大的暗影魔法，能够控制心智，让入侵者陷入违背自然的深度沉眠。他在一座被腐化的祭坛前不停祈祷，祭坛周围的蜡烛引导着黑暗能量。任何试图将他击杀的人，都必须击败这位教派首领，并面对他的守夜仪式被打断后惊醒的潜藏恐怖。"}},faq={{q="梦游者克尔里斯是谁？",a="梦游者克尔里斯是一名兽人巫师，也是统领黑暗深渊暮光之锤的高阶首领。他指挥着教派在整座沉没神殿中的活动，并忠心侍奉上古之神。",al={"克尔里斯背景故事","克尔里斯是谁","克尔里斯背景"}},{q="银色黎明为何追捕克尔里斯？",a="银色黎明追捕克尔里斯，是因为他行踪诡秘，在卡利姆多各地煽动邪恶。他一度被认为已经死亡或失踪，但人们发现，这片大陆上的诸多黑暗阴谋都有他在幕后操纵，因此将铲除他列为要务。",al={"银色黎明克尔里斯","为何击杀克尔里斯","黑暗深渊作恶原因"}},{q="克尔里斯与三头蛇颈龙阿库麦尔有何关系？",a="克尔里斯和他麾下的暮光之锤教徒崇拜阿库麦尔，这头三头蛇颈龙侍奉着一位上古之神。这头巨兽盘踞在沉没神殿的最深处。",al={"克尔里斯与阿库麦尔","克尔里斯为何喂养阿库麦尔"}},{q="击败克尔里斯后会发生什么？",a="克尔里斯身后有一座祭坛，上面摆着四支仪式蜡烛。点燃它们会解除圣所的防护结界，召来一波又一波阿库麦尔的仆从，并打开通往巨兽巢穴的封闭大门。",al={"克尔里斯蜡烛","克尔里斯的祭坛","月神圣地蜡烛"}},{q="克尔里斯在战斗中使用哪些力量？",a="克尔里斯使用强大的暗影法术、精神控制和魔法沉眠，使敌人丧失行动能力，同时继续他的黑暗仪式。",al={"克尔里斯技能","克尔里斯法术"}},{q="巴珊娜·符文图腾是谁？",a="巴珊娜·符文图腾是克尔里斯的盟友，正在调查黑暗深渊中的腐化。巴珊娜告诫冒险者，克尔里斯痴迷于崇拜上古之神，渴望让世界重归原始的混沌。",al={"巴珊娜·符文图腾克尔里斯","牛头人猎人克尔里斯"}}},fx={e447f79b={q="梦游者克尔里斯效忠哪一方？",a="克尔里斯领导着暮光之锤教派在当地的秘密组织。他既不为部落效力，也不为联盟效力，而是将一生完全奉献给对古神的崇拜与侍奉，并致力于让原始混乱重返艾泽拉斯。",al={"克尔里斯的阵营","克尔里斯侍奉谁","梦游者克尔里斯的效忠对象"}},["710418bf"]={q="梦游者克尔里斯为什么在黑暗深渊？",a="克尔里斯在沉没的废墟中领导暮光之锤。教派成员在那里与古神沟通，并崇拜古神的仆从、九头蛇阿库麦尔。他在月神圣所主持教派仪式，远离窥探的目光。",al={"克尔里斯为何在黑暗深渊","克尔里斯在黑暗深渊的目的","克尔里斯为何来到这里"}},["7c0659ed"]={q="梦游者克尔里斯与谁有关联？",a="除了指挥洞穴中潜伏的暮光之锤教徒，克尔里斯还主持教派对可怖九头蛇阿库麦尔的崇拜。他也与自己崇拜的古神保持联系，在卡利姆多各地执行他们的黑暗计划。",al={"克尔里斯的盟友","克尔里斯与谁共事","克尔里斯的关系网"}}},fp="20,257,18.404.0,19.287.0,23.346.1,28.212.0,38.232.0,44.160.0,38.197.1,38.131.0,25.212.0"}
P.entries["npc:tyrande-whisperwind"] = {n="泰兰德·语风",s="泰兰德·语风在泰达希尔守望着暗夜精灵。她是艾露恩的高阶女祭司，也是族人的最高领袖，曾与玛法里奥·怒风一同引领他们熬过上古之战，以及此后长达一万年的漫长的守望。如今，她统领着艾露恩姐妹会，并指挥哨兵大军保卫卡利姆多。",h="泰兰德·语风在泰达希尔守望着暗夜精灵。她是艾露恩的高阶女祭司，也是族人的最高领袖，曾与玛法里奥·怒风一同引领他们熬过上古之战，以及此后长达一万年的漫长的守望。如今，她统领着艾露恩姐妹会，并指挥哨兵大军保卫卡利姆多。",kw={"达纳苏斯","艾露恩","卡多雷","玛法里奥","女祭司","哨兵","泰达希尔","泰兰德","语风"},ang={["class:Druid"]="身为德鲁伊，你应当知道，当玛法里奥沉睡于翡翠梦境时，泰兰德与塞纳里奥议会密切合作，保护神圣的林地，养护泰达希尔。",["class:Priest"]="身为牧师，你可以将泰兰德视为Elune神恩的鲜活载体。她代表着kaldorei祭司的至高境界，以信仰召唤月光星辰，治愈伤痛。",["faction:Alliance"]="尽管你的族人长期隐居，并坚决捍卫自身的独立，泰兰德仍带领暗夜精灵加入联盟，共同抵御卡利姆多日益加剧的威胁。",["faction:Horde"]="对部落而言，泰兰德是一位强大且绝不妥协的对手。她已命令Sentinels以武力抵抗灰谷各地的资源采集活动。",["race:NightElf"]="身为暗夜精灵，泰兰德是你的最高领袖和高阶女祭司。一万多年来，她始终守望着你的族人，在每一次磨难中捍卫月神之光。"},sec={{t="月亮女神的选民",b="泰兰德出生于古老的卡多雷帝国，与孪生兄弟玛法里奥和伊利丹怒风一同长大。兄弟二人分别踏上了德鲁伊之道与魔法之路，而她成为了艾露恩的女祭司。当燃烧军团在上古之战期间首次入侵艾泽拉斯时，泰兰德与玛法里奥并肩抵抗。月亮女神亲自赐予她恩宠，泰兰德则将姐妹会塑造成了一支战斗力量。当卡多雷面临灭顶之灾时，她麾下的女祭司以神圣的治疗之力和月神的怒火迎战。"},{t="漫长的守望与哨兵",b="大灾变之后，随着永恒之井被封印，玛法里奥和德鲁伊们进入翡翠梦境，开始了漫长的休眠。泰兰德独自承担起守护这片劫后余生的国度的重任。她组建了哨兵，这支由精锐女战士组成的部队在卡利姆多的森林中巡逻了一万年。在漫长的守望期间，她们监视着古老的邪恶力量和残存的恶魔。泰兰德始终坚守着对艾露恩的信仰，而她与玛法里奥每次短暂重聚之间，往往相隔数百年。"},{t="第三次大战与新的家园",b="当燃烧军团在第三次大战期间卷土重来时，泰兰德唤醒了沉睡的德鲁伊，共同应对危机。尽管她不信任初来乍到的兽人和人类，仍协助各方在海加尔山结成了背水一战的联军。暗夜精灵在诺达希尔牺牲了永生之力，以消灭阿克蒙德。如今，海加尔山仍留着那场战斗的伤痕，而玛法里奥又忙于守护翡翠梦境。泰兰德在达纳苏斯宏伟的月神殿中治理着卡多雷，警惕部落的入侵，而她的族人也成为了联盟的一员。"}},faq={{q="泰兰德·语风是谁？",a="泰兰德·语风是艾露恩的高阶女祭司，也是暗夜精灵精神与政务上的最高领袖。一万多年来，她引领族人走过了从上古之战到第三次大战的岁月。如今，她在达纳苏斯的月神殿中领导着卡多雷。",al={"泰兰德是谁","泰兰德·语风背景故事","暗夜精灵领袖"}},{q="泰兰德如今住在哪里？",a="泰兰德居住在达纳苏斯，这座城市坐落于泰达希尔高耸的枝杈之间。她在月神殿的上层圣所主持事务，身边环绕着艾露恩的女祭司和哨兵卫兵。",al={"泰兰德在哪里","泰兰德位置","哪里能找到泰兰德"}},{q="泰兰德与玛法里奥是什么关系？",a="泰兰德与玛法里奥·怒风是终身伴侣，共同引领暗夜精灵文明走过了一万年的岁月。年轻时，玛法里奥和他的孪生兄弟伊利丹都曾追求她。泰兰德选择了玛法里奥，他对平衡与自然的执着，与她对艾露恩的信仰彼此呼应。",al={"泰兰德 玛法里奥","泰兰德结婚了吗","泰兰德与伊利丹"}},{q="艾露恩姐妹会是什么？",a="艾露恩姐妹会是一个古老的暗夜精灵女祭司组织，侍奉着月亮女神。在泰兰德的领导下，其成员既救治伤者、指引心灵，也以勇猛的军事指挥官和战士的身份投身战斗。",al={"艾露恩姐妹会","艾露恩的女祭司","泰兰德 牧师"}},{q="泰兰德在漫长的守望期间发挥了什么作用？",a="在大分裂之后的一万年里，玛法里奥和男性德鲁伊沉睡于翡翠梦境，泰兰德则建立并统领了哨兵。她巡逻于卡利姆多的荒野，猎杀残存的萨特和恶魔，在与世隔绝的岁月中守护族人的安全。",al={"漫长的守望是什么","泰兰德 漫长的守望","哨兵领袖"}},{q="泰兰德为何警惕部落？",a="泰兰德对部落心存戒备，因为兽人在第三次大战期间进入灰谷，砍伐神圣的森林，并在恶魔之血的影响下杀死了半神塞纳留斯。双方曾在海加尔山达成脆弱的停战协议，但部落仍在灰谷持续伐木，使她麾下的哨兵始终保持高度警惕。",al={"泰兰德 部落","泰兰德为何憎恨兽人","暗夜精灵对抗部落"}}},fp="19,338,26.540.0,32.504.0,29.584.0,27.295.0,36.179.0,55.289.0,32.213.0,45.271.0,33.290.0"}
P.entries["npc:tyrion"] = {n="泰里恩",s="泰里恩在暴风要塞内留意宫廷动向，协助秘密行动。这位侏儒与埃林·提亚斯一同搜集情报，帮助挫败针对王国的阴谋。",h="泰里恩在暴风要塞内留意宫廷动向，协助秘密行动。这位侏儒与埃林·提亚斯一同搜集情报，帮助挫败针对王国的阴谋。",kw={"埃林·提亚斯","侏儒","潜入城堡","必备物品","间谍","暴风要塞","伏击","泰里恩"},ang={["class:Rogue"]="作为参与埃林·提亚斯秘密行动的潜行者，你可以倚重泰里恩这位暴风要塞内的盟友。",["faction:Alliance"]="泰里恩的情报工作帮助王室抵御潜藏在王国首都中的威胁。",["race:Gnome"]="作为一名侏儒，泰里恩展现了侏儒在联盟谍报工作中的机敏与才智。他在不引起人类贵族注意的情况下开展工作。"},sec={{t="要塞中的低调身影",b="泰里恩留意着暴风要塞的厅堂，密切关注王宫。他还与不受官方监管的联络人保持联系。"},{t="暗影与谍报",b="埃林·提亚斯是贸易区的一名奶酪商人，他将敏感事务托付给泰里恩。提亚斯经营着一个隐秘的情报网，需要绕过贵族的官僚程序时，他就会派可靠的特工去找泰里恩。"},{t="揭露威胁",b="泰里恩帮助调查者进入城中戒备森严的地方，取得敏感物品。他的工作揭露了潜藏在王国王权核心的危险。他会在有组织的袭击威胁到暴风城的领袖之前，向盟友发出警告。"}},faq={{q="泰里恩是谁？",a="泰里恩是暴风要塞内的一名侏儒特工。他搜集情报，在王室常规渠道之外处理秘密事务。",al={"这个侏儒是谁","泰里恩身份","泰里恩做什么"}},{q="在哪里可以找到泰里恩？",a="泰里恩就在暴风城的暴风要塞内。他留意着那些由他信任的联络人派来的特工。",al={"泰里恩位置","泰里恩在哪里","寻找泰里恩"}},{q="他与埃林·提亚斯有什么关系？",a="泰里恩与埃林·提亚斯是多年的好友，也是合作伙伴。提亚斯通过生意上的人脉搜集传闻，需要在要塞内展开秘密行动时，他就会派可靠的冒险者去找泰里恩。",al={"泰里恩与埃林·提亚斯","泰里恩认识提亚斯吗","提亚斯的关系"}},{q="泰里恩提供哪些任务？",a="泰里恩参与了“潜入城堡”和“必备物品”等秘密行动。他还会在“伏击！”期间向盟友发出警告。",al={"泰里恩任务","他提供哪些任务"}},{q="为什么一名侏儒会在人类宫廷中负责秘密行动？",a="侏儒是联盟的重要盟友。泰里恩凭借敏锐的头脑、潜行本领和灵活运用技术的才智，在人类宫廷中执行秘密任务。",al={"为什么侏儒在暴风要塞","侏儒特工要塞"}},{q="泰里恩正在调查怎样的阴谋？",a="泰里恩追查被盗的情报和王室宫廷内隐藏的阴谋。他的调查最终牵出了一场发生在城内的武装伏击。",al={"泰里恩阴谋","泰里恩在调查什么"}}},fx={f469be85={q="泰里恩效忠于哪一方？",a="泰里恩在暴风要塞内秘密活动，与老友埃林·提亚斯共事，后者既是奶酪商大师，也是盗贼线人。尽管依靠暗影、密语和秘密谍报手段行事，他始终忠于暴风城与联盟的团结，默默保护王国，使其免受潜藏于内部的威胁。",al={"泰里恩忠于暴风城吗","泰里恩阵营","泰里恩为谁效力"}}},fp="6,163,28.138.0,21.230.0,21.227.1,14.131.0,24.112.0,39.201.0,30.149.0,61.143.0,55.125.1"}
P.entries["npc:ukor"] = {n="乌克尔",s="乌克尔从剃刀岭运来补给后，在试炼谷外东边的小路旁歇脚。训练场的物资已经很充足，他希望这些补给仍能帮到自己的同胞。",h="乌克尔从剃刀岭运来补给后，在试炼谷外东边的小路旁歇脚。训练场的物资已经很充足，他希望这些补给仍能帮到自己的同胞。",kw={"苦工的重担","杜隆塔尔","格罗斯克","苦工","剃刀岭","乌克尔","试炼谷"},ang={["faction:Horde"]="对刚刚完成试炼的新兵来说，帮助乌克尔是他们早期参与部落聚落之间日常物资运送的一次机会。",["race:Orc"]="兽人苦工承担着繁重的体力劳动，为新部落的建设出力。乌克尔让人看到，即使是地位卑微的劳工，也想支援杜隆塔尔的战士。"},sec={{t="苦工的差事",b="乌克尔在试炼谷外东边的道路旁歇脚，从剃刀岭向南运送食物让他疲惫不堪。兽人苦工常常整日受严厉的监工驱使，砍伐树木或搬运石块。乌克尔主动决定为新兵送去补给。他穿过杜隆塔尔的红色平原，那里有蝎子和野猪出没，却发现训练场早已备足了物资。他带来的包裹派不上用场。如今，他请路过的年轻冒险者把这些补给送回北边，交给旅店老板格罗斯克。"}},faq={{q="乌克尔是谁？",a="乌克尔在杜隆塔尔南部，从试炼谷向东延伸的道路旁歇脚。他是个热心的兽人苦工。",al={"乌克尔背景故事","乌克尔是谁","乌克尔做什么"}},{q="乌克尔为什么带着一袋食物站在路边？",a="乌克尔从剃刀岭运来口粮，想让在试炼谷受训的年轻战士填饱肚子。他抵达后发现，那里的补给已经很充足，用不上这袋食物。",al={"乌克尔为什么在这里","乌克尔任务缘由","乌克尔食物包裹"}},{q="乌克尔请路过的旅人做什么？",a="乌克尔请向北前往剃刀岭的旅人把包裹送还给旅店老板格罗斯克。他太害怕沿途的野兽，不敢亲自把东西送回去。",al={"乌克尔任务","乌克尔想要什么","苦工的重担任务"}}},fp="4,170,15.488.0,12.112.0,53.194.0,43.164.0"}
P.entries["npc:ula-elek"] = {n="尤拉莱克",s="在森金村，尤拉莱克为部落各地的战士打造护甲。这位黑暗之矛铁匠与索恩格瑞姆·火眼携手，将巨魔的传统工艺与从卡利姆多各地收集的战利品相结合，打造专用装备。",h="在森金村，尤拉莱克为部落各地的战士打造护甲。这位黑暗之矛铁匠与索恩格瑞姆·火眼携手，将巨魔的传统工艺与从卡利姆多各地收集的战利品相结合，打造专用装备。",kw={"野蛮护手","黑暗之矛","杜隆塔尔","萨特蹄子","森金村","铁匠","索恩格瑞姆·火眼","尤拉莱克"},ang={["class:Warrior"]="作为战士，你依靠尤拉莱克来凑齐你的 Brutal 护甲套装，他按照索恩格瑞姆·火眼的指示，将来之不易的萨特蹄子制成坚固的护手。",["profession:Blacksmithing"]="作为铁匠，你能看到部落的铁匠如何走出传统铸造工坊，将野兽和恶魔身上的战利品用于打造战士的护甲。",["race:Troll"]="作为巨魔，你能看到黑暗之矛的铁匠如何在森金村开阔的海岸上锻造前线装备，帮助年轻的部落武装起来。"},sec={{t="黑暗之矛的铁匠",b="尤拉莱克是森金村一位技艺精湛的护甲匠，为黑暗之矛效力。附近的野猪人和海蟹威胁着这处沿海聚落，因此部族需要坚固的护甲和堪用的刀剑。尤拉莱克的手艺也吸引着来自部落各地的老练战士。"},{t="锻造野蛮护甲",b="年轻战士前往贫瘠之地的高处拜访索恩格瑞姆·火眼后，会被派往南方的森金村。这位老兵信任尤拉莱克，让他为身经百战的斗士锻造野蛮护手。为此，尤拉莱克需要稀有的材料，尤其是灰谷东北部那些吸取森林魔力的萨特身上肿胀而未分趾的蹄子。"}},faq={{q="尤拉莱克是谁？",a="尤拉莱克是森金村的一位黑暗之矛巨魔护甲匠。部落的老兵信任他，让他为前途可期的前线战士锻造专用护甲。",al={"尤拉莱克是谁","尤拉莱克的故事","尤拉莱克的背景"}},{q="在哪里可以找到尤拉莱克？",a="尤拉莱克位于森金村，就在杜隆塔尔东南海岸、剃刀岭以南。",al={"尤拉莱克的位置","尤拉莱克在哪里","寻找尤拉莱克"}},{q="索恩格瑞姆·火眼为什么派战士去找尤拉莱克？",a="索恩格瑞姆·火眼派战士去找尤拉莱克，是因为他信任这位巨魔铁匠，让他为赢得自己尊重的战士打造野蛮护手。",al={"索恩格瑞姆 和尤拉莱克","为什么找尤拉莱克"}},{q="尤拉莱克制作护手需要什么材料？",a="尤拉莱克要求战士猎杀灰谷东北部的萨特，收集它们肿胀而未分趾的蹄子，用来制作野蛮护手。",al={"尤拉莱克的材料","野蛮护手 的材料"}},{q="尤拉莱克打造什么装备？",a="尤拉莱克擅长打造重型作战护甲。他制作的野蛮护手是野蛮护甲套装的一部分，供前途可期的部落战士使用。",al={"尤拉莱克制作什么","尤拉莱克的奖励"}},{q="为什么制作护手需要萨特的蹄子？",a="灰谷东北部的萨特吸取森林的魔力，其中最强大的萨特有着肿胀而未分趾的蹄子。尤拉莱克从这些蹄子中提取力量，并将其注入护手。",al={"为什么需要萨特蹄子","制作护手用的蹄子"}}},fp="8,220,22.265.0,24.335.0,16.145.0,28.94.0,54.147.0,56.132.0,38.133.0,42.191.0"}
P.entries["npc:umpi"] = {n="乌比",s="在塔伦米尔，乌比承受着药剂师林度恩的实验。这只青蛙被关在皇家药剂师学会的工坊里，充当毒素和瘟疫药剂的实验对象。",h="在塔伦米尔，乌比承受着药剂师林度恩的实验。这只青蛙被关在皇家药剂师学会的工坊里，充当毒素和瘟疫药剂的实验对象。",kw={"药剂师林度恩","苦楚药剂","受难药剂","青蛙","希尔斯布莱德丘陵","塔伦米尔","乌比"},ang={["race:Undead"]="身为Undead，你亲眼见识了皇家药剂师学会的无情手段：其研究人员将生与死视为变量，借此完善被遗忘者的军备。"},sec={{t="永无止境的试药生涯",b="乌比是塔伦米尔的一只青蛙，承受着药剂师林度恩的实验所带来的代价。对林度恩而言，检验配方需要活生生的血肉，因此他给乌比灌下受难药剂和苦楚药剂等致命药剂。毒药夺去了她的性命，但林度恩又让她复生，好让她为皇家药剂师学会承受下一剂毒药。"}},faq={{q="乌比是谁？",a="乌比是药剂师林度恩养在塔伦米尔的一只青蛙。林度恩让她充当助手，也将她作为炼金实验的主要对象。",al={"乌比是谁","乌比是什么","塔伦米尔青蛙"}},{q="药剂师林度恩为什么反复杀死乌比？",a="药剂师林度恩用乌比来测定新配制毒素的效力。他给她灌下受难药剂等致命药剂，然后让她复生，继续下一次试验。",al={"为什么杀乌比","乌比中毒","林度恩青蛙"}},{q="乌比是活物还是亡灵？",a="乌比每次被毒死后，都会被重新唤起。药剂师林度恩说他让她复生了，不过她仍被视为野兽。",al={"乌比是亡灵吗","乌比僵尸","亡灵青蛙"}},{q="在哪里能找到乌比？",a="乌比在希尔斯布莱德丘陵的塔伦米尔，位于镇内的炼金工坊中。她就在药剂师林度恩的工作台旁。",al={"乌比在哪","乌比位置"}}},fp="4,166,27.315.0,12.139.0,44.176.0,24.131.0,24.126.0"}
P.entries["npc:undertaker-mordo"] = {n="管理员摩尔多",s="在丧钟镇的墓穴旁，管理员摩尔多迎接刚刚苏醒的被遗忘者。他告诉他们，他们已摆脱巫妖王的控制，并指引他们为Sylvanas女王的事业效力。始终没有动静的尸体则被投入火中。",h="在丧钟镇的墓穴旁，管理员摩尔多迎接刚刚苏醒的被遗忘者。他告诉他们，他们已摆脱巫妖王的控制，并指引他们为Sylvanas女王的事业效力。始终没有动静的尸体则被投入火中。",kw={"丧钟镇","粗暴的觉醒","灰影墓穴","提瑞斯法林地","管理员摩尔多"},ang={["race:Undead"]="身为Undead，当你在死亡中睁开双眼时，最先见到的就是管理员摩尔多。他指引你迈出为Sylvanas女王效力的第一步。"},sec={{t="丧钟镇的苏醒",b="管理员摩尔多照看着提瑞斯法林地的墓穴，死尸在这里挣脱天灾军团的控制。刚刚苏醒的被遗忘者在一个已然陌生的世界里遇见了他。他检验他们的神志，告诉他们如今变成了什么，并指引他们为希尔瓦娜斯·风行者女王效力。"},{t="未能苏醒者",b="有些送到墓穴的尸体始终没有醒来。摩尔多很快就会将它们投入火中。对于那些有了动静的，他态度冷淡而不耐烦，也没什么客套。只要他们还保有理智，他就让他们走上台阶，沿路前往礼拜堂，去找暗影牧师萨维斯，由萨维斯解释他们如今的存在。村庄北部泛滥的无脑僵尸是萨维斯的心头之患。他派新近复生者去消灭它们。"}},faq={{q="管理员摩尔多是谁？",a="管理员摩尔多照看着提瑞斯法林地丧钟镇的墓穴。他迎接新近复生的被遗忘者，并指引他们投身效力。",al={"摩尔多是谁","管理员摩尔多的故事","摩尔多 丧钟镇"}},{q="他为什么站在墓地里？",a="管理员摩尔多守在丧钟镇的墓穴旁，刚刚摆脱巫妖王控制的亡灵在这里苏醒。当他们开始有了动静，他便上前迎接。",al={"摩尔多为什么在墓地","摩尔多做什么","摩尔多的职责"}},{q="那些苏醒时失去理智的亡灵会怎样？",a="始终未能苏醒的尸体会被投入火中。暗影牧师萨维斯派新近复生者去消灭丧钟镇北部泛滥的无脑僵尸，即使那些僵尸曾经是他们的兄弟姐妹。",al={"未能获救者","丧钟镇发疯的亡灵","丧钟镇狂野的亡灵"}},{q="摩尔多把新近复生的被遗忘者派往哪里？",a="摩尔多让刚刚苏醒、神志完好的被遗忘者走出墓穴，沿路前往礼拜堂。在那里，暗影牧师萨维斯会解释加入被遗忘者意味着什么。",al={"见过摩尔多后去哪里","摩尔多任务指引","见过摩尔多后的下一步"}}},fp="16,257,27.270.0,21.424.0,24.128.0,34.134.0,60.215.0,43.181.0"}
P.entries["npc:ur-kyo"] = {n="乌尔库",s="在奥格瑞玛的精神谷，乌尔库指引牧师研习暗影与圣光之道。黑暗之矛视他为精神领袖和最伟大的牧师，他在部落的主城传授族人的传统。",h="在奥格瑞玛的精神谷，乌尔库指引牧师研习暗影与圣光之道。黑暗之矛视他为精神领袖和最伟大的牧师，他在部落的主城传授族人的传统。",kw={"黑暗之矛","虚弱妖术","奥格瑞玛","牧师训练师","暗影守卫","乌尔库","精神谷"},ang={["class:Priest"]="作为一名途经杜隆塔尔的部落牧师，你可以向乌尔库学习信仰之道、暗影仪式和神圣的防护法术。",["faction:Horde"]="作为部落的一员，你可以在奥格瑞玛的精神谷找到乌尔库，他在那里教导准备保卫部落的治疗者和暗影施法者。",["race:Troll"]="作为黑暗之矛巨魔，你可以将乌尔库视为你在奥格瑞玛最重要的精神导师。回音群岛失守后，他仍守护着你们部族的巫毒传统和古老的魔法仪式。"},sec={{t="黑暗之矛的精神导师",b="乌尔库在奥格瑞玛的精神谷指引黑暗之矛的秘术师和前来求教的修行者。逃离回音群岛后，黑暗之矛与萨尔领导的部落一同在杜隆塔尔安家。神圣的传统对部族依然至关重要，而乌尔库通过教导，让祖传的习俗得以延续。"},{t="指引与古老仪式",b="前来向乌尔库求教的牧师，会发现他是一位耐心传授信仰与古老仪式的导师。他教授虚弱妖术，以及名为暗影守卫的防护法术。部落牧师也向他求教，了解部落各族不同的信仰之道，从巨魔的巫毒和祖传习俗，到外族的修行法门。"}},faq={{q="乌尔库是谁？",a="乌尔库在奥格瑞玛的精神谷训练牧师。黑暗之矛视他为精神领袖和最伟大的牧师。",al={"乌尔库职责","乌尔库身份","乌尔库是谁"}},{q="在哪里能找到乌尔库？",a="乌尔库位于精神谷，那是奥格瑞玛西侧的巨魔聚居区。到水边的训练小屋寻找他，他与其他精神导师都在那里。",al={"乌尔库位置","乌尔库地图","寻找乌尔库"}},{q="乌尔库教授哪些技能？",a="乌尔库向牧师传授基础的暗影与圣光法术。他还指导黑暗之矛牧师掌握虚弱妖术和暗影守卫。",al={"乌尔库法术","乌尔库技能","巨魔牧师法术"}},{q="乌尔库为何在奥格瑞玛修行，而不在回音群岛？",a="在扎拉赞恩背叛、回音群岛失守后，黑暗之矛与兽人一同在杜隆塔尔重新定居。乌尔库在精神谷传授部族的神秘传统，为部落培养新的守护者。",al={"乌尔库奥格瑞玛故事","乌尔库为何在奥格瑞玛"}},{q="乌尔库与巨魔以外的牧师有往来吗？",a="有。乌尔库教导前来求学的部落牧师，与包括被遗忘者在内的其他部落成员分享黑暗之矛的知识。",al={"亡灵能否向乌尔库学习","乌尔库部落训练师"}},{q="乌尔库在黑暗之矛牧师中担任什么角色？",a="黑暗之矛公认乌尔库是他们最伟大的牧师，也是最重要的精神领袖。他将祖传的习俗、仪式和巫毒法门传授给下一代。",al={"乌尔库地位","部族最伟大的牧师"}}},fp="6,203,33.290.0,26.287.0,14.127.0,24.164.0,33.136.0,65.214.0,44.130.0,50.167.0"}
P.entries["npc:uzzek"] = {n="犹塞克",s="犹塞克在前沿哨所西南方守望着贫瘠之地东部。这位身经百战的兽人曾在卡利姆多各地的多次交战中幸存，如今考验并训练着穿越这片平原、颇具潜力的部落战士。",h="犹塞克在前沿哨所西南方守望着贫瘠之地东部。这位身经百战的兽人曾在卡利姆多各地的多次交战中幸存，如今考验并训练着穿越这片平原、颇具潜力的部落战士。",kw={"贫瘠之地","前沿哨所","防御之道","索恩格瑞姆·火眼","犹塞克","战士训练师"},ang={["class:Warrior"]="作为一名战士，当你离开最初的训练场、踏入更广阔的贫瘠之地时，你将接受犹塞克对毅力和防御技巧的考验。",["faction:Horde"]="作为部落的一员，你会在前沿哨所附近找到犹塞克，他和其他久经沙场的守卫一同守望着杜隆塔尔与荒野草原之间防守薄弱的边界。"},sec={{t="平原老兵",b="犹塞克在前沿哨所西南方、靠近贫瘠之地东部边缘的地方训练年轻战士。他在近来的战争中经历了残酷的战斗，如今考验着那些学习自卫的战士。为了证明自己的本领，他们要面对侵扰这处通道的凶猛野兽和劫掠者。"}},faq={{q="犹塞克是谁？",a="犹塞克是一位经验丰富的兽人战士，驻守在贫瘠之地东部，就在前沿哨所西南方。他指导着志向远大的部落战士，教他们学习防御作战。",al={"犹塞克是谁","犹塞克背景故事","犹塞克非玩家角色"}},{q="在哪里可以找到犹塞克？",a="你可以在前沿哨所西南方的高地一带找到犹塞克，那里俯瞰着从杜隆塔尔通往贫瘠之地的道路。",al={"犹塞克位置","犹塞克在哪里","寻找犹塞克"}},{q="犹塞克对部落战士有何作用？",a="犹塞克通过防御之道等试炼，考验年轻战士的耐力和决心。随后，他会指引他们去拜访索恩格瑞姆·火眼这样的资深大师。",al={"犹塞克战士任务","防御之道 犹塞克"}}},fp="5,185,21.252.0,13.153.0,23.129.0,45.154.0"}
P.entries["npc:valstag-ironjaw"] = {n="瓦斯塔格·铁腭",s="在米奈希尔城堡，瓦斯塔格·铁腭协助守卫洛克莫丹与海岸之间的道路。他向驻军通报威胁旅人与补给的危险。",h="在米奈希尔城堡，瓦斯塔格·铁腭协助守卫洛克莫丹与海岸之间的道路。他向驻军通报威胁旅人与补给的危险。",kw={"丹奥加兹告急","斯托菲队长","洛克莫丹","米奈希尔港","米奈希尔城堡","瓦斯塔格·铁腭","湿地"},ang={["faction:Alliance"]="身为联盟旅人，你的贸易和出行依赖于米奈希尔港与卡兹莫丹群山之间的路线，而瓦斯塔格正协助维持这条路线的畅通。",["race:Dwarf"]="身为从铁炉堡或洛克莫丹前来的矮人，你会在守卫西部海岸的前沿驻军中找到瓦斯塔格。"},sec={{t="城堡中的职责",b="瓦斯塔格·铁腭在米奈希尔港的米奈希尔城堡内服役，是矮人驻军的一员。龙喉氏族兽人和饥饿的野兽威胁着他们的通信与补给。因此，他协助协调主要道路的防务，尤其是穿过丹奥加兹、通往洛克莫丹的险路。"},{t="确保隘道安全",b="敌对势力盘踞在丹奥加兹告急，危及米奈希尔港与洛克莫丹之间的旅人和补给车队。瓦斯塔格派遣有能力的冒险者，前去对付隘道中的强盗和兽人。他还在前线斥候与斯托菲队长等指挥官之间传递军情报告。"}},faq={{q="在哪里可以找到瓦斯塔格·铁腭？",a="你可以在米奈希尔城堡内找到瓦斯塔格·铁腭，那是位于湿地西部米奈希尔港的一座石堡。",al={"瓦斯塔格位置","瓦斯塔格·铁腭在哪里","瓦斯塔格·铁腭非玩家角色"}},{q="瓦斯塔格在湿地担任什么职责？",a="瓦斯塔格·铁腭是驻守城堡的一名铁炉堡矮人。他协助保卫通往矮人腹地的山路。",al={"瓦斯塔格做什么","瓦斯塔格职责"}},{q="为什么通往洛克莫丹的隘道让他如此忧心？",a="丹奥加兹告急将米奈希尔港这座海港与洛克莫丹和铁炉堡连接起来。那里的敌对势力威胁着粮食、部队调动和补给。",al={"为何关注丹奥加兹告急","瓦斯塔格洛克莫丹"}},{q="斯托菲队长是谁？",a="斯托菲队长是米奈希尔城堡的一名高级军官。瓦斯塔格与他协调，确保军情报告和治安公文送达驻军指挥部。",al={"与斯托菲队长的联系","斯托菲是谁"}}},fx={bcb025ae={q="瓦斯塔格·铁腭是谁？",a="瓦斯塔格·铁腭是一名健壮的矮人守卫，驻扎在港口城镇米奈希尔港的米奈希尔城堡中。他为联盟和矮人同胞效力，协助守护连接湿地沿海港口与洛克莫丹高地的危险商路和山间隘口。",al={"瓦斯塔格是谁","瓦斯塔格·铁腭的背景故事","瓦斯塔格·铁腭是谁"}},["3e0052ae"]={q="瓦斯塔格·铁腭属于哪一方？",a="瓦斯塔格忠于铁炉堡和联盟。他是米奈希尔港守军的一员，与斯托菲队长等矮人军方人士协同应对当地的威胁，保护旅人，维持补给线畅通。",al={"瓦斯塔格·铁腭的阵营","瓦斯塔格为谁效力","瓦斯塔格属于联盟吗"}}},fp="15,148,16.286.0,17.302.0,33.113.0,44.125.0,53.150.0,25.156.0"}
P.entries["npc:vanndar-stormpike"] = {n="范达尔·雷矛",s="范达尔·雷矛坐镇丹巴达尔，率领雷矛探险队深入奥特兰克山谷。他在冰封的群峰间寻找古代遗物和原始资源，为联盟与霜狼兽人展开绝不退让的战争。",h="范达尔·雷矛坐镇丹巴达尔，率领雷矛探险队深入奥特兰克山谷。他在冰封的群峰间寻找古代遗物和原始资源，为联盟与霜狼兽人展开绝不退让的战争。",kw={"奥特兰克","丹巴达尔","矮人","霜狼","山丘之王","雷矛","范达尔"},ang={["faction:Alliance"]="身为联盟的一员，你可以将范达尔视为奥特兰克前线的最高指挥官。他坚守北方的城防，将联盟的领土向荒野群山推进。",["race:Dwarf"]="身为铁炉堡的矮人，你可以从范达尔争取古老传承、为Explorer's Guild赢得荣耀的战斗中，看到他不屈的山丘之王精神。"},sec={{t="丹巴达尔之主",b="范达尔·雷矛是铁炉堡身经百战的山丘之王，率领矮人在奥特兰克山谷开展挖掘。第三次大战之后，他带领雷矛卫队开进北方群山，寻找深藏的矿产和失落已久的泰坦神器。他将丹巴达尔建成坚固的基地，宣称这片山谷是祖先的土地，理应归联盟所有。他在那里指挥军事哨站、防御碉堡和前线攻势。范达尔决心绝不让撤退的号角在自己的统领下响起。"},{t="冰封山口之战",b="范达尔的采矿和勘探活动深入霜狼氏族的家园，引发了一场残酷的山地战争。兽人要求他撤离，但他寸步不让，誓言奥特兰克山谷必将属于矮人。在丹巴达尔深处的王座厅内，范达尔在元帅和贴身护卫的陪同下，指挥防御，抵御霜狼的入侵。他还派遣联盟勇士突破敌军防线，夺取山谷。"}},faq={{q="范达尔·雷矛是谁？",a="范达尔·雷矛是一位矮人山丘之王，统领着雷矛探险队。他坐镇丹巴达尔，指挥联盟在奥特兰克山谷的战事。",al={"范达尔是谁","范达尔·雷矛的故事","雷矛领袖"}},{q="范达尔为何在奥特兰克山谷作战？",a="范达尔带领雷矛探险队来到奥特兰克山谷，寻找古代遗物并开采自然资源。他拒绝放弃对这些资源的主张，使矮人与当地的霜狼兽人陷入了血腥冲突。",al={"矮人为何在奥特兰克","范达尔的动机","雷矛的目的"}},{q="范达尔驻守在哪里？",a="范达尔在奥特兰克山谷北部的要塞丹巴达尔指挥部队。矮人的碉堡、元帅和精锐卫兵守护着这座要塞。",al={"范达尔在哪里","范达尔的位置","丹巴达尔首领"}},{q="范达尔的主要敌人是谁？",a="范达尔的主要敌人是德雷克塔尔，他是霜狼氏族的酋长，也是一位年迈的萨满祭司。德雷克塔尔力图将擅自闯入的矮人赶出霜狼世代居住的家园。",al={"范达尔的对手","范达尔与谁作战","霜狼领袖"}}},fp="17,194,18.473.0,23.452.0,25.146.0,42.215.0,24.141.0,28.175.0"}
P.entries["npc:varimathras"] = {n="瓦里玛萨斯",s="在皇家区，瓦里玛萨斯为希尔瓦娜斯·风行者女士出谋划策，并指挥她的军队。这位恐惧魔王在争夺洛丹伦的内战中战败，向女妖之王宣誓效忠，如今在幽暗城担任她的左膀右臂。",h="在皇家区，瓦里玛萨斯为希尔瓦娜斯·风行者女士出谋划策，并指挥她的军队。这位恐惧魔王在争夺洛丹伦的内战中战败，向女妖之王宣誓效忠，如今在幽暗城担任她的左膀右臂。",kw={"巴纳扎尔","德赛洛克","恐惧魔王","纳斯雷兹姆","皇家区","希尔瓦娜斯","幽暗城","瓦里玛萨斯"},ang={["class:Warlock"]="身为术士，你或许会觉得，让一名高阶nathrezim为一位凡人亡灵女王效力，展现了令人叹服又不安的意志。",["faction:Horde"]="身为部落的一员，你发现瓦里玛萨斯驻留幽暗城，令这里与奥格瑞玛之间产生了摩擦。部落花了数十年，才摆脱他所侍奉的恶魔主人的控制。",["race:Undead"]="身为亡灵，你认为瓦里玛萨斯证明了被遗忘者会用压迫者的武器反击压迫者。他已被降服，站在那位将洛丹伦从他掌控中解放出来的黑暗女王身旁。"},sec={{t="巫妖王的看守",b="第三次大战之前，基尔加丹将瓦里玛萨斯和其他恐惧魔王派往艾泽拉斯，看守巫妖王，确保耐奥祖的灵魂为燃烧军团的计划效力。阿克蒙德入侵卡利姆多期间，瓦里玛萨斯与兄弟德赛洛克和巴纳扎尔一同监管洛丹伦的天灾军团。燃烧军团在海加尔山败北，但三位恐惧魔王仍盘踞在首都的废墟中。直到阿尔萨斯王子归来，将他们赶入暗处，他们才得知主人的败讯。"},{t="恶魔的投降",b="随着巫妖王对亡灵军队的控制逐渐减弱，瓦里玛萨斯试图迫使刚刚获得自由的女妖希尔瓦娜斯·风行者为恐惧魔王的新政权效力。Sylvanas拒绝了他，并召集重获自由的亡灵摧毁了他的前哨基地。面临处决的瓦里玛萨斯乞求饶命，并提出用战术机密交换，其中包括他兄弟们的防御工事情报。Sylvanas饶了他一命，将他收归麾下，作为对付他同族的武器。"},{t="兄弟反目",b="攻下首都后，瓦里玛萨斯奉命杀死同为恐惧魔王的巴纳扎尔，以赢得希尔瓦娜斯的信任。他看似服从了命令，但巴纳扎尔在这场骗局中活了下来。随后，瓦里玛萨斯奉希尔瓦娜斯之命，处决了人类军阀大元帅加里瑟斯。如今，他在希尔瓦娜斯的王座旁协调遍及洛丹伦的军事行动，而部落中的许多人对这位恶魔盟友深感不安。"}},faq={{q="为什么恶魔会为被遗忘者效力？",a="在洛丹伦内战期间，希尔瓦娜斯·风行者率领刚刚重获自由的亡灵，击败了瓦里玛萨斯的军队。面临死亡的他乞求宽恕，并献上自己的谋略、军事知识与效忠。希尔瓦娜斯饶了他的性命，让他担任自己的军师和执行者。",al={"瓦里玛萨斯为何在幽暗城","恐惧魔王为何跟随希尔瓦娜斯","瓦里玛萨斯的效忠对象"}},{q="瓦里玛萨斯是什么生物？",a="瓦里玛萨斯是一名纳斯雷兹姆，也就是恐惧魔王。纳斯雷兹姆是为燃烧军团效力的恶魔，聪明而善于操纵他人，惯用精神控制、暗影魔法、瘟疫和离间手段。",al={"瓦里玛萨斯是什么种族","瓦里玛萨斯是吸血鬼吗","瓦里玛萨斯的物种"}},{q="瓦里玛萨斯在幽暗城的什么位置？",a="瓦里玛萨斯站在幽暗城皇家区的高台上，就在希尔瓦娜斯·风行者女士身旁，周围是被遗忘者皇家卫兵。",al={"瓦里玛萨斯在哪里","瓦里玛萨斯的位置","寻找瓦里玛萨斯"}},{q="瓦里玛萨斯和巴纳扎尔之间发生了什么？",a="攻下首都后，希尔瓦娜斯命令瓦里玛萨斯攻击他的兄弟巴纳扎尔，以考验他的忠诚。瓦里玛萨斯遵照她的命令，向同为恐惧魔王的兄弟倒戈相向。",al={"瓦里玛萨斯杀了巴纳扎尔吗","瓦里玛萨斯的兄弟","恐惧魔王的禁忌"}},{q="瓦里玛萨斯在天灾军团的建立过程中扮演了什么角色？",a="基尔加丹将兽人萨满祭司耐奥祖的灵魂禁锢在冰封王座之中，将其化作巫妖王，抛向艾泽拉斯。他派瓦里玛萨斯和其他恐惧魔王看守巫妖王，并监督天灾军团在洛丹伦的行动。",al={"瓦里玛萨斯与耐奥祖","瓦里玛萨斯与巫妖王的起源"}},{q="部落的其他领袖信任瓦里玛萨斯吗？",a="不信任。兽人、巨魔和牛头人因恶魔腐化而留下了深重的创伤，他们眼中的恐惧魔王是操纵他人的怪物。许多被遗忘者也将瓦里玛萨斯视为一件危险而受到严密约束的武器，而非真正的战友。",al={"部落信任瓦里玛萨斯吗","萨尔与瓦里玛萨斯","瓦里玛萨斯受信任吗"}}},fp="11,204,23.490.0,19.434.0,23.425.1,36.276.0,37.179.0,46.146.0,48.176.0,55.230.0,45.227.0"}
P.entries["npc:varok-saurfang"] = {n="Varok Saurfang",s="在奥格瑞玛，瓦罗克·萨鲁法尔 统率着大酋长萨尔麾下的部落大军。这位历经 旧部落 战争的老兵，以自己的力量与经验支持着年轻的部落。",h="在奥格瑞玛，瓦罗克·萨鲁法尔 统率着大酋长萨尔麾下的部落大军。这位历经 旧部落 战争的老兵，以自己的力量与经验支持着年轻的部落。",kw={"库卡隆","督军","萨鲁法尔","萨尔","瓦罗克","战士"},ang={["class:Warrior"]="身为战士，你可以将萨鲁法尔尊为无与伦比的老兵。他的战斧技艺、卓越战术与坚韧意志，体现了理想军人的风范。",["race:Orc"]="身为兽人，你可以将萨鲁法尔大王视为勇武的典范，同时也从他身上看到恶魔之血诅咒给心灵带来的创伤。"},sec={{t="战火中的不朽传奇",b="瓦罗克·萨鲁法尔 身上承载着 旧部落 战争的往昔。在尚在人世的战士中，鲜有人能与他的战绩比肩，许多人都认为他在战场上势不可挡。如今，他在奥格瑞玛担任高阶督军，帮助萨尔维系新生部落的团结。"},{t="血脉的重负",b="瓦罗克·萨鲁法尔 保卫部落，抵御威胁，维护萨尔的统治。他并非为了战斗而战斗。他鄙视穷兵黩武，为荣誉与部落的存续而战。"}},faq={{q="瓦罗克·萨鲁法尔 是谁？",a="瓦罗克·萨鲁法尔 是一位著名的兽人战士，也是部落中效命于大酋长萨尔的首席军事统帅。",al={"瓦罗克·萨鲁法尔 背景故事","萨鲁法尔 是谁","萨鲁法尔大王"}},{q="萨鲁法尔参加过哪些战争？",a="瓦罗克·萨鲁法尔 曾参与 旧部落 对抗联盟的战争。如今，他为萨尔的部落而战。",al={"萨鲁法尔 战争经历","萨鲁法尔 是否参加过 第一次兽人战争","萨鲁法尔 的战斗"}},{q="萨鲁法尔如何看待部落的过去？",a="在恶魔之血诅咒肆虐的年代，瓦罗克·萨鲁法尔 曾为 旧部落 而战。如今，他效忠于萨尔的部落，而这个部落已经背离了那条道路。",al={"萨鲁法尔 血之诅咒","萨鲁法尔 为何悔恨过去"}},{q="萨鲁法尔在如今的部落中担任什么职责？",a="瓦罗克·萨鲁法尔 以高阶督军的身份统率萨尔的军队。他督导军队备战，执行大酋长的命令，并指导年轻的部落战士。",al={"萨鲁法尔 如今的职责","萨鲁法尔 在奥格瑞玛的职责"}}},fp="14,170,27.227.0,23.190.0,22.101.0,32.101.0,40.140.0,45.156.0"}
P.entries["npc:velarok"] = {n="Velarok",s="Velarok Windblade是一名独行的人类剑士，在灼热峡谷的灰烬与余烬间扎营，身旁横陈着黑铁矮人残缺不全的尸体。他誓要向残忍杀害父亲的当地黑铁矮人复仇，并招募过往旅人打造一件复仇武器。他向援手之人提出的每一个要求，都源于那份一心复仇的渴望。",h="Velarok...",kw={"灼热峡谷","瑟银哨塔","惩戒火炬","维拉罗克","维拉罗克·风刃"},ang={["race:Dwarf"]="黑铁矮人是铁炉堡的敌人，陌生人向他们复仇的誓言很容易赢得铜须部族的同情，然而灼热峡谷中滋生的狡诈邪恶，远不止黑铁矮人。",["race:Human"]="Velarok讲述父亲遇害、儿子复仇的故事，正是利用了许多人类所珍视的孝道与正义复仇的理念。"},sec={{t="儿子的复仇",b="在瑟银哨塔东南方，Velarok Windblade自称是一名悲痛的人类战士，被困在灼热峡谷危机四伏的荒野中。他的营地四周，散落着与他交过手的黑铁矮人的尸体，血迹斑斑，伤痕累累。据Velarok所说，这些氏族矮人冷血地杀害了他的父亲。他满怀仇恨，招募旅人收集材料，制作惩戒火炬，用这件附魔武器向黑铁矮人和拉格纳罗斯的爪牙复仇。"},{t="欺诈者的真面目",b="父亲遇害的故事完全是编造的。惩戒火炬组装完毕并注满能量后，人类的幻象便随之破碎，显露出欺诈者维拉罗克的真身——黑龙中一条狡诈的幼龙。维拉罗克操纵凡人削弱黑铁矮人，为龙群的图谋效力，随后觉得这些有用的棋子颇为有趣，便饶了他们一命，留下些微不足道的小饰物交由仆人分发，自己则振翅飞向黑石山。"}},faq={{q="威拉罗克是谁？",a="威拉罗克·温布雷最初以一名满怀复仇之心的人类剑士的形象出现，在灼热峡谷的瑟银哨塔东南方扎营，誓要向黑铁氏族报杀父之仇。",al={"威拉罗克·温布雷是谁","威拉罗克身份","威拉罗克故事"}},{q="为什么威拉罗克周围都是矮人的尸体？",a="营地四周散落着黑铁矮人残缺不全的遗骸，阴森地印证着他所声称的血仇：为了给父亲报仇，他正在与这个氏族厮杀。",al={"残缺的黑铁遗骸","威拉罗克附近的矮人尸体","威拉罗克营地尸体"}},{q="惩戒火炬是什么？",a="这是一把以复仇之名，用从灼热峡谷各处收集的稀有材料组装而成的附魔火炬。威拉罗克让帮手收集各个部件，亲自将其组合并附魔，然后把制成的火炬绑定给帮助过他的人。",al={"威拉罗克火炬任务","惩戒火炬是什么"}},{q="威拉罗克为什么要伪装成人类？",a="伪装成人类让他能够招募联盟和部落的冒险者，而不引起怀疑。黑龙经常化身凡人，操纵他人打击自己的敌人，例如效忠拉格纳罗斯的黑铁矮人。",al={"威拉罗克为什么是人类","为什么欺骗玩家","欺诈者维拉罗克伪装"}},{q="威拉罗克显露真身后去了哪里？",a="显露出欺诈者维拉罗克的巨龙真身后，他便振翅飞向黑石山，回归自己的龙群，留下凡人仆人奖赏那些帮助过他的冒险者。",al={"威拉罗克飞去了哪里","威拉罗克结局","威拉罗克后来怎么样了"}},{q="威拉罗克解除伪装后会发动攻击吗？",a="不会。威拉罗克觉得冒险者在不知情时为他效力既有趣，又令他满意。他没有杀死他们，而是饶过他们的性命，允许他们从他的仆人那里领取一些不起眼的小饰物。",al={"是否要与威拉罗克战斗","威拉罗克会变成敌对吗"}}},fp="7,111,17.330.0,21.414.2,15.176.2,42.105.2,33.262.1,45.203.2,46.181.2,44.137.2"}
P.entries["npc:velora-nitely"] = {n="维罗拉·奈特雷",s="在幽暗城的贸易区，维罗拉·奈特雷为被遗忘者和部落锻造装备。她曾是洛丹伦最出色的护甲锻造师之一，如今却讲起了鲜少逗人发笑的冷笑话。",h="在幽暗城的贸易区，维罗拉·奈特雷为被遗忘者和部落锻造装备。她曾是洛丹伦最出色的护甲锻造师之一，如今却讲起了鲜少逗人发笑的冷笑话。",kw={"护甲锻造师","野蛮腿甲","龙喉胫骨","洛丹伦","索恩格瑞姆·火眼","贸易区","幽暗城","维罗拉·奈特雷"},ang={["class:Warrior"]="身为一名寻求传说中的野蛮护甲的部落战士，你会被指引北上，前往幽暗城寻找维罗拉。她用龙喉氏族兽人的骨头锻造结实的腿甲。",["profession:Blacksmithing"]="身为铁匠，你能从维罗拉精准的金属加工技艺中，看到洛丹伦的护甲锻造传统，即使她成为亡灵已久，这门技艺依然传承着。"},sec={{t="洛丹伦的铁匠",b="维罗拉·奈特雷在幽暗城贸易区的铁砧旁工作，为部落打造护甲。在第三次大战摧残北方之前，她便以卓越的护甲锻造技艺闻名于洛丹伦。亡灵之躯夺去了她的生命与温情，却丝毫没有损伤她的技艺。她与各个大陆的部落工匠合作，其中包括贫瘠之地的索恩格瑞姆·火眼。她既能加固厚重的战斗板甲，也能用龙喉氏族胫骨等坚硬材料锻造出强悍的野蛮腿甲。"},{t="面无表情的幽默",b="维罗拉·奈特雷总想在锻炉旁讲些笑话，尽管她的幽默鲜少奏效。她那些郁郁寡欢的被遗忘者同胞，许多都在为受诅咒的命运而苦恼，她却仍愿意找些乐子。死亡似乎毁掉了她讲笑话的节奏：她的俏皮话平淡而阴森，无论生者还是死者，都觉得毫无趣味。她却毫不气馁，依然讲个不停。"}},faq={{q="维罗拉·奈特雷是谁？",a="维罗拉·奈特雷是一名被遗忘者护甲锻造师，在幽暗城的贸易区工作。生前，她凭借非凡的金属加工技艺闻名于整个洛丹伦。",al={"维罗拉·奈特雷背景故事","维罗拉是谁","维罗拉·奈特雷非玩家角色"}},{q="在哪里可以找到维罗拉·奈特雷？",a="维罗拉·奈特雷在幽暗城贸易区的锻炉和护甲架附近工作。",al={"维罗拉·奈特雷位置","维罗拉·奈特雷在哪里","维罗拉·奈特雷地图"}},{q="她与索恩格瑞姆·火眼有什么联系？",a="维罗拉·奈特雷是一名部落铁匠，协助贫瘠之地的兽人护甲锻造师索恩格瑞姆·火眼。战士若为她带来龙喉氏族胫骨，她便会为其打造野蛮腿甲。",al={"维罗拉与索恩格瑞姆","索恩格瑞姆·火眼护甲","野蛮护甲任务线"}},{q="为什么她的笑话如此乏味？",a="维罗拉·奈特雷喜欢试着逗人发笑，但死亡影响了她讲笑话的方式。自从以亡灵之躯复起，她讲笑话时就显得生硬而面无表情，鲜少能逗人发笑。",al={"维罗拉的幽默感","维罗拉的笑话","维罗拉为什么讲笑话"}}},fp="13,177,20.480.0,13.334.0,21.168.0,33.86.0,45.148.0,25.174.0"}
P.entries["npc:ventaari-brightwish"] = {n="Ventaari Brightwish",s="文塔莉·明愿 是居住在泽风岛森达尔村的一名 翔空者。她迎接来自艾泽拉斯各地的旅行者，并提供任务 天视之赐。",h="文塔莉·明愿 是居住在泽风岛森达尔村的一名 翔空者。她迎接来自艾泽拉斯各地的旅行者，并提供任务 天视之赐。",kw={"明愿","天行","天眼","森达尔村","文塔里","泽风岛"},ang={["race:Skyborne"]="作为森达尔村 Skyborne 的一员，Ventaari Brightwish 帮助访客了解泽风岛的文化与习俗。"},sec={{t="森达尔村的居民",b="文塔莉·明愿 居住在泽风岛高耸悬崖上的森达尔村，是当地的 翔空者 之一。虽然她与 贝拉萨恩·明愿 同姓，但她的职责主要是帮助来到村中的新客，热情接待联盟和部落的访客，并通过 天视之赐 等任务，引导他们了解自己族人的传统。"}},faq={{q="温塔里·明愿 是谁？",a="温塔莉·明愿 是位于泽风岛森达尔村的一名 天裔 非玩家角色。她与访客交谈，并提供任务 天视之赐。",al={"文塔里","文塔里 是谁","文塔里·明愿"}},{q="在哪里可以找到 温塔里·明愿？",a="可以在泽风岛上的森达尔村找到她。",al={"文塔里 位置","文塔里 在哪里","森达尔村 文塔里"}},{q="温塔里 对部落或联盟有敌意吗？",a="没有。温塔里·明愿 保持中立，会与联盟和部落双方的冒险者交谈。",al={"文塔里 阵营","文塔里 是否友善","部落能否与 文塔里 交谈"}}},fp="19,116,28.238.0,27.114.0,37.60.0,45.85.0"}
P.entries["npc:verdan-the-everliving"] = {n="永生者沃尔丹",s="永生者沃尔丹是一头巨大的沼泽兽，潜伏在哀嚎洞穴深处绿意盎然的隧道中。他与堕落的尖牙德鲁伊一同栖身于沉睡的德鲁伊纳拉雷克斯所散播的梦魇之中，凶猛地攻击任何闯入他潮湿洞窟的人。",h="永生者沃尔丹是一头巨大的沼泽兽，潜伏在哀嚎洞穴深处绿意盎然的隧道中。他与堕落的尖牙德鲁伊一同栖身于沉睡的德鲁伊纳拉雷克斯所散播的梦魇之中，凶猛地攻击任何闯入他潮湿洞窟的人。",kw={"沼泽兽","尖牙德鲁伊","元素生物","永生者","纳拉雷克斯","梦魇","沃尔丹","哀嚎洞穴"},ang={["class:Druid"]="沃尔丹的巢穴令人不寒而栗，提醒着人们：当翡翠梦境化为梦魇，洞穴中会滋生出怎样的生物。",["class:Shaman"]="沃尔丹是一个变得扭曲而狂暴的土与水的元素之灵，消灭他，就是在为贫瘠之地失调的元素恢复平衡。",["faction:Horde"]="哀嚎洞穴位于贫瘠之地的腹地，因此，击败沃尔丹这样的危险野兽，对于保护附近的路口和定居点至关重要。"},sec={{t="葱郁深处的巨兽",b="沃尔丹是一头庞大的沼泽兽，是由枝叶、淤泥和泥沼构成的元素生物，潜伏在哀嚎洞穴草木丛生的深处。洞穴遭到腐化之前，他的过往无人知晓；人们只知道，他是那片草木繁茂、积水遍布的洞窟中最庞大、最危险的生物。"},{t="梦魇的扭曲",b="纳拉雷克斯曾试图将干旱的贫瘠之地变成一片葱郁的乐土，但他的仪式出了岔子，在翡翠梦境中化作一场鲜明如真的梦魇。随之而来的腐化渗入地下水，污染了洞穴内所有的生命。在这片遭到侵蚀的洞穴深处，沃尔丹如同一头庞大而凶暴的蛮兽四处游荡，与疯狂的尖牙德鲁伊盘踞在一起。"}},faq={{q="沃尔丹是什么生物？",a="沃尔丹是一头巨大的沼泽兽，是由植物残骸、泥炭和地下泥沼凝聚而成的元素生命。",al={"沃尔丹怪物类型","沃尔丹是什么","沃尔丹种族"}},{q="沃尔丹为什么敌视冒险者？",a="沃尔丹潜伏在哀嚎洞穴被梦魇污染的深处，沉睡中的纳拉雷克斯的梦境让那里的一切都充满了敌意。他将所有外来者都视为入侵者，誓要将其碾碎。",al={"沃尔丹为什么攻击","沃尔丹敌对","沃尔丹邪恶吗"}},{q="沃尔丹与尖牙德鲁伊有什么联系？",a="沃尔丹与疯狂的尖牙德鲁伊一同盘踞在被梦魇污染的洞穴中，同样敌视入侵者，守卫着洞穴更深处的区域。",al={"沃尔丹 尖牙德鲁伊","沃尔丹与尖牙的联系"}},{q="沃尔丹位于哀嚎洞穴的什么地方？",a="沃尔丹栖身于哀嚎洞穴蜿蜒通道深处的一处宽阔洞室中，那里长满了苔藓，沿途要经过数名堕落的尖牙首领。",al={"沃尔丹在哪里","沃尔丹位置","如何找到沃尔丹"}},{q="沃尔丹能被治愈或净化吗？",a="目前没有已知的方法能够净化沃尔丹，冒险者别无选择，只能消灭这头庞大的巨兽，确保能够安全穿过洞穴。",al={"沃尔丹能被拯救吗","拯救沃尔丹","净化沃尔丹"}},{q="沃尔丹为什么被称为“永生者”？",a="这一称号的由来无人知晓。沃尔丹是一头沼泽兽，栖身于哀嚎洞穴草木繁茂的深处。",al={"为什么叫永生者","永生者含义","沃尔丹名字由来"}}},fx={["429fb6d1"]={q="永生者沃尔丹是谁？",a="永生者沃尔丹是一头庞大的沼泽野兽，由植物与泥沼构成的元素生物，潜伏在哀嚎洞穴杂草丛生的深处。他栖居于沉睡的德鲁伊纳拉雷克斯所散播的噩梦之中，会凶猛地攻击任何闯入其领地的生物。",al={"沃尔丹是谁","永生者沃尔丹","沃尔丹是什么"}},["58b439d8"]={q="永生者沃尔丹站在哪一方？",a="沃尔丹不效忠任何阵营。他潜伏在被噩梦污染的深处，与堕落的尖牙德鲁伊为伍，对任何试图打扰洞穴或唤醒纳拉雷克斯的外来者都怀有同样的敌意。",al={"沃尔丹属于哪个阵营","沃尔丹是否与德鲁伊为伍","沃尔丹效忠谁"}},["06330139"]={q="永生者沃尔丹想要什么？",a="沃尔丹没有宏图大志，只会守卫领地并毁灭入侵者。他在洞穴深处永不停歇地巡守，只想粉碎任何胆敢接近巢穴的闯入者。",al={"沃尔丹的目标","沃尔丹想要什么","沃尔丹的动机"}},b1009155={q="永生者沃尔丹为何身在此处？",a="沃尔丹栖居在哀嚎洞穴葱郁而杂草丛生的深处。沉睡的德鲁伊纳拉雷克斯所带来的噩梦已使洞穴变得危机四伏。关于他在受到腐化之前的经历，一无所知。",al={"沃尔丹为何在哀嚎洞穴","沃尔丹如何来到这里","沃尔丹在此处的起源"}},["357d8159"]={q="永生者沃尔丹为何令人畏惧？",a="沃尔丹是哀嚎洞穴中最为凶残的怪物，令人闻风丧胆。他体型庞大，拥有植物般的强悍力量，几秒之内就能重创并击碎一名身披铠甲的战士。",al={"沃尔丹为何令人畏惧","沃尔丹危险吗","沃尔丹有多强"}}},fp="21,166,24.224.0,24.282.1,32.100.0,37.183.0,54.148.0,47.129.0,32.113.0,39.120.0"}
P.entries["npc:verna-furlbrow"] = {n="弗娜·法布隆",s="在西部荒野北部边界附近，弗娜·法布隆守在损坏的马车旁。歹徒将她赶出了家里的南瓜田，而通往艾尔文森林的路又让她困在了半途。",h="在西部荒野北部边界附近，弗娜·法布隆守在损坏的马车旁。歹徒将她赶出了家里的南瓜田，而通往艾尔文森林的路又让她困在了半途。",kw={"损坏的马车","法布隆","贾森农场","老马布兰契","难民","西奥多·法布隆","弗娜·法布隆","杂味炖肉"},ang={["faction:Alliance"]="受困的法布隆一家，让人看到了暴风城疏于照管边境给百姓带来的苦难。普通人被赶出家园，却没有王国士兵被派来保护他们。",["profession:Cooking"]="弗娜创制了杂味炖肉，并教边疆的厨师用搜寻来的肉和野生作物做出丰盛的饭菜。"},sec={{t="接连的不幸",b="弗娜和丈夫原本在西部荒野北部种植南瓜，直到猖獗的匪患迫使他们离开。歹徒占据了农场，于是他们把能带走的东西装上马车，带着自家的马老马布兰契，向艾尔文森林出发。他们的马车刚经过废弃的贾森农场不远就坏了。\n\n断裂的车轴让他们无法继续前行。弗娜要面对风吹雨打、强盗袭击和拾荒者，还得依靠过路的旅人，让一家人有饭吃、有人保护。"},{t="炉火旁的温情",b="弗娜依然欢迎那些被迫流落路旁的人。她因创制杂味炖肉而闻名这一带，也与遭遇相似命运的流浪者和难民分享饭食与温暖的炉火。\n\n她的炖锅需要从野外找来的食材：猪鼻、鱼人眼球、秋葵和秃鹫的筋肉。弗娜用这片严酷边疆所能提供的食材，为穷困潦倒的人做出丰盛的饭菜。"}},faq={{q="弗娜·法布隆为什么在路边扎营？",a="歹徒横行西部荒野北部后，弗娜和丈夫逃离了自家的南瓜农场。他们前往艾尔文森林时，马车在贾森农场附近坏了，让他们困在了路边。",al={"弗娜·法布隆为什么在这里","弗娜·法布隆位置","弗娜出了什么事"}},{q="农夫法布隆和她是什么关系？",a="农夫西奥多·法布隆是弗娜的丈夫。他们曾一起经营西部荒野的家园，直到强盗将他们赶出了自己的土地。",al={"弗娜·法布隆的丈夫","农夫法布隆是她的丈夫吗"}},{q="杂味炖肉是什么？",a="杂味炖肉是弗娜创制的一道边疆菜肴。她用野猪鼻、秃鹫的筋肉、鱼人眼球，以及从附近废弃农场采来的秋葵烹制这道菜，供滞留的难民充饥。",al={"杂味炖肉任务","弗娜·法布隆的炖菜","弗娜做什么菜"}},{q="法布隆一家的农场出了什么事？",a="在王国近来治安崩溃期间，成群结伙的强盗夺走了法布隆一家位于西部荒野北部的南瓜农场。法布隆一家不得不离开自己的家园和田地。",al={"法布隆南瓜农场","法布隆一家的农场出了什么事"}}},fx={c5a3789f={q="弗娜·法布隆是谁？",a="弗娜·法布隆是西部荒野一位朴实的农妇，也是农夫西奥多·法布隆的妻子。她以丰盛的杂味炖肉和慷慨的性情闻名乡间，与丈夫在西部荒野北部耕种着一片南瓜田，直到暴乱摧毁了他们的生计。如今，她流离失所，被困在路边，却仍试图在接连不断的厄运中保持乐观。",al={"弗娜·法布隆是谁","弗娜·法布隆的身份","弗娜·法布隆的故事"}},b45ce146={q="弗娜·法布隆效忠哪一方？",a="弗娜是暴风城王国忠诚的子民，坚定地支持联盟。和西部荒野的许多普通百姓一样，她对那些使这片土地四分五裂的歹徒毫无好感，只盼着和平与安全，以及摆脱乡间无法无天局面的机会。",al={"弗娜·法布隆的阵营","弗娜·法布隆是否属于联盟","弗娜·法布隆支持哪一方"}},["0d4268c1"]={q="弗娜·法布隆想要什么？",a="弗娜只想让家人吃饱，平安离开西部荒野。失去农场后，她和丈夫原打算到艾尔文森林避难，却因损坏的货车和饥饿疲惫的马匹而寸步难行。目前，她正在寻找炖汤的食材和喂给老布兰契的燕麦等补给，好在路边维持生计。",al={"弗娜·法布隆想要什么","弗娜·法布隆的目标","为何帮助弗娜·法布隆"}}},fp="14,182,23.462.0,19.399.0,44.209.0,30.132.0,22.196.0,37.172.0"}
P.entries["npc:verner-osgood"] = {n="弗纳·奥斯古",s="在湖畔镇的铁匠铺外，弗纳·奥斯古让炉火常燃。豺狼人袭扰着群山，而他要兼顾本地生意与暴风城卫队对马蹄铁、武器和护甲的需求。",h="在湖畔镇的铁匠铺外，弗纳·奥斯古让炉火常燃。豺狼人袭扰着群山，而他要兼顾本地生意与暴风城卫队对马蹄铁、武器和护甲的需求。",kw={"铁匠","豺狼人","马匹","湖畔镇","所罗门镇长","赤脊山","弗纳·奥斯古","犹勒"},ang={["faction:Alliance"]="暴风城能提供的军事援助依然少得令人担忧，湖畔镇只能依靠弗纳这样的本地工匠支撑下去。",["profession:Blacksmithing"]="身为铁匠，弗纳既要为民用马匹钉蹄铁，也要完成驻军防务所要求的严苛配额。",["race:Human"]="身为人类，你与暴风城的平民一样坚韧，在豺狼人和物资短缺的双重威胁下坚守阵地。"},sec={{t="湖畔镇的铁砧",b="在湖畔镇的熔炉旁，弗纳·奥斯古为镇上打造马蹄铁和其他物资。他的库存不断被征用，用来为暴风城卫队制造武器和护甲。王国兵力捉襟见肘，当地驻军物资短缺，维持赤脊山守军装备的重担，很大一部分落在了弗纳肩上。"},{t="豺狼人之患",b="豺狼人的袭击既威胁着弗纳的营生，也威胁着镇上的马匹。它们成群出没，在赤脊山的山丘间伏击牲畜，掳走那些游荡到湖畔镇外的役马。弗纳招募旅行者，猎杀这些劫掠者和它们的首领犹勒。"}},faq={{q="弗纳·奥斯古是谁？",a="弗纳·奥斯古照看着湖畔镇的熔炉，打造铁器和马蹄铁，同时满足当地驻军对装备的大量需求。",al={"弗纳·奥斯古","湖畔镇铁匠","弗纳是谁"}},{q="弗纳为什么缺少马蹄铁和铁料？",a="铁料不断被征用，用来为驻扎在赤脊山的暴风城卫队制造武器和护甲，留给弗纳的金属勉强够为镇上的马匹钉蹄铁。",al={"弗纳缺铁","马掌 任务背景","为什么没有马蹄铁"}},{q="豺狼人给弗纳带来了什么麻烦？",a="只要弗纳的马匹游荡到镇外，湖畔镇附近的豺狼人劫掠者就会将它们掳走。他雇用旅行者猎杀这些豺狼人，保护自己的生计，并向它们复仇。",al={"弗纳的豺狼人之患","弗纳为什么憎恨豺狼人"}},{q="犹勒是谁，弗纳为什么想要他的命？",a="犹勒统领着当地山丘间的豺狼人群。弗纳想要除掉他，瓦解劫掠者的协同，让它们无法再恐吓镇民、杀害他的马匹。",al={"犹勒 是谁","弗纳 犹勒 任务"}},{q="弗纳与所罗门镇长有什么关系？",a="弗纳在湖畔镇受所罗门镇长的行政管辖，既要维持民用手艺营生，也要满足镇长那举步维艰的行政机构在民政和军事上的需求。",al={"弗纳与所罗门镇长","弗纳与镇上领导者"}},{q="弗纳在暴风城有亲人吗？",a="弗纳与暴风城的手艺人杜纳尔和 巴斯尔·奥斯古 同姓，这暗示着当地各处可能有一个传承已久的人类工匠家族，世代以手艺谋生。",al={"弗纳的亲属","奥斯古家族"}}},fp="13,174,22.328.0,18.238.0,21.138.0,41.167.0,46.161.0,48.172.0,50.191.0,37.176.0"}
P.entries["npc:veron-amberstill"] = {n="维隆·冻石",s="在丹莫罗东部的冻石农场，维隆·冻石饲养着深受铁炉堡骑手信赖的山羊。",h="在丹莫罗东部的冻石农场，维隆·冻石饲养着深受铁炉堡骑手信赖的山羊。",kw={"冻石农场","丹莫罗","铁炉堡","坐骑商人","山地山羊","山羊商人","维隆·冻石"},ang={["faction:Alliance"]="作为铁炉堡的盟友，你必须证明自己对矮人王国的忠诚，才能赢得维隆的尊重，骑上山地山羊。",["race:Dwarf"]="身为矮人，你可以从维隆为遍布卡兹莫丹的骑手饲养的普通坐骑和迅捷坐骑身上，看到族人与山地山羊之间的深厚联系。"},sec={{t="坐骑大师",b="在丹莫罗东部的冻石农场，维隆·冻石繁育并训练山地山羊。它们凭借稳健的步伐和厚实的皮毛，翻越卡兹莫丹的陡坡，穿行于暴风雪中。维隆为矮人斥候、巡山人和四处游历的冒险者饲养这些山羊。他向矮人同胞出售普通坐骑和迅捷坐骑。其他种族的骑手必须证明自己对铁炉堡王座的忠诚，他才肯出售山羊。"}},faq={{q="维隆·冻石是谁？",a="维隆·冻石在丹莫罗的冻石农场繁育山地山羊。他为铁炉堡饲养健壮的坐骑，并将它们出售给符合条件的骑手。",al={"维隆·冻石","维隆是谁","冻石山羊商人"}},{q="非矮人能向维隆购买山羊吗？",a="可以。矮人可以购买维隆的山羊。其他种族的骑手必须在铁炉堡达到崇拜声望，他才会放心地把羊群中的山羊交给他们。",al={"人类能买山羊吗","非矮人山羊坐骑","铁炉堡声望山羊"}},{q="维隆·冻石在哪里？",a="你可以在丹莫罗东部丘陵的冻石农场外找到维隆，就在古博拉采掘场北面。",al={"维隆位置","维隆在哪","哪里能找到维隆·冻石"}},{q="矮人为什么骑山羊而不骑马？",a="山地山羊拥有厚实的皮毛、健壮的体格和稳健的步伐。凭借这些特征，它们比普通马匹更能适应丹莫罗的凛冽寒风和陡峭岩壁上的狭窄平台。",al={"矮人为什么骑山羊","矮人坐骑背景故事","山地山羊坐骑背景故事"}}},fx={["601a0646"]={q="维隆·冻石效忠哪一方？",a="维隆·冻石坚定地效忠于矮人的铁炉堡王国和联盟。他照料着矮人珍视的山羊坐骑，为同胞和在铁炉堡赢得崇高声望的可靠联盟盟友提供可靠的坐骑。",al={"维隆·冻石的阵营","维隆·冻石是否属于联盟","维隆·冻石效忠谁"}},b4666b3f={q="维隆·冻石为什么在这里？",a="维隆·冻石管理着冻石农场，它坐落在丹莫罗寒风吹拂的丘陵间。寒冷多石的地形非常适合饲养结实耐寒的山羊，使这座农场成为繁育和训练这些矮人标志性坐骑的中心。",al={"维隆·冻石为何在丹莫罗","维隆·冻石在此的原因","冻石农场的用途"}},["8bafbe3f"]={q="维隆·冻石想要什么？",a="维隆·冻石想保护自己的生计，保全农场珍贵的山羊群。他专注于繁育、饲养羊群，保护它们免受游荡在丹莫罗雪岭间的危险侵害，为有资格的骑手提供健壮的坐骑。",al={"维隆·冻石的目标","维隆想要什么","维隆·冻石的目的"}},["921d6dac"]={q="维隆·冻石与谁有关联？",a="维隆与冻石氏族以及以家族姓氏命名的农场紧密相连。他与农场中的亲人一起负责山羊的照料和繁育，这些山羊世世代代为丹莫罗的矮人服务。",al={"维隆·冻石的家人","维隆与谁有亲属关系","冻石家族"}}},fp="16,99,20.426.0,24.146.0,41.148.0,34.113.0,43.164.0"}
P.entries["npc:veronica-nials"] = {n="Veronica Nials",s="在避难谷地，维罗妮卡·尼艾丝队长指挥着激流堡的防御，而她的王国正分崩离析。她在阿拉希高地面对辛迪加的背叛与石拳食人魔的威胁。",h="在避难谷地，维罗妮卡·尼艾丝队长指挥着激流堡的防御，而她的王国正分崩离析。她在阿拉希高地面对辛迪加的背叛与石拳食人魔的威胁。",kw={"阿拉希高地","法库雷斯特","玛雷兹·考尔","避难谷地","激流堡","辛迪加","萨多尔大桥","维罗妮卡·尼艾丝"},ang={["faction:Alliance"]="身为联盟的一员，你看到激流堡的北方诸国分裂孤立，艰难求存，几乎无力援助邻近的盟友。",["race:Human"]="身为人类，你在尼艾丝身上看到了激流堡的尚武之傲，即使局势极为不利，她仍拒绝放弃阿拉索的祖传疆土。"},sec={{t="破碎王国的守卫者",b="第三次大战之后，激流堡四分五裂，人民面临石拳食人魔的入侵和辛迪加的背叛。在避难谷地，维罗妮卡·尼艾丝队长统率着幸存的激流堡守军。她指引联盟勇士对抗辛迪加首领，其中包括法库雷斯特公爵和术士玛雷兹·考尔。她还寻求找回阵亡士兵的徽章，让悲痛的家人得知他们的下落。"},{t="遭拒的求援",b="当拉格·加玛森和丹莫德的矮人守军向激流堡求援时，尼艾丝队长不得不拒绝。黑铁破坏者重创了萨多尔大桥，但她的部队连一名士兵也无法抽调到阿拉希高地之外。激流堡仍被占据，荣誉与职责使他们必须坚守故土。"}},faq={{q="维罗娜·尼艾丝是谁？",a="维罗娜·尼艾丝是激流堡军中的一名人类队长，驻守在避难谷地。她指挥部队，在阿拉希高地抵抗辛迪加渗透者和食人魔。",al={"维罗妮卡·尼艾丝是谁","尼艾丝队长","避难谷地队长"}},{q="尼艾丝队长为什么不援助丹莫德和萨多尔大桥？",a="尼艾丝队长无法抽调士兵援助丹莫德和萨多尔大桥。激流堡濒临毁灭，职责要求她的部队全力夺回沦陷的王国。",al={"萨多尔大桥求援","为什么不援助矮人","向联盟求援任务"}},{q="尼艾丝收集激流堡徽章有什么用？",a="辛迪加悬赏收购从被杀害的激流堡士兵身上夺取的徽章。尼艾丝请联盟冒险者找回这些被夺走的徽章，以便确认死讯，并通知阵亡守军的家人。",al={"激流堡徽章","为什么收集徽章","徽章任务"}}},fp="14,177,26.399.0,13.327.0,22.172.0,59.170.0,42.199.0"}
P.entries["npc:vesprystus"] = {n="维斯派塔斯",s="在鲁瑟兰村，维斯派塔斯送旅人往返于泰达希尔与卡利姆多大陆之间。他照料着宏伟的世界之树脚下的角鹰兽巢。",h="在鲁瑟兰村，维斯派塔斯送旅人往返于泰达希尔与卡利姆多大陆之间。他照料着宏伟的世界之树脚下的角鹰兽巢。",kw={"奥伯丁","黑海岸","飞行管理员","角鹰兽管理员","鲁瑟兰村","泰达希尔","维斯派塔斯"},ang={["faction:Alliance"]="作为抵达泰达希尔码头的联盟旅人，你可以找维斯派塔斯，迅速前往黑海岸沿岸。",["race:NightElf"]="作为初次离开泰达希尔的年轻暗夜精灵，你或许会发现维斯派塔斯已准备好送你启程，让你初见卡利姆多大陆。"},sec={{t="鲁瑟兰鹰巢的看守者",b="在泰达希尔南端的树脚下，维斯派塔斯照料着鲁瑟兰的角鹰兽巢。训练有素的角鹰兽载着旅人离开与世隔绝的精灵树上家园，飞往黑海岸和大陆。一道魔法传送门也将鲁瑟兰与上方树冠中的达纳苏斯连接起来。在海峡两岸，维斯派塔斯与奥伯丁的飞行管理员协作，将哨兵、使者和冒险者送往卡利姆多。"}},faq={{q="维斯派塔斯会将旅人送往何处？",a="维斯派塔斯载着旅人从鲁瑟兰村出发，越过海面，抵达黑海岸沿岸的奥伯丁。从那里转乘角鹰兽航线，便可向南前往灰谷，以及卡利姆多各地的其他暗夜精灵聚居地。",al={"他能带我去哪里","维斯派塔斯飞行路线","鲁瑟兰 飞行路线"}},{q="维斯派塔斯照料什么生物？",a="维斯派塔斯照料着一群忠诚的暗夜精灵角鹰兽，它们是原生于卡利姆多北部的古老有翼巨兽。世世代代以来，暗夜精灵饲养角鹰兽，与它们建立羁绊，借助它们穿行于森林树冠和崎岖的海岸线之间。",al={"他有哪些坐骑","维斯派塔斯的动物","他用什么载人飞行"}},{q="如何从维斯派塔斯所在之处前往达纳苏斯？",a="从鲁瑟兰村前往达纳苏斯，无须乘坐飞行坐骑。从维斯派塔斯的角鹰兽巢沿小径稍行几步，就能看见一道闪着粉色微光的传送门，将旅人送往树冠中的城市。",al={"如何从维斯派塔斯处前往达纳苏斯","维斯派塔斯到达纳苏斯","前往达纳苏斯的路线"}}},fp="10,152,30.380.0,36.221.0,36.218.0,56.174.0"}
P.entries["npc:vidra-hearthstove"] = {n="维德拉·壁炉",s="在塞尔萨玛的烈酒旅店，维德拉·壁炉用周围荒野中的野味制作血肠。",h="在塞尔萨玛的烈酒旅店，维德拉·壁炉用周围荒野中的野味制作血肠。",kw={"血肠","矮人厨师","壁炉","洛克莫丹","烈酒旅店","塞尔萨玛","维德拉·壁炉"},ang={["profession:Cooking"]="身为厨师，维德拉将当地粗粝的食材做成充饥果腹的饭菜，供饥肠辘辘的冒险者和山地巡逻队享用。她的烹饪沿袭了卡兹莫丹丰盛质朴的传统。",["race:Dwarf"]="身为途经塞尔萨玛的矮人，你可以在维德拉的厨房里尝到令人安心的家乡风味，她的饭菜也让镇民们保持着高昂的士气。"},sec={{t="烈酒旅店的厨房",b="维德拉为旅店备好食物，供当地居民和旅人享用。和旅店老板一样，她也姓壁炉。她制作血肠需要新鲜的野味：野猪内脏、蜘蛛脓液和熊肉。"}},faq={{q="维德拉·壁炉是谁？",a="维德拉·壁炉在烈酒旅店掌勺，也住在那里。旅店的客人和保卫洛克莫丹的巡山人都能吃到她制作的著名塞尔萨玛血肠。",al={"维德拉·壁炉的故事","维德拉是谁","烈酒旅店厨师"}},{q="在哪里可以找到维德拉·壁炉？",a="你可以在洛克莫丹塞尔萨玛镇中心的烈酒旅店里找到维德拉。",al={"维德拉位置","维德拉·壁炉在哪里","烈酒旅店维德拉"}},{q="她用什么原料制作塞尔萨玛血肠？",a="维德拉的著名配方需要洛克莫丹野生动物身上的熊肉、野猪肠和蜘蛛脓液。",al={"血肠原料","塞尔萨玛血肠用什么做","维德拉的配方"}}},fx={["5e429306"]={q="维德拉·壁炉效忠哪一方？",a="维德拉是卡兹莫丹忠诚的矮人居民，坚定地支持联盟。她在塞尔萨玛的中心生活和工作，为当地居民烹制饭菜，也欢迎跋涉穿过洛克莫丹的疲惫旅人。",al={"维德拉·壁炉 阵营","维德拉是否属于联盟","维德拉·壁炉 立场"}},e3ca8182={q="维德拉·壁炉想要什么？",a="维德拉潜心钻研厨艺，确保烈酒旅店的客人都能吃饱。她寻找湖畔野生动物身上新鲜、丰盛的食材，尤其是当地野兽的肉和内脏，用来制作她闻名遐迩的塞尔萨玛血肠。",al={"维德拉·壁炉 动机","维德拉想要什么","维德拉·壁炉 食谱"}},["8f91522d"]={q="维德拉·壁炉为什么在塞尔萨玛？",a="维德拉在烈酒旅店谋生，为镇上的居民、商贩和过路的冒险者提供家常饭菜。塞尔萨玛是洛克莫丹的主要枢纽，她的厨房为当地守军和工人提供了不可或缺的饮食保障。",al={"维德拉为什么在烈酒旅店","维德拉·壁炉 所在地点原因","维德拉为什么在这里"}}},fp="17,114,25.190.0,25.159.0,37.87.0,59.105.0"}
P.entries["npc:viktori-prism-antras"] = {n="维克托·安特拉斯",s="在夜色镇上方的山坡上，维克托·安特拉斯始终凝望着星空。",h="在夜色镇上方的山坡上，维克托·安特拉斯始终凝望着星空。",kw={"天文学","考格·旋轴","夜色镇","暮色森林","仰望星空","安特拉斯","观星者","望远镜","维克托"},ang={["faction:Alliance"]="帮助维克托，能让你在夜色镇找到一件难得的宁静之事，陪伴这位联盟居民在无处不在的悲剧中探寻奇观。",["profession:Engineering"]="热衷钻研机械的人会欣赏维克托的计划：他那精密的观测仪器，需要依照复杂的侏儒图纸来打造。",["race:Gnome"]="维克托的计划有赖于考格·旋轴的巧思，足见侏儒工程学的影响之广，甚至延伸到了最荒凉的人类城镇。"},sec={{t="仰望苍穹",b="沿着 Gryphon Roost 后方的斜坡向上，维克托·安特拉斯从暮色森林的阴霾中仰望天空。亡灵的侵袭、饥饿的蜘蛛和悄然蔓延的暗影将他包围，他的目光却始终投向那令人窒息的树冠之外。他希望造出一架精良的光学望远镜，让群星清晰地呈现在眼前，也让自己能暂避笼罩小镇的恐惧，寻得片刻安宁。"},{t="侏儒图纸与散落的零件",b="在这片被诅咒的森林里，哪怕只是打造一架精巧的望远镜，也要费一番工夫。维克托依照侏儒朋友考格·旋轴提供的图纸进行制作。他请过路的人寻找稀有的镜片制作材料和机械外壳，其中包括散落在危险地带的精细切割玻璃和金属镜片。"}},faq={{q="维克托·安特拉斯是谁？",a="维克托是夜色镇一位性情古怪的人类观星者。镇子面临着政治与超自然力量的威胁，他却一心打造用来研究星辰的望远镜。",al={"维克托是谁","维克托·安特拉斯背景故事","维克托 暮色森林"}},{q="在夜色镇哪里可以找到维克托？",a="维克托住在山坡上的一间小木屋里，刚过夜色镇的狮鹫管理员，沿小路上山时就在右手边。",al={"维克托·安特拉斯位置","维克托在哪里","夜色镇寻找维克托"}},{q="维克托想要打造什么？",a="维克托正试着依照侏儒同僚考格·旋轴绘制的图纸，打造一架天文望远镜。这需要几种专用镜片和零件。",al={"维克托望远镜","仰望星空 装置","维克托制作什么"}},{q="他为什么要在暮色森林研究星辰？",a="尽管暮色森林充满黑暗与恐怖，维克托仍对苍穹怀着无尽的好奇。研究夜空让他能在求知中暂避周围土地的腐朽。",al={"夜色镇为什么造望远镜","为什么在暮色森林研究星辰"}},{q="谁为维克托的望远镜设计了图纸？",a="望远镜的图纸出自考格·旋轴之手，他是维克托认识的一位富于巧思的侏儒。",al={"考格·旋轴","谁绘制了望远镜图纸"}},{q="维克托会协助保卫夜色镇吗？",a="不会。维克托是平民学者，并非战士，他将保卫夜色镇的职责交给指挥官阿尔泰娅·埃伯洛克和守夜人。他把全部精力都投入了天文研究。",al={"维克托是 守夜人 成员吗","维克托会战斗吗"}}},fp="20,138,21.351.0,38.291.0,28.172.0,38.127.0,32.156.0,43.181.0,47.92.0,35.178.0"}
P.entries["npc:viscous-fallout"] = {n="粘性辐射尘",s="在诺莫瑞根的下层通道中，粘性辐射尘在有毒的废水中游荡。",h="在诺莫瑞根的下层通道中，粘性辐射尘在有毒的废水中游荡。",kw={"诺莫瑞根","水藤","辐射","瑟玛普拉格","侏儒区","粘性辐射尘","水元素"},ang={["class:Druid"]="身为德鲁伊，你可以将粘性辐射尘视为大自然身上一道活生生的伤口，显露出污染渗入地下水时，肆无忌惮的工业活动所带来的伤害。",["class:Shaman"]="身为萨满祭司，你能认出这是一个被人造有毒废料玷污的水元素。",["race:Gnome"]="对侏儒而言，粘性辐射尘让他们想起麦克尼尔·瑟玛普拉格给家园带来的破坏，那里连流淌的水都带着剧毒。"},sec={{t="受污染的灵体",b="麦克尼尔·瑟玛普拉格提出了一个消灭入侵穴居人的阴险计划，随后辐射便席卷了诺莫瑞根。放射性尘埃让城市下层充满了有毒的软泥和污染物。粘性辐射尘是一个水元素，构成它身躯的物质中混杂着城里的有毒废料，变得黏稠不堪。它在城市陷落前的来历无人知晓。"},{t="废水中的痛苦",b="粘性辐射尘如同一滩活生生的有毒淤泥，在诺莫瑞根遭受辐射的下层通道中游荡。它接连喷吐毒液，随后猛攻挡在面前的一切。那些进入城中、试图净化受污染深处的人，必须消灭这个生物。"}},faq={{q="粘性辐射尘是什么？",a="粘性辐射尘是诺莫瑞根废城中的一个水元素小首领，受到了有毒淤泥和放射性尘埃的污染。",al={"粘性辐射尘是谁","粘性辐射尘的故事","粘性辐射尘是什么类型的怪物"}},{q="它是如何受到污染的？",a="麦克尼尔·瑟玛普拉格心怀叵测，提议用辐射击退入侵的穴居人，随后辐射便席卷了诺莫瑞根。有毒废料充斥着下层通道。没人确切知道这个元素生物是如何染上剧毒的；它已成为这座辐射废城的一部分。",al={"它为什么是绿色的","元素生物为什么有毒","粘性辐射尘是如何产生的"}},{q="它在诺莫瑞根的什么地方游荡？",a="粘性辐射尘在诺莫瑞根主要入口通道下方遭受辐射的下层通道和排水渠中游荡。它混迹于遍布这片区域的变异软泥怪和有毒废料之中。",al={"粘性辐射尘的位置","哪里能找到粘性辐射尘","如何找到粘性辐射尘"}},{q="它为什么充满敌意？",a="和徘徊在辐射深处的许多生物一样，粘性辐射尘会猛攻闯入受污染通道的活物。",al={"它为什么攻击","它还能获救吗"}},{q="它与铁炉堡有什么联系吗？",a="这种联系是间接的。逃离诺莫瑞根的侏儒如今以难民的身份住在铁炉堡内的侏儒区，而粘性辐射尘仍留在他们失去的家园中，与种种恐怖之物为伍。",al={"水藤 铁炉堡","与侏儒的联系"}},{q="这个元素生物能被净化或治愈吗？",a="目前尚无已知的方法能治愈这个元素生物。辐射和有毒化学物质已彻底渗透它的身躯，唯一的办法就是将它摧毁。",al={"粘性辐射尘能被治愈吗","净化粘性辐射尘"}}},fx={c0463f1a={q="粘性辐射尘效忠哪一方？",a="粘性辐射尘不听命于任何主人，也不属于任何阵营。虽然它身上的剧毒直接源于麦克尼尔·瑟玛普拉格向全城排放的放射性尘埃，但它并不是他、麻风侏儒或穴居人的盟友。它只是一个饱受折磨的元素生物，被污染逼疯，无差别地攻击一切挡在面前的事物。",al={"粘性辐射尘 阵营","粘性辐射尘效忠谁","粘性辐射尘是否与瑟玛普拉格同伙"}},["41523791"]={q="粘性辐射尘想要什么？",a="这个元素生物没有宏大的野心，也没有理性的目标。它是污染诺莫瑞根的毒物凝成的一团剧毒，在遭受辐射的走廊中游荡，攻击任何不幸踏入城中被淹通道的活物。",al={"粘性辐射尘 目标","粘性辐射尘做什么","粘性辐射尘 动机"}},["2b056577"]={q="粘性辐射尘为什么在这里？",a="它在诺莫瑞根遭受辐射的深处游荡，那里遍布有毒废料，都是麦克尼尔·瑟玛普拉格为击退穴居人而用辐射淹没城市所致。没人知道这个元素生物在城市沦陷之前来自何处。",al={"粘性辐射尘为什么在诺莫瑞根","粘性辐射尘如何来到这里","粘性辐射尘 所在地点原因"}}},fp="15,80,17.323.0,19.253.0,24.124.0,28.266.0,35.183.0,18.133.0,41.179.0,39.142.0"}
P.entries["npc:vol-jin"] = {n="沃金",s="在奥格瑞玛，沃金为大酋长萨尔出谋划策，同时为族人寻找长久的家园。这位黑暗之矛酋长是一名技艺高超的暗影猎手。",h="在奥格瑞玛，沃金为大酋长萨尔出谋划策，同时为族人寻找长久的家园。这位黑暗之矛酋长是一名技艺高超的暗影猎手。",kw={"黑暗之矛","索尔的堡垒","奥格瑞玛","森金","暗影猎手","萨尔","沃金","扎拉赞恩"},ang={["faction:Horde"]="身为部落的一员，你有沃金在萨尔身旁相助，献上机敏的谋略和丛林巨魔坚定不移的忠诚。",["race:Troll"]="身为巨魔，沃金就是你的酋长。他以精神上的智慧和战术上的果决，带领流离失所的黑暗之矛渡过重重难关。"},sec={{t="黑暗之矛酋长",b="沃金的父亲森金在部族世代居住的岛屿上死去后，沃金接掌了黑暗之矛。崇拜海巫的鱼人和人类军队几乎摧毁了这个与世隔绝的部族，但萨尔率领的兽人出手相助，与巨魔结下了深厚的情谊。逃离满目疮痍的群岛后，沃金宣誓率族人效忠新的部落，带领他们横渡无尽之海，来到卡利姆多。"},{t="在智慧谷议事",b="黑暗之矛在杜隆塔尔定居，但扎拉赞恩在回音群岛的背叛迫使许多难民逃往大陆上的森金村。沃金大部分时间都待在奥格瑞玛的索尔的堡垒，以战略谋略和暗影猎手的本领辅佐萨尔。在这座兽人都城中，他守护着初生的部落，并致力于收复族人的土地。"}},faq={{q="沃金是谁？",a="沃金领导着黑暗之矛巨魔部族，并在奥格瑞玛为大酋长萨尔出谋划策。他是一名技艺娴熟的暗影猎手，在部落领袖中代表着自己的族人。",al={"巨魔领袖是谁","沃金背景故事","黑暗之矛领袖"}},{q="沃金住在哪里？",a="沃金住在奥格瑞玛智慧谷的索尔的堡垒，就在大酋长萨尔身旁。",al={"沃金在哪里","沃金位置","寻找沃金"}},{q="黑暗之矛为何加入部落？",a="第三次大战期间，萨尔的舰队被海浪冲到了暗矛群岛的岸边。兽人与巨魔结盟，共同对抗敌对的人类和狂热的鱼人大军。森金死后，沃金宣誓率部族效忠萨尔，黑暗之矛随后跟随部落来到卡利姆多。",al={"巨魔为何加入部落","黑暗之矛与部落的历史","萨尔与沃金"}},{q="黑暗之矛为何没有住在自己的群岛上？",a="在杜隆塔尔近海的回音群岛定居后，巫医扎拉赞恩被黑暗魔法逼疯了。他奴役了自己的同胞，迫使沃金和幸存的黑暗之矛族人逃往大陆上的森金村。",al={"回音群岛发生了什么","巨魔为何在森金村","扎拉赞恩的背叛"}}},fp="7,138,26.364.0,31.370.0,15.158.0,24.88.0,37.267.0,53.223.0"}
P.entries["npc:volcor"] = {n="沃科尔",s="沃科尔负伤倒在黑海岸南部深处的黑木洞穴里。这位暗夜精灵斥候要靠他的熊伙伴格瑞姆克劳和奥伯丁的守卫，才能逃离充满敌意的熊怪。",h="沃科尔负伤倒在黑海岸南部深处的黑木洞穴里。这位暗夜精灵斥候要靠他的熊伙伴格瑞姆克劳和奥伯丁的守卫，才能逃离充满敌意的熊怪。",kw={"奥伯丁","黑木洞穴","黑海岸","武力脱身","潜行脱身","熊怪","格瑞姆","特伦希斯","沃科尔"},ang={["class:Druid"]="身为德鲁伊，你知道沃科尔与Grimclaw之间的羁绊，体现了德鲁伊与自然野兽之间的联系。营救他们也牵动着自然的平衡。",["class:Rogue"]="身为潜行者，你可以运用巧妙的战术，悄悄绕过黑木守卫，而不必依靠蛮力。",["race:NightElf"]="身为暗夜精灵，你能看到黑海岸的Kaldorei面临的危险，曾经温和的熊怪盟友如今正遭受腐化。"},sec={{t="困于大兽穴",b="沃科尔是一名暗夜精灵斥候，在黑木洞穴中负了伤。他追踪腐化的黑木部族，深入其地下巢穴，却遭到伏击，身受重伤。他无法独自突破敌对熊怪的阻拦，于是派忠诚的熊伙伴格瑞姆克劳前往黑海岸的荒野，去奥伯丁寻求援助。"},{t="脱身之路",b="沃科尔根据救援者的长处，提供了两种逃出洞穴的办法。斥候们带着特伦希斯的消息找到他后，偏好正面交锋的人可以杀出洞穴守卫的重围。擅长隐秘行动的人则可以悄悄绕过哨兵。"}},faq={{q="沃科尔在哪里？",a="沃科尔藏身于黑海岸南部的黑木洞穴深处，靠近灰谷边界，离奥伯丁以南的道路不远。",al={"沃科尔位置","沃科尔在哪","寻找沃科尔"}},{q="沃科尔为什么被困在黑木洞穴？",a="沃科尔在侦察黑木熊怪时遭到袭击，受了伤。他通往洞口的退路被切断，没有援助便无法突破敌对哨兵的阻拦。",al={"沃科尔为什么在洞穴里","沃科尔遭遇了什么"}},{q="格瑞姆是谁？",a="格瑞姆是沃科尔忠诚的熊伙伴。沃科尔被困后，派格瑞姆去奥伯丁寻求援助，让德鲁伊特伦希斯得知了他的处境。",al={"那只熊是谁","沃科尔的熊","格瑞姆背景故事"}},{q="你能如何帮助沃科尔逃脱？",a="沃科尔让你选择营救他的方式。你可以杀出洞中熊怪守卫的重围，也可以潜行绕过他们。",al={"武力或潜行脱身","沃科尔护送任务","营救沃科尔"}},{q="是谁派你寻找沃科尔？",a="有人发现格瑞姆独自游荡，主人却不见踪影后，奥伯丁的暗夜精灵德鲁伊特伦希斯便派你去寻找沃科尔。",al={"谁发布沃科尔任务","特伦希斯的关联"}},{q="是哪个熊怪部族袭击了他？",a="黑木部族袭击了沃科尔。这些熊怪原本生活在黑海岸，如今已遭腐化，陷入疯狂，充满敌意。",al={"哪些熊怪","黑木熊怪"}}},fp="6,172,18.321.0,16.177.1,24.132.0,39.167.0,16.141.0,31.123.0,28.121.0,36.130.0"}
P.entries["npc:vorn-skyseer"] = {n="沃恩·星眼",s="在纳拉其营地，沃恩·星眼欢迎踏上旅程的年轻牛头人。他住在莫高雷红云台地的帐篷之间，向新来者介绍营地的生活。",h="在纳拉其营地，沃恩·星眼欢迎踏上旅程的年轻牛头人。他住在莫高雷红云台地的帐篷之间，向新来者介绍营地的生活。",kw={"纳拉其营地","莫高雷","红云台地","牛头人","沃恩·星眼","欢迎"},ang={["faction:Horde"]="身为部落的一员，你可以从沃恩身上看到平原部族沉静稳重的天性，这些部族聚集在凯恩·血蹄的领导之下，建立永久的家园。",["race:Tauren"]="作为红云台地上的年轻牛头人，当你准备走向莫高雷更广阔的天地时，沃恩·星眼或许就是最早迎接你、让你感到熟悉而安心的面孔之一。"},sec={{t="纳拉其营地的亲切面孔",b="在纳拉其营地，沃恩·星眼迎接开始成年仪式的年轻牛头人。他们正准备离开红云台地，前往莫高雷更广阔的山谷，他亲切的话语与热情的欢迎帮助他们适应营地生活。"},{t="超然的旁观者",b="沃恩·星眼将营地的防务交给勇士们。他过着宁静悠然的生活，守望着故乡的平原。"}},faq={{q="沃恩·星眼是谁？",a="沃恩·星眼是莫高雷纳拉其营地的一位年长居民。他欢迎在红云台地开始初步试炼的年轻牛头人勇士。",al={"沃恩·星眼背景故事","沃恩是谁","沃恩莫高雷"}},{q="在哪里可以找到沃恩·星眼？",a="你可以在莫高雷西南部的红云台地上找到沃恩·星眼，他正在纳拉其营地的帐篷之间露天休息。",al={"沃恩·星眼位置","沃恩在哪里","沃恩纳拉其营地"}},{q="沃恩提供哪些任务？",a="沃恩在欢迎!任务中接收血蹄村礼品券。他向凭券而来的人致意，并提供一位小伙伴，陪伴他们冒险。",al={"沃恩·星眼任务","沃恩 欢迎任务"}}},fp="12,167,31.219.0,19.131.0,20.147.0,30.115.0,28.144.0"}
P.entries["npc:warcaller-gorlach"] = {n="公告员高拉克",s="公告员高拉克在奥格瑞玛巡逻，召唤部落勇士奔赴遥远的战线。他动员旅人与身经百战的战士，响应卡利姆多各地乃至更远处哨站的命令。",h="公告员高拉克在奥格瑞玛巡逻，召唤部落勇士奔赴遥远的战线。他动员旅人与身经百战的战士，响应卡利姆多各地乃至更远处哨站的命令。",kw={"灰谷狩猎","战斗号召","莫沙彻营地","高拉克","传令官","奥格瑞玛","公告员高拉克"},ang={["faction:Horde"]="身为部落勇士，如果你想证明自己的实力，或寻求前往杜隆塔尔之外的指引，可以向高拉克问路，前往需要增援的哨站。"},sec={{t="大酋长号召之声",b="公告员高拉克行走在奥格瑞玛的大道上，传达部落开拓疆土、保卫家园的号召。他在城中民众之间传达命令，寻找愿意考验自身勇气的志愿者。他派一些人前往灰谷，在那片争夺不休的林荫下作战。他指引另一些人前往菲拉斯的莫沙彻营地，那里的斥候正面对荒野的考验。他还召唤战士远赴瘟疫之地征战。随着远方的威胁日益加剧，高拉克号召首都的人们拿起武器。"}},faq={{q="公告员高拉克是谁？",a="公告员高拉克是一名在奥格瑞玛巡逻的兽人传令官，指引部落成员前往交战地区与偏远边疆。",al={"高拉克","高拉克是谁","公告员"}},{q="公告员高拉克会派冒险者去哪里？",a="公告员高拉克指引部落勇士前往需要支援的哨站，包括灰谷、菲拉斯的莫沙彻营地，以及瘟疫之地等遥远的前线。",al={"高拉克派遣地点","高拉克派往何处","高拉克任务"}},{q="在哪里可以找到公告员高拉克？",a="公告员高拉克在奥格瑞玛的街道与山谷间巡逻，号召城中的人们拿起武器。",al={"高拉克位置","高拉克在哪里","寻找高拉克"}}},fp="17,184,28.372.0,25.120.0,46.156.0,37.86.0"}
P.entries["npc:warden-thelwater"] = {n="典狱官塞尔沃特",s="暴风城发生了一场监狱暴动，典狱官塞尔沃特被围困在监狱入口。他召集有能力的冒险者，阻止迪菲亚潜行者囚犯，让叛乱无法蔓延到上方的城市。",h="暴风城发生了一场监狱暴动，典狱官塞尔沃特被围困在监狱入口。他召集有能力的冒险者，阻止迪菲亚潜行者囚犯，让叛乱无法蔓延到上方的城市。",kw={"巴基尔·斯瑞德","迪菲亚潜行者","监狱","暴动","暴风城","典狱官塞尔沃特"},ang={["class:Paladin"]="身为献身于秩序与正义的圣骑士，你可以帮助典狱官塞尔沃特控制暴力罪犯，恢复纪律。",["class:Rogue"]="身为潜行者，你进入监狱时，迪菲亚潜行者的阴谋与监狱内部的权力斗争仍在激起波澜。",["faction:Alliance"]="身为联盟的勇士，你可以帮助典狱官塞尔沃特恢复暴风城的秩序，阻止监狱叛乱威胁首都的居民。"},sec={{t="运河下的危机",b="暴风城运河下的监狱关押着王国最危险的恶徒、小偷和政治阴谋家。典狱官塞尔沃特负责看守这些囚犯，但一场有组织的叛乱让守卫措手不及。囚犯击溃了守卫，占领了牢房，塞尔沃特只能在入口筑起路障，竭力遏制这场发生在首都街道下方的武装叛乱。"},{t="隐瞒真相",b="塞尔沃特不愿让恐慌蔓延到暴风城的街头，因此秘密处理这场叛乱。暴动的主谋巴基尔·斯瑞德在迪菲亚潜行者囚犯中有着极大的影响力。塞尔沃特担心暴动会暴露暴风城统治的弱点，于是求助于外来的雇佣兵，让他们进入牢区，击败头目，悄悄夺回监狱。"}},faq={{q="典狱官塞尔沃特是谁？",a="典狱官塞尔沃特是驻守在暴风城监狱入口的人类官员。他负责管理这座戒备森严的监狱。",al={"塞尔沃特","监狱典狱官","塞尔沃特是谁"}},{q="监狱发生了什么？",a="囚犯发动了一场有组织的叛乱，主要由迪菲亚潜行者成员领导。他们击败守卫，占领了牢区，将塞尔沃特和他剩下的部下困在入口附近。",al={"监狱暴动","监狱发生了什么","监狱为何失守"}},{q="谁在领导这场监狱暴动？",a="巴基尔·斯瑞德在监狱深处指挥叛乱。他统领迪菲亚潜行者囚犯，并率领他们向守卫发起了突袭。",al={"监狱首领","谁领导叛乱","巴基尔·斯瑞德是谁"}},{q="暴风城卫兵为何没有大举介入？",a="塞尔沃特希望悄悄解决这场危机。暴风城防卫最森严的地牢竟被囚犯攻陷，这个消息可能引发恐慌，因此他召集行事谨慎的冒险者，夺回监狱内部的控制权。",al={"为何没有守卫","为何雇佣冒险者","秘密暴动"}},{q="这里关押着什么样的囚犯？",a="监狱关押着小混混、窃贼、杀人犯和危险的政治叛乱分子，其中包括迪菲亚潜行者的高层成员。",al={"监狱囚犯","监狱里关着谁","罪犯类型"}},{q="在哪里能找到典狱官塞尔沃特？",a="典狱官塞尔沃特就驻守在暴风城监狱入口外，靠近法师区与教堂广场之间的运河。",al={"塞尔沃特位置","典狱官在哪里","寻找塞尔沃特"}}},fp="16,182,22.422.0,20.401.1,24.94.0,30.222.0,31.139.0,56.203.0,37.146.0,36.146.0"}
P.entries["npc:warlord-goretooth"] = {n="军官高图斯",s="军官高图斯是驻扎在荒芜之地尘土飞扬的荒野中、统领卡加斯驻军的兽人军官。他在瞭望塔上协调部落针对邻近黑铁矮人的边境战事，并监视黑石山的火山威胁。虽然治军严厉，偶尔也能看到他在营地的篝火旁休憩。",h="军官高图斯是驻扎在荒芜之地尘土飞扬的荒野中、统领卡加斯驻军的兽人军官。他在瞭望塔上协调部落针对邻近黑铁矮人的边境战事，并监视黑石山的火山威胁。虽然治军严厉，偶尔也能看到他在营地的篝火旁休憩。",kw={"怒炉","荒芜之地","黑石","黑铁","伊崔格","高图斯","卡加斯","军官高图斯"},ang={["class:Warrior"]="高图斯在黑石山下达的军令残酷而直接，让崇尚武勇的勇士有机会与身经百战的矮人军团士兵交锋，检验自己的实力。",["faction:Horde"]="军官高图斯是部落在荒芜之地立足的支柱，指挥着针对黑铁矮人的关键军事行动。"},sec={{t="卡加斯的指挥官",b="军官隆克 高图斯 坐镇卡加斯的瞭望塔，指挥部落在危机四伏的东部边境开展行动。卡加斯是奥格瑞玛对抗黑石山内部及周围峡谷中潜藏威胁的主要集结地。高图斯监督巡逻，协调卡加斯探险队等侦察部队，并直接下达针对黑铁氏族士兵与首领的格杀令。离开瞭望哨时，这位严厉的指挥官也会展露随和的一面，常在营地篝火旁取暖，与营中的被遗忘者施法者打趣，随后再返回岗位。"},{t="打击黑铁",b="高图斯认为，黑铁矮人对部落在东部王国的利益构成了明确而迫切的威胁。他积极筹划进攻，打击盘踞在黑石深渊中的安格弗将军和达格兰·索瑞森大帝的部队，而非摆出防守姿态。他深知进攻这座古老的地下要塞事关重大，因此在战略问题上经常听取奥格瑞玛的伊崔格等兽人老兵的意见，在批准进一步向山中推进之前，先寻求他们久经沙场的智慧。"}},faq={{q="军官高图斯是谁？",a="军官高图斯是驻扎在荒芜之地卡加斯的部落高级军事指挥官。他组织部落巡逻，并指挥针对黑铁矮人的突袭。",al={"军官高图斯","高图斯 是谁","高图斯 荒芜之地","卡加斯指挥官"}},{q="他在卡加斯担任什么职务？",a="他统领这座前哨站，定期派遣卡加斯探险队出征，并下达军令，对黑石深渊内的黑铁氏族展开行动。",al={"高图斯 做什么","高图斯 职责","高图斯 驻地"}},{q="高图斯为什么派兵进攻黑石深渊？",a="黑铁矮人威胁着周边地区，并积极抵制部落在当地的势力。高图斯直接悬赏击杀他们的士兵、高级军官以及安格弗将军，以削弱他们对黑石山的控制。",al={"为什么击杀 黑铁","杀死安格弗将军 任务","高图斯 黑铁"}},{q="高图斯为什么向伊崔格请教？",a="伊崔格是一位经验丰富的兽人老兵，曾在黑石山中生活，对山中的内部政治与防御部署的了解几乎无人能及。在加紧进攻黑石山的要塞之前，高图斯会派冒险者去征询伊崔格的意见。",al={"高图斯 与伊崔格","伊崔格的智慧","为什么与伊崔格交谈"}}},fp="17,214,20.498.0,23.447.0,25.153.0,28.161.0,59.209.0,35.177.0"}
P.entries["npc:warmaster-laggrond"] = {n="拉格隆德",s="在奥特兰克山谷外，拉格隆德为霜狼氏族整备部落战士。他在奥特兰克山脉的山谷入口坐镇指挥，勇士们在此响应号召，援助霜狼氏族。",h="在奥特兰克山谷外，拉格隆德为霜狼氏族整备部落战士。他在奥特兰克山脉的山谷入口坐镇指挥，勇士们在此响应号召，援助霜狼氏族。",kw={"奥特兰克山脉","奥特兰克山谷","霜狼","拉格隆德","实验场","玩家对战","雷矛"},ang={["class:Warrior"]="身为战士，你要接受拉格隆德对前线勇气的考验，证明自己能够抵挡矮人的重甲部队和先锋冲锋。",["faction:Horde"]="拉格隆德是你参与奥特兰克山谷战事时最先接洽的人。他会表彰你为霜狼氏族立下的战功。",["race:Orc"]="身为兽人，响应拉格隆德的召唤，便意味着保卫霜狼氏族祖辈的庇护之地，抵御矮人的入侵。"},sec={{t="前线指挥官",b="拉格隆德在奥特兰克山谷入口指挥部落对抗雷矛探险队。在刺骨的严寒中，他只准许有实力的战士代表霜狼氏族和整个部落出战。"},{t="荣耀之路",b="拉格隆德要求前来参战的勇士先完成实验场，再投入战斗。勇士们在冰封的群峰间征战时，他会评定他们的声望，并嘉奖那些在霜狼氏族中赢得声名的人。"}},faq={{q="拉格隆德在哪里？",a="拉格隆德驻守在奥特兰克山谷入口传送门旁的部落营地附近，那里位于希尔斯布莱德丘陵以北、奥特兰克山脉积雪覆盖的山道中。",al={"拉格隆德位置","拉格隆德在哪","奥特兰克山谷入口督军"}},{q="拉格隆德的职责是什么？",a="拉格隆德为部落在奥特兰克山谷的战争招募战士。他考验新兵，并嘉奖那些在霜狼氏族中赢得声望的人。",al={"拉格隆德做什么","拉格隆德职责","为何与拉格隆德交谈"}},{q="实验场是什么任务？",a="拉格隆德要求有意入伍的新兵从奥特兰克山谷的蛮爪洞穴取回一面霜狼军旗。这场试炼会在他们投身战事前，检验他们的应变能力。",al={"实验场 部落","拉格隆德起始任务"}},{q="部落为何在奥特兰克山谷作战？",a="霜狼氏族在第一次兽人战争期间遭到流放，此后便以奥特兰克山谷为家。雷矛卫队是一支联盟矮人远征队，为寻找遗物和夺取领地而深入这片地区，引发了一场惨烈的领土战争。",al={"为何争夺奥特兰克山谷","霜狼氏族战争","奥特兰克山谷冲突"}},{q="联盟玩家能与拉格隆德互动吗？",a="不能。拉格隆德是忠于部落的勇士，会攻击靠近他山间哨站的联盟入侵者。",al={"联盟能与拉格隆德交谈吗","拉格隆德敌对"}}},fp="18,189,19.219.0,17.227.0,36.159.0,34.159.0,34.184.0,44.249.0,54.118.0"}
P.entries["npc:warsong-outrider"] = {n="战歌侦查骑兵",s="在从灰谷向东延伸的道路上，战歌侦查骑兵守望着部落的边境。她为战歌氏族执行侦察任务，监视过往旅人，并向前沿营地传递情报。只要无人挑衅，她便继续守望。",h="在从灰谷向东延伸的道路上，战歌侦查骑兵守望着部落的边境。她为战歌氏族执行侦察任务，监视过往旅人，并向前沿营地传递情报。只要无人挑衅，她便继续守望。",kw={"灰谷","艾萨拉","部落斥候","侦查骑兵更新","战歌氏族","战歌侦查骑兵"},ang={["faction:Alliance"]="尽管这名斥候效力于部落，但只要不受挑衅，她就不会向联盟旅人开火，让心怀戒备的旅人安然通过。",["faction:Horde"]="像她这样的侦查骑兵维持着补给与侦察路线的畅通，连接灰谷战火纷争的伐木作业区与艾萨拉荒野中的海岸。"},sec={{t="东部边境的哨卫",b="战歌侦查骑兵监视着灰谷与艾萨拉残破废墟之间的道路。远离碎木岗哨和伐木营地，她追踪着沿途的部队动向。她的弓箭和毒刺随时待命，但只会向攻击她的联盟入侵者开火。"}},faq={{q="在哪里可以找到战歌侦查骑兵？",a="她监视着灰谷东部通往艾萨拉的主干道。",al={"侦查骑兵位置","战歌侦查骑兵在哪","战歌侦查骑兵地图"}},{q="战歌侦查骑兵会一见到联盟玩家就发起攻击吗？",a="不会。除非途经此地的联盟旅人先动手，否则她不会攻击他们。",al={"她会主动攻击吗","战歌侦查骑兵会攻击联盟吗","战歌侦查骑兵仇恨"}},{q="她在战歌氏族的行动中承担什么职责？",a="她在灰谷与艾萨拉的边境侦察，留意威胁，并通过斥候向战歌氏族的首领传递前线报告。",al={"侦查骑兵做什么","战歌侦查骑兵职责","她为什么在这里"}},{q="击败战歌侦查骑兵能获得宝物吗？",a="不能。击败她不会获得任何战利品或特殊装备。这样做只能清除道路上的阻碍，或扰乱部落的侦察行动。",al={"战歌侦查骑兵战利品","她会掉落战利品吗","侦查骑兵掉落"}}},fp="16,223,28.276.0,40.73.0,59.66.0,50.135.0,55.120.0"}
P.entries["npc:watch-captain-parker"] = {n="Watch Captain Parker",s="在三角路口，帕克队长 守卫着道路，保护前往湖畔镇的旅人。他在路口巡逻，监视附近集结的豺狼人群，为进城的人们守住一道前沿防线。",h="在三角路口，帕克队长 守卫着道路，保护前往湖畔镇的旅人。他在路口巡逻，监视附近集结的豺狼人群，为进城的人们守住一道前沿防线。",kw={"达希","豺狼人","卫兵帕克","湖畔镇","帕克","赤脊山","三角路口","帕克队长"},ang={["faction:Alliance"]="作为联盟哨兵，Parker 让人看到兵力捉襟见肘的边防如何艰难地守护疆界。",["profession:Herbalism"]="作为草药师，你能从赤脊山山坡上盛开的鲜花中发现一份宁静的价值，那正是 Parker 想为达希寻来的花朵。",["race:Human"]="作为人类，你能从 Parker 身上看到一名普通哨兵，如何在举国危机中竭力维系王国边远村庄的安稳。"},sec={{t="驻守三角路口",b="在三角路口，帕克队长 看守着艾尔文森林、暮色森林和赤脊山之间的道路。暴风城能抽调的兵力寥寥，官方援助也很少抵达这片地区。帕克 和其他独自值守的哨兵必须确保路口不受匪徒、游荡的猛兽和劫掠的豺狼人侵扰。"},{t="评估豺狼人的威胁",b="帕克 岗哨北面和东面逐渐聚集的豺狼人营地引起了他的注意。随着豺狼人群步步逼近道路，他派身强体健的旅人前往湖畔镇，向菲尔顿副队长示警。赤脊山的豺狼人日益猖獗，威胁着补给车队和前往镇上寻求庇护的难民。"},{t="一丝温暖",b="独守路边岗哨难免凄凉，但善意依然能抵达三角路口。达希是湖畔镇旅店的侍者，她在 帕克 巡逻时为他送上一份热腾腾的午餐。帕克 被她的善意打动，请送餐的旅人去湖畔镇的草药师那里取一束花，再带回去交给达希。他叮嘱旅人，不要告诉草药师这束花是谁送的，又要送给谁。"}},faq={{q="卫兵帕克在哪里？",a="帕克 驻守在赤脊山西南部的三角路口，那里是道路交汇之处，靠近通往暮色森林和艾尔文森林的路口。",al={"帕克 位置","帕克 在哪里","寻找卫兵帕克"}},{q="帕克 为什么驻守在那么偏远的三角路口？",a="帕克 从三角路口出发，巡逻南面的道路，监视不断逼近的豺狼人群，协助维持通往湖畔镇的交通与补给路线畅通。",al={"帕克 职责","帕克 为何独自驻守","三角路口卫兵"}},{q="帕克 在赤脊山监视哪些威胁？",a="帕克 监视着威胁大道的赤脊山豺狼人，同时警惕石堡的黑石兽人和伊尔加拉之塔附近的暗皮豺狼人。",al={"赤脊山 的威胁","帕克 附近有哪些敌人","赤脊山 豺狼人威胁"}},{q="帕克 和达希是什么关系？",a="达希在湖畔镇旅店工作，会为驻守偏远岗哨的 帕克 送去热午餐。作为回报，帕克 请送餐的旅人去镇上的草药师那里为她取些鲜花，以表达谢意和爱慕之情。",al={"达希与 帕克","达希是谁","免费的午餐 任务背景"}},{q="帕克 为什么得不到暴风城的增援？",a="瓦里安·乌瑞恩国王失踪，首都政务陷入瘫痪，暴风城几乎无力援助赤脊山。当地的卫兵和地方官只能依靠四处游历的冒险者。",al={"为何没有暴风城军队","暴风城援助 赤脊山","帕克 的增援"}},{q="卫兵帕克提供哪些任务？",a="帕克 请旅人前往湖畔镇，向菲尔顿副队长报告道路附近逐渐聚集的豺狼人营地。他还托人将鲜花送到湖畔镇旅店，交给达希。",al={"帕克 的任务","帕克 提供的任务"}}},fp="20,182,25.305.0,26.279.0,17.366.0,30.139.0,57.155.0,46.156.0,41.222.0,57.187.0,36.182.0"}
P.entries["npc:watcher-backus"] = {n="守夜人巴库斯",s="守夜人巴库斯沿着暮色森林的道路警戒，留意危险，以及与暴风城政治阴谋有关的可疑往来。他在夜色镇与密斯特曼托庄园之间巡逻，搜寻亡灵和行踪诡异的旅人。",h="守夜人巴库斯沿着暮色森林的道路警戒，留意危险，以及与暴风城政治阴谋有关的可疑往来。他在夜色镇与密斯特曼托庄园之间巡逻，搜寻亡灵和行踪诡异的旅人。",kw={"巴库斯","夜色镇","暮色森林","密斯特曼托庄园","守夜人","失踪的使节","守夜人巴库斯"},ang={["faction:Alliance"]="对于追查失踪外交官的联盟密探而言，巴库斯是一位关键联络人，掌握着边境一线的情报。",["race:Human"]="身为人类，巴库斯展现了暮色森林守卫者的坚韧，即使遭到王都遗弃，仍决心守住道路。"},sec={{t="阴影中的巡逻",b="在夜色镇以北，守夜人巴库斯独自巡逻，途经密斯特曼托庄园。和守夜人的其他成员一样，他艰难地对抗着暮色森林的诅咒。暴风城的驻军几乎帮不上忙，当地志愿者只能独自守卫雾气笼罩的小径。巴库斯沿路抵御野兽和食尸鬼。"},{t="道路上的眼线",b="守夜人巴库斯独自巡逻时，能看到许多绕过夜色镇的往来行人。王室调查员追查一位高级外交官的失踪案，来到南方时，他想起了 阿德尔农场 周围反常的迪菲亚活动。"}},faq={{q="守夜人巴库斯是谁？",a="守夜人巴库斯是一名人类卫兵，隶属于处境艰难的守夜人，这支民兵负责保卫夜色镇和暮色森林的道路。",al={"巴库斯是谁","守夜人巴库斯职责","巴库斯暮色森林"}},{q="在哪里能找到守夜人巴库斯？",a="守夜人巴库斯在暮色森林中巡逻，路线沿着夜色镇向北通往密斯特曼托庄园的大路。",al={"巴库斯在哪里","巴库斯位置","巴库斯巡逻路线"}},{q="守夜人是什么？",a="守夜人是暴风城撤走正规驻军后，暮色森林居民为抵御亡灵、狼人和凶猛野兽而组建的当地志愿民兵。",al={"守夜人是什么","守夜人暮色森林","夜色镇卫兵"}},{q="巴库斯与失踪的使节有何关联？",a="在寻找一位失踪的暴风城外交官时，线索将冒险者引向暮色森林。守夜人巴库斯回忆起近期 阿德尔的农场 周围的迪菲亚活动，并协助查验从他们在那里的藏身处找回的文件。",al={"巴库斯失踪外交官","失踪外交官任务巴库斯"}},{q="镇上有什么关于守夜人巴库斯的传闻吗？",a="夜色镇的另一位卫兵守夜人布隆尼尔暗恋巴库斯，却从未表白，这在阴郁的镇上是一桩难得的轻松谈资。",al={"巴库斯布隆尼尔","守夜人布隆尼尔暗恋"}},{q="巴库斯为什么独自在密斯特曼托庄园附近巡逻？",a="守夜人的人手分散在整片领地，捉襟见肘，几乎抽不出身强力壮的守卫。像巴库斯这样的守夜人，只能独自走完漫长而危险的巡逻路线。",al={"为何独自巡逻","巴库斯危险"}}},fx={cd7ae440={q="守夜人巴库斯效忠哪一方？",a="守夜人巴库斯坚定地支持守夜人和饱受困苦的夜色镇居民。作为暮色森林尽职尽责的当地守卫之一，他为联盟效力，听命于镇上的领导者，日夜冒险巡行于阴暗的道路，保护旅人和居民免遭潜伏在幽暗中的贪婪恐怖之物侵袭。",al={"巴库斯阵营","守夜人巴库斯为谁效力","守夜人巴库斯效忠谁"}},f48ed911={q="守夜人巴库斯想要什么？",a="巴库斯想守护暮色森林道路的安全，让这片被暴风城军队遗弃的土地得到正义。当旅人或调查者将麻烦带到他面前时，他专注于排查危险的嫌疑人，清除巡逻路线上的亡灵，并确保夜色镇饱受困苦的居民能够生存下去。",al={"守夜人巴库斯的目标","巴库斯想做什么","巴库斯的动机"}},["8919f8c2"]={q="守夜人巴库斯与谁有关联？",a="除了与他一同巡逻幽暗森林的守夜人战友，巴库斯还引起了同为守卫的守夜人布隆尼尔的注意，后者对他的爱慕之情显而易见。他也与调查道路沿线可疑活动的探员协调行动，因此直接参与了涉及暴风城的更广泛调查。",al={"守夜人巴库斯的人脉","谁认识守夜人巴库斯","守夜人巴库斯的关系"}}},fp="14,221,23.298.0,16.228.1,22.119.0,34.94.0,24.184.0,49.220.1,57.148.0,51.176.0"}
P.entries["npc:watcher-dodds"] = {n="守夜人道茨",s="在暮色森林中央的十字路口，守夜人道茨为守夜人站岗。他在路边的哨所监视危险，并请旅人减少巨型蜘蛛的数量。",h="在暮色森林中央的十字路口，守夜人道茨为守夜人站岗。他在路边的哨所监视危险，并请旅人减少巨型蜘蛛的数量。",kw={"阿尔泰娅·埃伯洛克","十字路口","夜色镇","暮色森林","守夜人","蜘蛛","守夜人道茨"},ang={["faction:Alliance"]="对穿越暮色森林的联盟旅人来说，在夜色镇与西部地区之间的黑暗道路上，守夜人道茨的营火标示着少数几处能获得友方援助的安全地点之一。"},sec={{t="十字路口的守望",b="守夜人道茨听命于指挥官阿尔泰娅·埃伯洛克，为守夜人守卫十字路口。他的哨所位于夜色镇、乌鸦岭和逆风小径三条道路的交汇处。夜色镇的木栅保护着镇子，而道茨则在木栅之外站岗，周围尽是狼群、饥饿的食尸鬼和硕大的蜘蛛。他在路边的营地监视威胁，并请过路的雇佣兵杀死从灌木丛中涌出的蜘蛛，以免它们占据道路。"}},faq={{q="守夜人道茨是谁？",a="守夜人道茨是守夜人的一名人类成员，这支民兵队伍保护暮色森林，抵御肆虐当地的亡灵和野兽。他驻守在中央十字路口，那里不在夜色镇的庇护之下。",al={"守夜人道茨","道茨是谁","道茨 暮色森林"}},{q="在哪里可以找到守夜人道茨？",a="守夜人道茨在暮色森林中央的主要十字路口旁设有一处小营地。来自夜色镇、乌鸦岭和南部山口的道路在此交汇。",al={"守夜人道茨位置","道茨在哪里","道茨坐标"}},{q="他为什么要人猎杀蜘蛛？",a="巨型毒蜘蛛遍布周围的树林，捕食沿路往来的旅人和运送补给的信使。守夜人道茨请过路的冒险者减少结网毒蜘蛛的数量，以免它们让道路无法通行。",al={"八足的威胁","道茨蜘蛛任务","为什么猎杀蜘蛛"}},{q="守夜人道茨听命于谁？",a="守夜人道茨听命于指挥官阿尔泰娅·埃伯洛克，她在夜色镇的镇公所领导守夜人。",al={"道茨的指挥官","谁领导守夜人"}}},fp="13,187,23.444.0,21.207.0,31.159.0,32.217.0,33.106.0"}
P.entries["npc:wilder-thistlenettle"] = {n="维尔德·蓟草",s="在暴风城的矮人区，维尔德·蓟草独自饮酒，沉浸在往日的悲痛中。他曾与兄弟和采矿队一同进入月溪镇的死亡矿井，但一场塌方让他成了唯一的幸存者。",h="在暴风城的矮人区，维尔德·蓟草独自饮酒，沉浸在往日的悲痛中。他曾与兄弟和采矿队一同进入月溪镇的死亡矿井，但一场塌方让他成了唯一的幸存者。",kw={"兄弟","塌方","死亡矿井","矮人区","矿工","暴风城","蓟草","怀尔德"},ang={["profession:Mining"]="身为矿工，你知道不稳固的地层即使面对经验丰富的采矿队，也能将他们埋葬在地下深处。",["race:Dwarf"]="身为矮人，Wilder的悲痛让你想起深入挖掘的危险，以及缅怀遇难公会兄弟的责任。"},sec={{t="悲苦的幸存者",b="维尔德·蓟草在矮人区东南大门附近的一家酒馆里借酒浇愁。多年前，他与兄弟和同伴们一同深入月溪镇死亡矿井的矿脉。一场塌方将其余矿工封在地下，维尔德勉强活着逃回了地面。"},{t="深处的幽魂",b="维尔德的兄弟和遇难的采矿队化作不得安息的亡灵，在死亡矿井中徘徊。黑暗魔法或未了的心愿将他们束缚在地下废墟中。悲痛与愧疚压在维尔德心头，他请求前往矿井的旅人寻回死者的遗物，让他的兄弟得以安息。"}},faq={{q="在哪里可以找到维尔德·蓟草？",a="维尔德坐在暴风城矮人区的一家安静酒馆里，从该区东南入口进去，右手边便是。",al={"维尔德·蓟草 位置","维尔德 在哪里","蓟草 暴风城"}},{q="他的兄弟在死亡矿井遭遇了什么？",a="矿道突然坍塌，将维尔德的兄弟和其他矿工困在其中。维尔德逃了出来，如今仍在打听那些被困地下的人的消息。",al={"维尔德 兄弟 死亡矿井","兄弟遭遇了什么","蓟草 兄弟 背景故事"}},{q="维尔德为什么需要冒险者的帮助？",a="维尔德请求进入死亡矿井的旅人找回遇难矿工各自的矿业工会徽章，并调查他兄弟的遭遇。",al={"维尔德 任务","维尔德 想要什么","收集记忆 任务"}}},fp="20,209,17.303.0,18.298.1,38.127.0,46.125.0,33.152.0"}
P.entries["npc:wiley-the-black"] = {n="黑衣威利",s="黑衣威利待在湖畔镇旅店，远离是非。他欠格里安·斯托曼一条命，也会透露自己掌握的迪菲亚潜行者情报。",h="黑衣威利待在湖畔镇旅店，远离是非。他欠格里安·斯托曼一条命，也会透露自己掌握的迪菲亚潜行者情报。",kw={"迪菲亚潜行者","格里安·斯托曼","线人","湖畔镇","赤脊山","威利","黑衣威利"},ang={["class:Rogue"]="身为盗贼，威利展现了如何靠谋生手段和情报保住性命。他知道何时该用情报做交易，也知道该报答谁。",["faction:Alliance"]="暴风城的军队不在，联盟只能依靠威利这样的非官方线人，拼凑出西部荒野叛乱的全貌。"},sec={{t="无赖的人情债",b="黑衣威利一直待在湖畔镇旅店，远离西部荒野的动荡，也避开赤脊山豺狼人肆虐的边境。人民军的指挥官格里安·斯托曼曾救过他的命。斯托曼抱怨说，当初就该任由威利自生自灭。因此，当民兵需要了解迪菲亚潜行者的阴谋时，就会找上威利。他虽不情愿，还是会透露秘密情报，偿还这份人情。"}},faq={{q="在哪里可以找到黑衣威利？",a="黑衣威利就在湖畔镇旅店里，这家旅店位于赤脊山的湖畔镇。",al={"威利位置","黑衣威利在哪里","威利赤脊山","湖畔镇旅店威利"}},{q="威利为什么要帮助格里安·斯托曼？",a="格里安·斯托曼曾救过威利的命。威利用迪菲亚潜行者的情报偿还这份人情，尽管他并不愿意以身犯险。",al={"为什么帮助格里安","威利与格里安的关系","威利欠斯托曼的人情"}},{q="威利为什么了解迪菲亚潜行者？",a="威利熟悉地下世界，也很了解迪菲亚潜行者的行动。他为了报答格里安·斯托曼而透露自己掌握的情报，但他是否曾是这个组织的一员，尚无定论。",al={"威利是迪菲亚潜行者成员吗","威利为什么了解迪菲亚潜行者","威利与迪菲亚潜行者的联系"}},{q="他在调查迪菲亚潜行者的过程中起什么作用？",a="当人民军掌握了指向更大阴谋的线索时，斯托曼便派冒险者前往湖畔镇，给威利捎去口信。威利分析局势后写下一张便笺，指引民兵追查叛乱的首领。",al={"威利的任务作用","威利做什么","迪菲亚潜行者威利"}}},fx={["03fe7b6d"]={q="黑衣威利是谁？",a="黑衣威利是个行迹可疑的潜行者，目前住在湖畔镇的旅店里。他是个与不法之徒往来密切的无赖，对于迪菲亚潜行者及其遍布人类诸王国的秘密行动，掌握着出人意料的深层内幕。",al={"威利是谁","黑衣威利的故事","关于黑衣威利"}},["7107b7b4"]={q="黑衣威利效忠哪一方？",a="威利主要顾着自己的利益，与联盟的正式政治事务保持距离。不过，格里安·斯托曼曾救过他的命，因此威利愿意协助人民军对抗迪菲亚，偿还这份私人的恩情。",al={"威利是否效忠联盟","黑衣威利阵营","黑衣威利效忠谁"}},["72fbb4af"]={q="黑衣威利想要什么？",a="威利想还清欠格里安·斯托曼的恩情，并远离麻烦。提供有关迪菲亚潜行者的重要情报，就能履行他对格里安的义务，让他既能偿还人情，又能与西部荒野的战事保持安全距离。",al={"威利想要什么","黑衣威利的目标","威利为何帮忙"}},["9b688ede"]={q="黑衣威利为何身在赤脊山？",a="威利住进了湖畔镇旅店楼上的客房，远离西部荒野，也避开了暴风城当局直接管辖的范围。留在赤脊山让他能保持低调，同时留心各方消息。",al={"威利为何在湖畔镇","威利为何在这里","威利在赤脊山"}}},fp="15,151,18.384.0,33.91.0,39.152.0,49.173.0,51.234.0"}
P.entries["npc:willem"] = {n="Willem",s="在北郡修道院外，维里派遣新兵应对山谷中逐渐聚集的威胁。他听命于治安官玛克布莱德，此时迪菲亚潜行者正向北郡进逼。",h="在北郡修道院外，维里派遣新兵应对山谷中逐渐聚集的威胁。他听命于治安官玛克布莱德，此时迪菲亚潜行者正向北郡进逼。",kw={"迪菲亚","维里副队长","艾尔文森林","加瑞克·帕德弗特","治安官玛克布莱德","北郡","北郡修道院","维里"},ang={["class:Warrior"]="作为一名战士，你可以听从维里的指挥，驱逐强盗，为王国恢复秩序。",["faction:Alliance"]="作为联盟的一员，你可以通过维里了解到，迪菲亚引发的动乱甚至波及了艾尔文宁静的腹地。",["race:Human"]="作为一名走出北郡修道院的人类，你可能会遇见维里副队长。他是最早欢迎你为王国效力的暴风城军官之一。"},sec={{t="修道院的守卫",b="维里副队长守卫着北郡修道院的大门，暴风城军队在此驻守，维系着在山谷中的据点。王国的士兵分散在各地，因此治安官玛克布莱德麾下这样的小股驻军必须保卫周边地区。\n\n维里迎接前来的志愿者，派他们援助居民，并守卫山谷边缘。"},{t="对抗迪菲亚",b="迪菲亚潜行者是维里眼下最迫切的心腹之患。蒙着红色面巾的强盗闯入北郡，偷走补给，威胁农夫米莉·奥斯沃斯，还在附近的葡萄园和山丘间建立了据点。\n\n维里悬赏缉拿加瑞克·帕德弗特等臭名昭著的亡命之徒。他希望在这些强盗占领修道院之前，先瓦解他们的头目势力。"}},faq={{q="维里副队长是谁？",a="维里副队长在艾尔文森林的北郡修道院外服役，隶属暴风城军队。他听命于治安官玛克布莱德，指挥新兵应对山谷中的威胁。",al={"维里 是谁","维里副队长职责","维里 北郡"}},{q="维里副队长听命于谁？",a="维里副队长听命于治安官玛克布莱德，后者负责指挥北郡山谷的防御和军事行动。",al={"维里 指挥官","维里 的上司是谁","维里 领袖"}},{q="维里为何悬赏缉拿迪菲亚？",a="迪菲亚潜行者已经进入北郡山谷，威胁修道院，恐吓当地劳工。维里派遣战斗人员追捕强盗，以及加瑞克·帕德弗特等头目，以恢复秩序。",al={"为何悬赏 迪菲亚","维里 红色面罩","维里 迪菲亚"}},{q="在哪里可以找到维里副队长？",a="维里在艾尔文森林北部的北郡修道院正门外等候。他在那里迎接进入庭院的旅人和新兵。",al={"维里 位置","维里副队长在哪里","寻找 维里"}},{q="维里如何帮助当地劳工？",a="维里派遣战斗人员援助生计受到威胁的居民，其中包括果农米莉·奥斯沃斯和剥皮工伊根。",al={"维里 米莉·奥斯沃斯","维里 伊根","维里 任务"}},{q="为何维里这样的军人难以独力维持秩序？",a="暴风城面临内部困境、政治紧张局势，以及远方的军事任务。随着瓦里安国王失踪，北郡等地的驻军只能依靠缺乏实战经验的新兵和志愿者，处理国内的动乱。",al={"暴风城军队为何薄弱","北郡 为何缺乏防守","暴风城 北郡 兵力"}}},fx={cea9f32f={q="维里副队长效忠哪一方？",a="维里副队长是暴风城军队的一名忠诚士兵，为联盟效力。他在北郡修道院外站岗，维护王国的法律，并指引身强力壮的新兵保卫山谷，抵御强盗和窃贼。",al={"维里阵营","维里副队长为谁效力","维里属于联盟还是部落"}},["29d9c6b5"]={q="维里副队长为何来到北郡？",a="维里副队长驻守在北郡修道院外，维持秩序，并将新兵派往最需要他们的地方。王国的防御兵力捉襟见肘，他作为主要联络人，组织山谷居民应对当地的威胁。",al={"维里为何在北郡","维里为何来到这里","维里副队长的职责"}}},fp="6,175,23.342.0,22.354.0,21.159.0,33.107.0,45.197.0,33.148.0,41.130.0,62.209.0"}
P.entries["npc:william-pestle"] = {n="威廉·匹斯特",s="在闪金镇的狮王之傲旅店，威廉·匹斯特为暴风城的药剂店收集物资。他和兄弟摩根共同经营着贸易区的店铺。威廉雇用旅人寻找蜡烛、海藻和草药。",h="在闪金镇的狮王之傲旅店，威廉·匹斯特为暴风城的药剂店收集物资。他和兄弟摩根共同经营着贸易区的店铺。威廉雇用旅人寻找蜡烛、海藻和草药。",kw={"药剂店","收集海藻","闪金镇","狗头人蜡烛","狮王之傲旅店","马科伦","摩根·匹斯特","匹斯特","斯通菲尔德","威廉·匹斯特"},ang={["faction:Alliance"]="威廉协助为暴风城的贸易区供应药品和其他货物。他依靠途经闪金镇的联盟新兵，从周围的森林中收集材料。",["profession:Herbalism"]="身为闪金镇的草药师，你可以看到采集植物如何为威廉的生意提供帮助。他将野生植物和奇特的水生海藻调制成实用的药剂。"},sec={{t="在外奔走的药剂师",b="威廉在闪金镇的狮王之傲旅店开展工作。他的兄弟摩根·匹斯特在暴风城贸易区的匹斯特的药剂店照看柜台。在艾尔文森林，威廉与当地的采集者合作，为城里的店铺筹集原料。他定期向暴风城运送物资，那里的居民需要能帮助恢复的药膏、药水和药粉。"},{t="奇特的材料",b="普通的园圃草药并不总能满足威廉的需要。他雇用初来乍到的冒险者，收集艾尔文森林的狗头人携带的蜡烛，以及闪金镇东边水晶湖中鱼人身上的水晶海藻。对于不熟悉炼金术的人来说，这些材料或许显得古怪。威廉相信，将它们调配在一起能产生强大的效力。"},{t="为年轻恋人调制的药水",b="威廉是米尔德·斯通菲尔德的老朋友。当梅贝尔·马科伦和托米·乔·斯通菲尔德陷入两家的深仇之中时，威廉答应调制一份隐形水。配方中用到了从当地水域采集的海藻。它能让梅贝尔悄悄溜出去，与托米·乔见面。"}},faq={{q="威廉·匹斯特是谁？",a="威廉·匹斯特是一名炼金师，在闪金镇的狮王之傲旅店开展工作。他和兄弟摩根为暴风城的药剂店收集并配制物资。",al={"威廉·匹斯特","闪金镇炼金师","匹斯特是谁"}},{q="在哪里能找到威廉·匹斯特？",a="在艾尔文森林闪金镇的狮王之傲旅店内，可以找到威廉·匹斯特。",al={"匹斯特位置","威廉·匹斯特在哪里","威廉·匹斯特 闪金镇"}},{q="威廉用狗头人的蜡烛做什么？",a="威廉收集艾尔文森林矿洞中狗头人携带的蜡烛。他将蜡烛熔化，提炼其中的油脂，用于炼金配方和药剂店的备货。",al={"匹斯特为什么要蜡烛","狗头人蜡烛用途"}},{q="威廉为什么需要水晶海藻？",a="威廉用艾尔文森林当地湖泊中的水晶海藻调制隐形水。它能帮助梅贝尔·马科伦避开家人，去见托米·乔·斯通菲尔德。",al={"为什么收集海藻","鱼人海藻用途"}},{q="威廉·匹斯特与暴风城有什么联系？",a="威廉和兄弟摩根共同经营着暴风城贸易区的药剂店。威廉在闪金镇收集材料，再将物资运往城里的店铺。",al={"匹斯特 暴风城","威廉·匹斯特 药剂店"}},{q="威廉与斯通菲尔德和马科伦两家有什么关系？",a="威廉是米尔德丽德·斯通菲尔德的老朋友。他调制了一种能隐匿身形的饮剂，帮助托米·乔·斯通菲尔德和梅贝尔·马科伦避开两家的深仇。",al={"斯通菲尔德 马科伦 匹斯特","威廉·匹斯特 爱情任务"}}},fx={["520b1b0a"]={q="威廉·匹斯特效忠哪一方？",a="威廉是暴风城王国的忠诚子民，也是引以为荣的联盟一员。他以狮王之傲旅店为据点，运用炼金术知识、调制药剂，并帮助当地居民解决日常难题，为乡邻服务。",al={"威廉·匹斯特阵营","威廉·匹斯特是否属于联盟","威廉·匹斯特效忠谁"}},["2d067923"]={q="威廉·匹斯特想要什么？",a="威廉为自己的炼金配方寻找稀有而非寻常的材料。他经常招募过路的冒险者，收集大量狗头人蜡烛以获取蜡料，并从当地湖泊采集水晶海藻，将这些材料用于酿制强效隐形水等药剂。",al={"威廉·匹斯特需要什么","威廉·匹斯特的目标","威廉·匹斯特的材料"}},["8d6a9bd2"]={q="威廉·匹斯特为何身在闪金镇？",a="威廉和他的兄弟摩根在暴风城的贸易区经营一家药剂店，而威廉留在闪金镇的狮王之傲旅店，亲自采集乡间材料，并帮助艾尔文乡间的老朋友，例如米莱德 斯通菲尔德。",al={"威廉·匹斯特为何在这里","威廉为何在闪金镇","威廉·匹斯特为何在狮王之傲旅店"}}},fp="14,217,17.362.0,16.322.0,27.292.1,22.167.0,34.87.0,41.154.0,35.157.1,54.164.0,58.160.1"}
P.entries["npc:williden-marshal"] = {n="威利德·马绍尔",s="威利德·马绍尔是 马绍尔探险队 雄心勃勃的人类领袖，以安戈洛环形山北部的马绍尔营地为据点。珍稀植物、神秘水晶和有利可图的科学研究吸引着他，他带领团队进入环形山，却只能眼看着低地营地被盆地中的巨兽攻陷。",h="威利德·马绍尔是 马绍尔探险队 雄心勃勃的人类领袖，以安戈洛环形山北部的马绍尔营地为据点。珍稀植物、神秘水晶和有利可图的科学研究吸引着他，他带领团队进入环形山，却只能眼看着低地营地被盆地中的巨兽攻陷。",kw={"魔暴龙","马绍尔探险队","马绍尔营地","能量水晶","斯巴克·尼米尔","安戈洛环形山","威利德·马绍尔"},ang={["faction:Alliance"]="虽然在荒蛮的环形山中，威利德和他的核心团队迫于形势保持中立，但他们与联盟腹地仍有着深厚的文化和贸易联系。",["profession:Herbalism"]="威利德的考察队来到安戈洛，很大程度上是受环形山独特的史前植物吸引，这些植物在艾泽拉斯的其他地方都无法生长。",["race:Human"]="威利德从东部王国远道而来，深入卡利姆多南部未经驯服的腹地，体现了人类探索远方的好奇心和追逐商机的雄心。"},sec={{t="岌岌可危的立足之地",b="威利德·马绍尔带领整支科学考察队深入安戈洛环形山，寻求财富与发现。关于奇异水晶、未被编目的植物和未开发资源的传闻引起了他的兴趣，于是他在谷底各处建立了多座前哨营地。然而，这片原始荒野很快便向他们露出了獠牙。环形山中的凶猛野兽摧毁了他们的研究站，迫使威利德和幸存者退往北部峭壁，在那里建立了马绍尔营地。"},{t="挽救梦想",b="尽管被逼退到环形山边缘的山地，威利德仍不肯收拾行装，放弃自己的投入。他在相对安全的营地雇用过路的冒险者，请他们重返凶险的低地，找回遗失的食物箱、昂贵的科学仪器和他个人的考察日志。虽然斯巴克·尼米尔等亲密同伴常常只叫他“威利”，但他对这次考察十分认真——即使巨大的掠食者仍在下方山谷中游荡，他也坚持要找回他们的研究成果。"},{t="家族纽带",b="威利德并非环形山中唯一的 马绍尔 家族成员：霍莱伊·马绍尔与他同姓，在马绍尔营地与他并肩工作。他们一同选择了卡利姆多南部这片未经驯服的原始环形山，而威利德始终坚信，安戈洛的水晶矿藏和古老谜团蕴藏着真正的财富。"}},faq={{q="威利德·马绍尔是谁？",a="威利德·马绍尔是一名人类探险家，也是 马绍尔探险队 的指挥官。他带领一支由研究人员和冒险者组成的队伍进入安戈洛环形山，研究那里的奇异水晶和植物，寻求知识与利润。",al={"威利德·马绍尔是谁","威利德·马绍尔背景故事","谁领导马绍尔营地"}},{q="考察队为什么躲在洞穴里？",a="考察队最初在安戈洛的低地建立了多座研究基地。然而，考察队低估了安戈洛的凶险，环形山中的巨大掠食者攻陷了这些据点，迫使幸存者逃往北部岩台上的马绍尔营地。",al={"营地为何在洞穴里","考察队营地遭遇了什么","马绍尔 为何撤退"}},{q="威利德请冒险者做什么？",a="威利德请有能力的探险者冒险深入危机四伏的环形山盆地，从被毁的营地中找回补给，包括遗弃的食物储备、精密的研究设备，以及他遗失的考察日志。",al={"威利德 任务","抢救物资","威利德 想要什么"}},{q="威利德最初为什么来到安戈洛环形山？",a="他为寻找环形山独有的资源而来：珍稀植物、神秘的彩色能量水晶、古老的地质秘密，以及科学发现带回故乡后所能带来的丰厚利润。",al={"为何来到 安戈洛","威利德·马绍尔的动机","马绍尔 在研究什么"}},{q="威利德有家人吗？",a="有。他的姐妹霍莱伊·马绍尔也是马绍尔探险队的一员，在马绍尔营地与他并肩工作。",al={"威利德 的兄弟","利文斯顿·马绍尔","马绍尔 家族"}},{q="威利德·马绍尔属于联盟还是部落？",a="虽然身为人类，威利德却在马绍尔营地主持着一支中立的科学考察队。只要冒险者愿意找回他的补给并清除环形山中的威胁，无论来自联盟还是部落，他都乐于接受帮助。",al={"威利德 属于联盟吗","部落能与 威利德 交谈吗","马绍尔营地阵营"}}},fp="16,223,21.370.0,19.393.0,11.242.0,24.208.0,41.181.0,42.170.0,59.165.0,30.123.0,55.182.0"}
P.entries["npc:winna-hazzard"] = {n="温娜·哈萨德",s="温娜·哈萨德是一位古怪的被遗忘者研究员，驻扎在费伍德森林的血毒岗哨。她身边有一只猫作伴，时常发出狂笑，研究着这片染疫的生态环境，并用当地遭到腐化的动物进行令人不安的实验。",h="温娜·哈萨德是一位古怪的被遗忘者研究员，驻扎在费伍德森林的血毒岗哨。她身边有一只猫作伴，时常发出狂笑，研究着这片染疫的生态环境，并用当地遭到腐化的动物进行令人不安的实验。",kw={"血毒岗哨","费伍德森林","被遗忘者","小猫","温娜·哈萨德"},ang={["faction:Horde"]="温娜安稳地驻扎在血毒岗哨，招募过往的部落旅人为她收集受腐化的试剂，用于她那些离奇的研究。",["race:Undead"]="温娜体现了被遗忘者古怪性情中阴暗的一面，对腐化表现出不计后果的好奇，全然不顾自然的和谐。"},sec={{t="古怪的研究员",b="温娜·哈萨德代表着被遗忘者对费伍德森林异常衰败现象的关注。她驻扎在部落据点血毒岗哨，平日里观察当地的野生动物，构思利用受污染的水和带毒样本进行的实验。她快活而癫狂的举止往往掩盖着冷酷的动机，她用取自这片土地的污浊液体腐化身旁的小猫，便是明证。"}},faq={{q="温娜·哈萨德是谁？",a="温娜·哈萨德是一名被遗忘者任务发布者，位于费伍德森林中北部的血毒岗哨。她调查着费伍德森林中的腐化力量，并委托冒险者从荒野中收集样本。",al={"温娜·哈萨德","温娜是谁","费伍德森林的养猫女人"}},{q="她的小猫遭遇了什么？",a="当冒险者从周围的树林中为温娜带回一满瓶腐化液体时，她会直接将其喂给自己的宠物小猫，使它变异为被腐蚀的猫，随后发出狂笑。",al={"温娜的小猫","被腐蚀的猫","费伍德森林的猫实验"}},{q="温娜·哈萨德在费伍德森林有什么目的？",a="与许多被遗忘者药剂师和学者一样，温娜试图理解并驾驭生物疫病，利用费伍德森林无处不在的腐化，研究它如何改变并扭曲活生生的野兽。",al={"温娜·哈萨德的动机","温娜为什么在费伍德森林"}}},fp="13,226,21.289.0,21.145.0,27.201.1,40.174.0"}
P.entries["npc:winstone-wolfe"] = {n="温斯顿·沃尔菲",s="在拉文霍德庄园，温斯顿·沃尔菲看守着庄园的庭院。这名人类特工隶属于乔拉齐·拉文霍德公爵的秘密组织，该组织隐匿在希尔斯布莱德与奥特兰克山脉之间。",h="在拉文霍德庄园，温斯顿·沃尔菲看守着庄园的庭院。这名人类特工隶属于乔拉齐·拉文霍德公爵的秘密组织，该组织隐匿在希尔斯布莱德与奥特兰克山脉之间。",kw={"奥特兰克","希尔斯布莱德","拉文霍德","拉文霍德庄园","潜行者","温斯顿·沃尔菲"},ang={["class:Rogue"]="身为潜行者，你或许知道温斯顿·沃尔菲是拉文霍德庄园的一名特工，潜行者们会深入群山，来到这里，在组织中磨炼技艺。"},sec={{t="山中的办事人",b="温斯顿·沃尔菲在拉文霍德庄园为乔拉齐·拉文霍德公爵的组织效力。他沉默而警觉，处理庄园周边的事务，监视庭院及其管理员。只有行事谨慎且身怀才能的人，才能在那里不受干扰地行走。"}},faq={{q="温斯顿·沃尔菲是谁？",a="温斯顿·沃尔菲是一名在拉文霍德庄园效力的人类潜行者。这座庄园是刺客联盟的隐秘总部，高踞于希尔斯布莱德丘陵与奥特兰克山脉之上。",al={"沃尔菲是谁","温斯顿·沃尔菲的故事","拉文霍德沃尔菲"}},{q="在哪里可以找到温斯顿·沃尔菲？",a="温斯顿·沃尔菲位于拉文霍德庄园，从希尔斯布莱德丘陵的敦霍尔德城堡一带出发，沿着一条向北蜿蜒穿过群山的秘道即可抵达。",al={"沃尔菲的位置","温斯顿·沃尔菲在哪里","寻找温斯顿·沃尔菲"}},{q="他在拉文霍德担任什么职务？",a="温斯顿·沃尔菲在庄园周边担任特工和守卫，看守庭院，并协助处理组织的后勤事务。",al={"沃尔菲做什么","沃尔菲的职责"}}},fp="14,179,24.252.0,22.165.0,32.149.0,31.138.0"}
P.entries["npc:witch-doctor-jin-zil"] = {n="巫医金吉尔",s="在玛拉卡金，巫医金吉尔用黑暗巫毒对付部落的敌人。这位黑暗之矛巨魔秘术师住在石爪山脉南部的一处洞穴中，是达索克·快刀和暗影猎手洛克汉的老战友。",h="在玛拉卡金，巫医金吉尔用黑暗巫毒对付部落的敌人。这位黑暗之矛巨魔秘术师住在石爪山脉南部的一处洞穴中，是达索克·快刀和暗影猎手洛克汉的老战友。",kw={"达索克","金吉尔","玛拉卡金","洛克汉","石爪山","巫毒","巫医"},ang={["faction:Horde"]="作为部落的一员，当部落巩固石爪山南部道路的控制时，你可以依靠金吉尔与哨站的斥候一道，提供秘术防护和情报支援。",["race:Troll"]="作为巨魔，你看到金吉尔将黑暗之矛巫医的技艺带入卡利姆多崎岖的荒野。他与洛克汉等显赫人物有着深厚的交情。"},sec={{t="玛拉卡金的隐士",b="在玛拉卡金东面的一处洞穴中，金吉尔远离部族的海滨家园，研习丛林巨魔的古老技艺。他的洞穴里摆满了冒泡的坩埚，还关押着俘虏。他从石爪山的峭壁间收集奇异的施法材料，编织祝福与诅咒，保卫部落的山间营地。"},{t="值得信赖的老兵",b="金吉尔是部落资深斥候达索克·快刀和暗影猎手洛克汉的老朋友。达索克率队在前线与暗夜精灵和鹰身人交战。金吉尔则以灵魂之力和炼金术参战，用森林魔法和不稳定的巫毒削弱威胁，让敌人尚未抵达营地大门就已受挫。"}},faq={{q="在哪里可以找到巫医金吉尔？",a="金吉尔住在玛拉卡金东侧的一处洞穴中，玛拉卡金是位于石爪山脉南部隘口的部落定居点。",al={"金吉尔位置","金吉尔在哪里","金吉尔洞穴"}},{q="金吉尔与洛克汉和达索克·快刀有什么关系？",a="金吉尔是达索克·快刀和暗影猎手洛克汉信赖多年的老朋友。每当出现异常威胁，石爪山各处的斥候都会仰仗他的魔法。",al={"金吉尔的朋友","达索克与金吉尔","与洛克汉的关系"}},{q="金吉尔为什么在洞穴里关押囚犯？",a="金吉尔在洞穴工坊的笼子里关押着被俘的敌人。他利用俘虏和未经加工的施法材料试验诅咒、占卜预兆，并为定居点制作防御用的巫毒物品。",al={"金吉尔的囚犯","金吉尔的笼子","金吉尔为什么关押俘虏"}},{q="他会给部落冒险者什么样的任务？",a="他派旅行者前往石爪山各处，收集用于森林魔法和巫毒仪式的神秘材料。",al={"金吉尔任务","金吉尔想要什么"}}},fp="20,236,24.297.0,17.296.0,38.112.0,62.156.0,44.176.0,53.112.0"}
P.entries["npc:witch-doctor-uzer-i"] = {n="巫医尤克里",s="巫医尤克里是一名丛林巨魔秘术师，居住在菲拉斯原始森林中的莫沙彻营地。他致力于增强部落的魔法力量，研究捕获并利用灵魂精华的方法，那是强大自然生物的灵魂精华。尤克里试图捕获这些古老的森林之灵，将暗夜精灵历来倚重的原始能量直接注入附魔武器。",h="巫医尤克里是一名丛林巨魔秘术师，居住在菲拉斯原始森林中的莫沙彻营地。他致力于增强部落的魔法力量，研究捕获并利用灵魂精华的方法，那是强大自然生物的灵魂精华。尤克里试图捕获这些古老的森林之灵，将暗夜精灵历来倚重的原始能量直接...",kw={"莫沙彻营地","精灵龙","菲拉斯","山岭巨人","灵魂","尼尔鲁·火刃","树人","尤克里","巫医"},ang={["class:Shaman"]="萨满祭司会认出尤克里对沟通灵魂的执着，不过，他强行禁锢元素与荒野精华的做法，更偏向强硬的巫术，而非心怀敬畏地维持平衡。",["faction:Horde"]="尤克里为部落提供了掌握卡利姆多荒野原始魔法的途径，将这片土地的灵魂力量用于对付暗夜精灵等联盟盟友。",["race:NightElf"]="暗夜精灵视尤克里的做法为亵渎，惊恐地看着树人、角鹰兽和山岭巨人等神圣生物遭到屠杀，灵魂被束缚在武器之中。",["race:Troll"]="尤克里体现了典型的巨魔通灵习俗，运用传统的巫医仪式、缩小容器和巫毒来驾驭原始的生命精华。"},sec={{t="驾驭灵魂精华",b="巫医尤克里遵循巨魔传统的通灵之道，花费了大量心力，研究菲拉斯荒野中蕴藏的自然魔法。他认为，暗夜精灵借助森林野兽之灵的力量已有数千年，如今部落也该夺取这些原始力量了。他研究的核心是灵魂精华，也就是留存在生物体内的鲜活灵魂精华。为了利用这股力量，尤克里制作了特殊容器，能在灵魂逸散之前迅速缩小死去的生物，将其精华储存起来以供研究。"},{t="骇人的交易与仪式容器",b="要完善这些禁锢容器，需要蕴含黑暗力量的强效材料，尤克里无法独自在荒野中集齐。他杀死了一名游荡在菲拉斯林间的联盟矮人，割下这名入侵者的头颅，并安排将其交给尼尔鲁·火刃作交易，后者是一名住在奥格瑞玛幽暗的暗影裂口中的术士。作为这件骇人战利品的回报，尼尔鲁提供了完成束缚附魔所需的稀有草药。有了这些材料，尤克里成功制成了第一批容器，得以捕获当地枭兽、角鹰兽、精灵龙、树人和山岭巨人的灵魂。"},{t="以灵魂铸造武器",b="提取灵魂精华只是尤克里宏大计划的第一步。巫医从那些被他捕获灵魂的生物身上收集坚韧的肌腱、附魔矿物和石化碎木，将这些实物材料与受束缚的灵魂精华融合。通过这些仪式，他学会了将古老的森林之灵永久束缚在武器和装备中，为部落提供蕴含魔力的武器。除了施行仪式、制作装备，尤克里还对艾泽拉斯各地隐秘的力量之地抱有浓厚兴趣，积极追查那座古老的水下建筑——沉没的神庙的传闻。"}},faq={{q="什么是灵魂精华？",a="灵魂精华是生物死后残留的灵魂精华。巫医尤克里使用经过特殊附魔的容器，缩小被杀死的野兽和自然守护者的躯体，在它们逸出的灵魂消散于周围环境之前将其捕获。",al={"什么是灵魂精华","灵魂精华含义","灵魂精华定义"}},{q="尤克里为何要把矮人的头颅送到奥格瑞玛交易？",a="尤克里需要特殊材料来制作仪式容器。他在菲拉斯杀死了一名联盟矮人后，派人将割下的头颅送给奥格瑞玛的尼尔鲁·火刃，换取束缚灵魂精华灵魂所需的稀有草药。",al={"矮人头颅任务","为何把头颅送给尼尔鲁","尼尔鲁 火刃交易"}},{q="尤克里以哪些生物为目标？",a="他的目标是与自然世界有着内在联系、长期与暗夜精灵结盟的生物，包括辛特兰的枭兽，以及菲拉斯的角鹰兽、精灵龙、树人和山岭巨人。",al={"尤克里猎杀哪些野兽","尤克里的灵魂捕获目标","哪些动物能提供灵魂精华"}},{q="尤克里如何利用捕获的灵魂？",a="收集到灵魂精华以及碎木、肌腱和矿物等天然原材料后，尤克里便将灵魂精华永久束缚在武器中，为普通兵器注入古老森林守护者的原始神秘力量。",al={"灵魂武器","为何收集灵魂精华","灵魂精华武器奖励"}},{q="巫医尤克里在哪里？",a="巫医尤克里住在莫沙彻营地，这里是部落在菲拉斯中部的主要聚居地，四周林木繁茂，危机四伏。",al={"尤克里位置","尤克里在哪里","巫医尤克里位置"}},{q="尤克里对沉没的神庙知道些什么？",a="尤克里研究灵魂与艾泽拉斯各地的神秘场所，听闻了那座名为沉没的神庙的水下阿塔莱圣所，并指引感兴趣的冒险者去找地精探险家玛尔冯·瑞文斯克，展开进一步调查。",al={"尤克里沉没的神庙","沉没的神庙菲拉斯任务","阿塔哈卡神庙尤克里"}}},fp="19,219,21.377.0,34.417.1,25.416.0,15.183.0,47.188.0,42.212.0,46.183.0,37.104.0,46.163.0"}
P.entries["npc:wizbang-cranktoggle"] = {n="维兹班恩·曲针",s="在黑海岸，维兹班恩·曲针以奥伯丁为据点，维持着一个传声盒网络的运转。这位古怪的侏儒工程师住在旅店楼上，远离诺莫瑞根和铁炉堡的厅堂。",h="在黑海岸，维兹班恩·曲针以奥伯丁为据点，维持着一个传声盒网络的运转。这位古怪的侏儒工程师住在旅店楼上，远离诺莫瑞根和铁炉堡的厅堂。",kw={"奥伯丁","传声盒","曲针","黑海岸","电动推进器","工程师","小齿轮","侏儒","维兹班恩"},ang={["profession:Engineering"]="身为工程师，你能看出侏儒的惯常做法：在未经探索的土地上，用gaffer jacks和electropellers等专用工具解决后勤难题。",["race:Gnome"]="身为侏儒，看到同胞在卡利姆多崎岖的海岸沿线运营一个实验性的通信网络，会让你想起诺莫瑞根永不停歇的创造精神。",["race:NightElf"]="身为暗夜精灵，你知道哨兵和德鲁伊依靠小精灵、信使以及与自然的联系。维兹班恩却将喧闹旋转的齿轮和金属箱子带进了黑海岸的神圣林地。"},sec={{t="奥伯丁的工程师",b="维兹班恩·曲针将联盟的巧思带到了奥伯丁。这位侏儒工程师在旅店楼上工作，身边堆满工具和零件。这里的暗夜精灵追求与自然和谐共处，遵循古老的习俗。维兹班恩则专注于解决实际的机械问题，远离卡利姆多庄严的德鲁伊传统。"},{t="传声盒网络",b="沿着黑海岸崎岖的海岸线，维兹班恩维护着一个传声盒网络。他的装置能够自动发送报告，并将消息传递到远方。海边的恶劣天气和充满敌意的野生动物常常损坏这些装置。维兹班恩请旅人寻找零件，回收小齿轮之类的工具，并找回电能草莓，好让网络继续运转。"}},faq={{q="在哪里能找到维兹班恩·曲针？",a="维兹班恩·曲针住在奥伯丁的旅店楼上，奥伯丁是黑海岸的一处暗夜精灵聚居地。",al={"维兹班恩位置","维兹班恩在哪里","奥伯丁侏儒位置"}},{q="维兹班恩·曲针在黑海岸做什么？",a="维兹班恩是一位联盟工程师，致力于在黑海岸的荒野各处架设并维护传声盒。",al={"维兹班恩为什么在奥伯丁","维兹班恩的目的","维兹班恩做什么"}},{q="传声盒是什么？",a="传声盒是维兹班恩·曲针制造的机械装置，用于监测情况，并在黑海岸各处远距离传递信息。野生动物和恶劣天气常常损坏这些装置。",al={"传声盒是什么","传声盒背景故事","传声盒用途"}},{q="维兹班恩与其他侏儒有亲属关系吗？",a="维兹班恩与德尔伯·曲针有着相同的姓氏，这表明他们可能来自同一个工匠家族。",al={"曲针家族","德尔伯·曲针是谁","维兹班恩的亲属"}},{q="暗夜精灵为什么容忍他在奥伯丁摆弄机械？",a="暗夜精灵和侏儒都是大联盟的成员。奥伯丁为盟友种族提供住宿和庇护，尽管侏儒机械与精灵追求的自然和谐显得格格不入。",al={"暗夜精灵与侏儒","奥伯丁为什么允许工程学"}},{q="维兹班恩会交给冒险者什么任务？",a="维兹班恩请旅人沿海岸寻找导电器和小齿轮等零件，帮助修理并配置他的传声盒。",al={"维兹班恩任务","维兹班恩提供什么任务"}}},fp="19,176,24.319.0,19.339.0,37.108.0,47.108.0,19.179.0,39.109.0,59.174.0,44.139.0"}
P.entries["npc:wizlo-bearingshiner"] = {n="维兹罗",s="维兹罗是一名地精工匠，滞留在千针石林的白沙岗哨。他是商队遭半人马袭击后的唯一幸存者，正招募旅人从残骸中找回一件贵重的超适应齿轮。",h="维兹罗是一名地精工匠，滞留在千针石林的白沙岗哨。他是商队遭半人马袭击后的唯一幸存者，正招募旅人从残骸中找回一件贵重的超适应齿轮。",kw={"地精工程师","超适应齿轮","千针石林","白沙岗哨","维兹罗"},ang={["faction:Horde"]="部落旅人在白沙岗哨与当地牛头人一同扎营时，可以轻松借助维兹罗的机械专长，获得实用的小装置。",["profession:Engineering"]="工程师们或许能理解维兹罗的心愿：找回神秘的超适应齿轮，并弄清它有什么用途。"},sec={{t="岗哨里的工程师",b="维兹罗与牛头人一同暂住在峡谷道路旁的白沙岗哨，行程却被迫耽搁了。半人马袭击了他的商队，只有他一人幸存。他的客户还在等着收货，他担心自己无法按时交货。"},{t="滞留的货物",b="维兹罗最好的小装置挂在一头凶猛黑豹的脖子上，那头黑豹被关在白沙岗哨以北、他被毁的商队旁的笼子里。就连半人马也对这头野兽避之不及。维兹罗愿意提供笼子的钥匙，并悬赏请旅人找回超适应齿轮，尽管他承认自己还没弄清这件装置究竟有什么用途。"}},faq={{q="维兹罗是谁？",a="维兹罗是一名地精工匠，商队遭半人马袭击后，他滞留在千针石林的白沙岗哨。他正在寻求帮助，想从一头关在笼子里的黑豹身上找回超适应齿轮。",al={"维兹罗","维兹罗是谁","白沙岗哨地精"}},{q="在哪里可以找到维兹罗？",a="他位于白沙岗哨，那是千针石林伊索克营地附近道路旁的一处部落营地。",al={"维兹罗位置","维兹罗在哪","寻找维兹罗"}},{q="他在做什么实验？",a="维兹罗正设法找回他的超适应齿轮。他承认自己还得弄清它有什么用途；这件装置的确切功能尚不清楚。",al={"维兹罗任务","维兹罗做什么","维兹罗的小装置"}},{q="为什么一个地精会在白沙岗哨与部落共事？",a="白沙岗哨并不是维兹罗原定的停留地点。半人马在附近袭击了他的商队，他因此滞留于此，而他的客户还在等着收货。",al={"维兹罗为何在此","维兹罗是部落吗","白沙岗哨的地精"}},{q="维兹罗属于热砂港吗？",a="目前没有证据表明维兹罗隶属于热砂港。他与部落一同驻留在白沙岗哨，一心想找回货物，交到客户手中。",al={"维兹罗阵营","热砂港维兹罗","维兹罗财团"}},{q="超适应齿轮是什么？",a="超适应齿轮是一件贵重的装置，带在一头关在笼子里的黑豹身上，笼子就在维兹罗被毁的商队旁。它的确切用途尚不清楚——就连维兹罗也说，自己还没弄明白它有什么用。",al={"超适应齿轮","维兹罗的装置","小装置任务"}}},fx={["7d59faba"]={q="维兹罗想要什么？",a="维兹罗想从看守着他那辆在白沙岗哨以北损毁的篷车的黑豹身上找回超适应齿轮。半人马袭击了篷车，害他困在此地，而他的客户还在等着货物。",al={"维兹罗想要什么","维兹罗的目标","维兹罗的实验"}},["1b304945"]={q="维兹罗为什么在千针石林？",a="半人马袭击了维兹罗附近的篷车，白沙岗哨便成了他意料之外的落脚处。他是唯一的幸存者，还在担心客户们等着收货。",al={"维兹罗为什么在这里","维兹罗为什么在千针石林","维兹罗为什么在白沙岗哨"}}},fp="19,249,23.232.0,19.276.0,27.190.0,37.118.0,37.117.0,58.145.0,45.162.0,33.150.0"}
P.entries["npc:wizzle-brassbolts"] = {n="维兹尔·铜栓",s="维兹尔·铜栓是一名侏儒工程师，与工匠同伴们一起驻扎在千针石林的盐碱平地上。他在沙漠赛道为侏儒赛车队工作，寻找当地的耐用材料来加固他们的试验型火箭赛车。",h="维兹尔·铜栓是一名侏儒工程师，与工匠同伴们一起驻扎在千针石林的盐碱平地上。他在沙漠赛道为侏儒赛车队工作，寻找当地的耐用材料来加固他们的试验型火箭赛车。",kw={"铜栓","沙漠赛道","飞行员比罗·长须","火箭赛车","闪光平原","千针石林","维兹尔"},ang={["profession:Engineering"]="维兹尔体现了侏儒的工程学理念：将高速机械推向极限，在金属板无法胜任时，依靠不同寻常的材料来加固结构。",["race:Gnome"]="来到闪光平原的侏儒会发现，维兹尔与他们志同道合，执意要用精湛的技艺击败热砂地精那些不顾风险的机械装置。"},sec={{t="盐碱地上的巧思",b="在闪光平原蒸腾的热浪中，侏儒与地精之间的工程学较量化作了一场场高速火箭赛车竞赛。维兹尔·铜栓是侏儒赛车队的一员，努力让赛车在惊人的高速和盐粒的磨蚀下保持完好。为了加固赛车，他招募冒险者猎杀当地的野生动物，比如在盆地中游荡的结实海龟，收集它们坚硬的龟壳，制造足以容纳他兄弟新研制的腐蚀性火箭燃料的油箱。"},{t="远方的朋友",b="维兹尔与各大陆的朋友保持着密切联系，其中就有飞行员比罗·长须，他会派信使给兄弟们送来赛车头盔。有了这样的帮助，尽管闪光平原的试验场偏远而环境恶劣，维兹尔仍能维持侏儒赛车队的物资供应。"}},faq={{q="在哪里可以找到维兹尔·铜栓？",a="维兹尔·铜栓位于千针石林东南部闪光平原的沙漠赛道。他就站在侏儒维修人员和他们的机械设备之间。",al={"维兹尔位置","维兹尔·铜栓在哪里","维兹尔·铜栓地图"}},{q="维兹尔为什么要收集龟壳？",a="他的兄弟正在研制一种新的火箭燃料，腐蚀性强得足以蚀穿赛车底盘。维兹尔用闪光平原上陆龟坚如磐石的龟壳制造新油箱，用来容纳这种燃料。",al={"硬化龟壳任务","维兹尔为什么要龟壳","龟壳赛道"}},{q="铜栓兄弟是谁？",a="铜栓兄弟指的是维兹尔和他的兄弟菲兹尔与瑞兹尔，他们都是侏儒工匠，在沙漠赛道经营侏儒火箭赛车队，与地精竞速。飞行员比罗·长须是他们的朋友。",al={"铜栓家族","铜栓兄弟","维兹尔的兄弟"}},{q="维兹尔对部落玩家友好吗？",a="是的。沙漠赛道是中立地带，维兹尔自己的任务，比如收集硬化的陆龟壳，也同样向部落和联盟的冒险者开放。",al={"部落能与维兹尔交谈吗","维兹尔·铜栓部落"}}},fx={ae9cecf8={q="维兹尔·铜栓是谁？",a="维兹尔·铜栓是一名勇敢的侏儒工程师，驻扎在千针石林的闪光平原上。她与同族一道埋头研发尖端工程项目和机械创新，在炽热无情的盐碱地上展现诺莫瑞根的巧思。",al={"维兹尔是谁","维兹尔·铜栓的背景","维兹尔·铜栓是谁"}},["704bc566"]={q="维兹尔·铜栓想要什么？",a="维兹尔想从各地搜集稀有而坚固的材料，以加固并完善她的工程造物。无论是收集坚硬的龟壳，还是获取尾鳍之类的强大野兽部件，她都要依靠勇敢的旅人带来机械测试所需的奇异材料。",al={"维兹尔想要什么","维兹尔·铜栓的目标","维兹尔·铜栓的任务"}},["96d92e19"]={q="维兹尔·铜栓为什么在这里？",a="维兹尔驻扎在闪光平原的沙漠赛道，支持侏儒工程工作，以及与地精对手之间持续进行的车辆竞赛。广阔平坦的盐碱盆地是测试高速机械和实验性装置的理想场所。",al={"维兹尔为什么在这里","维兹尔为什么在沙漠赛道","维兹尔为什么在千针石林"}}},fp="17,183,27.375.0,25.223.0,35.168.0,39.180.0,32.171.0,36.142.0"}
P.entries["npc:wizzlecrank-s-shredder"] = {n="维兹克兰克的伐木机",s="在淤泥沼泽，维兹克兰克的伐木机被困在荆棘谷地精的操作员之间。驾驶员维兹克兰克钻进机器，想把它偷走，却发现没有钥匙就无法移动。这个地精必须先发动引擎，才能设法逃脱。",h="在淤泥沼泽，维兹克兰克的伐木机被困在荆棘谷地精的操作员之间。驾驶员维兹克兰克钻进机器，想把它偷走，却发现没有钥匙就无法移动。这个地精必须先发动引擎，才能设法逃脱。",kw={"贫瘠之地","点火","驾驶员维兹克兰克","淤泥沼泽","逃脱","荆棘谷地精","维兹克兰克","维兹克兰克的伐木机"},ang={["faction:Horde"]="部落一向憎恶荆棘谷地精在贫瘠之地滥伐森林、肆意开采并留下毒污的行径。帮助一名受困的驾驶员，正好让你有机会砸毁他们的钻探设施。",["profession:Engineering"]="地精伐木机采用粗陋的蒸汽和活塞技术。驾驶员维兹克兰克的困境表明，专有的点火系统在野外有多容易出问题。"},sec={{t="困于淤泥",b="淤泥沼泽深处，维兹克兰克正待在一台无法移动的伐木机里。这台荆棘谷地精的机器身处遭到污染的盆地，周围都是充满敌意的雇佣兵。维兹克兰克爬上机器，想把它偷走，随后才发现必须用钥匙解锁它的操纵杆。另一名伐木机操作员问他是否一切正常时，他慌了神，谎称机器出了故障。如今他仍把自己关在里面，附近尽是守卫和监工，只盼有人能在荆棘谷地精起疑之前取来钥匙。"},{t="轰鸣突围",b="拿到井架顶端控制室里主管身上的打火钥匙后，伐木机轰隆作响，再次启动。驾驶员维兹克兰克开着笨重的机器，从周围的雇佣兵中冲出，刀刃飞旋，金属装甲承受着攻击。同情这位被困驾驶员的路人护送着这台脆弱的机器，离开盆地，前往安全地带。"}},faq={{q="维兹克兰克的伐木机里是谁？",a="这台机械步行机里坐着地精驾驶员维兹克兰克。他钻进这台荆棘谷地精的机器，想把它偷走，却因没有钥匙而被困在了他们的地盘上。",al={"谁驾驶伐木机","驾驶员维兹克兰克","维兹克兰克的伐木机里是谁"}},{q="伐木机为什么被困在淤泥沼泽？",a="维兹克兰克钻进伐木机时，并不知道解锁操纵杆需要一把钥匙。周围都是荆棘谷地精的劳工、钻探工和守卫，他便对一名起了疑心的操作员谎称机器出了故障。如今他在里面等着有人从井架顶端的主管那里取来钥匙。",al={"伐木机为什么被困","维兹克兰克被困","伐木机怎么了"}},{q="伐木机为什么有时不见了？",a="如果淤泥沼泽北部洼地里的伐木机不见了，就说明另一位旅人已经发动引擎，正在护送维兹克兰克前往安全地带。护送结束后不久，它就会回到起点。",al={"伐木机消失","维兹克兰克的伐木机在哪里","伐木机不见了"}},{q="荆棘谷地精在淤泥沼泽做什么？",a="荆棘谷地精正在贫瘠之地北部开采原油和焦油，砍伐林木。他们的作业将一处天然水源变成了有毒的油污泥潭沼泽，里面挤满了雇来的打手和工头。",al={"淤泥沼泽是什么","荆棘谷地精淤泥沼泽"}}},fp="22,209,21.490.0,21.363.1,37.181.0,43.317.0,38.223.0,48.195.0"}
P.entries["npc:wrenix-the-wretched"] = {n="卑鄙的维尼克斯",s="在棘齿城，卑鄙的维尼克斯守着他的奇怪装置，帮助人们破解难开的锁。这位地精工匠提供工具，用来打开锁得严严实实的储物箱。",h="在棘齿城，卑鄙的维尼克斯守着他的奇怪装置，帮助人们破解难开的锁。这位地精工匠提供工具，用来打开锁得严严实实的储物箱。",kw={"贫瘠之地","机械装置","地精","开锁","海盗","棘齿城","维尼克斯","卑鄙"},ang={["class:Rogue"]="身为潜行者，你可以从维尼克斯那里获得工具，练习打开南海海盗的上锁箱。",["profession:Engineering"]="维尼克斯的gizmotronic apparatus展现了热砂机械装置运转时的模样：吵闹、时好时坏，却能有效完成精密作业。"},sec={{t="棘齿城的工匠",b="卑鄙的维尼克斯在棘齿城的机械旁工作，这座地精港口坐落在贫瘠之地的海岸上。身为热砂港的工匠，他熟悉各种机械装置，也知道如何绕过锁具，取出里面的东西。在海岸一带活动的潜行者和斥候可以向他寻求帮助。"},{t="精密装置",b="维尼克斯总把他的机械装置放在手边。他借助这台装置和自己的机械技艺，提供盗贼工具和开锁器具。那些想在商旅海岸找回被窃的南海海盗走私品的人，可以用上这些工具。"}},faq={{q="卑鄙的维尼克斯是谁？",a="维尼克斯是贫瘠之地棘齿城的一名地精工匠。他在自己的机械设备旁工作，经营各种机械装置和开锁工具。",al={"维尼克斯","维尼克斯是谁","卑鄙的维尼克斯"}},{q="在哪里能找到维尼克斯？",a="在棘齿城那台大型机械装置旁可以找到维尼克斯，这座港口城镇位于贫瘠之地的东海岸。",al={"维尼克斯位置","维尼克斯在哪里","维尼克斯棘齿城"}},{q="他身旁的机械设备是什么？",a="维尼克斯的机械设备是一台地精制造的机器，用于修造和诊断工作。他用它制作精密盗贼工具等专用器具。",al={"精密机械装置","维尼克斯的机器","那台机器是什么"}},{q="他为什么帮助冒险者对付南海海盗？",a="贫瘠之地沿岸的南海海盗把贵重的掠夺品藏在上锁的箱子里。维尼克斯的机械工具能帮助足智多谋的潜行者打开这些箱子，让双方都能获利。",al={"为什么是南海","盗亦有道背景故事","维尼克斯海盗"}}},fp="19,152,19.288.0,25.254.0,27.136.0,26.117.0,46.168.0,63.163.0"}
P.entries["npc:wynne-larson"] = {n="维恩·拉尔森",s="在暴风城的法师区，维恩·拉尔森为王国各地的法师供应长袍。自达拉然和奎尔萨拉斯在第三次大战中陷落以来，她依靠当地工匠，并指引施法者寻找制作附魔衣物所需的稀有材料。",h="在暴风城的法师区，维恩·拉尔森为王国各地的法师供应长袍。自达拉然和奎尔萨拉斯在第三次大战中陷落以来，她依靠当地工匠，并指引施法者寻找制作附魔衣物所需的稀有材料。",kw={"星结之衣","达拉然","法师区","法纹长袍","奎尔萨拉斯","长袍商人","暴风城","维恩·拉尔森"},ang={["class:Mage"]="身为法师，你可以在奥术之路的早期向维恩求助，裁制Manaweave和星结衣物。",["faction:Alliance"]="身为联盟的一员，你可以看到暴风城正挺身而出，为幸存的联盟种族提供自给自足的奥术工艺。",["profession:Tailoring"]="身为裁缝，你可以看到，在北方的纺织中心陷落后，服装商和裁缝如何帮助暴风城。"},sec={{t="新的奥术市场",b="在第三次大战之前，达拉然和奎尔萨拉斯供应最精良的织物和附魔法衣。两地的毁灭重创了原有的贸易路线和奥术织物制造业。如今，维恩·拉尔森在暴风城的法师区与当地裁缝和附魔师合作，鲁坎·考迪尔便是其中之一。他们共同满足城中日益增长的长袍和魔织装备需求。"},{t="制作魔法长袍",b="初学法术的法师和已有一定造诣的法师都会来到维恩的店里购买奥术衣物。她知道制作法纹长袍和星结之衣等法衣需要哪些材料。为了找到这些材料，她会派施法者前往危险之地，取回新鲜的蜘蛛丝等稀有材料。尽管北方的供货短缺，她的工作仍帮助暴风城的法师维持装备供应。"}},faq={{q="在哪里可以找到维恩·拉尔森？",a="你可以在暴风城的法师区找到维恩·拉尔森，她在那里向施法者出售奥术布甲胸甲和衣物。",al={"维恩·拉尔森位置","维恩·拉尔森在哪里","暴风城法师长袍商人"}},{q="维恩为什么会提到达拉然和奎尔萨拉斯？",a="在第三次大战之前，达拉然和奎尔萨拉斯是东部王国附魔织物的主要供应地。两地的毁灭切断了进口来源，因此暴风城的商人转而依靠当地工匠，以及来自更遥远地区的稀有材料。",al={"维恩达拉然对话","奎尔萨拉斯长袍","长袍为何难寻"}},{q="哪些任务与维恩·拉尔森有关？",a="维恩通过收集原料、法纹长袍、新鲜的蜘蛛丝和星结之衣这些任务，帮助法师获得裁制的奥术衣物。",al={"维恩·拉尔森任务","暴风城长袍任务","法纹长袍任务"}},{q="维恩·拉尔森出售什么？",a="维恩出售初级和中级布甲长袍，包括燃烧长袍、多彩长袍、双线长袍和银色长袍。",al={"维恩·拉尔森商品","维恩出售哪些长袍"}},{q="维恩在暴风城依靠谁提供制作所需的物资？",a="维恩依靠当地工匠，尤其是附魔师鲁坎·考迪尔和暴风城的其他手艺人，为她出售的货物进行编织和附魔。",al={"谁制作维恩的长袍","鲁坎·考迪尔的关联"}},{q="维恩·拉尔森与暴风城的其他拉尔森有亲属关系吗？",a="维恩与暴风城的服装商伊万·拉尔森同姓，詹妮·拉尔森也与他们同姓。这个共同的姓氏暗示，他们可能是城中从事服装行业的手艺人家族。",al={"暴风城拉尔森家族","伊万·拉尔森","詹妮·拉尔森"}}},fx={["61901341"]={q="维恩·拉尔森是谁？",a="维恩·拉尔森是一位受人尊敬的人类长袍商人，在暴风城的法师区经营生意。她主要为施法者和裁缝学徒提供货物，出售从当地工匠手中购得的优质布制服装和奥术材料。",al={"维恩·拉尔森是谁","维恩·拉尔森的身份","维恩是谁"}},f66b818d={q="维恩·拉尔森属于哪一方？",a="维恩·拉尔森是暴风城的忠诚公民，也是一位自豪的联盟成员。她与当地的人类工匠和城中的法师群体密切合作，为联盟施法者供应精良的服装。",al={"维恩·拉尔森的阵营","维恩·拉尔森为谁效力","维恩·拉尔森与联盟"}},["3ea6d1a4"]={q="维恩·拉尔森为什么在法师区？",a="维恩把店铺设在法师区，因为那里聚集着暴风城的学者、奥术师和附魔师。她出售长袍，也帮助施法学徒，因此这个街区自然成了她经营生意的地方。",al={"维恩为什么在这里","维恩为什么在法师区","维恩·拉尔森在此的目的"}},d20d9bb4={q="维恩·拉尔森想要什么？",a="随着达拉然被毁、奎尔萨拉斯沦为废墟，精良的魔法织物变得稀缺。维恩想通过采购新鲜的蜘蛛丝等稀有材料，并支持当地工匠，让暴风城的施法者继续穿上优质的服装。",al={"维恩想要什么","维恩·拉尔森的目标","维恩·拉尔森的动机"}}},fp="12,238,19.362.0,24.362.0,30.130.0,47.231.0,33.141.0,28.136.0,58.139.0,54.159.0"}
P.entries["npc:xavathras"] = {n="萨瓦瑟拉斯",s="萨瓦瑟拉斯是一名凶残的萨特指挥官，栖身于费伍德森林克斯特拉斯废墟的帐篷之间。他率领着一群碧火萨特，奉主人萨瓦里克之命，监督对一口古老月亮井的腐化。",h="萨瓦瑟拉斯是一名凶残的萨特指挥官，栖身于费伍德森林克斯特拉斯废墟的帐篷之间。他率领着一群碧火萨特，奉主人萨瓦里克之命，监督对一口古老月亮井的腐化。",kw={"克斯特拉斯","费伍德森林","碧火","月亮井","萨特","萨瓦里克","萨瓦瑟拉斯"},ang={["class:Druid"]="试图消除费伍德森林恶魔污染的德鲁伊认为，萨瓦瑟拉斯蓄意毒化纯净水源的行径是对自然的冒犯，必须加以制止。",["race:NightElf"]="对暗夜精灵而言，萨瓦瑟拉斯既代表着远古同胞沦为恶魔野兽的悲剧，也是一个仍在亵渎他们神圣月亮井的恶徒。"},sec={{t="克斯特拉斯的腐化者",b="在费伍德森林遭到污染的林地中，克斯特拉斯废墟已落入碧火萨特的魔爪。萨瓦瑟拉斯驻扎在精灵石砌建筑之间的营地里，奉另一名残忍的萨特萨瓦里克之命，指挥着对附近一口月亮井的亵渎。他用恶魔能量毒化纯净的井水，加深了笼罩森林的腐化。他的存在直接威胁着恢复林地的种种努力，也因此招致了艾瑞丹·蓝风等暗夜精灵的愤怒，他们决意将他除掉。"}},faq={{q="萨瓦瑟拉斯是谁？",a="萨瓦瑟拉斯是一名残忍的萨特首领，统率着盘踞在费伍德森林克斯特拉斯废墟中的碧火萨特。他效忠于萨瓦里克，负责腐化废墟中那口古老的精灵月亮井。",al={"萨瓦瑟拉斯是谁","萨瓦瑟拉斯背景故事","克斯特拉斯的萨特首领是谁"}},{q="在哪里能找到萨瓦瑟拉斯？",a="萨瓦瑟拉斯在克斯特拉斯废墟的萨特帐篷之间扎营，这处古老的暗夜精灵遗址位于费伍德森林中南部。",al={"萨瓦瑟拉斯位置","萨瓦瑟拉斯在哪里","克斯特拉斯废墟萨特"}},{q="艾瑞丹·蓝风为什么想要除掉萨瓦瑟拉斯？",a="艾瑞丹·蓝风力图守护费伍德森林，阻止恶魔的污秽肆意蔓延。萨瓦瑟拉斯正不断加深一口月亮井的腐化，因此，对那些试图净化这片土地的人来说，除掉他是当务之急。",al={"为什么要杀萨瓦瑟拉斯"}},{q="萨瓦瑟拉斯为谁效力？",a="萨瓦瑟拉斯为萨瓦里克效力，后者是另一名残忍而强大的萨特，在费伍德森林中活动，进一步巩固燃烧军团对这片腐化森林残存的控制。",al={"萨瓦瑟拉斯的主人是谁","萨瓦里克 萨瓦瑟拉斯"}}},fp="9,138,23.400.0,17.161.0,29.120.0,45.175.0,29.128.0"}
P.entries["npc:yaw-sharpmane"] = {n="雅文·刺鬃",s="雅文·刺鬃在血蹄村指引年轻的牛头人猎人。他教他们追踪、求生，以及驯服莫高雷的野兽。",h="雅文·刺鬃在血蹄村指引年轻的牛头人猎人。他教他们追踪、求生，以及驯服莫高雷的野兽。",kw={"野兽","血蹄","猎人","莫高雷","刺鬃","驯服","牛头人","训练师","雅文"},ang={["class:Hunter"]="作为一名离开红云台地的牛头人猎人，雅文·刺鬃可以指引你与你的第一位野兽伙伴建立羁绊。",["race:Tauren"]="身为牛头人，你遵循Shu'halo的传统，与自然和谐共处，敬重莫高雷的野兽。"},sec={{t="平原上的引路人",b="雅文·刺鬃在血蹄村传授射击、追踪和生存技巧。在红云台地证明过自己的年轻猎人会来找他磨炼技艺，然后再踏上莫高雷更广阔的平原。"},{t="建立羁绊",b="雅文·刺鬃引导新猎人完成驯服野兽的古老仪式。他要求他们与莫高雷的本土动物建立羁绊，考验他们的耐心，以及对自然平衡的尊重。随后，他会教他们照料和训练一位长久相伴的伙伴。"}},faq={{q="雅文·刺鬃是谁？",a="雅文·刺鬃在血蹄村训练猎人。他教导年轻的牛头人射击、野外生存，以及驯服动物伙伴的方法。",al={"雅文·刺鬃","雅文是谁","血蹄村猎人训练师"}},{q="在哪里可以找到雅文·刺鬃？",a="你可以在血蹄村找到雅文·刺鬃，村子位于莫高雷中部的石牛湖畔。",al={"雅文·刺鬃位置","雅文在哪里","雅文坐标"}},{q="雅文·刺鬃教猎人什么？",a="雅文·刺鬃传授猎人的基本技能，并引导有潜力的猎人完成驯服和指挥野兽的仪式。",al={"雅文教什么","雅文猎人技能","雅文技能"}},{q="雅文提供哪些任务？",a="雅文·刺鬃引导牛头人猎人完成驯服野兽的试炼，从“猎人之道”到“驯服野兽”，再到“训练野兽”。",al={"雅文任务","雅文·刺鬃任务"}},{q="为什么猎人在十级左右需要与他交谈？",a="当你迎来第十个历练的季节，你会去找雅文·刺鬃，学习如何从莫高雷的荒野中捕获一位长久相伴的动物伙伴，并喂养和指挥它。",al={"雅文十级","血蹄村驯服野兽"}},{q="雅文·刺鬃会与猎人以外的人交谈吗？",a="雅文·刺鬃会礼貌地与其他职业的旅者交谈，但他的知识和试炼是为猎人准备的。",al={"雅文非猎人","其他职业能与雅文交谈吗"}}},fp="13,139,21.221.0,18.253.0,21.144.0,31.103.0,38.125.0,27.141.0,52.149.0,45.112.0"}
P.entries["npc:yeh-kinya"] = {n="叶基亚",s="叶基亚是一名丛林巨魔学者，住在塔纳利斯沙漠海岸的热砂港。他声称要寻找古老的知识与文物，以了解黑暗力量，并派遣自愿相助的冒险者前往艾泽拉斯各地，搜集失落的巨魔遗物。",h="叶基亚是一名丛林巨魔学者，住在塔纳利斯沙漠海岸的热砂港。他声称要寻找古老的知识与文物，以了解黑暗力量，并派遣自愿相助的冒险者前往艾泽拉斯各地，搜集失落的巨魔遗物。",kw={"哈卡","铁靴","摩沙鲁","灵魂掠夺者","热砂港","塔纳利斯","风蛇","叶基亚"},ang={["class:Priest"]="对灵魂精华敏感的牧师，或许会因叶基亚随意搜集被困的尖啸者灵魂而深感不安。",["race:Troll"]="黑暗之矛巨魔深知哈卡再度崛起会带来致命的危险。"},sec={{t="热砂港的学者",b="叶基亚悠闲地待在热砂港的地精和码头工人之间，自称是一名潜心研究历史与灵魂的学者。他招募旅人，前往卡利姆多和东部王国各地寻找鲜为人知的魔法物品，从辛特兰的古老巨卵，到埋藏在祖尔法拉克废墟中的预言石板。他声称这些差事只是为了和平地探究古代巨魔历史，但他对血神哈卡的格外关注，引起了警觉者的怀疑。"},{t="风蛇的骗局",b="在学者的伪装之下，叶基亚其实是哈卡灵魂掠夺者的狂热信徒。他精心利用搜集来的每一件文物和每一份灵魂精华，为可怕的血神在艾泽拉斯重塑肉身做准备。当勘查员詹斯·铁靴逐步查清并揭露他的阴谋后，叶基亚便撕下了友善的伪装。他没有为自己的背叛接受追究，而是化作一条绿色风蛇，越过茫茫大海逃向南海，留下受骗的英雄们前往尤亚姆巴岛，向赞达拉寻求援助。"}},faq={{q="叶基亚是谁？",a="叶基亚是一名丛林巨魔，站在塔纳利斯热砂港的水边。他自称是一名寻找历史遗物与灵魂的学者，对巨魔之神哈卡尤其感兴趣。",al={"叶基亚背景故事","叶基亚是谁","叶基亚非玩家角色"}},{q="叶基亚为什么想要摩沙鲁的预言和远古之卵？",a="叶基亚说，他需要这些文物来研究古代巨魔的历史与灵魂。摩沙鲁石板位于祖尔法拉克废墟中，远古之卵则在辛特兰，两者都与他对哈卡的兴趣有关。",al={"为什么需要远古之卵","摩沙鲁的预言 巨魔","叶基亚的目的"}}},fp="9,172,32.415.0,20.420.2,17.204.2,69.225.2"}
P.entries["npc:yvette-farthing"] = {n="伊维特·法席恩",s="在布瑞尔，伊维特·法席恩与父亲库勒曼一同住在恐惧之末旅店。身为被遗忘者，她仍记得那段被天灾军团斩断的爱情。",h="在布瑞尔，伊维特·法席恩与父亲库勒曼一同住在恐惧之末旅店。身为被遗忘者，她仍记得那段被天灾军团斩断的爱情。",kw={"未寄出的信","阿加曼德磨坊","布瑞尔","库勒曼·法席恩","恐惧之末旅店","萨尔曼·阿加曼德","提瑞斯法林地","伊维特·法席恩"},ang={["race:Undead"]="身为Undead，即使亡灵之身让心变得冷硬，你也可能仍保留着身为人类时关于爱情的记忆。"},sec={{t="磨坊的回声",b="在第三次大战毁掉洛丹伦之前，伊维特爱着繁荣的阿加曼德磨坊的继承人萨尔曼·阿加曼德。当天灾军团的瘟疫逼近时，伊维特和父亲库勒曼恳求萨尔曼与他们一起离开庄园。他不肯离去，一心守护家族的基业。伊维特和萨尔曼都死去了，随后又以亡灵之身复生。伊维特在布瑞尔拥有自由意志的被遗忘者中找到了容身之处，却不知道萨尔曼最终的命运。"},{t="最后的告别",b="磨坊陷落之前，萨尔曼匆匆给伊维特写了一封情书。信中，他讲述了弟弟代弗林的背叛，也为自己选择留下而悔恨。这封信被天灾军团截获，遗落在阿加曼德磨坊的废墟中，直到冒险者将它找回。读到萨尔曼临终前的告白，伊维特短暂地重温了生前那种真切的绝望。随后，她强迫自己恢复冷漠，满心苦涩，因为昔日的眷恋在被遗忘者残酷的现实中已无处容身。"}},faq={{q="伊维特·法席恩是谁？",a="伊维特·法席恩是一名住在布瑞尔恐惧之末旅店的被遗忘者女性。她是库勒曼·法席恩的女儿，在第三次大战摧毁王国之前，曾住在提瑞斯法林地的农田间。",al={"伊维特·法席恩背景故事","伊维特是谁","布瑞尔伊维特"}},{q="伊维特与阿加曼德磨坊有什么关系？",a="伊维特爱着萨尔曼·阿加曼德。当瘟疫威胁这片地区时，她试图劝他与自己一起逃走，但他选择留下来保卫家族庄园。",al={"伊维特 阿加曼德","萨尔曼 阿加曼德与伊维特","伊维特的恋人"}},{q="把萨尔曼的信交给她后，会发生什么？",a="读到萨尔曼失落已久的信时，伊维特被他临终前诉说爱情与背叛的话语触动，一时悲痛欲绝。她很快又摆出冷硬的态度，说自己如今已是被遗忘者，凡人的感情毫无用处。",al={"未寄出的信交任务","萨尔曼的信奖励","伊维特读信反应"}},{q="伊维特的父亲是谁？",a="伊维特的父亲是库勒曼·法席恩，他也是一名被遗忘者，同样住在布瑞尔的恐惧之末旅店。他们起初一起逃离，但最终都死于瘟疫，成为了被遗忘者。",al={"伊维特的父亲","库勒曼与伊维特","库勒曼·法席恩是谁"}}},fp="15,150,19.394.0,16.470.1,23.178.0,45.165.0,54.201.1,23.188.0"}
P.entries["npc:zaldimar-wefhellt"] = {n="扎尔迪玛·维夫希尔特",s="在狮王之傲旅店楼上，扎尔迪玛·维夫希尔特指导年轻法师学习最初的法术。当他的课程已无法满足他们时，他便让他们前往暴风城继续修习。",h="在狮王之傲旅店楼上，扎尔迪玛·维夫希尔特指导年轻法师学习最初的法术。当他的课程已无法满足他们时，他便让他们前往暴风城继续修习。",kw={"艾尔文森林","闪金镇","狮王之傲旅店","法师训练师","维夫希尔特","扎尔迪玛"},ang={["class:Mage"]="作为一名离开北郡修道院的年轻人类法师，你踏入更广阔的世界，初次遇见扎尔迪玛。他教你入门法术，随后指引你前往暴风城的巫师圣殿。",["faction:Alliance"]="扎尔迪玛在狮王之傲旅店教导艾尔文森林的联盟施法者。你可以在前往暴风城之前学习魔法。"},sec={{t="闪金镇的法师",b="在狮王之傲旅店楼上，扎尔迪玛·维夫希尔特向新手法师传授奥术、火焰与冰霜的入门技艺。当学徒学有所成，需要更深入的教导时，他便让他们北上，前往暴风城的法师区。在那里，詹妮亚·坎农能教给他们更多知识。"}},faq={{q="扎尔迪玛·维夫希尔特是谁？",a="在闪金镇的狮王之傲旅店，扎尔迪玛·维夫希尔特向新手法师传授最初的法术。他指引他们前往暴风城继续修习。",al={"扎尔迪玛是谁","扎尔迪玛·维夫希尔特的职责","闪金镇法师训练师"}},{q="在哪里能找到扎尔迪玛·维夫希尔特？",a="扎尔迪玛·维夫希尔特位于闪金镇的狮王之傲旅店二楼，就在楼梯上来后最左边的房间里。",al={"扎尔迪玛的位置","扎尔迪玛在哪里","如何找到扎尔迪玛"}},{q="扎尔迪玛让新手法师去哪里？",a="法师掌握基础知识后，扎尔迪玛便让他们前往暴风城的法师区。在那里，他们可以到巫师圣殿与詹妮亚·坎农交谈。",al={"扎尔迪玛任务","扎尔迪玛让人去找谁","与詹妮亚交谈任务"}},{q="扎尔迪玛与其他法师有亲属关系吗？",a="目前没有已知的扎尔迪玛的亲属。他在狮王之傲旅店授课。",al={"维夫希尔特家族","扎尔娜·维夫希尔特","扎尔迪玛的亲属"}}},fx={["10a0eae6"]={q="扎尔迪玛·维夫希尔特效忠哪一方？",a="扎尔迪玛是联盟的忠诚成员，为暴风城王国效力。他驻守在艾尔文森林腹地，将自己的奥术造诣用于指导年轻的施法者，帮助他们挺身保卫王国，维护王权。",al={"扎尔迪玛·维夫希尔特的阵营","扎尔迪玛属于联盟吗"}},["063cda12"]={q="扎尔迪玛·维夫希尔特想要什么？",a="扎尔迪玛希望引导初出茅庐的法师，应对研习奥术时的种种危险。学徒在闪金镇掌握施法的基本原理后，他便会指引他们去寻找更高阶的导师，例如暴风城法师区的詹妮亚·坎农，进一步精进技艺。",al={"扎尔迪玛·维夫希尔特的动机","扎尔迪玛想要什么"}},d06c7379={q="扎尔迪玛·维夫希尔特为什么会在闪金镇？",a="扎尔迪玛住在狮王之傲旅店楼上，担任闪金镇的常驻法师训练师。刚离开北郡山谷的冒险者往往都要在闪金镇停留，因此这里是他接引法师新秀、传授基础奥术法术的理想地点。",al={"扎尔迪玛为什么在这里","扎尔迪玛 狮王之傲旅店"}}},fp="17,183,21.249.0,25.154.0,35.125.0,38.146.0,39.71.0"}
P.entries["npc:zamja"] = {n="扎姆沙",s="在奥格瑞玛的 暗巷区，扎姆沙教部落旅人烹饪。这位黑暗之矛巨魔教厨师们用卡利姆多的野兽制作餐食。",h="在奥格瑞玛的 暗巷区，扎姆沙教部落旅人烹饪。这位黑暗之矛巨魔教厨师们用卡利姆多的野兽制作餐食。",kw={"烹饪训练师","黑暗之矛","奥格瑞玛","暗巷区","加基森之旅","巨魔","扎姆沙"},ang={["profession:Cooking"]="扎姆沙是奥格瑞玛为部落角色提供训练的主要烹饪训练师之一。她教授必备的食谱，并指引经验丰富的厨师南下塔纳利斯，接受进阶训练。",["race:Troll"]="和许多黑暗之矛巨魔一样，扎姆沙在大酋长萨尔的旗帜下定居于奥格瑞玛。她将巨魔的机敏才智与烹饪技艺带到了部落的主城。"},sec={{t="暗巷区 的锋利的切肉刀",b="扎姆沙在 暗巷区 工作，在那里切肉，并教部落旅人烹饪。烹饪能帮助旅人在杜隆塔尔和贫瘠之地的荒野中，将生的猎物制成口粮。掌握了基础食谱的厨师可以前往南方的加基森，寻求进一步的训练。"}},faq={{q="扎姆沙是谁？",a="扎姆沙是奥格瑞玛 暗巷区 的一位黑暗之矛巨魔烹饪训练师。她教导部落厨师，帮助他们精进厨艺。",al={"扎姆沙 非玩家角色","扎姆沙是谁","扎姆沙 奥格瑞玛"}},{q="在哪里可以找到扎姆沙？",a="你可以在 暗巷区 找到扎姆沙，那是一条蜿蜒于奥格瑞玛力量谷与荣誉谷之间的阴凉沟壑。",al={"扎姆沙位置","扎姆沙在哪里","扎姆沙训练师位置"}},{q="扎姆沙提供什么训练？",a="扎姆沙教授烹饪技能，以及用卡利姆多各地的野兽和猎物制作食物的食谱。准备好接受进一步训练的厨师，可以寻找更高阶的训练师。",al={"扎姆沙教什么","扎姆沙烹饪食谱","烹饪训练师 奥格瑞玛"}},{q="扎姆沙会指引技艺精湛的厨师去哪里？",a="当奥格瑞玛的训练已无法满足一位厨师的需求时，扎姆沙会指引他们前往塔纳利斯的加基森，寻找迪尔格·奎克里弗。",al={"扎姆沙任务","加基森之旅 任务","部落高级烹饪"}}},fp="5,137,21.245.0,13.126.0,23.117.0,31.160.0,37.116.0"}
P.entries["npc:zangen-stonehoof"] = {n="赞金·石蹄",s="赞金·石蹄在高地的篝火旁照料火焰，并援助遍布卡利姆多的牛头人同胞。每到傍晚，他都会让雷霆崖中央的篝火持续燃烧。",h="赞金·石蹄在高地的篝火旁照料火焰，并援助遍布卡利姆多的牛头人同胞。每到傍晚，他都会让雷霆崖中央的篝火持续燃烧。",kw={"篝火","高地","月亮井水","劳恩·峭壁行者","神圣的火焰","雷霆崖","赞金·石蹄"},ang={["faction:Horde"]="作为来到雷霆崖的部落旅人，你可以向赞金寻求帮助，前往灰谷等争夺中的地区。",["race:Tauren"]="身为牛头人，赞金将莫高雷的城镇中心与远方的同胞联系起来，其中包括千针石林的Cliffrunners。"},sec={{t="高地的火焰守护者",b="赞金·石蹄照料着雷霆崖高地上的公共篝火。每到傍晚，暮色笼罩莫高雷时，他便在城中最高的崖顶上点燃篝火。火焰为聚集在大酋长凯恩·血蹄麾下的各个部族带来温暖。赞金也与莫高雷台地之外的盟友保持联系，协助大陆各地的灵性事务与仪式。"},{t="援助峭壁行者",b="赞金帮助驻守在南方千针石林的劳恩·峭壁行者。劳恩需要暗夜精灵月亮井的井水来举行神圣仪式，于是赞金召集可靠的部落冒险者，穿越双方争夺的灰谷森林。他们从古老的林地中取得了装满井水的小瓶，并将其送往南方的乱风岗。赞金帮助延续古老的仪式，也支援着散布各地的牛头人哨站。"}},faq={{q="赞金·石蹄是谁？",a="赞金·石蹄照料着雷霆崖高地中央的篝火。每到傍晚，他都会让篝火持续燃烧，并为卡利姆多各地的远方同胞安排援助和物资运送。",al={"赞金是谁","赞金·石蹄","赞金做什么"}},{q="赞金如何照料篝火？",a="每到傍晚，夜幕降临时，赞金便会点燃高地上身旁的大篝火。火焰为上层平台带来光明与温暖。",al={"赞金为什么在火边","赞金篝火","点燃篝火"}},{q="赞金为什么需要灰谷的月亮井水？",a="赞金替驻守在千针石林乱风岗的劳恩·峭壁行者办事。劳恩需要灰谷的月亮井水来举行一场神圣仪式，因此赞金派旅人前去取水，并将井水送往南方。",al={"赞金月亮井任务","神圣的火焰","为什么需要月亮井水"}},{q="在哪里可以找到赞金·石蹄？",a="赞金·石蹄站在雷霆崖上层台地高地中央的公共火坑旁。",al={"赞金位置","寻找赞金·石蹄","赞金在哪里"}}},fp="16,157,29.349.0,23.388.0,24.171.0,37.147.0,51.212.0,36.115.0"}
P.entries["npc:zankaja"] = {n="赞卡沙",s="在奥格瑞玛，年轻的兽人女子赞卡沙焦急地等待着伴侣多格兰的消息。他被派往十字路口执勤，那里地处贫瘠之地危险的边疆。",h="在奥格瑞玛，年轻的兽人女子赞卡沙焦急地等待着伴侣多格兰的消息。他被派往十字路口执勤，那里地处贫瘠之地危险的边疆。",kw={"贫瘠之地","十字路口","多格兰","加兹罗格","奥格瑞玛","力量谷","智慧谷","赞卡沙"},ang={["faction:Horde"]="身为部落的一员，你可以从赞卡沙的恳求中看到，守住十字路口这样的哨站，需要驻守那里的步兵付出鲜血与牺牲。",["race:Orc"]="身为兽人，你可以看到杜隆塔尔的普通家庭为此付出的代价：为了履行对大酋长新建国度的职责，亲人们奔赴尚未驯服、危机四伏的边疆。"},sec={{t="牵挂的心",b="赞卡沙在奥格瑞玛等待着伴侣多格兰的消息。多格兰得到晋升，随后南下，前去增援贫瘠之地的十字路口哨站。这项任命是战士的荣耀，但边疆环境险恶，野猪人、半人马和凶猛的野兽出没其间。多格兰既没有传回消息，也没有如期归来，赞卡沙便开始请求旅人为她打听他的消息。"},{t="噩耗传来",b="贫瘠之地传来的消息证实了赞卡沙最深的恐惧：多格兰落入了野猪人手中。在奥格瑞玛的峡谷高墙之内，她仍怀着希望，尽管边疆残酷无情。旅人带回的消息，描绘出部落危机四伏的边境上一幅沉重的牺牲图景。"}},faq={{q="在哪里可以找到赞卡沙？",a="赞卡沙住在奥格瑞玛的力量谷与智慧谷之间的道路旁。",al={"赞卡沙位置","赞卡沙在哪里","寻找赞卡沙"}},{q="多格兰是谁？",a="多格兰是赞卡沙的伴侣，一名兽人战士，最近因晋升而被派往贫瘠之地的十字路口驻守。",al={"多格兰是谁","多格兰","赞卡沙的伴侣"}},{q="赞卡沙为什么担忧？",a="多格兰被派往环境恶劣的贫瘠之地，在十字路口执勤，之后却没有归来，也没有给家里传回消息。赞卡沙担心他在边疆遭遇了不测。",al={"赞卡沙想要什么","赞卡沙的难题","赞卡沙为什么难过"}},{q="赞卡沙请求冒险者做什么？",a="赞卡沙请求途经此地、准备离开奥格瑞玛的冒险者前往十字路口，拜访加兹罗格队长，打听多格兰的下落与安危。",al={"赞卡沙任务","多格兰的消息任务"}},{q="多格兰在贫瘠之地遭遇了什么？",a="赞卡沙不知道多格兰在贫瘠之地遭遇了什么。她请求旅人去十字路口找加兹罗格谈谈，再从那里继续追查线索。",al={"多格兰死了吗","多格兰的命运","多格兰遭遇了什么"}}},fp="7,147,16.391.0,14.286.1,25.98.0,14.114.0,23.156.0,40.147.0,39.152.1"}
P.entries["npc:zardeth-of-the-black-claw"] = {n="黑爪加尔德斯",s="在暴风城的法师区，黑爪加尔德斯守护着一个隐秘的术士密会。他住在已宰的羔羊下方的密室里，平日装作普通酒客。当好奇的贵族探查得太深，他便让他们的追查永远终结。",h="在暴风城的法师区，黑爪加尔德斯守护着一个隐秘的术士密会。他住在已宰的羔羊下方的密室里，平日装作普通酒客。当好奇的贵族探查得太深，他便让他们的追查永远终结。",kw={"贵族佳酿","巴尔雷·维沙克","黑爪","法师区","麝鼠根","已宰的羔羊","蒂罗亚之泪","术士","加尔德斯"},ang={["class:Warlock"]="身为人类术士，加尔德斯展现了某些人在联盟腹地求生时所依赖的冷酷与务实，在那里，能否活命可能取决于是否先下手杀人。",["faction:Alliance"]="对于效忠联盟的人而言，加尔德斯揭示了暴风城光鲜街道之下腐败的阴暗面。",["profession:Herbalism"]="身为草药师，你能看出加尔德斯的阴谋如何将蒂罗亚之泪和麝鼠根这样的有毒植物变成致命工具。"},sec={{t="羔羊之下的暗影",b="已宰的羔羊下方的隧道庇护着研习黑暗法术的人。在他们上方，法师区的高塔中，人们公开钻研着奥术之道。黑爪加尔德斯在地下墓穴中活动，守护着藏在城市卫兵眼皮底下的术士。联盟谴责邪能魔法，因此这个密会隐匿行踪，在王室调查员到来之前便清除威胁。"},{t="让贵族噤声",b="鲍雷斯·维沙克公爵听闻了隐秘术士集会的传言，便敦促贵族展开全面调查。加尔德斯担心追查会摧毁已宰的羔羊下方的据点，于是暗中安排了应对之策。这位贵族偏爱美酒。加尔德斯派出一名密探，穿越东部王国，搜集两种罕见的致命植物：暮色森林的蒂罗亚之泪，以及巨石水坝下方的麝鼠根。"},{t="贵族的佳酿",b="加尔德斯将搜集来的植物混入烈性麦酒，酿成黑爪烈酒，把致命毒酒伪装成一份寻常的奢华礼品。毒酒被送到维沙克的庄园，迅速而无声地夺去了他的性命。随着这位贵族死去，他推动的调查也在王室介入之前告终。加尔德斯和其他术士保住了已宰的羔羊下方的隐秘据点。"}},faq={{q="黑爪加尔德斯是谁？",a="加尔德斯是一名人类术士，守护着暴风城法师区内已宰的羔羊地下墓穴中的秘密结社。他化解外界的怀疑，处理威胁，以免城中术士的秘密行踪暴露。",al={"加尔德斯","加尔德斯是谁","加尔德斯 暴风城"}},{q="在哪里可以找到加尔德斯？",a="加尔德斯位于暴风城法师区南半部的已宰的羔羊下方。进入酒馆，找到后方通往地下的通道，沿着蜿蜒的地下墓穴前行，便能抵达术士的据点。",al={"加尔德斯位置","加尔德斯在哪里","加尔德斯 已宰的羔羊"}},{q="加尔德斯为什么想要维沙克公爵死？",a="鲍雷斯·维沙克公爵发现了暴风城地下有术士活动的证据，便敦促城中的贵族展开调查。正式调查可能会让当局找到并铲除已宰的羔羊的术士集会，将其中的术士处死。",al={"为何杀死维沙克","维沙克公爵成为目标","贵族的陈酿缘由"}},{q="黑爪烈酒是什么？",a="黑爪烈酒是加尔德斯用烈性麦酒和两种罕见毒草酿制的致命饮品，毒草分别是夜色镇的蒂罗亚之泪和湿地的麝鼠根。他将其伪装成昂贵的陈酿，以便悄无声息地杀死维沙克公爵。",al={"黑爪烈酒","这酒是什么","维沙克 毒药"}},{q="黑爪是什么？",a="黑爪是加尔德斯在暴风城秘密术士网络中所属的组织或持有的头衔。其成员躲避暴风城卫兵和肯瑞托的追查，以致命手段保守秘密。",al={"黑爪含义","黑爪是谁","黑爪 术士"}},{q="暴风城为什么会容许术士存在？",a="暴风城并不公开容忍术士，因此他们藏身于已宰的羔羊下方的地窖。当局可能出于务实的考虑而睁一只眼闭一只眼，也可能始终不知情，因为像加尔德斯这样的密探会杀死那些准备揭露术士的人。",al={"术士是否合法","暴风城术士背景","城里为何有术士"}}},fx={ec5a54de={q="黑爪加尔德斯效忠哪一方？",a="黑爪加尔德斯关心的是暴风城隐秘术士们的生存，而非王国的律法。他在法师区地下以联盟的名义行事，却只忠于藏身已宰的羔羊的术士团体，随时准备除掉任何可能揭露他们黑暗研究的贵族或官员。",al={"黑爪加尔德斯的阵营","黑爪加尔德斯为谁效力","黑爪加尔德斯忠于暴风城吗"}},["212e3858"]={q="黑爪加尔德斯想要什么？",a="黑爪加尔德斯力图保护自己的术士团体，避开暴风城贵族的审查。当维沙克勋爵听闻他们在地下设立的据点，并推动正式调查时，黑爪加尔德斯立刻着手谋划，要悄无声息地将这位多管闲事的贵族永远除掉。",al={"黑爪加尔德斯的目标是什么","黑爪加尔德斯的计划","黑爪加尔德斯想要什么"}},f970876d={q="黑爪加尔德斯为什么会在暴风城？",a="黑爪加尔德斯在已宰的羔羊的地下墓穴中活动，借酒馆不起眼的外表掩护，秘密研习邪能魔法。他始终警戒着外来的威胁，确保聚集在地下的施术者能够钻研禁忌之术，不受城中当局干涉。",al={"黑爪加尔德斯为什么在这里","黑爪加尔德斯在已宰的羔羊的目的","黑爪加尔德斯为什么来到暴风城"}}},fp="25,241,25.383.0,22.451.1,12.371.2,33.220.0,25.220.0,40.217.0,25.234.0,23.196.0,45.258.0"}
P.entries["npc:zargh"] = {n="扎尔夫",s="扎尔夫在贫瘠之地的十字路口售卖肉食，并将上等肉品送往奥格瑞玛。",h="扎尔夫在贫瘠之地的十字路口售卖肉食，并将上等肉品送往奥格瑞玛。",kw={"贫瘠之地","屠夫","十字路口","格雷什卡","烤狮排","肉","扎尔夫"},ang={["faction:Horde"]="身为部落的一员，你可以看到，十字路口与奥格瑞玛之间的交通线如何利用双足飞龙，运送信使往返于贫瘠之地与杜隆塔尔之间。",["profession:Cooking"]="身为厨师，你可以向扎尔夫购买烤狮排的食谱，这是贫瘠之地出售的少数此类食谱之一。它能让你用当地捕食者的肉制作菜肴。"},sec={{t="十字路口的屠夫",b="扎尔夫在十字路口售卖腌肉、腿肉，以及来自周围平原的野味。准备深入荒野的旅人可以在他的店里补充给养。他还将上等肉品运过杜隆塔尔，送到奥格瑞玛的力量谷，交给旅店老板格雷什卡。"},{t="信使的差事",b="扎尔夫通过双足飞龙将鲜肉送往奥格瑞玛的旅店老板格雷什卡那里，确保肉在变质前送达。格雷什卡的一封信提起，扎尔夫曾在一次意外中失去一根手指。收到她的消息后，扎尔夫暗示，旅人日后或许会收到一份婚礼请柬。"}},faq={{q="在哪里可以找到扎尔夫？",a="你可以在十字路口找到扎尔夫，这里是部落在贫瘠之地中部的聚居地。他在营地的商贩中售卖肉食。",al={"扎尔夫位置","扎尔夫在哪里","扎尔夫非玩家角色"}},{q="扎尔夫与旅店老板格雷什卡有什么联系？",a="扎尔夫向奥格瑞玛的旅店老板格雷什卡供应贫瘠之地的上等肉品。他们的书信流露出亲密的私人情谊，而在收到一封来信后，扎尔夫暗示，或许很快就会有婚礼请柬送来。",al={"扎尔夫 格雷什卡","扎尔夫的关系","扎尔夫要和谁结婚"}},{q="扎尔夫的手指出了什么事？",a="格雷什卡的一封信说，扎尔夫在一次屠宰意外中失去了一根手指。这场意外至今仍是两人之间的私下笑谈，拿他切下的肉里究竟有什么来打趣。",al={"扎尔夫断指","扎尔夫的意外"}},{q="扎尔夫出售什么？",a="扎尔夫出售大块腿肉、腌制火腿排、野猪腿等补给品，以及烤狮排的食谱。",al={"扎尔夫出售物品","扎尔夫的货物"}}},fp="5,109,25.257.0,18.248.1,23.124.0,48.195.0,32.156.0,21.118.0"}
P.entries["npc:zarlman-two-moons"] = {n="扎尔曼·双月",s="在莫高雷中部，扎尔曼·双月引导着血蹄村的精神生活。贝恩·血蹄处理日常事务，扎尔曼则与灵魂沟通，引导年轻的牛头人完成幻象仪祭。",h="在莫高雷中部，扎尔曼·双月引导着血蹄村的精神生活。贝恩·血蹄处理日常事务，扎尔曼则与灵魂沟通，引导年轻的牛头人完成幻象仪祭。",kw={"血蹄","莫高雷","仪式","萨满祭司","灵魂","牛头人","双月","村庄","幻象","扎尔曼"},ang={["class:Shaman"]="身为萨满祭司，你遵循着扎尔曼所体现的牛头人传统：在务实地领导部族的同时，与灵魂沟通。",["faction:Horde"]="作为来到莫高雷中部聚居地的部落盟友，你可以向扎尔曼了解塑造牛头人文化的精神习俗。",["race:Tauren"]="身为牛头人冒险者，你可以寻求扎尔曼的指引，完成青年时期的神圣仪式，唤醒洞察灵魂的视野。"},sec={{t="无形世界的守护者",b="扎尔曼·双月照料灵魂，贝恩·血蹄则统领血蹄村的防御，处理世俗事务。村民们仰赖扎尔曼，与灵魂世界保持和谐。他将平原上的日常艰辛与先祖的声音联系起来，尊奉大地母亲与先祖的智慧。"},{t="幻象之礼",b="扎尔曼引导逐渐成年的牛头人完成幻象仪祭，这是每个人都必须经历的传统试炼。他教导初学者调制神圣的药剂，留心先祖降下的征兆。年轻的猎人、萨满祭司和战士通过仪式，寻找命中注定的道路和灵魂向导。扎尔曼教导他们，若没有心灵的明晰，在平原上拥有再强大的力量也意义甚微。"}},faq={{q="扎尔曼·双月是谁？",a="扎尔曼·双月引导着莫高雷血蹄村的精神生活。贝恩·血蹄负责村庄的实际防御与日常事务，扎尔曼则守护村民的心灵，引导年轻的牛头人遵循部族传统。",al={"扎尔曼是谁","扎尔曼·双月的故事","血蹄村的萨满祭司是谁"}},{q="扎尔曼在血蹄村担任什么职责？",a="扎尔曼负责血蹄村的精神事务、与先祖的沟通以及传统仪式。他与负责实际事务的贝恩·血蹄相辅相成，维系着部族与自然之灵及先祖之间的平衡。",al={"扎尔曼的职责","扎尔曼的作用","血蹄村的秘法师"}},{q="什么是幻象仪祭？",a="幻象仪祭是莫高雷年轻牛头人成年时经历的传统仪式。在扎尔曼的引导下，初学者饮下仪式药剂，看见幻象，并获得自然之灵的指引。",al={"幻象仪祭任务","什么是幻象仪祭","牛头人幻象任务"}},{q="在哪里可以找到扎尔曼·双月？",a="扎尔曼·双月位于莫高雷中部的血蹄村，就在石牛湖弯曲的湖岸内侧。",al={"扎尔曼在哪里","扎尔曼的位置","如何找到扎尔曼"}},{q="扎尔曼与贝恩·血蹄是什么关系？",a="在血蹄村，扎尔曼与贝恩·血蹄分掌精神与世俗事务。贝恩领导实际事务与军事行动，扎尔曼则提供神秘的智慧，守护部族的精神平衡。",al={"贝恩与扎尔曼","扎尔曼与贝恩的关系"}},{q="为什么幻象仪祭对年轻的牛头人很重要？",a="幻象仪祭标志着牛头人步入成年。它认可年轻人成为部族的一员，揭示他们内心的灵魂向导，并巩固他们与大地母亲的联系。",al={"为什么要进行幻象仪祭","幻象仪祭的重要性"}}},fp="17,218,20.295.0,18.358.0,25.228.0,44.221.0,27.197.0,37.107.0,43.202.0,52.191.0"}
P.entries["npc:zarrin"] = {n="扎瑞恩",s="在多兰纳尔的旅店后方，扎瑞恩传授卡多雷的烹饪之道。他在泰达希尔照看着一处露天炉火，年轻的暗夜精灵和访客在这里学习如何用这棵巨树上土生土长的动植物烹制餐食。",h="在多兰纳尔的旅店后方，扎瑞恩传授卡多雷的烹饪之道。他在泰达希尔照看着一处露天炉火，年轻的暗夜精灵和访客在这里学习如何用这棵巨树上土生土长的动植物烹制餐食。",kw={"烹饪","多兰纳尔","卡多雷","泰达希尔","训练师","扎瑞恩"},ang={["profession:Cooking"]="当你在泰达希尔踏上旅程时，扎瑞恩可以教你用野兽的肉和采集到的食材烹制营养丰富的餐食。",["race:NightElf"]="扎瑞恩在世界之树的树冠下传授传统风味与烹饪方法，让Kaldorei的日常饮食习俗延续至今。"},sec={{t="多兰纳尔的守炉人",b="在多兰纳尔的旅店后方，扎瑞恩照看着露天的烹饪用火，传授卡多雷的烹饪技艺。泰达希尔本土的动植物为这里的居民提供食物。扎瑞恩教访客如何采集食材，以及如何在家烹制餐食。"}},faq={{q="在哪里可以找到扎瑞恩？",a="扎瑞恩就在多兰纳尔的旅店后方，位于道路对面的露天院子里，守着一处烹饪用火。",al={"扎瑞恩位置","扎瑞恩在哪里","多兰纳尔烹饪训练师"}},{q="扎瑞恩教授什么？",a="扎瑞恩向新手传授烹饪基础和暗夜精灵的传统食谱。",al={"扎瑞恩训练师","扎瑞恩教什么"}},{q="扎瑞恩提供什么任务？",a="扎瑞恩通过卡多雷的菜谱任务，请旅行者帮忙烹制传统菜肴，教初来乍到的人掌握当地的烹饪方法。",al={"扎瑞恩任务","卡多雷的菜谱任务"}}},fp="6,180,24.214.0,24.96.0,23.81.0,29.135.0"}
P.entries["npc:zenn-foulhoof"] = {n="赛恩·腐蹄",s="在多兰纳尔以东，赛恩·腐蹄向旅人索要森林中的施法材料。暗夜精灵严密监视着他。",h="在多兰纳尔以东，赛恩·腐蹄向旅人索要森林中的施法材料。暗夜精灵严密监视着他。",kw={"腐化的松果","多兰纳尔","萨特","寻求救赎","泰达希尔","赛恩·腐蹄"},ang={["class:Druid"]="身为德鲁伊，你可能会认为，赛恩篡改野生施法材料、散播腐化污秽的行径违背了塞纳里奥的教义，这些教义旨在守护泰达希尔的纯净。",["race:NightElf"]="身为暗夜精灵，看到一个萨特闲躺在泰达希尔的神圣枝干上，你会觉得这是对 Elune 和荒野之灵的侮辱。萨特背叛了 kaldorei 的传承。"},sec={{t="林中的阴谋家",b="赛恩·腐蹄住在多兰纳尔外围，暗夜精灵容忍他留在那里，但始终监视着他。大多数萨特侍奉恶魔主人，公然发动袭击，赛恩却摆出一副友善的面孔。他声称自己已经改过自新，或是提出用东西交换夜刃豹的獠牙、巨翼枭的羽毛和树林蜘蛛丝。轻信他的年轻人为他收集邪恶仪式所需的材料。多兰纳尔的议会不会任由他胡作非为。他们命令旅人给他喂下腐化的森林果实，让这个诡计多端的萨特暂时变成一只无害的青蛙，以此羞辱他。"}},faq={{q="暗夜精灵为什么没有立刻攻击赛恩·腐蹄？",a="赛恩·腐蹄摆出一副友善的面孔，也没有在世界之树上公然犯下暴行。多兰纳尔的议会监视着他，选择当众羞辱他，而非立即判他死刑。",al={"赛恩 为什么友善","暗夜精灵为什么不杀 赛恩","赛恩·腐蹄邪恶吗"}},{q="给赛恩喂下腐化的松果和浆果后，会发生什么？",a="多兰纳尔的长者命人给赛恩喂下腐化的果实，作为他为恶行赎罪的惩罚。他吃下果实后，惩罚的结果便会显现。",al={"赛恩 赎罪任务","寻求救赎 任务","赛恩 青蛙"}},{q="萨特是什么？",a="萨特原本是暗夜精灵，在 上古之战 期间宣誓效忠燃烧军团后，变成了头生犄角、脚长裂蹄的恶魔。大多数萨特已被深深腐化，对未受腐化的同族充满暴戾的敌意。",al={"萨特是什么","萨特背景故事"}}},fp="13,97,22.539.1,64.190.0,64.120.1,16.215.0"}
P.entries["npc:zevrost"] = {n="泽弗洛斯特",s="在奥格瑞玛的暗影裂口，泽弗洛斯特教导术士运用邪能魔法。他指引部落学徒完成召唤仪式，掌握黑暗神器的使用方法。",h="在奥格瑞玛的暗影裂口，泽弗洛斯特教导术士运用邪能魔法。他指引部落学徒完成召唤仪式，掌握黑暗神器的使用方法。",kw={"暗影裂口","邪能魔法","地狱战马","奥格瑞玛","训练师","术士","泽弗洛斯特"},ang={["class:Warlock"]="身为部落术士，你可以向泽弗洛斯特学习高阶法术，并受他派遣，寻找专门的武器、副手物品和一匹烈焰战马。",["race:Orc"]="身为兽人，你周围的族人大多排斥恶魔魔法。泽弗洛斯特代表着那些在大酋长严密监视下仍然运用黑暗法术的施术者。"},sec={{t="黑暗法术大师",b="在奥格瑞玛地下的暗影裂口，泽弗洛斯特是萨尔这座都城中部落术士的主要导师之一。兽人曾遭受恶魔腐化，因此至今仍对邪能魔法心存戒备，施术者也受到严密监视。泽弗洛斯特教导术士严守戒律，驾驭恶魔而不屈从于它们的腐化。他说，邪能只会毁掉那些内心不够强大的人。"},{t="指引雄心",b="泽弗洛斯特对术士的指引不止于法术与诅咒，还为他们开启了探索更高深黑暗力量的道路。寻求奥拉赫宝珠等高阶法器，或希望掌握召唤烈焰缠身的地狱战马之法的学徒，往往都要经过他的指点。他将心怀壮志的施术者引荐给其他大师，包括贫瘠之地的梅纳拉·沃伦德，让他们将驾驭暗影魔法的能力推向极限。"}},faq={{q="泽弗洛斯特是谁？",a="泽弗洛斯特在奥格瑞玛地下的暗影裂口训练部落术士。他向初学者和经验丰富的施术者传授咒语，并指引他们完成重要的职业仪式。",al={"泽弗洛斯特职责","泽弗洛斯特是谁","泽弗洛斯特非玩家角色"}},{q="在哪里可以找到泽弗洛斯特？",a="泽弗洛斯特位于暗影裂口，那是奥格瑞玛主要城区下方的一处洞穴。",al={"泽弗洛斯特位置","泽弗洛斯特在哪","寻找泽弗洛斯特"}},{q="为什么奥格瑞玛容许泽弗洛斯特这样的术士存在？",a="萨尔领导的部落允许术士在隐蔽的暗影裂口修习法术，但对他们严加监视。兽人仍记得恶魔之血带来的腐化，但部落也看重术士在对抗敌人时所能施展的无情力量。",al={"为什么奥格瑞玛允许术士存在","术士 暗影裂口"}},{q="泽弗洛斯特如何看待恶魔魔法？",a="泽弗洛斯特认为，黑暗与奥术能量只会腐化意志薄弱的人。他敦促学生在研习时严守戒律，以免屈从于自己所驾驭的毁灭力量。",al={"泽弗洛斯特语录","泽弗洛斯特信念"}}},fp="7,146,23.333.0,21.386.0,15.184.0,27.91.0,53.230.0,46.187.0"}
P.entries["npc:zjolnir"] = {n="祖尼尔",s="在森金村，祖尼尔为黑暗之矛骑手和值得信赖的部落勇士饲养迅猛龙。他训练的坐骑承载着巨魔骑手深厚的文化自豪感。",h="在森金村，祖尼尔为黑暗之矛骑手和值得信赖的部落勇士饲养迅猛龙。他训练的坐骑承载着巨魔骑手深厚的文化自豪感。",kw={"黑暗之矛","杜隆塔尔","坐骑","迅猛龙","森金村","巨魔坐骑","祖尼尔"},ang={["faction:Horde"]="身为部落勇士，你可以向黑暗之矛部族证明自己坚定不移的忠诚，赢得骑乘祖尼尔的迅猛龙奔赴战场的资格。",["race:Troll"]="身为黑暗之矛巨魔，你可以骑乘这些迅捷的利爪猛兽，它们在你的文化传承和战斗传统中占据着核心地位。祖尼尔为你的族人提供这些坐骑。"},sec={{t="黑暗之矛迅猛龙饲养者",b="在森金村的兽栏附近，祖尼尔饲养着黑暗之矛偏爱的凶猛迅猛龙坐骑。它们生性凶猛，脾气多变，需要行家悉心照料，才能养大并配上鞍具投入战斗。对于掌握了骑术的巨魔同胞，祖尼尔会慷慨地赠予这些珍贵的坐骑。其他部落成员则必须先赢得黑暗之矛部族的崇拜，他才会放心地将迅猛龙交给他们。"}},faq={{q="在哪里可以找到祖尼尔？",a="祖尼尔在森金村照料迅猛龙兽栏，这座黑暗之矛定居点位于杜隆塔尔南部海岸。",al={"祖尼尔位置","祖尼尔在哪里","迅猛龙商人位置"}},{q="祖尼尔出售什么？",a="祖尼尔出售用哨子召唤的迅猛龙，它们是黑暗之矛巨魔的种族坐骑。他提供多个品种和颜色的坐骑，供初学骑术的骑手和经验丰富的老手选择。",al={"祖尼尔商人","他出售什么","巨魔坐骑商人"}},{q="非巨魔种族也能向他购买迅猛龙吗？",a="可以。非巨魔种族必须在暗矛巨魔中的声望达到崇拜，祖尼尔才会向他们出售坐骑。巨魔只需掌握所需的骑术即可购买。",al={"兽人能买迅猛龙吗","谁能向祖尼尔购买坐骑","部落迅猛龙坐骑"}}},fp="7,157,32.401.0,25.101.0,23.160.0,36.165.0"}
P.entries["npc:zor-lonetree"] = {n="佐尔·孤树",s="在索尔的堡垒，佐尔·孤树研究着杜隆塔尔之外与部落息息相关的事务。他对联盟政治的了解，帮助大酋长的幕僚研判卡利姆多各地的对外事务。",h="在索尔的堡垒，佐尔·孤树研究着杜隆塔尔之外与部落息息相关的事务。他对联盟政治的了解，帮助大酋长的幕僚研判卡利姆多各地的对外事务。",kw={"顾问","联盟政治","索尔的堡垒","奥格瑞玛","石爪山","力量谷","佐尔·孤树"},ang={["class:Shaman"]="作为一名回应元素力量异动的萨满祭司，你与佐尔·孤树有着共同的目标，他正关注着石爪山脉中受苦的灵体。",["faction:Horde"]="作为一名在人体聚居地或争议边界附近活动的部落斥候，你可以向奥格瑞玛的佐尔·孤树求助，解读敌人的意图与遗物。"},sec={{t="索尔的堡垒的顾问",b="佐尔·孤树身在索尔的堡垒，关注着杜隆塔尔之外的动向。作为部落高层一位精明的顾问，他对人类和联盟政治有着非同寻常的敏锐见解。异邦的奇物传到奥格瑞玛时，他会加以研究；大地之灵出现异动时，他会指引旅者前去调查。他曾检视从人类聚居地带回的贵族珠宝，也曾追查石爪山脉的灵体骚动，让大酋长的幕僚随时掌握政治与灵体两方面的情况。"}},faq={{q="佐尔·孤树是谁？",a="佐尔·孤树在奥格瑞玛的索尔的堡垒内为部落出谋划策。他对联盟政治的敏锐洞察，以及对卡利姆多灵体事务的关注，使他成为一位得力的顾问。",al={"佐尔·孤树是谁","佐尔是谁","佐尔 奥格瑞玛"}},{q="在哪里可以找到佐尔·孤树？",a="你可以在索尔的堡垒内找到佐尔·孤树，那里位于奥格瑞玛中心的智慧谷。",al={"佐尔·孤树位置","佐尔·孤树在哪里","奥格瑞玛的佐尔"}},{q="佐尔·孤树会交给冒险者什么任务？",a="佐尔·孤树派遣部落勇士援助石爪峰的灵体，平息石爪山脉的元素骚动。他也会分析斥候带回主城的奇异人类遗物。",al={"佐尔·孤树任务","石爪山的灵体 佐尔"}},{q="佐尔·孤树为什么了解联盟？",a="佐尔·孤树专精于对外事务和治国之道。他研究人类贵族的习俗和联盟的动向，因此能够解读其他兽人可能忽略的贵族印戒、礼服饰物和战术意图。",al={"佐尔·孤树 联盟背景故事","佐尔为什么了解联盟政治"}}},fp="12,154,24.537.0,20.175.0,30.98.0,46.200.0,53.213.0"}
P.entries["npc:zureetha-fargaze"] = {n="祖雷萨",s="在试炼谷，祖雷萨警惕着威胁年轻部落新兵的危险。她与杜隆塔尔的工头塔兹利尔一同，派新兵查明并铲除潜藏在谷中的火刃氏族邪教。",h="在试炼谷，祖雷萨警惕着威胁年轻部落新兵的危险。她与杜隆塔尔的工头塔兹利尔一同，派新兵查明并铲除潜藏在谷中的火刃氏族邪教。",kw={"火刃氏族","火刃奖章","杜隆塔尔","工头塔兹利尔","试炼谷","祖雷萨"},ang={["class:Warlock"]="作为试炼谷的一名术士，你会接到祖雷萨最初的任务，迎战那些被腐化的邪恶魔仆，它们与火刃氏族的黑暗召唤有关。",["race:Orc"]="作为一名初入世界的年轻兽人，你从祖雷萨身上看到了守护新家园所需的警觉，以免过去的恶魔污秽再度侵染这片土地。"},sec={{t="谷中的眼睛",b="工头塔兹利尔负责督管劳作与纪律，祖雷萨则留意着这些事务之外的危险。火刃氏族邪教已悄然潜入试炼谷，腐化了弱小的恶魔，并在附近的火刃集会所积蓄力量。她派未经考验的冒险者夺取邪教徒的徽章，证实他们的存在，并破坏他们初期的活动。随后，她指引久经磨练的新兵深入杜隆塔尔。"}},faq={{q="祖雷萨是谁？",a="祖雷萨守望着杜隆塔尔的试炼谷。她站在工头塔兹利尔附近，留意着威胁训练场的隐患。",al={"祖雷萨背景故事","祖雷萨是谁","祖雷萨试炼谷"}},{q="她为什么担忧火刃氏族？",a="火刃氏族邪教已在附近的一处洞穴扎根，在那里聚集邪恶的魔仆，腐化这片宁静的试炼之地。祖雷萨派新兵夺取邪教徒的徽章作为证据，并削减邪教的势力。",al={"火刃氏族试炼谷","祖雷萨为什么要徽章","火刃氏族邪教杜隆塔尔"}},{q="新兵完成最初的试炼后，她会派他们去哪里？",a="年轻的兽人和巨魔战胜当地的威胁、证明自己后，祖雷萨便派他们向东南方越过山脊，前往森金村援助黑暗之矛部族。",al={"祖雷萨之后去哪里","祖雷萨下一个任务","向森金报到"}}},fp="16,196,18.432.0,24.138.0,45.210.0,56.170.0"}
P.entries["quest:10"] = {n="谢申克的救赎",s="在加基森，高级勘探员菲兹杜瑟正为一件事烦心：他派往镇子东南方沙漠中大裂口的得力助手，初级勘探员谢申克失踪了。你受托查明谢申克的下落，至少也要找回勘探设备。",h="在加基森，高级勘探员菲兹杜瑟正为一件事烦心：他派往镇子东南方沙漠中大裂口的得力助手，初级勘探员谢申克失踪了。你受托查明谢申克的下落，至少也要找回勘探设备。",kw={"菲兹杜瑟","加基森","大裂口","谢申克","勘探","塔纳利斯"},sec={{t="失踪的勘探员",b="高级勘探员菲兹杜瑟忧心忡忡。初级勘探员谢申克进入大裂口后便杳无音信，而那里传回的最后一份报告提到，更多那种古怪的虫子出现了。菲兹杜瑟怀疑，这些虫子是否已经同时占据了沙漠中的两大片区域。你受托前去搜寻谢申克，找不到他的话，就找回勘探设备，菲兹杜瑟担心那可能是仅存的东西了。"},{t="菲兹杜瑟的判断",b="在菲兹杜瑟眼中，谢申克是个好地精，可惜他没能活下来。考虑到勘探设备记录下来的信息，菲兹杜瑟希望这次牺牲多少能有些价值。这些虫子表现出的狡诈令人担忧，而目前的研究表明，有第三方在控制它们，这对加基森乃至整片沙漠都不是好兆头。"}},faq={{q="高级勘探员菲兹杜瑟是谁？",a="菲兹杜瑟是加基森的高级勘探员，一直在调查沙漠中那些古怪的虫子，也是谢申克的上司。",al={"菲兹杜瑟","谁提供这个任务","勘探员菲兹杜瑟"}},{q="初级勘探员谢申克是谁？",a="谢申克曾是菲兹杜瑟的得力助手，被派往加基森东南方的沙漠后失踪了。",al={"谢申克","谢申克是谁","初级勘探员"}},{q="大裂口在哪里？",a="加基森东南方有一片沙漠区域，勘探员们称之为大裂口。",al={"大裂口位置","大裂口在哪里","裂口位置"}},{q="这一步之前是什么？",a="这一步接在腐化之巢之后。",al={"上一个任务","前置条件","先做什么任务"}}},fp="25,222,23.385.0,22.313.1,36.103.0,34.135.0,34.59.0,27.53.0"}
P.entries["quest:100"] = {n="水之召唤",s="在银松森林的海岸，萨满祭司在圣泉火盆完成水之召唤。仪式净除了附近的腐化，一个纯水之灵随之现身。",h="在银松森林的海岸，萨满祭司在圣泉火盆完成水之召唤。仪式净除了附近的腐化，一个纯水之灵随之现身。",kw={"圣泉火盆","水之召唤","元素生物","水之魂","萨满祭司试炼","银松森林","水之图腾"},ang={["class:Shaman"]="作为萨满祭司，你通过治愈远离家园、饱受苦难的水域来证明自己的决心，并获得与水之灵沟通的资格。",["faction:Horde"]="作为部落的一员，你帮助净化被遗忘者控制下的银松森林中被腐化的水道，维护元素的和谐。"},sec={{t="净化之光迸发",b="在圣泉火盆，你念出最后的咒文，唤出一道迸发的光芒。光芒驱散了威胁泉水的弱小之灵，海岸归于寂静。"},{t="水之灵的谢意",b="那些灵体消失后，一个水之魂出现在火盆旁。它感谢你举行仪式，并说此地的污秽已经消退。然而，银松森林日渐衰败的土地上，生机仍在不断流逝，部落的萨满祭司必须保持警惕，守护这里的生命。"}},faq={{q="火盆仪式结束时会发生什么？",a="在圣泉火盆念出的最后一道咒语会释放出一道光芒，摧毁附近被腐化的灵体，并净化周围的水流。",al={"火盆仪式光芒","永恒之泉爆发"}},{q="水之魂是谁？",a="水之魂是一个由纯净之水构成的小型元素生物，在圣泉火盆附近被腐化的元素生物遭到消灭后现身。",al={"水之灵银松森林","水之魂"}},{q="水之灵如何描述银松森林的状况？",a="水之灵感谢萨满祭司们，并说虽然当地的腐化已经消退，银松森林各处的生机仍在不断流逝，需要持续的照料。",al={"水之灵警告","银松森林腐化"}},{q="这个仪式在哪里举行？",a="仪式在银松森林海岸的圣泉火盆举行。",al={"火盆位置","水之召唤位置"}},{q="萨满祭司为何必须干预银松森林的状况？",a="萨满祭司必须保护远方饱受侵扰的水域，使其免遭疫病和残留腐化的侵蚀，这是元素试炼的一部分，旨在获得水之图腾，并证明自己守护平衡的决心。",al={"萨满祭司为何在此","萨满祭司银松森林职责"}},{q="试炼的下一步是什么？",a="与水之魂见面后，萨满祭司会获得元素残骸或指引，以完成旅程并铸成水之图腾。",al={"水之召唤下一步","水之魂现身之后"}}},fp="13,151,26.151.0,21.276.0,46.162.0,40.155.0,48.140.0,34.88.0,41.160.0,30.146.0"}
P.entries["quest:1001"] = {n="传声盒411号",s="在黑海岸沿岸，传声盒 411 需要蛇颈龙的眼球才能恢复运作。这项联盟差事来自维兹班恩·曲针，一位性情古怪、醉醺醺的侏儒发明家，他通过机械中继网络开展工作。",h="在黑海岸沿岸，传声盒 411 需要蛇颈龙的眼球才能恢复运作。这项联盟差事来自维兹班恩·曲针，一位性情古怪、醉醺醺的侏儒发明家，他通过机械中继网络开展工作。",kw={"奥伯丁","传声盒 411","蟹肉酿酒","黑海岸","侏儒","蛇颈龙的眼球","机械修造","维兹班恩·曲针"},ang={["profession:Engineering"]="用蛇颈龙的眼球校准机械发射器，展现了不循常规的工匠突破界限的手段。",["race:Gnome"]="维兹班恩·曲针展现了侏儒开展野外工作的古怪方式：大胆的发明、奇特的部件选择，以及把危险的游泳差事交给碰巧路过的人。",["race:NightElf"]="奥伯丁的哨兵守望着黑海岸的水域，不过通常任由岸边那些古怪的侏儒装置自行运作。"},sec={{t="杂音中的声音",b="在你帮忙修好更南边的传声盒827后，侏儒发明家维兹班恩·曲针的声音再次伴着噼啪杂音从机械发射器中传来。他待在某个看不见的安全地方，指引冒险者沿着黑海岸雾气弥漫的沙滩向北，寻找一台名为传声盒411的受损终端。他的传话不时被打嗝声打断，还夹杂着对蟹肉酒的低声赞叹。他说，当地的水生掠食者身上有他的海岸设备维持运作所需的东西。"},{t="浪涛下的眼睛",b="要让 传声盒 411 恢复运作，必须把蛇颈龙的眼球放进它敞开的舱口。黑海岸鱼龙 是凶猛的海兽，在奥伯丁外的浅海游荡，据维兹班恩所说，它们的眼球具有重新校准装置所需的特性。这些眼球让设备重新启动，通信线路也随之接通，传来下一项任务，交代任务的声音却更加含混不清。"}},faq={{q="传声盒 411 是什么？",a="传声盒 411 是一台机械发射器，位于奥伯丁以北的黑海岸岸边。它属于一个实验性的监听与研究网络，由侏儒工程师维兹班恩·曲针维护。",al={"传声盒 411","传声盒 411 是什么","传声盒 411 用途"}},{q="维兹班恩·曲针是谁？",a="维兹班恩·曲针是一位性情古怪的侏儒工匠，通过传声盒网络远程传话。他在野外研究期间纵情享用 蟹肉葡萄酒，依靠路过的冒险者前往危险之地收集动物器官。",al={"维兹班恩","维兹班恩 是谁","传声盒 制造者"}},{q="机器为什么需要蛇颈龙的眼球？",a="侏儒工程学常常将古怪的有机物与机械部件结合，用来完成不同寻常的任务。维兹班恩说，蛇颈龙的眼球对修复 传声盒 411 至关重要，无论是用于光学传感器，还是生物研究。",al={"为什么需要蛇颈龙的眼球","机器所需的蛇颈龙的眼球","传声盒 眼球"}},{q="传声盒 411 在哪里？",a="传声盒 411 位于黑海岸的沙滩上，在暗夜精灵定居点奥伯丁以北。",al={"传声盒 411 在哪里","传声盒 411 位置","寻找 传声盒 411"}},{q="在哪里能找到黑海岸鱼龙？",a="黑海岸鱼龙 在奥伯丁外及附近沿岸的海水中游动。游过碎浪区，就很容易找到它们。",al={"鱼龙 在哪里","蛇颈龙的眼球来源","鱼龙 位置"}},{q="修好 传声盒 411 后会发生什么？",a="机器重新嗡嗡运转起来后，维兹班恩·曲针会隔着杂音向你道谢，再喝上一口，然后问你是否愿意修理他的下一台机器，传声盒323。",al={"下一台 传声盒","传声盒 411 之后的任务","传声盒 任务链"}}},fp="11,196,24.357.0,21.320.0,20.197.0,27.222.0,38.190.0,29.89.0,36.120.0,40.151.0"}
P.entries["quest:1002"] = {n="传声盒323号",s="维兹班恩·曲针的野外研究来到了传声盒 323，这是黑海岸沿岸的第三站。你收集六颗月夜猛虎的牙齿，将它们放进奥伯丁以北的机器里。",h="维兹班恩·曲针的野外研究来到了传声盒 323，这是黑海岸沿岸的第三站。你收集六颗月夜猛虎的牙齿，将它们放进奥伯丁以北的机器里。",kw={"奥伯丁","传声盒","传声盒 323","曲针","黑海岸","牙齿","月夜猛虎","维兹班恩"},ang={["profession:Engineering"]="身为工程师，你能看出，尽管这些Buzzboxes运转粗糙，却将自动化材料处理与远距离语音传输结合在了一起。",["race:Gnome"]="身为侏儒，你能听出维兹班恩的远程语音网络正在运作，尽管他缺乏自律，这仍展现了侏儒工程学的巧思。",["race:NightElf"]="身为暗夜精灵，你知道面对凶猛的Moonstalkers时，必须心怀敬畏，谨慎行事。侏儒科学却将它们致命的獠牙磨成了粉末。"},sec={{t="含糊不清的传讯",b="你操作了更南边的传声盒 411后，维兹班恩·曲针的声音伴着噼啪声从扬声器里传来。他喝了太多酒，指示含糊不清，但还是让你前往奥伯丁以北，寻找道路桥梁附近的传声盒 323。他的研究需要六颗月夜猛虎的牙齿，牙齿来自游荡在黑海岸森林中的凶猛猎手。"},{t="侏儒野外机械",b="在你动手之前，传声盒 323便不断传出杂音和隐约的嘟囔声。将所需的牙齿放进进料斗，机器便剧烈震动起来，咔咔作响，将牙齿磨成粉末。维兹班恩醉醺醺的声音再次从收发器里传来，庆贺你送来了材料，并指引你前往他那分散各处的网络中的下一台机器。"}},faq={{q="传声盒 323在哪里？",a="传声盒 323位于黑海岸的奥伯丁以北，就在主路旁，靠近横跨当地河流的桥梁。",al={"传声盒 323位置","传声盒 323在哪","寻找传声盒 323"}},{q="是谁在通过传声盒说话？",a="维兹班恩·曲针是一位身处黑海岸别处的侏儒发明家，他一边喝着麦酒，一边通过远程发射器说话。",al={"传声盒里谁在说话","传声盒侏儒","维兹班恩·曲针"}},{q="传声盒 323会怎样处理牙齿？",a="将月夜猛虎的牙齿放进去，传声盒 323的齿轮就会把它们磨成细粉，供维兹班恩进行自动化生物采样。",al={"牙齿如何处理","为何需要月夜猛虎的牙齿","传声盒研磨"}},{q="黑海岸的月夜猛虎在哪里？",a="月夜猛虎及其幼崽在奥伯丁南北道路沿线的幽暗林地和山丘间徘徊。",al={"月夜猛虎在哪","刷月夜猛虎的牙齿","月夜猛虎位置"}},{q="传声盒 323的前后分别是什么任务？",a="传声盒 323的前一个任务是收集蛇颈龙的眼球的传声盒 411，后一个任务则是传声盒 525，要求你沿路向南，从蓟熊身上收集灰白的头皮。",al={"传声盒任务链","传声盒 323后续任务","传声盒顺序"}},{q="为什么维兹班恩说话如此语无伦次？",a="维兹班恩指路时已经酩酊大醉，时不时停下来寻找自己的麦酒，还在说话间隙大口吞饮，发出响亮的声音。",al={"维兹班恩为何醉酒","传声盒语音含糊"}}},fp="11,172,22.311.0,23.329.0,29.108.0,36.120.0,40.136.0,43.110.0,46.179.0,37.129.0"}
P.entries["quest:1003"] = {n="传声盒525号",s="在黑海岸沿岸，传声盒 525正等着人们完成维兹班恩·曲针最后的古怪要求。这名侏儒散布各处的机器需要动物残骸，以及越来越奇怪的材料。",h="在黑海岸沿岸，传声盒 525正等着人们完成维兹班恩·曲针最后的古怪要求。这名侏儒散布各处的机器需要动物残骸，以及越来越奇怪的材料。",kw={"奥伯丁","传声盒 525","黑海岸","灰色头皮","蓟熊","蓟熊啤酒","维兹班恩·曲针"},ang={["race:Gnome"]="身为侏儒，你能从这些机器中看出维兹班恩的雄心：复杂的工程技术，与令人质疑的实际用途混在了一起。",["race:NightElf"]="身为暗夜精灵，你知道黑海岸的守护者治下严明，对侏儒鲁莽的摆弄几乎没有耐心。"},sec={{t="含混的传讯",b="传声盒 323维护完毕后，嘎嘎作响的扬声器里传来了维兹班恩·曲针含混不清的指示。他夹杂着醉笑，口齿不清地絮叨着路线，让帮手们沿黑海岸的大路一路向南。他让他们猎杀灰斑蓟熊，将四块厚实的头皮放进传声盒 525的舱格里。这台机器藏在路旁灌木丛中的一道栅栏后面。"},{t="蒸馏者的秘密",b="传声盒 525里传出了维兹班恩·曲针的声音，喧闹的歌声盖过了机器的嗡鸣。当灰毛熊的头皮被放进收纳舱后，维兹班恩承认了这些机器的用途。他的装置可以传递消息，也能酿酒和蒸馏烈酒。暗夜精灵不欢迎他在他们的城镇里贩酒，所以他把机器藏在了野外。这些熊头皮是酿造烈性蓟熊啤酒的原料。"}},faq={{q="传声盒 525在哪里？",a="从奥伯丁沿大路向南走很远，就能在路边一道简陋的栅栏附近找到传声盒 525，它有一部分藏在灌木下。",al={"传声盒 525位置","传声盒 525在哪","寻找传声盒 525"}},{q="维兹班恩为什么需要灰毛熊的头皮？",a="维兹班恩说，修理传声盒 525需要灰毛熊的头皮，就像之前的机器需要蟹腿、蛇颈龙的眼球和月夜猛虎的牙齿一样。一首关于蓟熊啤酒的醉歌暗示，这些头皮另有用途。",al={"为何需要灰毛熊头皮","传声盒熊头皮","头皮有何用途"}},{q="维兹班恩为什么把传声盒藏在荒野里？",a="维兹班恩把机器安置在奥伯丁外，依靠旅人前去照料。传声盒 525揭示了他藏起机器的原因：暗夜精灵不欢迎他在他们的城镇里贩酒。",al={"传声盒为何藏起来","为何隐藏传声盒","维兹班恩的秘密"}},{q="是谁在通过传声盒说话？",a="维兹班恩·曲针是一名颇有进取心的侏儒工匠，他通过安装在黑海岸各处传声盒里的语音传送器说话。",al={"谁在传声盒里说话","传声盒声音","维兹班恩的身份"}},{q="没有头皮，维兹班恩也能通过机器说话吗？",a="能。头皮放进去之前，维兹班恩就已经能通过传声盒 525说话了。等工作完成，他才解释索要头皮的原因。",al={"传声盒坏了吗","维兹班恩说谎了吗"}},{q="传声盒唱的是什么歌？",a="在你放入头皮之前，扬声器反复唱着一首醉醺醺的打油诗：“蟹肉葡萄酒虽甜，蛇颈龙麦酒也香，月夜猛虎私酿更是上佳。可要说心头最爱，还得是蓟熊啤酒，很快我就能喝上啦！”",al={"传声盒唱歌","蓟熊 啤酒之歌"}}},fp="11,167,22.405.0,22.401.1,29.134.0,38.211.1,58.182.1,36.138.0,57.125.1,32.245.0"}
P.entries["quest:1007"] = {n="远古雕像",s="在佐拉姆海岸附近，一次娜迦袭击过后，古代雕像遗失了。精灵塔尔伦在灰谷西北海岸扎营，需要你找回他掉落在浪涛中的遗物。",h="在佐拉姆海岸附近，一次娜迦袭击过后，古代雕像遗失了。精灵塔尔伦在灰谷西北海岸扎营，需要你找回他掉落在浪涛中的遗物。",kw={"古代雕像","灰谷","娜迦","佐拉姆的废墟","卢泽尔","塔尔伦","佐拉姆海岸"},ang={["faction:Alliance"]="作为一名身在灰谷的联盟旅人，你面临着东部部落哨站的威胁，也要提防盘踞西部海岸的敌对娜迦。",["race:NightElf"]="作为一名暗夜精灵，你能看出佐拉姆的废墟是大灾变之前Kaldorei文明的遗存。保护雕像这样的文物，能让先祖的记忆延续下去。"},sec={{t="海岸伏击",b="塔尔伦驾着小船，穿过灰谷西北海岸佐拉姆沉没废墟旁的浅水区时，遭到了娜迦的袭击。他狼狈地逃上岸，只带着勉强够用的补给，匆匆扎了营。仓皇逃命时，他把从废墟中找到的古代雕像掉在了沙滩上。"},{t="佐拉姆的古老秘密",b="为了古代雕像，塔尔伦冒险踏入了娜迦盘踞的佐拉姆海岸。等你归还雕像后，他会解释，这座沉没的城市藏着数百年来被人遗忘的谜团。他相信，这件精巧的雕刻是揭开潮水之下隐秘的关键。"}},faq={{q="塔尔伦是谁，为什么独自待在海岸上？",a="塔尔伦是一名精灵探险者，在佐拉姆海岸的南端扎营。对历史的好奇驱使他前来探索佐拉姆沉没的废墟，但娜迦伏击了他的小船，迫使他逃到了岸上。",al={"塔尔伦是谁","塔尔伦的故事","灰谷塔尔伦"}},{q="塔尔伦在哪里弄丢了雕像？",a="塔尔伦在营地以北的海岸附近弄丢了雕像。雕像半埋在沙中，附近有一艘翻覆的小船和一棵倒下的树，就在他的小船遇袭的浪涛边。",al={"古代雕像在哪里","雕像位置","寻找古代雕像"}},{q="古代雕像是什么？",a="古代雕像是一件从佐拉姆水下废墟中找回的暗夜精灵遗物。塔尔伦说，它具有历史与神秘学意义，也是揭开这座沉没之城残存秘密的关键。",al={"雕像是什么","雕像的意义"}},{q="佐拉姆海岸为什么会有娜迦？",a="娜迦已将佐拉姆沉没的废墟据为己有。他们在灰谷西部的海滩上巡逻，抵御外来者，周围的精灵废墟早在一万年前、大灾变发生之前就已沉入海底。",al={"这里为什么有娜迦","佐拉姆海岸娜迦","灰谷的娜迦"}},{q="归还雕像后会发生什么？",a="归还雕像后，塔尔伦便能解开这片地区更多的谜团。娜迦的威胁依然存在，而你接下来将被指引去寻找他们的首领卢泽尔。",al={"找回雕像后做什么","后续任务"}},{q="雕像有守卫吗？",a="雕像就在水边，周围到处都是敌对的娜迦战士，以及在海岸徘徊的野兽。对独行的旅人而言，取回它十分危险。",al={"雕像有守卫吗","雕像附近的敌人"}}},fp="21,193,19.256.0,20.241.0,47.190.0,35.183.0,30.196.0,39.210.0,43.153.1,25.163.0"}
P.entries["quest:1008"] = {n="佐拉姆海岸",s="如今，娜迦正从佐拉姆海岸威胁灰谷。阿斯特兰纳的辛德瑞尔·速火派遣联盟勇士扫荡西北海岸，那里坐落着一座古城的废墟。阻止娜迦，便能保护森林，抵御暗夜精灵遥远过往中挥之不去的阴影。",h="如今，娜迦正从佐拉姆海岸威胁灰谷。阿斯特兰纳的辛德瑞尔·速火派遣联盟勇士扫荡西北海岸，那里坐落着一座古城的废墟。阻止娜迦，便能保护森林，抵御暗夜精灵遥远过往中挥之不去的阴影。",kw={"灰谷","阿斯特兰纳","娜迦","辛德瑞尔","海岸","大分裂","速火","怒尾","佐拉姆"},ang={["class:Hunter"]="身为猎人，你可以利用饱受海风侵袭的海岸和残破的废墟作为观察点，追踪从碎浪中现身的两栖袭击者。",["faction:Alliance"]="对联盟而言，守住灰谷西翼，才能避免阿斯特兰纳陷入海岸入侵者与部落伐木势力的夹击。",["race:NightElf"]="对暗夜精灵而言，每一个倒在海岸上的娜迦，都会唤起艾萨拉的傲慢与Sundering撕裂远古世界的记忆。Sentinels不会让这些扭曲的同族在卡利姆多重新夺回土地。"},sec={{t="海岸上的阴影",b="在灰谷的西北边缘，佐拉姆海岸与迷雾之海相接。海岸位于阿斯特兰纳西北方，森林的树冠在这里让位于海滨。这片海滩曾沉寂了漫长岁月，散落的石块来自一万年前毁灭的文明。如今，怒尾娜迦已从幽暗的潮水中大举涌出。他们在暗夜精灵领地的边界建立了滩头阵地，威胁着要向内陆推进。"},{t="沉没的佐拉姆城",b="佐拉姆城在大灾变中沉入海底，如今只剩碎裂的残垣，隐没在浪涛之下。漫长岁月里，这座城一直荒废着，几乎被卡多雷遗忘。娜迦突然出现在废墟中，唤起了阿斯特兰纳守卫们痛苦的回忆。辛德瑞尔·速火这样的哨兵知道，这些入侵者是他们扭曲的同族，诞生于那场远古灾难。他们不会让深海再次吞噬这片海岸。"}},faq={{q="佐拉姆海岸是什么地方？",a="佐拉姆海岸沿灰谷崎岖的西北海岸延伸，面朝迷雾之海。古老的卡多雷城市佐拉姆就坐落于此，它在一万年前的大灾变中被大海吞没。",al={"佐拉姆海岸","佐拉姆海岸在哪","佐拉姆是什么"}},{q="娜迦为何进攻灰谷海岸？",a="阿斯特兰纳的哨兵并不确切知道娜迦为何进攻灰谷海岸。娜迦的军营和侵略行为威胁着森林，因此暗夜精灵在他们推进之前便发起了攻击。",al={"娜迦为何在此","娜迦在佐拉姆的动机","为何是怒尾"}},{q="辛德瑞尔·速火是谁？",a="辛德瑞尔·速火是驻守阿斯特兰纳的一名暗夜精灵哨兵。她警戒着危及灰谷的威胁，并组织反击敌人的入侵，包括盘踞海岸的娜迦。",al={"辛德瑞尔","阿斯特兰纳任务发布者","速火"}},{q="暗夜精灵与娜迦有着怎样的共同历史？",a="娜迦曾是侍奉艾萨拉女王的上层精灵暗夜精灵。大灾变期间，永恒之井崩塌，他们被拖入深渊，变成了蛇形生物。这份同族之缘，让如今的卡多雷每次与他们相遇都倍感苦涩。",al={"娜迦与精灵的关系","与娜迦的历史","共同历史"}},{q="清剿佐拉姆海岸之后会发生什么？",a="海岸上的娜迦数量减少后，辛德瑞尔·速火便派遣联盟守卫，应对边境沿线其他来自空中的威胁。她指派斥候向南前往石爪山，对付凶猛的双足飞龙。",al={"下一个任务","佐拉姆海岸之后","风巢双足飞龙"}},{q="部落也在佐拉姆海岸活动吗？",a="是的。阿斯特兰纳的联盟勇士在海岸猎杀娜迦，而部落则据守佐拉姆加前哨站，那是海岸上一处设有防御工事的海滨前哨。部落在此争夺领地，同时与娜迦和联盟交战。",al={"部落与佐拉姆海岸","佐拉姆加","部落是否在此"}}},fp="16,272,20.381.0,25.412.0,25.202.0,45.200.0,27.187.0,52.277.0,45.212.1,46.225.0"}
P.entries["quest:1009"] = {n="卢泽尔",s="塔尔伦需要佐拉姆之戒，才能打开在海岸上发现的古代雕像。纳迦已将戒指带到了他们的海岛圣所。",h="塔尔伦需要佐拉姆之戒，才能打开在海岸上发现的古代雕像。纳迦已将戒指带到了他们的海岛圣所。",kw={"灰谷","纳迦","佐拉姆之戒","卢泽尔","大分裂","塔尔伦","佐拉姆海岸"},ang={["faction:Alliance"]="身为联盟旅者，你帮助塔尔伦遏制沿灰谷北部海岸登陆的纳迦威胁。",["race:NightElf"]="身为暗夜精灵，夺回佐拉姆之戒，就是从亵渎先祖沉没废墟的纳迦手中夺回一份祖先的遗产。"},sec={{t="佐拉姆之钥",b="塔尔伦相信，佐拉姆之戒能打开从海岸寻回的古代雕像。在大灾变撕裂卡利姆多、令沿海城市沉没之前，强大的暗夜精灵贵族统治着佐拉姆。这枚戒指曾是他们的王权信物之一。灾变之后，它消失在海浪之下，长达数千年，让沉没遗物的秘密始终避开了好奇的目光。"},{t="纳迦入侵",b="纳迦最近来到佐拉姆海岸，开始搜寻故土的废墟。卢泽尔是当地纳迦族群的首领，她找到了佐拉姆之戒，并将它带到了北方海岛上的圣所。暗夜精灵塔尔伦请求联盟旅者猎杀卢泽尔，夺回这件传世之物，好让他打开从浅滩寻回的雕像。"}},faq={{q="卢泽尔是谁？",a="卢泽尔统领着灰谷西北部佐拉姆海岸的纳迦。她的巢穴位于北方近海的一座岛屿上，她在那里守护着从沉没的暗夜精灵文明中寻回的宝藏。",al={"卢泽尔背景故事","纳迦首领是谁","卢泽尔首领"}},{q="佐拉姆之戒是什么？",a="在大灾变之前，佐拉姆之戒属于佐拉姆的古代统治者。塔尔伦相信，它能打开一尊古代雕像上的锁。",al={"佐拉姆之戒背景故事","戒指有什么用","佐拉姆钥匙"}},{q="塔尔伦为什么需要这枚戒指？",a="塔尔伦想揭开一尊古代卡多雷雕像内部的秘密，这尊雕像最近才从海岸寻回。他相信，只有佐拉姆之戒才能转动雕像上的锁。",al={"为什么要取回佐拉姆之戒","塔尔伦雕像的锁"}},{q="佐拉姆城去了哪里？",a="一万年前，大灾变摧毁了古老的卡多雷城市佐拉姆。城中宏伟的石砌建筑大多沉入了迷雾之海，只在沿岸留下零散的废墟。",al={"佐拉姆发生了什么","佐拉姆废墟"}},{q="卢泽尔在哪里？",a="卢泽尔居住在佐拉姆海岸北端外海的一座大型岩石岛上，周围簇拥着蛇形的追随者。",al={"卢泽尔在哪里","卢泽尔海岛位置"}},{q="取回戒指后会发生什么？",a="你归还戒指后，塔尔伦就能完成在海岸上的调查。他会酬谢你的帮助，并铭记你的功劳。",al={"塔尔伦接下来做什么","卢泽尔后续"}}},fp="6,125,16.370.0,18.369.0,14.193.0,26.137.0,29.161.0,31.183.0,24.122.0,39.124.0"}
P.entries["quest:101"] = {n="惩罚图腾",s="在夜色镇，伊瓦夫人为旅人提供抵御暮色森林危险的护符。她需要食尸鬼的獠牙、骷髅的手指和蜘蛛毒液，为惩罚图腾施加附魔，让这枚护符能够反击攻击者。",h="在夜色镇，伊瓦夫人为旅人提供抵御暮色森林危险的护符。她需要食尸鬼的獠牙、骷髅的手指和蜘蛛毒液，为惩罚图腾施加附魔，让这枚护符能够反击攻击者。",kw={"夜色镇","暮色森林","食尸鬼的獠牙","伊瓦夫人","防护符","骷髅的手指","蜘蛛毒液","惩罚图腾"},ang={["class:Paladin"]="身为圣骑士，你或许会质疑用亡灵的骨头和蜘蛛毒液制作护符的做法。暮色森林的种种危险，却让人难以轻视实用的民间巫术。",["class:Priest"]="身为牧师，你知道Church of the Holy Light教导人们心怀信仰、虔诚奉献，而伊瓦夫人这样的秘术师则通过阴森的有形护符引导精神意志。",["class:Warlock"]="身为术士，你能认出艾瓦的防护符中编织的反击诅咒。",["faction:Alliance"]="在无法获得大规模军事增援的边境地区，联盟旅人常常依靠伊瓦夫人这样的当地秘术师，获取民间护符和防护法术。"},sec={{t="血光之兆",b="伊瓦夫人在夜色镇烛光摇曳的家中，为登门者占卜命运。她感知到前方的危险与暴力，除了占卜，也提供实用的巫术。为了制作抵御暮色森林掠食者的护符，她需要从这片闹鬼的森林中收集十颗食尸鬼的獠牙、十根骷髅的手指和五瓶蜘蛛毒液。"},{t="艾瓦的附魔",b="伊瓦夫人用附魔将食尸鬼的獠牙、躁动不安的骷髅的手指和蜘蛛毒液结合起来。在佩戴者身陷致命险境时，图腾会散发出一道魔法光环，将暴行反弹，伤害任何攻击佩戴者的人。"}},faq={{q="伊瓦夫人是谁？",a="伊瓦夫人是一位住在夜色镇的占卜师和秘术师。她解读预兆，为面临暮色森林超自然危险的当地居民和旅人制作防护符。",al={"伊瓦夫人","谁提供这个任务","艾瓦 夜色镇"}},{q="惩罚图腾有什么用途？",a="惩罚图腾是一枚用来抵御攻击者的附魔护符。当佩戴者受到威胁时，它的魔力会反击那些企图伤害佩戴者的人。",al={"惩罚图腾用途","图腾有什么作用","图腾背景故事"}},{q="伊瓦夫人为什么需要食尸鬼的獠牙、骷髅的手指和蜘蛛毒液？",a="伊瓦夫人用食尸鬼的獠牙、骷髅的手指和蜘蛛毒液制作防护附魔，对攻击者施以反击。",al={"为什么需要蜘蛛毒液","图腾材料","为什么需要骷髅的手指"}},{q="在哪里能找到制作图腾的材料？",a="这些材料来自暮色森林中的亡灵和野兽。食尸鬼和骷髅在墓地与果园中游荡，而大型毒蜘蛛则遍布幽暗的林地。",al={"哪里能找到獠牙","哪里获取材料","食尸鬼和蜘蛛在哪里"}},{q="伊瓦夫人预见了什么危险？",a="伊瓦夫人警告说，前方有危险和流血之灾。她说，低语的风诉说着旅人前路上的威胁。",al={"艾瓦 占卜","即将到来的危险","未来的流血之灾"}},{q="制作图腾算是黑暗魔法吗？",a="艾瓦的法术用到了阴森的民间巫术和尸体残肢，但暮色森林危机四伏，防护符也因此成为人们认可的自卫手段。",al={"这是通灵术吗","艾瓦 邪恶吗","黑暗魔法图腾"}}},fp="23,185,22.294.0,17.231.0,18.173.0,47.153.0,73.137.0,45.176.0,36.105.0,44.131.0"}
P.entries["quest:1010"] = {n="巴斯兰的头发",s="在灰谷西部的迈斯特拉岗哨，奥雷迪尔·阔叶正在为阿斯特兰纳一个生病的孩子寻找巴斯兰的头发。他认为疾病侵袭了孩子的灵魂，便派你前往北方的古老废墟，那里过去曾出产这种罕见的疗伤草药。",h="在灰谷西部的迈斯特拉岗哨，奥雷迪尔·阔叶正在为阿斯特兰纳一个生病的孩子寻找巴斯兰的头发。他认为疾病侵袭了孩子的灵魂，便派你前往北方的古老废墟，那里过去曾出产这种罕见的疗伤草药。",kw={"灰谷","巴斯兰的头发","巴斯兰鬼屋","黑海岸","被遗忘者","迈斯特拉岗哨","奥雷迪尔·阔叶","植物束"},ang={["faction:Alliance"]="作为联盟的一员，你帮助阿斯特兰纳的孩子取得药物，也支援了坚守灰谷西部的前线定居点，抵御敌对的部落和被遗忘者的扩张。",["profession:Herbalism"]="采药的追踪能力可以显示散落在巴斯兰鬼屋各处的植物束，让你在废墟中寻找它们时轻松许多。",["race:NightElf"]="作为暗夜精灵，你面对的是盘踞在巴斯兰鬼屋的被遗忘者，他们严重威胁着灰谷北部的神圣疆界和那里的孩子。"},sec={{t="灵魂之疾",b="奥雷迪尔·阔叶是迈斯特拉岗哨的一名暗夜精灵草药师，正为一种棘手的疾病发愁。岗哨就在黑海岸边界以南。阿斯特兰纳有个孩子病得很重，寻常药物都已无效。奥雷迪尔认为，疾病不仅侵袭了孩子的肉体，也侵袭了她的灵魂。他正在寻找巴斯兰的头发，这种罕见的疗伤草药生长在北方古老的精灵废墟中。"},{t="废墟中的入侵者",b="巴斯兰鬼屋位于通往黑海岸的道路东侧。被遗忘者的密探已潜入这片残破的聚居地，让寻找草药束的过程变得危机四伏。草药送回迈斯特拉岗哨后，奥雷迪尔便调制出一剂舒缓病痛的药水。亡灵在灰谷北部公然活动，令他深感不安。"}},faq={{q="巴斯兰的头发是什么？",a="巴斯兰的头发是一种罕见的药用植物，原产于灰谷的巴斯兰鬼屋。暗夜精灵草药师看重它的疗愈功效，尤其是它能缓解灵魂的病痛，而非寻常的肉体创伤。",al={"巴斯兰的头发植物","头发是什么","巴斯兰 草药"}},{q="迈斯特拉岗哨有谁生病了？",a="迈斯特拉岗哨没有人生病。生病的是阿斯特兰纳的暗夜精灵小女孩蕾拉·怀特姆恩；她是皮尔图拉斯·怀特姆恩的女儿。她的病情每个小时都在恶化，寻常药物也无济于事，因为这疾病似乎源于灵魂，这促使奥雷迪尔·阔叶寻求古老草药的帮助。",al={"迈斯特拉 生病的孩子","奥雷迪尔在医治谁","谁需要药剂"}},{q="巴斯兰鬼屋在哪里？",a="巴斯兰鬼屋位于灰谷西北部，在迈斯特拉岗哨以北，就在通往黑海岸边界的大路东侧。敌对的被遗忘者特工已占据这片废墟。",al={"巴斯兰鬼屋位置","哪里能找到巴斯兰的头发","巴斯兰 在哪里"}},{q="为什么巴斯兰鬼屋有被遗忘者？",a="没人知道被遗忘者有什么企图。直到草药送回，奥雷迪尔才得知他们的存在，亡灵竟潜伏在暗夜精灵领地如此深入的地方，令他十分不安。",al={"巴斯兰 的亡灵","灰谷为什么有 被遗忘者","被遗忘者 巴斯兰鬼屋"}},{q="采集植物后会发生什么？",a="你为奥雷迪尔带回五束巴斯兰的头发后，他会调制一剂药水，并请你尽快送给阿斯特兰纳那个生病的孩子。后续任务奥雷迪尔的药剂由此开始。",al={"巴斯兰的头发后续任务","奥雷迪尔用头发做什么","奥雷迪尔的药剂任务链"}},{q="草药师更容易找到植物束吗？",a="是的。这些植物束散落在地上，单凭肉眼很难发现。学过采药的冒险者可以用草药追踪能力找到它们。",al={"采药 巴斯兰的头发","追踪巴斯兰的头发","植物束 草药追踪"}}},fp="14,263,24.410.0,24.311.1,23.231.0,30.303.0,33.191.0,42.154.0,40.192.1,45.165.0"}
P.entries["quest:1011"] = {n="被遗忘者的病菌",s="在灰谷东部，凯尼斯·静风注视着被遗忘者日益逼近。他担心他们正在调制瘟疫，意图蹂躏精灵的圣地，于是派联盟勇士前往朵丹尼尔兽穴附近的一处营地，夺取样本。",h="在灰谷东部，凯尼斯·静风注视着被遗忘者日益逼近。他担心他们正在调制瘟疫，意图蹂躏精灵的圣地，于是派联盟勇士前往朵丹尼尔兽穴附近的一处营地，夺取样本。",kw={"药剂师","灰谷","一瓶病菌","朵丹尼尔兽穴","林歌神殿","被遗忘者","被遗忘者的疾病","凯尼斯·静风","暗夜精灵"},ang={["class:Druid"]="德鲁伊将兽穴视为与翡翠梦境相通的圣地。朵丹尼尔附近那些装在瓶中的瘟疫，直接威胁着塞纳里奥议会守护的核心。",["faction:Alliance"]="部落的被遗忘者盟友将化学战带到了灰谷。这一威胁让联盟领袖意识到，森林中的冲突早已超出了木材之争。",["race:NightElf"]="对 Kaldorei 而言，亡灵出现在神圣兽穴附近，是无法容忍的亵渎。保护沉睡的德鲁伊和灰谷免受邪恶毒素侵害，就是捍卫他们的生存与荣耀。"},sec={{t="森林中的瘟疫",b="灰谷的暗夜精灵长期以来一直面对着萨特、狂暴的元素生物和兽人伐木队。被遗忘者带来了更阴暗的威胁。这支部落的亡灵势力正在古老废墟和神圣兽穴附近扎根。他们的到来带来了战火，也让人担忧炼金瘟疫会在 卡多雷 的林地间蔓延。"},{t="潜入朵丹尼尔",b="在林歌神殿以南、朵丹尼尔兽穴附近，被遗忘者的药剂师和斥候加固了一处营地。在熬制药剂的大锅和污秽的试剂之间，他们将未经试验的毒素装进瓶中。凯尼斯·静风派斥候潜入其中，取回完好的一瓶病菌，以便在被遗忘者将其散播到整片森林之前，研究瓶中不稳定的物质。"}},faq={{q="凯尼斯·静风是谁？",a="凯尼斯·静风是一名暗夜精灵，在灰谷东部的林歌神殿废墟中守望。他追踪这片地区敌对势力的动向，尤其关注被遗忘者，以及兽穴附近的腐化力量。",al={"凯尼斯·静风","被遗忘者的病菌 任务由谁给予","林歌神殿任务给予者"}},{q="被遗忘者的营地在哪里？",a="被遗忘者的营地位于林歌神殿以南，靠近朵丹尼尔兽穴。他们的部队聚集在制药台和帐篷周围，调制生物药剂。",al={"营地在哪里","病菌瓶在哪里","朵丹尼尔 营地位置"}},{q="被遗忘者为什么来到灰谷？",a="被遗忘者在灰谷从事炼金术和生物方面的活动。他们在 卡多雷 的古老兽穴附近收集试剂、调制有毒化合物，令精灵担心他们意图让这片土地染上疫病。",al={"被遗忘者 为什么在灰谷","灰谷的亡灵","被遗忘者 的动机"}},{q="取回瓶子后会发生什么？",a="凯尼斯·静风检查夺来的瓶子，辨认其中的物质。他的调查揭示了附近朵丹尼尔兽穴中沉睡德鲁伊的困境，接着他便着手应对这一危险。",al={"接下来做什么","被遗忘者的病菌 之后","后续任务"}},{q="林歌神殿是什么地方？",a="林歌神殿是一处古老、几乎被遗弃的暗夜精灵废墟，位于灰谷最东部，靠近艾萨拉边界。凯尼斯·静风独自住在那里，指挥着这片地区对抗被遗忘者的战斗。",al={"林歌神殿前哨","林歌神殿是什么地方"}},{q="灰谷的兽穴是什么地方？",a="兽穴是神圣的地下庇护所，暗夜精灵德鲁伊在其中沉睡，与翡翠梦境相通。朵丹尼尔兽穴便是这样的地方，因此附近的被遗忘者营地令 卡多雷 深感忧虑。",al={"兽穴是什么","朵丹尼尔 的用途","兽穴"}}},fp="17,222,23.321.0,25.344.0,25.219.0,35.162.0,34.198.0,41.199.1,20.206.0,38.217.0"}
